ST.xhtml:
// Отслеживание изменения сигнала
IF VI_Heartbeat_Signal <> L_Last_Heartbeat_State THEN
    L_Last_Heartbeat_Time := VI_System_Time_MS;
    L_Last_Heartbeat_State := VI_Heartbeat_Signal;
END_IF;

// Проверка таймаута
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Heartbeat_Time, VI_System_Time_MS - L_Last_Heartbeat_Time, (4294967295 - L_Last_Heartbeat_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > VI_Timeout_MS THEN
    VO_Module_Online := FALSE;
    VO_Error_Active := TRUE;
ELSE
    VO_Module_Online := TRUE;
    VO_Error_Active := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_IO_Module_Watchdog <<<

IF NOT VI_Enable THEN
    GVL_HMI_Config_Workflow.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

// Preserve workflow memory from the previous scan. Validation is a state of the
// current draft and must remain visible until a new validation request changes it.
L_State := GVL_HMI_Config_Workflow.G_Workflow_State;

L_State.Runtime_Valid := TRUE;
L_State.Runtime_System_Time_MS := VI_System_Time_MS;

L_State.Editor_Open :=
    GVL_HMI_Config_Workflow.G_Open_Editor_Request;

L_State.Validation_Requested :=
    GVL_HMI_Config_Workflow.G_Validate_Request;

L_State.Activation_Requested :=
    GVL_HMI_Config_Workflow.G_Activate_Request;

L_State.Rollback_Requested :=
    GVL_HMI_Config_Workflow.G_Rollback_Request;

L_State.Reset_Default_Requested :=
    GVL_HMI_Config_Workflow.G_Reset_Default_Request;

L_State.Active_Version :=
    GVL_Water_Topology_Config.G_Active_Config_Version;

// Generic draft identity follows the generic staged config version. The staged
// change monitor increments it when any GVL_CONFIG_CONTROL.STG_* value changes.
L_State.Draft_Version :=
    GVL_CONFIG_CONTROL.G_Staged_Config_Version;

// Topology draft identity is tracked separately so topology-only edits cannot
// reuse a validation result from an older staged topology version.
L_State.Topology_Draft_Version :=
    GVL_Config_Activation.G_Staged_Config_Version;

L_State.Last_Stable_Version :=
    GVL_Config_Activation.G_Last_Stable_Config_Version;

L_State.Topology_Activation_Required :=
    L_State.Topology_Draft_Version <> GVL_Water_Topology_Config.G_Active_Config_Version;

L_State.Topology_Validation_OK :=
    (NOT L_State.Topology_Activation_Required) OR GVL_Config_Activation.G_Activation_State.Staged_Config_Valid;

L_State.Quarantine_Visible :=
    GVL_Config_Activation.G_Config_Quarantine_Active;

L_State.Service_Mode_Required := TRUE;
L_State.Operator_Ack_Required := TRUE;
L_State.Activation_Allowed := FALSE;
L_State.Activation_Blocked := FALSE;
L_State.Rollback_Allowed := FALSE;
L_State.Reset_Default_Allowed := FALSE;

IF (L_State.Validated_Draft_Version <> L_State.Draft_Version) OR
   (L_State.Validated_Topology_Version <> L_State.Topology_Draft_Version) THEN
    L_State.Validation_OK := FALSE;
    L_State.Validation_Failed := FALSE;
    L_State.Draft_Dirty := TRUE;
END_IF;

IF L_State.Editor_Open THEN
    L_State.Edit_Session_Active := TRUE;
END_IF;

IF L_State.Validation_Requested THEN
    // HMI Validate launches the staged-config simulation gate. The simulation
    // manager consumes the request and publishes result/error for HMI and apply.
    GVL_CONFIG_SIMULATION.G_Simulation_Request := TRUE;
    GVL_CONFIG_SIMULATION.G_Simulation_Confirm := TRUE;
END_IF;

// Consume only a new simulation result. Sequence is used instead of timestamp so
// repeated simulation runs in the same millisecond are still detected.
IF (GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq <> 0) AND
   (GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq <> L_State.Validation_Result_Seq) THEN

    IF L_State.Topology_Validation_OK
       AND GVL_CONFIG_SIMULATION.G_Simulation_Result_OK THEN

        L_State.Validation_OK := TRUE;
        L_State.Validation_Failed := FALSE;
        L_State.Validated_Draft_Version := L_State.Draft_Version;
        L_State.Validated_Topology_Version := L_State.Topology_Draft_Version;
        L_State.Validation_Last_Run_MS := GVL_CONFIG_SIMULATION.G_Simulation_Last_Run_MS;
        L_State.Validation_Result_Seq := GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq;
        L_State.Draft_Dirty := FALSE;

    ELSE

        L_State.Validation_OK := FALSE;
        L_State.Validation_Failed := TRUE;
        L_State.Validation_Last_Run_MS := GVL_CONFIG_SIMULATION.G_Simulation_Last_Run_MS;
        L_State.Validation_Result_Seq := GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq;

    END_IF;

END_IF;

IF L_State.Activation_Requested THEN

    IF GVL_HMI_Config_Workflow.G_Service_Mode_Active
       AND GVL_HMI_Config_Workflow.G_Operator_Ack
       AND L_State.Validation_OK
       AND (L_State.Validated_Draft_Version = L_State.Draft_Version)
       AND (L_State.Validated_Topology_Version = L_State.Topology_Draft_Version)
       AND GVL_CONFIG_SIMULATION.G_Simulation_Result_OK THEN

        L_State.Activation_Allowed := TRUE;
        IF L_State.Topology_Activation_Required THEN
            GVL_Config_Activation.G_Activation_Request := TRUE;
        END_IF;
        GVL_CONFIG_CONTROL.G_Apply_Request := TRUE;
        GVL_CONFIG_CONTROL.G_Apply_Confirm := TRUE;

    ELSE

        L_State.Activation_Blocked := TRUE;

    END_IF;

END_IF;

IF L_State.Rollback_Requested THEN

    IF GVL_HMI_Config_Workflow.G_Operator_Ack THEN

        L_State.Rollback_Allowed := TRUE;
        GVL_Config_Activation.G_Rollback_Request := TRUE;
        GVL_CONFIG_CONTROL.G_Rollback_Request := TRUE;
        GVL_CONFIG_CONTROL.G_Rollback_Confirm := TRUE;

    END_IF;

END_IF;

IF L_State.Reset_Default_Requested THEN

    IF GVL_HMI_Config_Workflow.G_Service_Mode_Active
       AND GVL_HMI_Config_Workflow.G_Operator_Ack THEN

        L_State.Reset_Default_Allowed := TRUE;
        GVL_CONFIG_CONTROL.G_Reset_Default_Request := TRUE;
        GVL_CONFIG_CONTROL.G_Reset_Default_Confirm := TRUE;

    END_IF;

END_IF;

IF L_State.Activation_Blocked THEN

    L_State.Status_Code := 2;
    L_State.Status_Text := 'HMI activation blocked';

ELSIF L_State.Validation_Failed THEN

    L_State.Status_Code := 1;
    L_State.Status_Text := 'HMI validation failed';

ELSIF L_State.Validation_Requested THEN

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI config validation requested';

ELSIF L_State.Activation_Allowed THEN

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI config activation requested';

ELSIF L_State.Rollback_Allowed THEN

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI config rollback requested';

ELSIF L_State.Reset_Default_Allowed THEN

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI config reset default requested';

ELSIF L_State.Draft_Dirty THEN

    L_State.Status_Code := 1;
    L_State.Status_Text := 'HMI draft changed - validation required';

ELSIF L_State.Validation_OK THEN

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI validation passed';

ELSE

    L_State.Status_Code := 0;
    L_State.Status_Text := 'HMI config workflow healthy';

END_IF;

GVL_HMI_Config_Workflow.G_Workflow_State := L_State;

GVL_HMI_Config_Workflow.G_Runtime_Valid := TRUE;
GVL_HMI_Config_Workflow.G_Last_Update_MS := VI_System_Time_MS;
GVL_HMI_Config_Workflow.G_Status_Code := L_State.Status_Code;
GVL_HMI_Config_Workflow.G_Status_Text := L_State.Status_Text;

IF GVL_HMI_Config_Workflow.G_Validate_Request THEN
    GVL_HMI_Config_Workflow.G_Validate_Request := FALSE;
END_IF;

IF GVL_HMI_Config_Workflow.G_Activate_Request THEN
    GVL_HMI_Config_Workflow.G_Activate_Request := FALSE;
END_IF;

IF GVL_HMI_Config_Workflow.G_Rollback_Request THEN
    GVL_HMI_Config_Workflow.G_Rollback_Request := FALSE;
END_IF;

IF GVL_HMI_Config_Workflow.G_Reset_Default_Request THEN
    GVL_HMI_Config_Workflow.G_Reset_Default_Request := FALSE;
END_IF;

// Вычисление времени цикла
IF L_Last_Time = 0 THEN
    L_Last_Time := VI_System_Time_MS;
    L_Cycle_Time_S := 1.0;
ELSE
    L_Cycle_Time_S := UDINT_TO_REAL((SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1))) / 1000.0;
    L_Last_Time := VI_System_Time_MS;
END_IF;
IF L_Cycle_Time_S <= 0.0 THEN L_Cycle_Time_S := 0.01; END_IF;

// 1. Определение активного тарифа
IF VI_Tariff.Enabled THEN
    IF VI_Tariff.Night_Start_Hour > VI_Tariff.Night_End_Hour THEN
        // Переход через полночь (например, 23:00 - 07:00)
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) OR (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    ELSE
        // В пределах одного дня
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) AND (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    END_IF;
ELSE
    L_Is_Night := FALSE;
END_IF;

// 2. Расчет эффективной уставки
VO_Effective_Setpoint := VI_Config.design_temp;
IF L_Is_Night THEN
    VO_Effective_Setpoint := VO_Effective_Setpoint + VI_Tariff.Boost_Delta;
END_IF;

// 3. ПИД-регулирование
L_PID(
    VI_SetPoint := VO_Effective_Setpoint,
    VI_ProcessValue := VI_Current_Temp,
    VI_Kp := VI_Config.pid_kp,
    VI_Tn := 300.0,
    VI_Tv := 0.0,
    VI_Y_Min := 0.0,
    VI_Y_Max := 100.0,
    VI_Cycle_Time_S := L_Cycle_Time_S,
    VO_Output => VO_Valve_Pos
);

// 4. ШИМ-модуляция для термоэлектрического привода
IF VI_Config.pwm_period_s > 0 THEN
    L_PWM_Period_MS := TO_UDINT(VI_Config.pwm_period_s) * 1000;
ELSE
    L_PWM_Period_MS := 600000; // 10 минут
END_IF;

L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
IF L_Current_Phase_MS >= L_PWM_Period_MS THEN
    L_PWM_Start_Time := VI_System_Time_MS - (L_Current_Phase_MS - L_PWM_Period_MS); // Сохраняем остаток для точности
    L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
END_IF;

L_PWM_Duty_MS := TO_UDINT((VO_Valve_Pos / 100.0) * TO_REAL(L_PWM_Period_MS));

IF VI_IsActivePLC THEN
    VO_Pump_Run := (VO_Valve_Pos > 5.0);

    IF VO_Valve_Pos >= 100.0 THEN
        VO_Valve_Bool := TRUE;
    ELSIF VO_Valve_Pos <= 0.0 THEN
        VO_Valve_Bool := FALSE;
    ELSE
        VO_Valve_Bool := (L_Current_Phase_MS <= L_PWM_Duty_MS);
    END_IF;
ELSE
    VO_Pump_Run := FALSE;
    VO_Valve_Bool := FALSE;
END_IF;

GVL_OUTDOOR_LIGHTING.G_Outdoor_Dark_Active := FALSE;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Active := FALSE;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Party_Active := FALSE;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Security_Active := FALSE;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR DISABLED';

FOR L_Zone := 1 TO GVL_CONSTANTS.C_MAX_OUTDOOR_ZONES DO
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Light_Level[L_Zone] := 0;
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Socket_State[L_Zone] := FALSE;
END_FOR;

IF (NOT VI_IsActivePLC) OR (NOT GVL_OUTDOOR_LIGHTING.G_Outdoor_Enabled) THEN
    RETURN;
END_IF;

L_Dark := FALSE;
IF GVL_OUTDOOR_LIGHTING.G_Outdoor_Fallback_To_Night THEN
    L_Dark := VI_Is_Night;
END_IF;
IF GVL_OUTDOOR_LIGHTING.G_Outdoor_Use_Lux_Sensor AND GVL_STATE.G_Ambient_Lux_Valid THEN
    L_Dark := L_Dark OR (GVL_STATE.G_Ambient_Lux < GVL_OUTDOOR_LIGHTING.G_Outdoor_Lux_Threshold);
END_IF;

IF GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Start_MS <= GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_End_MS THEN
    L_Economy := (VI_Time_Of_Day_MS >= GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Start_MS) AND (VI_Time_Of_Day_MS < GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_End_MS);
ELSE
    L_Economy := (VI_Time_Of_Day_MS >= GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Start_MS) OR (VI_Time_Of_Day_MS < GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_End_MS);
END_IF;

L_Party := (VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_PARTY);
L_Any_Motion := FALSE;
FOR L_Zone := 1 TO GVL_CONSTANTS.C_MAX_OUTDOOR_ZONES DO
    L_Motion_Index := GVL_OUTDOOR_LIGHTING.G_Outdoor_Motion_Zone_Index[L_Zone];
    IF (L_Motion_Index >= 1) AND (L_Motion_Index <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
        L_Any_Motion := L_Any_Motion OR VI_Motion_Sensors[L_Motion_Index];
    END_IF;
END_FOR;
L_Security := VI_Security_Armed AND L_Any_Motion;

GVL_OUTDOOR_LIGHTING.G_Outdoor_Dark_Active := L_Dark;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Active := L_Dark AND L_Economy;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Party_Active := L_Party;
GVL_OUTDOOR_LIGHTING.G_Outdoor_Security_Active := L_Security;

FOR L_Zone := 1 TO GVL_CONSTANTS.C_MAX_OUTDOOR_ZONES DO
    IF GVL_OUTDOOR_LIGHTING.G_Outdoor_Manual_Mode[L_Zone] THEN
        L_Target_Level := GVL_OUTDOOR_LIGHTING.G_Outdoor_Manual_Light_Level[L_Zone];
        L_Target_Socket := GVL_OUTDOOR_LIGHTING.G_Outdoor_Manual_Socket_State[L_Zone];
    ELSIF L_Party THEN
        L_Target_Level := GVL_OUTDOOR_LIGHTING.G_Outdoor_Party_Level;
        L_Target_Socket := GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_Enabled AND GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_On_In_Party;
    ELSIF L_Security THEN
        L_Target_Level := GVL_OUTDOOR_LIGHTING.G_Outdoor_Security_Level;
        L_Target_Socket := GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_Enabled AND NOT GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_Off_In_Security;
    ELSIF L_Dark AND L_Economy THEN
        L_Target_Level := GVL_OUTDOOR_LIGHTING.G_Outdoor_Economy_Level;
        L_Target_Socket := FALSE;
    ELSIF L_Dark THEN
        L_Target_Level := GVL_OUTDOOR_LIGHTING.G_Outdoor_Auto_Level;
        L_Target_Socket := GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_Enabled AND GVL_OUTDOOR_LIGHTING.G_Outdoor_Sockets_On_In_Auto;
    ELSE
        L_Target_Level := 0;
        L_Target_Socket := FALSE;
    END_IF;

    GVL_OUTDOOR_LIGHTING.G_Outdoor_Light_Level[L_Zone] := L_Target_Level;
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Socket_State[L_Zone] := L_Target_Socket;

    L_Light_Index := GVL_OUTDOOR_LIGHTING.G_Outdoor_Light_Zone_Index[L_Zone];
    IF (L_Light_Index >= 1) AND (L_Light_Index <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
        FOR L_Slot := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
            IF NOT VIO_Rule_Actions[L_Slot].Active THEN
                VIO_Rule_Actions[L_Slot].Active := TRUE;
                VIO_Rule_Actions[L_Slot].Triggered := FALSE;
                VIO_Rule_Actions[L_Slot].Action_Type := E_Rule_Action_Type.ACTION_SET_LIGHTING_BASE;
                VIO_Rule_Actions[L_Slot].Target_ID := TO_BYTE(L_Light_Index);
                VIO_Rule_Actions[L_Slot].Value := TO_REAL(L_Target_Level);
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    L_Socket_Index := GVL_OUTDOOR_LIGHTING.G_Outdoor_Socket_Index[L_Zone];
    IF (L_Socket_Index >= 1) AND (L_Socket_Index <= GVL_CONSTANTS.C_MAX_SOCKETS) THEN
        FOR L_Slot := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
            IF NOT VIO_Rule_Actions[L_Slot].Active THEN
                VIO_Rule_Actions[L_Slot].Active := TRUE;
                VIO_Rule_Actions[L_Slot].Triggered := FALSE;
                VIO_Rule_Actions[L_Slot].Action_Type := E_Rule_Action_Type.ACTION_SET_SOCKET;
                VIO_Rule_Actions[L_Slot].Target_ID := TO_BYTE(L_Socket_Index);
                IF L_Target_Socket THEN
                    VIO_Rule_Actions[L_Slot].Value := REAL#1.0;
                ELSE
                    VIO_Rule_Actions[L_Slot].Value := REAL#0.0;
                END_IF;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
END_FOR;

IF L_Party THEN
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR PARTY';
ELSIF L_Security THEN
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR SECURITY';
ELSIF L_Dark AND L_Economy THEN
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR ECONOMY';
ELSIF L_Dark THEN
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR AUTO';
ELSE
    GVL_OUTDOOR_LIGHTING.G_Outdoor_Status_Text := 'OUTDOOR DAY OFF';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Outdoor_Lighting_Manager <<<

// ==============================================================================
// Heating root-cause diagnostics observer
// Public diagnostics/explainability layer.
// Does NOT own control/runtime decisions.
// ==============================================================================



IF NOT VI_Enable THEN
    GVL_STATE.G_Heating_RootCause := E_Heating_RootCause.RC_NONE;
    GVL_STATE.G_Heating_RootConfidence := 0.0;
    GVL_STATE.G_Heating_Confidence := 0.0;
    GVL_STATE.G_Heating_Error_Score := 1.0;
    GVL_STATE.G_Heating_Confidence_Reason_Code := -1;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'Heating diagnostics disabled';
    RETURN;
END_IF;

// ======================================================
// DEMAND MAP
// ======================================================
fbDemandMap(
    VI_Zone_Valves := GVL_STATE.G_Zone_Valves,
    VI_Zone_Configs := GVL_CONFIG.G_HMI_FloorHeating_Configs,
    VO_Manifold_Demand_Map => L_Demand_Map
);

// ======================================================
// INTERNAL INFERENCE ENGINE
// ======================================================
fbRootCause(
    VI_Emergency_Stop := GVL_STATE.G_Safety_Emergency_Stop,
    VI_Gas_Safety := GVL_STATE.G_Safety_Gas_Latched,
    VI_IO_Failsafe := GVL_STATE.G_Heating_IO_Fault,

    VI_Cascade_Available := GVL_STATE.G_Heating_Cascade_Available,
    VI_Cascade_Degraded := GVL_STATE.G_Heating_Cascade_Degraded,
    VI_Cascade_Partial_Capacity := GVL_STATE.G_Heating_Cascade_Partial_Capacity,
    VI_Cascade_No_Flame := GVL_STATE.G_Heating_Cascade_No_Flame,
    VI_Cascade_Transport_Degraded := GVL_STATE.G_Heating_Cascade_Transport_Degraded,
    VI_Cascade_Ignition_Timeout := GVL_STATE.G_Heating_Cascade_Ignition_Timeout,
    VI_Cascade_Active_Boilers := GVL_STATE.G_Heating_Cascade_Active_Boilers,
    VI_Cascade_Available_Boilers := GVL_STATE.G_Heating_Cascade_Available_Boilers,

    VI_Boiler_OT_Online := GVL_STATE.G_Boiler_OT_Online,
    VI_Boiler_Error := GVL_STATE.G_Boiler_Error,
    VI_Boiler_Flame := GVL_STATE.G_Boiler_Flame,
    VI_Boiler_OT_Command_Timeout := GVL_STATE.G_Boiler_OT_Command_Timeout,
    VI_Boiler_OT_Heartbeat_Timeout := GVL_STATE.G_Boiler_OT_Heartbeat_Timeout,
    VI_Boiler_OT_Adapter_Error := GVL_STATE.G_Boiler_OT_Adapter_Error,

    VI_Manifold_Pumps := GVL_STATE.G_Manifold_Pumps,
    VI_Manifold_Valves := GVL_STATE.G_Manifold_Valves,

    VI_Sensor_Error := GVL_STATE.G_Heating_Sensor_Fault,
    VI_Supply_Temps := GVL_STATE.G_Manifold_T_Supply,
    VI_Target_Supply := GVL_STATE.G_Target_Temperature,
    VI_Demand_Map := L_Demand_Map
);

// ======================================================
// PUBLIC DIAGNOSTICS STATE
// ======================================================
GVL_STATE.G_Heating_RootCause := fbRootCause.VO_RootCause;
GVL_STATE.G_Heating_RootConfidence := fbRootCause.VO_Confidence;
GVL_STATE.G_Heating_Confidence := fbRootCause.VO_Confidence;
GVL_STATE.G_Heating_Error_Score := fbRootCause.VO_Error_Score;
GVL_STATE.G_Heating_Confidence_Reason_Code := fbRootCause.VO_Reason_Code;
GVL_STATE.G_Heating_Confidence_Reason_Text := fbRootCause.VO_Reason_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_RootCause_Diagnostics <<<

L_Changed :=
    (VI_Gas_Alarm <> L_Last_Gas)
    OR (VI_Leak_Alarm <> L_Last_Leak);

FOR L_i := 1 TO 4 DO
    IF VI_Pumps[L_i] <> L_Last_Pumps[L_i] THEN
        L_Changed := TRUE;
    END_IF;
END_FOR;

IF L_Changed THEN
    VO_Last_Change_Time := VI_System_Time;
END_IF;

L_Last_Gas := VI_Gas_Alarm;
L_Last_Leak := VI_Leak_Alarm;

FOR L_i := 1 TO 4 DO
    L_Last_Pumps[L_i] := VI_Pumps[L_i];
END_FOR;

// ==============================================================================
// System evacuation helper
//
// Internal helper for PRG_System.
// Owns evacuation guidance, target/hazard zone name projection,
// and evacuation lighting activation.
// ==============================================================================



FOR L_i := 1 TO 32 DO
    GVL_STATE.G_Evac_Guidance[L_i] := 0;

    IF GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := -1;
    END_IF;

    IF GVL_CONFIG.G_Evac_Exit_Zones[L_i] AND NOT GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := 1;
    END_IF;
END_FOR;

GVL_STATUS.G_Evac_Target_Zone_Name := '';
GVL_STATUS.G_Evac_Hazard_Zone_Name := '';

FOR L_i := 1 TO 32 DO
    IF (GVL_STATUS.G_Evac_Hazard_Zone_Name = '') AND GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATUS.G_Evac_Hazard_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Hazard_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Hazard_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;

    IF (GVL_STATUS.G_Evac_Target_Zone_Name = '') AND (GVL_STATE.G_Evac_Guidance[L_i] = 1) THEN
        GVL_STATUS.G_Evac_Target_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Target_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Target_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;
END_FOR;

IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP AND GVL_STATE.G_Safety_Smoke_Latched THEN
    GVL_STATE.G_Evacuation_Lighting_Active := TRUE;
ELSE
    GVL_STATE.G_Evacuation_Lighting_Active := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Evacuation <<<

// ==============================================================================
// Heating runtime observer authorization
// Governed passive-bootstrap authorization only.
// Read-only.
// Deterministic.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_Enable_Authorized := FALSE;
VO_Enable_Effective := FALSE;
VO_Authorization_Valid := FALSE;

VO_Status_Code := 0;
VO_Status_Text := 'Heating runtime observer authorization inactive';

// ======================================================
// REQUEST VALIDATION
// ======================================================
IF NOT VI_Enable_Request THEN
    RETURN;
END_IF;

// ======================================================
// GOVERNANCE VALIDATION
// ======================================================
IF NOT VI_Bootstrap_Mode THEN
    VO_Status_Code := 100;
    VO_Status_Text := 'Bootstrap mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Passive_Mode THEN
    VO_Status_Code := 110;
    VO_Status_Text := 'Passive mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_ReadOnly_Mode THEN
    VO_Status_Code := 120;
    VO_Status_Text := 'Read-only mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Governance_Locked THEN
    VO_Status_Code := 130;
    VO_Status_Text := 'Governance lock required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Runtime_Authority_Disabled THEN
    VO_Status_Code := 140;
    VO_Status_Text := 'Runtime authority isolation required';
    RETURN;
END_IF;

IF NOT VI_Writable_Exports_Disabled THEN
    VO_Status_Code := 150;
    VO_Status_Text := 'Writable exports must remain disabled';
    RETURN;
END_IF;

// ======================================================
// AUTHORIZED PASSIVE BOOTSTRAP ACTIVATION
// ======================================================
VO_Enable_Authorized := TRUE;
VO_Enable_Effective := TRUE;
VO_Authorization_Valid := TRUE;

VO_Status_Code := 1;
VO_Status_Text := 'Heating runtime observer authorization granted';

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observer_Authorization <<<

VO_HMI_Status_Text := VI_Status_Msg;

CASE VI_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_HMI_State_Code := 0;
    E_System_Severity.SEV_WARNING:
        VO_HMI_State_Code := 1;
    E_System_Severity.SEV_DEGRADED:
        VO_HMI_State_Code := 2;
    E_System_Severity.SEV_CRITICAL:
        VO_HMI_State_Code := 3;
ELSE
        // No fallback required
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_HMI_Interface <<<

// read real time
L_Real_Now := GVL_STATUS.G_System_Time_MS;

// wrap-safe delta (real time base)
IF L_Real_Now >= GVL_TIME_SERVICE.G_Last_Now_MS THEN
    L_Elapsed := L_Real_Now - GVL_TIME_SERVICE.G_Last_Now_MS;
    GVL_TIME_SERVICE.G_Wrap_Detected := FALSE;
ELSE
    L_Elapsed := (16#FFFFFFFF - GVL_TIME_SERVICE.G_Last_Now_MS) + L_Real_Now + 1;
    GVL_TIME_SERVICE.G_Wrap_Detected := TRUE;
END_IF;

GVL_TIME_SERVICE.G_Last_Now_MS := L_Real_Now;

// --- SIMULATION MODE ---
IF GVL_TIME_SERVICE.G_Sim_Enabled THEN

    IF NOT GVL_TIME_SERVICE.G_Sim_Frozen THEN
        L_Scaled_Delta := REAL_TO_UDINT(TO_REAL(L_Elapsed) * GVL_TIME_SERVICE.G_Sim_Time_Scale);

        GVL_TIME_SERVICE.G_Sim_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS + L_Scaled_Delta;

        GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS + L_Scaled_Delta;

        IF GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS >= 86400000 THEN
            GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS MOD 86400000;
            GVL_TIME_SERVICE.G_Sim_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week + 1;
            IF GVL_TIME_SERVICE.G_Sim_Day_Of_Week > 7 THEN
                GVL_TIME_SERVICE.G_Sim_Day_Of_Week := 1;
            END_IF;
        END_IF;
    END_IF;

    GVL_TIME_SERVICE.G_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week;

ELSE
    GVL_TIME_SERVICE.G_Now_MS := L_Real_Now;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_STATUS.G_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := TO_INT(GVL_STATUS.G_Current_Day);
END_IF;

// TOD unified
GVL_TIME_SERVICE.G_Current_TOD := UDINT_TO_TOD(GVL_TIME_SERVICE.G_Time_Of_Day_MS);

GVL_TIME_SERVICE.G_Delta_MS := L_Elapsed;

IF NOT VI_Enable THEN
    GVL_IO_Binding_Runtime.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    // Flood sensor runtime binding.
    L_Binding :=
        GVL_IO_Binding_Config.G_Flood_Sensor_Binding[L_i];

    IF L_Binding.Binding_Valid THEN

        L_Channel := L_Binding.Physical_Channel_Id;

        IF (L_Channel >= 1)
           AND (L_Channel <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS) THEN

            GVL_IO_Binding_Runtime.G_Flood_Sensor_Value[L_i] :=
                GVL_IO.DI_Flood_Sensors[L_Channel];

            GVL_IO_Binding_Runtime.G_Flood_Sensor_Valid[L_i] := TRUE;

        ELSE

            L_Any_Invalid := TRUE;

        END_IF;

    ELSE

        L_Any_Missing := TRUE;

    END_IF;

    // Valve close feedback runtime binding.
    L_Binding :=
        GVL_IO_Binding_Config.G_Water_Valve_Close_FB_Binding[L_i];

    IF L_Binding.Binding_Valid THEN

        L_Channel := L_Binding.Physical_Channel_Id;

        IF (L_Channel >= 1)
           AND (L_Channel <= GVL_CONSTANTS.C_MAX_WATER_ZONES) THEN

            GVL_IO_Binding_Runtime.G_Water_Valve_Close_FB_Value[L_i] :=
                GVL_IO.DI_Water_Zone_Close_FB[L_Channel];

            GVL_IO_Binding_Runtime.G_Water_Valve_Close_FB_Valid[L_i] := TRUE;

        ELSE

            L_Any_Invalid := TRUE;

        END_IF;

    END_IF;

    // Valve open feedback runtime binding.
    L_Binding :=
        GVL_IO_Binding_Config.G_Water_Valve_Open_FB_Binding[L_i];

    IF L_Binding.Binding_Valid THEN

        L_Channel := L_Binding.Physical_Channel_Id;

        IF (L_Channel >= 1)
           AND (L_Channel <= GVL_CONSTANTS.C_MAX_WATER_ZONES) THEN

            GVL_IO_Binding_Runtime.G_Water_Valve_Open_FB_Value[L_i] :=
                GVL_IO.DI_Water_Zone_Open_FB[L_Channel];

            GVL_IO_Binding_Runtime.G_Water_Valve_Open_FB_Valid[L_i] := TRUE;

        ELSE

            L_Any_Invalid := TRUE;

        END_IF;

    END_IF;

END_FOR;

GVL_IO_Binding_Runtime.G_Any_Invalid_Binding :=
    L_Any_Invalid;

GVL_IO_Binding_Runtime.G_Any_Missing_Binding :=
    L_Any_Missing;

GVL_IO_Binding_Runtime.G_Runtime_Valid := TRUE;
GVL_IO_Binding_Runtime.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Invalid THEN
    GVL_IO_Binding_Runtime.G_Status_Code := 2;
    GVL_IO_Binding_Runtime.G_Status_Text :=
        'Hardware binding invalid';
ELSIF L_Any_Missing THEN
    GVL_IO_Binding_Runtime.G_Status_Code := 1;
    GVL_IO_Binding_Runtime.G_Status_Text :=
        'Hardware binding incomplete';
ELSE
    GVL_IO_Binding_Runtime.G_Status_Code := 0;
    GVL_IO_Binding_Runtime.G_Status_Text :=
        'Hardware binding runtime healthy';
END_IF;

VO_Meta.Meta_Analytics_Visible := FALSE;
VO_Meta.Meta_Analytics_Degraded := FALSE;
VO_Meta.Meta_Analytics_Attention := FALSE;

VO_Meta.Supervision_Integrity_Visible := FALSE;
VO_Meta.Supervision_Integrity_Observation := 0;

VO_Meta.Adaptive_Drift_Visible := FALSE;
VO_Meta.Adaptive_Drift_Observation := 0;

VO_Meta.Confidence_Degradation_Visible := FALSE;
VO_Meta.Confidence_Degradation_Observation := 0;

VO_Meta.Analytics_Consistency_Visible := FALSE;
VO_Meta.Analytics_Consistency_Observation := 0;

VO_Meta.Sequencing_Meta_Observation := FALSE;
VO_Meta.Ownership_Meta_Observation := FALSE;
VO_Meta.Synchronization_Meta_Observation := FALSE;

VO_Meta.Status_Code := 0;
VO_Meta.Status_Text := 'Heating runtime meta supervision inactive';

VO_Publication_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

VO_Meta.Meta_Analytics_Visible := TRUE;
VO_Meta.Supervision_Integrity_Visible := TRUE;
VO_Meta.Adaptive_Drift_Visible := TRUE;
VO_Meta.Confidence_Degradation_Visible := TRUE;
VO_Meta.Analytics_Consistency_Visible := TRUE;

VO_Meta.Sequencing_Meta_Observation := VI_Runtime_Observation_Valid;
VO_Meta.Ownership_Meta_Observation := VI_Runtime_Observer_Ready;
VO_Meta.Synchronization_Meta_Observation := NOT VI_Runtime_Observer_Fault;

IF VI_Runtime_Observer_Fault THEN
    VO_Meta.Meta_Analytics_Degraded := TRUE;
    VO_Meta.Meta_Analytics_Attention := TRUE;
    VO_Meta.Supervision_Integrity_Observation := 900;
ELSIF NOT VI_Runtime_Observation_Valid THEN
    VO_Meta.Meta_Analytics_Attention := TRUE;
    VO_Meta.Supervision_Integrity_Observation := 200;
ELSE
    VO_Meta.Supervision_Integrity_Observation := 1;
END_IF;

VO_Meta.Status_Code := VI_Runtime_Status_Code;
VO_Meta.Status_Text := VI_Runtime_Status_Text;

VO_Publication_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Meta_Supervision_Publisher <<<

IF NOT VI_Enable THEN
    GVL_Distributed_Authority.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_State.Runtime_Valid := TRUE;
L_State.Runtime_System_Time_MS := VI_System_Time_MS;

L_State.Controller_Id :=
    GVL_Distributed_Runtime.G_Local_Node_State.Controller_Id;

L_State.Runtime_Node_Id :=
    GVL_Distributed_Runtime.G_Local_Node_State.Runtime_Node_Id;

L_State.Authority_Domain_Id :=
    GVL_Distributed_Runtime.G_Local_Node_State.Authority_Domain_Id;

L_State.Authority_Election_Active := TRUE;

L_Lease_Expired :=
    (VI_System_Time_MS - GVL_Distributed_Authority.G_Authority_Lease_Start_MS)
    > GVL_Distributed_Authority.G_Authority_Lease_Duration_MS;

L_State.Authority_Lease_Expired := L_Lease_Expired;
L_State.Authority_Lease_Valid := NOT L_Lease_Expired;

L_State.Replication_Consensus_Healthy :=
    GVL_Distributed_Runtime.G_Distributed_Replication_Healthy;

L_State.Replication_Consensus_Stale :=
    NOT GVL_Distributed_Runtime.G_Distributed_Replication_Healthy;

L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

L_State.Distributed_Safety_Barrier_OK :=
    GVL_Runtime_Restart_Continuity.G_Runtime_Valid
    AND NOT GVL_Config_Activation.G_Config_Quarantine_Active
    AND NOT GVL_Distributed_Runtime.G_Split_Brain_Suspected
    AND GVL_IO_Binding_Runtime.G_Runtime_Valid
    AND L_Finalized_Runtime_Continuity;

IF NOT L_State.Distributed_Safety_Barrier_OK THEN

    L_State.Split_Brain_Blocked := TRUE;
    L_State.Authority_Observer_Only := TRUE;

    L_State.Status_Code := 3;
    L_State.Status_Text :=
        'Distributed authority blocked by safety barrier';

ELSIF L_State.Replication_Consensus_Healthy
   AND NOT L_Lease_Expired
   AND L_Finalized_Runtime_Continuity THEN

    L_State.Authority_Master_Elected := TRUE;

    L_State.Recovery_Authority_Allowed := TRUE;
    L_State.Rollback_Authority_Allowed := TRUE;
    L_State.Quarantine_Authority_Allowed := TRUE;

    L_State.Status_Code := 1;
    L_State.Status_Text :=
        'Distributed master authority active';

ELSE

    L_State.Authority_Backup_Elected := TRUE;

    L_State.Status_Code := 2;
    L_State.Status_Text :=
        'Distributed backup authority active';

END_IF;

GVL_Distributed_Authority.G_Authority_State := L_State;

GVL_Distributed_Authority.G_Split_Brain_Blocked :=
    L_State.Split_Brain_Blocked;

GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK :=
    L_State.Distributed_Safety_Barrier_OK;

GVL_Distributed_Authority.G_Runtime_Valid := TRUE;
GVL_Distributed_Authority.G_Last_Update_MS := VI_System_Time_MS;
GVL_Distributed_Authority.G_Status_Code := L_State.Status_Code;
GVL_Distributed_Authority.G_Status_Text := L_State.Status_Text;

IF NOT VI_Enable THEN
    GVL_Water_Topology_Config.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Config := GVL_Water_Topology_Config_Source.G_Source_Record[L_i];

    IF NOT L_Config.Config_Valid THEN
        L_Config.Config_Valid := TRUE;
        L_Config.Config_Version := 1;
        L_Config.Sensor_Id := TO_UINT(L_i);
        L_Config.Logical_Zone_Id := TO_UINT(L_i);
        L_Config.Hydraulic_Segment_Id := TO_UINT(L_i);
        L_Config.Isolation_Group_Id := TO_UINT(L_i);
        L_Config.Primary_Valve_Group_Id := TO_UINT(L_i);
        L_Config.Fallback_Domain_Id := 1;
        L_Config.Recovery_Domain_Id := 1;

        IF (L_i MOD 4) = 0 THEN
            L_Config.Shared_Trunk := TRUE;
            L_Config.Cross_Zone_Dependency := TRUE;
            L_Config.Multi_Valve_Required := TRUE;
            L_Config.Secondary_Valve_Group_Id := TO_UINT(L_i + 100);
        END_IF;
    END_IF;

    IF L_Config.Primary_Valve_Group_Id = 0 THEN
        L_Config.Config_Valid := FALSE;
        L_Config.Status_Code := 1;
        L_Config.Status_Text := 'Invalid topology config';
    ELSE
        L_Config.Status_Code := 0;
        L_Config.Status_Text := 'Topology config loaded';
    END_IF;

    GVL_Water_Topology_Config.G_Config_Record[L_i] := L_Config;

    L_Any_Invalid := L_Any_Invalid OR NOT L_Config.Config_Valid;
    L_Any_Multi_Valve := L_Any_Multi_Valve OR L_Config.Multi_Valve_Required;

END_FOR;

GVL_Water_Topology_Config.G_Active_Config_Version := GVL_Water_Topology_Config_Source.G_Source_Version;
GVL_Water_Topology_Config.G_Config_Loaded := TRUE;
GVL_Water_Topology_Config.G_Runtime_Remap_Ready := TRUE;
GVL_Water_Topology_Config.G_Any_Invalid_Config := L_Any_Invalid;
GVL_Water_Topology_Config.G_Any_Multi_Valve_Required := L_Any_Multi_Valve;
GVL_Water_Topology_Config.G_Runtime_Valid := TRUE;
GVL_Water_Topology_Config.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Invalid THEN
    GVL_Water_Topology_Config.G_Status_Code := 2;
    GVL_Water_Topology_Config.G_Status_Text := 'Topology config invalid';
ELSIF L_Any_Multi_Valve THEN
    GVL_Water_Topology_Config.G_Status_Code := 1;
    GVL_Water_Topology_Config.G_Status_Text := 'Multi-valve topology active';
ELSE
    GVL_Water_Topology_Config.G_Status_Code := 0;
    GVL_Water_Topology_Config.G_Status_Text := 'Topology config runtime healthy';
END_IF;

// ==============================================================================
// Heating runtime supervisory enrichment
// Passive observability-only connector for restored supervisory FB stack.
//
// DOES NOT own runtime.
// DOES NOT own heating logic.
// DOES NOT own diagnostics authority.
// DOES NOT own OpenTherm transport.
// DOES NOT write outputs or commands.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_Status_Code := 0;
VO_Status_Text := 'Heating runtime supervisory enrichment disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// PASSIVE CIRCUIT EDGE INGESTION
// ======================================================
// Circuit control publishes canonical runtime projection only. This supervisory
// connector is the integration boundary that raises those passive projection
// edges into the event/anomaly stream used by timeline, reconstruction and
// causality observers.
L_Phase_Event := VI_Phase_Event;
L_Anomaly := VI_Anomaly;
L_Circuit_Event_Active := FALSE;
L_Circuit_Event_Code := 0;
L_Circuit_Event_Text := '';

FOR L_Circuit_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_Circuit_i].Source_Loss_Event THEN
        L_Circuit_Event_Active := TRUE;
        L_Circuit_Event_Code := 804;
        L_Circuit_Event_Text := 'Heating circuit temperature source loss';
        EXIT;
    ELSIF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_Circuit_i].Fallback_Activated_Event THEN
        L_Circuit_Event_Active := TRUE;
        L_Circuit_Event_Code := 802;
        L_Circuit_Event_Text := 'Heating circuit fallback activated';
        EXIT;
    ELSIF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_Circuit_i].Fallback_Recovered_Event THEN
        L_Circuit_Event_Active := TRUE;
        L_Circuit_Event_Code := 803;
        L_Circuit_Event_Text := 'Heating circuit fallback recovered';
        EXIT;
    ELSIF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_Circuit_i].Source_Switched_Event THEN
        L_Circuit_Event_Active := TRUE;
        L_Circuit_Event_Code := 801;
        L_Circuit_Event_Text := 'Heating circuit temperature source switched';
        EXIT;
    END_IF;
END_FOR;

IF L_Circuit_Event_Active THEN
    L_Phase_Event.Phase := VI_Runtime_Context.Current_Phase;
    L_Phase_Event.Event_Active := TRUE;
    L_Phase_Event.Event_Completed := TRUE;
    L_Phase_Event.Event_Failed := FALSE;
    L_Phase_Event.Start_Time_MS := VI_System_Time_MS;
    L_Phase_Event.End_Time_MS := VI_System_Time_MS;
    L_Phase_Event.Duration_MS := 0;
    L_Phase_Event.Ordering_Valid := TRUE;
    L_Phase_Event.Isolation_Valid := TRUE;
    L_Phase_Event.Status_Code := L_Circuit_Event_Code;
    L_Phase_Event.Status_Text := L_Circuit_Event_Text;
    L_Phase_Event.Diagnostics_Visible := TRUE;
    L_Phase_Event.Explainability_Visible := TRUE;
    L_Phase_Event.Safety_Integrity_Valid := TRUE;
    L_Phase_Event.OpenTherm_Ownership_Valid := TRUE;
    L_Phase_Event.Cascade_Ownership_Valid := TRUE;

    L_Anomaly.Anomaly_Active := TRUE;
    L_Anomaly.Runtime_Degraded := L_Anomaly.Runtime_Degraded OR (L_Circuit_Event_Code = 802) OR (L_Circuit_Event_Code = 804);
    L_Anomaly.Diagnostics_Degraded := L_Anomaly.Diagnostics_Degraded OR (L_Circuit_Event_Code = 804);
    L_Anomaly.Explainability_Degraded := L_Anomaly.Explainability_Degraded OR (L_Circuit_Event_Code = 804);

    IF L_Circuit_Event_Code = 804 THEN
        IF L_Anomaly.Severity_Level < 80 THEN
            L_Anomaly.Severity_Level := 80;
        END_IF;
        L_Anomaly.Status_Code := 804;
        L_Anomaly.Status_Text := 'Heating circuit source loss observed';
    ELSIF L_Circuit_Event_Code = 802 THEN
        IF L_Anomaly.Severity_Level < 40 THEN
            L_Anomaly.Severity_Level := 40;
        END_IF;
        L_Anomaly.Status_Code := 802;
        L_Anomaly.Status_Text := 'Heating circuit fallback activation observed';
    ELSIF L_Circuit_Event_Code = 803 THEN
        L_Anomaly.Status_Code := 803;
        L_Anomaly.Status_Text := 'Heating circuit fallback recovery observed';
    ELSE
        L_Anomaly.Status_Code := 801;
        L_Anomaly.Status_Text := 'Heating circuit source switch observed';
    END_IF;
END_IF;

// ======================================================
// SOURCE INSTABILITY AGGREGATION
// ======================================================
// Per-circuit predictive details remain in GVL_Heating_Source_Stability.G_State.
// This supervisory layer publishes only the aggregate source-instability view
// into the canonical runtime predictive state.
L_Source_Instability_Max := REAL#0.0;
L_Source_Attention := FALSE;
L_Source_Oscillation_Trend := FALSE;
L_Source_Degraded_Trend := FALSE;
L_Source_Loss_Trend := FALSE;

FOR L_Circuit_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF GVL_Heating_Source_Stability.G_State[L_Circuit_i].Instability_Score > L_Source_Instability_Max THEN
        L_Source_Instability_Max := GVL_Heating_Source_Stability.G_State[L_Circuit_i].Instability_Score;
    END_IF;

    L_Source_Attention :=
        L_Source_Attention OR
        GVL_Heating_Source_Stability.G_State[L_Circuit_i].Instability_Attention;

    L_Source_Oscillation_Trend :=
        L_Source_Oscillation_Trend OR
        GVL_Heating_Source_Stability.G_State[L_Circuit_i].Oscillation_Detected;

    L_Source_Degraded_Trend :=
        L_Source_Degraded_Trend OR
        GVL_Heating_Source_Stability.G_State[L_Circuit_i].Degraded_Trend_Visible;

    L_Source_Loss_Trend :=
        L_Source_Loss_Trend OR
        (GVL_Heating_Source_Stability.G_State[L_Circuit_i].Source_Loss_Count > 0);
END_FOR;

IF L_Source_Instability_Max < REAL#0.0 THEN
    L_Source_Instability_UINT := 0;
ELSIF L_Source_Instability_Max > REAL#100.0 THEN
    L_Source_Instability_UINT := 100;
ELSE
    L_Source_Instability_UINT := REAL_TO_UINT(L_Source_Instability_Max);
END_IF;

// ======================================================
// EXECUTION FRAME FROM CURRENT RUNTIME CONTEXT
// ======================================================
L_Frame.Phase := VI_Runtime_Context.Current_Phase;
L_Frame.Frame_Started := TRUE;
L_Frame.Frame_Completed := VI_Runtime_Context.Output_Projection_Executed;
L_Frame.Frame_Failed := VI_Runtime_Context.Runtime_Fault;
L_Frame.Frame_Start_MS := VI_System_Time_MS;
L_Frame.Frame_End_MS := VI_System_Time_MS;
L_Frame.Frame_Duration_MS := 0;

L_Frame.Sequencing_Valid :=
    VI_Runtime_Context.DHW_Before_Heating_Valid AND
    VI_Runtime_Context.State_Publication_Before_Diagnostics_Valid AND
    VI_Runtime_Context.Output_Projection_Last_Valid;

L_Frame.Ownership_Valid :=
    VI_Runtime_Context.OpenTherm_Ownership_Valid AND
    VI_Runtime_Context.Cascade_Ownership_Valid AND
    VI_Runtime_Context.Safety_Isolation_Valid;

L_Frame.Synchronization_Valid :=
    VI_Runtime_Context.Diagnostics_Isolation_Valid AND
    VI_Runtime_Context.Explainability_Isolation_Valid;

L_Frame.Runtime_Jitter_Detected := L_Anomaly.Runtime_Jitter_Detected;
L_Frame.Runtime_Latency_Detected := L_Anomaly.Runtime_Latency_Detected;
L_Frame.Runtime_Degraded := L_Anomaly.Runtime_Degraded;
L_Frame.Status_Code := VI_Runtime_Context.Runtime_Status_Code;
L_Frame.Status_Text := VI_Runtime_Context.Runtime_Status_Text;

fbTimelineObserver(
    VI_Enable := TRUE,
    VI_Frame := L_Frame,
    VIO_Timeline := VIO_Execution_Timeline
);

// ======================================================
// EVENT BUFFER
// ======================================================
fbEventManager(
    VI_Enable := TRUE,
    VI_Event := L_Phase_Event,
    VIO_Buffer := VIO_Event_Buffer
);

// ======================================================
// ROOT-CAUSE / CAUSALITY NODE
// ======================================================
fbRootCauseCorrelator(
    VI_Enable := TRUE,
    VI_Anomaly := L_Anomaly
);

VO_Causality_Node := fbRootCauseCorrelator.VO_Node;

// ======================================================
// CAUSALITY EDGE BUILT FROM NODE STATE
// ======================================================
VO_Causality_Edge.Source_Node_ID := 1;
VO_Causality_Edge.Target_Node_ID := 2;
VO_Causality_Edge.Edge_Active := VO_Causality_Node.Node_Active;
VO_Causality_Edge.Propagation_Detected :=
    VO_Causality_Node.Runtime_Degraded OR
    VO_Causality_Node.Runtime_Fault OR
    VO_Causality_Node.Cascade_Degraded OR
    VO_Causality_Node.OpenTherm_Degraded OR
    VO_Causality_Node.Sequencing_Invalid OR
    VO_Causality_Node.Ownership_Invalid OR
    VO_Causality_Node.Synchronization_Invalid;

VO_Causality_Edge.Runtime_Propagation :=
    VO_Causality_Node.Runtime_Degraded OR VO_Causality_Node.Runtime_Fault;
VO_Causality_Edge.Cascade_Propagation := VO_Causality_Node.Cascade_Degraded;
VO_Causality_Edge.OpenTherm_Propagation := VO_Causality_Node.OpenTherm_Degraded;
VO_Causality_Edge.Diagnostics_Propagation := VO_Causality_Node.Diagnostics_Degraded;
VO_Causality_Edge.Sequencing_Propagation := VO_Causality_Node.Sequencing_Invalid;
VO_Causality_Edge.Ownership_Propagation := VO_Causality_Node.Ownership_Invalid;
VO_Causality_Edge.Synchronization_Propagation := VO_Causality_Node.Synchronization_Invalid;
VO_Causality_Edge.Severity_Level := VO_Causality_Node.Severity_Level;
VO_Causality_Edge.Critical_Path := VO_Causality_Node.Root_Cause_Candidate;
VO_Causality_Edge.Status_Code := VO_Causality_Node.Status_Code;
VO_Causality_Edge.Status_Text := VO_Causality_Node.Status_Text;

// ======================================================
// FORENSIC RECONSTRUCTION
// ======================================================
fbReconstructionEngine(
    VI_Enable := TRUE,
    VI_Node := VO_Causality_Node,
    VI_Edge := VO_Causality_Edge,
    VI_System_Time_MS := VI_System_Time_MS
);

VO_Blackbox_Event := fbReconstructionEngine.VO_Event;

// ======================================================
// STABILITY / OT / CASCADE PREDICTIVE SUPERVISION
// ======================================================
fbStabilityModel(
    VI_Enable := TRUE,
    VI_Runtime_Degraded := L_Anomaly.Runtime_Degraded,
    VI_Runtime_Critical := L_Anomaly.Critical_Anomaly
);

fbOTCascadeCorrelator(
    VI_Enable := TRUE,
    VI_Cascade_Degraded := L_Anomaly.Cascade_Degraded,
    VI_OT_Degraded := L_Anomaly.OpenTherm_Transport_Degraded,
    VI_OT_Command_Valid := VI_OT_Command_Valid,
    VI_Boiler_Count := VI_Cascade_Boiler_Count
);

fbOTInstabilityPredictor(
    VI_Enable := TRUE,
    VI_OT_Degraded := L_Anomaly.OpenTherm_Transport_Degraded,
    VI_OT_Command_Valid := VI_OT_Command_Valid
);

IF L_Anomaly.Critical_Anomaly THEN
    L_Runtime_Risk := 100;
ELSIF L_Anomaly.Runtime_Degraded THEN
    L_Runtime_Risk := 60;
ELSE
    L_Runtime_Risk := 0;
END_IF;

IF L_Anomaly.Cascade_Boiler_Loss_Detected THEN
    L_Cascade_Risk := 100;
ELSIF L_Anomaly.Cascade_Degraded THEN
    L_Cascade_Risk := 60;
ELSE
    L_Cascade_Risk := 0;
END_IF;

fbPredictiveCorrelation(
    VI_Enable := TRUE,
    VI_Runtime_Risk := L_Runtime_Risk,
    VI_Cascade_Risk := L_Cascade_Risk,
    VI_OT_Risk := fbOTInstabilityPredictor.VO_OT_Instability_Risk
);

// ======================================================
// PREDICTIVE PUBLICATION MODEL
// ======================================================
VO_Predictive_State.Predictive_Analytics_Visible := TRUE;
VO_Predictive_State.Predictive_Analytics_Degraded :=
    fbPredictiveCorrelation.VO_Correlation_Degraded OR L_Source_Attention;
VO_Predictive_State.Predictive_Analytics_Attention :=
    (fbPredictiveCorrelation.VO_Correlation_Score > 40) OR L_Source_Attention;
VO_Predictive_State.Runtime_Stable := fbStabilityModel.VO_Runtime_Stable;
VO_Predictive_State.Runtime_Stability_Score := fbStabilityModel.VO_Stability_Score;
VO_Predictive_State.Runtime_Degradation_Observation := L_Runtime_Risk;
VO_Predictive_State.Runtime_Failure_Observation := SEL(L_Anomaly.Critical_Anomaly, 0, 100);
VO_Predictive_State.Source_Instability_Observation := L_Source_Instability_UINT;
VO_Predictive_State.Source_Instability_Attention := L_Source_Attention;
VO_Predictive_State.Source_Oscillation_Trend_Visible := L_Source_Oscillation_Trend;
VO_Predictive_State.Source_Degraded_Trend_Visible := L_Source_Degraded_Trend;
VO_Predictive_State.Source_Loss_Trend_Visible := L_Source_Loss_Trend;
VO_Predictive_State.Cascade_Degradation_Observation := L_Cascade_Risk;
VO_Predictive_State.Cascade_Degraded_Trend_Visible := fbOTCascadeCorrelator.VO_Correlation_Detected;
VO_Predictive_State.OpenTherm_Instability_Observation := fbOTInstabilityPredictor.VO_OT_Instability_Risk;
VO_Predictive_State.OpenTherm_Degraded_Trend_Visible := fbOTInstabilityPredictor.VO_OT_Degraded_Trend;
VO_Predictive_State.Sequencing_Observation := SEL(VO_Causality_Node.Sequencing_Invalid, 0, 100);
VO_Predictive_State.Ownership_Observation := SEL(VO_Causality_Node.Ownership_Invalid, 0, 100);
VO_Predictive_State.Synchronization_Observation := SEL(VO_Causality_Node.Synchronization_Invalid, 0, 100);
VO_Predictive_State.Status_Code := fbPredictiveCorrelation.VO_Status_Code;

IF L_Source_Attention THEN
    VO_Predictive_State.Status_Text := 'Predictive analytics attention: heating source instability observed';
ELSE
    VO_Predictive_State.Status_Text := fbPredictiveCorrelation.VO_Status_Text;
END_IF;

VO_Status_Code := VO_Predictive_State.Status_Code;
VO_Status_Text := VO_Predictive_State.Status_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Supervisory_Enrichment <<<

// ==============================================================================
// Heating runtime OT instability predictor
// Read-only predictive OT supervision layer.
// ==============================================================================



VO_OT_Instability_Risk := 0;
VO_OT_Degraded_Trend := FALSE;

VO_Status_Code := 0;
VO_Status_Text := 'Heating runtime OT predictor disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

IF NOT VI_OT_Command_Valid THEN
    VO_OT_Instability_Risk := 100;
    VO_OT_Degraded_Trend := TRUE;

    VO_Status_Code := 900;
    VO_Status_Text := 'Heating runtime OT instability critical';

ELSIF VI_OT_Degraded THEN
    VO_OT_Instability_Risk := 60;
    VO_OT_Degraded_Trend := TRUE;

    VO_Status_Code := 200;
    VO_Status_Text := 'Heating runtime OT degradation trend';

ELSE
    VO_OT_Instability_Risk := 5;

    VO_Status_Code := 1;
    VO_Status_Text := 'Heating runtime OT nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_OT_Instability_Predictor <<<

L_Current_Slot := (VI_Time_Index / (GVL_CONSTANTS.C_MS_IN_MINUTE * 10)) MOD TO_UDINT(GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY);

FOR L_i := 1 TO 32 DO
    VO_Light_Outputs[L_i] := FALSE;
END_FOR;

IF VI_Mode_Record THEN
    GVL_Retain.G_Presence_History[L_Current_Slot] := 0;
    FOR L_i := 1 TO 16 DO
        IF VI_Light_Inputs[L_i] THEN
            GVL_Retain.G_Presence_History[L_Current_Slot] :=
                GVL_Retain.G_Presence_History[L_Current_Slot] OR SHL(WORD#1, L_i - 1);
        END_IF;
    END_FOR;
ELSE
    FOR L_i := 1 TO 16 DO
        VO_Light_Outputs[L_i] :=
            (GVL_Retain.G_Presence_History[L_Current_Slot] AND SHL(WORD#1, L_i - 1)) <> 0;
    END_FOR;
END_IF;

IF NOT VI_Enable THEN
    GVL_Forensic_Journal.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Write_Index := GVL_Forensic_Journal.G_Write_Index + 1;

IF L_Write_Index > 256 THEN
    L_Write_Index := 1;
END_IF;

IF GVL_Config_Activation.G_Activation_State.Activation_Allowed
   OR GVL_Config_Activation.G_Activation_State.Rollback_Active THEN

    L_Record.Record_Valid := TRUE;
    L_Record.Event_Time_MS := VI_System_Time_MS;
    L_Record.Event_Id := GVL_Forensic_Journal.G_Last_Event_Id + 1;

    L_Record.Config_Version := GVL_Config_Activation.G_Activation_State.Active_Version;
    L_Record.Topology_Version := GVL_Water_Topology_Config.G_Active_Config_Version;

    IF GVL_Config_Activation.G_Activation_State.Rollback_Active THEN
        L_Record.Rollback_Event := TRUE;
        L_Record.Event_Class := 2;
        L_Record.Event_Severity := 2;
        L_Record.Event_Text := 'Topology rollback activated';
        GVL_Forensic_Journal.G_Last_Rollback_Event_Id := L_Record.Event_Id;
    ELSE
        L_Record.Activation_Event := TRUE;
        L_Record.Event_Class := 1;
        L_Record.Event_Severity := 1;
        L_Record.Event_Text := 'Topology activation completed';
        GVL_Forensic_Journal.G_Last_Activation_Event_Id := L_Record.Event_Id;
    END_IF;

    GVL_Forensic_Journal.G_Journal[L_Write_Index] := L_Record;
    GVL_Forensic_Journal.G_Last_Event_Id := L_Record.Event_Id;
    GVL_Forensic_Journal.G_Write_Index := L_Write_Index;
END_IF;

IF GVL_Runtime_Restart_Continuity.G_Continuity_State.Restore_Completed THEN
    L_Write_Index := GVL_Forensic_Journal.G_Write_Index + 1;

    IF L_Write_Index > 256 THEN
        L_Write_Index := 1;
    END_IF;

    L_Record.Record_Valid := TRUE;
    L_Record.Event_Time_MS := VI_System_Time_MS;
    L_Record.Event_Id := GVL_Forensic_Journal.G_Last_Event_Id + 1;
    L_Record.Restart_Event := TRUE;
    L_Record.Event_Class := 3;
    L_Record.Event_Severity := 1;
    L_Record.Config_Version := GVL_Runtime_Restart_Continuity.G_Continuity_State.Active_Config_Version;
    L_Record.Event_Text := 'Warm restart continuity restored';

    GVL_Forensic_Journal.G_Journal[L_Write_Index] := L_Record;
    GVL_Forensic_Journal.G_Last_Event_Id := L_Record.Event_Id;
    GVL_Forensic_Journal.G_Write_Index := L_Write_Index;
    GVL_Forensic_Journal.G_Last_Restart_Event_Id := L_Record.Event_Id;
END_IF;

IF GVL_Config_Activation.G_Config_Quarantine_Active THEN
    L_Write_Index := GVL_Forensic_Journal.G_Write_Index + 1;

    IF L_Write_Index > 256 THEN
        L_Write_Index := 1;
    END_IF;

    L_Record.Record_Valid := TRUE;
    L_Record.Event_Time_MS := VI_System_Time_MS;
    L_Record.Event_Id := GVL_Forensic_Journal.G_Last_Event_Id + 1;
    L_Record.Quarantine_Event := TRUE;
    L_Record.Event_Class := 4;
    L_Record.Event_Severity := 3;
    L_Record.Config_Version := GVL_Config_Activation.G_Activation_State.Staged_Version;
    L_Record.Event_Text := 'Config quarantine active';

    GVL_Forensic_Journal.G_Journal[L_Write_Index] := L_Record;
    GVL_Forensic_Journal.G_Last_Event_Id := L_Record.Event_Id;
    GVL_Forensic_Journal.G_Write_Index := L_Write_Index;
END_IF;

GVL_Forensic_Journal.G_Runtime_Valid := TRUE;
GVL_Forensic_Journal.G_Last_Update_MS := VI_System_Time_MS;
GVL_Forensic_Journal.G_Status_Code := 0;
GVL_Forensic_Journal.G_Status_Text := 'Persistent forensic journal active';

IF NOT VI_IsActivePLC THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    VO_Send_Code_Req := FALSE;
    VO_Code_To_Send := '';
    VO_Status_Msg := 'Охрана: резервный ПЛК';
    L_Arming_In_Progress := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    L_Pin_Entry_Active := FALSE;
    RETURN;
END_IF;

IF VI_Config.max_access_attempts < 1 THEN
    L_Max_Attempts := 1;
ELSE
    L_Max_Attempts := VI_Config.max_access_attempts;
END_IF;

IF VI_Config.pin_entry_timeout_seconds > 0 THEN
    L_Pin_Entry_Timeout_MS := VI_Config.pin_entry_timeout_seconds * 1000;
ELSIF VI_Config.entry_delay_seconds > 0 THEN
    L_Pin_Entry_Timeout_MS := VI_Config.entry_delay_seconds * 1000;
ELSE
    L_Pin_Entry_Timeout_MS := 45000;
END_IF;

IF VI_Config.combined_alarm_window_seconds > 0 THEN
    L_Combined_Window_MS := VI_Config.combined_alarm_window_seconds * 1000;
ELSE
    L_Combined_Window_MS := 10000;
END_IF;

R_Trig_Arm(CLK := VI_Arm_Request);
R_Trig_Disarm(CLK := VI_Disarm_Request);

// 1. Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := GVL_RETAIN.G_Access_Codes,
    VI_RFID_Tags := GVL_RETAIN.G_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Логика постановки на охрану (с задержкой на выход)
L_Auto_Arm_Trigger := FALSE;
IF VI_Config.auto_arm_enabled THEN
    IF VI_Current_TOD >= UDINT_TO_TOD(VI_Config.auto_arm_time_ms) THEN
        L_Auto_Arm_Trigger := TRUE;
    END_IF;
END_IF;
R_Trig_Auto_Arm(CLK := L_Auto_Arm_Trigger);

IF ((R_Trig_Arm.Q AND L_Valid_PIN) OR R_Trig_Auto_Arm.Q) AND NOT VO_Armed AND NOT L_Arming_In_Progress THEN
    L_Door_Blocking_Open := FALSE;
    L_Window_Blocking_Open := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
        IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN
            L_Door_Blocking_Open := TRUE;
        END_IF;
    END_FOR;

    FOR L_i := 1 TO 16 DO
        IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] THEN
            L_Window_Blocking_Open := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Door_Blocking_Open AND (NOT L_Window_Blocking_Open OR VI_Config.allow_short_away_open_windows) THEN
        FOR L_i := 1 TO 16 DO
            L_Allowed_Open_Windows[L_i] :=
                VI_Config.allow_short_away_open_windows
                AND VI_Window_Sensors[L_i]
                AND NOT VI_Bypass_Windows[L_i];
        END_FOR;

        L_Arming_In_Progress := TRUE;
        L_PIN_Fail_Count := 0;
        L_Pin_Entry_Active := FALSE;
        L_Combined_Window_Active := FALSE;
        L_Combined_Event_Count := 0;
        VO_Status_Msg := 'Постановка на охрану. Покиньте помещение.';
    ELSE
        IF L_Door_Blocking_Open THEN
            VO_Status_Msg := 'Ошибка постановки: Открыты двери';
        ELSE
            VO_Status_Msg := 'Ошибка постановки: Открыты окна';
        END_IF;
    END_IF;
END_IF;

L_Arm_Delay_Timer(IN := L_Arming_In_Progress, PT := TO_TIME(VI_Config.exit_delay_seconds * 1000), VI_System_Time_MS := VI_System_Time_MS);
IF L_Arm_Delay_Timer.Q THEN
    L_Arming_In_Progress := FALSE;
    VO_Armed := TRUE;
    VO_Status_Msg := 'Система под охраной';
END_IF;

// 3. Логика снятия с охраны с PIN/RFID и 2FA
IF R_Trig_Disarm.Q AND VO_Armed THEN
    IF L_Valid_PIN THEN
        L_PIN_Fail_Count := 0;

        IF VI_Config.enable_2fa THEN
            L_Disarm_Pending := TRUE;
            L_2FA_Required := TRUE;
            VO_Status_Msg := 'Ожидание 2FA для снятия с охраны';
        ELSE
            VO_Armed := FALSE;
            VO_Alarm_Active := FALSE;
            VO_Siren_Active := FALSE;
            L_Arming_In_Progress := FALSE;
            L_Pin_Entry_Active := FALSE;
            L_Combined_Window_Active := FALSE;
            L_Combined_Event_Count := 0;
            FOR L_i := 1 TO 16 DO
                L_Allowed_Open_Windows[L_i] := FALSE;
            END_FOR;
            VO_Status_Msg := 'Система снята с охраны';
        END_IF;
    ELSE
        IF L_PIN_Fail_Count < 255 THEN
            L_PIN_Fail_Count := L_PIN_Fail_Count + 1;
        END_IF;

        IF L_PIN_Fail_Count >= L_Max_Attempts THEN
            VO_Alarm_Active := TRUE;
            VO_Siren_Active := TRUE;
            VO_Status_Msg := 'ТРЕВОГА! Превышено количество попыток PIN';
        ELSE
            VO_Status_Msg := 'Неверный PIN/RFID';
        END_IF;
    END_IF;
END_IF;

fbTwoFactor(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Start_Auth := L_2FA_Required,
    VI_Method := E_TwoFactor_Method.TF_METHOD_TOTP,
    VI_User_Code := VI_2FA_Code,
    VI_Reset_Success := L_Reset_2FA
);

VO_Send_Code_Req := fbTwoFactor.VO_Send_Code_Req;
VO_Code_To_Send := fbTwoFactor.VO_Code_To_Send;

IF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Success THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    L_Arming_In_Progress := FALSE;
    L_Pin_Entry_Active := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := TRUE;
    L_Combined_Window_Active := FALSE;
    L_Combined_Event_Count := 0;
    FOR L_i := 1 TO 16 DO
        L_Allowed_Open_Windows[L_i] := FALSE;
    END_FOR;
    VO_Status_Msg := 'Система снята с охраны';
ELSIF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Locked THEN
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    VO_Status_Msg := 'Ошибка 2FA: Превышено количество попыток';
ELSE
    L_Reset_2FA := FALSE;
END_IF;

// 4. Логика тревоги: задержка PIN + комбинированная авария датчиков
IF VO_Armed THEN
    FOR L_i := 1 TO 16 DO
        IF L_Allowed_Open_Windows[L_i] AND NOT VI_Window_Sensors[L_i] THEN
            L_Allowed_Open_Windows[L_i] := FALSE;
        END_IF;
    END_FOR;

    L_Any_Sensor_Active := FALSE;
    L_Intrusion_Active_Count := 0;
    L_Intrusion_Event_Count := 0;

    FOR L_i := 1 TO 16 DO
        IF VI_Motion_Sensors[L_i] AND NOT VI_Bypass_Motion[L_i] THEN
            L_Any_Sensor_Active := TRUE;
            L_Intrusion_Active_Count := L_Intrusion_Active_Count + 1;
            IF NOT L_Prev_Motion_Sensors[L_i] THEN
                L_Intrusion_Event_Count := L_Intrusion_Event_Count + 1;
            END_IF;
        END_IF;
        L_Prev_Motion_Sensors[L_i] := VI_Motion_Sensors[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
        IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN
            L_Any_Sensor_Active := TRUE;
            L_Intrusion_Active_Count := L_Intrusion_Active_Count + 1;
            IF NOT L_Prev_Door_Sensors[L_i] THEN
                L_Intrusion_Event_Count := L_Intrusion_Event_Count + 1;
            END_IF;
        END_IF;
        L_Prev_Door_Sensors[L_i] := VI_Door_Sensors[L_i];
    END_FOR;

    FOR L_i := 1 TO 16 DO
        IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] AND NOT L_Allowed_Open_Windows[L_i] THEN
            L_Any_Sensor_Active := TRUE;
            L_Intrusion_Active_Count := L_Intrusion_Active_Count + 1;
            IF NOT L_Prev_Window_Sensors[L_i] THEN
                L_Intrusion_Event_Count := L_Intrusion_Event_Count + 1;
            END_IF;
        END_IF;
        L_Prev_Window_Sensors[L_i] := VI_Window_Sensors[L_i];
    END_FOR;

    IF L_Intrusion_Event_Count > 0 THEN
        IF NOT L_Combined_Window_Active THEN
            L_Combined_Window_Active := TRUE;
            L_Combined_First_Event_MS := VI_System_Time_MS;
            L_Combined_Event_Count := L_Intrusion_Event_Count;
        ELSE
            IF VI_System_Time_MS >= L_Combined_First_Event_MS THEN
                L_Combined_Elapsed_MS := VI_System_Time_MS - L_Combined_First_Event_MS;
            ELSE
                L_Combined_Elapsed_MS := (4294967295 - L_Combined_First_Event_MS) + VI_System_Time_MS + 1;
            END_IF;

            IF L_Combined_Elapsed_MS <= L_Combined_Window_MS THEN
                L_Combined_Event_Count := L_Combined_Event_Count + L_Intrusion_Event_Count;
            ELSE
                L_Combined_First_Event_MS := VI_System_Time_MS;
                L_Combined_Event_Count := L_Intrusion_Event_Count;
            END_IF;
        END_IF;
    END_IF;

    IF L_Combined_Window_Active THEN
        IF VI_System_Time_MS >= L_Combined_First_Event_MS THEN
            L_Combined_Elapsed_MS := VI_System_Time_MS - L_Combined_First_Event_MS;
        ELSE
            L_Combined_Elapsed_MS := (4294967295 - L_Combined_First_Event_MS) + VI_System_Time_MS + 1;
        END_IF;

        IF L_Combined_Elapsed_MS > L_Combined_Window_MS THEN
            L_Combined_Window_Active := FALSE;
            L_Combined_Event_Count := 0;
        END_IF;
    END_IF;

    IF (L_Intrusion_Active_Count >= 2) OR (L_Combined_Window_Active AND (L_Combined_Event_Count >= 2)) THEN
        VO_Alarm_Active := TRUE;
        VO_Siren_Active := TRUE;
        L_Pin_Entry_Active := FALSE;
        VO_Status_Msg := 'ТРЕВОГА! Комбинированное нарушение периметра';
    ELSIF L_Any_Sensor_Active THEN
        L_Pin_Entry_Active := TRUE;
    END_IF;

    L_Alarm_Delay_Timer(IN := L_Pin_Entry_Active, PT := TO_TIME(L_Pin_Entry_Timeout_MS), VI_System_Time_MS := VI_System_Time_MS);

    IF L_Alarm_Delay_Timer.Q THEN
        VO_Alarm_Active := TRUE;
        VO_Siren_Active := TRUE;
        VO_Status_Msg := 'ТРЕВОГА! Нарушение периметра';
    ELSIF L_Pin_Entry_Active AND NOT VO_Alarm_Active THEN
        VO_Status_Msg := 'Внимание! Введите PIN-код для отмены тревоги';
    END_IF;
ELSE
    L_Pin_Entry_Active := FALSE;
    L_Alarm_Delay_Timer(IN := FALSE, PT := T#0s, VI_System_Time_MS := VI_System_Time_MS);
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Security_System_Manager <<<

// ==============================================================================
// Heating runtime diagnostics phase
// Owns diagnostics publication for heating runtime sequencing.
// Does NOT own heating control or output decisions.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// ROOT CAUSE DIAGNOSTICS
// ======================================================
fbRootCauseDiagnostics(
    VI_Enable := TRUE
);

// ======================================================
// DEFAULTS
// ======================================================
L_Any_Heating_Device_OOS := FALSE;
L_Critical_Fault := FALSE;
L_Device_Text := '';
L_Critical_Text := '';
L_Event_Text := '';
L_Add_Text := '';

// ======================================================
// SERVICE / OUT-OF-SERVICE FLAGS
// ======================================================
GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service :=
    NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service;

GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service :=
    NOT GVL_CONFIG.G_Electric_Heater_In_Service;

IF GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service THEN
    L_Any_Heating_Device_OOS := TRUE;
    L_Add_Text := 'backup pump out of service';
    L_Device_Text := L_Add_Text;
END_IF;

IF GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service THEN
    L_Any_Heating_Device_OOS := TRUE;
    L_Add_Text := 'electric heater out of service';
    IF LEN(L_Device_Text) = 0 THEN
        L_Device_Text := L_Add_Text;
    ELSIF (LEN(L_Device_Text) + LEN(L_Add_Text) + 2) < 200 THEN
        L_Device_Text := CONCAT(L_Device_Text, CONCAT('; ', L_Add_Text));
    END_IF;
END_IF;

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_BACKUP_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 400,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_ELECTRIC_HEATER_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 401,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO

    GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] :=
        NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];

    IF GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] THEN
        L_Any_Heating_Device_OOS := TRUE;
        L_Add_Text := CONCAT('manifold pump OOS #', INT_TO_STRING(L_i));

        IF LEN(L_Device_Text) = 0 THEN
            L_Device_Text := L_Add_Text;
        ELSIF (LEN(L_Device_Text) + LEN(L_Add_Text) + 2) < 200 THEN
            L_Device_Text := CONCAT(L_Device_Text, CONCAT('; ', L_Add_Text));
        END_IF;
    END_IF;

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_MANIFOLD_PUMP_OUT_OF_SERVICE,
        VI_Severity := 2,
        VI_Active := GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i],
        VI_Timestamp := VI_System_Time_MS,
        VI_Source := 410 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );

END_FOR;

GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service :=
    NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service;

GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service :=
    NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service;

IF GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service THEN
    L_Any_Heating_Device_OOS := TRUE;
    L_Add_Text := 'DHW heating pump out of service';

    IF LEN(L_Device_Text) = 0 THEN
        L_Device_Text := L_Add_Text;
    ELSIF (LEN(L_Device_Text) + LEN(L_Add_Text) + 2) < 200 THEN
        L_Device_Text := CONCAT(L_Device_Text, CONCAT('; ', L_Add_Text));
    END_IF;
END_IF;

IF GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service THEN
    L_Any_Heating_Device_OOS := TRUE;
    L_Add_Text := 'DHW circ pump out of service';

    IF LEN(L_Device_Text) = 0 THEN
        L_Device_Text := L_Add_Text;
    ELSIF (LEN(L_Device_Text) + LEN(L_Add_Text) + 2) < 200 THEN
        L_Device_Text := CONCAT(L_Device_Text, CONCAT('; ', L_Add_Text));
    END_IF;
END_IF;

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_DHW_HEATING_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 420,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_DHW_CIRC_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 421,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

// ======================================================
// FREEZE HARDWARE EVENT PROJECTION
// ======================================================
L_Critical_Fault := GVL_STATE.G_Freeze_Hardware_Failed;

IF L_Critical_Fault THEN
    L_Critical_Text := 'Freeze hardware critical fault';
END_IF;

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_FREEZE_HARDWARE_FAILED,
    VI_Severity := 4,
    VI_Active := L_Critical_Fault,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 430,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

GVL_STATUS.G_Diagnostics.Freeze_Hardware_Event_Pending :=
    GVL_STATUS.G_Diagnostics.Freeze_Hardware_Event_Pending OR
    L_Critical_Fault OR
    L_Any_Heating_Device_OOS;

IF L_Critical_Fault AND L_Any_Heating_Device_OOS THEN
    L_Event_Text := CONCAT(L_Critical_Text, '; ');
    IF (LEN(L_Event_Text) + LEN(L_Device_Text)) < 200 THEN
        L_Event_Text := CONCAT(L_Event_Text, L_Device_Text);
    END_IF;
    GVL_STATUS.G_Diagnostics.Freeze_Hardware_Event_Text := L_Event_Text;
ELSIF L_Critical_Fault THEN
    GVL_STATUS.G_Diagnostics.Freeze_Hardware_Event_Text := L_Critical_Text;
ELSIF L_Any_Heating_Device_OOS THEN
    GVL_STATUS.G_Diagnostics.Freeze_Hardware_Event_Text := L_Device_Text;
END_IF;

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Diagnostics_Phase <<<

L_Outdoor := GVL_STATE.G_Outdoor_Temp;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_DeltaT := GVL_STATE.G_Room_Temps[L_i] - L_Outdoor;

    L_Loss := L_DeltaT * REAL#0.01 * GVL_HEATING_POLICY.G_Zone_Thermal_Inertia[L_i];

    L_Gain := (GVL_STATE.G_Floor_Temps[L_i] - GVL_STATE.G_Room_Temps[L_i]) * REAL#0.05;

    GVL_HEATING_POLICY.G_Zone_Heat_Loss_Rate[L_i] := L_Loss;
    GVL_HEATING_POLICY.G_Zone_Heat_Gain_Rate[L_i] := L_Gain;

    GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] := L_Gain - L_Loss;

    GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := 
        GVL_STATE.G_Target_Temperature - GVL_STATE.G_Room_Temps[L_i];

    IF ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) > REAL#0.01 THEN
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 
            REAL_TO_UDINT(ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] /
                  GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) * REAL#60000.0);
    ELSE
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Predicted_Temp_30m[L_i] :=
        GVL_STATE.G_Room_Temps[L_i] + 
        GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] * REAL#30.0;

    GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] :=
        LIMIT(REAL#0.0, REAL#1.0, ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]));

END_FOR;

VO_Send_Telegram := FALSE;
IF VI_Fire_Alarm_Active AND NOT L_Prev_Fire THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПОЖАРНАЯ ТРЕВОГА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Gas_Alarm_Active AND NOT L_Prev_Gas THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! УТЕЧКА ГАЗА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Flood_Alarm_Active AND NOT L_Prev_Flood THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПРОТЕЧКА ВОДЫ!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Security_Armed AND NOT L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ВКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
ELSIF NOT VI_Security_Armed AND L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ОТКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
END_IF;

L_Prev_Fire := VI_Fire_Alarm_Active;
L_Prev_Gas := VI_Gas_Alarm_Active;
L_Prev_Flood := VI_Flood_Alarm_Active;
L_Prev_Security := VI_Security_Armed;

IF (VI_System_Time_MS - L_last_update_time) >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
    L_last_update_time := VI_System_Time_MS;
    L_tmp_word := 0;
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN L_tmp_word := L_tmp_word OR 1; END_IF;
    IF VI_Security_Armed THEN L_tmp_word := L_tmp_word OR 2; END_IF;
    IF VI_Flood_Alarm_Active THEN L_tmp_word := L_tmp_word OR 4; END_IF;
    IF VI_Gas_Alarm_Active THEN L_tmp_word := L_tmp_word OR 8; END_IF;
    IF VI_Fire_Alarm_Active THEN L_tmp_word := L_tmp_word OR 16; END_IF;
    VO_Modbus_Registers[0] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Modbus_Registers[L_i] := TO_WORD(TO_INT(VI_FloorHeating_Temps[L_i] * REAL#10.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        VO_Modbus_Registers[16 + L_i] := TO_WORD(TO_INT(VI_Room_Temps[L_i] * REAL#10.0));
    END_FOR;

    L_tmp_word := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF VI_Zone_Valve_States[L_i] THEN
            L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_i - 1);
        END_IF;
    END_FOR;
    VO_Modbus_Registers[33] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Modbus_Registers[33 + L_i] := TO_WORD(TO_INT(VI_Manifold_Pressures[L_i] * REAL#100.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        VO_Modbus_Registers[39 + L_i] := TO_WORD(VI_Lighting_Base_Levels[L_i]);
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        VO_Modbus_Registers[71 + L_i] := TO_WORD(VI_Blinds_Positions[L_i]);
    END_FOR;

    FOR L_i := 0 TO (GVL_CONSTANTS.C_MAX_SOCKETS - 1) / 16 DO
        L_tmp_word := 0;
        FOR L_j := 1 TO 16 DO
            L_idx := (L_i * 16) + L_j;
            IF L_idx <= GVL_CONSTANTS.C_MAX_SOCKETS THEN
                IF VI_Socket_States[L_idx] THEN
                    L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_j - 1);
                END_IF;
            END_IF;
        END_FOR;
        VO_Modbus_Registers[92 + L_i] := L_tmp_word;
    END_FOR;

    VO_Modbus_Registers[100] := SEL(VI_Send_2FA_Req, 0, 1);
    IF VI_Send_2FA_Req THEN
        L_Code_UDINT := STRING_TO_UDINT(VI_2FA_Code);
        VO_Modbus_Registers[101] := TO_WORD(L_Code_UDINT AND 16#FFFF);
        VO_Modbus_Registers[102] := TO_WORD(SHR(L_Code_UDINT, 16));
    ELSE
        VO_Modbus_Registers[101] := 0;
        VO_Modbus_Registers[102] := 0;
    END_IF;

    VO_Data_Ready := TRUE;
END_IF;

VO_Arm_Req := FALSE;
VO_Disarm_Req := FALSE;
VO_Set_Scenario_Req := FALSE;
VO_Set_Temp_Req := FALSE;
VO_Set_Vent_Req := FALSE;
VO_Reset_Errors_Req := FALSE;
VO_Set_Config_Req := FALSE;
VO_Sync_Time_Req := FALSE;
L_Has_Command_To_Process := FALSE;

IF VI_Command_Received THEN
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN
        L_Process_Command := VI_Incoming_Command;
        L_Has_Command_To_Process := TRUE;
    ELSE
        IF L_Buffer_Count < GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN
            L_Command_Buffer[L_Buffer_Head] := VI_Incoming_Command;
            L_Buffer_Head := L_Buffer_Head + 1;
            IF L_Buffer_Head > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Head := 1; END_IF;
            L_Buffer_Count := L_Buffer_Count + 1;
        END_IF;
    END_IF;
END_IF;

IF NOT L_Has_Command_To_Process AND (VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE) AND (L_Buffer_Count > 0) THEN
    L_Process_Command := L_Command_Buffer[L_Buffer_Tail];
    L_Buffer_Tail := L_Buffer_Tail + 1;
    IF L_Buffer_Tail > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Tail := 1; END_IF;
    L_Buffer_Count := L_Buffer_Count - 1;
    L_Has_Command_To_Process := TRUE;
END_IF;

IF L_Has_Command_To_Process THEN
    L_IP_Allowed := FALSE;
    IF L_Process_Command.source_ip = '' THEN
        L_IP_Allowed := TRUE;
    ELSE
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALLOWED_IPS DO
            IF VI_Allowed_IPs[L_i] = L_Process_Command.source_ip THEN
                L_IP_Allowed := TRUE;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    IF NOT L_IP_Allowed THEN
        VO_HMI_Status_Message := 'Gateway: Ошибка безопасности (Неизвестный IP)';
        RETURN;
    END_IF;

    IF L_Process_Command.crc32 <> DWORD#0 THEN
        VO_HMI_Status_Message := 'Gateway: CRC unsupported in legacy mode';
        RETURN;
    END_IF;

    L_Deduplicator(
        VI_Command_ID := L_Process_Command.command_id,
        VI_Command_Type := L_Process_Command.command_type,
        VI_Command_Value := L_Process_Command.target_value,
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF L_Deduplicator.VO_Is_New_Command THEN
        CASE L_Process_Command.command_type OF
            E_Gateway_Command_Type.CMD_SET_SCENARIO:
                VO_Set_Scenario_Req := TRUE;
                VO_Target_Scenario := L_Process_Command.target_scenario;
                VO_HMI_Status_Message := 'Gateway: Сценарий изменен';
            E_Gateway_Command_Type.CMD_SET_LIGHT:
                IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
                    VO_Lighting_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Команда освещения принята';
                END_IF;
            E_Gateway_Command_Type.CMD_SET_BLINDS:
                IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_BLINDS) THEN
                    VO_Blinds_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Команда штор принята';
                END_IF;
            E_Gateway_Command_Type.CMD_SET_SOCKET:
                IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_SOCKETS) THEN
                    VO_Socket_Override[L_Process_Command.target_zone] := L_Process_Command.target_on_off;
                    VO_HMI_Status_Message := 'Gateway: Команда розетки принята';
                END_IF;
            E_Gateway_Command_Type.CMD_SET_SECURITY:
                IF L_Process_Command.target_armed THEN VO_Arm_Req := TRUE; ELSE VO_Disarm_Req := TRUE; END_IF;
                VO_PIN_Code := L_Process_Command.target_pin;
                VO_2FA_Code_In := L_Process_Command.target_2fa_code;
                VO_HMI_Status_Message := 'Gateway: Запрос охраны принят';
            E_Gateway_Command_Type.CMD_SET_TEMP:
                IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
                    VO_Set_Temp_Req := TRUE;
                    VO_Target_Zone := L_Process_Command.target_zone;
                    VO_Target_Temp := L_Process_Command.target_value;
                    VO_HMI_Status_Message := 'Gateway: Уставка температуры изменена';
                END_IF;
            E_Gateway_Command_Type.CMD_SET_VENT:
                VO_Set_Vent_Req := TRUE;
                VO_Target_Vent_Speed := TO_BYTE(L_Process_Command.target_value);
                VO_HMI_Status_Message := 'Gateway: Уставка вентиляции изменена';
            E_Gateway_Command_Type.CMD_TELEGRAM_MSG:
                VO_Telegram_Msg := L_Process_Command.telegram_msg;
                VO_Send_Telegram := TRUE;
                VO_HMI_Status_Message := 'Gateway: Сообщение Telegram отправлено';
            E_Gateway_Command_Type.CMD_SYNC_TIME:
                VO_Sync_Time_Req := TRUE;
                VO_New_Time_MS := REAL_TO_UDINT(L_Process_Command.target_value);
                VO_HMI_Status_Message := 'Gateway: Время синхронизировано';
            E_Gateway_Command_Type.CMD_RESET_ERRORS:
                VO_Reset_Errors_Req := TRUE;
                VO_HMI_Status_Message := 'Gateway: Запрос на сброс ошибок принят';
            E_Gateway_Command_Type.CMD_SET_CONFIG:
                VO_Set_Config_Req := TRUE;
                VO_HMI_Status_Message := 'Gateway: Запрос на применение конфигурации принят';
        END_CASE;
    ELSE
        VO_HMI_Status_Message := 'Gateway: duplicate command ignored';
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Gateway_Interface <<<

// ==============================================================================
// Heating manifold control helper
// Internal refactoring helper for FB_Heating_System_Manager.
// Valve test override remains in FB_Heating_System_Manager for now.
// ==============================================================================



FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Status := L_Empty_Status;

    L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
    IF L_PID_Timer[L_i].Q THEN
        L_PID_Timer[L_i](IN := FALSE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
        L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);

        L_PID_Valves[L_i](
            VI_SetPoint := VI_Target_Supply_Temp,
            VI_ProcessValue := VI_Manifold_Temps_Supply[L_i],
            VI_Kp := 2.0,
            VI_Tn := 120.0,
            VI_Tv := 0.0,
            VI_Y_Min := 0.0,
            VI_Y_Max := 100.0,
            VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Manifold_Valves[L_i]
        );
    END_IF;

    L_Pump_Run_Timer[L_i](
        IN := VO_Manifold_Pumps[L_i] AND NOT L_Pump_In_Pause[L_i],
        PT := T#72h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Run_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := TRUE;
    END_IF;

    L_Pump_Pause_Timer[L_i](
        IN := L_Pump_In_Pause[L_i],
        PT := T#1h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Pause_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := FALSE;
    END_IF;

    IF VI_DHW_Heating_Demand THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0;
    ELSE
        VO_Manifold_Pumps[L_i] := VI_IsActivePLC AND VI_Any_Zone_Active[L_i] AND NOT L_Pump_In_Pause[L_i];
        IF NOT VO_Manifold_Pumps[L_i] AND NOT VI_Freeze_Mode_Active THEN
            VO_Manifold_Valves[L_i] := 0.0;
        END_IF;
    END_IF;

    IF VI_Freeze_Mode_Active THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        IF VO_Manifold_Valves[L_i] < 35.0 THEN
            VO_Manifold_Valves[L_i] := 35.0;
        END_IF;
    END_IF;

    L_Status.Pump_On := VO_Manifold_Pumps[L_i];
    L_Status.Pump_Current := VI_Manifold_Currents[L_i];
    L_Status.Pressure := VI_Manifold_Pressures[L_i];
    L_Status.Temp_Supply := VI_Manifold_Temps_Supply[L_i];
    L_Status.Temp_Return := VI_Manifold_Temps_Return[L_i];
    L_Status.Valve_Pos := VO_Manifold_Valves[L_i];

    L_Pump_Diag[L_i](
        VI_Current_Value := VI_Manifold_Currents[L_i],
        VI_Nominal_Value := 0.55,
        VI_Is_Running := VO_Manifold_Pumps[L_i],
        VI_Reset_Stats := FALSE,
        VI_System_Time_MS := VI_System_Time_MS,
        VIO_Health_Data := L_Status.Health
    );

    IF VO_Manifold_Pumps[L_i] THEN
        L_Delta_T := VI_Manifold_Temps_Supply[L_i] - VI_Manifold_Temps_Return[L_i];

        L_Status.Error := FALSE;
        L_Status.Error_ID := 0;

        IF VI_Manifold_Currents[L_i] <= 0.01 THEN
            L_Status.Error := TRUE;
            L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_NO_CURRENT);
        ELSIF VI_Manifold_Currents[L_i] < 0.3 THEN
            L_Status.Error := TRUE;
            L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_UNDERCURRENT);
        ELSIF VI_Manifold_Currents[L_i] > 1.5 THEN
            L_Status.Error := TRUE;
            L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_OVERCURRENT);
        END_IF;

        IF (NOT L_Status.Error) AND ((VI_Manifold_Pressures[L_i] < 1.5) OR (VI_Manifold_Pressures[L_i] > 2.5)) THEN
            L_Status.Error := TRUE;
            L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE);
        END_IF;

        IF NOT L_Status.Error THEN
            IF L_Delta_T < 5.0 THEN
                L_Status.Error := TRUE;
                L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_LOW);
            ELSIF L_Delta_T > 10.0 THEN
                L_Status.Error := TRUE;
                L_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_HIGH);
            END_IF;
        END_IF;
    END_IF;

    VO_Status[L_i] := L_Status;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Manifold_Control <<<

IF NOT VI_Enable THEN
    GVL_Distributed_Orchestration.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_State.Runtime_Valid := TRUE;
L_State.Runtime_System_Time_MS := VI_System_Time_MS;

L_State.Orchestration_Sequence_Id :=
    GVL_Distributed_Orchestration.G_Last_Distributed_Sequence_Id + 1;

L_State.Distributed_Execution_Active := TRUE;

L_State.Cross_Node_Isolation_Required :=
    GVL_Distributed_Orchestration.G_Cross_Node_Isolation_Active;

L_State.Cross_Node_Recovery_Required :=
    GVL_Distributed_Orchestration.G_Cross_Node_Recovery_Active;

L_State.Cross_Node_Rollback_Required :=
    GVL_Distributed_Orchestration.G_Cross_Node_Rollback_Active;

L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

L_State.Distributed_Scheduler_Healthy :=
    GVL_Runtime_Bus.G_TX_Healthy
    AND GVL_Distributed_Runtime.G_Distributed_Authority_Healthy
    AND L_Finalized_Runtime_Continuity;

L_State.Distributed_Timing_Window_Valid :=
    GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK
    AND L_Finalized_Runtime_Continuity;

IF L_State.Distributed_Scheduler_Healthy
   AND L_State.Distributed_Timing_Window_Valid THEN
    L_State.Distributed_Projection_Granted := TRUE;
    L_State.Distributed_Recovery_Allowed := TRUE;
    L_State.Distributed_Rollback_Allowed := TRUE;
    L_State.Status_Code := 0;
    L_State.Status_Text := 'Distributed orchestration runtime healthy';
ELSE
    L_State.Distributed_Projection_Blocked := TRUE;
    L_State.Distributed_Conflict_Detected := TRUE;
    L_State.Status_Code := 2;
    L_State.Status_Text := 'Distributed orchestration blocked';
END_IF;

IF GVL_Distributed_Runtime.G_Split_Brain_Suspected THEN
    L_State.Distributed_Split_Execution_Suspected := TRUE;
    L_State.Distributed_Projection_Blocked := TRUE;
    L_State.Status_Code := 3;
    L_State.Status_Text := 'Distributed split execution suspected';
END_IF;

GVL_Distributed_Orchestration.G_Orchestration_State := L_State;
GVL_Distributed_Orchestration.G_Last_Distributed_Sequence_Id := L_State.Orchestration_Sequence_Id;
GVL_Distributed_Orchestration.G_Distributed_Projection_Healthy := L_State.Distributed_Projection_Granted;
GVL_Distributed_Orchestration.G_Distributed_Scheduler_Healthy := L_State.Distributed_Scheduler_Healthy;
GVL_Distributed_Orchestration.G_Runtime_Valid := TRUE;
GVL_Distributed_Orchestration.G_Last_Update_MS := VI_System_Time_MS;
GVL_Distributed_Orchestration.G_Status_Code := L_State.Status_Code;
GVL_Distributed_Orchestration.G_Status_Text := L_State.Status_Text;

// Сброс выходов по умолчанию
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Enable[L_i] := FALSE;
    VO_Boiler_Setpoint[L_i] := 0.0;
END_FOR;

// Инициализация ротации
IF NOT L_Rotation_Initialized THEN
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Rotation_Initialized := TRUE;
END_IF;

// Принудительная остановка
IF VI_Boiler_Stop THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Ротация строго каждые 168 часов
IF (VI_System_Time_MS - L_Last_Rotation_MS) >= L_Rotation_Period_MS THEN
    IF GVL_CONSTANTS.C_MAX_BOILERS > 1 THEN
        L_Lead_Boiler := 3 - L_Lead_Boiler;
    END_IF;
    L_Last_Rotation_MS := VI_System_Time_MS;
END_IF;

L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);

L_Lead_Available :=
    VI_Boiler_OT_Online[L_Lead_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Lead_Boiler];

L_Reserve_Available :=
    (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
    VI_Boiler_OT_Online[L_Reserve_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Reserve_Boiler];

// Контроль "команда есть, пламени нет" для ведущего котла
L_Flame_Miss_Timer[L_Lead_Boiler](
    IN := VI_Enable AND L_Lead_Available AND NOT VI_DHW_Heating_Demand AND NOT VI_Boiler_Flame_Status[L_Lead_Boiler],
    PT := T#120s
);

IF L_Flame_Miss_Timer[L_Lead_Boiler].Q AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Lead_Available :=
        VI_Boiler_OT_Online[L_Lead_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Lead_Boiler];
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Нет запроса тепла
IF NOT VI_Enable THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Целевая уставка
IF VI_DHW_Heating_Demand THEN
    L_Target_Setpoint := LIMIT(20.0, VI_DHW_Target_Temp + 15.0, 85.0);
ELSE
    L_Target_Setpoint := LIMIT(20.0, VI_Target_Supply_Temp + 5.0, 80.0);
END_IF;

// Выбор ведущего по доступности
IF NOT L_Lead_Available AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Lead_Available := TRUE;
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Основной котёл
IF L_Lead_Available THEN
    VO_Boiler_Enable[L_Lead_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Lead_Boiler] := L_Target_Setpoint;
END_IF;

// Резервный котёл: >80% или отказ основного
L_Start_Reserve :=
    L_Reserve_Available AND
    (
        (VI_Demand_Power > 80.0) OR
        (NOT L_Lead_Available)
    );

IF L_Start_Reserve THEN
    VO_Boiler_Enable[L_Reserve_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Reserve_Boiler] := L_Target_Setpoint;
END_IF;

VO_Lead_Boiler := L_Lead_Boiler;

IF NOT VI_Config.enabled THEN
    RETURN;
END_IF;

L_Deviation := ABS(VI_Current_Value - L_Last_Value);

IF VI_System_Time_MS >= L_Last_Log_Time THEN
    L_Elapsed_Time := VI_System_Time_MS - L_Last_Log_Time;
ELSE
    L_Elapsed_Time := (4294967295 - L_Last_Log_Time) + VI_System_Time_MS + 1;
END_IF;

IF (L_Deviation >= (ABS(L_Last_Value) * VI_Config.deviation_threshold_percent / REAL#100.0)) OR
   (L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_HOUR) THEN
    L_Write_Index := (VO_Data.record_count MOD 100) + 1;
    VO_Data.write_index := L_Write_Index;
    VO_Data.values[L_Write_Index] := VI_Current_Value;
    VO_Data.timestamps[L_Write_Index] := VI_System_Time_MS;
    VO_Data.record_count := VO_Data.record_count + 1;
    VO_Data.sum_values := VO_Data.sum_values + VI_Current_Value;
    VO_Data.config := VI_Config;
    L_Last_Value := VI_Current_Value;
    L_Last_Log_Time := VI_System_Time_MS;
END_IF;

// ==============================================================================
// System persist manager helper
//
// Internal helper for PRG_System.
// Owns persistent snapshot packing, controlled NVRAM write gating,
// FB_NVRAM_Manager call, and last-written buffer tracking.
// ==============================================================================



// Pack persistent snapshot into compact byte buffer for controlled NVRAM mirroring
VIO_Persist_Buffer[0] := TO_BYTE(TO_INT(GVL_STATE.G_System_Mode));
IF GVL_PERSISTENT.P_Safety_Gas_Latched THEN
    VIO_Persist_Buffer[1] := BYTE#1;
ELSE
    VIO_Persist_Buffer[1] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_Safety_Smoke_Latched THEN
    VIO_Persist_Buffer[2] := BYTE#1;
ELSE
    VIO_Persist_Buffer[2] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_Safety_Leak_Latched THEN
    VIO_Persist_Buffer[3] := BYTE#1;
ELSE
    VIO_Persist_Buffer[3] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_DHW_Heating_Active THEN
    VIO_Persist_Buffer[4] := BYTE#1;
ELSE
    VIO_Persist_Buffer[4] := BYTE#0;
END_IF;

VIO_Persist_Buffer_Changed :=
    (VIO_Persist_Buffer[0] <> VIO_Last_Written_Persist_Buffer[0]) OR
    (VIO_Persist_Buffer[1] <> VIO_Last_Written_Persist_Buffer[1]) OR
    (VIO_Persist_Buffer[2] <> VIO_Last_Written_Persist_Buffer[2]) OR
    (VIO_Persist_Buffer[3] <> VIO_Last_Written_Persist_Buffer[3]) OR
    (VIO_Persist_Buffer[4] <> VIO_Last_Written_Persist_Buffer[4]);

VIO_NVRAM_Cmd := 0;
VIO_NVRAM_Offset := 0;

IF GVL_CONFIG.G_HMI_Apply_Settings THEN
    // explicit config apply may request a controlled write
    VIO_NVRAM_Cmd := 1;
    GVL_CONFIG.G_HMI_Apply_Settings := FALSE;

ELSIF VIO_Persist_Buffer_Changed THEN
    // controlled write: no more often than once per 60 seconds
    IF (VIO_Last_Persist_Write_MS = 0) OR
       ((VI_System_Time_MS - VIO_Last_Persist_Write_MS) >= 60000) THEN
        VIO_NVRAM_Cmd := 1;
    END_IF;
END_IF;

fbNVRAMManager(
    VI_Command := VIO_NVRAM_Cmd,
    VI_Offset := VIO_NVRAM_Offset,
    VI_DataRef := VIO_Persist_Buffer[0],
    VI_DataSize := 5,
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Operator_ID := 'SYSTEM',
    VI_IsActivePLC := VI_IsActivePLC,
    VI_TwoPersonConfirmation := FALSE,
    VO_Done => VIO_NVRAM_Done,
    VO_Error => VIO_NVRAM_Err,
    VO_ErrorID => VIO_NVRAM_ErrID
);

IF (VIO_NVRAM_Cmd = 1) AND VIO_NVRAM_Done AND NOT VIO_NVRAM_Err THEN
    VIO_Last_Written_Persist_Buffer[0] := VIO_Persist_Buffer[0];
    VIO_Last_Written_Persist_Buffer[1] := VIO_Persist_Buffer[1];
    VIO_Last_Written_Persist_Buffer[2] := VIO_Persist_Buffer[2];
    VIO_Last_Written_Persist_Buffer[3] := VIO_Persist_Buffer[3];
    VIO_Last_Written_Persist_Buffer[4] := VIO_Persist_Buffer[4];
    VIO_Last_Persist_Write_MS := VI_System_Time_MS;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Persist_Manager <<<

IF NOT VI_Enable THEN
    GVL_Runtime_Bus.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

L_TX_Index := UDINT_TO_UINT(GVL_Runtime_Bus.G_Last_Sequence_Id + 1);

IF L_TX_Index > 128 THEN
    L_TX_Index := 1;
END_IF;

L_Frame.Frame_Valid := TRUE;

L_Frame.Frame_Time_MS := VI_System_Time_MS;
L_Frame.Frame_Id := GVL_Runtime_Bus.G_Last_Frame_Id + 1;

L_Frame.Source_Controller_Id :=
    GVL_Distributed_Runtime.G_Local_Node_State.Controller_Id;

L_Frame.Source_Runtime_Node_Id :=
    GVL_Distributed_Runtime.G_Local_Node_State.Runtime_Node_Id;

L_Frame.Frame_Sequence_Id :=
    GVL_Runtime_Bus.G_Last_Sequence_Id + 1;

L_Frame.Frame_Ack_Required := TRUE;

L_Frame.Authority_State_Frame := TRUE;
L_Frame.Recovery_State_Frame := TRUE;
L_Frame.Quarantine_State_Frame := TRUE;
L_Frame.Topology_State_Frame := TRUE;
L_Frame.Binding_State_Frame := TRUE;
L_Frame.Predictive_State_Frame := TRUE;

IF GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK
   AND NOT GVL_Distributed_Runtime.G_Split_Brain_Suspected
   AND L_Finalized_Runtime_Continuity THEN

    L_Frame.Replication_Consistent := TRUE;

    L_Frame.Status_Code := 0;
    L_Frame.Status_Text :=
        'Deterministic replication frame accepted';

ELSE

    L_Frame.Replication_Rejected := TRUE;

    L_Frame.Status_Code := 2;
    L_Frame.Status_Text :=
        'Deterministic replication frame rejected';

END_IF;

GVL_Runtime_Bus.G_TX_Frames[L_TX_Index] := L_Frame;

GVL_Runtime_Bus.G_Last_Frame_Id :=
    L_Frame.Frame_Id;

GVL_Runtime_Bus.G_Last_Sequence_Id :=
    L_Frame.Frame_Sequence_Id;

GVL_Runtime_Bus.G_TX_Healthy :=
    L_Frame.Replication_Consistent;

GVL_Runtime_Bus.G_RX_Healthy := TRUE;

GVL_Runtime_Bus.G_Any_Replication_Rejected :=
    L_Frame.Replication_Rejected;

GVL_Runtime_Bus.G_Runtime_Valid := TRUE;
GVL_Runtime_Bus.G_Last_Update_MS := VI_System_Time_MS;

IF L_Frame.Replication_Rejected THEN
    GVL_Runtime_Bus.G_Status_Code := 2;
    GVL_Runtime_Bus.G_Status_Text :=
        'Runtime bus replication rejected';
ELSE
    GVL_Runtime_Bus.G_Status_Code := 0;
    GVL_Runtime_Bus.G_Status_Text :=
        'Runtime bus replication healthy';
END_IF;

VO_System_OK := FALSE;
VO_System_Warning := FALSE;
VO_System_Critical := FALSE;
VO_Status_Msg := '';

// ------------------------------------------------------
// Stateful deterministic mode governance.
// ------------------------------------------------------
// SAFE_STOP entry is immediate.
// SAFE_STOP exit is convergence-lease gated.
//
// Prevents one-cycle false recovery and transient
// healthy visibility from restoring system operation.
// ------------------------------------------------------

L_Requested_Mode := E_System_Operating_Mode.MODE_NORMAL;

CASE VI_System_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_System_OK := TRUE;
        VO_Status_Msg := 'Система в норме';
        L_Requested_Mode := E_System_Operating_Mode.MODE_NORMAL;

    E_System_Severity.SEV_WARNING:
        VO_System_Warning := TRUE;
        L_Requested_Mode := E_System_Operating_Mode.MODE_DEGRADED;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_WATER_LEAK:
                VO_Status_Msg := 'Предупреждение: протечка воды';

            E_System_Root_Cause.ROOT_CO_WARNING:
                VO_Status_Msg := 'Предупреждение: повышенный CO';

            ELSE
                VO_Status_Msg := 'Предупреждение системы';
        END_CASE;

    E_System_Severity.SEV_DEGRADED:
        VO_System_Warning := TRUE;
        L_Requested_Mode := E_System_Operating_Mode.MODE_DEGRADED;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_SENSOR_FAULT:
                VO_Status_Msg := 'Деградация: ошибка датчика';

            E_System_Root_Cause.ROOT_IO_OFFLINE:
                VO_Status_Msg := 'Деградация: модуль IO недоступен';

            E_System_Root_Cause.ROOT_COMM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка связи';

            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'Деградация: watchdog fault';

            E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка подсистемы';

            ELSE
                VO_Status_Msg := 'Деградация системы';
        END_CASE;

    E_System_Severity.SEV_CRITICAL:
        VO_System_Critical := TRUE;

        IF (VI_Root_Cause = E_System_Root_Cause.ROOT_GAS_LEAK OR
            VI_Root_Cause = E_System_Root_Cause.ROOT_CO_CRITICAL) AND
            VI_Freeze_Risk THEN
            L_Requested_Mode := E_System_Operating_Mode.MODE_FREEZE_PROTECTION;
        ELSE
            L_Requested_Mode := E_System_Operating_Mode.MODE_SAFE_STOP;
        END_IF;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_FIRE:
                VO_Status_Msg := 'АВАРИЯ: ПОЖАР';

            E_System_Root_Cause.ROOT_GAS_LEAK:
                VO_Status_Msg := 'АВАРИЯ: УТЕЧКА ГАЗА';

            E_System_Root_Cause.ROOT_CO_CRITICAL:
                VO_Status_Msg := 'АВАРИЯ: КРИТИЧЕСКИЙ CO';

            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'АВАРИЯ: WATCHDOG';

            ELSE
                VO_Status_Msg := 'АВАРИЯ СИСТЕМЫ';
        END_CASE;
END_CASE;

// ------------------------------------------------------
// Deterministic SAFE_STOP exit hardening.
// ------------------------------------------------------
// SAFE_STOP/FREEZE_PROTECTION exit requires sustained
// convergence evidence and convergence lease acquisition.
// ------------------------------------------------------

IF (VO_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP)
OR (VO_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION)
THEN
    IF (L_Requested_Mode <> E_System_Operating_Mode.MODE_SAFE_STOP)
    AND (L_Requested_Mode <> E_System_Operating_Mode.MODE_FREEZE_PROTECTION)
    THEN
        IF NOT GVL_CONVERGENCE.Convergence_Lease_OK THEN
            // Hold previous safe mode until deterministic
            // convergence/recovery proof exists.
            L_Requested_Mode := VO_System_Mode;

            IF VO_Status_Msg = '' THEN
                VO_Status_Msg := 'Ожидание подтверждения восстановления';
            ELSE
                VO_Status_Msg := CONCAT(VO_Status_Msg, ' | convergence pending');
            END_IF;
        END_IF;
    END_IF;
END_IF;

VO_System_Mode := L_Requested_Mode;

// >>> BULK_SYNC_ANCHOR: FB_State_Manager <<<

IF NOT VI_Enable THEN
    GVL_Water_Runtime_Projection.G_Projection_Valid := FALSE;
    RETURN;
END_IF;

L_Global_Leak := FALSE;
L_Global_Warning := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Runtime_State.Projection_Valid := FALSE;
    L_Runtime_State.Projection_Valid := TRUE;
    L_Runtime_State.Projection_System_Time_MS := VI_System_Time_MS;
    L_Runtime_State.Physical_Sensor_Index := TO_UINT(L_i);
    L_Runtime_State.Physical_Input_Valid := TRUE;
    L_Runtime_State.Leak_Warning_Active := GVL_STATE.G_Flood_Warning[L_i];
    L_Runtime_State.Leak_Confirmed := GVL_STATE.G_Flood_Alarm[L_i];
    L_Runtime_State.Active_Safety_Leak_Latched := GVL_INTENT_SAFETY.I_Water_Main_Close_Required;
    L_Runtime_State.Active_Global_Close_Path := GVL_COMMAND_SHADOW.G_Close_Valve_35 OR GVL_COMMAND_SHADOW.G_Close_Valve_36;

    L_Runtime_State.Mapping_Valid := (GVL_CONFIG.G_Flood_Global_Config.sensor_to_valve_map[L_i] <> 0);
    L_Runtime_State.Mapping_Missing := NOT L_Runtime_State.Mapping_Valid;

    IF L_Runtime_State.Mapping_Valid THEN
        L_Runtime_State.Valve_Group_Id := TO_UINT(GVL_CONFIG.G_Flood_Global_Config.sensor_to_valve_map[L_i]);
        L_Runtime_State.Selective_Isolation_Possible := TRUE;
        L_Runtime_State.Fallback_Global_Isolation_Required := FALSE;
    ELSE
        L_Runtime_State.Selective_Isolation_Possible := FALSE;
        L_Runtime_State.Fallback_Global_Isolation_Required := TRUE;
    END_IF;

    L_Runtime_State.Logical_Sensor_Valid := TRUE;
    L_Runtime_State.Hydraulic_Zone_Id := TO_UINT(L_i);
    L_Runtime_State.Hydraulic_Segment_Id := TO_UINT(L_i);
    L_Runtime_State.Isolation_Group_Id := L_Runtime_State.Valve_Group_Id;

    IF L_Runtime_State.Leak_Confirmed THEN
        L_Runtime_State.Leak_Confidence := 1.0;
    ELSIF L_Runtime_State.Leak_Warning_Active THEN
        L_Runtime_State.Leak_Confidence := 0.5;
    ELSE
        L_Runtime_State.Leak_Confidence := 0.0;
    END_IF;

    L_Runtime_State.Sensor_Quality_Valid := TRUE;

    IF L_Runtime_State.Leak_Confirmed THEN
        IF L_Runtime_State.Mapping_Valid THEN
            L_Runtime_State.Reason_Code := 1;
            L_Runtime_State.Reason_Text := 'Leak confirmed';
        ELSE
            L_Runtime_State.Reason_Code := 2;
            L_Runtime_State.Reason_Text := 'Leak confirmed fallback';
        END_IF;
    ELSIF L_Runtime_State.Leak_Warning_Active THEN
        L_Runtime_State.Reason_Code := 3;
        L_Runtime_State.Reason_Text := 'Leak warning active';
    ELSE
        L_Runtime_State.Reason_Code := 0;
        L_Runtime_State.Reason_Text := 'No leak activity';
    END_IF;

    L_Runtime_State.Warning_Started_Event := GVL_STATE.G_Flood_Warning_Rise[L_i];
    L_Runtime_State.Leak_Confirmed_Event := GVL_STATE.G_Flood_Alarm_Rise[L_i];
    L_Runtime_State.Leak_Cleared_Event := GVL_STATE.G_Flood_Alarm_Fall[L_i];
    L_Runtime_State.Isolation_Requested_Event := L_Runtime_State.Leak_Confirmed;
    L_Runtime_State.Mapping_Invalid_Event := L_Runtime_State.Mapping_Missing;
    L_Runtime_State.Supervisory_Observation_Only := TRUE;

    GVL_Water_Runtime_Projection.G_Leak_Runtime_State[L_i] := L_Runtime_State;

    L_Global_Leak := L_Global_Leak OR L_Runtime_State.Leak_Confirmed;
    L_Global_Warning := L_Global_Warning OR L_Runtime_State.Leak_Warning_Active;
END_FOR;

GVL_Water_Runtime_Projection.G_Global_Leak_Active := L_Global_Leak;
GVL_Water_Runtime_Projection.G_Global_Warning_Active := L_Global_Warning;
GVL_Water_Runtime_Projection.G_Projection_Valid := TRUE;
GVL_Water_Runtime_Projection.G_Last_Projection_MS := VI_System_Time_MS;
GVL_Water_Runtime_Projection.G_Runtime_Projection_Status_Code := 0;
GVL_Water_Runtime_Projection.G_Runtime_Projection_Status_Text := 'Water runtime semantic projection active';

L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);

GVL_STATE.G_Heating_IO_Fault := FALSE;
GVL_STATE.G_Heating_Sensor_Fault := FALSE;
GVL_STATE.G_Heating_Subsystem_Degraded := FALSE;
L_Sensor_Error := FALSE;
L_Subsys_Degraded := FALSE;
L_Allocation_Degraded := FALSE;

L_IO_Failsafe_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_IO_Failsafe_Active := TRUE;
        GVL_STATE.G_Heating_IO_Fault := TRUE;
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
        EXIT;
    END_IF;
END_FOR;

fbSafetyGate(
    VI_System_Mode := VI_System_Mode,
    VI_Emergency_Stop := VI_Emergency_Stop,
    VI_Gas_Safety_Stop := VI_Gas_Safety_Stop,
    VI_IO_Failsafe_Active := L_IO_Failsafe_Active,
    VI_Outdoor_Temp := VI_Outdoor_Temp,
    VI_Freeze_Threshold := VI_Config.Freeze_Threshold,
    VI_Floor_Temps := VI_Floor_Temps,
    VO_Freeze_Mode_Active => L_Freeze_Active,
    VO_Freeze_Target_Supply => L_Freeze_Target_Supply
);

fbSafeState(
    VI_Block_Normal_Heating := fbSafetyGate.VO_Block_Normal_Heating,
    VI_IO_Failsafe_Active := fbSafetyGate.VO_IO_Failsafe_Active,
    VI_Gas_Safety_Active := fbSafetyGate.VO_Gas_Safety_Active,
    VI_Freeze_Active := L_Freeze_Active,
    VI_Freeze_Target_Supply := L_Freeze_Target_Supply,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online
);

IF fbSafeState.VO_Applied THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Zone_Valves[L_i] := fbSafeState.VO_Zone_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Manifold_Pumps[L_i] := fbSafeState.VO_Manifold_Pumps[L_i];
        VO_Manifold_Valves[L_i] := fbSafeState.VO_Manifold_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_i] := fbSafeState.VO_Boiler_OT_Enable[L_i];
        VO_Boiler_OT_Setpoint[L_i] := fbSafeState.VO_Boiler_OT_Setpoint[L_i];
        VO_Boiler_Status[L_i] := fbSafeState.VO_Boiler_Status[L_i];
    END_FOR;

    VO_Backup_Circulation_Pump := fbSafeState.VO_Backup_Circulation_Pump;
    VO_Electric_Heater_Enable := fbSafeState.VO_Electric_Heater_Enable;
    VO_Freeze_Risk_Status := fbSafeState.VO_Freeze_Risk_Status;
    RETURN;
END_IF;

VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

IF L_Freeze_Active THEN
    L_Target_Supply_Temp := L_Freeze_Target_Supply;
ELSE
    L_Target_Supply_Temp := VI_Config.Target_Floor_Temp;
END_IF;

fbAdaptiveTarget(
    VI_Base_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Global_Target_Temperature := GVL_STATE.G_Target_Temperature,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VO_Target_Supply_Temp => L_Target_Supply_Temp
);

L_Policy_Target_Adjustment := GVL_HEATING_POLICY.G_Policy_Target_Adjustment;

IF L_Policy_Target_Adjustment > REAL#5.0 THEN
    L_Policy_Target_Adjustment := REAL#5.0;
ELSIF L_Policy_Target_Adjustment < REAL#-3.0 THEN
    L_Policy_Target_Adjustment := REAL#-3.0;
END_IF;

L_Target_Supply_Temp :=
    LIMIT(
        GVL_CONSTANTS.C_BOILER_SETPOINT_MIN,
        L_Target_Supply_Temp + L_Policy_Target_Adjustment,
        GVL_CONSTANTS.C_BOILER_SETPOINT_MAX
    );

fbCircuitControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Current_Hour := VI_Current_Hour,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Config := VI_Config,
    VI_Tariff := VI_Tariff,
    VI_Scenario_Adjust := REAL#0.0,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VI_Rule_Actions := VI_Rule_Actions,
    VO_Zone_Valves => VO_Zone_Valves,
    VO_Heating_Sensor_Fault => L_Sensor_Error
);

GVL_STATE.G_Heating_Sensor_Fault := L_Sensor_Error;

fbDemandMap(
    VI_Zone_Valves := VO_Zone_Valves,
    VI_Zone_Configs := VI_Zone_Configs,
    VO_Manifold_Demand_Map => L_Manifold_Demand_Map
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Manifold_Available[L_i] := VI_Manifold_Pressures[L_i] >= GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE;
    L_Manifold_In_Service[L_i] := GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];
    L_Manifold_Subsystem_Degraded[L_i] :=
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i]
        OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i];

    L_Manifold_Base_Priority[L_i] := GVL_CONFIG.G_Manifold_Priority[L_i];
    L_Manifold_Thermal_Weight[L_i] := GVL_CONFIG.G_Manifold_Thermal_Weight[L_i];
END_FOR;

fbPolicyPriorityBridge(
    VI_Enable := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Zone_Valves := VO_Zone_Valves,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Manifold_Base_Priority := L_Manifold_Base_Priority,
    VI_Zone_Priority_Bias := GVL_HEATING_POLICY.G_Zone_Priority_Bias,
    VI_Policy_Priority_Multiplier := GVL_HEATING_POLICY.G_Policy_Priority_Multiplier,
    VO_Manifold_Effective_Priority => L_Manifold_Effective_Priority
);

fbAllocationFilter(
    VI_Enable := TRUE,
    VI_Enable_Policy_Allocation := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_Manifold_Demand_Map := L_Manifold_Demand_Map,
    VI_Manifold_Available := L_Manifold_Available,
    VI_Manifold_In_Service := L_Manifold_In_Service,
    VI_Manifold_Subsystem_Degraded := L_Manifold_Subsystem_Degraded,
    VI_Manifold_Base_Priority := L_Manifold_Effective_Priority,
    VI_Manifold_Thermal_Weight := L_Manifold_Thermal_Weight,
    VI_Max_Thermal_Budget := GVL_CONFIG.G_Max_Thermal_Budget,
    VO_Manifold_Demand_Filtered => L_Manifold_Demand_Filtered,
    VO_Allocation_Degraded => L_Allocation_Degraded
);

fbRuntimeObservability(
    VI_Policy_Active := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Freeze_Bypass_Active := L_Freeze_Active,
    VI_DHW_Bypass_Active := VI_DHW_Heating_Demand,
    VI_Budget_Max := GVL_CONFIG.G_Max_Thermal_Budget,
    VI_Budget_Used := fbAllocationFilter.VO_Thermal_Budget_Used,
    VI_Requested := L_Manifold_Demand_Map,
    VI_Allowed := fbAllocationFilter.VO_Manifold_Allowed,
    VI_Filtered := L_Manifold_Demand_Filtered,
    VI_Block_Reason := fbAllocationFilter.VO_Manifold_Block_Reason,
    VI_Effective_Priority := fbAllocationFilter.VO_Manifold_Priority_Effective,
    VI_Priority_Bridge_Active := fbPolicyPriorityBridge.VO_Bridge_Active,
    VI_Priority_Bias_Applied := fbPolicyPriorityBridge.VO_Manifold_Priority_Bias_Applied,
    VI_Priority_Effective := L_Manifold_Effective_Priority
);

IF L_Allocation_Degraded THEN
    GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
END_IF;

fbManifoldControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Any_Zone_Active := L_Manifold_Demand_Filtered,
    VI_Manifold_Pressures := VI_Manifold_Pressures,
    VI_Manifold_Currents := VI_Manifold_Currents,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Manifold_Temps_Return := VI_Manifold_Temps_Return,
    VO_Manifold_Pumps => VO_Manifold_Pumps,
    VO_Manifold_Valves => VO_Manifold_Valves,
    VO_Status => VO_Status
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Pressure_OK := VI_Manifold_Pressures[L_i] >= GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE;

    IF VO_Manifold_Pumps[L_i] AND NOT L_Pressure_OK THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
    END_IF;

    IF (L_Prev_Pressure[L_i] > REAL#0.0) AND ((L_Prev_Pressure[L_i] - VI_Manifold_Pressures[L_i]) > REAL#0.2) THEN
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] := TRUE;
    ELSE
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] := FALSE;
    END_IF;

    IF (L_Prev_Current[L_i] > REAL#0.0) AND (VI_Manifold_Currents[L_i] > (L_Prev_Current[L_i] * REAL#1.2)) THEN
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] := TRUE;
    ELSE
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] := FALSE;
    END_IF;

    IF GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] THEN
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
    END_IF;

    L_Prev_Pressure[L_i] := VI_Manifold_Pressures[L_i];
    L_Prev_Current[L_i] := VI_Manifold_Currents[L_i];
END_FOR;

// ======================================================
// HEATING CONFIDENCE PUBLICATION
// ======================================================
// The former local error-score decay path has been replaced by the
// normalized input confidence surface. Runtime faults may still reduce
// confidence and reason publication, but the base confidence now comes
// from canonical input semantics.
L_Confidence := GVL_INPUT.IN_Min_Zone_Confidence;

IF L_Confidence < REAL#0.0 THEN
    L_Confidence := REAL#0.0;
ELSIF L_Confidence > REAL#1.0 THEN
    L_Confidence := REAL#1.0;
END_IF;

GVL_STATE.G_Heating_Confidence_Reason_Code := 0;
GVL_STATE.G_Heating_Confidence_Reason_Text := 'OK';

IF GVL_INPUT.IN_Input_Degraded OR GVL_INPUT.IN_Anomaly_Detected THEN
    GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
    GVL_STATE.G_Heating_Confidence_Reason_Code := 5;

    IF GVL_INPUT.IN_Anomaly_Reason <> '' THEN
        GVL_STATE.G_Heating_Confidence_Reason_Text := GVL_INPUT.IN_Anomaly_Reason;
    ELSE
        GVL_STATE.G_Heating_Confidence_Reason_Text := 'Input quality degraded';
    END_IF;
END_IF;

IF GVL_STATE.G_Heating_IO_Fault THEN
    IF L_Confidence > REAL#0.8 THEN
        L_Confidence := REAL#0.8;
    END_IF;
    GVL_STATE.G_Heating_Confidence_Reason_Code := 2;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'IO fault detected';
ELSIF GVL_STATE.G_Heating_Sensor_Fault THEN
    IF L_Confidence > REAL#0.6 THEN
        L_Confidence := REAL#0.6;
    END_IF;
    GVL_STATE.G_Heating_Confidence_Reason_Code := 1;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'Sensor fault detected';
ELSE
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Pressures[L_i] < GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE THEN
            IF L_Confidence > REAL#0.7 THEN
                L_Confidence := REAL#0.7;
            END_IF;
            GVL_STATE.G_Heating_Confidence_Reason_Code := 3;
            GVL_STATE.G_Heating_Confidence_Reason_Text := 'Low manifold pressure';
            EXIT;
        END_IF;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] THEN
            IF L_Confidence > REAL#0.75 THEN
                L_Confidence := REAL#0.75;
            END_IF;
            GVL_STATE.G_Heating_Confidence_Reason_Code := 4;
            GVL_STATE.G_Heating_Confidence_Reason_Text := 'Predictive pump degradation';
            EXIT;
        END_IF;
    END_FOR;
END_IF;

GVL_STATE.G_Heating_Confidence := L_Confidence;
GVL_STATE.G_Heating_Error_Score := REAL#1.0 - L_Confidence;

IF GVL_STATE.G_Heating_Confidence < REAL#0.5 THEN
    L_Target_Supply_Temp := L_Target_Supply_Temp - REAL#3.0;
END_IF;

CASE GVL_STATE.G_Heating_Confidence_Reason_Code OF
    1:
        L_Target_Supply_Temp := LIMIT(GVL_CONSTANTS.C_BOILER_SETPOINT_MIN, REAL#40.0, GVL_CONSTANTS.C_BOILER_SETPOINT_MAX);
    2:
        VO_Backup_Circulation_Pump := TRUE;
    3:
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            VO_Manifold_Pumps[L_i] := FALSE;
        END_FOR;
    4:
        L_Target_Supply_Temp := LIMIT(GVL_CONSTANTS.C_BOILER_SETPOINT_MIN, L_Target_Supply_Temp - REAL#5.0, GVL_CONSTANTS.C_BOILER_SETPOINT_MAX);
    5:
        // Input-quality degradation is published for explainability first.
        // Runtime suppression remains governed by existing sensor validation
        // and safety/pressure ownership paths.
ELSE
    // no auto-recovery action
END_CASE;

fbValveTestManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Valve_Currents := VI_Manifold_Currents,
    VI_Valve_End_Switches := VI_Manifold_End_Switches,
    VI_Config := VI_Valve_Test_Config
);

IF fbValveTestManager.VO_Test_Active THEN
    L_i := fbValveTestManager.VO_Current_Valve;
    IF L_i >= 1 AND L_i <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
        IF fbValveTestManager.VO_Valve_Cmd[L_i] THEN
            VO_Manifold_Valves[L_i] := REAL#100.0;
        ELSE
            VO_Manifold_Valves[L_i] := REAL#0.0;
        END_IF;
        VO_Manifold_Pumps[L_i] := FALSE;
    END_IF;
END_IF;

fbBoilerControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Policy_Degraded := L_Policy_Degraded,
    VI_Manifold_Pumps := VO_Manifold_Pumps,
    VI_Manifold_Valves := VO_Manifold_Valves,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_OT_Enable => VO_Boiler_OT_Enable,
    VO_Boiler_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_Boiler_Status => VO_Boiler_Status,
    VO_Any_Subsystem_Degraded => L_Subsys_Degraded
);

GVL_STATE.G_Heating_Subsystem_Degraded := GVL_STATE.G_Heating_Subsystem_Degraded OR L_Subsys_Degraded;

// >>> BULK_SYNC_ANCHOR: FB_Heating_System_Manager <<<

VO_Average := 0.0;
VO_Max := 0.0;
VO_Min := 0.0;
VO_Trend_Up := FALSE;
VO_Trend_Down := FALSE;

IF VI_Count > 0 AND VI_Count <= GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    VO_Max := VI_Data[1];
    VO_Min := VI_Data[1];
    L_Sum := 0.0;

    FOR L_i := 1 TO VI_Count DO
        IF VI_Data[L_i] > VO_Max THEN VO_Max := VI_Data[L_i]; END_IF;
        IF VI_Data[L_i] < VO_Min THEN VO_Min := VI_Data[L_i]; END_IF;
        L_Sum := L_Sum + VI_Data[L_i];
    END_FOR;

    VO_Average := L_Sum / INT_TO_REAL(VI_Count);

    IF VI_Count >= 2 THEN
        VO_Trend_Up := (VI_Data[VI_Count] > VI_Data[1]);
        VO_Trend_Down := (VI_Data[VI_Count] < VI_Data[1]);
    END_IF;
END_IF;

IF NOT VI_Enable THEN
    GVL_Water_Isolation_Runtime.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Isolation := FALSE;
L_Any_Selective := FALSE;
L_Global_Fallback := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Leak_State := GVL_Water_Runtime_Projection.G_Leak_Runtime_State[L_i];
    L_Traversal := GVL_Water_Orchestration.G_Traversal_State[L_i];

    L_Isolation_State := L_Empty_Isolation_State;
    L_Isolation_State.Projection_Valid := TRUE;
    L_Isolation_State.Projection_System_Time_MS := VI_System_Time_MS;

    L_Isolation_State.Hydraulic_Zone_Id := L_Leak_State.Hydraulic_Zone_Id;
    L_Isolation_State.Isolation_Group_Id := L_Leak_State.Isolation_Group_Id;
    L_Isolation_State.Valve_Group_Id := L_Traversal.Target_Valve_Group_Id;

    L_Isolation_State.Active_Global_Close_Path :=
        L_Leak_State.Active_Global_Close_Path;

    L_Isolation_State.Active_Safety_Latch :=
        L_Leak_State.Active_Safety_Leak_Latched;

    L_Isolation_State.Mapping_Valid :=
        L_Traversal.Traversal_Valid;

    L_Isolation_State.Fallback_To_Global_Required :=
        L_Traversal.Global_Fallback_Required;

    IF L_Leak_State.Leak_Confirmed THEN

        L_Isolation_State.Isolation_Requested := TRUE;

        IF L_Traversal.Selective_Path_Allowed
           AND NOT L_Traversal.Global_Fallback_Required THEN

            L_Isolation_State.Selective_Isolation_Requested := TRUE;
            L_Isolation_State.Reason_Code := 1;
            L_Isolation_State.Reason_Text :=
                'Selective orchestration path available';

        ELSE

            L_Isolation_State.Global_Isolation_Requested := TRUE;
            L_Isolation_State.Reason_Code := 2;
            L_Isolation_State.Reason_Text :=
                'Global fallback required';

        END_IF;

    END_IF;

    GVL_Water_Isolation_Runtime.G_Isolation_Runtime_State[L_i] :=
        L_Isolation_State;

    L_Any_Isolation :=
        L_Any_Isolation
        OR L_Isolation_State.Isolation_Requested;

    L_Any_Selective :=
        L_Any_Selective
        OR L_Isolation_State.Selective_Isolation_Requested;

    L_Global_Fallback :=
        L_Global_Fallback
        OR L_Isolation_State.Global_Isolation_Requested;

END_FOR;

GVL_Water_Isolation_Runtime.G_Any_Isolation_Requested :=
    L_Any_Isolation;

GVL_Water_Isolation_Runtime.G_Any_Selective_Isolation :=
    L_Any_Selective;

GVL_Water_Isolation_Runtime.G_Global_Fallback_Required :=
    L_Global_Fallback;

GVL_Water_Isolation_Runtime.G_Runtime_Valid := TRUE;
GVL_Water_Isolation_Runtime.G_Last_Update_MS := VI_System_Time_MS;

IF L_Global_Fallback THEN
    GVL_Water_Isolation_Runtime.G_Status_Code := 2;
    GVL_Water_Isolation_Runtime.G_Status_Text :=
        'Global isolation fallback required';
ELSIF L_Any_Selective THEN
    GVL_Water_Isolation_Runtime.G_Status_Code := 1;
    GVL_Water_Isolation_Runtime.G_Status_Text :=
        'Selective orchestration active';
ELSE
    GVL_Water_Isolation_Runtime.G_Status_Code := 0;
    GVL_Water_Isolation_Runtime.G_Status_Text :=
        'Isolation runtime active';
END_IF;

// ==============================================================================
// Heating runtime event manager
// Read-only orchestration telemetry/event layer.
// DOES NOT own runtime.
// DOES NOT own heating logic.
// DOES NOT own diagnostics.
// DOES NOT own OpenTherm transport.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_Event_Stored := FALSE;
VO_Buffer_Overflow := FALSE;
VO_Manager_Ready := FALSE;
VO_Manager_Status_Code := 0;
VO_Manager_Status_Text := 'Heating runtime event manager disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// BUFFER VALIDATION
// ======================================================
IF VIO_Buffer.Write_Index > 32 THEN
    VIO_Buffer.Write_Index := 1;
END_IF;

IF VIO_Buffer.Read_Index > 32 THEN
    VIO_Buffer.Read_Index := 1;
END_IF;

// ======================================================
// WRITE INDEX
// ======================================================
L_Write_Index := VIO_Buffer.Write_Index + 1;

IF L_Write_Index > 32 THEN
    L_Write_Index := 1;
END_IF;

// ======================================================
// STORE EVENT
// ======================================================
VIO_Buffer.Events[L_Write_Index] := VI_Event;
VIO_Buffer.Write_Index := L_Write_Index;

IF VIO_Buffer.Event_Count < 32 THEN
    VIO_Buffer.Event_Count := VIO_Buffer.Event_Count + 1;
ELSE
    VIO_Buffer.Overflow := TRUE;
    VO_Buffer_Overflow := TRUE;
END_IF;

// ======================================================
// BUFFER INTEGRITY
// ======================================================
VIO_Buffer.Ordering_Integrity_Valid :=
    VI_Event.Ordering_Valid;

VIO_Buffer.Isolation_Integrity_Valid :=
    VI_Event.Isolation_Valid;

VIO_Buffer.Diagnostics_Visibility_Valid :=
    VI_Event.Diagnostics_Visible;

VIO_Buffer.Explainability_Visibility_Valid :=
    VI_Event.Explainability_Visible;

VIO_Buffer.OpenTherm_Ownership_Valid :=
    VI_Event.OpenTherm_Ownership_Valid;

VIO_Buffer.Cascade_Ownership_Valid :=
    VI_Event.Cascade_Ownership_Valid;

VIO_Buffer.Safety_Ownership_Valid :=
    VI_Event.Safety_Integrity_Valid;

VIO_Buffer.Lifecycle_Integrity_Valid :=
    NOT VI_Event.Event_Failed;

// ======================================================
// BUFFER STATUS
// ======================================================
IF VO_Buffer_Overflow THEN
    VIO_Buffer.Status_Code := 100;
    VIO_Buffer.Status_Text := 'Heating runtime event buffer overflow';
ELSE
    VIO_Buffer.Status_Code := 1;
    VIO_Buffer.Status_Text := 'Heating runtime event stored';
END_IF;

// ======================================================
// OUTPUT STATUS
// ======================================================
VO_Event_Stored := TRUE;
VO_Manager_Ready := TRUE;
VO_Manager_Status_Code := VIO_Buffer.Status_Code;
VO_Manager_Status_Text := VIO_Buffer.Status_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Event_Manager <<<

// Normalize count to analyzer bounds
L_Count := UDINT_TO_INT(VI_Data.record_count);
IF L_Count < 0 THEN
    L_Count := 0;
END_IF;
IF L_Count > GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    L_Count := GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS;
END_IF;

// Copy source values into analyzer-compatible buffer
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS DO
    L_Data_Copy[L_i] := 0.0;
END_FOR;

IF L_Count > 0 THEN
    FOR L_i := 1 TO L_Count DO
        L_Data_Copy[L_i] := VI_Data.values[L_i];
    END_FOR;
END_IF;

fbAnalyzer(
    VI_Count := L_Count,
    VI_Data := L_Data_Copy,
    VO_Average => VO_Average,
    VO_Max => VO_Max,
    VO_Min => VO_Min,
    VO_Trend_Up => VO_Trend_Up,
    VO_Trend_Down => VO_Trend_Down
);

IF NOT VI_Enable THEN
    GVL_Water_Orchestration.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Conflict := FALSE;
L_Any_Escalation := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Path :=
        GVL_Water_Hydraulic_Graph.G_Isolation_Path[L_i];

    // Traversal runtime.
    L_Traversal := L_Empty_Traversal;
    L_Traversal.Runtime_Valid := TRUE;

    L_Traversal.Runtime_System_Time_MS :=
        VI_System_Time_MS;

    L_Traversal.Sensor_Id := TO_UINT(L_i);

    L_Traversal.Start_Segment_Id :=
        L_Path.Active_Isolation_Group_Id;

    L_Traversal.Target_Valve_Group_Id :=
        L_Path.Active_Valve_Group_Id;

    L_Traversal.Shared_Trunk_Traversal :=
        L_Path.Shared_Trunk_Impact;

    L_Traversal.Upstream_Dependency_Detected :=
        L_Path.Shared_Trunk_Impact;

    L_Traversal.Downstream_Impact_Detected :=
        L_Path.Cross_Zone_Impact;

    L_Traversal.Traversal_Valid :=
        L_Path.Isolation_Path_Valid;

    L_Traversal.Traversal_Conflict :=
        L_Path.Conflict_Detected;

    L_Traversal.Traversal_Ambiguous :=
        L_Path.Isolation_Path_Ambiguous;

    IF L_Path.Multi_Valve_Path THEN
        L_Traversal.Dependency_Depth := 2;
    ELSE
        L_Traversal.Dependency_Depth := 1;
    END_IF;

    L_Traversal.Selective_Path_Allowed :=
        L_Path.Selective_Isolation_Allowed;

    L_Traversal.Global_Fallback_Required :=
        L_Path.Global_Fallback_Required;

    // Orchestration runtime.
    L_Orchestration := L_Empty_Orchestration;
    L_Orchestration.Runtime_Valid := TRUE;

    L_Orchestration.Runtime_System_Time_MS :=
        VI_System_Time_MS;

    L_Orchestration.Isolation_Sequence_Active :=
        L_Traversal.Traversal_Valid;

    L_Orchestration.Shared_Trunk_Sequencing :=
        L_Traversal.Shared_Trunk_Traversal;

    L_Orchestration.Staged_Close_Required :=
        L_Path.Multi_Valve_Path;

    L_Orchestration.Recovery_Sequence_Active :=
        GVL_INTENT_SAFETY.I_Water_Selective_Recovery_Allowed;

    L_Orchestration.Staged_Open_Required :=
        L_Orchestration.Recovery_Sequence_Active
        AND L_Path.Multi_Valve_Path;

    L_Orchestration.Observation_Window_Active :=
        L_Orchestration.Recovery_Sequence_Active;

    // Conservative sequencing governance.
    IF L_Traversal.Traversal_Conflict
       OR L_Traversal.Traversal_Ambiguous THEN

        L_Orchestration.Rollback_Required := TRUE;
        L_Orchestration.Escalation_Required := TRUE;
        L_Orchestration.Sequencing_Valid := FALSE;

        L_Orchestration.Status_Code := 2;
        L_Orchestration.Status_Text :=
            'Orchestration conflict escalation active';

    ELSE

        L_Orchestration.Sequencing_Valid := TRUE;

        IF L_Orchestration.Shared_Trunk_Sequencing THEN
            L_Orchestration.Status_Code := 1;
            L_Orchestration.Status_Text :=
                'Shared trunk orchestration active';
        ELSE
            L_Orchestration.Status_Code := 0;
            L_Orchestration.Status_Text :=
                'Deterministic orchestration active';
        END_IF;

    END_IF;

    GVL_Water_Orchestration.G_Traversal_State[L_i] :=
        L_Traversal;

    GVL_Water_Orchestration.G_Orchestration_State[L_i] :=
        L_Orchestration;

    L_Any_Conflict :=
        L_Any_Conflict
        OR L_Traversal.Traversal_Conflict;

    L_Any_Escalation :=
        L_Any_Escalation
        OR L_Orchestration.Escalation_Required;

END_FOR;

GVL_Water_Orchestration.G_Topology_Version := 1;
GVL_Water_Orchestration.G_Config_Runtime_Ready := TRUE;

GVL_Water_Orchestration.G_Any_Traversal_Conflict :=
    L_Any_Conflict;

GVL_Water_Orchestration.G_Any_Escalation_Required :=
    L_Any_Escalation;

GVL_Water_Orchestration.G_Runtime_Valid := TRUE;
GVL_Water_Orchestration.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Escalation THEN
    GVL_Water_Orchestration.G_Status_Code := 2;
    GVL_Water_Orchestration.G_Status_Text :=
        'Water orchestration escalation active';
ELSIF L_Any_Conflict THEN
    GVL_Water_Orchestration.G_Status_Code := 1;
    GVL_Water_Orchestration.G_Status_Text :=
        'Water orchestration conflict detected';
ELSE
    GVL_Water_Orchestration.G_Status_Code := 0;
    GVL_Water_Orchestration.G_Status_Text :=
        'Water orchestration runtime healthy';
END_IF;

// Reset retained outputs on every call before any early return.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    VO_Supply_Fans[L_i] := 0;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    VO_Exhaust_Fans[L_i] := 0;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Heater_Power[L_i] := 0.0;
END_FOR;

VO_Status_Msg := '';
VO_Ventilation_IO_Fault := FALSE;
VO_Ventilation_Subsystem_Degraded := FALSE;

// ========================================
// Ventilation policy layer
// ========================================
L_Policy_Normal := (VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL);
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

IF NOT VI_IsActivePLC THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: РЕЗЕРВНЫЙ ПЛК';
    RETURN;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        VO_Ventilation_IO_Fault := TRUE;
        VO_Status_Msg := 'ОШИБКА: Потеря связи с модулями ввода-вывода';
        RETURN;
    END_IF;
END_FOR;

// =========================
// SYSTEM MODE / HARD REQUEST OVERRIDES
// =========================
IF L_Policy_Safe_Stop OR VI_Vent_Stop THEN
    IF VI_Vent_Stop THEN
        VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА ПО КОМАНДЕ';
    ELSE
        VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
    END_IF;
    RETURN;
END_IF;

IF L_Policy_Degraded THEN
    VO_Ventilation_Subsystem_Degraded := TRUE;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
    RETURN;
END_IF;

// 1. Определение базовой скорости и целевой температуры по сценарию (ТЗ 7.1)
CASE VI_Current_Scenario OF
    E_SCENARIO_TYPE.SCENARIO_AWAY:
        L_Base_Speed := VI_Config.Scenario_Modes[3].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[3].Target_Temp;
    E_SCENARIO_TYPE.SCENARIO_SLEEP:
        L_Base_Speed := VI_Config.Scenario_Modes[2].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[2].Target_Temp;
    ELSE // PRESENCE, MORNING, EVENING
        L_Base_Speed := VI_Config.Scenario_Modes[1].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[1].Target_Temp;
END_CASE;

// 2. Логика управления приточными установками (П-1, П-2, П-3)
IF NOT L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
            L_PID_Heaters[L_i](
                VI_SetPoint := L_Target_Temp,
                VI_ProcessValue := VI_Supply_Temps[L_i],
                VI_Kp := 4.0, VI_Tn := 120.0, VI_Tv := 0.0,
                VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
                VO_Output => VO_Heater_Power[L_i]
            );
        END_IF;

        VO_Supply_Fans[L_i] := L_Base_Speed;

        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
            IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
                IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_VENTILATION THEN
                    VO_Supply_Fans[L_i] := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
                END_IF;
            END_IF;
        END_FOR;
    END_FOR;
END_IF;

// 3. Логика управления вытяжными установками (В-1 .. В-5)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    VO_Exhaust_Fans[L_i] := L_Base_Speed;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
        IF VI_Config.wet_zone_to_exhaust_map[L_j] = L_i THEN
            L_Wet_Zone_Timers[L_j](IN := VI_Wet_Zone_Active[L_j], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);
            IF VI_Wet_Zone_Active[L_j] THEN
                VO_Exhaust_Fans[L_i] := 80;
            ELSIF L_Wet_Zone_Timers[L_j].Q THEN
                VO_Exhaust_Fans[L_i] := 50;
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// ========================================
// OPERATIONAL REQUEST OVERRIDES
// ========================================
IF NOT L_Policy_Degraded THEN
    IF VI_Supply_100_Req THEN
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
            VO_Supply_Fans[L_i] := 100;
        END_FOR;
    ELSIF VI_Supply_80_Req THEN
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
            IF VO_Supply_Fans[L_i] < 80 THEN
                VO_Supply_Fans[L_i] := 80;
            END_IF;
        END_FOR;
    END_IF;

    IF VI_PV3_Boost_Req THEN
        IF GVL_CONSTANTS.C_MAX_SUPPLY_FANS >= 3 THEN
            VO_Supply_Fans[3] := 100;
        END_IF;
    END_IF;
END_IF;

IF VI_Exhaust_100_Req THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 100;
    END_FOR;
END_IF;

// ========================================
// VENT_FINAL_CLAMP
// ========================================
IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := MIN(VO_Exhaust_Fans[L_i], VI_Config.Degraded_Exhaust_Limit);
    END_FOR;
END_IF;

// 4. Формирование статусного сообщения
IF L_Policy_Degraded THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
ELSIF VI_PV3_Boost_Req OR VI_Supply_100_Req OR VI_Exhaust_100_Req OR VI_Supply_80_Req THEN
    VO_Status_Msg := 'Вентиляция: активен операционный boost/request';
ELSE
    VO_Status_Msg := 'Вентиляция работает в штатном режиме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Ventilation_System_Manager <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    VO_OT_Enable[L_i] := FALSE;
    VO_OT_Setpoint[L_i] := 0.0;
    VO_OT_Command_Valid[L_i] := FALSE;

    L_Command_Enable := FALSE;
    L_Setpoint := 0.0;
    L_Setpoint_x10 := 0;

    // ======================================================
    // COMMAND VALIDATION
    // ======================================================
    IF VI_Enable[L_i] AND VI_OT_Online[L_i] AND NOT VI_OT_Error[L_i] THEN
        L_Command_Enable := TRUE;
        L_Setpoint := LIMIT(20.0, VI_Setpoint[L_i], 80.0);
        L_Setpoint_x10 := REAL_TO_UINT(L_Setpoint * 10.0);

        VO_OT_Enable[L_i] := TRUE;
        VO_OT_Setpoint[L_i] := L_Setpoint;
    END_IF;

    // ======================================================
    // PHYSICAL ADAPTER COMMAND IMAGE
    // ======================================================
    GVL_OPENTHERM_ADAPTER.G_Command[L_i].Enable := L_Command_Enable;
    GVL_OPENTHERM_ADAPTER.G_Command[L_i].Setpoint_x10 := L_Setpoint_x10;

    // Sequence is advanced only when the actual command image changes.
    // This keeps the command stable long enough for adapter ACK validation.
    L_Command_Changed :=
        (L_Command_Enable <> L_Last_Command_Enable[L_i]) OR
        (L_Setpoint_x10 <> L_Last_Command_Setpoint_x10[L_i]);

    IF L_Command_Changed THEN
        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence :=
            GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence + 1;

        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Last_Write_MS :=
            GVL_STATUS.G_System_Time_MS;

        L_Last_Command_Enable[L_i] := L_Command_Enable;
        L_Last_Command_Setpoint_x10[L_i] := L_Setpoint_x10;
    END_IF;

    // Command is valid only when the adapter confirms the current stable sequence.
    VO_OT_Command_Valid[L_i] :=
        L_Command_Enable AND
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Ack AND
        (NOT GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error) AND
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Online;

END_FOR;

// ==============================================================================
// Heating source stability observer
//
// Predictive observability-only layer.
//
// DOES NOT own runtime authority.
// DOES NOT own outputs.
// DOES NOT close valves.
// DOES NOT modify heating demand.
// DOES NOT override runtime decisions.
//
// Observes:
// - source switching frequency
// - fallback oscillation
// - degradation persistence
// - recovery trends
// - confidence volatility
//
// Publishes predictive instability semantics only.
//
// Reads only canonical runtime projection contracts.
// Does not depend on explainability publication topology.
// ==============================================================================



IF NOT VI_Enable THEN
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO

    // ======================================================
    // VISIBILITY
    // ======================================================
    GVL_Heating_Source_Stability.G_State[L_i].Visible :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Visible;

    // ======================================================
    // EDGE COUNTING
    // ======================================================
    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Switched_Event THEN
        IF GVL_Heating_Source_Stability.G_State[L_i].Source_Switch_Count < 65535 THEN
            GVL_Heating_Source_Stability.G_State[L_i].Source_Switch_Count :=
                GVL_Heating_Source_Stability.G_State[L_i].Source_Switch_Count + 1;
        END_IF;

        GVL_Heating_Source_Stability.G_State[L_i].Last_Observation_MS :=
            VI_System_Time_MS;
    END_IF;

    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Activated_Event THEN
        IF GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count < 65535 THEN
            GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count :=
                GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count + 1;
        END_IF;

        GVL_Heating_Source_Stability.G_State[L_i].Last_Observation_MS :=
            VI_System_Time_MS;
    END_IF;

    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Recovered_Event THEN
        IF GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count < 65535 THEN
            GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count :=
                GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count + 1;
        END_IF;

        GVL_Heating_Source_Stability.G_State[L_i].Last_Observation_MS :=
            VI_System_Time_MS;
    END_IF;

    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Loss_Event THEN
        IF GVL_Heating_Source_Stability.G_State[L_i].Source_Loss_Count < 65535 THEN
            GVL_Heating_Source_Stability.G_State[L_i].Source_Loss_Count :=
                GVL_Heating_Source_Stability.G_State[L_i].Source_Loss_Count + 1;
        END_IF;

        GVL_Heating_Source_Stability.G_State[L_i].Last_Observation_MS :=
            VI_System_Time_MS;
    END_IF;

    // ======================================================
    // CONFIDENCE VOLATILITY
    // ======================================================
    L_Confidence_Delta := ABS(
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence -
        L_Last_Confidence[L_i]
    );

    L_Confidence_Volatility :=
        GVL_Heating_Source_Stability.G_State[L_i].Confidence_Volatility * REAL#0.90 +
        L_Confidence_Delta * REAL#0.10;

    IF L_Confidence_Volatility < REAL#0.0 THEN
        L_Confidence_Volatility := REAL#0.0;
    ELSIF L_Confidence_Volatility > REAL#1.0 THEN
        L_Confidence_Volatility := REAL#1.0;
    END_IF;

    GVL_Heating_Source_Stability.G_State[L_i].Confidence_Volatility :=
        L_Confidence_Volatility;

    // ======================================================
    // SOURCE TRUST TREND
    // ======================================================
    L_Source_Trust_Trend :=
        GVL_Heating_Source_Stability.G_State[L_i].Source_Trust_Trend * REAL#0.95 +
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence * REAL#0.05;

    IF GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Degraded THEN
        L_Source_Trust_Trend := L_Source_Trust_Trend * REAL#0.98;
    END_IF;

    IF L_Source_Trust_Trend < REAL#0.0 THEN
        L_Source_Trust_Trend := REAL#0.0;
    ELSIF L_Source_Trust_Trend > REAL#1.0 THEN
        L_Source_Trust_Trend := REAL#1.0;
    END_IF;

    GVL_Heating_Source_Stability.G_State[L_i].Source_Trust_Trend :=
        L_Source_Trust_Trend;

    // ======================================================
    // TREND OBSERVATION
    // ======================================================
    GVL_Heating_Source_Stability.G_State[L_i].Degraded_Trend_Visible :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Degraded OR
        (GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count >
         GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count);

    GVL_Heating_Source_Stability.G_State[L_i].Recovery_Trend_Visible :=
        (GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count > 0) AND
        (GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count >=
         GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count);

    GVL_Heating_Source_Stability.G_State[L_i].Oscillation_Detected :=
        (GVL_Heating_Source_Stability.G_State[L_i].Source_Switch_Count >= 3) OR
        ((GVL_Heating_Source_Stability.G_State[L_i].Fallback_Activation_Count >= 2) AND
         (GVL_Heating_Source_Stability.G_State[L_i].Fallback_Recovery_Count >= 2));

    // ======================================================
    // INSTABILITY SCORE
    // ======================================================
    L_Instability_Score := REAL#0.0;

    IF GVL_Heating_Source_Stability.G_State[L_i].Oscillation_Detected THEN
        L_Instability_Score := L_Instability_Score + REAL#40.0;
    END_IF;

    IF GVL_Heating_Source_Stability.G_State[L_i].Degraded_Trend_Visible THEN
        L_Instability_Score := L_Instability_Score + REAL#30.0;
    END_IF;

    IF GVL_Heating_Source_Stability.G_State[L_i].Source_Loss_Count > 0 THEN
        L_Instability_Score := L_Instability_Score + REAL#30.0;
    END_IF;

    L_Instability_Score :=
        L_Instability_Score +
        (GVL_Heating_Source_Stability.G_State[L_i].Confidence_Volatility * REAL#20.0);

    IF L_Instability_Score > REAL#100.0 THEN
        L_Instability_Score := REAL#100.0;
    END_IF;

    GVL_Heating_Source_Stability.G_State[L_i].Instability_Score :=
        L_Instability_Score;

    GVL_Heating_Source_Stability.G_State[L_i].Instability_Attention :=
        L_Instability_Score >= REAL#60.0;

    // ======================================================
    // EXPLAINABILITY PUBLICATION
    // ======================================================
    IF GVL_Heating_Source_Stability.G_State[L_i].Source_Loss_Count > 0 THEN
        GVL_Heating_Source_Stability.G_State[L_i].Status_Code := 904;
        GVL_Heating_Source_Stability.G_State[L_i].Status_Text :=
            'Predictive source instability: source loss observed';

    ELSIF GVL_Heating_Source_Stability.G_State[L_i].Oscillation_Detected THEN
        GVL_Heating_Source_Stability.G_State[L_i].Status_Code := 903;
        GVL_Heating_Source_Stability.G_State[L_i].Status_Text :=
            'Predictive source instability: oscillation detected';

    ELSIF GVL_Heating_Source_Stability.G_State[L_i].Degraded_Trend_Visible THEN
        GVL_Heating_Source_Stability.G_State[L_i].Status_Code := 902;
        GVL_Heating_Source_Stability.G_State[L_i].Status_Text :=
            'Predictive source degradation trend observed';

    ELSE
        GVL_Heating_Source_Stability.G_State[L_i].Status_Code := 901;
        GVL_Heating_Source_Stability.G_State[L_i].Status_Text :=
            'Source stability nominal';
    END_IF;

    L_Last_Confidence[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Source_Stability_Observer <<<

// ==============================================================================
// Config simulation / validation function block
// Service/commissioning validation utility.
// Does NOT own runtime control and does NOT participate in heating phase runtime.
// ==============================================================================



VO_Executed := FALSE;
VO_Result_OK := GVL_CONFIG_SIMULATION.G_Simulation_Result_OK;
VO_Error_Text := GVL_CONFIG_SIMULATION.G_Simulation_Error_Text;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

IF VI_Request AND VI_Confirm THEN

    L_Error := FALSE;
    VO_Result_OK := TRUE;
    VO_Error_Text := '';

    // Simulate INPUT constraints.
    IF (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate < 0.0) OR (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid learning rate';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay < 0.0) OR (GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid recovery decay';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid minimum confidence';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid spike confidence';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Default_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Default_Confidence > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid default confidence';
        L_Error := TRUE;
    END_IF;

    // Simulate SCENARIO logic.
    IF (GVL_CONFIG_CONTROL.STG_Night_Start_Hour < 0) OR (GVL_CONFIG_CONTROL.STG_Night_Start_Hour > 23) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Night start hour invalid';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Night_End_Hour < 0) OR (GVL_CONFIG_CONTROL.STG_Night_End_Hour > 23) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Night end hour invalid';
        L_Error := TRUE;
    END_IF;

    IF GVL_CONFIG_CONTROL.STG_Night_Start_Hour = GVL_CONFIG_CONTROL.STG_Night_End_Hour THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Night window invalid';
        L_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold < 0.0) OR (GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold > 100.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Humidity threshold invalid';
        L_Error := TRUE;
    END_IF;

    // Simulate SAFETY.
    IF GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS < 1000 THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Recovery delay too small';
        L_Error := TRUE;
    END_IF;

    // Simulate FAIL-SAFE policy.
    IF NOT (
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water
    ) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Fail-safe disabled';
        L_Error := TRUE;
    END_IF;

    GVL_CONFIG_SIMULATION.G_Simulation_Result_OK := NOT L_Error;
    GVL_CONFIG_SIMULATION.G_Simulation_Error_Text := VO_Error_Text;
    GVL_CONFIG_SIMULATION.G_Simulation_Last_Run_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq := GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq + 1;
    GVL_CONFIG_SIMULATION.G_Simulation_Staged_Config_Version := GVL_CONFIG_CONTROL.G_Staged_Config_Version;
    VO_Executed := TRUE;

    // One-shot request consumption. HMI/service callers get the result from
    // GVL_CONFIG_SIMULATION and must raise a new request for another run.
    GVL_CONFIG_SIMULATION.G_Simulation_Request := FALSE;
    GVL_CONFIG_SIMULATION.G_Simulation_Confirm := FALSE;

END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Config_Simulation <<<

// >>> SYNC_TEST_MARKER_001 <<<


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


GVL_STATE.G_DHW_IO_Fault := FALSE;
GVL_STATE.G_DHW_Sensor_Fault := FALSE;
GVL_STATE.G_DHW_Subsystem_Degraded := FALSE;

IF VI_Emergency_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // временно используем общий аварийный код до детализации safety-кодов
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Фиксация текущего времени
L_Current_TOD := VI_Current_TOD;

// ========================================
// DHW POLICY LAYER
// ========================================
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Target_Temp_Adjusted := VI_Config.Target_Temp;
IF L_Policy_Degraded THEN
    L_Target_Temp_Adjusted := VI_Config.Target_Temp - VI_Config.Degraded_Target_Delta;
END_IF;

// ========================================
// DHW POLICY OVERRIDE
// ========================================
IF L_Policy_Safe_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

// Сброс признака выполнения термодезинфекции при смене дня.
IF L_Last_Legionella_Day <> VI_Current_Day_Of_Week THEN
    L_Legionella_Done_Today := FALSE;
    L_Last_Legionella_Day := VI_Current_Day_Of_Week;
END_IF;

// Базовый сброс незащёлкнутых статусных флагов на текущий цикл.
// Критические ошибки ниже могут зафиксироваться и завершить выполнение через RETURN.
VO_Status.Warning := FALSE;
VO_Status.Error := FALSE;
VO_Status.Error_ID := 0;

// Сброс ошибок
IF VI_Reset_Errors THEN
    L_Error_Latched := FALSE;
    L_Error_ID_Latched := 0;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_Error_Latched := TRUE;
        GVL_STATE.G_DHW_IO_Fault := TRUE;
        L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // Потеря связи с модулями ввода-вывода
    END_IF;
END_FOR;

// 1. Обработка неисправностей датчиков и сервисных режимов (ТЗ 7.0)
fbTempValidator(
    VI_Value := VI_Temp,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 100.0,
    VI_Fallback_Mode := 0,
    VI_Default_Value := 55.0
);

fbPressValidator(
    VI_Value := VI_Pressure,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 10.0,
    VI_Fallback_Mode := 0
);

VO_Status.Temp := fbTempValidator.VO_Value;
VO_Status.Pressure := fbPressValidator.VO_Value;

// Сохраняем последнее достоверное значение температуры ГВС.
// Используется только для диагностики/сервиса, не для fallback-управления.
IF NOT fbTempValidator.VO_Error THEN
    L_Last_Good_Temp := VO_Status.Temp;
END_IF;

IF fbTempValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_TEMP_SENSOR_FAULT); // Критическая ошибка датчика температуры
ELSIF (VO_Status.Pressure < 1.0 OR VO_Status.Pressure > 4.0) AND NOT fbPressValidator.VO_Error THEN
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_OUT_OF_RANGE); // Давление вне нормы
END_IF;

IF L_Error_Latched THEN
    // Критическая ошибка: переход в безопасное состояние с полной остановкой насосов.
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := L_Error_ID_Latched;
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Ошибка датчика давления не останавливает ГВС,
// но переводит подсистему в режим предупреждения (degraded mode).
IF fbPressValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    GVL_STATE.G_DHW_Subsystem_Degraded := TRUE;
    VO_Status.Warning := TRUE;
    VO_Status.Error := FALSE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_SENSOR_FAULT);
END_IF;

// 2. Логика поддержания температуры воды в бойлере (Нагрев)
// На этом этапе FB уже выполняется только на активном ПЛК.

// Термическая дезинфекция (Легионелла)
IF VI_Config.Anti_Legionella_Enabled
   AND (VI_Current_Day_Of_Week = VI_Config.Anti_Legionella_Day)
   AND (L_Current_TOD >= TOD#02:00)
   AND (L_Current_TOD <= TOD#04:00)
   AND NOT L_Legionella_Done_Today THEN
    L_Legionella_Active := TRUE;
ELSE
    L_Legionella_Active := FALSE;
END_IF;

L_Legionella_Timer(IN := L_Legionella_Active AND VO_Status.Temp >= 70.0, PT := T#30m, VI_System_Time_MS := VI_System_Time_MS);
IF L_Legionella_Timer.Q THEN
    L_Legionella_Active := FALSE; // Дезинфекция завершена
    L_Legionella_Done_Today := TRUE; // Повторно в те же сутки не запускать
END_IF;

// Двухпозиционное регулирование с гистерезисом
IF L_Legionella_Active THEN
    IF VO_Status.Temp < 70.0 THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > 72.0 THEN
        VO_Heating_Pump := FALSE;
    END_IF;
ELSE
    IF VO_Status.Temp < (L_Target_Temp_Adjusted - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (L_Target_Temp_Adjusted + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;
END_IF;

// 3. Управление циркуляционным насосом ГВС по расписанию
// Рециркуляция обеспечивает мгновенное наличие горячей воды у потребителя
VO_Circ_Pump := SEL(VI_Config.Circulation_Schedule_Enabled AND NOT (VI_Config.Night_Mode_Enabled AND (L_Current_TOD < VI_Config.Circulation_Start OR L_Current_TOD > VI_Config.Circulation_End)), FALSE, TRUE);

// Формирование статусных данных для визуализации.
// К этому моменту статус уже консистентен:
// - Error = критическая ошибка с остановкой ГВС
// - Warning = деградация без остановки
VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;

// >>> BULK_SYNC_ANCHOR: FB_DHW_Manager <<<

// Compatibility placeholder.
// Previous METHOD Calculate returned DWORD#0.
// Keep same behaviour without METHOD syntax for this CODESYS project format.
IF VI_Enable THEN
    VO_CRC := DWORD#0;
END_IF;

