// ==============================================================================
// Heating circuit explainability adapter
//
// Projection-to-explainability adapter.
//
// DOES NOT own runtime authority.
// DOES NOT own outputs.
// DOES NOT close valves.
// DOES NOT modify heating demand.
// DOES NOT override runtime decisions.
//
// Reads canonical runtime projection contracts and publishes legacy-compatible
// circuit explainability surfaces for HMI/diagnostics/supervisory visibility.
// ==============================================================================



IF NOT VI_Enable THEN
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_Heating_Circuit_Explainability.G_Source_Selection_Visible[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Visible;

    GVL_Heating_Circuit_Explainability.G_Selected_Source_Code[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Code;

    CASE GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Code OF
        1:
            GVL_Heating_Circuit_Explainability.G_Selected_Source_Text[L_i] := 'room';
        2:
            GVL_Heating_Circuit_Explainability.G_Selected_Source_Text[L_i] := 'floor';
    ELSE
        GVL_Heating_Circuit_Explainability.G_Selected_Source_Text[L_i] := 'none';
    END_CASE;

    GVL_Heating_Circuit_Explainability.G_Fallback_Active[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Active;

    GVL_Heating_Circuit_Explainability.G_Source_Degraded[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Degraded;

    GVL_Heating_Circuit_Explainability.G_Selected_Source_Confidence[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence;

    // Primary/fallback confidence remain legacy-compatible fields. The runtime
    // projection intentionally exposes selected confidence only, so these fields
    // mirror the selected source confidence until a dedicated richer projection
    // contract is introduced.
    GVL_Heating_Circuit_Explainability.G_Primary_Source_Confidence[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence;

    GVL_Heating_Circuit_Explainability.G_Fallback_Source_Confidence[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence;

    GVL_Heating_Circuit_Explainability.G_Reason_Code[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Reason_Code;

    GVL_Heating_Circuit_Explainability.G_Reason_Text[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Reason_Text;

    GVL_Heating_Circuit_Explainability.G_Source_Switched_Event[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Switched_Event;

    GVL_Heating_Circuit_Explainability.G_Fallback_Activated_Event[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Activated_Event;

    GVL_Heating_Circuit_Explainability.G_Fallback_Recovered_Event[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Recovered_Event;

    GVL_Heating_Circuit_Explainability.G_Source_Loss_Event[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Loss_Event;

    GVL_Heating_Circuit_Explainability.G_Last_Event_MS[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_MS;

    GVL_Heating_Circuit_Explainability.G_Last_Event_Code[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_Code;

    GVL_Heating_Circuit_Explainability.G_Last_Event_Text[L_i] :=
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_Text;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Circuit_Explainability_Adapter <<<

// Calibration records are allowed to be neutral by default:
// multiplier=1.0, offset=0.0, verification_passed=FALSE.
// Non-neutral corrections must be verified before they affect normalized IO.
L_Record_Has_Correction := (VI_Record.offset <> 0.0) OR (VI_Record.multiplier <> 1.0);
L_Multiplier_In_Range := (VI_Record.multiplier >= 0.01) AND (VI_Record.multiplier <= 100.0);

VO_Record_Valid := TRUE;
VO_Record_Fault := FALSE;
VO_Calibration_Applied := FALSE;
VO_Used_Offset := 0.0;
VO_Used_Multiplier := 1.0;
VO_Last_Calibration_Timestamp := VI_Record.last_calibration_timestamp;

IF NOT L_Multiplier_In_Range THEN
    VO_Record_Valid := FALSE;
    VO_Record_Fault := TRUE;
ELSIF L_Record_Has_Correction AND NOT VI_Record.verification_passed THEN
    VO_Record_Valid := FALSE;
    VO_Record_Fault := TRUE;
END_IF;

IF VO_Record_Valid THEN
    VO_Used_Offset := VI_Record.offset;
    VO_Used_Multiplier := VI_Record.multiplier;
    VO_Calibration_Applied := L_Record_Has_Correction OR (VI_Record.last_calibration_timestamp <> 0);
    VO_Calibrated_Value := (VI_Raw_Value * VI_Record.multiplier) + VI_Record.offset;
ELSE
    // Fail safe for invalid calibration records: publish raw normalized input
    // and let the caller raise diagnostics through VO_Record_Fault.
    VO_Calibrated_Value := VI_Raw_Value;
END_IF;

// ==============================================================================
// Heating root-cause inference engine
// Internal diagnostics core.
// Does NOT own explainability publication or runtime control.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_RootCause := E_Heating_RootCause.RC_NONE;
VO_Confidence := 1.0;
VO_Error_Score := 0.0;
VO_Reason_Code := 0;
VO_Reason_Text := 'Heating inference OK';

// ======================================================
// SAFETY / GLOBAL BLOCKS
// ======================================================
IF VI_Emergency_Stop THEN
    VO_RootCause := E_Heating_RootCause.RC_EMERGENCY_STOP;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 10;
    VO_Reason_Text := 'Emergency stop active';
    RETURN;
END_IF;

IF VI_Gas_Safety THEN
    VO_RootCause := E_Heating_RootCause.RC_GAS_SAFETY;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 20;
    VO_Reason_Text := 'Gas safety active';
    RETURN;
END_IF;

IF VI_IO_Failsafe THEN
    VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 30;
    VO_Reason_Text := 'Heating IO failsafe active';
    RETURN;
END_IF;

// ======================================================
// AGGREGATE LEGACY / LOW-LEVEL FLAGS
// ======================================================
L_AnyBoilerOnline := FALSE;
L_AnyBoilerError := FALSE;
L_AnyFlame := FALSE;
L_AnyCommandTimeout := FALSE;
L_AnyHeartbeatTimeout := FALSE;
L_AnyAdapterError := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF VI_Boiler_OT_Online[L_i] THEN
        L_AnyBoilerOnline := TRUE;
    END_IF;

    IF VI_Boiler_Error[L_i] THEN
        L_AnyBoilerError := TRUE;
    END_IF;

    IF VI_Boiler_Flame[L_i] THEN
        L_AnyFlame := TRUE;
    END_IF;

    IF VI_Boiler_OT_Command_Timeout[L_i] THEN
        L_AnyCommandTimeout := TRUE;
    END_IF;

    IF VI_Boiler_OT_Heartbeat_Timeout[L_i] THEN
        L_AnyHeartbeatTimeout := TRUE;
    END_IF;

    IF VI_Boiler_OT_Adapter_Error[L_i] THEN
        L_AnyAdapterError := TRUE;
    END_IF;
END_FOR;

L_AnyDemand := FALSE;
L_AnyPumpOn := FALSE;
L_AnyValveOpen := FALSE;
L_LowSupply := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Demand_Map[L_i] THEN
        L_AnyDemand := TRUE;
    END_IF;

    IF VI_Manifold_Pumps[L_i] THEN
        L_AnyPumpOn := TRUE;
    END_IF;

    IF VI_Manifold_Valves[L_i] > 5.0 THEN
        L_AnyValveOpen := TRUE;
    END_IF;

    IF VI_Demand_Map[L_i] AND (VI_Supply_Temps[L_i] < (VI_Target_Supply - 2.0)) THEN
        L_LowSupply := TRUE;
    END_IF;
END_FOR;

L_CascadeSemanticKnown :=
    VI_Cascade_Available OR
    VI_Cascade_Degraded OR
    VI_Cascade_Partial_Capacity OR
    VI_Cascade_No_Flame OR
    VI_Cascade_Transport_Degraded OR
    VI_Cascade_Ignition_Timeout OR
    (VI_Cascade_Active_Boilers > 0) OR
    (VI_Cascade_Available_Boilers > 0);

// ======================================================
// MODERN CASCADE / OPENTHERM SEMANTICS
// ======================================================
IF L_CascadeSemanticKnown THEN

    IF NOT VI_Cascade_Available THEN
        VO_RootCause := E_Heating_RootCause.RC_BOILER_OFFLINE;
        VO_Confidence := 0.95;
        VO_Error_Score := 0.95;
        VO_Reason_Code := 100;
        VO_Reason_Text := 'Heating cascade unavailable';
        RETURN;
    END_IF;

    IF VI_Cascade_Transport_Degraded THEN
        IF L_AnyHeartbeatTimeout THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.90;
            VO_Error_Score := 0.90;
            VO_Reason_Code := 210;
            VO_Reason_Text := 'OpenTherm heartbeat timeout';
            RETURN;
        END_IF;

        IF L_AnyCommandTimeout THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.85;
            VO_Error_Score := 0.85;
            VO_Reason_Code := 220;
            VO_Reason_Text := 'OpenTherm command ACK timeout';
            RETURN;
        END_IF;

        IF L_AnyAdapterError THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.85;
            VO_Error_Score := 0.85;
            VO_Reason_Code := 230;
            VO_Reason_Text := 'OpenTherm adapter error';
            RETURN;
        END_IF;

        VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
        VO_Confidence := 0.75;
        VO_Error_Score := 0.75;
        VO_Reason_Code := 200;
        VO_Reason_Text := 'OpenTherm transport degraded';
        RETURN;
    END_IF;

    IF VI_Cascade_Ignition_Timeout THEN
        VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
        VO_Confidence := 0.90;
        VO_Error_Score := 0.90;
        VO_Reason_Code := 300;
        VO_Reason_Text := 'Boiler ignition timeout';
        RETURN;
    END_IF;

    IF VI_Cascade_No_Flame THEN
        VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 310;
        VO_Reason_Text := 'Cascade active but no flame';
        RETURN;
    END_IF;

    IF VI_Cascade_Partial_Capacity THEN
        VO_RootCause := E_Heating_RootCause.RC_LOW_SUPPLY_TEMP;
        VO_Confidence := 0.60;
        VO_Error_Score := 0.40;
        VO_Reason_Code := 500;
        VO_Reason_Text := 'Partial cascade capacity';
        RETURN;
    END_IF;
END_IF;

// ======================================================
// LEGACY BOILER / TRANSPORT FALLBACK
// ======================================================
IF NOT L_AnyBoilerOnline THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_OFFLINE;
    VO_Confidence := 0.90;
    VO_Error_Score := 0.90;
    VO_Reason_Code := 110;
    VO_Reason_Text := 'No boiler online';
    RETURN;
END_IF;

IF L_AnyBoilerError THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_ERROR;
    VO_Confidence := 0.90;
    VO_Error_Score := 0.90;
    VO_Reason_Code := 120;
    VO_Reason_Text := 'Boiler error active';
    RETURN;
END_IF;

IF L_AnyDemand AND NOT L_AnyFlame THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
    VO_Confidence := 0.80;
    VO_Error_Score := 0.80;
    VO_Reason_Code := 130;
    VO_Reason_Text := 'Demand active but no flame';
    RETURN;
END_IF;

// ======================================================
// HYDRAULICS
// ======================================================
IF L_AnyDemand THEN
    IF NOT L_AnyPumpOn THEN
        VO_RootCause := E_Heating_RootCause.RC_PUMP_FAILURE;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 400;
        VO_Reason_Text := 'Demand active but manifold pumps are off';
        RETURN;
    END_IF;

    IF NOT L_AnyValveOpen THEN
        VO_RootCause := E_Heating_RootCause.RC_VALVES_CLOSED;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 410;
        VO_Reason_Text := 'Demand active but manifold valves are closed';
        RETURN;
    END_IF;
END_IF;

// ======================================================
// THERMAL TRANSFER
// ======================================================
IF L_AnyDemand AND L_LowSupply THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_HEAT_TRANSFER;
    VO_Confidence := 0.70;
    VO_Error_Score := 0.70;
    VO_Reason_Code := 420;
    VO_Reason_Text := 'Supply temperature below target under demand';
    RETURN;
END_IF;

// ======================================================
// SENSORS
// ======================================================
IF VI_Sensor_Error THEN
    VO_RootCause := E_Heating_RootCause.RC_SENSOR_ERROR;
    VO_Confidence := 0.70;
    VO_Error_Score := 0.70;
    VO_Reason_Code := 450;
    VO_Reason_Text := 'Heating sensor error active';
    RETURN;
END_IF;

// ======================================================
// NORMAL
// ======================================================
VO_RootCause := E_Heating_RootCause.RC_NONE;
VO_Confidence := 1.0;
VO_Error_Score := 0.0;
VO_Reason_Code := 0;
VO_Reason_Text := 'Heating inference OK';

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Any_Leak := FALSE;
L_Any_Warning := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    L_Sensor_Timers[L_i](
        IN := VI_Sensors[L_i],
        PT := TO_TIME(VI_Config.min_duration_ms + VI_Config.warning_duration_ms),
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF L_Sensor_Timers[L_i].ET >= TO_TIME(VI_Config.min_duration_ms) THEN
        L_Any_Warning := TRUE;

        IF L_Sensor_Timers[L_i].Q THEN
            L_Any_Leak := TRUE;
        END_IF;
    END_IF;
END_FOR;

// Manual latch instead of RS
IF GVL_INTENT_USER.I_Reset_Errors THEN
    VO_Leak_Detected := FALSE;
ELSIF L_Any_Leak THEN
    VO_Leak_Detected := TRUE;
END_IF;

VO_Leak_Warning_Level := L_Any_Warning;

IF VO_Leak_Detected THEN
    VO_Status_Msg := 'АВАРИЯ: ПРОТЕЧКА ВОДЫ.';
ELSIF L_Any_Warning THEN
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ: ОБНАРУЖЕНА ВОДА.';
ELSE
    VO_Status_Msg := 'Система контроля протечек в норме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Water_Leakage_Manager <<<

// Clear complete retained output snapshots before writing current frame.
// This prevents stale array entries in timeline/event/causality structures.
VO_Phase_Event := L_Empty_Phase_Event;
VO_Anomaly := L_Empty_Anomaly;
VO_Blackbox_Event := L_Empty_Blackbox_Event;
VO_Blackbox_Timeline := L_Empty_Blackbox_Timeline;
VO_Event_Buffer := L_Empty_Event_Buffer;
VO_Adaptive_Intelligence := L_Empty_Adaptive_Intelligence;
VO_Causality_Graph := L_Empty_Causality_Graph;
VO_Integration_Bridge := L_Empty_Integration_Bridge;
VO_Predictive_State := L_Empty_Predictive_State;
VO_Execution_Timeline := L_Empty_Execution_Timeline;
VO_Phase_Transition := L_Empty_Phase_Transition;
VO_Publication_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_Sequencing_Valid := VI_Runtime_Context.DHW_Before_Heating_Valid AND VI_Runtime_Context.State_Publication_Before_Diagnostics_Valid;
L_Ownership_Valid := VI_Runtime_Context.OpenTherm_Ownership_Valid AND VI_Runtime_Context.Cascade_Ownership_Valid AND VI_Runtime_Context.Safety_Isolation_Valid;
L_Synchronization_Valid := VI_Runtime_Context.Output_Projection_Last_Valid;
L_Runtime_Degraded := VI_Runtime_Observer_Fault OR NOT VI_Runtime_Observation_Valid;
L_Status_Code := VI_Runtime_Status_Code;

// Phase event
VO_Phase_Event.Phase := VI_Runtime_Context.Current_Phase;
