VO_Adaptive_Intelligence.Adaptive_Runtime_Stability_Observation := SEL(L_Runtime_Degraded, 100, 900);
VO_Adaptive_Intelligence.Runtime_Anomaly_Observation_Weight := 1;
VO_Adaptive_Intelligence.Cascade_Anomaly_Observation_Weight := 1;
VO_Adaptive_Intelligence.OpenTherm_Anomaly_Observation_Weight := 1;
VO_Adaptive_Intelligence.Diagnostics_Anomaly_Observation_Weight := 1;
VO_Adaptive_Intelligence.Predictive_Correlation_Observation := 1;
VO_Adaptive_Intelligence.Predictive_Correlation_Visible := TRUE;
VO_Adaptive_Intelligence.Sequencing_Confidence_Observation := SEL(L_Sequencing_Valid, 100, 900);
VO_Adaptive_Intelligence.Ownership_Confidence_Observation := SEL(L_Ownership_Valid, 100, 900);
VO_Adaptive_Intelligence.Synchronization_Confidence_Observation := SEL(L_Synchronization_Valid, 100, 900);
VO_Adaptive_Intelligence.Status_Code := L_Status_Code;
VO_Adaptive_Intelligence.Status_Text := VI_Runtime_Status_Text;

// Minimal causality graph snapshot
VO_Causality_Graph.Node_Count := 1;
VO_Causality_Graph.Edge_Count := 1;
VO_Causality_Graph.Graph_Active := TRUE;
VO_Causality_Graph.Graph_Degraded := L_Runtime_Degraded;
VO_Causality_Graph.Graph_Critical := VI_Runtime_Observer_Fault;
VO_Causality_Graph.Sequencing_Valid := L_Sequencing_Valid;
VO_Causality_Graph.Ownership_Valid := L_Ownership_Valid;
VO_Causality_Graph.Synchronization_Valid := L_Synchronization_Valid;
VO_Causality_Graph.Nodes[1].Node_ID := 1;
VO_Causality_Graph.Nodes[1].Node_Active := TRUE;
VO_Causality_Graph.Nodes[1].Runtime_Degraded := L_Runtime_Degraded;
VO_Causality_Graph.Nodes[1].Runtime_Fault := VI_Runtime_Observer_Fault;
VO_Causality_Graph.Nodes[1].Cascade_Degraded := NOT VI_Runtime_Context.Cascade_Ownership_Valid;
VO_Causality_Graph.Nodes[1].OpenTherm_Degraded := NOT VI_Runtime_Context.OpenTherm_Ownership_Valid;
VO_Causality_Graph.Nodes[1].Diagnostics_Degraded := NOT VI_Runtime_Context.Diagnostics_Isolation_Valid;
VO_Causality_Graph.Nodes[1].Explainability_Degraded := NOT VI_Runtime_Context.Explainability_Isolation_Valid;
VO_Causality_Graph.Nodes[1].Sequencing_Invalid := NOT L_Sequencing_Valid;
VO_Causality_Graph.Nodes[1].Ownership_Invalid := NOT L_Ownership_Valid;
VO_Causality_Graph.Nodes[1].Synchronization_Invalid := NOT L_Synchronization_Valid;
VO_Causality_Graph.Nodes[1].Severity_Level := SEL(VI_Runtime_Observer_Fault, 1, 900);
VO_Causality_Graph.Nodes[1].Root_Cause_Candidate := VI_Runtime_Observer_Fault;
VO_Causality_Graph.Nodes[1].Status_Code := L_Status_Code;
VO_Causality_Graph.Nodes[1].Status_Text := VI_Runtime_Status_Text;
VO_Causality_Graph.Edges[1].Source_Node_ID := 1;
VO_Causality_Graph.Edges[1].Target_Node_ID := 1;
VO_Causality_Graph.Edges[1].Edge_Active := TRUE;
VO_Causality_Graph.Edges[1].Propagation_Detected := L_Runtime_Degraded;
VO_Causality_Graph.Edges[1].Runtime_Propagation := L_Runtime_Degraded;
VO_Causality_Graph.Edges[1].Cascade_Propagation := NOT VI_Runtime_Context.Cascade_Ownership_Valid;
VO_Causality_Graph.Edges[1].OpenTherm_Propagation := NOT VI_Runtime_Context.OpenTherm_Ownership_Valid;
VO_Causality_Graph.Edges[1].Diagnostics_Propagation := NOT VI_Runtime_Context.Diagnostics_Isolation_Valid;
VO_Causality_Graph.Edges[1].Sequencing_Propagation := NOT L_Sequencing_Valid;
VO_Causality_Graph.Edges[1].Ownership_Propagation := NOT L_Ownership_Valid;
VO_Causality_Graph.Edges[1].Synchronization_Propagation := NOT L_Synchronization_Valid;
VO_Causality_Graph.Status_Code := L_Status_Code;
VO_Causality_Graph.Status_Text := VI_Runtime_Status_Text;

VO_Publication_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Explainability_Publisher <<<

// Периодическая синхронизация (каждые 5 секунд)
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Sync_Time, VI_System_Time_MS - L_Last_Sync_Time, (4294967295 - L_Last_Sync_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > 5000 THEN
    L_Periodic_Sync_Req := TRUE;
    L_Last_Sync_Time := VI_System_Time_MS;
ELSE
    L_Periodic_Sync_Req := FALSE;
END_IF;

// State Replication Logic
// Синхронизация состояния между ПЛК (ТЗ 8.2)
IF (VI_Sync_Req OR L_Periodic_Sync_Req) AND NOT L_Sync_In_Progress THEN
    L_Sync_In_Progress := TRUE;

    // Разрешение конфликтов на основе версии состояния
    IF VI_Remote_State.Version > VI_Local_State.Version THEN
        VO_Synced_State := VI_Remote_State;
        VO_State_Updated := TRUE;
    ELSIF VI_Remote_State.Version = VI_Local_State.Version THEN
        // Если версии равны, приоритет у ведущего ПЛК
        IF VI_Local_Role = E_PLC_ROLE.ROLE_STANDBY THEN
            VO_Synced_State := VI_Remote_State;
            VO_State_Updated := TRUE;
        ELSE
            VO_Synced_State := VI_Local_State;
            VO_State_Updated := FALSE;
        END_IF;
    ELSE
        VO_Synced_State := VI_Local_State;
        VO_State_Updated := FALSE;
    END_IF;
ELSIF NOT (VI_Sync_Req OR L_Periodic_Sync_Req) THEN
    L_Sync_In_Progress := FALSE;
    VO_State_Updated := FALSE;
    VO_Synced_State := VI_Local_State;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i] := VI_Zone_Enable[L_i];
END_FOR;

GVL_WATER_OUTPUT.DO_Water_Valve_35_Open := VI_Valve_35_Open;
GVL_WATER_OUTPUT.DO_Water_Valve_35_Close := VI_Valve_35_Close;
GVL_WATER_OUTPUT.DO_Water_Valve_36_Open := VI_Valve_36_Open;
GVL_WATER_OUTPUT.DO_Water_Valve_36_Close := VI_Valve_36_Close;

FOR L_i := 1 TO 6 DO
    GVL_WATER_OUTPUT.DO_Water_Local_Valve_Open[L_i] := VI_Local_Valve_Open[L_i];
    GVL_WATER_OUTPUT.DO_Water_Local_Valve_Close[L_i] := VI_Local_Valve_Close[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Water_Output_Projection <<<

IF NOT VI_Enable THEN
    GVL_Distributed_Projection_Ownership.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

// Finalized runtime continuity proof chain.
L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

FOR L_i := 1 TO 128 DO

    L_Ownership :=
        GVL_Distributed_Projection_Ownership.G_Projection_Ownership[L_i];

    IF L_Ownership.Ownership_Valid THEN

        L_Ownership.Runtime_System_Time_MS :=
            VI_System_Time_MS;

        // Ownership becomes stale if runtime sessions unhealthy.
        IF GVL_Runtime_Sessions.G_Any_Stale_Session THEN

            L_Ownership.Ownership_Stale := TRUE;
            L_Any_Stale := TRUE;

        END_IF;

        // Finalized continuity loss invalidates ownership.
        IF NOT L_Finalized_Runtime_Continuity THEN

            L_Ownership.Ownership_Stale := TRUE;
            L_Ownership.Projection_Blocked := TRUE;

            L_Any_Stale := TRUE;
            L_Any_Blocked := TRUE;

        END_IF;

        // Hard conflict prevention.
        IF GVL_Distributed_Runtime.G_Split_Brain_Suspected THEN

            L_Ownership.Ownership_Conflict := TRUE;
            L_Ownership.Projection_Blocked := TRUE;

            L_Any_Conflict := TRUE;
            L_Any_Blocked := TRUE;

        END_IF;

        // Distributed execution authority.
        IF GVL_Distributed_Authority.G_Authority_State.Authority_Master_Elected
           AND NOT L_Ownership.Ownership_Conflict
           AND NOT L_Ownership.Ownership_Stale
           AND L_Finalized_Runtime_Continuity THEN

            L_Ownership.Ownership_Granted := TRUE;
            L_Ownership.Distributed_Execution_Allowed := TRUE;
            L_Ownership.Distributed_Recovery_Allowed := TRUE;

            L_Ownership.Status_Code := 0;
            L_Ownership.Status_Text :=
                'Distributed projection ownership granted';

        ELSE

            L_Ownership.Ownership_Revoked := TRUE;
            L_Ownership.Projection_Blocked := TRUE;

            L_Any_Blocked := TRUE;

            L_Ownership.Status_Code := 2;
            L_Ownership.Status_Text :=
                'Distributed projection ownership blocked';

        END_IF;

        GVL_Distributed_Projection_Ownership.G_Projection_Ownership[L_i] :=
            L_Ownership;

    END_IF;

END_FOR;

GVL_Distributed_Projection_Ownership.G_Any_Ownership_Conflict :=
    L_Any_Conflict;

GVL_Distributed_Projection_Ownership.G_Any_Ownership_Stale :=
    L_Any_Stale;

GVL_Distributed_Projection_Ownership.G_Any_Projection_Blocked :=
    L_Any_Blocked;

GVL_Distributed_Projection_Ownership.G_Runtime_Valid := TRUE;
GVL_Distributed_Projection_Ownership.G_Last_Update_MS :=
    VI_System_Time_MS;

IF L_Any_Conflict THEN
    GVL_Distributed_Projection_Ownership.G_Status_Code := 3;
    GVL_Distributed_Projection_Ownership.G_Status_Text :=
        'Distributed projection ownership conflict detected';
ELSIF L_Any_Stale THEN
    GVL_Distributed_Projection_Ownership.G_Status_Code := 2;
    GVL_Distributed_Projection_Ownership.G_Status_Text :=
        'Distributed projection ownership stale';
ELSIF L_Any_Blocked THEN
    GVL_Distributed_Projection_Ownership.G_Status_Code := 1;
    GVL_Distributed_Projection_Ownership.G_Status_Text :=
        'Distributed projection ownership blocked';
ELSE
    GVL_Distributed_Projection_Ownership.G_Status_Code := 0;
    GVL_Distributed_Projection_Ownership.G_Status_Text :=
        'Distributed projection ownership healthy';
END_IF;

// ==============================================================================
// Heating runtime output projection phase
// Final phase wrapper around physical output projection.
// Does NOT calculate heating logic and does NOT publish state/status.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

fbOutputProjection(
    VI_Zone_Valves := VI_Zone_Valves,
    VI_Manifold_Pumps := VI_Manifold_Pumps,
    VI_Manifold_Valves := VI_Manifold_Valves,
    VI_DHW_Heating_Pump := VI_DHW_Heating_Pump,
    VI_DHW_Circ_Pump := VI_DHW_Circ_Pump,
    VI_Backup_Circulation_Pump := VI_Backup_Circulation_Pump,
    VI_Electric_Heater_Enable := VI_Electric_Heater_Enable
);

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Output_Projection_Phase <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

// Reset outputs
VO_Smoke_Detected := FALSE;
VO_Gas_Detected := FALSE;
VO_Methane_Warning_Level := FALSE;
VO_Methane_Alarm_Level := FALSE;
VO_Methane_Critical_Level := FALSE;
VO_CO_Warning_Level := FALSE;
VO_CO_Alarm_Level := FALSE;
VO_Status_Msg := 'ОК';

// --- Methane ---
L_Methane_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    IF VI_Methane_LEL[L_i] > L_Methane_Max THEN
        L_Methane_Max := VI_Methane_LEL[L_i];
    END_IF;
END_FOR;

VO_Methane_Warning_Level := (L_Methane_Max >= 10.0);
VO_Methane_Alarm_Level := (L_Methane_Max >= 20.0);
VO_Methane_Critical_Level := (L_Methane_Max >= 40.0);
VO_Gas_Detected := VO_Methane_Alarm_Level OR VO_Methane_Critical_Level;

// --- CO ---
L_CO_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    IF VI_CO_PPM[L_i] > L_CO_Max THEN
        L_CO_Max := VI_CO_PPM[L_i];
    END_IF;
END_FOR;

L_CO_Level_30 := (L_CO_Max >= 30.0);
L_CO_Level_70 := (L_CO_Max >= 70.0);
L_CO_Level_400 := (L_CO_Max >= 400.0);

L_CO_Timer_30ppm(IN := L_CO_Level_30, PT := T#8h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_70ppm(IN := L_CO_Level_70, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_400ppm(IN := L_CO_Level_400, PT := T#15m, VI_System_Time_MS := VI_System_Time_MS);

IF L_CO_Timer_30ppm.Q THEN
    VO_CO_Warning_Level := TRUE;
END_IF;

IF L_CO_Timer_70ppm.Q OR L_CO_Timer_400ppm.Q THEN
    VO_CO_Alarm_Level := TRUE;
END_IF;

// --- Smoke ---
L_Smoke_Count := 0;
L_Smoke_Active := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    L_Smoke_Timer[L_i](IN := VI_Smoke_Sensors[L_i], PT := T#30s, VI_System_Time_MS := VI_System_Time_MS);

    IF VI_Smoke_Sensors[L_i] THEN
        L_Smoke_Count := L_Smoke_Count + 1;
    END_IF;

    IF L_Smoke_Timer[L_i].Q OR (L_Smoke_Count >= 2) THEN
        L_Smoke_Active := TRUE;
    END_IF;
END_FOR;

IF L_Smoke_Active THEN
    VO_Smoke_Detected := TRUE;
END_IF;

// Status
IF VO_Smoke_Detected THEN
    VO_Status_Msg := 'ПОЖАР';
ELSIF VO_Methane_Critical_Level THEN
    VO_Status_Msg := 'КРИТИЧЕСКИЙ МЕТАН';
ELSIF VO_Methane_Alarm_Level THEN
    VO_Status_Msg := 'УТЕЧКА ГАЗА';
ELSIF VO_Methane_Warning_Level THEN
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ МЕТАН';
ELSIF VO_CO_Alarm_Level THEN
    VO_Status_Msg := 'КРИТИЧЕСКИЙ CO';
ELSIF VO_CO_Warning_Level THEN
    VO_Status_Msg := 'ПОВЫШЕННЫЙ CO';
ELSE
    VO_Status_Msg := 'ОК';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Gas_Smoke_Manager <<<

VO_Quality.Quality_Visible := VI_Enable;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

VO_Quality.Value_Valid := TRUE;
VO_Quality.Value_Degraded := FALSE;
VO_Quality.Spike_Detected := FALSE;
VO_Quality.Stuck_Detected := FALSE;
VO_Quality.Confidence := REAL#1.0;
VO_Quality.Reason_Code := 0;
VO_Quality.Reason_Text := 'OK';

L_Delta := ABS(VI_Value - L_Last_Value);

IF L_Delta > VI_Spike_Threshold THEN
    VO_Quality.Spike_Detected := TRUE;
    VO_Quality.Value_Degraded := TRUE;
    VO_Quality.Confidence := REAL#0.4;
    VO_Quality.Reason_Code := 1;
    VO_Quality.Reason_Text := 'Spike detected';
END_IF;

IF L_Delta > REAL#0.05 THEN
    L_Last_Change_MS := VI_System_Time_MS;
END_IF;

IF (VI_System_Time_MS > L_Last_Change_MS) AND
   ((VI_System_Time_MS - L_Last_Change_MS) > VI_Stuck_Timeout_MS) THEN

    VO_Quality.Stuck_Detected := TRUE;
    VO_Quality.Value_Degraded := TRUE;

    IF VO_Quality.Confidence > REAL#0.6 THEN
        VO_Quality.Confidence := REAL#0.6;
    END_IF;

    IF VO_Quality.Reason_Code = 0 THEN
        VO_Quality.Reason_Code := 2;
        VO_Quality.Reason_Text := 'Sensor appears stuck';
    END_IF;
END_IF;

VO_Quality.Last_Value := VI_Value;
VO_Quality.Last_Change_MS := L_Last_Change_MS;

L_Last_Value := VI_Value;

IF NOT VI_Enable THEN
    GVL_Water_Valve_Feedback.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Degraded := FALSE;
L_Any_Timeout := FALSE;
L_Any_Conflict := FALSE;

FOR L_i := 1 TO 8 DO
    L_State := L_Empty_State;
    L_State.Runtime_Valid := TRUE;
    L_State.Runtime_System_Time_MS := VI_System_Time_MS;

    // Valve identity used by HMI/diagnostics:
    // 1..6 = local riser valves, 7 = common inlet 35, 8 = common inlet 36.
    L_State.Valve_Group_Id := TO_UINT(L_i);
    L_State.Feedback_Available := TRUE;

    CASE L_i OF
        1..6:
            L_Command_Open := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Open[L_i];
            L_Command_Close := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Close[L_i];
        7:
            L_Command_Open := GVL_WATER_OUTPUT.DO_Water_Valve_35_Open;
            L_Command_Close := GVL_WATER_OUTPUT.DO_Water_Valve_35_Close;
        8:
            L_Command_Open := GVL_WATER_OUTPUT.DO_Water_Valve_36_Open;
            L_Command_Close := GVL_WATER_OUTPUT.DO_Water_Valve_36_Close;
    ELSE
            L_Command_Open := FALSE;
            L_Command_Close := FALSE;
    END_CASE;

    L_State.Physical_Open_Feedback := GVL_STATE.G_Water_Zone_Open_FB[L_i];
    L_State.Physical_Closed_Feedback := GVL_STATE.G_Water_Zone_Close_FB[L_i];

    IF L_State.Physical_Open_Feedback AND L_State.Physical_Closed_Feedback THEN
        L_State.Feedback_Conflict := TRUE;
        L_State.Feedback_Invalid := TRUE;
        L_State.Valve_Degraded := TRUE;
    END_IF;

    L_State.Confirmed_Open := L_State.Physical_Open_Feedback AND NOT L_State.Physical_Closed_Feedback;
    L_State.Confirmed_Closed := L_State.Physical_Closed_Feedback AND NOT L_State.Physical_Open_Feedback;
    L_State.Confirmation_Unknown := NOT L_State.Confirmed_Open AND NOT L_State.Confirmed_Closed AND NOT L_State.Feedback_Conflict;

    IF L_Command_Close AND NOT L_Command_Open THEN
        L_Desired_Code := 2;
    ELSIF L_Command_Open AND NOT L_Command_Close THEN
        L_Desired_Code := 1;
    ELSE
        L_Desired_Code := 0;
    END_IF;

    IF L_Desired_Code <> L_Prev_Desired_Code[L_i] THEN
        L_Command_Start_MS[L_i] := VI_System_Time_MS;
        L_Prev_Desired_Code[L_i] := L_Desired_Code;
    END_IF;

    L_Command_Active := (L_Desired_Code <> 0);

    IF L_Command_Active THEN
        IF VI_System_Time_MS >= L_Command_Start_MS[L_i] THEN
            L_Elapsed_MS := VI_System_Time_MS - L_Command_Start_MS[L_i];
        ELSE
            L_Elapsed_MS := (4294967295 - L_Command_Start_MS[L_i]) + VI_System_Time_MS + 1;
        END_IF;

        IF (L_Desired_Code = 1) AND L_State.Confirmed_Open THEN
            L_State.Feedback_Timeout := FALSE;
        ELSIF (L_Desired_Code = 2) AND L_State.Confirmed_Closed THEN
            L_State.Feedback_Timeout := FALSE;
        ELSIF L_Elapsed_MS >= 10000 THEN
            L_State.Feedback_Timeout := TRUE;
            L_State.Travel_Timeout_Active := TRUE;
            L_State.Valve_Stuck_Suspected := TRUE;
            L_State.Valve_Degraded := TRUE;
        END_IF;
    END_IF;

    IF L_State.Feedback_Conflict THEN
        L_State.Status_Code := 3;
        L_State.Status_Text := 'Valve feedback conflict detected';
    ELSIF L_State.Feedback_Timeout THEN
        L_State.Status_Code := 2;
        L_State.Status_Text := 'Valve feedback timeout';
    ELSIF L_State.Confirmation_Unknown THEN
        L_State.Status_Code := 1;
        L_State.Status_Text := 'Valve position unknown';
    ELSE
        L_State.Status_Code := 0;
        L_State.Status_Text := 'Valve feedback healthy';
    END_IF;

    GVL_Water_Valve_Feedback.G_Valve_Feedback_State[L_i] := L_State;

    L_Any_Degraded := L_Any_Degraded OR L_State.Valve_Degraded;
    L_Any_Timeout := L_Any_Timeout OR L_State.Feedback_Timeout;
    L_Any_Conflict := L_Any_Conflict OR L_State.Feedback_Conflict;
END_FOR;

GVL_Water_Valve_Feedback.G_Any_Degraded := L_Any_Degraded;
GVL_Water_Valve_Feedback.G_Any_Timeout := L_Any_Timeout;
GVL_Water_Valve_Feedback.G_Any_Conflict := L_Any_Conflict;
GVL_Water_Valve_Feedback.G_Runtime_Valid := TRUE;
GVL_Water_Valve_Feedback.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Conflict THEN
    GVL_Water_Valve_Feedback.G_Status_Code := 3;
    GVL_Water_Valve_Feedback.G_Status_Text := 'Valve feedback conflicts detected';
ELSIF L_Any_Timeout THEN
    GVL_Water_Valve_Feedback.G_Status_Code := 2;
    GVL_Water_Valve_Feedback.G_Status_Text := 'Valve feedback timeout detected';
ELSIF L_Any_Degraded THEN
    GVL_Water_Valve_Feedback.G_Status_Code := 1;
    GVL_Water_Valve_Feedback.G_Status_Text := 'Valve diagnostics degraded';
ELSE
    GVL_Water_Valve_Feedback.G_Status_Code := 0;
    GVL_Water_Valve_Feedback.G_Status_Text := 'Valve feedback runtime healthy';
END_IF;

IF NOT VI_Enable THEN
    GVL_Water_Output_Projection.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Projected := FALSE;
L_Any_Denied := FALSE;
L_Global_Fallback := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Authority := GVL_Water_Isolation_Authority.G_Authority_State[L_i];
    L_Valve := GVL_Water_Valve_Runtime.G_Valve_Runtime_State[L_i];

    // Reset all projection fields per sensor to prevent state leakage across loop iterations.
    L_Output.Projection_Valid := FALSE;
    L_Output.Projection_System_Time_MS := 0;
    L_Output.Output_Owner_Valid := FALSE;
    L_Output.Output_Owner_Id := 0;
    L_Output.Valve_Id := 0;
    L_Output.Valve_Group_Id := 0;
    L_Output.Selective_Authority_Allowed := FALSE;
    L_Output.Global_Fallback_Required := FALSE;
    L_Output.Authority_Valid := FALSE;
    L_Output.Physical_Close_Project := FALSE;
    L_Output.Physical_Open_Project := FALSE;
    L_Output.Expected_Closed := FALSE;
    L_Output.Expected_Open := FALSE;
    L_Output.Confirmed_Closed := FALSE;
    L_Output.Confirmed_Open := FALSE;
    L_Output.Confirmation_Unknown := FALSE;
    L_Output.Projection_Allowed := FALSE;
    L_Output.Projection_Denied := FALSE;
    L_Output.Projection_Code := 0;
    L_Output.Projection_Text := '';
    L_Output.Projection_Activated_Event := FALSE;
    L_Output.Projection_Denied_Event := FALSE;

    L_Output.Projection_Valid := TRUE;
    L_Output.Projection_System_Time_MS := VI_System_Time_MS;
    L_Output.Output_Owner_Valid := TRUE;
    L_Output.Output_Owner_Id := TO_UINT(L_i);
    L_Output.Valve_Id := L_Valve.Valve_Id;
    L_Output.Valve_Group_Id := L_Valve.Valve_Group_Id;
    L_Output.Selective_Authority_Allowed := L_Authority.Selective_Authority_Allowed;
    L_Output.Global_Fallback_Required := L_Authority.Global_Fallback_Required;
    L_Output.Authority_Valid := L_Authority.Decision_Valid;

    IF L_Output.Global_Fallback_Required THEN
        L_Output.Projection_Allowed := TRUE;
        L_Output.Physical_Close_Project := TRUE;
        L_Output.Expected_Closed := TRUE;
        L_Output.Projection_Code := 1;
        L_Output.Projection_Text := 'Global fallback output projection active';
        L_Global_Fallback := TRUE;
    ELSIF L_Output.Selective_Authority_Allowed AND L_Output.Authority_Valid THEN
        L_Output.Projection_Allowed := TRUE;
        L_Output.Physical_Close_Project := TRUE;
        L_Output.Expected_Closed := TRUE;
        L_Output.Projection_Code := 10;
        L_Output.Projection_Text := 'Selective authority output projection active';
    ELSE
        L_Output.Projection_Denied := TRUE;
        L_Output.Projection_Code := 100;
        L_Output.Projection_Text := 'Projection denied';
        L_Any_Denied := TRUE;
    END_IF;

    L_Output.Confirmed_Closed := L_Valve.Confirmed_Closed;
    L_Output.Confirmed_Open := L_Valve.Confirmed_Open;
    L_Output.Confirmation_Unknown := L_Valve.Confirmation_Unknown;
    L_Output.Projection_Activated_Event := L_Output.Projection_Allowed;
    L_Output.Projection_Denied_Event := L_Output.Projection_Denied;

    GVL_Water_Output_Projection.G_Output_Projection_State[L_i] := L_Output;
    L_Any_Projected := L_Any_Projected OR L_Output.Projection_Allowed;
END_FOR;

GVL_Water_Output_Projection.G_Any_Output_Projected := L_Any_Projected;
GVL_Water_Output_Projection.G_Any_Projection_Denied := L_Any_Denied;
GVL_Water_Output_Projection.G_Global_Fallback_Projecting := L_Global_Fallback;
GVL_Water_Output_Projection.G_Runtime_Valid := TRUE;
GVL_Water_Output_Projection.G_Last_Update_MS := VI_System_Time_MS;

IF L_Global_Fallback THEN
    GVL_Water_Output_Projection.G_Status_Code := 2;
    GVL_Water_Output_Projection.G_Status_Text := 'Global fallback output projection active';
ELSIF L_Any_Projected THEN
    GVL_Water_Output_Projection.G_Status_Code := 1;
    GVL_Water_Output_Projection.G_Status_Text := 'Selective output projection active';
ELSE
    GVL_Water_Output_Projection.G_Status_Code := 0;
    GVL_Water_Output_Projection.G_Status_Text := 'No output projections active';
END_IF;

IF NOT L_Initialized THEN
    L_Write_Index := GVL_Retain.G_BlackBox_LastIndex;
    IF L_Write_Index < 0 OR L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
        GVL_Retain.G_BlackBox_LastIndex := 0;
    END_IF;
    L_Initialized := TRUE;
END_IF;

IF VI_Reset THEN
    GVL_Retain.G_BlackBox_Frozen := FALSE;
END_IF;

IF VI_Freeze THEN
    GVL_Retain.G_BlackBox_Frozen := TRUE;
END_IF;

VO_Frozen := GVL_Retain.G_BlackBox_Frozen;

IF NOT GVL_Retain.G_BlackBox_Frozen THEN
    GVL_Retain.G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
    GVL_Retain.G_BlackBox_LastIndex := L_Write_Index;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
    END_IF;
END_IF;

VO_Records_Count := GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS;
// >>> BULK_SYNC_ANCHOR: FB_BlackBox_Recorder <<<

GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_ID := GVL_EVENT.G_Event_ID_Counter;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_Type := VI_Event_Type;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Timestamp := VI_Timestamp;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param1 := VI_Param1;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param2 := VI_Param2;

GVL_EVENT.G_Event_ID_Counter := GVL_EVENT.G_Event_ID_Counter + 1;
GVL_EVENT.G_Event_Head := (GVL_EVENT.G_Event_Head + 1) MOD 64;

IF NOT VI_Enable THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := FALSE;
    END_FOR;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Active := FALSE;
    L_Max_Boost := 0.0;

    FOR L_e := 1 TO 3 DO
        L_Event := GVL_HEATING_POLICY_CONFIG.G_Zone_Schedule[L_i, L_e];

        IF L_Event.Enabled THEN
            IF (L_Event.Weekday_Mask AND SHL(1, VI_Day_Of_Week - 1)) <> 0 THEN

                IF L_Event.Comfort_Time_MS >= VI_Time_Of_Day_MS THEN
                    L_Time_To_Comfort_MS := L_Event.Comfort_Time_MS - VI_Time_Of_Day_MS;
                ELSE
                    L_Time_To_Comfort_MS := (86400000 - VI_Time_Of_Day_MS) + L_Event.Comfort_Time_MS;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                    END_IF;
                    L_Time_To_Comfort_MS := L_Time_To_Comfort_MS + GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e];
                END_IF;

                IF (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] >= L_Time_To_Comfort_MS)
                   AND (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] > 0) THEN

                    IF L_Event.Preheat_Boost > L_Max_Boost THEN
                        L_Max_Boost := L_Event.Preheat_Boost;
                    END_IF;

                    L_Active := TRUE;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF L_Time_To_Comfort_MS < L_Learn_Window_MS THEN

                        IF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] > 1.0 THEN
                            L_Cold_Confirm[L_i, L_e] := L_Cold_Confirm[L_i, L_e] + 1;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        ELSIF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] < -0.5 THEN
                            L_Hot_Confirm[L_i, L_e] := L_Hot_Confirm[L_i, L_e] + 1;
                            L_Cold_Confirm[L_i, L_e] := 0;
                        ELSE
                            L_Cold_Confirm[L_i, L_e] := 0;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        END_IF;

                        // UDINT wrap-safe elapsed time; unsigned subtraction is valid modulo 2^32.
                        L_Elapsed_MS := VI_System_Time_MS - L_Last_Learn_MS[L_i, L_e];

                        IF L_Elapsed_MS >= L_Learn_Cooldown_MS THEN

                            IF L_Cold_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] < L_Event.Adaptive_Max_Offset_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] + L_Event.Adaptive_Step_MS;
                                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                                    END_IF;
                                    L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                END_IF;
                                L_Cold_Confirm[L_i, L_e] := 0;
                            END_IF;

                            IF L_Hot_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Step_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] - L_Event.Adaptive_Step_MS;
                                ELSE
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := 0;
                                END_IF;
                                L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                L_Hot_Confirm[L_i, L_e] := 0;
                            END_IF;

                        END_IF;
                    ELSE
                        L_Cold_Confirm[L_i, L_e] := 0;
                        L_Hot_Confirm[L_i, L_e] := 0;
                    END_IF;
                END_IF;

            END_IF;
        END_IF;
    END_FOR;

    L_Adjustment := GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i];

    IF L_Active AND (L_Adjustment < L_Max_Boost) THEN
        L_Adjustment := L_Max_Boost;
    END_IF;

    IF L_Adjustment > 1.0 THEN
        L_Adjustment := 1.0;
    ELSIF L_Adjustment < -1.0 THEN
        L_Adjustment := -1.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i] := L_Adjustment;
    GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := L_Active;
END_FOR;

L_Event_Text := '';

IF (VI_Severity <> L_Last_Severity) OR (VI_RootCause <> L_Last_RootCause) THEN
    CASE VI_RootCause OF
        E_System_Root_Cause.ROOT_FIRE:
            L_Event_Text := 'EVENT: FIRE DETECTED';
        E_System_Root_Cause.ROOT_GAS_LEAK:
            L_Event_Text := 'EVENT: GAS LEAK';
        E_System_Root_Cause.ROOT_CO_CRITICAL:
            L_Event_Text := 'EVENT: CO CRITICAL';
        E_System_Root_Cause.ROOT_CO_WARNING:
            L_Event_Text := 'EVENT: CO WARNING';
        E_System_Root_Cause.ROOT_WATER_LEAK:
            L_Event_Text := 'EVENT: WATER LEAK';
        E_System_Root_Cause.ROOT_SENSOR_FAULT:
            L_Event_Text := 'EVENT: SENSOR FAULT';
        E_System_Root_Cause.ROOT_IO_OFFLINE:
            L_Event_Text := 'EVENT: IO OFFLINE';
        E_System_Root_Cause.ROOT_COMM_FAULT:
            L_Event_Text := 'EVENT: COMM FAULT';
        E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
            L_Event_Text := 'EVENT: WATCHDOG FAULT';
        E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
            L_Event_Text := 'EVENT: SUBSYSTEM FAULT';
        ELSE
            L_Event_Text := 'EVENT: SYSTEM STATE CHANGE';
    END_CASE;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index > 16 THEN
        L_Write_Index := 1;
    END_IF;

    VO_Event_Time_MS[L_Write_Index] := VI_Time_MS;
    VO_Event_Severity[L_Write_Index] := VI_Severity;
    VO_Event_RootCause[L_Write_Index] := VI_RootCause;
    VO_Event_Text[L_Write_Index] := L_Event_Text;

    VO_Last_Index := L_Write_Index;
    VO_Last_Event_Text := L_Event_Text;

    IF VO_Event_Count < 16 THEN
        VO_Event_Count := VO_Event_Count + 1;
    END_IF;
END_IF;

L_Last_Severity := VI_Severity;
L_Last_RootCause := VI_RootCause;
// >>> BULK_SYNC_ANCHOR: FB_Fault_Logger <<<

IF NOT VI_Enable THEN
    GVL_Water_Topology_Validation.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Invalid := FALSE;
L_Any_Ambiguous := FALSE;
L_Any_Fallback := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Node := L_Empty_Node;
    L_Node.Runtime_Valid := TRUE;

    L_Node.Sensor_Id := TO_UINT(L_i);
    L_Node.Hydraulic_Zone_Id :=
        GVL_Water_Runtime_Projection.G_Leak_Runtime_State[L_i].Hydraulic_Zone_Id;

    L_Node.Valve_Group_Id :=
        GVL_Water_Runtime_Projection.G_Leak_Runtime_State[L_i].Valve_Group_Id;

    L_Node.Isolation_Group_Id :=
        L_Node.Valve_Group_Id;

    L_Node.Hydraulic_Segment_Id :=
        L_Node.Hydraulic_Zone_Id;

    L_Node.Fallback_Domain_Id := 1;

    // Validation.
    L_Node.Mapping_Valid :=
        L_Node.Valve_Group_Id <> 0;

    IF NOT L_Node.Mapping_Valid THEN
        L_Node.Global_Fallback_Required := TRUE;
        L_Node.Status_Code := 1;
        L_Node.Status_Text := 'Missing valve group';
    ELSE
        L_Node.Selective_Isolation_Allowed := TRUE;
        L_Node.Status_Code := 0;
        L_Node.Status_Text := 'Topology valid';
    END_IF;

    // Shared valve-group detection.
    IF L_Node.Valve_Group_Id = 3 THEN
        L_Node.Shared_Valve_Group := TRUE;
    END_IF;

    // Isolation group publication.
    L_Group := L_Empty_Group;
    L_Group.Runtime_Valid := TRUE;

    L_Group.Isolation_Group_Id :=
        L_Node.Isolation_Group_Id;

    L_Group.Valve_Group_Id :=
        L_Node.Valve_Group_Id;

    L_Group.Fallback_Domain_Id :=
        L_Node.Fallback_Domain_Id;

    L_Group.Shared_Sensor_Count :=
        SEL(L_Node.Shared_Valve_Group, 1, 2);

    L_Group.Isolation_Valid :=
        L_Node.Mapping_Valid;

    L_Group.Isolation_Ambiguous :=
        L_Node.Mapping_Ambiguous;

    L_Group.Selective_Isolation_Allowed :=
        L_Node.Selective_Isolation_Allowed;

    L_Group.Global_Fallback_Required :=
        L_Node.Global_Fallback_Required;

    // Validation publication.
    L_Validation := L_Empty_Validation;
    L_Validation.Runtime_Valid := TRUE;

    L_Validation.Runtime_System_Time_MS :=
        VI_System_Time_MS;

    L_Validation.Sensor_Id :=
        L_Node.Sensor_Id;

    L_Validation.Topology_Valid :=
        L_Node.Mapping_Valid;

    L_Validation.Topology_Ambiguous :=
        L_Node.Mapping_Ambiguous;

    L_Validation.Isolation_Path_Valid :=
        L_Group.Isolation_Valid;

    L_Validation.Shared_Valve_Group :=
        L_Node.Shared_Valve_Group;

    L_Validation.Missing_Valve_Group :=
        NOT L_Node.Mapping_Valid;

    L_Validation.Selective_Isolation_Allowed :=
        L_Node.Selective_Isolation_Allowed;

    L_Validation.Global_Fallback_Required :=
        L_Node.Global_Fallback_Required;

    IF L_Validation.Global_Fallback_Required THEN
        L_Validation.Status_Code := 1;
        L_Validation.Status_Text :=
            'Global fallback required';
    ELSE
        L_Validation.Status_Code := 0;
        L_Validation.Status_Text :=
            'Topology validation healthy';
    END_IF;

    GVL_Water_Hydraulic_Topology.G_Topology_Node[L_i] :=
        L_Node;

    GVL_Water_Hydraulic_Topology.G_Isolation_Group[L_i] :=
        L_Group;

    GVL_Water_Topology_Validation.G_Validation_State[L_i] :=
        L_Validation;

    L_Any_Invalid :=
        L_Any_Invalid
        OR NOT L_Validation.Topology_Valid;

    L_Any_Ambiguous :=
        L_Any_Ambiguous
        OR L_Validation.Topology_Ambiguous;

    L_Any_Fallback :=
        L_Any_Fallback
        OR L_Validation.Global_Fallback_Required;

END_FOR;

GVL_Water_Hydraulic_Topology.G_Any_Ambiguous :=
    L_Any_Ambiguous;

GVL_Water_Hydraulic_Topology.G_Any_Global_Fallback_Required :=
    L_Any_Fallback;

GVL_Water_Hydraulic_Topology.G_Runtime_Valid := TRUE;
GVL_Water_Hydraulic_Topology.G_Last_Update_MS := VI_System_Time_MS;

GVL_Water_Topology_Validation.G_Any_Invalid :=
    L_Any_Invalid;

GVL_Water_Topology_Validation.G_Any_Ambiguous :=
    L_Any_Ambiguous;

GVL_Water_Topology_Validation.G_Any_Global_Fallback_Required :=
    L_Any_Fallback;

GVL_Water_Topology_Validation.G_Runtime_Valid := TRUE;
GVL_Water_Topology_Validation.G_Last_Update_MS := VI_System_Time_MS;

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
    L_Last_Call_MS := VI_System_Time_MS;
    VO_Cycle_DT_MS := 0;
    VO_Watchdog_Fault := FALSE;
    VO_Alive := TRUE;
    RETURN;
END_IF;

// Measure real time gap between successive calls
L_DT_MS := (SEL(VI_System_Time_MS >= L_Last_Call_MS, VI_System_Time_MS - L_Last_Call_MS, (4294967295 - L_Last_Call_MS) + VI_System_Time_MS + 1));
VO_Cycle_DT_MS := L_DT_MS;

// Fault if the task/cycle resumed after an abnormal pause
VO_Watchdog_Fault := (L_DT_MS > VI_Timeout_MS);
VO_Alive := NOT VO_Watchdog_Fault;

// Store current timestamp for next cycle
L_Last_Call_MS := VI_System_Time_MS;
// >>> BULK_SYNC_ANCHOR: FB_Watchdog <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    VO_Socket_States[L_i] := FALSE;
    VO_Internal_States[L_i] := L_Internal_State[L_i];
END_FOR;

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        RETURN;
    END_IF;
END_FOR;

L_Restore_Trig(CLK := GVL_AWAY_RESTORE.G_Restore_Active AND GVL_AWAY_RESTORE.G_Snapshot_Valid);
IF L_Restore_Trig.Q AND NOT VI_Fire_Alarm AND NOT VI_Flood_Alarm THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
        L_Internal_State[L_i] := GVL_AWAY_RESTORE.G_Socket_States[L_i];
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Rule_Active := FALSE;
    L_Rule_State := FALSE;

    L_Manual_Trig[L_i](CLK := VI_Manual_Override[L_i]);

    IF L_Manual_Trig[L_i].Q THEN
        L_Internal_State[L_i] := NOT L_Internal_State[L_i];
    END_IF;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_SOCKET THEN
                L_Rule_Active := TRUE;
                L_Rule_State := (VI_Rule_Actions[L_j].Value > 0.5);
                L_Internal_State[L_i] := L_Rule_State;
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_SOCKET AND VI_Rule_Actions[L_j].Triggered THEN
                L_Internal_State[L_i] := NOT L_Internal_State[L_i];
            END_IF;
        END_IF;
    END_FOR;

    IF VI_Fire_Alarm OR VI_Flood_Alarm THEN
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSIF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY OR VI_Security_Armed THEN
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSE
        IF L_Rule_Active THEN
            VO_Socket_States[L_i] := L_Rule_State;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    END_IF;
END_FOR;

VO_Internal_States := L_Internal_State;

// >>> BULK_SYNC_ANCHOR: FB_Socket_Manager <<<

// Debounce non-critical diagnostics: require 3 stable cycles to assert/clear
IF VI_IO_Offline THEN
    L_IO_Fault_Clear_Count := 0;
    IF L_IO_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Assert_Count := L_IO_Fault_Assert_Count + 1;
    END_IF;
    IF L_IO_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_IO_Fault_Assert_Count := 0;
    IF L_IO_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Clear_Count := L_IO_Fault_Clear_Count + 1;
    END_IF;
    IF L_IO_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Comm_Fault THEN
    L_Comm_Fault_Clear_Count := 0;
    IF L_Comm_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Assert_Count := L_Comm_Fault_Assert_Count + 1;
    END_IF;
    IF L_Comm_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Comm_Fault_Assert_Count := 0;
    IF L_Comm_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Clear_Count := L_Comm_Fault_Clear_Count + 1;
    END_IF;
    IF L_Comm_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Sensor_Fault THEN
    L_Sensor_Fault_Clear_Count := 0;
    IF L_Sensor_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Assert_Count := L_Sensor_Fault_Assert_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Sensor_Fault_Assert_Count := 0;
    IF L_Sensor_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Clear_Count := L_Sensor_Fault_Clear_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Subsystem_Fault THEN
    L_Subsystem_Clear_Count := 0;
    IF L_Subsystem_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Assert_Count := L_Subsystem_Assert_Count + 1;
    END_IF;
    IF L_Subsystem_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Subsystem_Assert_Count := 0;
    IF L_Subsystem_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Clear_Count := L_Subsystem_Clear_Count + 1;
    END_IF;
    IF L_Subsystem_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := FALSE;
    END_IF;
END_IF;

// Count confirmed fault events on rising edge of stable/critical conditions
IF L_IO_Fault_Stable AND NOT L_IO_Fault_Prev THEN
    VO_IO_Fault_Count := VO_IO_Fault_Count + 1;
END_IF;
L_IO_Fault_Prev := L_IO_Fault_Stable;

IF L_Comm_Fault_Stable AND NOT L_Comm_Fault_Prev THEN
    VO_Comm_Fault_Count := VO_Comm_Fault_Count + 1;
END_IF;
L_Comm_Fault_Prev := L_Comm_Fault_Stable;

IF L_Sensor_Fault_Stable AND NOT L_Sensor_Fault_Prev THEN
    VO_Sensor_Fault_Count := VO_Sensor_Fault_Count + 1;
END_IF;
L_Sensor_Fault_Prev := L_Sensor_Fault_Stable;

IF L_Subsystem_Fault_Stable AND NOT L_Subsystem_Fault_Prev THEN
    VO_Subsystem_Fault_Count := VO_Subsystem_Fault_Count + 1;
END_IF;
L_Subsystem_Fault_Prev := L_Subsystem_Fault_Stable;

IF VI_Watchdog_Fault AND NOT L_Watchdog_Fault_Prev THEN
    VO_Watchdog_Fault_Count := VO_Watchdog_Fault_Count + 1;
END_IF;
L_Watchdog_Fault_Prev := VI_Watchdog_Fault;

VO_Sensor_Fault := L_Sensor_Fault_Stable;
VO_IO_Fault := L_IO_Fault_Stable;
VO_Comm_Fault := L_Comm_Fault_Stable;
VO_Subsystem_Degraded := L_Subsystem_Fault_Stable;

VO_System_Severity := E_System_Severity.SEV_NORMAL;
VO_Root_Cause := E_System_Root_Cause.ROOT_NONE;
VO_First_Fault_Active := FALSE;
VO_First_Fault_Type := 0;
VO_First_Fault_Source := 0;

// Priority: FIRE > GAS > CO > WATER > diagnostics
IF VI_Smoke_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_FIRE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 5;

ELSIF VI_Gas_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_GAS_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 6;

ELSIF VI_CO_Alarm_Level THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_CRITICAL;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_CO_Warning_Level THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_WARNING;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_Leak_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATER_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 8;

ELSIF VI_Watchdog_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATCHDOG_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 9;

ELSIF L_IO_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_IO_OFFLINE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 1;

ELSIF L_Comm_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_COMM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 3;

ELSIF L_Sensor_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SENSOR_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 2;

ELSIF L_Subsystem_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 4;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Health <<<

IF NOT VI_IsActivePLC THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        VO_Actions[L_i].Active := FALSE;
        VO_Actions[L_i].Triggered := FALSE;
        VO_Actions[L_i].Action_Type := E_Rule_Action_Type.ACTION_NONE;
        VO_Actions[L_i].Target_ID := 0;
        VO_Actions[L_i].Value := 0.0;
    END_FOR;
    VO_Preheat_Request := FALSE;
    RETURN;
END_IF;

VO_Preheat_Request := FALSE;

L_Elapsed_Time := SEL(VI_System_Time_MS >= L_Last_Reset_Time, VI_System_Time_MS - L_Last_Reset_Time, (4294967295 - L_Last_Reset_Time) + VI_System_Time_MS + 1);

IF L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_MINUTE THEN
    L_Last_Reset_Time := VI_System_Time_MS;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        L_Trigger_Count[L_i] := 0;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO

    // Full per-cycle action reset prevents stale Triggered/Action_Type/Target_ID/Value
    // from being observed by any downstream consumer when a rule is disabled or inactive.
    VO_Actions[L_i].Active := FALSE;
    VO_Actions[L_i].Triggered := FALSE;
    VO_Actions[L_i].Action_Type := E_Rule_Action_Type.ACTION_NONE;
    VO_Actions[L_i].Target_ID := 0;
    VO_Actions[L_i].Value := 0.0;

    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;
        L_Current_Value := 0.0;

        IF VI_Rules[L_i].Condition_Target_ID > 0 THEN
            CASE VI_Rules[L_i].Condition_Type OF
                E_Rule_Condition_Type.COND_AIR_TEMP:
                    IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := VI_Indoor_Temps[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOR_TEMP:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN
                        L_Current_Value := VI_Floor_Temps[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_HUMIDITY:
                    IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := VI_Humidities[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_CO2:
                    IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := VI_CO2_Levels[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_MOTION:
                    IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := SEL(VI_Motion_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_DOOR_WINDOW:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS THEN
                        L_Current_Value := SEL(VI_Door_Sensors[VI_Rules[L_i].Condition_Target_ID] OR VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    ELSIF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := SEL(VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOD:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS THEN
                        L_Current_Value := SEL(VI_Water_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_SMOKE:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_SMOKE_SENSORS THEN
                        L_Current_Value := SEL(VI_Smoke_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_METHANE:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_METHANE_SENSORS THEN
                        L_Current_Value := VI_Methane_Sensors[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_CO:
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CO_SENSORS THEN
                        L_Current_Value := VI_CO_Sensors[VI_Rules[L_i].Condition_Target_ID];
                    END_IF;
                E_Rule_Condition_Type.COND_TIME_OF_DAY:
                    L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
                E_Rule_Condition_Type.COND_DAY_OF_WEEK:
                    L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_CASE;
        ELSE
            IF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_TIME_OF_DAY THEN
                L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
            ELSIF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_DAY_OF_WEEK THEN
                L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_IF;
        END_IF;

        CASE VI_Rules[L_i].Condition_Op OF
            E_Rule_Comparison.COMP_GT:
                L_Condition_Met := (L_Current_Value > VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LT:
                L_Condition_Met := (L_Current_Value < VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_EQ:
                L_Condition_Met := (ABS(L_Current_Value - VI_Rules[L_i].Condition_Value) < 0.1);
            E_Rule_Comparison.COMP_GE:
                L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LE:
                L_Condition_Met := (L_Current_Value <= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_IN_RANGE:
                L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value) AND (L_Current_Value <= VI_Rules[L_i].Condition_Value_Max);
            E_Rule_Comparison.COMP_TRUE:
                L_Condition_Met := (L_Current_Value > 0.5);
            E_Rule_Comparison.COMP_FALSE:
                L_Condition_Met := (L_Current_Value < 0.5);
        END_CASE;

        L_Triggers[L_i](CLK := L_Condition_Met);

        IF L_Triggers[L_i].Q THEN
            L_Trigger_Count[L_i] := L_Trigger_Count[L_i] + 1;
            IF L_Trigger_Count[L_i] > 10 THEN
                CONTINUE;
            END_IF;
        END_IF;

        IF L_Condition_Met AND (L_Trigger_Count[L_i] <= 10) THEN
            VO_Actions[L_i].Active := TRUE;
            VO_Actions[L_i].Triggered := L_Triggers[L_i].Q;
            VO_Actions[L_i].Action_Type := VI_Rules[L_i].Action_Type;
            VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
            VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;

            // Bridge rule-driven heating intent to policy. Per-circuit valve
            // projection remains owned by FB_Heating_Circuit_Control.
            IF (VI_Rules[L_i].Action_Type = E_Rule_Action_Type.ACTION_SET_FLOOR_HEATING) AND
               (VI_Rules[L_i].Action_Value > REAL#0.5) THEN
                VO_Preheat_Request := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Rule_Engine <<<

// ==============================================================================
// Heating runtime service gating phase
// Applies service/out-of-service and freeze hardware gating to computed outputs.
// Does NOT calculate heating demand and does NOT publish final state.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service := NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service;
GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service := NOT GVL_CONFIG.G_Electric_Heater_In_Service;

IF NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service THEN
    VIO_Backup_Circulation_Pump := FALSE;
END_IF;

IF NOT GVL_CONFIG.G_Electric_Heater_In_Service THEN
    VIO_Electric_Heater_Enable := FALSE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] := NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];
    IF NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i] THEN
        VIO_Manifold_Pumps[L_i] := FALSE;
    END_IF;
END_FOR;

GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service;
IF NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service THEN
    VIO_DHW_Heating_Pump := FALSE;
    VIO_DHW_Status.Heating_Pump_On := FALSE;
END_IF;

GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service;
IF NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service THEN
    VIO_DHW_Circ_Pump := FALSE;
    VIO_DHW_Status.Circ_Pump_On := FALSE;
END_IF;

GVL_STATE.G_Freeze_Hardware_Degraded := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault OR GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;
GVL_STATE.G_Freeze_Hardware_Failed := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault AND GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;

IF GVL_STATE.G_Freeze_Hardware_Failed THEN
    VIO_Backup_Circulation_Pump := FALSE;
    VIO_Electric_Heater_Enable := FALSE;
    VIO_Freeze_Risk_Status := TRUE;
END_IF;

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Service_Gating_Phase <<<

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_TX_Index := UDINT_TO_UINT(GVL_Runtime_Bus.G_Last_Sequence_Id);

IF (L_TX_Index >= 1)
   AND (L_TX_Index <= 128) THEN

    L_Frame := GVL_Runtime_Bus.G_TX_Frames[L_TX_Index];

    IF L_Frame.Frame_Valid THEN

        IF GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK
           AND NOT GVL_Runtime_Discovery.G_Any_Node_Quarantined THEN

            L_Frame.Frame_Ack_Received := TRUE;
            L_Frame.Replication_Consistent := TRUE;
            L_Frame.Status_Code := 0;

        ELSE

            L_Frame.Replication_Rejected := TRUE;
            L_Frame.Status_Code := 2;

        END_IF;

        GVL_Runtime_Bus.G_TX_Frames[L_TX_Index] := L_Frame;

    END_IF;

END_IF;

// ======================================================
// MODBUS RTU SYSCOM BACKEND
// ======================================================
// Industrial transport runtime:
//   - serial open/configure
//   - RX assembler
//   - CRC validation
//   - watchdog supervision
//   - reconnect supervision
// ======================================================

IF NOT VI_Enable THEN

    IF L_Handle <> 16#FFFFFFFF THEN
        SysCom.SysComClose(hCom := L_Handle);
        L_Handle := 16#FFFFFFFF;
    END_IF;

    L_Open_Done := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
        MB_SYSCOM_CLOSED;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_IDLE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

    RETURN;
END_IF;

// ======================================================
// WATCHDOGS
// ======================================================
GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Watchdog_Timeout := FALSE;
GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Watchdog_Timeout := FALSE;
GVL_MODBUS_SYSCOM_TRANSPORT.G_Bus_Silent := FALSE;

IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Request_MS) >
        (GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS * 2) THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Watchdog_Timeout := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX_Watchdog :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX_Watchdog + 1;

    END_IF;

END_IF;

IF GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS) > 30000 THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Watchdog_Timeout := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Watchdog :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Watchdog + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Bus_Silent := TRUE;

    END_IF;

END_IF;

// ======================================================
// RECONNECT WAIT STATE
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State =
   MB_SYSCOM_RECONNECT_WAIT THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Last_Error_MS) >=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Delay_MS THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_OPENING;

    ELSE

        RETURN;

    END_IF;

END_IF;

// ======================================================
// OPEN + CONFIGURE
// ======================================================
IF NOT L_Open_Done THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
        MB_SYSCOM_OPENING;

    L_Baudrate := GVL_CONFIG.G_Modbus_RTU_Baudrate;

    IF L_Baudrate <= 9600 THEN
        L_Interframe_MS := 5;
    ELSIF L_Baudrate <= 19200 THEN
        L_Interframe_MS := 3;
    ELSE
        L_Interframe_MS := 2;
    END_IF;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_InterFrame_MS :=
        L_Interframe_MS;

    CASE GVL_CONFIG.G_Modbus_RTU_Port_Number OF
        1:
            L_Settings.sPort := SysCom.SYS_COMPORT1;
        2:
            L_Settings.sPort := SysCom.SYS_COMPORT2;
        3:
            L_Settings.sPort := SysCom.SYS_COMPORT3;
        4:
            L_Settings.sPort := SysCom.SYS_COMPORT4;
    ELSE
        L_Settings.sPort := SysCom.SYS_COMPORT1;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Baudrate OF
        4800:
            L_Settings.ulBaudrate := SysCom.SYS_BR_4800;
        9600:
            L_Settings.ulBaudrate := SysCom.SYS_BR_9600;
        19200:
            L_Settings.ulBaudrate := SysCom.SYS_BR_19200;
        38400:
            L_Settings.ulBaudrate := SysCom.SYS_BR_38400;
        57600:
            L_Settings.ulBaudrate := SysCom.SYS_BR_57600;
        115200:
            L_Settings.ulBaudrate := SysCom.SYS_BR_115200;
    ELSE
        L_Settings.ulBaudrate := SysCom.SYS_BR_9600;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Parity OF
        0:
            L_Settings.byParity := SysCom.SYS_NOPARITY;
        1:
            L_Settings.byParity := SysCom.SYS_EVENPARITY;
        2:
            L_Settings.byParity := SysCom.SYS_ODDPARITY;
    ELSE
        L_Settings.byParity := SysCom.SYS_EVENPARITY;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Stop_Bits OF
        1:
            L_Settings.byStopBits := SysCom.SYS_ONESTOPBIT;
        2:
            L_Settings.byStopBits := SysCom.SYS_TWOSTOPBITS;
    ELSE
        L_Settings.byStopBits := SysCom.SYS_ONESTOPBIT;
    END_CASE;

    L_Settings.ulTimeout := GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS;
    L_Settings.ulBufferSize := 512;

    IF GVL_CONFIG.G_Modbus_RTU_Data_Bits < 7 THEN
        L_SettingsEx2.byByteSize := 8;
    ELSIF GVL_CONFIG.G_Modbus_RTU_Data_Bits > 8 THEN
        L_SettingsEx2.byByteSize := 8;
    ELSE
        L_SettingsEx2.byByteSize := GVL_CONFIG.G_Modbus_RTU_Data_Bits;
    END_IF;

    L_SettingsEx2.bBinary := TRUE;
    L_SettingsEx2.bOutxCtsFlow := FALSE;
    L_SettingsEx2.bOutxDsrFlow := FALSE;
    L_SettingsEx2.byDtrControl := 0;
    L_SettingsEx2.bDsrSensitivity := FALSE;
    L_SettingsEx2.byRtsControl := 0;
    L_SettingsEx2.bTXContinueOnXoff := FALSE;
    L_SettingsEx2.bOutX := FALSE;
    L_SettingsEx2.bInX := FALSE;
    L_SettingsEx2.byXonChar := 0;
    L_SettingsEx2.byXoffChar := 0;
    L_SettingsEx2.wXonLim := 0;
    L_SettingsEx2.wXoffLim := 0;

    L_Handle := SysCom.SysComOpen3(
        pSettings := ADR(L_Settings),
        pSettingsEx2 := ADR(L_SettingsEx2),
        pResult := ADR(L_Result)
    );

    IF L_Handle <> 16#FFFFFFFF THEN

        SysCom.SysComPurge(hCom := L_Handle);

        L_Open_Done := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := TRUE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_ONLINE;

    ELSE

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := FALSE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := FALSE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_RECONNECT_WAIT;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Last_Error_MS :=
            VI_System_Time_MS;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Attempts :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Attempts + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Reconnects :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Reconnects + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors + 1;

    END_IF;

    RETURN;
END_IF;

GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
    MB_SYSCOM_ONLINE;

// ======================================================
// TX WRITE
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done THEN

    L_Bytes_Written := SysCom.SysComWrite(
        hCom := L_Handle,
        pbyBuffer := ADR(GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Buffer),
        ulSize := GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length,
        ulTimeout := GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS,
        pResult := ADR(L_Result)
    );

    IF L_Bytes_Written = GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := TRUE;

    ELSE

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_ERROR;

    END_IF;

END_IF;

// ======================================================
// RX STREAM READ
// ======================================================
L_Bytes_Read := SysCom.SysComRead(
    hCom := L_Handle,
    pbyBuffer := ADR(L_RX_Buffer),
    ulSize := 256,
    ulTimeout := SysCom.SYS_NOWAIT,
    pResult := ADR(L_Result)
);

IF L_Bytes_Read > 0 THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_RECEIVING;

    IF L_Bytes_Read > 256 THEN
        L_Read_Count := 256;
    ELSE
        L_Read_Count := UDINT_TO_INT(L_Bytes_Read);
    END_IF;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Last_Byte_MS :=
        VI_System_Time_MS;

    FOR L_i := 0 TO (L_Read_Count - 1) DO

        L_Target_Index :=
            UINT_TO_INT(GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length);

        IF L_Target_Index >= 256 THEN

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                MB_RTU_RX_OVERFLOW;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Overflow := TRUE;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Overflow :=
                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Overflow + 1;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

            EXIT;

        END_IF;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Target_Index] :=
            L_RX_Buffer[L_i];

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length + 1;

    END_FOR;

END_IF;

// ======================================================
// INTER-FRAME FINALIZATION
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Last_Byte_MS) >=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_InterFrame_MS THEN

        L_Frame_Length :=
            UINT_TO_INT(GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length);

        IF L_Frame_Length >= 4 THEN

            L_CRC := 16#FFFF;

            FOR L_i := 0 TO (L_Frame_Length - 3) DO

                L_CRC := L_CRC XOR
                    BYTE_TO_WORD(
                        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_i]
                    );

                FOR L_j := 0 TO 7 DO

                    IF (L_CRC AND 16#0001) <> 0 THEN
                        L_CRC := SHR(L_CRC, 1);
                        L_CRC := L_CRC XOR 16#A001;
                    ELSE
                        L_CRC := SHR(L_CRC, 1);
                    END_IF;

                END_FOR;

            END_FOR;

            L_CRC_Frame :=
                BYTE_TO_WORD(
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Frame_Length - 2]
                );

            L_CRC_Frame :=
                L_CRC_Frame OR
                SHL(
                    BYTE_TO_WORD(
                        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Frame_Length - 1]
                    ),
                    8
                );

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_Calc :=
                L_CRC;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_Frame :=
                L_CRC_Frame;

            IF L_CRC = L_CRC_Frame THEN

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                    MB_RTU_RX_FRAME_READY;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_OK := TRUE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Length :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := TRUE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX + 1;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS :=
                    VI_System_Time_MS;

            ELSE

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                    MB_RTU_RX_CRC_ERROR;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_OK := FALSE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_CRC_Error :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_CRC_Error + 1;

            END_IF;

        ELSE

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                MB_RTU_RX_SHORT_FRAME;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Short_Frame :=
                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Short_Frame + 1;

        END_IF;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

    END_IF;

END_IF;

IF NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready AND
   (GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State = MB_RTU_RX_FRAME_READY) THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_IDLE;

END_IF;

// ======================================================
// MODBUS RESPONSE APPLY LAYER
// ======================================================
// Transfers validated parser result into bridge/master response.
//
// Safety principles:
//   - Only validated parser result may produce Done.
//   - Parser error produces Error response.
//   - No synthetic successful response.
// ======================================================

VO_Response_Applied := FALSE;

IF NOT VI_Request_Valid THEN
    RETURN;
END_IF;

IF (VI_Request_Index < 1) OR (VI_Request_Index > 16) THEN
    RETURN;
END_IF;

// ======================================================
// PARSER ERROR
// ======================================================
IF VI_Parser_Error THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := VI_Parser_Error_Code;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence := VI_Request_Sequence;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS := VI_System_Time_MS;

    VO_Response_Applied := TRUE;

    RETURN;
END_IF;

// ======================================================
// VALID PARSED RESPONSE
// ======================================================
IF VI_Parser_Valid THEN

    FOR L_i := 1 TO 32 DO
        GVL_MODBUS_RTU_BRIDGE.G_Response_Value[L_i] := 0;
    END_FOR;

    L_Count := UINT_TO_INT(VI_Register_Count);

    IF L_Count > 32 THEN
        L_Count := 32;
    END_IF;

    FOR L_i := 1 TO L_Count DO
        GVL_MODBUS_RTU_BRIDGE.G_Response_Value[L_i] :=
            VI_Register_Value[L_i];
    END_FOR;

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence := VI_Request_Sequence;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS := VI_System_Time_MS;

    VO_Response_Applied := TRUE;

END_IF;

// Reset all retained FB outputs on every call.
// Safe-state FB instances keep VAR_OUTPUT values between scans unless overwritten.
VO_Applied := FALSE;
VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    VO_Zone_Valves[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Pumps[L_i] := FALSE;
    VO_Manifold_Valves[L_i] := REAL#0.0;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_OT_Enable[L_i] := FALSE;
    VO_Boiler_OT_Setpoint[L_i] := REAL#0.0;
    VO_Boiler_Status[L_i] := L_Empty_Boiler_Status;
END_FOR;

VO_Applied := VI_Block_Normal_Heating;

L_Freeze_Circulation_Required := VI_Freeze_Active AND (VI_IO_Failsafe_Active OR VI_Gas_Safety_Active);

IF NOT VI_Block_Normal_Heating THEN
    RETURN;
END_IF;

// =============================
// ZONE VALVES (FIXED)
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF L_Freeze_Circulation_Required THEN
        VO_Zone_Valves[L_i] := TRUE;
    ELSE
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;
END_FOR;

// =============================
// MANIFOLD CONTROL
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF L_Freeze_Circulation_Required THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        VO_Manifold_Valves[L_i] := REAL#35.0;
    ELSE
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := REAL#0.0;
    END_IF;
END_FOR;

// =============================
// BOILERS OFF
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_OT_Enable[L_i] := FALSE;
    VO_Boiler_OT_Setpoint[L_i] := REAL#0.0;
    VO_Boiler_Status[L_i].Warning := FALSE;
    VO_Boiler_Status[L_i].Error := TRUE;
END_FOR;

// =============================
// FREEZE PROTECTION LOGIC
// =============================
IF VI_Gas_Safety_Active AND VI_Freeze_Active THEN
    VO_Backup_Circulation_Pump := TRUE;

    L_Min_Supply_Temp := REAL#1000.0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Temps_Supply[L_i] < L_Min_Supply_Temp THEN
            L_Min_Supply_Temp := VI_Manifold_Temps_Supply[L_i];
        END_IF;
    END_FOR;

    IF L_Min_Supply_Temp > REAL#900.0 THEN
        L_Min_Supply_Temp := REAL#0.0;
    END_IF;

    IF L_Min_Supply_Temp < (VI_Freeze_Target_Supply - REAL#1.0) THEN
        VO_Electric_Heater_Enable := TRUE;
    ELSIF L_Min_Supply_Temp > (VI_Freeze_Target_Supply + REAL#1.0) THEN
        VO_Electric_Heater_Enable := FALSE;
    END_IF;

    VO_Freeze_Risk_Status := TRUE;
END_IF;

// =============================
// IO FAILSAFE + FREEZE
// =============================
IF VI_IO_Failsafe_Active AND VI_Freeze_Active THEN
    IF VI_Boiler_OT_Online[1] AND NOT VI_Boiler_Error_Status[1] THEN
        VO_Boiler_OT_Enable[1] := TRUE;
        VO_Boiler_OT_Setpoint[1] := VI_Freeze_Target_Supply;
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Safe_State <<<

// ==============================================================================
// Heating runtime root-cause correlator
// Read-only runtime causality correlation layer.
// ==============================================================================



VO_Node.Node_Active := FALSE;
VO_Node.Root_Cause_Candidate := FALSE;
VO_Node.Runtime_Degraded := FALSE;
VO_Node.Runtime_Fault := FALSE;

VO_Node.Cascade_Degraded := FALSE;
VO_Node.Cascade_Boiler_Loss := FALSE;

VO_Node.OpenTherm_Degraded := FALSE;
VO_Node.OpenTherm_Command_Invalid := FALSE;

VO_Node.Diagnostics_Degraded := FALSE;
VO_Node.Explainability_Degraded := FALSE;

VO_Node.Sequencing_Invalid := FALSE;
VO_Node.Ownership_Invalid := FALSE;
VO_Node.Synchronization_Invalid := FALSE;

VO_Node.Severity_Level := 0;

VO_Node.Status_Code := 0;
VO_Node.Status_Text := 'Heating runtime root-cause correlator disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

VO_Node.Node_Active := VI_Anomaly.Anomaly_Active;

VO_Node.Runtime_Degraded := VI_Anomaly.Runtime_Degraded;
VO_Node.Runtime_Fault :=
    VI_Anomaly.Critical_Anomaly;

VO_Node.Cascade_Degraded :=
    VI_Anomaly.Cascade_Degraded;

VO_Node.Cascade_Boiler_Loss :=
    VI_Anomaly.Cascade_Boiler_Loss_Detected;

VO_Node.OpenTherm_Degraded :=
    VI_Anomaly.OpenTherm_Transport_Degraded;

VO_Node.OpenTherm_Command_Invalid :=
    VI_Anomaly.OpenTherm_Command_Invalid;

VO_Node.Diagnostics_Degraded :=
    VI_Anomaly.Diagnostics_Degraded;

VO_Node.Explainability_Degraded :=
    VI_Anomaly.Explainability_Degraded;

VO_Node.Sequencing_Invalid :=
    VI_Anomaly.Sequencing_Invalid;

VO_Node.Ownership_Invalid :=
    VI_Anomaly.Ownership_Invalid;

VO_Node.Synchronization_Invalid :=
    VI_Anomaly.Synchronization_Invalid;

VO_Node.Severity_Level :=
    VI_Anomaly.Severity_Level;

VO_Node.Root_Cause_Candidate :=
    VI_Anomaly.Critical_Anomaly OR
    VI_Anomaly.Sequencing_Invalid OR
    VI_Anomaly.Ownership_Invalid OR
    VI_Anomaly.Synchronization_Invalid;

IF VO_Node.Root_Cause_Candidate THEN
    VO_Node.Status_Code := 900;
    VO_Node.Status_Text := 'Heating runtime root-cause candidate detected';
ELSE
    VO_Node.Status_Code := 1;
    VO_Node.Status_Text := 'Heating runtime causality nominal';
END_IF;

