    VI_Node.OpenTherm_Command_Invalid;

VO_Event.Sequencing_Invalid :=
    VI_Node.Sequencing_Invalid;

VO_Event.Ownership_Invalid :=
    VI_Node.Ownership_Invalid;

VO_Event.Synchronization_Invalid :=
    VI_Node.Synchronization_Invalid;

VO_Event.Root_Cause_Candidate :=
    VI_Node.Root_Cause_Candidate;

VO_Event.Critical_Path :=
    VI_Edge.Critical_Path;

// ======================================================
// STATUS
// ======================================================
IF VO_Event.Root_Cause_Candidate THEN
    VO_Event.Status_Code := 900;
    VO_Event.Status_Text := 'Heating runtime root-cause reconstructed';
ELSE
    VO_Event.Status_Code := 1;
    VO_Event.Status_Text := 'Heating runtime event reconstructed';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Event_Reconstruction_Engine <<<

IF NOT VI_Enable THEN
    GVL_Config_Activation.G_Activation_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_State.Runtime_Valid := TRUE;
L_State.Runtime_System_Time_MS := VI_System_Time_MS;

L_State.Active_Version :=
    GVL_Water_Topology_Config.G_Active_Config_Version;

L_State.Staged_Version :=
    GVL_Config_Activation.G_Staged_Config_Version;

L_State.Previous_Stable_Version :=
    GVL_Config_Activation.G_Last_Stable_Config_Version;

L_State.Activation_Requested :=
    GVL_Config_Activation.G_Activation_Request;

L_State.Rollback_Requested :=
    GVL_Config_Activation.G_Rollback_Request;

L_State.Rollback_Available :=
    GVL_Config_Activation.G_Last_Stable_Config_Version <> 0;

L_Staged_Valid := TRUE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    IF GVL_Config_Activation.G_Staged_Topology_Config[L_i].Primary_Valve_Group_Id = 0 THEN
        L_Staged_Valid := FALSE;
    END_IF;

END_FOR;

L_State.Staged_Config_Valid := L_Staged_Valid;
L_State.Migration_Compatible := TRUE;

IF L_State.Rollback_Requested THEN

    IF L_State.Rollback_Available THEN

        L_State.Rollback_Active := TRUE;
        L_State.Activation_Blocked := TRUE;

        GVL_Config_Activation.G_Config_Quarantine_Active := FALSE;

        L_State.Status_Code := 3;
        L_State.Status_Text := 'Rollback activation active';

    ELSE

        L_State.Rollback_Active := FALSE;
        L_State.Activation_Blocked := TRUE;

        L_State.Status_Code := 4;
        L_State.Status_Text := 'Rollback rejected: no stable version';

    END_IF;

    GVL_Config_Activation.G_Rollback_Request := FALSE;

ELSIF L_State.Activation_Requested THEN

    IF NOT L_State.Staged_Config_Valid THEN

        L_State.Activation_Blocked := TRUE;
        L_State.Config_Quarantine_Active := TRUE;

        GVL_Config_Activation.G_Config_Quarantine_Active := TRUE;

        L_State.Status_Code := 2;
        L_State.Status_Text := 'Config activation quarantined';

    ELSE

        L_State.Activation_Allowed := TRUE;

        GVL_Water_Topology_Config_Source.G_Source_Version :=
            L_State.Staged_Version;

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

            GVL_Water_Topology_Config_Source.G_Source_Record[L_i] :=
                GVL_Config_Activation.G_Staged_Topology_Config[L_i];

        END_FOR;

        GVL_Water_Topology_Config_Source.G_Source_Valid := TRUE;
        GVL_Water_Topology_Config_Source.G_Source_Activated_MS := VI_System_Time_MS;

        GVL_Config_Activation.G_Last_Stable_Config_Version :=
            L_State.Staged_Version;

        GVL_Config_Activation.G_Config_Quarantine_Active := FALSE;

        L_State.Status_Code := 1;
        L_State.Status_Text := 'Config activation completed';

    END_IF;

    GVL_Config_Activation.G_Activation_Request := FALSE;

ELSE

    L_State.Status_Code := 0;
    L_State.Status_Text := 'Config activation runtime healthy';

END_IF;

GVL_Config_Activation.G_Activation_State := L_State;

GVL_Config_Activation.G_Activation_Runtime_Valid := TRUE;
GVL_Config_Activation.G_Last_Update_MS := VI_System_Time_MS;
GVL_Config_Activation.G_Status_Code := L_State.Status_Code;
GVL_Config_Activation.G_Status_Text := L_State.Status_Text;

IF VI_Reset THEN
    VO_Output := FALSE;
    VO_Active := FALSE;
    L_Prev_Command := VI_Command;
    L_Start_MS := VI_Now_MS;
    RETURN;
END_IF;

IF VI_Command AND NOT L_Prev_Command THEN
    VO_Active := TRUE;
    L_Start_MS := VI_Now_MS;
END_IF;

VO_Output := FALSE;

IF VO_Active THEN
    IF VI_Now_MS >= L_Start_MS THEN
        L_Elapsed_MS := VI_Now_MS - L_Start_MS;
    ELSE
        L_Elapsed_MS := (4294967295 - L_Start_MS) + VI_Now_MS + 1;
    END_IF;

    IF L_Elapsed_MS < VI_Pulse_MS THEN
        VO_Output := TRUE;
    ELSE
        VO_Active := FALSE;
    END_IF;
END_IF;

L_Prev_Command := VI_Command;

// >>> BULK_SYNC_ANCHOR: FB_Access_Pulse_Channel <<<

IF NOT VI_Enable THEN
    GVL_Water_Recovery_Runtime.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Denied := FALSE;
L_Any_Unsafe := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    L_Feedback := GVL_Water_Valve_Feedback.G_Valve_Feedback_State[L_i];

    L_State.Runtime_Valid := FALSE;
    L_State.Runtime_System_Time_MS := 0;
    L_State.Recovery_Requested := FALSE;
    L_State.Recovery_Allowed := FALSE;
    L_State.Recovery_Denied := FALSE;
    L_State.Observation_Window_Active := FALSE;
    L_State.Unsafe_Recovery_Detected := FALSE;
    L_State.Valve_Degraded := FALSE;
    L_State.Confirmation_Healthy := FALSE;
    L_State.Recovery_Target_Valid := FALSE;
    L_State.Status_Code := 0;
    L_State.Status_Text := '';

    L_State.Runtime_Valid := TRUE;
    L_State.Runtime_System_Time_MS := VI_System_Time_MS;
    L_State.Recovery_Requested := GVL_INTENT_SAFETY.I_Water_Selective_Recovery_Allowed;
    L_State.Valve_Degraded := L_Feedback.Valve_Degraded;
    L_State.Confirmation_Healthy := NOT L_Feedback.Feedback_Conflict;
    L_State.Recovery_Target_Valid := L_Feedback.Valve_Group_Id <> 0;

    IF NOT L_State.Recovery_Requested THEN
        L_State.Status_Code := 0;
        L_State.Status_Text := 'Recovery observe only';
    ELSIF NOT L_State.Recovery_Target_Valid THEN
        L_State.Recovery_Denied := TRUE;
        L_State.Status_Code := 1;
        L_State.Status_Text := 'Recovery target invalid';
    ELSIF L_State.Valve_Degraded THEN
        L_State.Recovery_Denied := TRUE;
        L_State.Unsafe_Recovery_Detected := TRUE;
        L_State.Status_Code := 2;
        L_State.Status_Text := 'Recovery blocked by valve state';
    ELSIF NOT L_State.Confirmation_Healthy THEN
        L_State.Recovery_Denied := TRUE;
        L_State.Status_Code := 3;
        L_State.Status_Text := 'Recovery blocked by confirmation state';
    ELSE
        L_State.Recovery_Allowed := TRUE;
        L_State.Observation_Window_Active := TRUE;
        L_State.Status_Code := 0;
        L_State.Status_Text := 'Recovery governance healthy';
    END_IF;

    GVL_Water_Recovery_Runtime.G_Recovery_State[L_i] := L_State;
    L_Any_Denied := L_Any_Denied OR L_State.Recovery_Denied;
    L_Any_Unsafe := L_Any_Unsafe OR L_State.Unsafe_Recovery_Detected;
END_FOR;

GVL_Water_Recovery_Runtime.G_Any_Recovery_Denied := L_Any_Denied;
GVL_Water_Recovery_Runtime.G_Any_Unsafe_Recovery := L_Any_Unsafe;
GVL_Water_Recovery_Runtime.G_Runtime_Valid := TRUE;
GVL_Water_Recovery_Runtime.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Unsafe THEN
    GVL_Water_Recovery_Runtime.G_Status_Code := 2;
    GVL_Water_Recovery_Runtime.G_Status_Text := 'Recovery risk detected';
ELSIF L_Any_Denied THEN
    GVL_Water_Recovery_Runtime.G_Status_Code := 1;
    GVL_Water_Recovery_Runtime.G_Status_Text := 'Recovery governance denied';
ELSIF GVL_INTENT_SAFETY.I_Water_Selective_Recovery_Allowed THEN
    GVL_Water_Recovery_Runtime.G_Status_Code := 0;
    GVL_Water_Recovery_Runtime.G_Status_Text := 'Recovery governance healthy';
ELSE
    GVL_Water_Recovery_Runtime.G_Status_Code := 0;
    GVL_Water_Recovery_Runtime.G_Status_Text := 'Recovery observe only';
END_IF;

IF NOT VI_Enable THEN
    GVL_Predictive_Diagnostics.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_State := GVL_Predictive_Diagnostics.G_Diagnostics_State[L_i];

    L_Feedback :=
        GVL_Water_Valve_Feedback.G_Valve_Feedback_State[L_i];

    L_Recovery :=
        GVL_Water_Recovery_Runtime.G_Recovery_State[L_i];

    L_State.Runtime_Valid := TRUE;
    L_State.Runtime_System_Time_MS := VI_System_Time_MS;

    L_State.Device_Id := TO_UINT(L_i);
    L_State.Valve_Group_Id := L_Feedback.Valve_Group_Id;

    IF L_Feedback.Feedback_Timeout THEN
        L_State.Timeout_Count := L_State.Timeout_Count + 1;
    END_IF;

    IF L_Feedback.Feedback_Conflict THEN
        L_State.Conflict_Count := L_State.Conflict_Count + 1;
    END_IF;

    IF L_Recovery.Recovery_Denied THEN
        L_State.Recovery_Denied_Count :=
            L_State.Recovery_Denied_Count + 1;
    END_IF;

    L_State.Failure_Count :=
        L_State.Timeout_Count
        + L_State.Conflict_Count
        + L_State.Recovery_Denied_Count;

    // Predictive accumulation model foundation.
    L_State.Wear_Score :=
        TO_REAL(L_State.Failure_Count) * 0.1;

    L_State.Reliability_Score :=
        100.0 - L_State.Wear_Score;

    IF L_State.Reliability_Score < 0.0 THEN
        L_State.Reliability_Score := 0.0;
    END_IF;

    IF L_State.Failure_Count >= 3 THEN

        L_State.Degradation_Accumulating := TRUE;
        L_State.Service_Recommended := TRUE;

    END_IF;

    IF L_State.Failure_Count >= 10 THEN

        L_State.Service_Urgent := TRUE;
        L_State.Predictive_Quarantine_Recommended := TRUE;

    END_IF;

    IF L_State.Conflict_Count >= 2 THEN
        L_State.Intermittent_Fault_Suspected := TRUE;
    END_IF;

    IF L_State.Service_Urgent THEN

        L_State.Status_Code := 2;
        L_State.Status_Text :=
            'Urgent predictive maintenance required';

    ELSIF L_State.Service_Recommended THEN

        L_State.Status_Code := 1;
        L_State.Status_Text :=
            'Predictive maintenance recommended';

    ELSE

        L_State.Status_Code := 0;
        L_State.Status_Text :=
            'Predictive diagnostics healthy';

    END_IF;

    GVL_Predictive_Diagnostics.G_Diagnostics_State[L_i] :=
        L_State;

    L_Any_Degrading :=
        L_Any_Degrading
        OR L_State.Degradation_Accumulating;

    L_Any_Service :=
        L_Any_Service
        OR L_State.Service_Recommended;

    L_Any_Urgent :=
        L_Any_Urgent
        OR L_State.Service_Urgent;

END_FOR;

GVL_Predictive_Diagnostics.G_Any_Degradation_Accumulating :=
    L_Any_Degrading;

GVL_Predictive_Diagnostics.G_Any_Service_Recommended :=
    L_Any_Service;

GVL_Predictive_Diagnostics.G_Any_Urgent_Service :=
    L_Any_Urgent;

GVL_Predictive_Diagnostics.G_Runtime_Valid := TRUE;
GVL_Predictive_Diagnostics.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Urgent THEN
    GVL_Predictive_Diagnostics.G_Status_Code := 2;
    GVL_Predictive_Diagnostics.G_Status_Text :=
        'Urgent predictive maintenance required';
ELSIF L_Any_Service THEN
    GVL_Predictive_Diagnostics.G_Status_Code := 1;
    GVL_Predictive_Diagnostics.G_Status_Text :=
        'Predictive maintenance recommended';
ELSE
    GVL_Predictive_Diagnostics.G_Status_Code := 0;
    GVL_Predictive_Diagnostics.G_Status_Text :=
        'Predictive diagnostics runtime healthy';
END_IF;

L_Found := FALSE;

FOR L_i := 0 TO GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY - 1 DO
    IF (L_Processed_History[L_i] = VI_Command_ID) AND (VI_Command_ID <> 0) THEN
        IF VI_System_Time_MS >= L_Processed_Times[L_i] THEN
            L_Age_MS := VI_System_Time_MS - L_Processed_Times[L_i];
        ELSE
            L_Age_MS := (4294967295 - L_Processed_Times[L_i]) + VI_System_Time_MS + 1;
        END_IF;

        IF L_Age_MS < 3600000 THEN
            L_Found := TRUE;
            EXIT;
        END_IF;
    END_IF;
END_FOR;

IF (NOT L_Found) AND (VI_Command_ID <> 0) THEN
    VO_Is_New_Command := TRUE;
    VO_Processed_ID := VI_Command_ID;

    L_Processed_History[L_History_Index] := VI_Command_ID;
    L_Processed_Times[L_History_Index] := VI_System_Time_MS;

    L_History_Index := L_History_Index + 1;
    IF L_History_Index > GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY - 1 THEN
        L_History_Index := 0;
    END_IF;
ELSE
    VO_Is_New_Command := FALSE;
    VO_Processed_ID := 0;
END_IF;

IF NOT VI_Enable THEN
    GVL_Water_Isolation_Authority.G_Authority_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Selective := FALSE;
L_Any_Global := FALSE;
L_Any_Denied := FALSE;
L_Active_Isolation_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    IF GVL_Water_Isolation_Runtime.G_Isolation_Runtime_State[L_i].Isolation_Requested THEN
        L_Active_Isolation_Count := L_Active_Isolation_Count + 1;
    END_IF;
END_FOR;

L_Multiple_Isolations_Active := L_Active_Isolation_Count > 1;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Runtime := GVL_Water_Isolation_Runtime.G_Isolation_Runtime_State[L_i];
    L_Traversal := GVL_Water_Orchestration.G_Traversal_State[L_i];

    L_Authority := L_Empty_Authority;
    L_Authority.Decision_Valid := TRUE;
    L_Authority.Decision_System_Time_MS := VI_System_Time_MS;

    L_Authority.Isolation_Requested := L_Runtime.Isolation_Requested;
    L_Authority.Selective_Candidate := L_Runtime.Selective_Isolation_Requested;
    L_Authority.Global_Fallback_Candidate := L_Runtime.Global_Isolation_Requested;

    L_Authority.Hydraulic_Zone_Id := L_Runtime.Hydraulic_Zone_Id;
    L_Authority.Isolation_Group_Id := L_Runtime.Isolation_Group_Id;
    L_Authority.Valve_Group_Id := L_Runtime.Valve_Group_Id;

    // Orchestration-derived authority.
    L_Authority.Mapping_Valid := L_Traversal.Traversal_Valid;

    L_Authority.Deterministic_Target_Valid :=
        (L_Runtime.Valve_Group_Id <> 0)
        AND NOT L_Traversal.Traversal_Conflict
        AND NOT L_Traversal.Traversal_Ambiguous;

    L_Authority.Safety_Context_Allows_Selective :=
        NOT GVL_INTENT_SAFETY.I_Water_Main_Close_Required;

    IF NOT L_Authority.Isolation_Requested THEN

        L_Authority.Decision_Code := 0;
        L_Authority.Decision_Text := 'No authority required';

    ELSIF L_Multiple_Isolations_Active THEN

        L_Authority.Global_Fallback_Required := TRUE;
        L_Authority.Authority_Denied := TRUE;

        L_Authority.Decision_Code := 3;
        L_Authority.Decision_Text := 'Global fallback authority active: multiple leaks';

    ELSIF NOT L_Authority.Mapping_Valid
       OR NOT L_Authority.Deterministic_Target_Valid
       OR NOT L_Authority.Safety_Context_Allows_Selective THEN

        L_Authority.Global_Fallback_Required := TRUE;
        L_Authority.Authority_Denied := TRUE;

        L_Authority.Decision_Code := 2;
        L_Authority.Decision_Text := 'Global fallback authority active';

    ELSE

        L_Authority.Selective_Authority_Allowed := TRUE;

        L_Authority.Decision_Code := 10;
        L_Authority.Decision_Text := 'Selective authority granted';

    END_IF;

    GVL_Water_Isolation_Authority.G_Authority_State[L_i] :=
        L_Authority;

    L_Any_Selective :=
        L_Any_Selective
        OR L_Authority.Selective_Authority_Allowed;

    L_Any_Global :=
        L_Any_Global
        OR L_Authority.Global_Fallback_Required;

    L_Any_Denied :=
        L_Any_Denied
        OR L_Authority.Authority_Denied;

END_FOR;

GVL_Water_Isolation_Authority.G_Any_Selective_Authority_Allowed :=
    L_Any_Selective;

GVL_Water_Isolation_Authority.G_Any_Global_Fallback_Required :=
    L_Any_Global;

GVL_Water_Isolation_Authority.G_Any_Authority_Denied :=
    L_Any_Denied;

GVL_Water_Isolation_Authority.G_Authority_Valid := TRUE;
GVL_Water_Isolation_Authority.G_Last_Update_MS := VI_System_Time_MS;

IF L_Multiple_Isolations_Active THEN
    GVL_Water_Isolation_Authority.G_Status_Code := 3;
    GVL_Water_Isolation_Authority.G_Status_Text :=
        'Global fallback authority active: multiple leaks';
ELSIF L_Any_Global THEN
    GVL_Water_Isolation_Authority.G_Status_Code := 2;
    GVL_Water_Isolation_Authority.G_Status_Text :=
        'Global fallback authority active';
ELSIF L_Any_Selective THEN
    GVL_Water_Isolation_Authority.G_Status_Code := 1;
    GVL_Water_Isolation_Authority.G_Status_Text :=
        'Selective orchestration authority active';
ELSE
    GVL_Water_Isolation_Authority.G_Status_Code := 0;
    GVL_Water_Isolation_Authority.G_Status_Text :=
        'Authority arbitration healthy';
END_IF;

IF (NOT VI_IsActivePLC) THEN
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
        VO_Sim_Water_Leak[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
        VO_Sim_Gas_Leak[L_i] := REAL#0.0;
    END_FOR;
    RETURN;
END_IF;

IF (VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY) AND VI_Config.Presence_Simulation_Enabled THEN
    VO_Sim_Active := TRUE;

    IF (VI_System_Time_MS - L_Last_Toggle) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 30) THEN
        L_Last_Toggle := VI_System_Time_MS;
        L_Slot := (VI_System_Time_MS / GVL_CONSTANTS.C_MS_IN_MINUTE) MOD 32;

        FOR L_i := 1 TO 32 DO
            VO_Sim_Lights[L_i] := ((TO_UDINT(L_i) + L_Slot) MOD 5) = 0;
        END_FOR;
    END_IF;
ELSE
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    VO_Sim_Water_Leak[L_i] := FALSE;
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    VO_Sim_Gas_Leak[L_i] := REAL#0.0;
END_FOR;

