// ==============================================================================
// Heating runtime OT and cascade correlator
// Read-only degradation correlation layer.
// ==============================================================================



VO_Correlation_Detected := FALSE;
VO_Status_Code := 0;
VO_Status_Text := 'Heating OT/cascade correlator disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

VO_Correlation_Detected :=
    VI_Cascade_Degraded OR
    VI_OT_Degraded OR
    NOT VI_OT_Command_Valid OR
    (VI_Boiler_Count = 0);

IF VO_Correlation_Detected THEN
    VO_Status_Code := 200;
    VO_Status_Text := 'Heating OT/cascade degradation correlated';
ELSE
    VO_Status_Code := 1;
    VO_Status_Text := 'Heating OT/cascade nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_OT_Cascade_Correlator <<<

L_Gateway_Flood_Alarm_Active := GVL_HEALTH_BRIDGE.G_Leak_Detected OR GVL_STATE.G_Safety_Leak_Latched;
L_Gateway_Gas_Alarm_Active := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_HEALTH_BRIDGE.G_CO_Alarm_Level OR GVL_STATE.G_Safety_Gas_Latched;
L_Gateway_Fire_Alarm_Active := GVL_HEALTH_BRIDGE.G_Smoke_Detected OR GVL_STATE.G_Safety_Smoke_Latched;
L_Command_Received_Allowed := GVL_GATEWAY.G_Gateway_Command_Received AND VI_Gateway_Writes_Allowed;

VIO_Scenario_Req_Gateway := SCENARIO_NONE;

fbGateway(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Local_PLC_Role := SEL(VI_IsActivePLC, E_PLC_ROLE.ROLE_STANDBY, E_PLC_ROLE.ROLE_ACTIVE),
    VI_Incoming_Command := GVL_GATEWAY.G_Gateway_Command,
    VI_Command_Received := L_Command_Received_Allowed,
    VI_FloorHeating_Temps := VIO_FloorHeating_Temps,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Zone_Valve_States := VIO_Zone_Valve_States,
    VI_Manifold_Pressures := GVL_STATE.G_Manifold_Pressures,
    VI_Manifold_Pump_States := GVL_STATE.G_Manifold_Pumps,
    VI_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VI_Flood_Alarm_Active := L_Gateway_Flood_Alarm_Active,
    VI_Gas_Alarm_Active := L_Gateway_Gas_Alarm_Active,
    VI_Fire_Alarm_Active := L_Gateway_Fire_Alarm_Active,
    VI_Methane_Concentration := GVL_STATE.G_Methane_Sensors[1],
    VI_Lighting_Base_Levels := VIO_Lighting_Base_Levels,
    VI_Socket_States := GVL_STATE.G_Socket_States,
    VI_Blinds_Positions := GVL_STATE.G_Blinds_Positions,
    VI_Active_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Send_2FA_Req := GVL_COMMAND.G_Send_2FA_Req,
    VI_2FA_Code := GVL_COMMAND.G_2FA_Code_Out,
    VI_Allowed_IPs := GVL_CONFIG.G_Allowed_IPs,
    VO_Telegram_Msg => GVL_GATEWAY.G_Gateway_Telegram_Msg,
    VO_Send_Telegram => GVL_GATEWAY.G_Gateway_Send_Telegram,
    VO_HMI_Status_Message => GVL_GATEWAY.G_Gateway_HMI_Status_Message,
    VO_Data_Ready => GVL_GATEWAY.G_Gateway_Data_Ready,
    VO_Modbus_Registers => GVL_GATEWAY.G_Gateway_Modbus_Registers,
    VO_Arm_Req => GVL_COMMAND.G_Arm_Req,
    VO_Disarm_Req => GVL_COMMAND.G_Disarm_Req,
    VO_PIN_Code => GVL_COMMAND.G_PIN_Code,
    VO_RFID_Tag => GVL_COMMAND.G_RFID_Tag,
    VO_2FA_Code_In => GVL_COMMAND.G_2FA_Code_In,
    VO_Lighting_Override => GVL_COMMAND.G_Lighting_Override,
    VO_Blinds_Override => GVL_COMMAND.G_Blinds_Override,
    VO_Socket_Override => GVL_COMMAND.G_Socket_Override,
    VO_Reset_Errors_Req => GVL_COMMAND.G_Reset_Errors
);

IF L_Command_Received_Allowed AND fbGateway.VO_Set_Scenario_Req THEN
    VIO_Scenario_Req_Gateway := fbGateway.VO_Target_Scenario;
END_IF;

IF NOT L_Command_Received_Allowed THEN
    GVL_COMMAND.G_Arm_Req := FALSE;
    GVL_COMMAND.G_Disarm_Req := FALSE;
    GVL_COMMAND.G_PIN_Code := '';
    GVL_COMMAND.G_RFID_Tag := '';
    GVL_COMMAND.G_2FA_Code_In := '';
    GVL_COMMAND.G_Reset_Errors := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_COMMAND.G_Lighting_Override[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        GVL_COMMAND.G_Blinds_Override[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
        GVL_COMMAND.G_Socket_Override[L_i] := FALSE;
    END_FOR;
END_IF;

GVL_INTENT_USER.I_Source_Valid := TRUE;
GVL_INTENT_USER.I_Last_Update_MS := VI_System_Time_MS;
GVL_INTENT_USER.I_Arm_Request := GVL_COMMAND.G_Arm_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_Disarm_Request := GVL_COMMAND.G_Disarm_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_PIN_Code := GVL_COMMAND.G_PIN_Code;
GVL_INTENT_USER.I_RFID_Tag := GVL_COMMAND.G_RFID_Tag;
GVL_INTENT_USER.I_2FA_Code_In := GVL_COMMAND.G_2FA_Code_In;
GVL_INTENT_USER.I_Lighting_Override_32 := GVL_COMMAND.G_Lighting_Override;
GVL_INTENT_USER.I_Blinds_Override_32 := GVL_COMMAND.G_Blinds_Override;
GVL_INTENT_USER.I_Socket_Override_32 := GVL_COMMAND.G_Socket_Override;
GVL_INTENT_USER.I_Reset_Errors := GVL_COMMAND.G_Reset_Errors AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_Set_Temp_Req := fbGateway.VO_Set_Temp_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_Target_Zone := fbGateway.VO_Target_Zone;
GVL_INTENT_USER.I_Target_Temperature := fbGateway.VO_Target_Temp;
GVL_INTENT_USER.I_Set_Vent_Req := fbGateway.VO_Set_Vent_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_Target_Vent_Speed := fbGateway.VO_Target_Vent_Speed;
GVL_INTENT_USER.I_Set_Config_Req := fbGateway.VO_Set_Config_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_Time_Sync_Req := fbGateway.VO_Sync_Time_Req AND L_Command_Received_Allowed;
GVL_INTENT_USER.I_New_Time_MS := fbGateway.VO_New_Time_MS;

// >>> BULK_SYNC_ANCHOR: FB_System_Gateway_Intent <<<

// ==============================================================================
// System recovery helper
//
// Internal helper for PRG_System.
// Recovery no longer restores authoritative runtime state directly.
// Safety latches and system mode are reconstructed from current
// runtime truth through orchestrators/managers after boot.
// ==============================================================================



IF NOT VIO_Recovery_Done THEN
    VIO_Recovery_Done := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Recovery <<<

// ==============================================================================
// System diagnostics helper
//
// Legacy compatibility helper.
//
// IMPORTANT:
// This function block must not write aggregated diagnostics fields directly.
// Aggregated diagnostics ownership is centralized in:
//
//   FB_System_Health_Orchestrator
//
// Protected aggregate fields:
//
//   GVL_STATUS.G_Diagnostics.Sensor_Fault
//   GVL_STATUS.G_Diagnostics.IO_Offline
//   GVL_STATUS.G_Diagnostics.Subsystem_Degraded
//
// This stub is intentionally side-effect free to prevent resurrecting duplicate
// diagnostics aggregate writers from legacy call paths.
// ==============================================================================


// Intentionally side-effect free.
// Diagnostics aggregate projection is owned by FB_System_Health_Orchestrator.

// >>> BULK_SYNC_ANCHOR: FB_System_Diagnostics <<<

// ==============================================================================
// System scenario arbitration helper
//
// Internal helper for PRG_System.
// Owns scenario request validation, priority resolution, fail-safe clamp,
// degraded-mode adaptation, policy logging, and FB_Scenario_Manager call.
// ==============================================================================



// === SCENARIO REQUEST VALIDATION ===
// Normalize invalid values to NONE to avoid corrupt inputs.
// Actual enum range in E_SCENARIO_TYPE is 0..7.
IF TO_USINT(VIO_Scenario_Req_Operator) > 7 THEN
    VIO_Scenario_Req_Operator := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Gateway) > 7 THEN
    VIO_Scenario_Req_Gateway := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Rule) > 7 THEN
    VIO_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

// === SCENARIO PRIORITY RESOLUTION ===
// Produces VIO_Scenario_Req_Final (TRACE ONLY, not executed directly)
IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VIO_Scenario_Req_Final := 0;
    VIO_Scenario_Source := SRC_SAFETY;
ELSIF VIO_Scenario_Req_Operator <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Operator;
    VIO_Scenario_Source := SRC_OPERATOR;
ELSIF VIO_Scenario_Req_Gateway <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Gateway;
    VIO_Scenario_Source := SRC_GATEWAY;
ELSIF VIO_Scenario_Req_Rule <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Rule;
    VIO_Scenario_Source := SRC_RULE;
ELSE
    VIO_Scenario_Req_Final := GVL_STATUS.G_Current_Scenario;
    VIO_Scenario_Source := SRC_NONE;
END_IF;

VIO_Scenario_Intent := VIO_Scenario_Req_Final;

// === FAIL-SAFE SCENARIO CLAMP ===
CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE VIO_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ; // allowed in degraded
        ELSE
            VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        END_CASE;
END_CASE;

// === CONTEXT FAIL-SAFE AUTOMATION ===
// If security is armed and no explicit source is requesting another scenario,
// force safe occupancy context to AWAY while system remains in MODE_NORMAL.
IF VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF VI_Security_Armed AND
       (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN

        IF (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_NONE) AND
           (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
            GVL_POLICY.G_Away_Previous_Scenario := VIO_Scenario_Intent;
        ELSIF (GVL_STATUS.G_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE) AND
              (GVL_STATUS.G_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
            GVL_POLICY.G_Away_Previous_Scenario := GVL_STATUS.G_Current_Scenario;
        ELSE
            GVL_POLICY.G_Away_Previous_Scenario := E_SCENARIO_TYPE.SCENARIO_PRESENCE;
        END_IF;

        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
        VIO_Scenario_Source := SRC_POLICY;

        fbLogEvent(
            VI_Event_Type := 5,
            VI_Timestamp := VI_System_Time_MS,
            VI_Param1 := TO_UDINT(VIO_Scenario_Source),
            VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
        );
    END_IF;

    // When security is disarmed and no explicit source requests AWAY,
    // leave AWAY and return to the scenario captured before short-away arming.
    IF (NOT VI_Security_Armed) AND
       (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_AWAY) AND
       GVL_POLICY.G_Away_Active THEN

        L_Restore_Target := GVL_POLICY.G_Away_Previous_Scenario;

        IF (L_Restore_Target = E_SCENARIO_TYPE.SCENARIO_NONE) OR
           (L_Restore_Target = E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
            L_Restore_Target := E_SCENARIO_TYPE.SCENARIO_PRESENCE;
        END_IF;

        VIO_Scenario_Intent := L_Restore_Target;
        VIO_Scenario_Source := SRC_POLICY;
    END_IF;
END_IF;

// === DEGRADED-AWARE SCENARIO ADAPTATION ===
// Soft adaptation in degraded mode: keep explicit requests intact,
// but if no source is requesting a scenario, move behavior to a safer baseline.
IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF VI_Security_Armed THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY THEN
                IF (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_NONE) AND
                   (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
                    GVL_POLICY.G_Away_Previous_Scenario := VIO_Scenario_Intent;
                ELSE
                    GVL_POLICY.G_Away_Previous_Scenario := E_SCENARIO_TYPE.SCENARIO_PRESENCE;
                END_IF;

                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 6,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
                );
            END_IF;

        ELSIF VIO_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 7,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_SLEEP)
                );
            END_IF;
        END_IF;
    END_IF;
END_IF;

fbScenarioManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Activate_Request := VIO_Scenario_Intent,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_System_Mode := VI_System_Mode,
    VO_Current_Scenario => GVL_STATUS.G_Current_Scenario
);

// >>> BULK_SYNC_ANCHOR: FB_System_Scenario_Arbitration <<<

// Reset retained outputs before any early return.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    VO_Lighting_Levels[L_i] := 0;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    VO_Blinds_Positions[L_i] := 100;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
    VO_Wet_Zone_Light_Active[L_i] := FALSE;
END_FOR;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

GVL_STATE.G_Lighting_IO_Fault := FALSE;
GVL_STATE.G_Lighting_Subsystem_Degraded := FALSE;

L_Effective_Scenario := VI_Current_Scenario;
L_Effective_Simulation_Active := VI_Simulation_Active;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        RETURN;
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        L_Effective_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
        L_Effective_Simulation_Active := FALSE;
    E_System_Operating_Mode.MODE_DEGRADED:
        L_Effective_Simulation_Active := FALSE;
END_CASE;

L_Wet_Zone_Idx := 1;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        GVL_STATE.G_Lighting_IO_Fault := TRUE;
        GVL_STATE.G_Lighting_Subsystem_Degraded := TRUE;
        RETURN;
    END_IF;
END_FOR;

IF L_Effective_Scenario >= 1 AND L_Effective_Scenario <= GVL_CONSTANTS.C_MAX_SCENARIOS THEN
    L_Target_Base_Light := VI_Scenario_Configs[L_Effective_Scenario].lighting_level_base;
    L_Target_Base_Blinds := VI_Scenario_Configs[L_Effective_Scenario].blinds_position_percent;
ELSE
    L_Target_Base_Light := 100;
    L_Target_Base_Blinds := 100;
END_IF;

// Three-level away behavior from policy/TЗ.
// 1 short: light 100%, simulation off.
// 2 medium: base light 10%, simulation active.
// 3 long: base light 5%, simulation active.
IF L_Effective_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY THEN
    CASE VI_Away_Level OF
        1:
            L_Target_Base_Light := 100;
            L_Effective_Simulation_Active := FALSE;
        2:
            L_Target_Base_Light := 10;
            L_Effective_Simulation_Active := TRUE;
        3:
            L_Target_Base_Light := 5;
            L_Effective_Simulation_Active := TRUE;
    ELSE
            L_Target_Base_Light := 100;
            L_Effective_Simulation_Active := FALSE;
    END_CASE;
END_IF;

IF VI_Is_Night AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
    L_Target_Base_Blinds := 0;
END_IF;

IF L_Effective_Scenario <> L_Prev_Scenario THEN
    L_Transition_Light(VI_System_Time := VI_System_Time_MS, VI_Start_Time := VI_System_Time_MS, VI_Duration := 5000, VI_Start_Value := TO_REAL(L_Base_Light), VI_End_Value := TO_REAL(L_Target_Base_Light));
    L_Transition_Blinds(VI_System_Time := VI_System_Time_MS, VI_Start_Time := VI_System_Time_MS, VI_Duration := 10000, VI_Start_Value := TO_REAL(L_Base_Blinds), VI_End_Value := TO_REAL(L_Target_Base_Blinds));
    L_Prev_Scenario := L_Effective_Scenario;
ELSE
    L_Transition_Light(VI_System_Time := VI_System_Time_MS, VI_Start_Time := L_Transition_Light.VI_Start_Time, VI_Duration := L_Transition_Light.VI_Duration, VI_Start_Value := L_Transition_Light.VI_Start_Value, VI_End_Value := TO_REAL(L_Target_Base_Light));
    L_Transition_Blinds(VI_System_Time := VI_System_Time_MS, VI_Start_Time := L_Transition_Blinds.VI_Start_Time, VI_Duration := L_Transition_Blinds.VI_Duration, VI_Start_Value := L_Transition_Blinds.VI_Start_Value, VI_End_Value := TO_REAL(L_Target_Base_Blinds));
END_IF;

L_Base_Light := TO_BYTE(L_Transition_Light.VO_Current_Value);
L_Base_Blinds := TO_BYTE(L_Transition_Blinds.VO_Current_Value);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    L_Rule_Light_Active := FALSE;
    L_Rule_Light_Val := 0;
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_LIGHTING_BASE THEN
                L_Rule_Light_Active := TRUE;
                L_Rule_Light_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
                L_Light_States[L_i] := (L_Rule_Light_Val > 0);
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_LIGHTING AND VI_Rule_Actions[L_j].Triggered THEN
                L_Light_States[L_i] := NOT L_Light_States[L_i];
            END_IF;
        END_IF;
    END_FOR;

    IF VI_Physical_Switches[L_i] AND NOT L_Prev_Switches[L_i] THEN
        L_Light_States[L_i] := NOT L_Light_States[L_i];
        L_Manual_Override[L_i] := TRUE;
    END_IF;
    L_Prev_Switches[L_i] := VI_Physical_Switches[L_i];

    L_Motion_Timers[L_i](IN := VI_Motion_Sensors[L_i], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);

    IF L_Prev_Motion_Q[L_i] AND NOT L_Motion_Timers[L_i].Q THEN
        L_Manual_Override[L_i] := FALSE;
    END_IF;
    L_Prev_Motion_Q[L_i] := L_Motion_Timers[L_i].Q;

    IF L_Motion_Timers[L_i].Q THEN
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := TRUE;
        END_IF;
    ELSE
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := FALSE;
        END_IF;
    END_IF;

    IF L_Effective_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Simulation_Active THEN
        L_Light_States[L_i] := VI_Simulation_Lights[L_i];
    END_IF;

    IF VI_Manual_Light_Override[L_i] > 0 THEN
        VO_Lighting_Levels[L_i] := VI_Manual_Light_Override[L_i];
    ELSIF L_Rule_Light_Active THEN
        VO_Lighting_Levels[L_i] := L_Rule_Light_Val;
    ELSE
        VO_Lighting_Levels[L_i] := SEL(L_Light_States[L_i], 0, L_Base_Light);
    END_IF;

    // Short-away restore is a domain-owned runtime restore, not a direct IO write.
    IF GVL_AWAY_RESTORE.G_Restore_Active AND GVL_AWAY_RESTORE.G_Snapshot_Valid THEN
        L_Restore_Progress := GVL_AWAY_RESTORE.G_Restore_Progress;
        IF L_Restore_Progress < REAL#0.0 THEN
            L_Restore_Progress := REAL#0.0;
        ELSIF L_Restore_Progress > REAL#1.0 THEN
            L_Restore_Progress := REAL#1.0;
        END_IF;

        L_Restore_Level :=
            TO_REAL(VO_Lighting_Levels[L_i]) +
            ((TO_REAL(GVL_AWAY_RESTORE.G_Lighting_Levels[L_i]) - TO_REAL(VO_Lighting_Levels[L_i])) * L_Restore_Progress);

        IF L_Restore_Level < REAL#0.0 THEN
            L_Restore_Level := REAL#0.0;
        ELSIF L_Restore_Level > REAL#100.0 THEN
            L_Restore_Level := REAL#100.0;
        END_IF;

        VO_Lighting_Levels[L_i] := REAL_TO_BYTE(L_Restore_Level);
    END_IF;

    // Entrance assist affects only configured corridor/stairs zones.
    IF GVL_POLICY.G_Entrance_Light_Assist_Active THEN
        IF L_i = GVL_CONFIG.G_Entrance_Corridor_Light_Zone THEN
            VO_Lighting_Levels[L_i] := GVL_CONFIG.G_Entrance_Corridor_Light_Level;
        ELSIF L_i = GVL_CONFIG.G_Entrance_Stairs_Light_Zone THEN
            VO_Lighting_Levels[L_i] := GVL_CONFIG.G_Entrance_Stairs_Light_Level;
        END_IF;
    END_IF;

    // Security alarm boost: all lighting zones to 100% for the configured
    // five-minute window. This is intentionally applied inside the lighting
    // domain manager and after normal/restore calculations, not as direct IO.
    IF GVL_POLICY.G_Security_Alarm_Light_Boost_Active THEN
        VO_Lighting_Levels[L_i] := 100;
    END_IF;

    IF VI_Wet_Zone_Map[L_i] AND L_Wet_Zone_Idx <= GVL_CONSTANTS.C_MAX_WET_ZONES THEN
        VO_Wet_Zone_Light_Active[L_Wet_Zone_Idx] := (VO_Lighting_Levels[L_i] > 10);
        L_Wet_Zone_Idx := L_Wet_Zone_Idx + 1;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    L_Rule_Blinds_Active := FALSE;
    L_Rule_Blinds_Val := 0;
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_BLINDS THEN
                L_Rule_Blinds_Active := TRUE;
                L_Rule_Blinds_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;

    IF VI_Manual_Blinds_Override[L_i] > 0 THEN
        VO_Blinds_Positions[L_i] := VI_Manual_Blinds_Override[L_i];
    ELSIF L_Rule_Blinds_Active THEN
        VO_Blinds_Positions[L_i] := L_Rule_Blinds_Val;
    ELSE
        VO_Blinds_Positions[L_i] := L_Base_Blinds;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Lighting_Blinds_Manager <<<

IF NOT VI_Enable THEN
    GVL_Cluster_Safety_Barrier.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Block_Execution := FALSE;
L_Status_Code := 0;
L_Status_Text := 'Cluster safety barrier healthy';

GVL_Cluster_Safety_Barrier.G_Remote_Authority_Degraded := FALSE;
GVL_Cluster_Safety_Barrier.G_Runtime_Bus_Degraded := FALSE;
GVL_Cluster_Safety_Barrier.G_Projection_Ownership_Invalid := FALSE;
GVL_Cluster_Safety_Barrier.G_Recovery_Lock_Active := FALSE;
GVL_Cluster_Safety_Barrier.G_Deployment_Invalid := FALSE;
GVL_Cluster_Safety_Barrier.G_Authority_Downgraded := FALSE;
GVL_Cluster_Safety_Barrier.G_Orchestration_Restricted := FALSE;

// Finalized runtime continuity proof chain.
L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

// Root finalized continuity barrier.
IF NOT L_Finalized_Runtime_Continuity THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 9;
    L_Status_Text :=
        'Finalized runtime continuity invalid';

    GVL_Cluster_Safety_Barrier.G_Authority_Downgraded := TRUE;
    GVL_Cluster_Safety_Barrier.G_Orchestration_Restricted := TRUE;

END_IF;

// Remote authority staleness barrier.
IF GVL_Distributed_Runtime.G_Any_Remote_Node_Offline
   OR GVL_Distributed_Runtime.G_Split_Brain_Suspected THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 10;
    L_Status_Text :=
        'Cluster authority state degraded';

    GVL_Cluster_Safety_Barrier.G_Remote_Authority_Degraded := TRUE;

END_IF;

// Runtime bus integrity barrier.
IF GVL_Runtime_Bus.G_Any_Replication_Rejected
   OR NOT GVL_Runtime_Bus.G_TX_Healthy
   OR NOT GVL_Runtime_Bus.G_RX_Healthy THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 11;
    L_Status_Text :=
        'Runtime bus integrity degraded';

    GVL_Cluster_Safety_Barrier.G_Runtime_Bus_Degraded := TRUE;

END_IF;

// Projection ownership barrier.
IF GVL_Distributed_Projection_Ownership.G_Any_Ownership_Conflict
   OR GVL_Distributed_Projection_Ownership.G_Any_Ownership_Stale THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 12;
    L_Status_Text :=
        'Distributed projection ownership invalid';

    GVL_Cluster_Safety_Barrier.G_Projection_Ownership_Invalid := TRUE;

END_IF;

// Recovery lock barrier.
IF GVL_Distributed_Recovery_Lock.G_Recovery_Execution_Blocked
   OR GVL_Distributed_Recovery_Lock.G_Rollback_Execution_Blocked
   OR GVL_Distributed_Recovery_Lock.G_Reopen_Execution_Blocked THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 13;
    L_Status_Text :=
        'Distributed recovery execution blocked';

    GVL_Cluster_Safety_Barrier.G_Recovery_Lock_Active := TRUE;

END_IF;

// Discovery/deployment barrier.
IF GVL_Runtime_Discovery.G_Any_Discovery_Rejected
   OR GVL_Runtime_Discovery.G_Any_Node_Quarantined THEN

    L_Block_Execution := TRUE;
    L_Status_Code := 14;
    L_Status_Text :=
        'Runtime deployment/discovery invalid';

    GVL_Cluster_Safety_Barrier.G_Deployment_Invalid := TRUE;

END_IF;

// Cluster escalation semantics.
IF L_Block_Execution THEN

    GVL_Distributed_Authority.G_Authority_State.Authority_Observer_Only := TRUE;
    GVL_Distributed_Authority.G_Authority_State.Authority_Master_Elected := FALSE;

    GVL_Distributed_Orchestration.G_Distributed_Projection_Healthy := FALSE;

    GVL_Cluster_Safety_Barrier.G_Authority_Downgraded := TRUE;
    GVL_Cluster_Safety_Barrier.G_Orchestration_Restricted := TRUE;

END_IF;

GVL_Cluster_Safety_Barrier.G_Cluster_Execution_Blocked :=
    L_Block_Execution;

GVL_Cluster_Safety_Barrier.G_Runtime_Valid := TRUE;
GVL_Cluster_Safety_Barrier.G_Last_Update_MS := VI_System_Time_MS;
GVL_Cluster_Safety_Barrier.G_Status_Code := L_Status_Code;
GVL_Cluster_Safety_Barrier.G_Status_Text := L_Status_Text;

// default
VO_Mode := BEHAVIOR_HOME;
VO_Mode_Code := 0;

// priority-based transitions
IF VI_Maintenance_Request THEN
    VO_Mode := BEHAVIOR_MAINTENANCE;
    VO_Mode_Code := 300;
ELSIF VI_Away_Request THEN
    VO_Mode := BEHAVIOR_AWAY;
    VO_Mode_Code := 200;
ELSIF VI_Is_Night THEN
    VO_Mode := BEHAVIOR_NIGHT;
    VO_Mode_Code := 100;
END_IF;

IF VI_Write_Event AND (VI_Event.event_code <> 0) THEN
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx] := VI_Event;
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx].timestamp_ms := VI_System_Time_MS;

    GVL_Retain.G_History_Write_Idx := (GVL_Retain.G_History_Write_Idx MOD GVL_CONSTANTS.C_MAX_HISTORY_RECORDS) + 1;
    GVL_Retain.G_History_Total_Events := GVL_Retain.G_History_Total_Events + 1;
END_IF;

VO_Total_Events := GVL_Retain.G_History_Total_Events;
// >>> BULK_SYNC_ANCHOR: FB_History_Manager <<<

// Если ПЛК находится в режиме Standby (резерв), он не должен управлять выходами
IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VO_Gate_Open := FALSE;
    VO_Wicket_Open := FALSE;
    VO_Lock_1_Open := FALSE;
    VO_Lock_2_Open := FALSE;
    RETURN;
END_IF;

// 1. Логика автоматического закрытия замков при постановке на охрану (ТЗ 3.0)
// При переходе системы в режим "Охрана" принудительно блокируем все замки
IF VI_Armed AND NOT L_Prev_Armed THEN
    L_Auto_Lock_Req := TRUE;
END_IF;
L_Prev_Armed := VI_Armed;

// Детекторы фронта для команд
R_Trig_Gate(CLK := VI_Gate_Open_Req);
R_Trig_Wicket(CLK := VI_Wicket_Open_Req);
R_Trig_Lock_1_O(CLK := VI_Lock_1_Open_Req);
R_Trig_Lock_1_C(CLK := VI_Lock_1_Close_Req OR L_Auto_Lock_Req);
R_Trig_Lock_2_O(CLK := VI_Lock_2_Open_Req);
R_Trig_Lock_2_C(CLK := VI_Lock_2_Close_Req OR L_Auto_Lock_Req);

// Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := VI_Access_Codes,
    VI_RFID_Tags := VI_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Формирование импульсов управления исполнительными механизмами (Pulse Control)
// Открытие ворот и калитки требует валидного ПИН-кода или RFID-метки, если система под охраной
L_Gate_Timer(IN := R_Trig_Gate.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.gate_open_pulse_ms));
VO_Gate_Open := L_Gate_Timer.Q;

L_Wicket_Timer(IN := R_Trig_Wicket.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.wicket_open_pulse_ms));
VO_Wicket_Open := L_Wicket_Timer.Q;

L_Lock_1_Open_T(IN := R_Trig_Lock_1_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_1_Open := L_Lock_1_Open_T.Q;

L_Lock_1_Close_T(IN := R_Trig_Lock_1_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_1_Close := L_Lock_1_Close_T.Q;

L_Lock_2_Open_T(IN := R_Trig_Lock_2_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_2_Open := L_Lock_2_Open_T.Q;

L_Lock_2_Close_T(IN := R_Trig_Lock_2_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_2_Close := L_Lock_2_Close_T.Q;

// Сброс флага автоматического закрытия
IF L_Auto_Lock_Req THEN
    L_Auto_Lock_Req := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Access_Control <<<

// detect any motion
VO_Any_Motion := FALSE;
FOR L_i := 1 TO 32 DO
    IF VI_Motion_Sensors[L_i] THEN
        VO_Any_Motion := TRUE;
    END_IF;
END_FOR;

// init protection (avoid instant AWAY at boot)
IF NOT L_Initialized THEN
    L_Last_Motion_TS := VI_System_Time_MS;
    L_Initialized := TRUE;
END_IF;

// fast return: any motion immediately updates timestamp
IF VO_Any_Motion THEN
    L_Last_Motion_TS := VI_System_Time_MS;
END_IF;

// hysteresis logic:
// stay OCCUPIED until timeout expires
IF (VI_System_Time_MS - L_Last_Motion_TS) < L_Timeout_MS THEN
    VO_Occupied := TRUE;
ELSE
    VO_Occupied := FALSE;
END_IF;

VO_Auto_Away := NOT VO_Occupied;
VO_Last_Motion_TS := L_Last_Motion_TS;

// 0. Сброс статистики
IF VI_Reset_Stats THEN
    VIO_Health_Data.Starts_Count := 0;
    VIO_Health_Data.Sample_Count := 0;
    VIO_Health_Data.Current_Sum := 0.0;
    VIO_Health_Data.Avg_Start_Current := 0.0;
    VIO_Health_Data.Health_Score := 100;
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := '';
    VIO_Health_Data.Last_Start_Current := 0.0;
    VIO_Health_Data.Total_Runtime_Hours := 0;
    L_Accumulated_MS := 0;
END_IF;

// 1. Счётчик пусков и замер пускового тока
IF VI_Is_Running AND NOT L_Prev_Running THEN
    VIO_Health_Data.Starts_Count := VIO_Health_Data.Starts_Count + 1;
    VIO_Health_Data.Last_Start_Current := VI_Current_Value;
    L_Start_Time := VI_System_Time_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновление среднего пускового тока
    VIO_Health_Data.Sample_Count := VIO_Health_Data.Sample_Count + 1;
    VIO_Health_Data.Current_Sum := VIO_Health_Data.Current_Sum + VI_Current_Value;
    VIO_Health_Data.Avg_Start_Current := VIO_Health_Data.Current_Sum / UDINT_TO_REAL(VIO_Health_Data.Sample_Count);

    // 2. Анализ отклонения пускового тока (п. 12.1 ТЗ)
    IF VI_Current_Value > (VI_Nominal_Value * 1.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 5, 100));
    ELSIF VI_Current_Value > (VI_Nominal_Value * 1.2) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
    ELSIF VI_Current_Value < (VI_Nominal_Value * 0.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 2, 100));
    END_IF;
END_IF;

// 3. Анализ рабочего тока и наработки
IF VI_Is_Running THEN
    L_Elapsed_MS := (VI_System_Time_MS - L_Last_Calc_Time);
    L_Accumulated_MS := L_Accumulated_MS + L_Elapsed_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновляем наработку каждый час (3600000 мс)
    IF L_Accumulated_MS >= 3600000 THEN
        VIO_Health_Data.Total_Runtime_Hours := VIO_Health_Data.Total_Runtime_Hours + 1;
        L_Accumulated_MS := L_Accumulated_MS - 3600000;

        // Естественный износ: -1% здоровья каждые 1000 часов
        IF (VIO_Health_Data.Total_Runtime_Hours MOD 1000) = 0 THEN
            VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
        END_IF;

        // Анализ рабочего тока (после пускового режима)
        IF (VI_System_Time_MS - L_Start_Time) > 10000 THEN // 10 секунд после пуска
            IF VI_Current_Value > (VI_Nominal_Value * 1.1) THEN
                // Повышенный рабочий ток - ускоренный износ (-1% в час)
                VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 4. Генерация предупреждения
IF VIO_Health_Data.Health_Score < 20 THEN
    VIO_Health_Data.Maintenance_Required := TRUE;
    VIO_Health_Data.Warning_Message := 'Критический износ: проверьте механику';
ELSIF VIO_Health_Data.Health_Score < 60 THEN
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'Предупреждение: повышенное трение';
ELSE
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'В норме';
END_IF;

L_Prev_Running := VI_Is_Running;

// ==============================================================================
// Heating circuit control helper
//
// Internal refactoring helper for FB_Heating_System_Manager.
// Owns per-circuit sensor validation, temperature source fallback,
// floor-heating controller call, overheat shutdown, and rule action projection.
//
// Temperature source selection is confidence-aware:
// - range invalid still blocks that source;
// - passive input-quality confidence can prefer a healthier fallback;
// - degraded-but-range-valid sources remain operational if no better source exists.
//
// Publishes only canonical runtime projection semantics to
// GVL_Heating_Runtime_Projection. Explainability, predictive observation and
// supervisory ingestion consume that projection downstream.
// ==============================================================================



VO_Heating_Sensor_Fault := FALSE;
L_Min_Source_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    fbFloorTempValidator[L_i](
        VI_Value := VI_Floor_Temps[L_i],
        VI_Min_Valid := -40.0,
        VI_Max_Valid := 120.0,
        VI_Fallback_Mode := 0
    );

    L_Climate_Zone_ID := VI_Zone_Configs[L_i].zone;
    IF L_Climate_Zone_ID >= 1 AND L_Climate_Zone_ID <= 16 THEN
        fbRoomTempValidator[L_Climate_Zone_ID](
            VI_Value := VI_Room_Temps[L_Climate_Zone_ID],
            VI_Min_Valid := -40.0,
            VI_Max_Valid := 120.0,
            VI_Fallback_Mode := 0
        );
    END_IF;

    L_Floor_Source_Valid := NOT fbFloorTempValidator[L_i].VO_Error;
    L_Room_Source_Valid :=
        (L_Climate_Zone_ID >= 1) AND
        (L_Climate_Zone_ID <= 16) AND
        (NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error);

    L_Floor_Confidence := REAL#1.0;
    IF GVL_INPUT_QUALITY.G_Floor_Temp_Quality[L_i].Quality_Visible THEN
        L_Floor_Confidence := GVL_INPUT_QUALITY.G_Floor_Temp_Quality[L_i].Confidence;
    END_IF;

    L_Room_Confidence := REAL#1.0;
    IF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= 16) THEN
        IF GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_Climate_Zone_ID].Quality_Visible THEN
            L_Room_Confidence := GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_Climate_Zone_ID].Confidence;
        END_IF;
    END_IF;

    IF L_Floor_Confidence < REAL#0.0 THEN
        L_Floor_Confidence := REAL#0.0;
    ELSIF L_Floor_Confidence > REAL#1.0 THEN
        L_Floor_Confidence := REAL#1.0;
    END_IF;

    IF L_Room_Confidence < REAL#0.0 THEN
        L_Room_Confidence := REAL#0.0;
    ELSIF L_Room_Confidence > REAL#1.0 THEN
        L_Room_Confidence := REAL#1.0;
    END_IF;

    // Floor overheat protection remains floor-bound and range-validity based.
    L_Overheat_Timer[L_i](
        IN := L_Floor_Source_Valid AND (fbFloorTempValidator[L_i].VO_Value > VI_Config.Overheat_Threshold),
        PT := T#60s,
        VI_System_Time_MS := VI_System_Time_MS
    );

    L_Current_Temp := REAL#0.0;
    L_Sensor_Error := FALSE;
    L_Selected_Source_Code := 0;
    L_Selected_Source_Text := 'none';
    L_Selected_Confidence := REAL#0.0;
    L_Fallback_Active := FALSE;
    L_Source_Degraded := FALSE;
    L_Reason_Code := 0;
    L_Reason_Text := 'OK';

    IF VI_Zone_Configs[L_i].control_type = 1 OR VI_Zone_Configs[L_i].control_type = 2 THEN
        L_Primary_Source_Code := 1; // room
        L_Primary_Confidence := L_Room_Confidence;
        L_Fallback_Confidence := L_Floor_Confidence;

        // Primary: room air temperature. If room quality is degraded and floor
        // source is healthier, prefer floor fallback without declaring hard fault.
        IF L_Room_Source_Valid AND
           ((L_Room_Confidence >= L_Min_Source_Confidence) OR NOT L_Floor_Source_Valid OR (L_Room_Confidence >= L_Floor_Confidence)) THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
            L_Selected_Source_Code := 1;
            L_Selected_Source_Text := 'room';
            L_Selected_Confidence := L_Room_Confidence;
        ELSIF L_Floor_Source_Valid THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
            L_Selected_Source_Code := 2;
            L_Selected_Source_Text := 'floor';
            L_Selected_Confidence := L_Floor_Confidence;
            L_Fallback_Active := TRUE;
        ELSIF L_Room_Source_Valid THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
            L_Selected_Source_Code := 1;
            L_Selected_Source_Text := 'room';
            L_Selected_Confidence := L_Room_Confidence;
            L_Source_Degraded := TRUE;
            L_Reason_Code := 2;
            L_Reason_Text := 'Room source degraded but retained; floor source unavailable';
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    ELSE
        L_Primary_Source_Code := 2; // floor
        L_Primary_Confidence := L_Floor_Confidence;
        L_Fallback_Confidence := L_Room_Confidence;

        // Primary: floor temperature. If floor quality is degraded and room
        // source is healthier, prefer room fallback without declaring hard fault.
        IF L_Floor_Source_Valid AND
           ((L_Floor_Confidence >= L_Min_Source_Confidence) OR NOT L_Room_Source_Valid OR (L_Floor_Confidence >= L_Room_Confidence)) THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
            L_Selected_Source_Code := 2;
            L_Selected_Source_Text := 'floor';
            L_Selected_Confidence := L_Floor_Confidence;
        ELSIF L_Room_Source_Valid THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
            L_Selected_Source_Code := 1;
            L_Selected_Source_Text := 'room';
            L_Selected_Confidence := L_Room_Confidence;
            L_Fallback_Active := TRUE;
        ELSIF L_Floor_Source_Valid THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
            L_Selected_Source_Code := 2;
            L_Selected_Source_Text := 'floor';
            L_Selected_Confidence := L_Floor_Confidence;
            L_Source_Degraded := TRUE;
            L_Reason_Code := 2;
            L_Reason_Text := 'Floor source degraded but retained; room source unavailable';
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    END_IF;

    IF L_Fallback_Active THEN
        L_Source_Degraded := TRUE;
        L_Reason_Code := 1;
        IF L_Primary_Source_Code = 1 THEN
            L_Reason_Text := 'Room source degraded or unavailable; floor fallback selected';
        ELSE
            L_Reason_Text := 'Floor source degraded or unavailable; room fallback selected';
        END_IF;
    END_IF;

    IF L_Sensor_Error THEN
        L_Source_Degraded := TRUE;
        L_Reason_Code := 3;
        L_Reason_Text := 'No valid temperature source available';
        VO_Heating_Sensor_Fault := TRUE;
        VO_Zone_Valves[L_i] := FALSE;
    ELSE
        L_Zone_Config := VI_Zone_Configs[L_i];

        IF L_Zone_Config.comfort_temp > REAL#0.0 THEN
            L_Comfort_Target := L_Zone_Config.comfort_temp;
        ELSE
            L_Comfort_Target := L_Zone_Config.design_temp;
        END_IF;

        IF L_Zone_Config.economy_temp > REAL#0.0 THEN
            L_Economy_Target := L_Zone_Config.economy_temp;
        ELSE
            L_Economy_Target := L_Comfort_Target - REAL#3.0;
        END_IF;

        IF L_Zone_Config.long_away_temp > REAL#0.0 THEN
            L_Long_Away_Target := L_Zone_Config.long_away_temp;
        ELSE
            L_Long_Away_Target := GVL_POLICY.G_Away_Long_Economy_Setpoint_C;
        END_IF;

        L_Effective_Target := L_Comfort_Target;

        // Unused rooms may stay in economy even in normal mode.
        IF NOT L_Zone_Config.use_in_normal THEN
            L_Effective_Target := L_Economy_Target;
        END_IF;

        IF GVL_POLICY.G_Away_Active THEN
            CASE GVL_POLICY.G_Away_Level OF
                1:
                    IF L_Zone_Config.use_in_normal THEN
                        L_Effective_Target := L_Comfort_Target + GVL_POLICY.G_Away_Heating_Offset_C;
                    ELSE
                        L_Effective_Target := L_Economy_Target;
                    END_IF;
                2:
                    L_Effective_Target := L_Economy_Target;
                3:
                    L_Effective_Target := L_Long_Away_Target;
            ELSE
                    ;
            END_CASE;

            // Planned return preheat warms only rooms selected in configuration.
            IF GVL_POLICY.G_Away_Return_Preheat_Active AND L_Zone_Config.use_in_away_preheat THEN
                L_Effective_Target := L_Comfort_Target;
            END_IF;
        END_IF;

        IF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= GVL_CONSTANTS.C_MAX_ZONES) THEN
            L_Effective_Target := L_Effective_Target + GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_Climate_Zone_ID];
        END_IF;

        L_Effective_Target := L_Effective_Target + VI_Scenario_Adjust;

        L_Max_Target := L_Zone_Config.max_temp;
        IF L_Max_Target <= REAL#0.0 THEN
            L_Max_Target := REAL#45.0;
        END_IF;

        IF L_Effective_Target < REAL#5.0 THEN
            L_Effective_Target := REAL#5.0;
        ELSIF L_Effective_Target > L_Max_Target THEN
            L_Effective_Target := L_Max_Target;
        END_IF;

        L_Zone_Config.design_temp := L_Effective_Target;

        L_Floor_Controllers[L_i](
            VI_Current_Temp := L_Current_Temp,
            VI_Config := L_Zone_Config,
            VI_Tariff := VI_Tariff,
            VI_Current_Hour := VI_Current_Hour,
            VI_IsActivePLC := VI_IsActivePLC,
            VI_System_Time_MS := VI_System_Time_MS,
            VO_Valve_Bool => VO_Zone_Valves[L_i]
        );
    END_IF;

    L_Source_Loss_Active := L_Sensor_Error;

    L_Source_Switched_Event :=
        (L_Prev_Selected_Source_Code[L_i] <> 0) AND
        (L_Selected_Source_Code <> 0) AND
        (L_Selected_Source_Code <> L_Prev_Selected_Source_Code[L_i]);

    L_Fallback_Activated_Event :=
        L_Fallback_Active AND NOT L_Prev_Fallback_Active[L_i];

    L_Fallback_Recovered_Event :=
        (NOT L_Fallback_Active) AND L_Prev_Fallback_Active[L_i] AND NOT L_Source_Loss_Active;

    L_Source_Loss_Event :=
        L_Source_Loss_Active AND NOT L_Prev_Source_Loss[L_i];

    L_Last_Event_Code := 0;
    L_Last_Event_Text := '';

    IF L_Source_Loss_Event THEN
        L_Last_Event_Code := 4;
        L_Last_Event_Text := 'Temperature source loss';
    ELSIF L_Fallback_Activated_Event THEN
        L_Last_Event_Code := 2;
        L_Last_Event_Text := L_Reason_Text;
    ELSIF L_Fallback_Recovered_Event THEN
        L_Last_Event_Code := 3;
        L_Last_Event_Text := 'Fallback recovered; primary source selected';
    ELSIF L_Source_Switched_Event THEN
        L_Last_Event_Code := 1;
        L_Last_Event_Text := 'Temperature source switched';
    END_IF;

    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Visible := TRUE;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Code := L_Selected_Source_Code;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Selected_Source_Confidence := L_Selected_Confidence;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Active := L_Fallback_Active;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Degraded := L_Source_Degraded;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Sensor_Error_Active := L_Sensor_Error;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Reason_Code := L_Reason_Code;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Reason_Text := L_Reason_Text;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Switched_Event := L_Source_Switched_Event;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Activated_Event := L_Fallback_Activated_Event;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Fallback_Recovered_Event := L_Fallback_Recovered_Event;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Source_Loss_Event := L_Source_Loss_Event;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_Code := L_Last_Event_Code;
    GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_Text := L_Last_Event_Text;

    IF L_Last_Event_Code <> 0 THEN
        GVL_Heating_Runtime_Projection.G_Circuit_Projection[L_i].Last_Event_MS := VI_System_Time_MS;
    END_IF;

    L_Prev_Selected_Source_Code[L_i] := L_Selected_Source_Code;
    L_Prev_Fallback_Active[L_i] := L_Fallback_Active;
    L_Prev_Source_Loss[L_i] := L_Source_Loss_Active;

    IF L_Overheat_Timer[L_i].Q THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_FLOOR_HEATING THEN
                VO_Zone_Valves[L_i] := (VI_Rule_Actions[L_j].Value > REAL#0.5);
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Circuit_Control <<<

// Детекция фронта команды
L_cmd_rising := (VI_Command <> 0) AND (L_prev_Command = 0);
L_prev_Command := VI_Command;

IF L_cmd_rising THEN
    VO_Done := FALSE;
    VO_Error := FALSE;
    VO_ErrorID := 0;
    VO_HMI_Status_Message := '';

    // Валидация смещения
    IF VI_Offset >= C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#1501;
        VO_HMI_Status_Message := 'NVRAM: Неверное смещение';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    // Валидация указателя
    IF NOT __ISVALIDREF(VI_DataRef) THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150A;
        VO_HMI_Status_Message := 'NVRAM: Недействительная ссылка на данные';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    L_pData := ADR(VI_DataRef);

    IF (VI_Offset + VI_DataSize) > C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150B;
        VO_HMI_Status_Message := 'NVRAM: Размер данных превышает доступный объем';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    IF VI_Command = 2 THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150D;
        VO_HMI_Status_Message := 'NVRAM: READ not implemented';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    IF VI_Command = 1 THEN // ЗАПИСЬ (WRITE)
        IF NOT VI_IsActivePLC THEN
            VO_Error := TRUE;
            VO_ErrorID := 16#1509;
            VO_HMI_Status_Message := 'NVRAM: Запись запрещена (STANDBY)';
        ELSE
            // Проверка на изменение данных перед записью
            L_Data_Changed := FALSE;
            FOR L_i := 0 TO VI_DataSize - 1 DO
                IF GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] <> L_pData[L_i] THEN
                    L_Data_Changed := TRUE;
                    EXIT;
                END_IF;
            END_FOR;

            IF L_Data_Changed THEN
                // Безопасное копирование (WRITE)
                FOR L_i := 0 TO VI_DataSize - 1 DO
                    GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] := L_pData[L_i];
                END_FOR;
                VO_HMI_Status_Message := 'NVRAM: Данные успешно сохранены в RETAIN';
            ELSE
                VO_HMI_Status_Message := 'NVRAM: Данные не изменились, запись пропущена';
            END_IF;
        END_IF;
        VO_Done := TRUE;
    END_IF;
END_IF;

IF VI_Command = 0 THEN
    VO_Done := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_NVRAM_Manager <<<

// Защёлкиваем аварии независимо друг от друга
IF VI_Gas_Alarm THEN
    VO_Gas_Latched := TRUE;
END_IF;

IF VI_Leak_Alarm THEN
    VO_Leak_Latched := TRUE;
END_IF;

IF VI_Smoke_Alarm THEN
    VO_Smoke_Latched := TRUE;
END_IF;

L_Any_Active := VI_Gas_Alarm OR VI_Leak_Alarm OR VI_Smoke_Alarm;

// Ручной сброс допустим только когда все входные аварийные сигналы уже исчезли
IF VI_Reset AND NOT L_Any_Active THEN
    VO_Gas_Latched := FALSE;
    VO_Leak_Latched := FALSE;
    VO_Smoke_Latched := FALSE;
END_IF;

// Агрегированный аварийный стоп = любая защёлкнутая safety-авария
VO_Emergency_Stop := VO_Gas_Latched OR VO_Leak_Latched OR VO_Smoke_Latched;

// >>> BULK_SYNC_ANCHOR: FB_Safety_Manager <<<

// 1. Prepare K_ipad and K_opad
FOR i := 0 TO 63 DO
    IF i < KeyLength THEN
        K_ipad[i] := Key[i] XOR 16#36;
        K_opad[i] := Key[i] XOR 16#5C;
    ELSE
        K_ipad[i] := 16#36;
        K_opad[i] := 16#5C;
    END_IF;
END_FOR;

// 2. Inner Hash: SHA1(K_ipad || Message)
FOR i := 0 TO 63 DO
    InnerData[i] := K_ipad[i];
END_FOR;
FOR i := 0 TO MessageLength - 1 DO
    InnerData[64 + i] := Message[i];
END_FOR;

FB_SHA1_Inner(Data := InnerData, Length := 64 + MessageLength, Hash => InnerHash);

// 3. Outer Hash: SHA1(K_opad || InnerHash)
FOR i := 0 TO 63 DO
    OuterData[i] := K_opad[i];
END_FOR;
FOR i := 0 TO 19 DO
    OuterData[64 + i] := InnerHash[i];
END_FOR;

FB_SHA1_Outer(Data := OuterData, Length := 84, Hash => Hash);

Done := TRUE;

VO_Diagnostics.Freeze_Hardware_Event_Pending := FALSE;
VO_Diagnostics.Freeze_Hardware_Event_Text := '';
VO_Diagnostics.Backup_Pump_Fault := VI_Backup_Pump_Out_Of_Service;
VO_Diagnostics.Electric_Heater_Fault := VI_Electric_Heater_Out_Of_Service;
VO_Diagnostics.Backup_Pump_Recovered_After_Retry := FALSE;
VO_Diagnostics.Electric_Heater_Recovered_After_Retry := FALSE;
VO_Diagnostics.Backup_Pump_Out_Of_Service := VI_Backup_Pump_Out_Of_Service;
VO_Diagnostics.Electric_Heater_Out_Of_Service := VI_Electric_Heater_Out_Of_Service;

VO_Diagnostics.Pump_Exercise_Active := FALSE;
VO_Diagnostics.Pump_Exercise_Failed := FALSE;
VO_Diagnostics.Pump_Exercise_Last_Equipment := '';
VO_Diagnostics.Pump_Exercise_Last_Result := 'Pump exercise publisher passive';
VO_Diagnostics.Pump_Exercise_No_Feedback_Count := 0;
VO_Diagnostics.DHW_Heating_Pump_Exercise_Count := 0;
VO_Diagnostics.DHW_Circ_Pump_Exercise_Count := 0;
VO_Diagnostics.Backup_Pump_Exercise_Count := 0;
VO_Diagnostics.Pump_Exercise_Event_Seq := VI_System_Time_MS;
VO_Diagnostics.Pump_Exercise_Journal_1 := 'Passive diagnostics publication active';
VO_Diagnostics.Pump_Exercise_Journal_2 := '';
VO_Diagnostics.Pump_Exercise_Journal_3 := '';
VO_Diagnostics.Pump_Exercise_Journal_Last_Seq := VI_System_Time_MS;

VO_Diagnostics.Pump_Maintenance_Required := VI_Backup_Pump_Out_Of_Service OR VI_Electric_Heater_Out_Of_Service;
VO_Diagnostics.Pump_Maintenance_Warning := VO_Diagnostics.Pump_Maintenance_Required;

VO_Diagnostics.DHW_Heating_Pump_Out_Of_Service := VI_DHW_Heating_Pump_Out_Of_Service;
VO_Diagnostics.DHW_Circ_Pump_Out_Of_Service := VI_DHW_Circ_Pump_Out_Of_Service;

VO_Diagnostics.Maintenance_Last_Action := 'Diagnostics publication only';
VO_Diagnostics.Operator_Action_Blocked := FALSE;
VO_Diagnostics.Operator_Block_Reason := '';
VO_Diagnostics.Operator_Last_Forbidden_Action := '';
VO_Diagnostics.Operator_Journal_1 := 'Operator diagnostics passive';
VO_Diagnostics.Operator_Journal_2 := '';
VO_Diagnostics.Operator_Journal_3 := '';
VO_Diagnostics.Operator_Journal_Event_Seq := VI_System_Time_MS;
VO_Diagnostics.Operator_Journal_Last_Seq := VI_System_Time_MS;

VO_Diagnostics.Dangerous_Action_Pending_Confirm := VI_Dangerous_Action_Pending;
VO_Diagnostics.Dangerous_Action_Confirm_Text := VI_Dangerous_Action_Text;
VO_Diagnostics.Dangerous_Action_Confirm_Deadline_MS := 0;
VO_Diagnostics.User_Access_Level_Active := VI_User_Access_Level;
VO_Diagnostics.User_Access_Denied := FALSE;
VO_Diagnostics.User_Access_Deny_Reason := '';

VO_Diagnostics.Valve_Test_Mode_Active := FALSE;
VO_Diagnostics.Valve_Test_Deadline_MS := 0;
VO_Diagnostics.Valve_Test_Remaining_MS := 0;
VO_Diagnostics.Valve_Test_Validation_OK := TRUE;
VO_Diagnostics.Valve_Test_Validation_Text := 'No generic valve test active';
VO_Diagnostics.Valve_Test_Forced_Close := FALSE;

VO_Diagnostics.Water_Valve_Test_Mode_Active := FALSE;
VO_Diagnostics.Water_Valve_Test_Deadline_MS := 0;
VO_Diagnostics.Water_Valve_Test_Remaining_MS := 0;
VO_Diagnostics.Water_Valve_Test_Validation_OK := TRUE;
VO_Diagnostics.Water_Valve_Test_Validation_Text := 'No water valve test active';
VO_Diagnostics.Water_Valve_Test_Forced_Close := FALSE;
VO_Diagnostics.Gas_Valve_Test_Mode_Active := FALSE;
VO_Diagnostics.Gas_Valve_Test_Deadline_MS := 0;
VO_Diagnostics.Gas_Valve_Test_Remaining_MS := 0;
VO_Diagnostics.Gas_Valve_Test_Validation_OK := TRUE;
VO_Diagnostics.Gas_Valve_Test_Validation_Text := 'No gas valve test active';
VO_Diagnostics.Gas_Valve_Test_Forced_Close := FALSE;

VO_Diagnostics.Active_Leak_Sensor_Index := 0;
VO_Diagnostics.Active_Gas_Sensor_Index := 0;
VO_Diagnostics.Active_Leak_Zone_Name := '';
VO_Diagnostics.Active_Gas_Zone_Name := '';
VO_Diagnostics.Water_Valve_Test_Context := 'Water diagnostics passive';
VO_Diagnostics.Gas_Valve_Test_Context := 'Gas diagnostics passive';

VO_Diagnostics.Water_Recovery_Target_Zone_Index := 0;
VO_Diagnostics.Gas_Recovery_Target_Zone_Index := 0;
VO_Diagnostics.Water_Recovery_Selective_Allowed := FALSE;
VO_Diagnostics.Gas_Recovery_Selective_Allowed := FALSE;
VO_Diagnostics.Water_Recovery_Selective_Text := 'Selective water recovery inactive';
VO_Diagnostics.Gas_Recovery_Selective_Text := 'Selective gas recovery inactive';
VO_Diagnostics.Water_Recovery_Physical_Active := FALSE;
VO_Diagnostics.Water_Recovery_Physical_Zone_Name := '';

VO_Diagnostics.Water_Valve_Exercise_Last_Zone := 0;
VO_Diagnostics.Water_Valve_Exercise_Last_Result := 'Water valve exercise inactive';
VO_Diagnostics.Water_Close_Fault_Active := FALSE;
VO_Diagnostics.Water_Close_Fault_Zone_Name := '';
VO_Diagnostics.Water_Close_Fault_Text := '';
VO_Diagnostics.Water_Localization_Failed := FALSE;
VO_Diagnostics.Water_Main_Shutdown_Recommended := FALSE;
VO_Diagnostics.Water_Escalation_Text := '';
VO_Diagnostics.Alarm_Event_Pulse := FALSE;
VO_Diagnostics.Alarm_Event_Code := 0;
VO_Diagnostics.Alarm_Event_Value := 0.0;
VO_Diagnostics.Sensor_Fault := VI_Sensor_Fault;
VO_Diagnostics.IO_Offline := VI_IO_Offline;
VO_Diagnostics.Subsystem_Degraded := VI_Subsystem_Degraded;

L_Pressure_First := 0;
L_Current_First := 0;
L_Return_First := 0;
L_Any_Manifold_Fault := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] := VI_Manifold_Pump_Out_Of_Service[L_i];
    VO_Diagnostics.Manifold_Pump_Exercise_Count[L_i] := 0;

    VO_Diagnostics.Manifold_Pressure_Fault[L_i] := VI_Manifold_Pressure_Fault[L_i];
    VO_Diagnostics.Manifold_Pressure_Diag_Code[L_i] := SEL(VI_Manifold_Pressure_Fault[L_i], WORD#0, WORD#16#E004);
    IF VI_Manifold_Pressure_Fault[L_i] AND (L_Pressure_First = 0) THEN
        L_Pressure_First := L_i;
    END_IF;

    VO_Diagnostics.Manifold_Current_Fault[L_i] := VI_Manifold_Current_Fault[L_i];
    VO_Diagnostics.Manifold_Current_Diag_Code[L_i] := SEL(VI_Manifold_Current_Fault[L_i], WORD#0, WORD#16#E00A);
    IF VI_Manifold_Current_Fault[L_i] AND (L_Current_First = 0) THEN
        L_Current_First := L_i;
    END_IF;

    VO_Diagnostics.Manifold_Return_Temp_Fault[L_i] := VI_Manifold_Return_Temp_Fault[L_i];
    VO_Diagnostics.Manifold_Return_Temp_Diag_Code[L_i] := SEL(VI_Manifold_Return_Temp_Fault[L_i], WORD#0, WORD#16#E00D);
    IF VI_Manifold_Return_Temp_Fault[L_i] AND (L_Return_First = 0) THEN
        L_Return_First := L_i;
    END_IF;

    VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] := 0;
    IF VI_Manifold_Pressure_Fault[L_i] THEN
        VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] := VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] + 1;
    END_IF;
    IF VI_Manifold_Current_Fault[L_i] THEN
        VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] := VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] + 1;
    END_IF;
    IF VI_Manifold_Return_Temp_Fault[L_i] THEN
        VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] := VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] + 1;
    END_IF;

    VO_Diagnostics.Manifold_Sensor_Out_Of_Service[L_i] := VO_Diagnostics.Manifold_Sensor_Fault_Count[L_i] > 0;
    L_Any_Manifold_Fault := L_Any_Manifold_Fault OR VO_Diagnostics.Manifold_Sensor_Out_Of_Service[L_i];
END_FOR;

FOR L_i := 1 TO 32 DO
    VO_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
    VO_Diagnostics.Water_Zone_Close_Fault[L_i] := FALSE;
    VO_Diagnostics.Water_Zone_Critical_Close_Fault[L_i] := FALSE;
    VO_Diagnostics.Water_Zone_Close_Retry_Active[L_i] := FALSE;
    VO_Diagnostics.Water_Zone_Close_Retry_Count[L_i] := 0;
    VO_Diagnostics.Water_Zone_Close_Recovered_After_Retry[L_i] := FALSE;
END_FOR;

VO_Diagnostics.Manifold_Pressure_Fault_Active := L_Pressure_First > 0;
VO_Diagnostics.Manifold_Pressure_First_Fault_Index := L_Pressure_First;
VO_Diagnostics.Manifold_Pressure_Fault_Text := SEL(L_Pressure_First > 0, '', 'Manifold pressure fault active');

VO_Diagnostics.Manifold_Current_Fault_Active := L_Current_First > 0;
VO_Diagnostics.Manifold_Current_First_Fault_Index := L_Current_First;
VO_Diagnostics.Manifold_Current_Fault_Text := SEL(L_Current_First > 0, '', 'Manifold current fault active');

VO_Diagnostics.Manifold_Return_Temp_Fault_Active := L_Return_First > 0;
VO_Diagnostics.Manifold_Return_Temp_First_Fault_Index := L_Return_First;
VO_Diagnostics.Manifold_Return_Temp_Fault_Text := SEL(L_Return_First > 0, '', 'Manifold return temperature fault active');

VO_Diagnostics.Manifold_Sensor_Out_Of_Service_Active := L_Any_Manifold_Fault;
VO_Diagnostics.Manifold_Sensor_First_OOS_Index := SEL(L_Pressure_First > 0, SEL(L_Current_First > 0, L_Return_First, L_Current_First), L_Pressure_First);
VO_Diagnostics.Manifold_Sensor_OOS_Text := SEL(L_Any_Manifold_Fault, '', 'Manifold sensor out of service');

VO_Publication_Valid := VI_Enable;
IF VI_Subsystem_Degraded OR VI_IO_Offline OR VI_Sensor_Fault OR L_Any_Manifold_Fault THEN
    VO_Status_Code := 1;
    VO_Status_Text := 'System diagnostics degraded';
ELSE
    VO_Status_Code := 0;
    VO_Status_Text := 'System diagnostics nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Diagnostics_Publisher <<<

// ==============================================================================
// Heating runtime observer phase
// Owns governed observer authorization and finalized-state observer publication.
// Does NOT own heating control or output decisions.
// ==============================================================================



VO_Authorization_Executed := FALSE;
VO_Finalization_Executed := FALSE;
VO_Observer_Valid := FALSE;

// ======================================================
// GOVERNED OBSERVER AUTHORIZATION EVALUATION
// ======================================================
IF VI_Authorization_Stage THEN

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
        E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_PENDING;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
        E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_PENDING;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 10;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
        'Heating runtime observer authorization pending';
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active :=
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request;

    fbRuntimeObserverAuthorization(
        VI_Enable_Request := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request,
        VI_Bootstrap_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Bootstrap_Mode,
        VI_Passive_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Passive_Mode,
        VI_ReadOnly_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_ReadOnly_Mode,
        VI_Governance_Locked := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Governance_Locked,
        VI_Runtime_Authority_Disabled := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Runtime_Authority_Disabled,
        VI_Writable_Exports_Disabled := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Writable_Exports_Disabled
    );

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Authorized :=
        fbRuntimeObserverAuthorization.VO_Enable_Authorized;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective :=
        fbRuntimeObserverAuthorization.VO_Enable_Effective;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Valid :=
        fbRuntimeObserverAuthorization.VO_Authorization_Valid;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Status_Code :=
        fbRuntimeObserverAuthorization.VO_Status_Code;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Status_Text :=
        fbRuntimeObserverAuthorization.VO_Status_Text;

    IF NOT GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request THEN
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
            'Heating runtime observer inactive';
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
    ELSIF NOT GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective THEN
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 20;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
            'Heating runtime observer authorization denied';
    END_IF;

    VO_Authorization_Executed := TRUE;
END_IF;

// ======================================================
// GOVERNED FINALIZED-STATE RUNTIME OBSERVER
// ======================================================
IF VI_Finalization_Stage THEN

    IF GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective THEN

        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Rollback_Validated := FALSE;

        IF NOT L_Enable_Last THEN
            L_Activation_Stabilized := FALSE;

            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_STABILIZATION;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_STABILIZATION;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 30;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer stabilization active';

            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := FALSE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := FALSE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code := 100;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
                'Heating runtime observer stabilization cycle active';
        END_IF;

        fbRuntimeObserver(
            VI_Enable := TRUE,
            VI_Runtime_Context := VI_Runtime_Context,
            VI_Diagnostics_Valid := VI_Diagnostics_Valid
        );

        GVL_Heating_Runtime_Observation.G_Runtime_Observation :=
            fbRuntimeObserver.VO_Observation;

        IF L_Activation_Stabilized THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_OPERATIONAL;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_OPERATIONAL;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 40;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer operational';

            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := TRUE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := TRUE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready :=
                fbRuntimeObserver.VO_Observer_Ready;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault :=
                fbRuntimeObserver.VO_Observer_Fault;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code :=
                fbRuntimeObserver.VO_Status_Code;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
                fbRuntimeObserver.VO_Status_Text;

            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Activation_Validated := TRUE;
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Sequencing_Validated := TRUE;
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Publication_Validated := TRUE;
            VO_Observer_Valid := TRUE;
        ELSE
            L_Activation_Stabilized := TRUE;
        END_IF;

    ELSE
        L_Activation_Stabilized := FALSE;

        IF L_Enable_Last THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_ROLLBACK;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_ROLLBACK;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 50;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer rollback cleanup completed';
        ELSIF GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 20;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer authorization denied';
        ELSE
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 0;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer inactive';
        END_IF;

        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := TRUE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Ready := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Fault := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Current_Phase := E_Heating_Runtime_Phase.HRP_DISABLED;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Demand_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Heating_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Circulation_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Demand_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Runtime_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Output_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Available := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Degraded := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Active_Boilers := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Available_Boilers := 0;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Online := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Command_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Transport_Degraded := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Explainability_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Before_Heating_Observed := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_After_Publication_Observed := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Output_Projection_Last_Observed := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Safety_Ownership_Valid := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Observation_Status_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Observation_Status_Text :=
            'Heating runtime observation inactive';

        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
            'Heating runtime observation inactive';

        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Activation_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Sequencing_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Publication_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Rollback_Validated := TRUE;
    END_IF;

    L_Enable_Last :=
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective;

    VO_Finalization_Executed := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observer_Phase <<<

// ==============================================================================
// Блок таймера задержки выключения (System Timer TOF)
// Назначение:
// - Замена стандартного TOF для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    Q := TRUE;
    ET := T#0s;
    L_Running := FALSE;
ELSE
    IF L_Prev_IN THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
    END_IF;

    IF L_Running THEN
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := FALSE;
            ET := PT;
            L_Running := FALSE;
        ELSE
            Q := TRUE;
        END_IF;
    END_IF;
END_IF;

L_Prev_IN := IN;

// ==============================================================================
// System intent publisher helper
//
// Internal helper for PRG_System.
// Owns publication of system-mode gates into GVL_INTENT_SYSTEM.
// ==============================================================================



GVL_INTENT_SYSTEM.I_Source_Valid := TRUE;
GVL_INTENT_SYSTEM.I_Last_Update_MS := VI_System_Time_MS;
GVL_INTENT_SYSTEM.I_Mode_Safe_Stop_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Mode_Degraded_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
GVL_INTENT_SYSTEM.I_Mode_Freeze_Protection_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
GVL_INTENT_SYSTEM.I_Operator_Scenario_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Lighting_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Blinds_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Socket_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Gateway_Writes_Allowed := VI_Gateway_Writes_Allowed;
GVL_INTENT_SYSTEM.I_Scenario_Request_Allowed := (GVL_STATE.G_System_Mode <> E_System_Operating_Mode.MODE_SAFE_STOP);

// >>> BULK_SYNC_ANCHOR: FB_System_Intent_Publisher <<<

R_Trig_Start(CLK := VI_Start_Auth);

IF VI_Reset_Success THEN
    VO_State.Is_Success := FALSE;
END_IF;

IF R_Trig_Start.Q AND NOT VO_State.is_pending AND NOT VO_State.Is_Locked THEN
    VO_State.is_pending := TRUE;
    VO_State.Auth_Method := VI_Method;
    L_Start_Time := VI_System_Time_MS;
    VO_State.Attempts_Left := 3;
    VO_State.Is_Success := FALSE;
    VO_State.Is_Locked := FALSE;
    L_Prev_User_Code := '';

    IF VI_Method <> E_TwoFactor_Method.TF_METHOD_TOTP THEN
        // Генерируем одноразовый код через HMAC (без упрощенного алгоритма "по времени")
        L_Time_Step := VI_System_Time_MS / 30000;
        L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // Секрет-шаблон, заменяется из конфигурации
        FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step + L_Start_Time, L_i * 8) AND 16#FF); END_FOR;
        fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
        L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
        L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
        L_Generated_Code := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
        WHILE LEN(L_Generated_Code) < 6 DO
            L_Generated_Code := CONCAT('0', L_Generated_Code);
        END_WHILE;

        VO_Code_To_Send := L_Generated_Code;
        VO_Send_Code_Req := TRUE;
    ELSE
        // Для TOTP код не отправляем
        VO_Code_To_Send := '';
        VO_Send_Code_Req := FALSE;
    END_IF;
ELSE
    VO_Send_Code_Req := FALSE;
END_IF;

IF VO_State.is_pending THEN
    L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1));

    IF L_Elapsed_Time < (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Time_Left_S := TO_UINT(((GVL_CONSTANTS.C_MS_IN_MINUTE * 5) - L_Elapsed_Time) / 1000);
    ELSE
        VO_State.Time_Left_S := 0;
    END_IF;

    IF VI_User_Code <> '' AND VI_User_Code <> L_Prev_User_Code THEN
        L_Code_Valid := FALSE;

        IF VI_Method = E_TwoFactor_Method.TF_METHOD_TOTP THEN
            // Вычисляем TOTP для текущего шага времени (30 секунд)
            L_Time_Step := VI_System_Time_MS / 30000; 

            // Подготовка ключа (в реальном проекте берется из GVL_CONFIG)
            L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // '1234'

            // Проверка текущего шага
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Current_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Current_TOTP) < 6 DO L_Current_TOTP := CONCAT('0', L_Current_TOTP); END_WHILE;

            // Проверка предыдущего шага (для компенсации рассинхронизации)
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step - 1, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Prev_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Prev_TOTP) < 6 DO L_Prev_TOTP := CONCAT('0', L_Prev_TOTP); END_WHILE;

            IF VI_User_Code = L_Current_TOTP OR VI_User_Code = L_Prev_TOTP THEN
                L_Code_Valid := TRUE;
            END_IF;
        ELSE
            IF VI_User_Code = L_Generated_Code THEN
                L_Code_Valid := TRUE;
            END_IF;
        END_IF;

        IF L_Code_Valid THEN
            VO_State.Is_Success := TRUE;
            VO_State.is_pending := FALSE;
        ELSE
            IF VO_State.Attempts_Left > 0 THEN
                VO_State.Attempts_Left := VO_State.Attempts_Left - 1;
            END_IF;

            IF VO_State.Attempts_Left = 0 THEN
                VO_State.Is_Locked := TRUE;
                VO_State.is_pending := FALSE;
                L_Lockout_Start_Time := VI_System_Time_MS; // Блокировка на 5 минут
            END_IF;
        END_IF;
    END_IF;
    L_Prev_User_Code := VI_User_Code;

    IF L_Elapsed_Time > (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.is_pending := FALSE; // Таймаут
    END_IF;
END_IF;

IF VO_State.Is_Locked THEN
    IF (SEL(VI_System_Time_MS >= L_Lockout_Start_Time, VI_System_Time_MS - L_Lockout_Start_Time, (4294967295 - L_Lockout_Start_Time) + VI_System_Time_MS + 1)) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Is_Locked := FALSE;
    END_IF;
END_IF;

VO_Code_Valid := FALSE;

// Вычисляем хэш введенного кода
IF LEN(VI_Code_To_Check) > 0 THEN
    pCode := ADR(VI_Code_To_Check);
    L_Input_Hash := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_Access_Codes[L_i] <> 0 AND VI_Access_Codes[L_i] = L_Input_Hash THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;

// Проверяем RFID метку
IF LEN(VI_RFID_To_Check) > 0 THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_RFID_Tags[L_i] <> '' AND VI_RFID_Tags[L_i] = VI_RFID_To_Check THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_AccessCode_Manager <<<

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

L_Requested_Scenario := VI_Activate_Request;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP,
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        IF VO_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
            VO_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
            VO_Status_Msg := 'Сценарии принудительно отключены режимом безопасности';
        END_IF;
        RETURN;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE L_Requested_Scenario OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE:
                VO_Status_Msg := 'Сценарии работают в ограниченном degraded-режиме';
        ELSE
                L_Requested_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
                VO_Status_Msg := 'Небезопасный сценарий заблокирован degraded-режимом';
        END_CASE;
ELSE
        // Normal mode: no additional clamp required.
END_CASE;

IF L_Requested_Scenario <> VO_Current_Scenario THEN
    // Проверка минимального времени работы сценария
    IF (VI_System_Time_MS - L_Last_Scenario_Time) >= 60000 OR VO_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
        // Логика переключения сценариев
        VO_Current_Scenario := L_Requested_Scenario;
        L_Last_Scenario_Time := VI_System_Time_MS;

        CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
        ELSE
            VO_Status_Msg := 'Активирован сценарий';
        END_CASE;
    END_IF;
END_IF;

// --- PREHEAT SCENARIO INSERT ---
IF VI_Preheat_Request THEN
    // removed: direct heating write (moved to Heating Manager)
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Scenario_Manager <<<

// ======================================================
// MODBUS RTU SYSCOM TRANSPORT BOUNDARY
// ======================================================
// Byte-level transport boundary between:
//   - project RTU frame runtime
//   - concrete SysCom backend
//
// This FB intentionally does NOT:
//   - open COM ports
//   - call SysCom APIs
//   - generate fake RX frames
//   - generate fake TX done
//
// It only transfers bytes between frame runtime and SysCom backend runtime.
// ======================================================

IF NOT VI_Enable THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error := FALSE;

    RETURN;
END_IF;

// ======================================================
// EXPORT TX FRAME
// ======================================================
IF GVL_MODBUS_RTU_FRAME.G_TX_Ready AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length :=
        GVL_MODBUS_RTU_FRAME.G_TX_Frame.Length;

    FOR L_i := 0 TO 255 DO
        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Buffer[L_i] :=
            GVL_MODBUS_RTU_FRAME.G_TX_Frame.Data[L_i];
    END_FOR;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error_Code := 0;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Request_MS :=
        VI_System_Time_MS;

END_IF;

// ======================================================
// CONFIRMED TX DONE - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done THEN

    GVL_MODBUS_RTU_FRAME.G_TX_Ready := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Done_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX + 1;

END_IF;

// ======================================================
// IMPORT RX FRAME - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready THEN

    GVL_MODBUS_RTU_FRAME.G_RX_Frame.Valid := TRUE;
    GVL_MODBUS_RTU_FRAME.G_RX_Frame.Length :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Length;

    FOR L_i := 0 TO 255 DO
        GVL_MODBUS_RTU_FRAME.G_RX_Frame.Data[L_i] :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_i];
    END_FOR;

    GVL_MODBUS_RTU_FRAME.G_Last_RX_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_RTU_FRAME.G_RX_Ready := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX + 1;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := FALSE;

END_IF;

// ======================================================
// TRANSPORT ERRORS - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error OR
   GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors + 1;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error := FALSE;

END_IF;

// ======================================================
// MODBUS RTU RX FRAME PARSER
// ======================================================

VO_Valid := FALSE;
VO_Error := FALSE;
VO_Error_Code := 0;
VO_Exception_Response := FALSE;
VO_Register_Count := 0;

FOR L_i := 1 TO 32 DO
    VO_Register_Value[L_i] := 0;
END_FOR;

IF NOT VI_Frame.Valid THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0201;
    RETURN;
END_IF;

IF VI_Frame.Length < 5 THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0202;
    RETURN;
END_IF;

CASE VI_Expected_Function OF
    MB_FC03_READ_HOLDING_REGISTERS:
        L_Expected_Function := 3;
    MB_FC04_READ_INPUT_REGISTERS:
        L_Expected_Function := 4;
    MB_FC06_WRITE_SINGLE_REGISTER:
        L_Expected_Function := 6;
    MB_FC16_WRITE_MULTIPLE_REGISTERS:
        L_Expected_Function := 16;
ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0203;
    RETURN;
END_CASE;

// ======================================================
// CRC VALIDATION
// ======================================================
L_CRC_Frame :=
    BYTE_TO_WORD(VI_Frame.Data[VI_Frame.Length - 2]) OR
    SHL(BYTE_TO_WORD(VI_Frame.Data[VI_Frame.Length - 1]), 8);

L_CRC_Calc := 16#FFFF;

FOR L_i := 0 TO (VI_Frame.Length - UINT#3) DO

    L_CRC_Calc := L_CRC_Calc XOR BYTE_TO_WORD(VI_Frame.Data[L_i]);

    FOR L_j := 0 TO 7 DO
        IF (L_CRC_Calc AND 16#0001) <> 0 THEN
            L_CRC_Calc := SHR(L_CRC_Calc, 1);
            L_CRC_Calc := L_CRC_Calc XOR 16#A001;
        ELSE
            L_CRC_Calc := SHR(L_CRC_Calc, 1);
        END_IF;
    END_FOR;

END_FOR;

IF L_CRC_Calc <> L_CRC_Frame THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0204;
    RETURN;
END_IF;

IF VI_Frame.Data[0] <> VI_Expected_Slave_ID THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0205;
    RETURN;
END_IF;

L_Function_Byte := VI_Frame.Data[1];

IF L_Function_Byte = (L_Expected_Function OR 16#80) THEN
    VO_Exception_Response := TRUE;
    VO_Error := TRUE;
    VO_Error_Code := 16#0206;
    RETURN;
END_IF;

IF L_Function_Byte <> L_Expected_Function THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0207;
    RETURN;
END_IF;

CASE VI_Expected_Function OF

    MB_FC03_READ_HOLDING_REGISTERS,
    MB_FC04_READ_INPUT_REGISTERS:

        L_Byte_Count := VI_Frame.Data[2];

        IF (L_Byte_Count = 0) OR ((L_Byte_Count MOD 2) <> 0) THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0208;
            RETURN;
        END_IF;

        VO_Register_Count := L_Byte_Count / 2;

        IF VO_Register_Count > 32 THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0209;
            RETURN;
        END_IF;

        L_Data_Index := 3;

        FOR L_i := 1 TO VO_Register_Count DO

            VO_Register_Value[L_i] :=
                SHL(BYTE_TO_WORD(VI_Frame.Data[L_Data_Index]), 8) OR
                BYTE_TO_WORD(VI_Frame.Data[L_Data_Index + 1]);

            L_Data_Index := L_Data_Index + 2;

        END_FOR;

    MB_FC06_WRITE_SINGLE_REGISTER,
    MB_FC16_WRITE_MULTIPLE_REGISTERS:

        VO_Register_Count := 0;

ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#020A;
    RETURN;
END_CASE;

VO_Valid := TRUE;

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

// ============================================================================== // System alarm orchestrator helper // // Internal helper for PRG_System. // Owns FB_Alarm_Manager call and alarm output projection. // ==============================================================================
fbAlarmManager( VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Gas_Alarm := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_HEALTH_BRIDGE.G_CO_Alarm_Level, VI_Fire_Alarm := GVL_HEALTH_BRIDGE.G_Smoke_Detected, VI_Flood_Alarm := GVL_HEALTH_BRIDGE.G_Leak_Detected, VI_Security_Alarm := GVL_ALARM.G_Security_Alarm, VI_First_Fault_Active := VI_First_Fault_Active, VI_First_Fault_Type := VI_First_Fault_Type, VI_First_Fault_Source := VI_First_Fault_Source, VI_Boiler_Errors := GVL_STATE.G_Boiler_Error, VI_Security_Msg := GVL_STATUS.G_Security_Status_Msg, VI_Acknowledge_All := GVL_CONFIG.G_HMI_Ack_Alarms OR GVL_COMMAND.G_Reset_Errors, VI_Mute_Siren := GVL_ALARM_AUDIBLE_ACK.G_Ack_Active, VIO_Next_Alarm_ID := GVL_ALARM.G_Next_Alarm_ID, VO_Global_Critical => GVL_ALARM.G_Global_Critical, VO_Global_Warning => GVL_ALARM.G_Global_Warning, VO_Siren_Active => GVL_ALARM.G_Global_Siren, VO_Active_Count => GVL_ALARM.G_Active_Alarm_Count, VO_Unacked_Count => GVL_ALARM.G_Unacked_Alarm_Count, VO_Event_Pulse => GVL_STATUS.G_Diagnostics.Alarm_Event_Pulse, VO_Event_Code => GVL_STATUS.G_Diagnostics.Alarm_Event_Code, VO_Event_Value => GVL_STATUS.G_Diagnostics.Alarm_Event_Value, VO_Alarm_List => GVL_ALARM.G_Alarm_List );
// >>> BULK_SYNC_ANCHOR: FB_System_Alarm_Orchestrator <<<

VO_Due := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_Interval_MS := VI_Interval_MS;
IF L_Interval_MS = 0 THEN
    L_Interval_MS := 1;
END_IF;

IF VO_Last_Run_MS = 0 THEN
    VO_Last_Run_MS := VI_Now_MS;
    VO_Due := TRUE;
    RETURN;
END_IF;

IF VI_Now_MS >= VO_Last_Run_MS THEN
    L_Elapsed_MS := VI_Now_MS - VO_Last_Run_MS;
ELSE
    L_Elapsed_MS := (4294967295 - VO_Last_Run_MS) + VI_Now_MS + 1;
END_IF;

IF L_Elapsed_MS >= L_Interval_MS THEN
    VO_Due := TRUE;
    VO_Last_Run_MS := VI_Now_MS;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Periodic_Due_Gate <<<

// ==============================================================================
// Heating runtime timeline observer
// Read-only deterministic execution timeline layer.
// ==============================================================================



IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// SAFE INDEX NORMALIZATION
// ======================================================
IF (VIO_Timeline.Write_Index < 1) OR
   (VIO_Timeline.Write_Index >= 64) THEN

    L_Index := 1;

    IF VIO_Timeline.Write_Index >= 64 THEN
        VIO_Timeline.Timeline_Overflow := TRUE;
    END_IF;

ELSE
    L_Index := VIO_Timeline.Write_Index + 1;
END_IF;

// ======================================================
// FRAME STORAGE
// ======================================================
VIO_Timeline.Frames[L_Index] := VI_Frame;
VIO_Timeline.Write_Index := L_Index;

IF VIO_Timeline.Frame_Count < 64 THEN
    VIO_Timeline.Frame_Count :=
        VIO_Timeline.Frame_Count + 1;
END_IF;

// ======================================================
// TELEMETRY UPDATE
// ======================================================
VIO_Timeline.Sequencing_Valid :=
    VI_Frame.Sequencing_Valid;

VIO_Timeline.Ownership_Valid :=
    VI_Frame.Ownership_Valid;

VIO_Timeline.Synchronization_Valid :=
    VI_Frame.Synchronization_Valid;

VIO_Timeline.Runtime_Jitter_Detected :=
    VI_Frame.Runtime_Jitter_Detected;

VIO_Timeline.Runtime_Latency_Detected :=
    VI_Frame.Runtime_Latency_Detected;

VIO_Timeline.Runtime_Degraded :=
    VI_Frame.Runtime_Degraded;

VIO_Timeline.Status_Code := VI_Frame.Status_Code;
VIO_Timeline.Status_Text := VI_Frame.Status_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Timeline_Observer <<<

IF NOT GVL_BEHAVIOR_ADAPT.G_Adapt_Enabled THEN RETURN; END_IF;

idx := USINT_TO_INT(iScenario);

L_Stats := GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[idx];
L_Stats.Activations := L_Stats.Activations + 1;

IF iSuccess THEN
    L_Stats.Success_Count := L_Stats.Success_Count + 1;
ELSE
    L_Stats.Failure_Count := L_Stats.Failure_Count + 1;
END_IF;

IF L_Stats.Activations > 0 THEN
    L_Stats.Success_Rate := UDINT_TO_REAL(L_Stats.Success_Count) / UDINT_TO_REAL(L_Stats.Activations);
END_IF;

IF (iScenario = REASON_SCENARIO_VENT_BOOST) AND (iZone >= 1) AND (iZone <= GVL_CONSTANTS.C_MAX_ZONES) THEN

    L_Zone := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone];

    IF L_Zone.Zone_Weight = 0.0 THEN
        L_Zone.Zone_Weight := GVL_BEHAVIOR_ADAPT.G_Adapt_Default_Zone_Weight;
    END_IF;

    L_Decay := GVL_BEHAVIOR_ADAPT.G_Decay_Factor;
    L_Zone.Zone_Weight := L_Zone.Zone_Weight * L_Decay;
    L_Zone.Confidence := L_Zone.Confidence * L_Decay;

    L_Zone.Activations := L_Zone.Activations + 1;

    IF iSuccess THEN
        L_Zone.Success_Count := L_Zone.Success_Count + 1;
    ELSE
        L_Zone.Failure_Count := L_Zone.Failure_Count + 1;
    END_IF;

    IF L_Zone.Activations > 0 THEN
        L_Zone.Success_Rate := UDINT_TO_REAL(L_Zone.Success_Count) / UDINT_TO_REAL(L_Zone.Activations);
    END_IF;

    IF iConfidence >= GVL_BEHAVIOR_ADAPT.G_Adapt_Min_Confidence THEN
        L_Zone.Confidence := L_Zone.Confidence +
            (iConfidence - L_Zone.Confidence) * GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate;
    END_IF;

    IF (GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold > 0) AND
       ((L_Zone.Activations MOD INT_TO_UDINT(GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold)) = 0) THEN

        L_Adjustment :=
            (L_Zone.Success_Rate - 0.5)
            * GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate
            * L_Zone.Confidence;

        L_Zone.Zone_Weight := LIMIT(0.5, L_Zone.Zone_Weight + L_Adjustment, 2.0);

    END_IF;

    L_Zone.Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

    GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone] := L_Zone;

END_IF;

GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[idx] := L_Stats;

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block calculates optimization diagnostics only.
// It does NOT modify thermal demand.
//
// Thermal demand ownership remains in:
// FB_Heating_Thermal_Model.
// ==============================================================================

L_Total_Demand := 0.0;

// Aggregate thermal load estimate.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Total_Demand := L_Total_Demand + ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]);
END_FOR;

GVL_HEATING_POLICY.G_Optimization_Load_Index := L_Total_Demand;
GVL_HEATING_POLICY.G_Optimization_Energy_Saving_Active := FALSE;

// Zone optimization diagnostics.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    IF L_Total_Demand > 0.01 THEN
        L_Load := ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]) / L_Total_Demand;
    ELSE
        L_Load := 0.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Optimization_Score[L_i] :=
        L_Load +
        ((1.0 - GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i]) * 0.2);

    // Advisory energy-saving indication only.
    IF L_Total_Demand > 5.0 THEN
        GVL_HEATING_POLICY.G_Optimization_Energy_Saving_Active := TRUE;
    END_IF;

END_FOR;

// ==============================================================================
// System timebase helper
//
// Internal helper for PRG_System.
// Owns PLC runtime clock projection into GVL_STATUS:
// - monotonic system milliseconds
// - time-of-day milliseconds
// - day of week / day of year rollover
// - TOD representation
// ==============================================================================



GVL_STATUS.G_System_Time_MS := TIME_TO_UDINT(TIME());

L_Time_Diff := SEL(
    GVL_STATUS.G_System_Time_MS >= GVL_STATUS.G_Last_System_Time_MS,
    GVL_STATUS.G_System_Time_MS - GVL_STATUS.G_Last_System_Time_MS,
    (4294967295 - GVL_STATUS.G_Last_System_Time_MS) + GVL_STATUS.G_System_Time_MS + 1
);

GVL_STATUS.G_Time_Of_Day_MS := (GVL_STATUS.G_Time_Of_Day_MS + L_Time_Diff) MOD 86400000;

IF GVL_STATUS.G_Time_Of_Day_MS < L_Time_Diff THEN
    GVL_STATUS.G_Current_Day := (GVL_STATUS.G_Current_Day MOD 7) + 1;
    GVL_STATUS.G_Day_Of_Year := (GVL_STATUS.G_Day_Of_Year MOD 365) + 1;
END_IF;

GVL_STATUS.G_Last_System_Time_MS := GVL_STATUS.G_System_Time_MS;
GVL_STATUS.G_Current_TOD := UDINT_TO_TOD(GVL_STATUS.G_Time_Of_Day_MS);

