// ======================================================
// MODBUS RTU TX FRAME BUILDER
// ======================================================
// Builds Modbus RTU request frames only.
// This FB does not send data and does not modify response state.
// ======================================================

VO_Error := FALSE;
VO_Error_Code := 0;
VO_Frame.Valid := FALSE;
VO_Frame.Length := 0;
VO_Frame.CRC := 0;
L_Function_Byte := 0;

FOR L_i := 0 TO 255 DO
    VO_Frame.Data[L_i] := 0;
END_FOR;

IF NOT VI_Request_Valid THEN
    RETURN;
END_IF;

IF VI_Slave_ID = 0 THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0101;
    RETURN;
END_IF;

IF (VI_Register_Count = 0) OR (VI_Register_Count > 32) THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0102;
    RETURN;
END_IF;

CASE VI_Function_Code OF
    MB_FC03_READ_HOLDING_REGISTERS:
        L_Function_Byte := 3;
    MB_FC04_READ_INPUT_REGISTERS:
        L_Function_Byte := 4;
    MB_FC06_WRITE_SINGLE_REGISTER:
        L_Function_Byte := 6;
    MB_FC16_WRITE_MULTIPLE_REGISTERS:
        L_Function_Byte := 16;
ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0104;
    RETURN;
END_CASE;

VO_Frame.Data[0] := VI_Slave_ID;
VO_Frame.Data[1] := L_Function_Byte;
VO_Frame.Data[2] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Start_Register), 8));
VO_Frame.Data[3] := WORD_TO_BYTE(UINT_TO_WORD(VI_Start_Register) AND 16#00FF);

CASE VI_Function_Code OF

    MB_FC03_READ_HOLDING_REGISTERS,
    MB_FC04_READ_INPUT_REGISTERS:

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Register_Count), 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(UINT_TO_WORD(VI_Register_Count) AND 16#00FF);
        VO_Frame.Length := 6;

    MB_FC06_WRITE_SINGLE_REGISTER:

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(VI_Write_Value[1], 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(VI_Write_Value[1] AND 16#00FF);
        VO_Frame.Length := 6;

    MB_FC16_WRITE_MULTIPLE_REGISTERS:

        L_Byte_Count := VI_Register_Count * 2;

        IF L_Byte_Count > 64 THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0103;
            RETURN;
        END_IF;

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Register_Count), 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(UINT_TO_WORD(VI_Register_Count) AND 16#00FF);
        VO_Frame.Data[6] := UINT_TO_BYTE(L_Byte_Count);

        L_Pos := 7;

        FOR L_i := 1 TO UINT_TO_INT(VI_Register_Count) DO
            VO_Frame.Data[L_Pos] := WORD_TO_BYTE(SHR(VI_Write_Value[L_i], 8));
            VO_Frame.Data[L_Pos + 1] := WORD_TO_BYTE(VI_Write_Value[L_i] AND 16#00FF);
            L_Pos := L_Pos + 2;
        END_FOR;

        VO_Frame.Length := 7 + L_Byte_Count;

ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0104;
    RETURN;
END_CASE;

// ======================================================
// INLINE MODBUS RTU CRC16
// ======================================================
L_CRC := 16#FFFF;

FOR L_i := 0 TO (UINT_TO_INT(VO_Frame.Length) - 1) DO

    L_CRC := L_CRC XOR BYTE_TO_WORD(VO_Frame.Data[L_i]);

    FOR L_j := 0 TO 7 DO
        IF (L_CRC AND 16#0001) <> 0 THEN
            L_CRC := SHR(L_CRC, 1);
            L_CRC := L_CRC XOR 16#A001;
        ELSE
            L_CRC := SHR(L_CRC, 1);
        END_IF;
    END_FOR;

END_FOR;

VO_Frame.CRC := L_CRC;
VO_Frame.Data[VO_Frame.Length] := WORD_TO_BYTE(L_CRC AND 16#00FF);
VO_Frame.Data[VO_Frame.Length + 1] := WORD_TO_BYTE(SHR(L_CRC, 8));
VO_Frame.Length := VO_Frame.Length + 2;
VO_Frame.Valid := TRUE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_TX_Index := UDINT_TO_UINT(GVL_Runtime_Bus.G_Last_Sequence_Id);

IF (L_TX_Index >= 1)
   AND (L_TX_Index <= 128) THEN

    L_Frame := GVL_Runtime_Bus.G_TX_Frames[L_TX_Index];

    IF L_Frame.Frame_Valid THEN

        IF GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK
           AND NOT GVL_Runtime_Sessions.G_Any_Stale_Session THEN

            L_Frame.Frame_Ack_Received := TRUE;
            L_Frame.Replication_Consistent := TRUE;
            L_Frame.Status_Code := 0;

        ELSE

            L_Frame.Replication_Rejected := TRUE;
            L_Frame.Status_Code := 2;

        END_IF;

        GVL_Runtime_Bus.G_TX_Frames[L_TX_Index] := L_Frame;

    END_IF;

END_IF;

IF NOT VI_Enable THEN
    GVL_Runtime_Sessions.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

// Finalized runtime continuity proof chain.
L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

GVL_Runtime_Sessions.G_Local_Session.Session_Valid := TRUE;
GVL_Runtime_Sessions.G_Local_Session.Session_Connected := TRUE;
GVL_Runtime_Sessions.G_Local_Session.Last_Heartbeat_MS :=
    VI_System_Time_MS;

GVL_Runtime_Sessions.G_Local_Session.Transport_Healthy :=
    GVL_Runtime_Bus.G_TX_Healthy
    AND L_Finalized_Runtime_Continuity;

GVL_Runtime_Sessions.G_Local_Session.Runtime_Replication_Healthy :=
    GVL_Distributed_Runtime.G_Distributed_Replication_Healthy
    AND L_Finalized_Runtime_Continuity;

GVL_Runtime_Sessions.G_Local_Session.Authority_Granted :=
    GVL_Distributed_Authority.G_Authority_State.Authority_Master_Elected
    AND L_Finalized_Runtime_Continuity;

FOR L_i := 1 TO 16 DO

    L_Session := GVL_Runtime_Sessions.G_Remote_Sessions[L_i];

    IF L_Session.Session_Valid THEN

        IF (VI_System_Time_MS - L_Session.Last_Heartbeat_MS) > 30000 THEN

            L_Session.Session_Stale := TRUE;
            L_Session.Session_Reconnect_Required := TRUE;

            L_Any_Stale := TRUE;

        END_IF;

        IF NOT L_Finalized_Runtime_Continuity THEN

            L_Session.Session_Stale := TRUE;
            L_Session.Session_Quarantined := TRUE;

            L_Any_Stale := TRUE;
            L_Any_Quarantine := TRUE;

        END_IF;

        IF L_Session.Session_Quarantined THEN
            L_Any_Quarantine := TRUE;
        END_IF;

        GVL_Runtime_Sessions.G_Remote_Sessions[L_i] :=
            L_Session;

    END_IF;

END_FOR;

GVL_Runtime_Sessions.G_Any_Stale_Session :=
    L_Any_Stale;

GVL_Runtime_Sessions.G_Any_Quarantined_Session :=
    L_Any_Quarantine;

GVL_Runtime_Sessions.G_Runtime_Valid := TRUE;
GVL_Runtime_Sessions.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Quarantine THEN
    GVL_Runtime_Sessions.G_Status_Code := 2;
    GVL_Runtime_Sessions.G_Status_Text :=
        'Quarantined runtime session detected';
ELSIF L_Any_Stale THEN
    GVL_Runtime_Sessions.G_Status_Code := 1;
    GVL_Runtime_Sessions.G_Status_Text :=
        'Stale runtime session detected';
ELSE
    GVL_Runtime_Sessions.G_Status_Code := 0;
    GVL_Runtime_Sessions.G_Status_Text :=
        'Runtime session governance healthy';
END_IF;

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block owns only global policy mode/adjustment and policy quality/self-tune
// diagnostics. It does NOT own per-zone thermal fields, per-zone target adjustment,
// preheat request, or optimization demand values.
//
// Field owners:
// - FB_Heating_Thermal_Model: thermal response/demand/time/model confidence;
// - FB_Heating_Predictive_Controller: preheat-needed prediction;
// - FB_Heating_Optimizer: optimization scores/load diagnostics;
// - FB_Heating_Policy_Observer / FB_Heating_Schedule_Preheat: zone target policy;
// - FB_Heating_Policy_Manager: global policy and quality/self-level diagnostics.
// ==============================================================================

L_Zone_Hold_MS := VI_Min_Hold_MS / 2;
IF L_Zone_Hold_MS < 60000 THEN
    L_Zone_Hold_MS := 60000;
END_IF;

IF NOT L_Quality_Initialized THEN
    L_Last_Room_Avg := VI_Room_Temp_Avg;
    L_Filtered_Trend := 0.0;
    L_Same_Cause_Since := VI_System_Time_MS;
    L_Last_Cause := VI_RootCause;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        GVL_HEATING_POLICY.G_Zone_Quality[L_i] := 0.0;
        GVL_HEATING_POLICY.G_Zone_Improving[L_i] := FALSE;
        GVL_HEATING_POLICY.G_Zone_Stable[L_i] := TRUE;
        GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] := 0;
    END_FOR;

    L_Quality_Initialized := TRUE;
END_IF;

// ==============================================================================
// Global predictive adjustment based on aggregate room trend.
// ==============================================================================
L_Trend := VI_Room_Temp_Avg - L_Last_Room_Avg;
L_Last_Room_Avg := VI_Room_Temp_Avg;
L_Filtered_Trend := (L_Filtered_Trend * 0.8) + (L_Trend * 0.2);

L_Predictive_Adjustment := 0.0;
IF (L_Filtered_Trend < -0.03) AND (VI_Room_Temp_Avg < (VI_Target_Temp + 0.5)) THEN
    L_Predictive_Adjustment := 1.0;
ELSIF L_Filtered_Trend > 0.03 THEN
    L_Predictive_Adjustment := -0.5;
END_IF;

IF L_Predictive_Adjustment > 1.0 THEN
    L_Predictive_Adjustment := 1.0;
END_IF;
IF L_Predictive_Adjustment < -1.0 THEN
    L_Predictive_Adjustment := -1.0;
END_IF;

GVL_HEATING_POLICY.G_Policy_Predictive_Adjustment := L_Predictive_Adjustment;
GVL_HEATING_POLICY.G_Policy_Predictive_Active := ABS(L_Predictive_Adjustment) > 0.001;

// ==============================================================================
// Aggregate quality / feedback diagnostics.
// ==============================================================================
L_Room_Error := VI_Target_Temp - VI_Room_Temp_Avg;
L_Supply_Error := VI_Target_Temp - VI_Supply_Temp;
L_DeltaT := VI_Supply_Temp - VI_Return_Temp;
L_Quality := 0.0;

IF L_Room_Error > 1.0 THEN
    L_Quality := L_Quality + 2.0;
END_IF;
IF L_Supply_Error > 1.0 THEN
    L_Quality := L_Quality + 1.0;
END_IF;
IF L_DeltaT < 3.0 THEN
    L_Quality := L_Quality + 1.0;
END_IF;

L_Improving := L_Quality < L_Last_Quality;
L_Stable := L_Quality = 0.0;

// ==============================================================================
// Per-zone quality / self-level diagnostics only.
// Does not write target adjustment, thermal demand, time-to-heat, or preheat flags.
// ==============================================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Zone_Error := VI_Target_Temp - VI_Room_Temps[L_i];
    L_Zone_Quality := 0.0;

    IF L_Zone_Error > 1.0 THEN
        L_Zone_Quality := L_Zone_Quality + 2.0;
    END_IF;
    IF VI_Floor_Temps[L_i] < (VI_Target_Temp - 2.0) THEN
        L_Zone_Quality := L_Zone_Quality + 1.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Improving[L_i] :=
        L_Zone_Quality < GVL_HEATING_POLICY.G_Zone_Quality[L_i];

    GVL_HEATING_POLICY.G_Zone_Stable[L_i] :=
        L_Zone_Quality = 0.0;

    L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i];

    IF GVL_HEATING_POLICY.G_Zone_Stable[L_i] THEN
        L_Zone_Desired_Level := 0;
    ELSIF GVL_HEATING_POLICY.G_Zone_Improving[L_i] THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] - 1;
    ELSIF L_Zone_Quality >= 3.0 THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] + 1;
    END_IF;

    IF L_Zone_Desired_Level > 2 THEN
        L_Zone_Desired_Level := 2;
    END_IF;
    IF L_Zone_Desired_Level < 0 THEN
        L_Zone_Desired_Level := 0;
    END_IF;

    IF L_Zone_Desired_Level <> GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] THEN
        IF (VI_System_Time_MS - L_Zone_Last_Level_Accept_MS[L_i]) >= L_Zone_Hold_MS THEN
            GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] := L_Zone_Desired_Level;
            L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        END_IF;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Quality[L_i] := L_Zone_Quality;
END_FOR;

// ==============================================================================
// Global self-level and policy mode.
// ==============================================================================
IF VI_RootCause <> L_Last_Cause THEN
    L_Same_Cause_Since := VI_System_Time_MS;
    L_Self_Level := 0;
END_IF;
L_Last_Cause := VI_RootCause;

IF L_Stable THEN
    L_Self_Level := 0;
ELSIF L_Improving THEN
    L_Self_Level := L_Self_Level - 1;
ELSIF (VI_System_Time_MS - L_Same_Cause_Since) > (VI_Min_Hold_MS * 2) AND (VI_RootConfidence > 0.8) AND (L_Quality >= 3.0) THEN
    L_Self_Level := L_Self_Level + 1;
END_IF;

IF L_Self_Level > 2 THEN
    L_Self_Level := 2;
END_IF;
IF L_Self_Level < 0 THEN
    L_Self_Level := 0;
END_IF;

L_Raw_Mode := E_Heating_Policy_Mode.HPM_NORMAL;
L_Raw_Block := FALSE;
L_Raw_Target_Adjustment := L_Predictive_Adjustment;
L_Raw_Priority_Multiplier := 1.0;
L_Force_Immediate := FALSE;

IF VI_Emergency_Stop OR VI_Gas_Safety THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_SAFETY_BLOCK;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootCause = E_Heating_RootCause.RC_IO_OFFLINE THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootConfidence >= 0.6 THEN
    CASE VI_RootCause OF
        E_Heating_RootCause.RC_NO_HEAT_TRANSFER:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment + 3.0 + TO_REAL(L_Self_Level);
        E_Heating_RootCause.RC_PUMP_FAILURE:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Priority_Multiplier := 0.5 - (0.1 * TO_REAL(L_Self_Level));
        E_Heating_RootCause.RC_VALVES_CLOSED:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment - 2.0;
        E_Heating_RootCause.RC_NO_FLAME,
        E_Heating_RootCause.RC_BOILER_ERROR:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Priority_Multiplier := 0.7;
    ELSE
        IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
        END_IF;
    END_CASE;
ELSE
    IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
        L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
    END_IF;
END_IF;

IF L_Raw_Target_Adjustment > 5.0 THEN
    L_Raw_Target_Adjustment := 5.0;
END_IF;
IF L_Raw_Target_Adjustment < -3.0 THEN
    L_Raw_Target_Adjustment := -3.0;
END_IF;
IF L_Raw_Priority_Multiplier < 0.3 THEN
    L_Raw_Priority_Multiplier := 0.3;
END_IF;
IF L_Raw_Priority_Multiplier > 1.0 THEN
    L_Raw_Priority_Multiplier := 1.0;
END_IF;

L_Effective_Hold_MS := VI_Min_Hold_MS;
IF VI_RootConfidence >= 0.9 THEN
    L_Effective_Hold_MS := VI_Min_Hold_MS / 2;
END_IF;

IF NOT L_Initialized THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
    L_Initialized := TRUE;
ELSIF L_Force_Immediate THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
ELSIF (L_Raw_Mode <> L_Held_Mode) OR (ABS(L_Raw_Target_Adjustment - L_Held_Target_Adjustment) > 0.001) OR (ABS(L_Raw_Priority_Multiplier - L_Held_Priority_Multiplier) > 0.001) OR (L_Raw_Block <> L_Held_Block) THEN
    IF (VI_System_Time_MS - L_Last_Accept_MS) >= L_Effective_Hold_MS THEN
        L_Held_Mode := L_Raw_Mode;
        L_Held_Block := L_Raw_Block;
        L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
        L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
        L_Last_Accept_MS := VI_System_Time_MS;
    END_IF;
END_IF;

VO_Policy_Mode := L_Held_Mode;
VO_Block_Heating := L_Held_Block;
VO_Target_Adjustment := L_Held_Target_Adjustment;
VO_Priority_Multiplier := L_Held_Priority_Multiplier;
VO_Self_Tune_Active := L_Self_Level > 0;
VO_Self_Tune_Level := L_Self_Level;
VO_Feedback_Stable := L_Stable;
VO_Feedback_Improving := L_Improving;
VO_Feedback_Quality := L_Quality;

L_Last_Quality := L_Quality;

IF NOT VI_Enable THEN
    GVL_Cluster_Runtime_FSM.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

// Finalized runtime continuity proof chain.
L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

// Reset runtime states.
GVL_Cluster_Runtime_FSM.G_State_Startup := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Discovery := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Synchronization := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Operational := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Degraded := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Observer_Only := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Recovery_Lock := FALSE;
GVL_Cluster_Runtime_FSM.G_State_Quarantine := FALSE;

// Startup state.
IF NOT GVL_Distributed_Runtime.G_Runtime_Valid THEN

    GVL_Cluster_Runtime_FSM.G_State_Startup := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 1;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime startup';

ELSIF GVL_Runtime_Discovery.G_Runtime_Valid
   AND NOT GVL_Runtime_Discovery.G_Any_Discovery_Rejected THEN

    GVL_Cluster_Runtime_FSM.G_State_Discovery := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 2;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime discovery';

END_IF;

// Synchronization state.
IF GVL_Runtime_Bus.G_TX_Healthy
   AND GVL_Runtime_Bus.G_RX_Healthy THEN

    GVL_Cluster_Runtime_FSM.G_State_Synchronization := TRUE;

END_IF;

// Operational state.
IF GVL_Distributed_Execution_Gates.G_Can_Execute
   AND GVL_Distributed_Execution_Gates.G_Can_Orchestrate
   AND L_Finalized_Runtime_Continuity THEN

    GVL_Cluster_Runtime_FSM.G_State_Operational := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 0;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime operational';

END_IF;

// Degraded state.
IF GVL_Cluster_Safety_Barrier.G_Cluster_Execution_Blocked THEN

    GVL_Cluster_Runtime_FSM.G_State_Degraded := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 10;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime degraded';

END_IF;

// Observer-only state.
IF GVL_Distributed_Authority.G_Authority_State.Authority_Observer_Only THEN

    GVL_Cluster_Runtime_FSM.G_State_Observer_Only := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 11;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime observer-only';

END_IF;

// Recovery lock state.
IF GVL_Distributed_Recovery_Lock.G_Recovery_Execution_Blocked THEN

    GVL_Cluster_Runtime_FSM.G_State_Recovery_Lock := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 12;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime recovery-locked';

END_IF;

// Quarantine state.
IF GVL_Runtime_Discovery.G_Any_Node_Quarantined THEN

    GVL_Cluster_Runtime_FSM.G_State_Quarantine := TRUE;

    GVL_Cluster_Runtime_FSM.G_Status_Code := 13;
    GVL_Cluster_Runtime_FSM.G_Status_Text :=
        'Cluster runtime quarantined';

END_IF;

GVL_Cluster_Runtime_FSM.G_Runtime_Valid := TRUE;
GVL_Cluster_Runtime_FSM.G_Last_Update_MS := VI_System_Time_MS;

// Initialize variables
H0 := 16#67452301;
H1 := 16#EFCDAB89;
H2 := 16#98BADCFE;
H3 := 16#10325476;
H4 := 16#C3D2E1F0;

// Pre-processing
FOR i := 0 TO Length - 1 DO
    PaddedData[i] := Data[i];
END_FOR;

// Append the bit '1' to the message
PaddedData[Length] := 16#80;

// Append 0 <= k < 512 bits '0', such that the resulting message length in bits
// is congruent to -64 ≡ 448 (mod 512)
PaddedLength := Length + 1;
WHILE (PaddedLength MOD 64) <> 56 DO
    PaddedData[PaddedLength] := 0;
    PaddedLength := PaddedLength + 1;
END_WHILE;

// Append length of message (before pre-processing), in bits, as 64-bit big-endian integer
// Since our message is small (max 127 bytes), we only need the lower 32 bits
Temp := TO_DWORD(Length * 8);
PaddedData[PaddedLength] := 0;
PaddedData[PaddedLength+1] := 0;
PaddedData[PaddedLength+2] := 0;
PaddedData[PaddedLength+3] := 0;
PaddedData[PaddedLength+4] := TO_BYTE(SHR(Temp, 24));
PaddedData[PaddedLength+5] := TO_BYTE(SHR(Temp, 16));
PaddedData[PaddedLength+6] := TO_BYTE(SHR(Temp, 8));
PaddedData[PaddedLength+7] := TO_BYTE(Temp);
PaddedLength := PaddedLength + 8;

NumBlocks := PaddedLength / 64;

// Process the message in successive 512-bit chunks
FOR i := 0 TO NumBlocks - 1 DO
    BlockOffset := i * 64;

    // Break chunk into sixteen 32-bit big-endian words w[i], 0 <= i <= 15
    FOR j := 0 TO 15 DO
        W[j] := SHL(TO_DWORD(PaddedData[BlockOffset + j*4]), 24) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 1]), 16) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 2]), 8) OR
                TO_DWORD(PaddedData[BlockOffset + j*4 + 3]);
    END_FOR;

    // Message schedule: extend the sixteen 32-bit words into eighty 32-bit words
    FOR j := 16 TO 79 DO
        Temp := W[j-3] XOR W[j-8] XOR W[j-14] XOR W[j-16];
        W[j] := SHL(Temp, 1) OR SHR(Temp, 31); // Left rotate by 1
    END_FOR;

    // Initialize hash value for this chunk
    A := H0;
    B := H1;
    C := H2;
    D := H3;
    E := H4;

    // Main loop
    FOR j := 0 TO 79 DO
        IF j <= 19 THEN
            F := (B AND C) OR ((NOT B) AND D);
            K := 16#5A827999;
        ELSIF j <= 39 THEN
            F := B XOR C XOR D;
            K := 16#6ED9EBA1;
        ELSIF j <= 59 THEN
            F := (B AND C) OR (B AND D) OR (C AND D);
            K := 16#8F1BBCDC;
        ELSE
            F := B XOR C XOR D;
            K := 16#CA62C1D6;
        END_IF;

        Temp := (SHL(A, 5) OR SHR(A, 27)) + F + E + K + W[j];
        E := D;
        D := C;
        C := SHL(B, 30) OR SHR(B, 2);
        B := A;
        A := Temp;
    END_FOR;

    // Add this chunk's hash to result so far
    H0 := H0 + A;
    H1 := H1 + B;
    H2 := H2 + C;
    H3 := H3 + D;
    H4 := H4 + E;
END_FOR;

// Produce the final hash value (big-endian)
Hash[0] := TO_BYTE(SHR(H0, 24)); Hash[1] := TO_BYTE(SHR(H0, 16)); Hash[2] := TO_BYTE(SHR(H0, 8)); Hash[3] := TO_BYTE(H0);
Hash[4] := TO_BYTE(SHR(H1, 24)); Hash[5] := TO_BYTE(SHR(H1, 16)); Hash[6] := TO_BYTE(SHR(H1, 8)); Hash[7] := TO_BYTE(H1);
Hash[8] := TO_BYTE(SHR(H2, 24)); Hash[9] := TO_BYTE(SHR(H2, 16)); Hash[10] := TO_BYTE(SHR(H2, 8)); Hash[11] := TO_BYTE(H2);
Hash[12] := TO_BYTE(SHR(H3, 24)); Hash[13] := TO_BYTE(SHR(H3, 16)); Hash[14] := TO_BYTE(SHR(H3, 8)); Hash[15] := TO_BYTE(H3);
Hash[16] := TO_BYTE(SHR(H4, 24)); Hash[17] := TO_BYTE(SHR(H4, 16)); Hash[18] := TO_BYTE(SHR(H4, 8)); Hash[19] := TO_BYTE(H4);

// ==============================================================================
// Heating safety gate helper
// ==============================================================================



VO_Gas_Safety_Active := VI_Gas_Safety_Stop;
VO_Emergency_Safe_Stop_Active := VI_Emergency_Stop OR (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
VO_IO_Failsafe_Active := VI_IO_Failsafe_Active;

// REAL validity guard: NaN fails self-equality; extreme values are rejected as sensor faults.
VO_Outdoor_Temp_Valid := (VI_Outdoor_Temp = VI_Outdoor_Temp) AND (VI_Outdoor_Temp > -80.0) AND (VI_Outdoor_Temp < 80.0);
IF VO_Outdoor_Temp_Valid THEN
    L_Outdoor_Temp_Safe := VI_Outdoor_Temp;
ELSE
    L_Outdoor_Temp_Safe := 20.0;
    GVL_STATE.G_Heating_Sensor_Fault := TRUE;
END_IF;

VO_Block_Normal_Heating := VO_Gas_Safety_Active OR VO_Emergency_Safe_Stop_Active OR VO_IO_Failsafe_Active;
VO_Freeze_Mode_Active := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION) OR (L_Outdoor_Temp_Safe < -5.0);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Floor_Temps[L_i] < 7.0 THEN
        VO_Freeze_Mode_Active := TRUE;
    END_IF;
END_FOR;

IF VO_Freeze_Mode_Active THEN
    VO_Freeze_Target_Supply := LIMIT(20.0, VI_Freeze_Threshold + 2.0, 35.0);
ELSE
    VO_Freeze_Target_Supply := 0.0;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Safety_Gate <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i] := VI_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i] := VI_Manifold_Pumps[L_i];
    GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i] := REAL_TO_UINT(VI_Manifold_Valves[L_i] * 1000.0);
END_FOR;

GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump := VI_DHW_Heating_Pump;
GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump := VI_DHW_Circ_Pump;
GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump := VI_Backup_Circulation_Pump;
GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable := VI_Electric_Heater_Enable;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Output_Projection <<<

IF NOT VI_Enable THEN
    GVL_Water_Isolation_Intent.G_Intent_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Selective := FALSE;
L_Global_Fallback := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_State := GVL_Water_Isolation_Runtime.G_Isolation_Runtime_State[L_i];

    GVL_Water_Isolation_Intent.G_Zone_Close_Requested[L_i] := FALSE;
    GVL_Water_Isolation_Intent.G_Valve_Group_Close_Requested[L_i] := FALSE;

    IF L_State.Selective_Isolation_Requested THEN

        IF (L_State.Hydraulic_Zone_Id >= 1)
           AND (L_State.Hydraulic_Zone_Id <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS) THEN

            GVL_Water_Isolation_Intent.G_Zone_Close_Requested[
                L_State.Hydraulic_Zone_Id
            ] := TRUE;

        END_IF;

        IF (L_State.Valve_Group_Id >= 1)
           AND (L_State.Valve_Group_Id <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS) THEN

            GVL_Water_Isolation_Intent.G_Valve_Group_Close_Requested[
                L_State.Valve_Group_Id
            ] := TRUE;

        END_IF;

        L_Any_Selective := TRUE;

    END_IF;

    IF L_State.Global_Isolation_Requested THEN
        L_Global_Fallback := TRUE;
    END_IF;

END_FOR;

GVL_Water_Isolation_Intent.G_Global_Isolation_Requested :=
    L_Global_Fallback;

GVL_Water_Isolation_Intent.G_Intent_Valid := TRUE;

IF L_Global_Fallback THEN
    GVL_Water_Isolation_Intent.G_Status_Code := 2;
    GVL_Water_Isolation_Intent.G_Status_Text :=
        'Global isolation fallback requested';
ELSIF L_Any_Selective THEN
    GVL_Water_Isolation_Intent.G_Status_Code := 1;
    GVL_Water_Isolation_Intent.G_Status_Text :=
        'Localized isolation intent available';
ELSE
    GVL_Water_Isolation_Intent.G_Status_Code := 0;
    GVL_Water_Isolation_Intent.G_Status_Text :=
        'No isolation intent active';
END_IF;

IF NOT VI_Enable THEN
    GVL_Distributed_Execution_Gates.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

// Observer-only runtime semantics.
// Observer nodes may:
//   - observe runtime state;
//   - receive publications;
//   - participate in diagnostics.
//
// Observer nodes must NEVER:
//   - execute orchestration;
//   - own projections;
//   - execute recovery;
//   - publish physical outputs.
L_Observer_Only :=
    GVL_Distributed_Authority.G_Authority_State.Authority_Observer_Only;

// Semantic continuity authority.
L_Semantic_Continuity_Valid :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected;

// Finalized publication proof chain.
L_Finalized_Publication_Continuity :=
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

L_Allow :=
    NOT GVL_Cluster_Safety_Barrier.G_Cluster_Execution_Blocked
    AND GVL_Distributed_Authority.G_Authority_State.Authority_Master_Elected
    AND NOT GVL_Distributed_Runtime.G_Split_Brain_Suspected
    AND NOT GVL_Distributed_Projection_Ownership.G_Any_Ownership_Conflict
    AND NOT GVL_Runtime_Sessions.G_Any_Stale_Session
    AND L_Semantic_Continuity_Valid
    AND L_Finalized_Publication_Continuity
    AND NOT L_Observer_Only;

GVL_Distributed_Execution_Gates.G_Can_Replicate :=
    GVL_Runtime_Bus.G_TX_Healthy
    AND GVL_Runtime_Bus.G_RX_Healthy;

GVL_Distributed_Execution_Gates.G_Can_Execute :=
    L_Allow;

GVL_Distributed_Execution_Gates.G_Can_Orchestrate :=
    L_Allow
    AND GVL_Distributed_Orchestration.G_Distributed_Scheduler_Healthy;

GVL_Distributed_Execution_Gates.G_Can_Recover :=
    L_Allow
    AND NOT GVL_Distributed_Recovery_Lock.G_Recovery_Execution_Blocked;

GVL_Distributed_Execution_Gates.G_Can_Rollback :=
    L_Allow
    AND NOT GVL_Distributed_Recovery_Lock.G_Rollback_Execution_Blocked;

GVL_Distributed_Execution_Gates.G_Can_Own_Projection :=
    L_Allow
    AND NOT GVL_Distributed_Projection_Ownership.G_Any_Projection_Blocked;

GVL_Distributed_Execution_Gates.G_Runtime_Valid := TRUE;
GVL_Distributed_Execution_Gates.G_Last_Update_MS :=
    VI_System_Time_MS;

IF L_Observer_Only THEN

    GVL_Distributed_Execution_Gates.G_Status_Code := 2;
    GVL_Distributed_Execution_Gates.G_Status_Text :=
        'Distributed runtime observer-only';

ELSIF L_Allow THEN

    GVL_Distributed_Execution_Gates.G_Status_Code := 0;
    GVL_Distributed_Execution_Gates.G_Status_Text :=
        'Distributed execution gates open';

ELSE

    GVL_Distributed_Execution_Gates.G_Status_Code := 1;
    GVL_Distributed_Execution_Gates.G_Status_Text :=
        'Distributed execution gates restricted';

END_IF;

IF NOT VI_Enable THEN
    GVL_Water_Runtime_Hardening.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Rollback := FALSE;
L_Any_Escalation := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    // Recovery FSM.
    L_FSM := L_Empty_FSM;
    L_FSM.Runtime_Valid := TRUE;

    L_FSM.Runtime_System_Time_MS :=
        VI_System_Time_MS;

    L_FSM.Recovery_Domain_Id :=
        GVL_Water_Topology_Config.G_Config_Record[L_i].Recovery_Domain_Id;

    L_FSM.Recovery_Requested :=
        GVL_INTENT_SAFETY.I_Water_Selective_Recovery_Allowed;

    L_FSM.Recovery_Sequencing_Active :=
        GVL_Water_Orchestration.G_Orchestration_State[L_i].Recovery_Sequence_Active;

    L_FSM.Recovery_Verification_Window_Active :=
        GVL_Water_Orchestration.G_Orchestration_State[L_i].Observation_Window_Active;

    // Conservative runtime hardening.
    IF GVL_Water_Physical_Runtime.G_Convergence_State[L_i].Escalation_Required THEN

        L_FSM.Rollback_Required := TRUE;
        L_FSM.Escalation_Required := TRUE;
        L_FSM.Operator_Ack_Required := TRUE;
        L_FSM.Recovery_Denied := TRUE;
        L_FSM.FSM_State := 100;

        L_FSM.Status_Code := 2;
        L_FSM.Status_Text :=
            'Recovery rollback escalation active';

    ELSIF L_FSM.Recovery_Requested THEN

        L_FSM.Recovery_Completed := TRUE;
        L_FSM.FSM_State := 10;

        L_FSM.Status_Code := 1;
        L_FSM.Status_Text :=
            'Recovery sequencing active';

    ELSE

        L_FSM.FSM_State := 0;

        L_FSM.Status_Code := 0;
        L_FSM.Status_Text :=
            'Recovery FSM idle';

    END_IF;

    GVL_Water_Runtime_Hardening.G_Recovery_FSM[L_i] :=
        L_FSM;

    // Runtime event publication.
    IF L_i <= 128 THEN

        L_Event := L_Empty_Event;
        L_Event.Runtime_Valid := TRUE;

        L_Event.Event_Time_MS := VI_System_Time_MS;
        L_Event.Event_Id := TO_UINT(L_i);

        IF L_FSM.Escalation_Required THEN
            L_Event.Event_Text :=
                'Water runtime escalation active';
        ELSE
            L_Event.Event_Text :=
                'Water runtime healthy';
        END_IF;

        GVL_Water_Runtime_Hardening.G_Event_Log[L_i] :=
            L_Event;

    END_IF;

    L_Any_Rollback :=
        L_Any_Rollback
        OR L_FSM.Rollback_Required;

    L_Any_Escalation :=
        L_Any_Escalation
        OR L_FSM.Escalation_Required;

END_FOR;

GVL_Water_Runtime_Hardening.G_Runtime_Quarantine_Active :=
    L_Any_Escalation;

GVL_Water_Runtime_Hardening.G_Service_Mode_Active := FALSE;
GVL_Water_Runtime_Hardening.G_Maintenance_Mode_Active := FALSE;

GVL_Water_Runtime_Hardening.G_Any_Rollback_Required :=
    L_Any_Rollback;

GVL_Water_Runtime_Hardening.G_Any_Escalation_Required :=
    L_Any_Escalation;

GVL_Water_Runtime_Hardening.G_Runtime_Valid := TRUE;
GVL_Water_Runtime_Hardening.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Escalation THEN
    GVL_Water_Runtime_Hardening.G_Status_Code := 2;
    GVL_Water_Runtime_Hardening.G_Status_Text :=
        'Runtime quarantine escalation active';
ELSIF L_Any_Rollback THEN
    GVL_Water_Runtime_Hardening.G_Status_Code := 1;
    GVL_Water_Runtime_Hardening.G_Status_Text :=
        'Recovery rollback active';
ELSE
    GVL_Water_Runtime_Hardening.G_Status_Code := 0;
    GVL_Water_Runtime_Hardening.G_Status_Text :=
        'Production runtime hardening active';
END_IF;

// ======================================================
// MODBUS RTU DRIVER ORCHESTRATION
// ======================================================
// Responsibilities:
//   1. Detect active request.
//   2. Build TX frame.
//   3. Wait for physical RX frame.
//   4. Validate/parse RX frame.
//   5. Apply validated response.
//
// IMPORTANT:
//   Real serial exchange is still external.
//   Concrete RTU/COM implementation must:
//      - send G_TX_Frame
//      - fill G_RX_Frame
//      - set G_RX_Ready
// ======================================================

VO_Driver_Online := FALSE;
VO_Driver_Error := FALSE;
VO_Driver_Error_Code := 0;

GVL_MODBUS_RTU_BRIDGE.G_Driver_Online := FALSE;
GVL_MODBUS_RTU_BRIDGE.G_Driver_Error := FALSE;
GVL_MODBUS_RTU_BRIDGE.G_Driver_Error_Code := 0;

IF NOT VI_Enable THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;

    GVL_MODBUS_RTU_FRAME.G_TX_Ready := FALSE;
    GVL_MODBUS_RTU_FRAME.G_RX_Ready := FALSE;

    L_Exchange_In_Progress := FALSE;

    RETURN;
END_IF;

IF NOT VI_Driver_Attached THEN

    VO_Driver_Error := TRUE;
    VO_Driver_Error_Code := 16#0002;

    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error_Code := VO_Driver_Error_Code;

    IF GVL_MODBUS_RTU_BRIDGE.G_Request_Valid THEN

        GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := VO_Driver_Error_Code;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS :=
            VI_System_Time_MS;

    END_IF;

    L_Exchange_In_Progress := FALSE;

    RETURN;
END_IF;

// ======================================================
// REQUEST DETECTION
// ======================================================
L_Request_Active := GVL_MODBUS_RTU_BRIDGE.G_Request_Valid;

IF L_Request_Active THEN

    IF GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence <> L_Last_Sequence THEN

        L_Last_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

        L_Exchange_In_Progress := TRUE;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := TRUE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;

        // ==============================================
        // BUILD TX FRAME
        // ==============================================
        FB_TX_Builder(
            VI_Request_Valid := TRUE,
            VI_Slave_ID := GVL_MODBUS_RTU_BRIDGE.G_Request_Slave_ID,
            VI_Function_Code := GVL_MODBUS_RTU_BRIDGE.G_Request_Function_Code,
            VI_Start_Register := GVL_MODBUS_RTU_BRIDGE.G_Request_Start_Register,
            VI_Register_Count := GVL_MODBUS_RTU_BRIDGE.G_Request_Register_Count,
            VI_Write_Value := GVL_MODBUS_RTU_BRIDGE.G_Request_Write_Value
        );

        IF FB_TX_Builder.VO_Error THEN

            GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code :=
                FB_TX_Builder.VO_Error_Code;

            GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence :=
                GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

            GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS :=
                VI_System_Time_MS;

            L_Exchange_In_Progress := FALSE;

            RETURN;

        END_IF;

        GVL_MODBUS_RTU_FRAME.G_TX_Frame :=
            FB_TX_Builder.VO_Frame;

        GVL_MODBUS_RTU_FRAME.G_TX_Ready := TRUE;
        GVL_MODBUS_RTU_FRAME.G_Last_TX_MS := VI_System_Time_MS;

    END_IF;

END_IF;

// ======================================================
// RX FRAME AVAILABLE
// ======================================================
IF L_Exchange_In_Progress AND
   GVL_MODBUS_RTU_FRAME.G_RX_Ready THEN

    // ==================================================
    // PARSE RX FRAME
    // ==================================================
    FB_RX_Parser(
        VI_Frame := GVL_MODBUS_RTU_FRAME.G_RX_Frame,
        VI_Expected_Slave_ID :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Slave_ID,
        VI_Expected_Function :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Function_Code
    );

    // ==================================================
    // APPLY RESPONSE
    // ==================================================
    FB_Response_Apply(
        VI_Request_Valid := TRUE,
        VI_Request_Index := GVL_MODBUS_RTU_BRIDGE.G_Request_Index,
        VI_Request_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence,
        VI_Parser_Valid := FB_RX_Parser.VO_Valid,
        VI_Parser_Error := FB_RX_Parser.VO_Error,
        VI_Parser_Error_Code := FB_RX_Parser.VO_Error_Code,
        VI_Register_Count := FB_RX_Parser.VO_Register_Count,
        VI_Register_Value := FB_RX_Parser.VO_Register_Value,
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF FB_Response_Apply.VO_Response_Applied THEN

        L_Last_Success_MS := VI_System_Time_MS;

        GVL_MODBUS_RTU_FRAME.G_RX_Ready := FALSE;

        L_Exchange_In_Progress := FALSE;

    END_IF;

END_IF;

// ======================================================
// DRIVER ONLINE STATE
// ======================================================
IF (L_Last_Success_MS > 0) AND
   ((VI_System_Time_MS - L_Last_Success_MS) <
    GVL_CONFIG.G_OpenTherm_Heartbeat_Timeout_MS) THEN

    VO_Driver_Online := TRUE;

    GVL_MODBUS_RTU_BRIDGE.G_Driver_Online := TRUE;

END_IF;

// ======================================================
// CLEAR IDLE BUSY STATE
// ======================================================
IF NOT L_Request_Active THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;

    L_Exchange_In_Progress := FALSE;

END_IF;

// ==============================================================================
// Heating runtime state publication phase
// Owns publication of finalized runtime outputs into global state/status layers.
// Does NOT calculate heating logic and does NOT mutate outputs.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_STATE.G_Zone_Valves[L_i] := VI_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATE.G_Manifold_Pumps[L_i] := VI_Manifold_Pumps[L_i];
    GVL_STATE.G_Manifold_Valves[L_i] := VI_Manifold_Valves[L_i];
    GVL_STATUS.G_Manifold_Status[L_i] := VI_Manifold_Status[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    GVL_STATE.G_Boiler_OT_Enable[L_i] := VI_Boiler_OT_Enable[L_i];
    GVL_STATE.G_Boiler_OT_Setpoint[L_i] := VI_Boiler_OT_Setpoint[L_i];
    GVL_STATUS.G_Boiler_Status[L_i] := VI_Boiler_Status[L_i];
END_FOR;

GVL_STATE.G_Backup_Circulation_Pump := VI_Backup_Circulation_Pump;
GVL_STATE.G_Electric_Heater_Enable := VI_Electric_Heater_Enable;
GVL_STATE.G_Safety_Freeze_Risk := VI_Freeze_Risk_Status;
GVL_STATE.G_DHW_Heating_Pump := VI_DHW_Heating_Pump;
GVL_STATE.G_DHW_Circ_Pump := VI_DHW_Circ_Pump;
GVL_STATUS.G_DHW_Status := VI_DHW_Status;

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_State_Publication_Phase <<<

IF NOT GVL_TRACE.G_Trace_Enabled THEN RETURN; END_IF;

L_Index := GVL_TRACE.G_Trace_Write_Index;

GVL_TRACE.G_Trace_Buffer[L_Index].Timestamp_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_TRACE.G_Trace_Buffer[L_Index].Layer := iLayer;
GVL_TRACE.G_Trace_Buffer[L_Index].Source := iSource;
GVL_TRACE.G_Trace_Buffer[L_Index].Reason_Code := iReason;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Bool := iValueBool;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Real := iValueReal;
GVL_TRACE.G_Trace_Buffer[L_Index].Text := iText;

L_Index := L_Index + 1;
IF L_Index > 200 THEN L_Index := 1; END_IF;

GVL_TRACE.G_Trace_Write_Index := L_Index;

// ==============================================================================
// Heating runtime predictive correlation weighting engine
// Read-only predictive adaptive correlation layer.
// ==============================================================================



VO_Correlation_Score := 0;
VO_Correlation_Degraded := FALSE;

VO_Status_Code := 0;
VO_Status_Text := 'Heating predictive correlation engine disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// SAFE ARITHMETIC
// ======================================================
L_Total :=
    TO_UDINT(VI_Runtime_Risk) +
    TO_UDINT(VI_Cascade_Risk) +
    TO_UDINT(VI_OT_Risk);

VO_Correlation_Score :=
    TO_UINT(L_Total / 3);

// ======================================================
// CORRELATION ANALYSIS
// ======================================================
IF VO_Correlation_Score > 70 THEN
    VO_Correlation_Degraded := TRUE;

    VO_Status_Code := 900;
    VO_Status_Text := 'Heating predictive correlation critical';

ELSIF VO_Correlation_Score > 40 THEN
    VO_Correlation_Degraded := TRUE;

    VO_Status_Code := 200;
    VO_Status_Text := 'Heating predictive correlation degraded';

ELSE
    VO_Status_Code := 1;
    VO_Status_Text := 'Heating predictive correlation nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Predictive_Correlation_Weighting_Engine <<<

VO_Event_Pulse := FALSE;
VO_Event_Code := 0;
VO_Event_Value := 0.0;

// 1. Детекция новых тревог (антидребезг + передний фронт)
T_Debounce_Gas(IN := VI_Gas_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Fire(IN := VI_Fire_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Flood(IN := VI_Flood_Alarm, PT := T#500ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Security(IN := VI_Security_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);

R_Trig_Gas(CLK := T_Debounce_Gas.Q);
R_Trig_Fire(CLK := T_Debounce_Fire.Q);
R_Trig_Flood(CLK := T_Debounce_Flood.Q);
R_Trig_Security(CLK := T_Debounce_Security.Q);
R_Trig_First_Fault(CLK := VI_First_Fault_Active);
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    R_Trig_Boiler[L_i](CLK := VI_Boiler_Errors[L_i]);
END_FOR;

// 2. Добавление новых тревог в список (Кольцевой буфер)
L_Pending_Count := 0;
L_Event_Pulse_Latched := FALSE;

IF R_Trig_Gas.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Gas';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Критическая концентрация газа!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Fire.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Fire';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружено задымление!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Flood.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Flood';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружена протечка воды!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Security.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Security';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := VI_Security_Msg;
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_First_Fault.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Diagnostics';
    L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(VI_First_Fault_Source);

    CASE VI_First_Fault_Type OF
        1: L_First_Fault_Type_Text := 'IO';
        2: L_First_Fault_Type_Text := 'Sensor';
        3: L_First_Fault_Type_Text := 'Comm';
        4: L_First_Fault_Type_Text := 'Subsystem';
        ELSE L_First_Fault_Type_Text := 'Unknown';
    END_CASE;

    CASE VI_First_Fault_Source OF
        1: L_First_Fault_Source_Text := 'Heating';
        2: L_First_Fault_Source_Text := 'DHW';
        3: L_First_Fault_Source_Text := 'Ventilation';
        4: L_First_Fault_Source_Text := 'Lighting';
        5: L_First_Fault_Source_Text := 'Access';
        ELSE L_First_Fault_Source_Text := 'Unknown';
    END_CASE;

    L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Diagnostics root cause: ', CONCAT(L_First_Fault_Source_Text, CONCAT(' / ', L_First_Fault_Type_Text)));
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF R_Trig_Boiler[L_j].Q AND L_Pending_Count < 10 THEN
        L_Pending_Count := L_Pending_Count + 1;
        L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
        L_Pending_Alarms[L_Pending_Count].Source := 'Boiler';
        L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(L_j);
        L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Авария котла №', INT_TO_STRING(L_j));
        L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
        L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
        L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
    END_IF;
END_FOR;

// Обработка очереди новых тревог с учетом приоритетов
FOR L_i := 1 TO L_Pending_Count DO

    L_Target_Slot := 0;

    // 1. Ищем пустой слот
    FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_k].ID = 0 THEN
            L_Target_Slot := L_k;
            EXIT;
        END_IF;
    END_FOR;

    // 2. Ищем квитированную тревогу с наименьшим приоритетом
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF VO_Alarm_List[L_k].Is_Acknowledged AND TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    // 3. Ищем неквитированную тревогу с наименьшим приоритетом (если он ниже добавляемой)
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri AND TO_INT(VO_Alarm_List[L_k].Severity) < TO_INT(L_Pending_Alarms[L_i].Severity) THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    IF L_Target_Slot = 0 THEN 
        // Буфер полон критических неквитированных тревог. Не затираем!
        CONTINUE; 
    END_IF;

    VO_Alarm_List[L_Target_Slot] := L_Pending_Alarms[L_i];
    VO_Alarm_List[L_Target_Slot].ID := VIO_Next_Alarm_ID;
    VIO_Next_Alarm_ID := VIO_Next_Alarm_ID + 1;
    IF VIO_Next_Alarm_ID = 0 THEN VIO_Next_Alarm_ID := 1; END_IF;
    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1203;
        VO_Event_Value := TO_REAL(VO_Alarm_List[L_Target_Slot].Severity);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_FOR;

// 3. Обновление статуса существующих тревог (ушли ли они?)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Source = 'Gas' THEN VO_Alarm_List[L_i].Is_Active := VI_Gas_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Fire' THEN VO_Alarm_List[L_i].Is_Active := VI_Fire_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Flood' THEN VO_Alarm_List[L_i].Is_Active := VI_Flood_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Security' THEN VO_Alarm_List[L_i].Is_Active := VI_Security_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Diagnostics' THEN VO_Alarm_List[L_i].Is_Active := VI_First_Fault_Active;
        ELSIF VO_Alarm_List[L_i].Source = 'Boiler' THEN 
            IF TO_INT(VO_Alarm_List[L_i].Source_ID) >= 1 AND TO_INT(VO_Alarm_List[L_i].Source_ID) <= GVL_CONSTANTS.C_MAX_BOILERS THEN
                VO_Alarm_List[L_i].Is_Active := VI_Boiler_Errors[TO_INT(VO_Alarm_List[L_i].Source_ID)];
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 4. Квитирование тревог
IF VI_Acknowledge_All THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_i].ID <> 0 THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1201;
        VO_Event_Value := TO_REAL(VO_Unacked_Count);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_IF;

// 4.5 Автоквитирование некритичных тревог, если они больше не активны
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
        IF VO_Alarm_List[L_i].Severity <> E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 5. Очистка списка (удаление неактивных И квитированных тревог)
// В кольцевом буфере мы просто помечаем слот как пустой (ID = 0), без сдвига массива
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND VO_Alarm_List[L_i].Is_Acknowledged THEN
        // Удаляем тревогу
        VO_Alarm_List[L_i].ID := 0;
        IF NOT L_Event_Pulse_Latched THEN
            VO_Event_Pulse := TRUE;
            VO_Event_Code := 1202;
            VO_Event_Value := 0.0;
            L_Event_Pulse_Latched := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 6. Подсчет статистики и формирование глобальных флагов
VO_Global_Critical := FALSE;
VO_Global_Warning := FALSE;
VO_Siren_Active := FALSE;
VO_Active_Count := 0;
VO_Unacked_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Is_Active THEN
            VO_Active_Count := VO_Active_Count + 1;
        END_IF;

        IF NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
            VO_Unacked_Count := VO_Unacked_Count + 1;

            IF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
                VO_Global_Critical := TRUE;
                // Сирена работает только для активных неквитированных критических тревог, если не включен Mute
                IF VO_Alarm_List[L_i].Is_Active AND NOT VI_Mute_Siren THEN
                    VO_Siren_Active := TRUE;
                END_IF;
            ELSIF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH THEN
                VO_Global_Warning := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Alarm_Manager <<<

IF NOT VI_Enable THEN
    GVL_Distributed_Recovery_Lock.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Lock := GVL_Distributed_Recovery_Lock.G_Recovery_Lock;

L_Lock.Runtime_System_Time_MS := VI_System_Time_MS;
L_Lock.Lock_Valid := TRUE;

// Finalized runtime continuity proof chain.
L_Finalized_Runtime_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

// Cluster-exclusive recovery execution lock.
IF GVL_Distributed_Runtime.G_Split_Brain_Suspected
   OR GVL_Distributed_Projection_Ownership.G_Any_Ownership_Conflict
   OR GVL_Runtime_Sessions.G_Any_Stale_Session
   OR NOT L_Finalized_Runtime_Continuity THEN

    L_Lock.Lock_Conflict := TRUE;
    L_Lock.Distributed_Execution_Allowed := FALSE;

    GVL_Distributed_Recovery_Lock.G_Recovery_Execution_Blocked := TRUE;
    GVL_Distributed_Recovery_Lock.G_Rollback_Execution_Blocked := TRUE;
    GVL_Distributed_Recovery_Lock.G_Reopen_Execution_Blocked := TRUE;

    L_Lock.Status_Code := 3;
    L_Lock.Status_Text :=
        'Distributed recovery execution locked';

ELSE

    L_Lock.Recovery_Lock_Active := TRUE;
    L_Lock.Distributed_Execution_Allowed := TRUE;

    GVL_Distributed_Recovery_Lock.G_Recovery_Execution_Blocked := FALSE;
    GVL_Distributed_Recovery_Lock.G_Rollback_Execution_Blocked := FALSE;
    GVL_Distributed_Recovery_Lock.G_Reopen_Execution_Blocked := FALSE;

    L_Lock.Status_Code := 0;
    L_Lock.Status_Text :=
        'Distributed recovery lock healthy';

END_IF;

GVL_Distributed_Recovery_Lock.G_Recovery_Lock := L_Lock;

GVL_Distributed_Recovery_Lock.G_Runtime_Valid := TRUE;
GVL_Distributed_Recovery_Lock.G_Last_Update_MS :=
    VI_System_Time_MS;

GVL_Distributed_Recovery_Lock.G_Status_Code :=
    L_Lock.Status_Code;

GVL_Distributed_Recovery_Lock.G_Status_Text :=
    L_Lock.Status_Text;

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block owns predictive preheat decision only.
// It does NOT modify thermal demand. Thermal demand is owned by
// FB_Heating_Thermal_Model and may be interpreted by downstream advisory layers.
// ==============================================================================

L_Now_TOD := GVL_TIME_SERVICE.G_Time_Of_Day_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_Time_To_Heat := GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i];
    L_Time_To_Comfort := GVL_HEATING_POLICY.G_Zone_Comfort_Time_MS[L_i];

    // Predictive preheat decision.
    IF GVL_HEATING_POLICY.G_Zone_Schedule_Enabled[L_i] THEN

        IF L_Time_To_Comfort > L_Now_TOD THEN
            IF (L_Time_To_Comfort - L_Now_TOD) <= L_Time_To_Heat THEN
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := TRUE;
            ELSE
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
            END_IF;
        END_IF;

    END_IF;

    // Confidence gating.
    IF GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] < 0.1 THEN
        GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
    END_IF;

END_FOR;

// reset
VO_Block_Heating := FALSE;
VO_Block_Ventilation := FALSE;
VO_Block_Lighting := FALSE;
VO_Block_Sockets := FALSE;
VO_System_Degraded := FALSE;
VO_Code := 0;

// FIRE has highest priority. Safety-stop ownership remains in PRG_Safety.
IF VI_Fire_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Ventilation := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 100;
    RETURN;
END_IF;

// GAS has higher priority than behavior mode.
IF VI_Gas_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Lighting := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 200;
    RETURN;
END_IF;

// LEAK blocks heating but does not suppress later degradation/mode overlays.
IF VI_Leak_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Code := 300;
END_IF;

// IO degraded blocks heating and marks system degraded.
IF VI_IO_Degraded THEN
    VO_System_Degraded := TRUE;
    VO_Block_Heating := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 400;
    END_IF;
END_IF;

// Ownership violation marks system degraded. Test/result handler owns any safe-stop reaction.
IF VI_Ownership_Violation THEN
    VO_System_Degraded := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 500;
    END_IF;
END_IF;

// Behavior mode overlays. These are lower priority than safety/system faults.
CASE VI_Behavior_Mode OF
    BEHAVIOR_AWAY:
        VO_Block_Lighting := TRUE;
        VO_Block_Sockets := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 600;
        END_IF;

    BEHAVIOR_NIGHT:
        VO_Block_Lighting := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 700;
        END_IF;

    BEHAVIOR_MAINTENANCE:
        VO_Block_Heating := TRUE;
        VO_Block_Ventilation := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 800;
        END_IF;
ELSE
        // No fallback required
END_CASE;

IF NOT VI_Enable THEN
    GVL_Water_Hydraulic_Graph.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Shared_Trunk := FALSE;
L_Any_Conflict := FALSE;
L_Any_Fallback := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Validation :=
        GVL_Water_Topology_Validation.G_Validation_State[L_i];

    // Graph edge publication.
    L_Edge := L_Empty_Edge;
    L_Edge.Runtime_Valid := TRUE;

    L_Edge.Edge_Id := TO_UINT(L_i);

    L_Edge.Upstream_Segment_Id :=
        GVL_Water_Hydraulic_Topology.G_Topology_Node[L_i].Hydraulic_Segment_Id;

    L_Edge.Downstream_Segment_Id :=
        GVL_Water_Hydraulic_Topology.G_Topology_Node[L_i].Hydraulic_Zone_Id;

    L_Edge.Isolation_Group_Id :=
        GVL_Water_Hydraulic_Topology.G_Topology_Node[L_i].Isolation_Group_Id;

    L_Edge.Valve_Group_Id :=
        GVL_Water_Hydraulic_Topology.G_Topology_Node[L_i].Valve_Group_Id;

    // Shared trunk semantics.
    IF L_Edge.Valve_Group_Id = 3 THEN
        L_Edge.Shared_Trunk := TRUE;
        L_Edge.Cross_Zone_Dependency := TRUE;
    END_IF;

    L_Edge.Dependency_Valid :=
        L_Validation.Topology_Valid;

    L_Edge.Dependency_Ambiguous :=
        L_Validation.Topology_Ambiguous;

    L_Edge.Selective_Isolation_Allowed :=
        L_Validation.Selective_Isolation_Allowed;

    L_Edge.Global_Fallback_Required :=
        L_Validation.Global_Fallback_Required;

    // Isolation path runtime.
    L_Path := L_Empty_Path;
    L_Path.Runtime_Valid := TRUE;

    L_Path.Runtime_System_Time_MS :=
        VI_System_Time_MS;

    L_Path.Sensor_Id := TO_UINT(L_i);

    L_Path.Isolation_Path_Valid :=
        L_Edge.Dependency_Valid;

    L_Path.Isolation_Path_Ambiguous :=
        L_Edge.Dependency_Ambiguous;

    L_Path.Active_Isolation_Group_Id :=
        L_Edge.Isolation_Group_Id;

    L_Path.Active_Valve_Group_Id :=
        L_Edge.Valve_Group_Id;

    L_Path.Shared_Trunk_Impact :=
        L_Edge.Shared_Trunk;

    L_Path.Cross_Zone_Impact :=
        L_Edge.Cross_Zone_Dependency;

    L_Path.Selective_Isolation_Allowed :=
        L_Edge.Selective_Isolation_Allowed;

    L_Path.Global_Fallback_Required :=
        L_Edge.Global_Fallback_Required;

    // Multi-valve/shared-trunk path.
    IF L_Path.Shared_Trunk_Impact THEN
        L_Path.Multi_Valve_Path := TRUE;
    END_IF;

    // Conflict detection.
    IF L_Path.Isolation_Path_Ambiguous THEN
        L_Path.Conflict_Detected := TRUE;
    END_IF;

    // Conservative escalation.
    IF L_Path.Conflict_Detected THEN
        L_Path.Global_Fallback_Required := TRUE;
        L_Path.Selective_Isolation_Allowed := FALSE;

        L_Path.Status_Code := 2;
        L_Path.Status_Text :=
            'Isolation path conflict detected';

    ELSIF L_Path.Shared_Trunk_Impact THEN
        L_Path.Status_Code := 1;
        L_Path.Status_Text :=
            'Shared trunk isolation path active';

    ELSE
        L_Path.Status_Code := 0;
        L_Path.Status_Text :=
            'Isolation path resolved';
    END_IF;

    GVL_Water_Hydraulic_Graph.G_Topology_Edge[L_i] :=
        L_Edge;

    GVL_Water_Hydraulic_Graph.G_Isolation_Path[L_i] :=
        L_Path;

    L_Any_Shared_Trunk :=
        L_Any_Shared_Trunk
        OR L_Path.Shared_Trunk_Impact;

    L_Any_Conflict :=
        L_Any_Conflict
        OR L_Path.Conflict_Detected;

    L_Any_Fallback :=
        L_Any_Fallback
        OR L_Path.Global_Fallback_Required;

END_FOR;

GVL_Water_Hydraulic_Graph.G_Any_Shared_Trunk :=
    L_Any_Shared_Trunk;

GVL_Water_Hydraulic_Graph.G_Any_Conflict :=
    L_Any_Conflict;

GVL_Water_Hydraulic_Graph.G_Any_Global_Fallback_Required :=
    L_Any_Fallback;

GVL_Water_Hydraulic_Graph.G_Runtime_Valid := TRUE;
GVL_Water_Hydraulic_Graph.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Conflict THEN
    GVL_Water_Hydraulic_Graph.G_Status_Code := 2;
    GVL_Water_Hydraulic_Graph.G_Status_Text :=
        'Hydraulic graph conflicts detected';
ELSIF L_Any_Shared_Trunk THEN
    GVL_Water_Hydraulic_Graph.G_Status_Code := 1;
    GVL_Water_Hydraulic_Graph.G_Status_Text :=
        'Shared trunk governance active';
ELSE
    GVL_Water_Hydraulic_Graph.G_Status_Code := 0;
    GVL_Water_Hydraulic_Graph.G_Status_Text :=
        'Hydraulic graph runtime healthy';
END_IF;

VO_Ownership_Violation := FALSE;

// Gas: signal present, alarm disappeared
IF (VI_Gas_Level > 20.0) AND L_Last_Gas_Alarm AND (NOT VI_Gas_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Leak: once latched should not drop instantly
IF L_Last_Leak_Alarm AND (NOT VI_Leak_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Smoke: same rule
IF L_Last_Smoke_Alarm AND (NOT VI_Smoke_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

L_Last_Gas_Alarm := VI_Gas_Alarm;
L_Last_Leak_Alarm := VI_Leak_Alarm;
L_Last_Smoke_Alarm := VI_Smoke_Alarm;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

CASE L_State OF
    0: // Ожидание
        VO_Test_Active := FALSE;
        L_Need_Test := FALSE;

        // Поиск клапана, которому нужен тест (раз в неделю)
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF VI_Config[L_i].enabled AND ((VI_System_Time_MS - L_Last_Test_Time[L_i]) > (VI_Config[L_i].test_interval_days * 86400000)) THEN
                L_Current_Valve := L_i;
                L_Need_Test := TRUE;
                EXIT;
            END_IF;
        END_FOR;

        IF L_Need_Test THEN
            L_State := 1;
            L_Test_Start_Time := VI_System_Time_MS;
            VO_Test_Active := TRUE;
            VO_Current_Valve := L_Current_Valve;
            VO_Valve_Cmd[L_Current_Valve] := TRUE; // Открываем
            VO_Status_Msg := CONCAT('ТЕСТ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));
            VO_Test_Results[L_Current_Valve] := TRUE; // Сброс результата
        END_IF;

    1: // Тестирование (ожидание открытия)
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик сработал до истечения таймаута
            // Проверка тока
            IF ABS(VI_Valve_Currents[L_Current_Valve] - VI_Config[L_Current_Valve].Nominal_Current) > (VI_Config[L_Current_Valve].Nominal_Current * 0.2) THEN
                VO_Test_Results[L_Current_Valve] := FALSE; // Ошибка по току
            END_IF;

            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := VO_Test_Results[L_Current_Valve];

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер для проверки закрытия
            L_State := 2;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут открытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: ЗАКЛИНИВАНИЕ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер
            L_State := 2;
        END_IF;

    2: // Ожидание закрытия
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF NOT VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик разомкнулся (клапан закрыт)
            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
            IF VO_Test_Results[L_Current_Valve] THEN
                VO_Status_Msg := 'ТЕСТ ЗАВЕРШЕН УСПЕШНО';
            END_IF;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут закрытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: НЕ ЗАКРЫЛСЯ КЛАПАН ', INT_TO_STRING(L_Current_Valve));

            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
        END_IF;
ELSE
        // No fallback required
END_CASE;

L_Cycle_Time_Safe := VI_Cycle_Time_S;
IF L_Cycle_Time_Safe <= REAL#0.0 THEN
    L_Cycle_Time_Safe := REAL#0.01;
END_IF;

VO_Error := VI_SetPoint - VI_ProcessValue;
IF ABS(VO_Error) < VI_Deadband THEN
    VO_Error := REAL#0.0;
END_IF;

IF VI_Reset THEN
    L_Integral_Sum := REAL#0.0;
    L_Prev_Error := REAL#0.0;
    VO_Output := LIMIT(VI_Y_Min, REAL#0.0, VI_Y_Max);
    VO_Limiting := FALSE;
    RETURN;
END_IF;

L_P_Term := VI_Kp * VO_Error;

IF VI_Tv > REAL#0.0 THEN
    L_Derivative := (VO_Error - L_Prev_Error) / L_Cycle_Time_Safe;
    L_D_Term := VI_Kp * VI_Tv * L_Derivative;
ELSE
    L_Derivative := REAL#0.0;
    L_D_Term := REAL#0.0;
END_IF;

IF VI_Manual_Mode THEN
    VO_Output := LIMIT(VI_Y_Min, VI_Manual_Value, VI_Y_Max);
    L_Integral_Sum := VO_Output - L_P_Term - L_D_Term;
    L_Prev_Error := VO_Error;
    VO_Limiting := (VO_Output <= VI_Y_Min) OR (VO_Output >= VI_Y_Max);
    RETURN;
END_IF;

IF VI_Tn > REAL#0.0 THEN
    L_I_Candidate := L_Integral_Sum + ((VI_Kp / VI_Tn) * VO_Error * L_Cycle_Time_Safe);
ELSE
    L_I_Candidate := L_Integral_Sum;
END_IF;

L_Output_Predicted := L_P_Term + L_I_Candidate + L_D_Term;

// Anti-windup: accept the new integral only if it does not push the output farther into saturation.
IF VI_Tn > REAL#0.0 THEN
    IF (L_Output_Predicted > VI_Y_Max) AND (VO_Error > REAL#0.0) THEN
        // hold integral
    ELSIF (L_Output_Predicted < VI_Y_Min) AND (VO_Error < REAL#0.0) THEN
        // hold integral
    ELSE
        L_Integral_Sum := L_I_Candidate;
    END_IF;
END_IF;

L_Output_Raw := L_P_Term + L_Integral_Sum + L_D_Term;
VO_Output := LIMIT(VI_Y_Min, L_Output_Raw, VI_Y_Max);
VO_Limiting := (L_Output_Raw > VI_Y_Max) OR (L_Output_Raw < VI_Y_Min);
L_Prev_Error := VO_Error;

// >>> BULK_SYNC_ANCHOR: FB_PID_Controller <<<

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_TX_Index := UDINT_TO_UINT(GVL_Runtime_Bus.G_Last_Sequence_Id);

IF (L_TX_Index >= 1)
   AND (L_TX_Index <= 128) THEN

    L_Frame := GVL_Runtime_Bus.G_TX_Frames[L_TX_Index];

    IF L_Frame.Frame_Valid THEN

        IF GVL_Distributed_Authority.G_Distributed_Safety_Barrier_OK
           AND GVL_Runtime_Sessions.G_Runtime_Valid
           AND NOT GVL_Runtime_Sessions.G_Any_Stale_Session
           AND NOT GVL_Runtime_Sessions.G_Any_Quarantined_Session THEN

            L_Frame.Frame_Ack_Received := TRUE;
            L_Frame.Replication_Consistent := TRUE;
            L_Frame.Replication_Rejected := FALSE;
            L_Frame.Status_Code := 0;

        ELSE

            L_Frame.Frame_Ack_Received := FALSE;
            L_Frame.Replication_Consistent := FALSE;
            L_Frame.Replication_Rejected := TRUE;
            L_Frame.Status_Code := 2;

        END_IF;

        GVL_Runtime_Bus.G_TX_Frames[L_TX_Index] := L_Frame;
        GVL_Runtime_Bus.G_TX_Healthy := L_Frame.Replication_Consistent;
        GVL_Runtime_Bus.G_Any_Replication_Rejected := L_Frame.Replication_Rejected;

    END_IF;

END_IF;

L_Found_Index := 0;
L_Was_Active := FALSE;
FOR L_i := 1 TO 50 DO
    IF (VIO_Events[L_i].Code = VI_Code) AND (VIO_Events[L_i].Source = VI_Source) THEN
        L_Found_Index := L_i;
        L_Was_Active := VIO_Events[L_i].Active;
        EXIT;
    END_IF;
END_FOR;

L_Debounce_Index := 0;
L_Oldest_Time := 16#FFFFFFFF;
L_Oldest_Index := 1;

FOR L_i := 1 TO 50 DO
    IF L_Debounce_Used[L_i] THEN
        IF (L_Debounce_Code[L_i] = VI_Code) AND (L_Debounce_Source[L_i] = VI_Source) THEN
            L_Debounce_Index := L_i;
            EXIT;
        END_IF;
        IF L_Debounce_Last_Change_Time[L_i] < L_Oldest_Time THEN
            L_Oldest_Time := L_Debounce_Last_Change_Time[L_i];
            L_Oldest_Index := L_i;
        END_IF;
    ELSE
        L_Debounce_Index := L_i;
        EXIT;
    END_IF;
END_FOR;

IF L_Debounce_Index = 0 THEN
    L_Debounce_Index := L_Oldest_Index;
END_IF;

IF NOT L_Debounce_Used[L_Debounce_Index] OR
   (L_Debounce_Code[L_Debounce_Index] <> VI_Code) OR
   (L_Debounce_Source[L_Debounce_Index] <> VI_Source) THEN
    L_Debounce_Used[L_Debounce_Index] := TRUE;
    L_Debounce_Code[L_Debounce_Index] := VI_Code;
    L_Debounce_Source[L_Debounce_Index] := VI_Source;
    L_Debounce_Last_Input_State[L_Debounce_Index] := VI_Active;
    L_Debounce_Stable_State[L_Debounce_Index] := FALSE;
    L_Debounce_Last_Change_Time[L_Debounce_Index] := VI_Timestamp;
END_IF;

IF VI_Active <> L_Debounce_Last_Input_State[L_Debounce_Index] THEN
    L_Debounce_Last_Input_State[L_Debounce_Index] := VI_Active;
    L_Debounce_Last_Change_Time[L_Debounce_Index] := VI_Timestamp;
END_IF;

IF (VI_Timestamp - L_Debounce_Last_Change_Time[L_Debounce_Index]) > 2000 THEN
    L_Debounce_Stable_State[L_Debounce_Index] := L_Debounce_Last_Input_State[L_Debounce_Index];
END_IF;

L_Stable_State := L_Debounce_Stable_State[L_Debounce_Index];

IF L_Stable_State THEN
    IF NOT L_Was_Active THEN
        L_Index := (VIO_Count MOD 50) + 1;
        VIO_Events[L_Index].Code := VI_Code;
        VIO_Events[L_Index].Severity := VI_Severity;
        VIO_Events[L_Index].Active := TRUE;
        VIO_Events[L_Index].Timestamp := VI_Timestamp;
        VIO_Events[L_Index].Source := VI_Source;
        VIO_Count := VIO_Count + 1;
    ELSIF L_Found_Index > 0 THEN
        VIO_Events[L_Found_Index].Severity := VI_Severity;
    END_IF;
ELSE
    IF L_Found_Index > 0 THEN
        VIO_Events[L_Found_Index].Active := FALSE;
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Diagnostics_Event_Manager <<<

IF NOT VI_Enable THEN
    GVL_Water_Valve_Runtime.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Degraded := FALSE;
L_Any_Confirmation_Unknown := FALSE;
L_Any_Unsafe_Reopen := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Authority :=
        GVL_Water_Isolation_Authority.G_Authority_State[L_i];

    L_Valve := L_Empty_Valve;
    L_Valve.Runtime_Valid := TRUE;

    L_Valve.Runtime_System_Time_MS := VI_System_Time_MS;

    L_Valve.Valve_Id := L_Authority.Valve_Group_Id;
    L_Valve.Valve_Group_Id := L_Authority.Valve_Group_Id;

    L_Valve.Close_Requested :=
        L_Authority.Selective_Authority_Allowed
        OR L_Authority.Global_Fallback_Required;

    L_Valve.Global_Fallback_Request :=
        L_Authority.Global_Fallback_Required;

    L_Valve.Selective_Authority_Allowed :=
        L_Authority.Selective_Authority_Allowed;

    // Observe-only compatibility visibility.
    L_Valve.Physical_Output_Active :=
        GVL_COMMAND_SHADOW.G_Close_Valve_35
        OR GVL_COMMAND_SHADOW.G_Close_Valve_36;

    L_Valve.Output_Command_Projected :=
        L_Valve.Close_Requested;

    // Feedback/runtime hooks.
    L_Valve.Confirmation_Available :=
        GVL_Water_Valve_Feedback.G_Valve_Feedback_State[L_i].Feedback_Available;

    IF L_Valve.Confirmation_Available THEN

        L_Valve.Confirmed_Closed :=
            GVL_Water_Valve_Feedback.G_Valve_Feedback_State[L_i].Confirmed_Closed;

    ELSE

        L_Valve.Confirmation_Unknown := TRUE;

    END_IF;

    // Observe-only semantics must not force degraded state.
    L_Valve.Diagnostics_Available := FALSE;
    L_Valve.Valve_Healthy := TRUE;

    IF L_Valve.Confirmation_Available
       AND NOT L_Valve.Confirmed_Closed
       AND L_Valve.Close_Requested THEN

        L_Valve.Valve_Degraded := TRUE;

    END_IF;

    IF L_Valve.Valve_Degraded THEN

        L_Valve.Unsafe_Reopen_Denied := TRUE;
        L_Valve.Recovery_Allowed := FALSE;

        L_Valve.Status_Code := 2;
        L_Valve.Status_Text :=
            'Recovery denied: valve degraded';

    ELSIF L_Valve.Confirmation_Unknown THEN

        L_Valve.Status_Code := 1;
        L_Valve.Status_Text :=
            'Valve confirmation unavailable';

    ELSE

        L_Valve.Status_Code := 0;
        L_Valve.Status_Text :=
            'Valve governance runtime healthy';

    END_IF;

    GVL_Water_Valve_Runtime.G_Valve_Runtime_State[L_i] :=
        L_Valve;

    L_Any_Degraded :=
        L_Any_Degraded
        OR L_Valve.Valve_Degraded;

    L_Any_Confirmation_Unknown :=
        L_Any_Confirmation_Unknown
        OR L_Valve.Confirmation_Unknown;

    L_Any_Unsafe_Reopen :=
        L_Any_Unsafe_Reopen
        OR L_Valve.Unsafe_Reopen_Denied;

END_FOR;

GVL_Water_Valve_Runtime.G_Any_Valve_Degraded :=
    L_Any_Degraded;

GVL_Water_Valve_Runtime.G_Any_Confirmation_Unknown :=
    L_Any_Confirmation_Unknown;

GVL_Water_Valve_Runtime.G_Any_Unsafe_Reopen_Denied :=
    L_Any_Unsafe_Reopen;

GVL_Water_Valve_Runtime.G_Runtime_Valid := TRUE;
GVL_Water_Valve_Runtime.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Degraded THEN
    GVL_Water_Valve_Runtime.G_Status_Code := 2;
    GVL_Water_Valve_Runtime.G_Status_Text :=
        'Valve governance degraded';
ELSIF L_Any_Confirmation_Unknown THEN
    GVL_Water_Valve_Runtime.G_Status_Code := 1;
    GVL_Water_Valve_Runtime.G_Status_Text :=
        'Valve confirmation unknown';
ELSE
    GVL_Water_Valve_Runtime.G_Status_Code := 0;
    GVL_Water_Valve_Runtime.G_Status_Text :=
        'Valve governance runtime active';
END_IF;

IF NOT VI_Enable THEN
    GVL_Water_Output_Reconciliation.G_Runtime_Valid := FALSE;
    RETURN;
END_IF;

L_Any_Runtime_Mismatch := FALSE;
L_Any_Confirmation_Mismatch := FALSE;
L_Any_Conflict := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_Output := GVL_Water_Output_Projection.G_Output_Projection_State[L_i];
    L_Valve := GVL_Water_Valve_Runtime.G_Valve_Runtime_State[L_i];

    // Reset all reconciliation fields per sensor to prevent state leakage across loop iterations.
    L_State.Runtime_Valid := FALSE;
    L_State.Runtime_System_Time_MS := 0;
    L_State.Valve_Group_Id := 0;
    L_State.Projection_Active := FALSE;
    L_State.Runtime_Output_Active := FALSE;
    L_State.Expected_Closed := FALSE;
    L_State.Confirmed_Closed := FALSE;
    L_State.Confirmation_Unknown := FALSE;
    L_State.Reconciliation_Healthy := FALSE;
    L_State.Projection_Runtime_Mismatch := FALSE;
    L_State.Projection_Confirmation_Mismatch := FALSE;
    L_State.Conflict_Detected := FALSE;
    L_State.Topology_Invalid := FALSE;
    L_State.Status_Code := 0;
    L_State.Status_Text := '';

    L_State.Runtime_Valid := TRUE;
    L_State.Runtime_System_Time_MS := VI_System_Time_MS;

    L_State.Valve_Group_Id := L_Output.Valve_Group_Id;
    L_State.Projection_Active := L_Output.Physical_Close_Project;
    L_State.Runtime_Output_Active := L_Valve.Physical_Output_Active;
    L_State.Expected_Closed := L_Output.Expected_Closed;
    L_State.Confirmed_Closed := L_Valve.Confirmed_Closed;
    L_State.Confirmation_Unknown := L_Valve.Confirmation_Unknown;

    IF L_Valve.Confirmation_Available THEN

        IF L_State.Projection_Active <> L_State.Runtime_Output_Active THEN
            L_State.Projection_Runtime_Mismatch := TRUE;
        END_IF;

        IF L_State.Expected_Closed
           AND NOT L_State.Confirmed_Closed THEN
            L_State.Projection_Confirmation_Mismatch := TRUE;
        END_IF;

    END_IF;

    IF L_Output.Projection_Allowed
       AND L_Output.Projection_Denied THEN
        L_State.Conflict_Detected := TRUE;
    END_IF;

    IF L_Output.Valve_Group_Id = 0 THEN
        L_State.Topology_Invalid := TRUE;
    END_IF;

    L_State.Reconciliation_Healthy :=
        NOT L_State.Projection_Runtime_Mismatch
        AND NOT L_State.Projection_Confirmation_Mismatch
        AND NOT L_State.Conflict_Detected
        AND NOT L_State.Topology_Invalid;

    IF L_State.Conflict_Detected THEN
        L_State.Status_Code := 3;
        L_State.Status_Text := 'Projection conflict detected';
    ELSIF L_State.Projection_Runtime_Mismatch THEN
        L_State.Status_Code := 2;
        L_State.Status_Text := 'Projection runtime mismatch';
        L_Any_Runtime_Mismatch := TRUE;
    ELSIF L_State.Projection_Confirmation_Mismatch THEN
        L_State.Status_Code := 1;
        L_State.Status_Text := 'Projection confirmation mismatch';
        L_Any_Confirmation_Mismatch := TRUE;
    ELSE
        L_State.Status_Code := 0;
        L_State.Status_Text := 'Reconciliation healthy';
    END_IF;

    IF L_State.Conflict_Detected THEN
        L_Any_Conflict := TRUE;
    END_IF;

    GVL_Water_Output_Reconciliation.G_Reconciliation_State[L_i] := L_State;
END_FOR;

GVL_Water_Output_Reconciliation.G_Any_Runtime_Mismatch := L_Any_Runtime_Mismatch;
GVL_Water_Output_Reconciliation.G_Any_Confirmation_Mismatch := L_Any_Confirmation_Mismatch;
GVL_Water_Output_Reconciliation.G_Any_Conflict_Detected := L_Any_Conflict;
GVL_Water_Output_Reconciliation.G_Runtime_Valid := TRUE;
GVL_Water_Output_Reconciliation.G_Last_Update_MS := VI_System_Time_MS;

IF L_Any_Conflict THEN
    GVL_Water_Output_Reconciliation.G_Status_Code := 3;
    GVL_Water_Output_Reconciliation.G_Status_Text := 'Water output reconciliation conflict';
ELSIF L_Any_Runtime_Mismatch THEN
    GVL_Water_Output_Reconciliation.G_Status_Code := 2;
    GVL_Water_Output_Reconciliation.G_Status_Text := 'Water output runtime mismatch';
ELSIF L_Any_Confirmation_Mismatch THEN
    GVL_Water_Output_Reconciliation.G_Status_Code := 1;
    GVL_Water_Output_Reconciliation.G_Status_Text := 'Water output confirmation mismatch';
ELSE
    GVL_Water_Output_Reconciliation.G_Status_Code := 0;
    GVL_Water_Output_Reconciliation.G_Status_Text := 'Water output reconciliation healthy';
END_IF;

// 1. Error checking and scaling based on sensor type
VO_Error := FALSE;
VO_Diag_Code := 0;

CASE VI_Sensor_Type OF
    0: // 4-20mA (NAMUR NE43: < 3.6mA or > 21mA)
        IF VI_Raw_Value < GVL_CONSTANTS.C_ANALOG_3_6MA_RAW THEN // < 3.6mA (Open circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSIF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_21MA_RAW THEN // > 21mA (Short circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 2;
        ELSE
            // 4mA = 5529, 20mA = 27648
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value - GVL_CONSTANTS.C_ANALOG_4MA_RAW) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX - GVL_CONSTANTS.C_ANALOG_4MA_RAW)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    1: // 0-10V (0-27648)
        IF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_10V_MAX_RAW THEN // Out of range
            VO_Error := TRUE;
            VO_Diag_Code := 3;
        ELSE
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    2: // PT100/1000 (Direct temperature * 10, e.g., 255 = 25.5C)
        // Typically, 16-bit signed integer for temperature
        IF VI_Raw_Value = 16#7FFF OR VI_Raw_Value = 16#8000 THEN // Sensor error codes
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSE
            L_Scaled := TO_REAL(TO_INT(VI_Raw_Value)) / 10.0;
            IF L_Scaled < VI_Min_Scale OR L_Scaled > VI_Max_Scale THEN
                VO_Error := TRUE;
                VO_Diag_Code := 3;
            END_IF;
        END_IF;

    ELSE
        VO_Error := TRUE;
        VO_Diag_Code := 16#FFFF; // Unknown sensor type
END_CASE;

// 2. Fallback handling
IF VO_Error THEN
    IF VI_Fallback_Mode = 1 THEN
        VO_Value := VI_Default_Value;
    END_IF;
    // If VI_Fallback_Mode = 0, VO_Value retains its last good value (L_Filtered)
    RETURN;
END_IF;

// 3. Calibration
L_Scaled := (L_Scaled * VI_Multiplier) + VI_Offset;

// 4. Moving Average Filter (ТЗ 1.2)
IF L_First_Scan THEN
    L_Filtered := L_Scaled;
    L_First_Scan := FALSE;
    L_Last_Time := VI_System_Time_MS;

    // Инициализация массива истории
    FOR L_i := 0 TO 9 DO
        L_History[L_i] := L_Scaled;
    END_FOR;
    L_History_Sum := L_Scaled * 10.0;
    L_History_Count := 10;
    L_History_Idx := 0;
END_IF;

L_DT := (SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1));
IF VI_Filter_Time_MS = 0 THEN
    L_Filtered := L_Scaled;
    L_Last_Time := VI_System_Time_MS;
ELSIF L_DT >= (VI_Filter_Time_MS / 10) THEN // Обновляем 10 раз за время фильтрации
    // Вычитаем старое значение
    L_History_Sum := L_History_Sum - L_History[L_History_Idx];

    // Добавляем новое значение
    L_History[L_History_Idx] := L_Scaled;
    L_History_Sum := L_History_Sum + L_Scaled;

    // Сдвигаем индекс
    L_History_Idx := (L_History_Idx + 1) MOD 10;

    // Вычисляем среднее
    L_Filtered := L_History_Sum / 10.0;

    L_Last_Time := VI_System_Time_MS;
END_IF;

VO_Value := L_Filtered;

// ==============================================================================
// Heating allocation filter
// Runtime decision gate between Demand_Map and Manifold_Control.
//
// IMPORTANT:
// This FB is NOT a second runtime owner.
// This FB is NOT an orchestration layer.
//
// Actual ownership remains in:
// PRG_Heating
// → FB_Heating_System_Manager
// → active subsystem owners.
//
// Current responsibility:
// - manifold availability gating;
// - service-state filtering;
// - freeze-mode exceptions;
// - bounded demand authorization.
//
// Optional responsibility when explicitly enabled:
// - priority-based allocation;
// - thermal budget limiting.
// ==============================================================================



// ======================================================
// DEFAULT STATE
// ======================================================
VO_Allocation_Degraded := FALSE;
VO_Thermal_Budget_Used := REAL#0.0;
L_AnyPolicyBlock := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Filtered[L_i] := VI_Manifold_Demand_Map[L_i];
    VO_Manifold_Allowed[L_i] := TRUE;
    VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.NONE;
    VO_Manifold_Priority_Effective[L_i] := VI_Manifold_Base_Priority[L_i];
END_FOR;

// ======================================================
// STRICT PASSTHROUGH MODE
// ======================================================
IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// FREEZE EXCEPTION MODE
//
// Freeze protection has higher authority than
// service gating and policy throttling.
// ======================================================
IF VI_Freeze_Mode_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i] THEN
            VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.FREEZE_BYPASS;
        END_IF;
    END_FOR;
    RETURN;
END_IF;

// ======================================================
// DHW PRIORITY GATE
//
// Manifold_Control already owns DHW shutdown.
// Keep this filter transparent during DHW hold to avoid
// creating duplicate DHW authority here.
// ======================================================
IF VI_DHW_Heating_Demand THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i] THEN
            VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.DHW_BYPASS;
        END_IF;
    END_FOR;
    RETURN;
END_IF;

// ======================================================
// MANIFOLD AUTHORIZATION FILTER
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO

    IF NOT VI_Manifold_Available[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.PRESSURE_UNAVAILABLE;
    END_IF;

    IF NOT VI_Manifold_In_Service[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.SERVICE_DISABLED;
    END_IF;

    IF VI_Manifold_Subsystem_Degraded[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.PREDICTIVE_DEGRADED;
    END_IF;

    IF VI_Manifold_Demand_Map[L_i] AND NOT VO_Manifold_Allowed[L_i] THEN
        VO_Manifold_Demand_Filtered[L_i] := FALSE;
        VO_Allocation_Degraded := TRUE;
    END_IF;

END_FOR;

// ======================================================
// OPTIONAL POLICY LAYER
//
// This layer can only reduce demand that is already
// authorized by availability/service/degraded checks.
// It never creates new demand and never writes outputs.
// ======================================================
IF NOT VI_Enable_Policy_Allocation THEN
    RETURN;
END_IF;

// Invalid or unset budget means no policy throttling.
IF VI_Max_Thermal_Budget <= REAL#0.0 THEN
    RETURN;
END_IF;

// Rebuild output demand from allowed candidates only.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Filtered[L_i] := FALSE;
END_FOR;

L_MaxPriority := 0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Demand_Map[L_i] AND VO_Manifold_Allowed[L_i] THEN
        IF VO_Manifold_Priority_Effective[L_i] > L_MaxPriority THEN
            L_MaxPriority := VO_Manifold_Priority_Effective[L_i];
        END_IF;
    END_IF;
END_FOR;

L_Used := REAL#0.0;

FOR L_CurrentPriority := L_MaxPriority TO 0 BY -1 DO
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i]
           AND VO_Manifold_Allowed[L_i]
           AND (VO_Manifold_Priority_Effective[L_i] = L_CurrentPriority) THEN

            L_Weight := VI_Manifold_Thermal_Weight[L_i];
            IF L_Weight <= REAL#0.0 THEN
                L_Weight := REAL#1.0;
            END_IF;

            IF (L_Used + L_Weight) <= VI_Max_Thermal_Budget THEN
                VO_Manifold_Demand_Filtered[L_i] := TRUE;
                L_Used := L_Used + L_Weight;
            ELSE
                L_AnyPolicyBlock := TRUE;
                IF VO_Manifold_Block_Reason[L_i] = E_Heating_Allocation_Block_Reason.NONE THEN
                    VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.POLICY_BUDGET_SHED;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

VO_Thermal_Budget_Used := L_Used;

IF L_AnyPolicyBlock THEN
    VO_Allocation_Degraded := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Allocation_Filter <<<

L_Mode_Active := GVL_SAFETY_SHUTDOWN.G_Safety_Active;
L_Phase := GVL_SAFETY_RECOVERY.G_Recovery_Phase;
GVL_SAFETY_RECOVERY.G_Recovery_Exit_Allowed := FALSE;

CASE L_Phase OF

    IDLE:
        IF NOT L_Mode_Active AND GVL_SAFETY_RECOVERY.G_Recovery_Requested THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := STABILIZING;
            GVL_SAFETY_RECOVERY.G_Recovery_Active := TRUE;
            GVL_SAFETY_RECOVERY.G_Recovery_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 0;
        END_IF;

    STABILIZING:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSIF (GVL_TIME_SERVICE.G_Now_MS - GVL_SAFETY_RECOVERY.G_Recovery_Start_MS) > GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := WAIT_MANUAL_CONFIRM;
            GVL_SAFETY_RECOVERY.G_Recovery_Stable_Since_MS := GVL_TIME_SERVICE.G_Now_MS;
        END_IF;

    WAIT_MANUAL_CONFIRM:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSE
            GVL_SAFETY_RECOVERY.G_Recovery_Exit_Allowed := TRUE;
            IF GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm THEN
                GVL_SAFETY_RECOVERY.G_Recovery_Phase := RECOVERING;
                GVL_SAFETY_RECOVERY.G_Recovery_Exit_Allowed := FALSE;
            END_IF;
        END_IF;

    RECOVERING:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSE
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := COOLDOWN;
            GVL_SAFETY_RECOVERY.G_Recovery_Cooldown_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
        END_IF;

    COOLDOWN:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSE
            L_Time_OK := (GVL_TIME_SERVICE.G_Now_MS - GVL_SAFETY_RECOVERY.G_Recovery_Cooldown_Start_MS) > GVL_SAFETY_RECOVERY_CONFIG.G_Cooldown_Time_MS;

            IF L_Time_OK THEN
                GVL_SAFETY_RECOVERY.G_Recovery_Phase := IDLE;
                GVL_SAFETY_RECOVERY.G_Recovery_Active := FALSE;
                GVL_SAFETY_RECOVERY.G_Recovery_Requested := FALSE;
                GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm := FALSE;
            END_IF;
        END_IF;

    ABORTED:
        GVL_SAFETY_RECOVERY.G_Recovery_Active := FALSE;
        GVL_SAFETY_RECOVERY.G_Recovery_Requested := FALSE;
        GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm := FALSE;
        GVL_SAFETY_RECOVERY.G_Recovery_Exit_Allowed := FALSE;
        IF NOT L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := IDLE;
        END_IF;

END_CASE;

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Recovery <<<

GVL_IO_WRITE_RUNTIME_BUFFER.B_PreOutput_Block_IO := GVL_COMMAND_VERIFY.PreOutput_Block_IO;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Output_Freshness_Block := GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Output_Publication_Block := (NOT GVL_OUTPUT_EPOCH.Output_Publication_Valid) OR (NOT GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid) OR GVL_OUTPUT_EPOCH.Output_Lease_Expired;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Distributed_Publication_Block := (NOT GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid) OR GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active OR GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired OR (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled) OR (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid) OR (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent);
GVL_IO_WRITE_RUNTIME_BUFFER.B_Snapshot_Block := (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid) OR GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Distributed_Execution_Block := NOT GVL_Distributed_Execution_Gates.G_Can_Execute OR NOT GVL_Distributed_Execution_Gates.G_Can_Own_Projection;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Global_Hard_Stop := (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP) OR (GVL_SAFETY_RECOVERY.G_Recovery_Phase <> IDLE) OR GVL_IO_WRITE_RUNTIME_BUFFER.B_PreOutput_Block_IO OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Output_Freshness_Block OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Output_Publication_Block OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Distributed_Publication_Block OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Snapshot_Block OR ( GVL_IO_WRITE_RUNTIME_BUFFER.B_Distributed_Execution_Block AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> FIRE) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> GAS) );
GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Safety_Stop := GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop OR GVL_COMMAND_SHADOW.G_Boiler_Stop;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Freeze_Active := GVL_STATE.G_Safety_Freeze_Risk;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Fire_Siren_Enable := GVL_ALARM.G_Gas_Fire_Siren OR GVL_ALARM.G_Global_Siren OR GVL_ALARM.G_Global_Critical;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Siren_Authority := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_HEALTH_BRIDGE.G_CO_Alarm_Level OR GVL_STATE.G_Safety_Gas_Latched;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Fire_Siren_Authority := GVL_HEALTH_BRIDGE.G_Smoke_Detected OR GVL_STATE.G_Safety_Smoke_Latched;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Heating_Forced_Off := GVL_COMMAND_SHADOW.G_Heating_Block OR GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Vent_Forced_Off := ( GVL_COMMAND_SHADOW.G_Vent_Stop OR GVL_COMMAND_SHADOW.G_Vent_Block ) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> FIRE) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> GAS);
GVL_IO_WRITE_RUNTIME_BUFFER.B_Water_Forced_Off := GVL_COMMAND_SHADOW.G_Water_Block OR GVL_COMMAND_SHADOW.G_Water_Emergency_Stop;
GVL_IO_WRITE_RUNTIME_BUFFER.B_Access_Safety_Override := (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS);
GVL_IO_WRITE_RUNTIME_BUFFER.B_Access_Forced_Off := (GVL_SAFETY_RECOVERY.G_Recovery_Phase <> IDLE) AND NOT GVL_IO_WRITE_RUNTIME_BUFFER.B_Access_Safety_Override;
// >>> BULK_SYNC_ANCHOR: PRG_IO_Write_Phase_01_Context <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Global_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Valid := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Granted := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Quarantine_Active := TRUE;

GVL_GLOBAL_AUTHORITY_SYNC.Heating_Authority_Coherent := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Ventilation_Authority_Coherent := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Water_Authority_Coherent := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Access_Authority_Coherent := FALSE;
GVL_GLOBAL_AUTHORITY_SYNC.Lighting_Authority_Coherent := FALSE;

// Historical truth authority required.
IF NOT GVL_HISTORICAL_TRUTH.Historical_Truth_Granted THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34000;
    L_Error_Text := 'Historical truth authority not granted';
END_IF;

// Cross-domain split-brain detectors.
IF GVL_GLOBAL_AUTHORITY_SYNC.Authority_Epoch_Fragmentation_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34001;
    L_Error_Text := 'Authority epoch fragmentation detected';
END_IF;

IF GVL_GLOBAL_AUTHORITY_SYNC.Partial_Recovery_SplitBrain_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34002;
    L_Error_Text := 'Partial recovery split-brain detected';
END_IF;

IF GVL_GLOBAL_AUTHORITY_SYNC.Cross_Domain_Replay_Skew_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34003;
    L_Error_Text := 'Cross-domain replay skew detected';
END_IF;

IF GVL_GLOBAL_AUTHORITY_SYNC.Distributed_Authority_Divergence_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34004;
    L_Error_Text := 'Distributed authority divergence detected';
END_IF;

IF GVL_GLOBAL_AUTHORITY_SYNC.Global_Causality_Desynchronization_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34005;
    L_Error_Text := 'Global causality desynchronization detected';
END_IF;

IF GVL_GLOBAL_AUTHORITY_SYNC.Multi_Domain_Chronology_Drift_Detected THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34006;
    L_Error_Text := 'Multi-domain chronology drift detected';
END_IF;

// Cross-domain synchronization validation.
IF L_Global_Valid
AND NOT GVL_GLOBAL_AUTHORITY_SYNC.Cross_Domain_Epoch_Coherent THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34010;
    L_Error_Text := 'Cross-domain epoch coherence invalid';
END_IF;

IF L_Global_Valid
AND NOT GVL_GLOBAL_AUTHORITY_SYNC.Distributed_Authority_Generation_Coherent THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34011;
    L_Error_Text := 'Distributed authority generation coherence invalid';
END_IF;

IF L_Global_Valid
AND NOT GVL_GLOBAL_AUTHORITY_SYNC.Global_Causality_Timeline_Stable THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34012;
    L_Error_Text := 'Global causality timeline unstable';
END_IF;

IF L_Global_Valid
AND NOT GVL_GLOBAL_AUTHORITY_SYNC.Multi_Domain_Recovery_Coherent THEN
    L_Global_Valid := FALSE;
    L_Error_Code := 34013;
    L_Error_Text := 'Multi-domain recovery coherence invalid';
END_IF;

IF L_Global_Valid THEN
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Valid := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Granted := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Quarantine_Active := FALSE;

    GVL_GLOBAL_AUTHORITY_SYNC.Heating_Authority_Coherent := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Ventilation_Authority_Coherent := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Water_Authority_Coherent := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Access_Authority_Coherent := TRUE;
    GVL_GLOBAL_AUTHORITY_SYNC.Lighting_Authority_Coherent := TRUE;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Epoch :=
        GVL_HISTORICAL_TRUTH.Historical_Truth_Epoch;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Epoch_Coherent := TRUE;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Last_Update_MS := L_Now_MS;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Lease_Expired := FALSE;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Last_Error_Code := 0;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Last_Error_Text := '';
ELSE
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Valid := FALSE;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Granted := FALSE;
    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Quarantine_Active := TRUE;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Lease_Expired := TRUE;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Last_Error_Code :=
        L_Error_Code;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Last_Error_Text :=
        L_Error_Text;

    GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Invalidation_Count :=
        GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Invalidation_Count + 1;
END_IF;

GVL_Safety_Selector.G_CO_Effective := 0.0;
GVL_Safety_Selector.G_Methane_Effective := 0.0;
GVL_Safety_Selector.G_Smoke_Effective := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    GVL_Safety_Selector.G_CO_Effective_Array[L_i] := GVL_STATE.G_CO_Sensors[L_i];
    IF GVL_STATE.G_CO_Sensors[L_i] > GVL_Safety_Selector.G_CO_Effective THEN
        GVL_Safety_Selector.G_CO_Effective := GVL_STATE.G_CO_Sensors[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    GVL_Safety_Selector.G_Methane_Effective_Array[L_i] := GVL_STATE.G_Methane_Sensors[L_i];
    IF GVL_STATE.G_Methane_Sensors[L_i] > GVL_Safety_Selector.G_Methane_Effective THEN
        GVL_Safety_Selector.G_Methane_Effective := GVL_STATE.G_Methane_Sensors[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    GVL_Safety_Selector.G_Smoke_Effective_Array[L_i] := GVL_STATE.G_Smoke_Sensors[L_i];
    GVL_Safety_Selector.G_Smoke_Effective :=
        GVL_Safety_Selector.G_Smoke_Effective
        OR GVL_STATE.G_Smoke_Sensors[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Selector <<<

IF GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Distributed_Epoch_Linearity_Granted
AND NOT GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Order_Divergence
AND NOT GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Unsafe_Historical_Rewrite_Detected
AND NOT GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Causality_Gap_Detected THEN

    GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Ordering_Integrity_Valid := TRUE;
    GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Ordering_Integrity_Granted := TRUE;
    GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Ordering_Integrity_Granted_Proof := TRUE;
    GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Timeline_Canonical := TRUE;
    GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Forensic_Ordering_Coherent := TRUE;
END_IF;

GVL_HMI_ALARM_AUDIBLE_ACK.G_Ack_Active := GVL_ALARM_AUDIBLE_ACK.G_Ack_Active;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS := GVL_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm := GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached := GVL_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Last_Ack_Accepted := GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Accepted;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied := GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Last_Denial_Code := GVL_ALARM_AUDIBLE_ACK.G_Last_Denial_Code;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Last_Event_MS := GVL_ALARM_AUDIBLE_ACK.G_Last_Event_MS;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Status_Text := GVL_ALARM_AUDIBLE_ACK.G_Status_Text;
GVL_HMI_ALARM_AUDIBLE_ACK.G_Effective_Siren_Muted := GVL_ALARM_AUDIBLE_ACK.G_Ack_Active;

// >>> BULK_SYNC_ANCHOR: PRG_HMI_Alarm_Audible_Ack_Dashboard <<<

// PASSIVE PHYSICS REALITY VERIFICATION
// NO EXECUTION MUTATION
// NO ACTUATION MUTATION
// NO AUTHORITY MUTATION

GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Physical_Runtime_Reality_Valid :=
    GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Runtime_Causal_Projection_Valid;

GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Commanded_State_Verified_Physically :=
    GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal;

GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Physical_Response_Coherent :=
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Coherent;

GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Sensor_Physics_Coherent := TRUE;

IF GVL_RUNTIME_TRANSITION_SYSTEM.Illegal_Runtime_Transition_Observed THEN
    GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Physical_Reality_Divergence_Detected := TRUE;
END_IF;

IF GVL_RUNTIME_TRANSITION_SYSTEM.Unsafe_State_Promotion_Observed THEN
    GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Commanded_State_Mismatch_Detected := TRUE;
END_IF;

IF GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Fork_Detected THEN
    GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Impossible_Physical_Response_Detected := TRUE;
END_IF;

// PASSIVE READ-ONLY OBSERVABILITY GOVERNOR
// NO authority mutation
// NO execution mutation
// NO blocking semantics

GVL_PASSIVE_RUNTIME_VERIFICATION_FABRIC.Runtime_Verification_Consistency_Valid :=
    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Causality_Reversal_Prevention_Granted;

GVL_PASSIVE_RUNTIME_VERIFICATION_FABRIC.Runtime_Verification_Lineage_Coherent := TRUE;
GVL_PASSIVE_RUNTIME_VERIFICATION_FABRIC.Runtime_Verification_Timeline_Monotonic := TRUE;

// ======================================================
// MODBUS RTU BRIDGE
// ======================================================
// This PRG transfers requests from the project runtime
// into the RTU bridge contract and applies confirmed responses.
//
// A concrete CODESYS Modbus RTU implementation must:
//   1. Observe G_Request_*
//   2. Execute physical RS485 transaction
//   3. Fill G_Response_*
//
// Safety:
//   - No response is generated internally.
//   - No fake Done is allowed.
// ======================================================

IF NOT GVL_MODBUS_RTU_BRIDGE.G_Bridge_Enabled THEN
    RETURN;
END_IF;

// ======================================================
// EXPORT FIRST ACTIVE REQUEST
// ======================================================
GVL_MODBUS_RTU_BRIDGE.G_Request_Valid := FALSE;

FOR L_i := 1 TO 16 DO

    IF GVL_MODBUS_MASTER.G_Request[L_i].Enable THEN

        GVL_MODBUS_RTU_BRIDGE.G_Request_Valid := TRUE;
        GVL_MODBUS_RTU_BRIDGE.G_Request_Index := L_i;
        GVL_MODBUS_RTU_BRIDGE.G_Request_Slave_ID :=
            GVL_MODBUS_MASTER.G_Request[L_i].Slave_ID;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Function_Code :=
            GVL_MODBUS_MASTER.G_Request[L_i].Function_Code;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Start_Register :=
            GVL_MODBUS_MASTER.G_Request[L_i].Start_Register;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Register_Count :=
            GVL_MODBUS_MASTER.G_Request[L_i].Register_Count;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Write_Value :=
            GVL_MODBUS_MASTER.G_Request[L_i].Write_Value;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence :=
            GVL_MODBUS_MASTER.G_Request[L_i].Sequence;

        GVL_MODBUS_RTU_BRIDGE.G_Request_Timeout_MS :=
            GVL_MODBUS_MASTER.G_Request[L_i].Timeout_MS;

        EXIT;
    END_IF;

END_FOR;

// ======================================================
// APPLY CONFIRMED RESPONSE
// ======================================================
IF GVL_MODBUS_RTU_BRIDGE.G_Response_Done OR
   GVL_MODBUS_RTU_BRIDGE.G_Response_Error THEN

    L_i := GVL_MODBUS_RTU_BRIDGE.G_Request_Index;

    IF (L_i >= 1) AND (L_i <= 16) THEN

        GVL_MODBUS_MASTER.G_Response[L_i].Busy :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Busy;

        GVL_MODBUS_MASTER.G_Response[L_i].Done :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Done;

        GVL_MODBUS_MASTER.G_Response[L_i].Error :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error;

        GVL_MODBUS_MASTER.G_Response[L_i].Error_Code :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code;

        GVL_MODBUS_MASTER.G_Response[L_i].Read_Value :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Value;

        GVL_MODBUS_MASTER.G_Response[L_i].Last_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence;

        GVL_MODBUS_MASTER.G_Response[L_i].Last_Update_MS :=
            GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS;

    END_IF;

END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Distributed_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// DISTRIBUTED EPOCH GOVERNOR
// ======================================================
// Governs peer epoch reconciliation foundation.
// Prevents distributed stale authority continuity.
//
// Current implementation mode:
// peer-optional foundation mode.
//
// Missing peer topology is NOT treated as divergence.
// Peer validation activates only after real peer
// synchronization state exists.
// ======================================================

GVL_DISTRIBUTED_EPOCH.Peer_Lease_Expired := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Semantic_Continuity_Lost := FALSE;

// ------------------------------------------------------
// Local authority projection.
// ------------------------------------------------------

GVL_DISTRIBUTED_EPOCH.Local_Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch;
GVL_DISTRIBUTED_EPOCH.Local_Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch;
GVL_DISTRIBUTED_EPOCH.Local_Boot_Generation := GVL_TIME_MONOTONIC.Boot_Generation_ID;
GVL_DISTRIBUTED_EPOCH.Local_Fencing_Token := GVL_PLC_FENCING.PLC_Fencing_Token;

// ------------------------------------------------------
// Transitional peer-ingestion detection.
// ------------------------------------------------------
// During bounded peer-ingestion restoration the peer layer
// still mirrors local-visible runtime/session state.
//
// Real remote fencing exchange is not implemented yet.
// Equality-based fencing conflict semantics therefore remain
// suppressed until explicit remote token transport exists.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token = GVL_STATUS.G_Active_PLC_ID THEN
    L_Transitional_Peer_Projection := TRUE;
END_IF;

// ------------------------------------------------------
// Peer session detection.
// ------------------------------------------------------
// Peer validation becomes authoritative only after
// real peer epoch continuity exists.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

// ------------------------------------------------------
// Peer lease validation foundation.
// ------------------------------------------------------

IF L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_EPOCH.Peer_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_EPOCH.Peer_Lease_Timeout_MS THEN
            GVL_DISTRIBUTED_EPOCH.Peer_Lease_Expired := TRUE;

            L_Distributed_Valid := FALSE;
            L_Error_Code := 13000;
            L_Error_Text := 'Peer lease expired';
        END_IF;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer runtime continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch < GVL_DISTRIBUTED_EPOCH.Local_Runtime_Epoch THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer snapshot continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch < GVL_DISTRIBUTED_EPOCH.Local_Snapshot_Epoch THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer boot generation continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation <> GVL_DISTRIBUTED_EPOCH.Local_Boot_Generation THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer fencing continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid
AND L_Peer_Session_Active
AND NOT L_Transitional_Peer_Projection
THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token = GVL_DISTRIBUTED_EPOCH.Local_Fencing_Token THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict := TRUE;

        L_Distributed_Valid := FALSE;
        L_Error_Code := 13001;
        L_Error_Text := 'Peer fencing conflict detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Distributed semantic continuity.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale
OR GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale
OR GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch
OR GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict
THEN
    GVL_DISTRIBUTED_EPOCH.Peer_Semantic_Continuity_Lost := TRUE;
END_IF;

// ------------------------------------------------------
// Publish distributed epoch state.
// ------------------------------------------------------

IF L_Distributed_Valid THEN
    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch := GVL_DISTRIBUTED_EPOCH.Distributed_Epoch + 1;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Epoch := GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch_Consistent := TRUE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Valid := TRUE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Publication_Allowed := TRUE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Quarantine_Active := FALSE;

    GVL_DISTRIBUTED_EPOCH.Peer_Last_Reconciliation_MS := L_Now_MS;

    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Code := 0;
    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Text := '';
ELSE
    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch_Consistent := FALSE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Valid := FALSE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Publication_Allowed := FALSE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Quarantine_Active := TRUE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Text := L_Error_Text;
END_IF;

// ==============================================================================
// LIGHTING — deterministic lighting/blinds/socket phase map.
// ==============================================================================
// Execution order is preserved from the former monolithic PRG_Lighting body.
// No gating, shedding or behavior changes are applied here.
// ==============================================================================

PRG_Lighting_Phase_01_Context();
PRG_Lighting_Phase_02_Managers();
PRG_Lighting_Phase_03_Priority_Restrictions();
PRG_Lighting_Phase_04_Output_Publication();

// >>> BULK_SYNC_ANCHOR: PRG_Lighting <<<

// MAIN PHASE 02 — local PLC authority / cold-spare model.
// Critical: yes. Called every PLC scan.
//
// Current architecture: one active PLC controls the system; a second PLC is a
// cold spare only and must not participate in runtime ownership, hot failover,
// direct state replication or physical output arbitration.


GVL_MAIN_PHASE_FEEDBACK.G_Current_Phase := 2;

// Local-only authority. No hot standby arbitration is performed in runtime.
GVL_STATUS.G_Is_Active_PLC := TRUE;
GVL_STATUS.G_Other_PLC_Is_Active := FALSE;
GVL_STATUS.G_Remote_PLC_Alive := FALSE;
GVL_STATUS.G_Remote_PLC_Pulse := FALSE;
GVL_STATUS.G_Active_PLC_ID := GVL_STATUS.G_Local_PLC_ID;

// Physical/service status outputs. The heartbeat output is only a local service
// indicator and is not used for automatic failover.
fbServiceHeartbeatTimer(
    IN := NOT fbServiceHeartbeatTimer.Q,
    PT := T#500ms,
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS
);

IF fbServiceHeartbeatTimer.Q THEN
    L_Service_Heartbeat_State := NOT L_Service_Heartbeat_State;
END_IF;

GVL_IO.DO_Heartbeat_Pulse := L_Service_Heartbeat_State;
GVL_IO.DO_Active_Status := TRUE;

fbSystemDiagnostics();
PRG_PLC_Arbitration();
PRG_PLC_Fencing_Governor();

GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Executed := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Valid := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Status_Text := 'Single active PLC / cold-spare authority phase executed';
GVL_MAIN_PHASE_FEEDBACK.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Main_Phase_02_Redundancy <<<

// ======================================================
// MODBUS RTU SYSCOM TRANSPORT EXECUTION
// ======================================================
// Byte-level transport boundary execution.
// ======================================================

FB_SysCom_Transport(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

// ======================================================
// MODBUS MASTER RUNTIME SCHEDULER
// ======================================================
// Library-independent Modbus master scheduler.
// ======================================================

IF NOT GVL_CONFIG.G_OpenTherm_Enabled THEN

    GVL_MODBUS_MASTER.G_Master_Online := FALSE;
    GVL_MODBUS_MASTER.G_Master_Error := FALSE;

    GVL_MODBUS_MASTER.G_Active := FALSE;
    GVL_MODBUS_MASTER.G_Active_Index := 0;
    GVL_MODBUS_MASTER.G_Active_Sequence := 0;
    GVL_MODBUS_MASTER.G_Active_Start_MS := 0;
    GVL_MODBUS_MASTER.G_Active_Retry_Count := 0;

    FOR L_i := 1 TO 16 DO
        GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Error := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 0;
    END_FOR;

    RETURN;
END_IF;

GVL_MODBUS_MASTER.G_Master_Online :=
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Online;

GVL_MODBUS_MASTER.G_Master_Error :=
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error;

// ======================================================
// START NEW TRANSACTION
// ======================================================
IF NOT GVL_MODBUS_MASTER.G_Active THEN

    FOR L_i := 1 TO 16 DO

        IF GVL_MODBUS_MASTER.G_Request[L_i].Enable THEN

            GVL_MODBUS_MASTER.G_Active := TRUE;
            GVL_MODBUS_MASTER.G_Active_Index := L_i;
            GVL_MODBUS_MASTER.G_Active_Sequence :=
                GVL_MODBUS_MASTER.G_Request[L_i].Sequence;

            GVL_MODBUS_MASTER.G_Active_Start_MS :=
                GVL_STATUS.G_System_Time_MS;

            GVL_MODBUS_MASTER.G_Active_Retry_Count := 0;

            GVL_MODBUS_MASTER.G_Response[L_i].Busy := TRUE;
            GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 0;

            EXIT;

        END_IF;

    END_FOR;

END_IF;

// ======================================================
// ACTIVE TRANSACTION SUPERVISION
// ======================================================
IF GVL_MODBUS_MASTER.G_Active THEN

    L_i := GVL_MODBUS_MASTER.G_Active_Index;

    L_Elapsed_MS :=
        GVL_STATUS.G_System_Time_MS -
        GVL_MODBUS_MASTER.G_Active_Start_MS;

    IF GVL_MODBUS_MASTER.G_Response[L_i].Done OR
       GVL_MODBUS_MASTER.G_Response[L_i].Error THEN

        GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;

        GVL_MODBUS_MASTER.G_Active := FALSE;
        GVL_MODBUS_MASTER.G_Last_Transaction_MS :=
            GVL_STATUS.G_System_Time_MS;

        GVL_MODBUS_MASTER.G_Total_Transactions :=
            GVL_MODBUS_MASTER.G_Total_Transactions + 1;

        IF GVL_MODBUS_MASTER.G_Response[L_i].Error THEN
            GVL_MODBUS_MASTER.G_Total_Errors :=
                GVL_MODBUS_MASTER.G_Total_Errors + 1;
        END_IF;

    ELSIF L_Elapsed_MS > GVL_MODBUS_MASTER.G_Request[L_i].Timeout_MS THEN

        GVL_MODBUS_MASTER.G_Active_Retry_Count :=
            GVL_MODBUS_MASTER.G_Active_Retry_Count + 1;

        IF GVL_MODBUS_MASTER.G_Active_Retry_Count >
           GVL_CONFIG.G_Modbus_RTU_Retry_Count THEN

            GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error := TRUE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 16#0003;

            GVL_MODBUS_MASTER.G_Response[L_i].Last_Sequence :=
                GVL_MODBUS_MASTER.G_Active_Sequence;

            GVL_MODBUS_MASTER.G_Response[L_i].Last_Update_MS :=
                GVL_STATUS.G_System_Time_MS;

            GVL_MODBUS_MASTER.G_Active := FALSE;

            GVL_MODBUS_MASTER.G_Total_Timeouts :=
                GVL_MODBUS_MASTER.G_Total_Timeouts + 1;

            GVL_MODBUS_MASTER.G_Total_Errors :=
                GVL_MODBUS_MASTER.G_Total_Errors + 1;

        ELSE

            GVL_MODBUS_MASTER.G_Active_Start_MS :=
                GVL_STATUS.G_System_Time_MS;

        END_IF;

    END_IF;

END_IF;

// Observational domain execution policy.
// Classifies domains as critical, periodic or idle-by-design.
// Does not gate execution and does not write physical outputs.


GVL_DOMAIN_EXECUTION_POLICY.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

GVL_DOMAIN_EXECUTION_POLICY.G_Security_Context_Active :=
    GVL_ALARM.G_Security_Armed
    OR GVL_ALARM.G_Security_Alarm;

GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active :=
    GVL_STATUS.G_Current_Scenario = SCENARIO_AWAY;

GVL_DOMAIN_EXECUTION_POLICY.G_Presence_Context_Active :=
    GVL_STATUS.G_Current_Scenario = SCENARIO_PRESENCE;

GVL_DOMAIN_EXECUTION_POLICY.G_Emergency_Context_Active :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = WATER_LEAK)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP);

GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    OR GVL_COMMAND_SHADOW.G_Lock_1_Open
    OR GVL_COMMAND_SHADOW.G_Lock_1_Close
    OR GVL_COMMAND_SHADOW.G_Lock_2_Open
    OR GVL_COMMAND_SHADOW.G_Lock_2_Close
    OR GVL_COMMAND_SHADOW.G_Gate_Open
    OR GVL_COMMAND_SHADOW.G_Wicket_Open
    OR GVL_ACCESS_RUNTIME.G_Any_Pulse_Active;

GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run :=
    (NOT GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run)
    AND (
        GVL_DOMAIN_EXECUTION_POLICY.G_Security_Context_Active
        OR GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active
    );

GVL_DOMAIN_EXECUTION_POLICY.Access_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run
    AND NOT GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run;

IF GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Access_Mode := 2;
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Access_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Access_Mode := 0;
END_IF;

GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    OR GVL_STATE.G_Evacuation_Lighting_Active
    OR GVL_LIGHTING_RUNTIME.G_Emergency_Override_Active
    OR GVL_LIGHTING_RUNTIME.G_Any_Light_Active
    OR GVL_LIGHTING_RUNTIME.G_Any_Blind_Not_Safe_Open
    OR GVL_LIGHTING_RUNTIME.G_Any_Socket_Active
    OR GVL_ALARM.G_Security_Alarm;

GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run :=
    (NOT GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run)
    AND (
        GVL_DOMAIN_EXECUTION_POLICY.G_Security_Context_Active
        OR GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active
        OR GVL_DOMAIN_EXECUTION_POLICY.G_Presence_Context_Active
    );

GVL_DOMAIN_EXECUTION_POLICY.Lighting_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run
    AND NOT GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run;

IF GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Lighting_Mode := 2;
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Lighting_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Lighting_Mode := 0;
END_IF;

GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = WATER_LEAK)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP)
    OR GVL_COMMAND_SHADOW.G_Water_Block
    OR GVL_COMMAND_SHADOW.G_Water_Emergency_Stop
    OR GVL_COMMAND_SHADOW.G_Close_Valve_35
    OR GVL_COMMAND_SHADOW.G_Close_Valve_36
    OR GVL_WATER_DOMAIN_STATUS.G_Recovery_Requested
    OR GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Output_35_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Output_36_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Any_Zone_Active;

GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run :=
    (NOT GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run)
    AND (
        GVL_DOMAIN_EXECUTION_POLICY.G_Security_Context_Active
        OR GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active
    );

GVL_DOMAIN_EXECUTION_POLICY.Water_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run
    AND NOT GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run;

IF GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Water_Mode := 2;
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Water_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Water_Mode := 0;
END_IF;

L_Heating_Output_Active :=
    GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump
    OR GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump
    OR GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump
    OR GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Heating_Output_Active :=
        L_Heating_Output_Active
        OR GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Heating_Output_Active :=
        L_Heating_Output_Active
        OR GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i]
        OR (GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i] > 0);
END_FOR;

GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP)
    OR GVL_COMMAND_SHADOW.G_Heating_Block
    OR GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop
    OR GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop
    OR GVL_STATE.G_Safety_Gas_Latched
    OR GVL_STATE.G_Safety_Freeze_Risk
    OR L_Heating_Output_Active;

GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run :=
    (NOT GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run)
    AND (
        GVL_STATUS.G_Current_Scenario = SCENARIO_MORNING
        OR GVL_STATUS.G_Current_Scenario = SCENARIO_EVENING
        OR GVL_STATUS.G_Current_Scenario = SCENARIO_SLEEP
        OR GVL_STATUS.G_Current_Scenario = SCENARIO_PRESENCE
        OR GVL_INPUT.IN_Preheat_Request
        OR GVL_INPUT.IN_Freeze_Request
    );

GVL_DOMAIN_EXECUTION_POLICY.Heating_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run
    AND NOT GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run;

IF GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Heating_Mode := 2;
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Heating_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Heating_Mode := 0;
END_IF;

L_Vent_Output_Active := GVL_VENT_OUTPUT.DO_Vent_Enable;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    L_Vent_Output_Active :=
        L_Vent_Output_Active
        OR (GVL_VENT_OUTPUT.AO_Supply_Fans[L_i] > 0);
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    L_Vent_Output_Active :=
        L_Vent_Output_Active
        OR (GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i] > 0);
END_FOR;

GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP)
    OR GVL_COMMAND_SHADOW.G_Vent_Stop
    OR GVL_COMMAND_SHADOW.G_Vent_Block
    OR GVL_COMMAND_SHADOW.G_Vent_PV3_Boost
    OR GVL_COMMAND_SHADOW.G_Exhaust_100_Req
    OR GVL_COMMAND_SHADOW.G_Vent_Smoke_Exhaust
    OR L_Vent_Output_Active;

GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run :=
    (NOT GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run)
    AND (
        GVL_DOMAIN_EXECUTION_POLICY.G_Presence_Context_Active
        OR GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active
        OR GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost
    );

GVL_DOMAIN_EXECUTION_POLICY.Vent_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run
    AND NOT GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run;

IF GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Vent_Mode := 2;
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Vent_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Vent_Mode := 0;
END_IF;

GVL_DOMAIN_EXECUTION_POLICY.Simulation_Context_Active :=
    GVL_SIMULATION.G_Test_Scenario_Active
    OR GVL_SIMULATION.G_Test_Start
    OR GVL_DOMAIN_EXECUTION_POLICY.G_Security_Context_Active
    OR GVL_DOMAIN_EXECUTION_POLICY.G_Away_Context_Active;

GVL_DOMAIN_EXECUTION_POLICY.Simulation_Run_Allowed :=
    GVL_SIMULATION.G_Simulation_Enable
    AND GVL_DOMAIN_EXECUTION_POLICY.Simulation_Context_Active
    AND NOT GVL_FABRIC_LIFECYCLE_REGISTRY.Simulation_Suspension_Recommended;

GVL_DOMAIN_EXECUTION_POLICY.Simulation_Idle_By_Design :=
    NOT GVL_DOMAIN_EXECUTION_POLICY.Simulation_Run_Allowed;

IF GVL_DOMAIN_EXECUTION_POLICY.Simulation_Run_Allowed THEN
    GVL_DOMAIN_EXECUTION_POLICY.Simulation_Mode := 1;
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Simulation_Mode := 0;
END_IF;

GVL_DOMAIN_EXECUTION_POLICY.Any_Critical_Run :=
    GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run;

GVL_DOMAIN_EXECUTION_POLICY.Any_Periodic_Run :=
    GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run
    OR GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run;

GVL_DOMAIN_EXECUTION_POLICY.Any_Idle_By_Design :=
    GVL_DOMAIN_EXECUTION_POLICY.Access_Idle_By_Design
    OR GVL_DOMAIN_EXECUTION_POLICY.Lighting_Idle_By_Design
    OR GVL_DOMAIN_EXECUTION_POLICY.Water_Idle_By_Design
    OR GVL_DOMAIN_EXECUTION_POLICY.Heating_Idle_By_Design
    OR GVL_DOMAIN_EXECUTION_POLICY.Vent_Idle_By_Design
    OR GVL_DOMAIN_EXECUTION_POLICY.Simulation_Idle_By_Design;

IF GVL_DOMAIN_EXECUTION_POLICY.Any_Critical_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Status_Code := 2;
    GVL_DOMAIN_EXECUTION_POLICY.Status_Text := 'Domain execution policy critical activity present';
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Any_Periodic_Run THEN
    GVL_DOMAIN_EXECUTION_POLICY.Status_Code := 1;
    GVL_DOMAIN_EXECUTION_POLICY.Status_Text := 'Domain execution policy periodic activity present';
ELSE
    GVL_DOMAIN_EXECUTION_POLICY.Status_Code := 0;
    GVL_DOMAIN_EXECUTION_POLICY.Status_Text := 'Domain execution policy idle by design';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Domain_Execution_Policy <<<

IF GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Granted
AND NOT GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Unsafe_Recovery_Reordering_Detected
AND NOT GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.CrossDomain_Reactivation_Race
AND NOT GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Recovery_Topology_Divergence
AND NOT GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Residual_Unsafe_Reactivation_Detected THEN

    GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Recovery_Ordering_Integrity_Valid := TRUE;
    GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.CrossDomain_Recovery_Ordering_Stable := TRUE;
    GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Recovery_Authority_Sequencing_Canonical := TRUE;
    GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Physical_Reactivation_Topology_Safe := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Forensic_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Valid := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Granted := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Quarantine_Active := TRUE;

GVL_FORENSIC_EVIDENCE_FABRIC.Authority_Lineage_Reconstructable := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Decision_Causality_Traceable := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Distributed_Evidence_Coherent := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Immutable_Audit_Continuity_Valid := FALSE;
GVL_FORENSIC_EVIDENCE_FABRIC.Recovery_Lineage_Preserved := FALSE;

// Compliance federation required.
IF NOT GVL_COMPLIANCE_FEDERATION_FABRIC.Compliance_Federation_Granted THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43000;
    L_Error_Text := 'Compliance federation authority not granted';
END_IF;

// Forensic split-brain detectors.
IF GVL_FORENSIC_EVIDENCE_FABRIC.Authority_Lineage_Gap_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43001;
    L_Error_Text := 'Authority lineage gap detected';
END_IF;

IF GVL_FORENSIC_EVIDENCE_FABRIC.NonReconstructable_Decision_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43002;
    L_Error_Text := 'Non-reconstructable decision detected';
END_IF;

IF GVL_FORENSIC_EVIDENCE_FABRIC.History_Evidence_Divergence_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43003;
    L_Error_Text := 'History evidence divergence detected';
END_IF;

IF GVL_FORENSIC_EVIDENCE_FABRIC.Causal_Chain_Erosion_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43004;
    L_Error_Text := 'Causal chain erosion detected';
END_IF;

IF GVL_FORENSIC_EVIDENCE_FABRIC.Distributed_Forensic_Inconsistency_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43005;
    L_Error_Text := 'Distributed forensic inconsistency detected';
END_IF;

IF GVL_FORENSIC_EVIDENCE_FABRIC.Immutable_Audit_Discontinuity_Detected THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43006;
    L_Error_Text := 'Immutable audit discontinuity detected';
END_IF;

// Forensic reconstruction validation.
IF L_Forensic_Valid
AND NOT GVL_FORENSIC_EVIDENCE_FABRIC.Historical_Proof_Chain_Valid THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43010;
    L_Error_Text := 'Historical proof chain invalid';
END_IF;

IF L_Forensic_Valid
AND NOT GVL_FORENSIC_EVIDENCE_FABRIC.Governance_Event_Lineage_Coherent THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43011;
    L_Error_Text := 'Governance event lineage coherence invalid';
END_IF;

IF L_Forensic_Valid
AND NOT GVL_FORENSIC_EVIDENCE_FABRIC.Semantic_Transition_Traceable THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43012;
    L_Error_Text := 'Semantic transition traceability invalid';
END_IF;

IF L_Forensic_Valid
AND NOT GVL_FORENSIC_EVIDENCE_FABRIC.Physical_Transition_Traceable THEN
    L_Forensic_Valid := FALSE;
    L_Error_Code := 43013;
    L_Error_Text := 'Physical transition traceability invalid';
END_IF;

IF L_Forensic_Valid THEN
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Valid := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Granted := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Quarantine_Active := FALSE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Authority_Lineage_Reconstructable := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Decision_Causality_Traceable := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Distributed_Evidence_Coherent := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Immutable_Audit_Continuity_Valid := TRUE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Recovery_Lineage_Preserved := TRUE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Epoch :=
        GVL_COMPLIANCE_FEDERATION_FABRIC.Compliance_Federation_Epoch;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Epoch_Coherent := TRUE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Last_Update_MS :=
        L_Now_MS;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Lease_Expired := FALSE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Last_Error_Code := 0;
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Last_Error_Text := '';
ELSE
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Valid := FALSE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Granted := FALSE;
    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Quarantine_Active := TRUE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Lease_Expired := TRUE;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Last_Error_Code :=
        L_Error_Code;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Last_Error_Text :=
        L_Error_Text;

    GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Invalidation_Count :=
        GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Snapshot_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// IMMUTABLE RUNTIME SNAPSHOT GOVERNOR
// ======================================================
// Governs immutable publication snapshot semantics.
// Prevents mutable runtime publication leakage.
//
// Runtime snapshot is upstream of output freshness.
// However distributed publication continuity must
// still remain semantically consistent.
// ======================================================

GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected := FALSE;
GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := FALSE;
GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := FALSE;

// ------------------------------------------------------
// Runtime authority linkage.
// ------------------------------------------------------

IF NOT GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 12000;
    L_Error_Text := 'Runtime authority invalid';
END_IF;

// ------------------------------------------------------
// Distributed publication continuity linkage.
// ------------------------------------------------------

L_Distributed_Publication_Healthy :=
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired;

IF L_Snapshot_Valid
AND NOT L_Distributed_Publication_Healthy
THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 12001;
    L_Error_Text := 'Distributed publication continuity invalid';
END_IF;

// ------------------------------------------------------
// Mutation detection foundation.
// ------------------------------------------------------

IF L_Snapshot_Valid
AND GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected
THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 12003;
    L_Error_Text := 'Runtime mutation anomaly detected';

    GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected := TRUE;
END_IF;

// ------------------------------------------------------
// Immutable snapshot freeze semantics.
// ------------------------------------------------------

IF L_Snapshot_Valid THEN
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := TRUE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid := TRUE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Freeze_Start_MS := L_Now_MS;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Publication_MS := L_Now_MS;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch + 1;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch + 1;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Code := 0;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := FALSE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid := FALSE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Code := L_Error_Code;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Text := L_Error_Text;
END_IF;

// ======================================================
// CENTRAL CONFIGURATION VALIDATION
// ======================================================
// Diagnostic-only layer.
//
// This PRG may set validation/configuration status flags and text,
// but must not directly mutate aggregated diagnostics fields.
// Aggregated diagnostics ownership is centralized in:
//
//   FB_System_Health_Orchestrator
//
// This PRG also must not write command/shadow/output structures.
// ======================================================

L_Config_Error := FALSE;

// ======================================================
// ACTIVE SIZE CONFIGURATION
// ======================================================
IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones > GVL_CONSTANTS.C_MAX_WATER_ZONES) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones > GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Blinds < 0) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Blinds > GVL_CONSTANTS.C_MAX_BLINDS) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Sockets < 0) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Sockets > GVL_CONSTANTS.C_MAX_SOCKETS) THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// HEATING CIRCUIT CONFIGURATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Zone := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].zone);
    L_Sensor := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].sensor_id);
    L_Manifold := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].manifold_id);

    IF (L_Zone < 1) OR (L_Zone > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (L_Sensor < 1) OR (L_Sensor > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (L_Manifold < 1) OR (L_Manifold > GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].min_temp > GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].max_temp THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

IF (GVL_CONFIG.G_Max_Active_Manifolds < 1) OR
   (GVL_CONFIG.G_Max_Active_Manifolds > GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Max_Thermal_Budget <= 0.0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Policy_Min_Hold_MS < 10000 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// ACCESS / TIMING CONFIGURATION
// ======================================================
IF (GVL_CONFIG.G_Access_Pulse_MS < 100) OR (GVL_CONFIG.G_Access_Pulse_MS > 5000) THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// MAP CONFIGURATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
    L_Map_Index := GVL_CONFIG.G_Door_Map[L_i];
    IF (L_Map_Index < 1) OR (L_Map_Index > GVL_CONSTANTS.C_MAX_SECURITY_SENSORS) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Map_Index := GVL_CONFIG.G_Window_Map[L_i];
    IF L_Map_Index <> 0 THEN
        IF (L_Map_Index < 1) OR (L_Map_Index > (GVL_CONSTANTS.C_MAX_SECURITY_SENSORS * 2)) THEN
            L_Config_Error := TRUE;
        END_IF;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF (GVL_CONFIG.G_FloorTemp_Map[L_i] < 1) OR (GVL_CONFIG.G_FloorTemp_Map[L_i] > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    IF (GVL_CONFIG.G_RoomTemp_Map[L_i] < 1) OR (GVL_CONFIG.G_RoomTemp_Map[L_i] > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

// ======================================================
// HARDWARE SERVICE / RETRY CONFIGURATION
// ======================================================
IF GVL_CONFIG.G_Freeze_Hardware_Retry_Count < 0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Freeze_Hardware_Retry_Delay_MS < 1000 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Pump_Exercise_Enabled THEN
    IF GVL_CONFIG.G_Pump_Exercise_Interval_MS < GVL_CONSTANTS.C_MS_IN_MINUTE THEN
        L_Config_Error := TRUE;
    END_IF;
    IF GVL_CONFIG.G_Pump_Exercise_Duration_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Exercise_Enabled THEN
    IF GVL_CONFIG.G_Water_Valve_Exercise_Interval_MS < GVL_CONSTANTS.C_MS_IN_MINUTE THEN
        L_Config_Error := TRUE;
    END_IF;
    IF GVL_CONFIG.G_Water_Valve_Exercise_Duration_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Close_Retry_Count < 0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Close_Retry_Delay_MS < 1000 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// OPENTHERM / MODBUS RTU CONFIGURATION
// ======================================================
IF GVL_CONFIG.G_OpenTherm_Enabled THEN

    IF GVL_CONFIG.G_OpenTherm_Heartbeat_Timeout_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_OpenTherm_Command_Ack_Timeout_MS < 500 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Baudrate < 1200 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Parity > 2) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Stop_Bits < 1) OR
       (GVL_CONFIG.G_Modbus_RTU_Stop_Bits > 2) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Data_Bits < 7) OR
       (GVL_CONFIG.G_Modbus_RTU_Data_Bits > 8) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Slave_ID = 0 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Poll_Interval_MS < 50 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS < 50 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Retry_Count < 0 THEN
        L_Config_Error := TRUE;
    END_IF;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        IF GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Cmd_Enable_Offset = GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Status_Word_Offset THEN
            L_Config_Error := TRUE;
        END_IF;

        IF GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Cmd_Setpoint_x10_Offset = GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Status_Word_Offset THEN
            L_Config_Error := TRUE;
        END_IF;
    END_FOR;
END_IF;

// ======================================================
// SENSOR COUNT SANITY
// ======================================================
IF GVL_CONSTANTS.C_MAX_METHANE_SENSORS < 2 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_SMOKE_SENSORS < 6 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_CO_SENSORS < 8 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_FLOOD_SENSORS < 9 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// CONFIG SIMULATION / COMMISSIONING VALIDATION
// ======================================================
fbConfigSimulation(
    VI_Enable := TRUE,
    VI_Request := GVL_CONFIG_SIMULATION.G_Simulation_Request,
    VI_Confirm := GVL_CONFIG_SIMULATION.G_Simulation_Confirm
);

IF fbConfigSimulation.VO_Executed AND NOT fbConfigSimulation.VO_Result_OK THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// STORE FLAGS
// ======================================================
GVL_CONFIG_VALIDATION.G_Config_Valid := NOT L_Config_Error;
GVL_CONFIG_VALIDATION.G_Config_Critical_Error := L_Config_Error;
GVL_CONFIG_VALIDATION.G_Config_Last_Update_MS := GVL_STATUS.G_System_Time_MS;

IF L_Config_Error THEN
    GVL_CONFIG_VALIDATION.G_Config_Active_Error_Text := 'CONFIG VALIDATION ERROR';
    GVL_STATUS.G_System_Mode_Text := 'CONFIG ERROR';
ELSE
    GVL_CONFIG_VALIDATION.G_Config_Active_Error_Text := '';
END_IF;

IF GVL_CONFIG_VALIDATION.G_Config_Active_Error_Text <> '' THEN
    GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text := GVL_CONFIG_VALIDATION.G_Config_Active_Error_Text;
ELSIF GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text <> '' THEN
    GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text := GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text;
ELSE
    GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text := '';
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Consensus_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Valid := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Granted := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Quarantine_Active := TRUE;

GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Distributed_Governance_Projection_Consistent := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Semantic_Consensus_Valid := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.CrossNode_Authority_Interpretation_Aligned := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Reality_Canonical := FALSE;
GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Projection_Lineage_Coherent := FALSE;

// Semantic epoch invariance required.
IF NOT GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Granted THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50000;
    L_Error_Text := 'Semantic epoch invariance not granted';
END_IF;

// Governance observer split-brain detectors.
IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Governance_Divergence_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50001;
    L_Error_Text := 'Observer governance divergence detected';
END_IF;

IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.CrossNode_Authority_Interpretation_Fork THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50002;
    L_Error_Text := 'Cross-node authority interpretation fork detected';
END_IF;

IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Semantic_Projection_Mismatch_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50003;
    L_Error_Text := 'Semantic projection mismatch detected';
END_IF;

IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Canonical_Governance_Reality_Lost THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50004;
    L_Error_Text := 'Canonical governance reality lost';
END_IF;

IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Projection_Lineage_Drift_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50005;
    L_Error_Text := 'Observer projection lineage drift detected';
END_IF;

IF GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Distributed_Governance_Reality_Fork_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50006;
    L_Error_Text := 'Distributed governance reality fork detected';
END_IF;

// Observer consensus validation.
IF L_Consensus_Valid
AND NOT GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Canonical_Projection_Vector_Stable THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50010;
    L_Error_Text := 'Canonical projection vector invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Distributed_Interpretation_Equivalence_Valid THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50011;
    L_Error_Text := 'Distributed interpretation equivalence invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Projection_Causality_Grounded THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50012;
    L_Error_Text := 'Governance projection causality invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Timeline_Consensus_Monotonic THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 50013;
    L_Error_Text := 'Observer timeline consensus monotonicity invalid';
END_IF;

IF L_Consensus_Valid THEN
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Valid := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Granted := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Quarantine_Active := FALSE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Distributed_Governance_Projection_Consistent := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Semantic_Consensus_Valid := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.CrossNode_Authority_Interpretation_Aligned := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Reality_Canonical := TRUE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Observer_Projection_Lineage_Coherent := TRUE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Epoch :=
        GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Epoch;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Epoch_Coherent := TRUE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Last_Update_MS :=
        L_Now_MS;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Lease_Expired := FALSE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Last_Error_Code := 0;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Last_Error_Text := '';
ELSE
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Valid := FALSE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Granted := FALSE;
    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Quarantine_Active := TRUE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Lease_Expired := TRUE;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Last_Error_Code :=
        L_Error_Code;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Last_Error_Text :=
        L_Error_Text;

    GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Invalidation_Count :=
        GVL_GOVERNANCE_OBSERVER_CONSENSUS_FABRIC.Governance_Observer_Consensus_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Transport_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// TRANSPORT FRESHNESS GOVERNOR
// ======================================================
// Governs transport freshness semantics.
// Prevents stale transport semantic publication.
//
// Transport freshness is upstream of runtime barrier in MAIN.
// It must not consume runtime barrier or downstream recovery
// governance state, because runtime barrier consumes transport
// freshness state later in the same scan-cycle.
// ======================================================

GVL_TRANSPORT_FRESHNESS.Transport_Stale_Frame_Detected := FALSE;
GVL_TRANSPORT_FRESHNESS.Transport_Transaction_Mismatch := FALSE;
GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid := FALSE;

// Monotonic authority linkage.
IF L_Transport_Valid AND (NOT GVL_TIME_MONOTONIC.Monotonic_Time_Valid) THEN
    L_Transport_Valid := FALSE;
    L_Error_Code := 10001;
    L_Error_Text := 'Transport monotonic authority invalid';
END_IF;

// Transport reconnect quarantine.
IF GVL_TRANSPORT_FRESHNESS.Transport_Reconnect_Stabilizing THEN
    GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active := TRUE;

    L_Transport_Valid := FALSE;

    IF L_Error_Code = 0 THEN
        L_Error_Code := 10003;
        L_Error_Text := 'Transport reconnect stabilization active';
    END_IF;
END_IF;

// Lease freshness validation.
L_Delta_MS := L_Now_MS - GVL_TRANSPORT_FRESHNESS.Transport_Last_Refresh_MS;

IF L_Transport_Valid AND GVL_TRANSPORT_FRESHNESS.Transport_Lease_Valid THEN
    IF L_Delta_MS > GVL_TRANSPORT_FRESHNESS.Transport_Lease_Timeout_MS THEN
        L_Transport_Valid := FALSE;
        L_Error_Code := 10004;
        L_Error_Text := 'Transport lease expired';

        GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired := TRUE;
    END_IF;
END_IF;

// Publish authoritative transport freshness state.
IF L_Transport_Valid THEN
    GVL_TRANSPORT_FRESHNESS.Transport_Epoch := GVL_TRANSPORT_FRESHNESS.Transport_Epoch + 1;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Epoch := GVL_TRANSPORT_FRESHNESS.Transport_Publication_Epoch + 1;

    GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid := TRUE;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed := TRUE;

    GVL_TRANSPORT_FRESHNESS.Transport_Lease_Valid := TRUE;
    GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Refresh_MS := L_Now_MS;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Publication_MS := L_Now_MS;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Code := 0;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Text := '';
ELSE
    GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid := FALSE;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid := TRUE;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Code := L_Error_Code;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Text := L_Error_Text;

    GVL_TRANSPORT_FRESHNESS.Transport_Invalidation_Count := GVL_TRANSPORT_FRESHNESS.Transport_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Invariance_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Valid := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Granted := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Quarantine_Active := TRUE;

GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Authority_Semantics_Invariant := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.CrossEpoch_Permission_Mapping_Stable := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Intent_Continuity_Valid := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Governance_Meaning_Preservation_Coherent := FALSE;
GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Evolution_Lineage_Traceable := FALSE;

// Trust epoch monotonicity required.
IF NOT GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Granted THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49000;
    L_Error_Text := 'Trust epoch monotonicity not granted';
END_IF;

// Semantic epoch drift detectors.
IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Authority_Drift_Detected THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49001;
    L_Error_Text := 'Semantic authority drift detected';
END_IF;

IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.CrossEpoch_Permission_Reinterpretation THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49002;
    L_Error_Text := 'Cross-epoch permission reinterpretation detected';
END_IF;

IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Intent_To_Authority_Mismatch_Detected THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49003;
    L_Error_Text := 'Intent-to-authority mismatch detected';
END_IF;

IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Governance_Semantic_Fork_Detected THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49004;
    L_Error_Text := 'Governance semantic fork detected';
END_IF;

IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Migration_Lineage_Gap_Detected THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49005;
    L_Error_Text := 'Semantic migration lineage gap detected';
END_IF;

IF GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Distributed_Semantic_Divergence_Detected THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49006;
    L_Error_Text := 'Distributed semantic divergence detected';
END_IF;

// Semantic invariance validation.
IF L_Invariance_Valid
AND NOT GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Explicit_Semantic_Migration_Governed THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49010;
    L_Error_Text := 'Explicit semantic migration governance invalid';
END_IF;

IF L_Invariance_Valid
AND NOT GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.CrossEpoch_Semantic_Equivalence_Valid THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49011;
    L_Error_Text := 'Cross-epoch semantic equivalence invalid';
END_IF;

IF L_Invariance_Valid
AND NOT GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Distributed_Semantic_Consensus_Stable THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49012;
    L_Error_Text := 'Distributed semantic consensus invalid';
END_IF;

IF L_Invariance_Valid
AND NOT GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Interpretation_Integrity_Valid THEN
    L_Invariance_Valid := FALSE;
    L_Error_Code := 49013;
    L_Error_Text := 'Semantic interpretation integrity invalid';
END_IF;

IF L_Invariance_Valid THEN
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Valid := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Granted := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Quarantine_Active := FALSE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Authority_Semantics_Invariant := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.CrossEpoch_Permission_Mapping_Stable := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Intent_Continuity_Valid := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Governance_Meaning_Preservation_Coherent := TRUE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Evolution_Lineage_Traceable := TRUE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Epoch :=
        GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Epoch;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Epoch_Coherent := TRUE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Last_Update_MS :=
        L_Now_MS;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Lease_Expired := FALSE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Last_Error_Code := 0;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Valid := FALSE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Granted := FALSE;
    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Quarantine_Active := TRUE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Lease_Expired := TRUE;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Last_Error_Code :=
        L_Error_Code;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Last_Error_Text :=
        L_Error_Text;

    GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Invalidation_Count :=
        GVL_SEMANTIC_EPOCH_INVARIANCE_FABRIC.Semantic_Epoch_Invariance_Invalidation_Count + 1;
END_IF;

L_Weights.W_Comfort := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort;
L_Weights.W_Night := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night;
L_Weights.W_Preheat := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat;
L_Weights.W_VentBoost := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost;
L_Weights.W_AccessSecure := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure;

L_Hour := TO_INT(GVL_TIME_SERVICE.G_Time_Of_Day_MS / 3600000);

GVL_INTENT_BEHAVIOR.I_Request_Night_Mode := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode := FALSE;

GVL_INTENT_BEHAVIOR.I_Score_Comfort := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Comfort_Base_Score * L_Weights.W_Comfort);
GVL_INTENT_BEHAVIOR.I_Score_Night := 0;
GVL_INTENT_BEHAVIOR.I_Score_Preheat := 0;
GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost := 0;
GVL_INTENT_BEHAVIOR.I_Score_Access_Secure := 0;

IF (L_Hour >= GVL_SCENARIO_CONFIG.G_Night_Start_Hour) OR (L_Hour < GVL_SCENARIO_CONFIG.G_Night_End_Hour) THEN
    GVL_INTENT_BEHAVIOR.I_Score_Night := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Night_Base_Score * L_Weights.W_Night);
END_IF;

IF GVL_INPUT.IN_Preheat_Request THEN
    GVL_INTENT_BEHAVIOR.I_Score_Preheat := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Preheat_Base_Score * L_Weights.W_Preheat);
END_IF;

L_BestVentScore := 0.0;
L_BestVentZone := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Hum := GVL_INPUT.IN_Room_Hum[L_i];

    IF GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight = 0.0 THEN
        L_ZoneWeight := GVL_BEHAVIOR_ADAPT.G_Adapt_Default_Zone_Weight;
    ELSE
        L_ZoneWeight := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight;
    END_IF;

    L_AdaptConfidence := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Confidence;
    IF L_AdaptConfidence <= 0.0 THEN
        L_AdaptConfidence := GVL_SCENARIO_CONFIG.G_Fallback_Adapt_Confidence;
    END_IF;

    L_InputConfidence := GVL_INPUT.IN_Zone_Confidence[L_i];
    IF L_InputConfidence <= 0.0 THEN
        L_InputConfidence := GVL_SCENARIO_CONFIG.G_Fallback_Input_Confidence;
    END_IF;

    L_ZoneConfidence := L_AdaptConfidence * L_InputConfidence;

    IF L_Hum > GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold THEN
        L_ZoneScore := GVL_SCENARIO_CONFIG.G_VentBoost_Base_Score * L_Weights.W_VentBoost * L_ZoneWeight * L_ZoneConfidence;

        IF L_ZoneScore > L_BestVentScore THEN
            L_BestVentScore := L_ZoneScore;
            L_BestVentZone := L_i;
        END_IF;
    END_IF;
END_FOR;

GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost := REAL_TO_INT(L_BestVentScore);
GVL_INTENT_BEHAVIOR.I_Best_VentBoost_Zone := L_BestVentZone;

IF (L_Hour >= GVL_SCENARIO_CONFIG.G_Access_Secure_Start_Hour) OR (L_Hour < GVL_SCENARIO_CONFIG.G_Access_Secure_End_Hour) THEN
    GVL_INTENT_BEHAVIOR.I_Score_Access_Secure := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_AccessSecure_Base_Score * L_Weights.W_AccessSecure);
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Night >= GVL_SCENARIO_CONFIG.G_Night_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Night_Mode := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Preheat >= GVL_SCENARIO_CONFIG.G_Comfort_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost >= GVL_SCENARIO_CONFIG.G_VentBoost_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Access_Secure >= GVL_SCENARIO_CONFIG.G_AccessSecure_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode := TRUE;
END_IF;

GVL_INTENT_BEHAVIOR.I_Weight_Night := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Night) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Comfort := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Comfort) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Vent_Boost := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Access_Secure := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Access_Secure) / 100.0;

IF GVL_INTENT_BEHAVIOR.I_Request_Night_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Night mode';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Vent Boost';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Comfort';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Access Secure';
ELSE
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Idle';
END_IF;

GVL_INTENT_BEHAVIOR.I_Reason_Text := GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text;
GVL_INTENT_BEHAVIOR.I_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

L_Trace_Changed :=
    (GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text <> L_Last_Selected_Scenario_Text)
    OR (GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost <> L_Last_Vent_Boost_Request)
    OR (GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost <> L_Last_Vent_Boost_Score);

IF L_Trace_Changed THEN
    fbTrace(
        iLayer := TRACE_SCENARIO,
        iSource := SRC_SCENARIO,
        iReason := REASON_SCENARIO_VENT_BOOST,
        iValueBool := GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost,
        iValueReal := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost),
        iText := GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text
    );

    L_Last_Selected_Scenario_Text := GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text;
    L_Last_Vent_Boost_Request := GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost;
    L_Last_Vent_Boost_Score := GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost;
END_IF;

// ======================================================
// DISTRIBUTED PEER INGESTION
// ======================================================
// Bounded peer-session ingestion layer.
//
// Purpose:
// normalize replicated HA session state into distributed
// peer-input fields consumed by distributed governors.
//
// This layer does NOT:
// - perform reconciliation/quarantine decisions
// - perform split-brain detection
// - validate peer publication correctness
// - mutate local runtime authority
// ======================================================

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ------------------------------------------------------
// Peer session freshness projection.
// ------------------------------------------------------

GVL_DISTRIBUTED_EPOCH.Peer_Last_Refresh_MS :=
    GVL_HA_SESSION_REPLICATION.HA_Remote_Last_Refresh_MS;

GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active :=
    GVL_HA_SESSION_REPLICATION.HA_Remote_Session_Valid;

// ------------------------------------------------------
// Replicated remote session ingestion.
// ------------------------------------------------------

IF GVL_HA_SESSION_REPLICATION.HA_Remote_Session_Valid THEN
    GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Runtime_Epoch;

    GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Snapshot_Epoch;

    GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Boot_Generation;

    GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Fencing_Token;
ELSE
    GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active := FALSE;
    GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch := 0;
    GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch := 0;
    GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation := 0;
    GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token := 0;
    GVL_DISTRIBUTED_EPOCH.Peer_Last_Refresh_MS := 0;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Distributed_Peer_Ingestion <<<

// Passive maintainability governance placeholder.
// Runtime maintainability state is currently represented by fabric GVLs only.
// This program is intentionally side-effect free until ownership is formalized.

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Consensus_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid := FALSE;
GVL_SENSOR_CONSENSUS.Sensor_Consensus_Quarantine_Active := TRUE;
GVL_SENSOR_CONSENSUS.Sensor_Consensus_Lease_Expired := TRUE;
GVL_SENSOR_CONSENSUS.Sensor_Consensus_Freshness_Valid := FALSE;

GVL_SENSOR_CONSENSUS.Physics_Invariants_Satisfied := FALSE;
GVL_SENSOR_CONSENSUS.Cross_Sensor_Correlation_Valid := FALSE;
GVL_SENSOR_CONSENSUS.Telemetry_Plausibility_Valid := FALSE;

IF GVL_SENSOR_CONSENSUS.Sensor_Replay_Suspected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22000;
    L_Error_Text := 'Sensor replay suspected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Sensor_Partition_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22001;
    L_Error_Text := 'Sensor partition detected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Sensor_Hallucination_Suspected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22002;
    L_Error_Text := 'Sensor hallucination suspected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Cross_Sensor_Divergence_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22003;
    L_Error_Text := 'Cross sensor divergence detected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Sensor_Drift_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22004;
    L_Error_Text := 'Sensor drift detected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Sensor_Oscillation_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22005;
    L_Error_Text := 'Sensor oscillation detected';
END_IF;

IF L_Consensus_Valid
AND GVL_SENSOR_CONSENSUS.Sensor_Stuck_State_Detected THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22006;
    L_Error_Text := 'Sensor stuck state detected';
END_IF;

// Physics invariants.
IF L_Consensus_Valid
AND NOT GVL_SENSOR_CONSENSUS.Flow_Response_Valid THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22010;
    L_Error_Text := 'Flow response invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_SENSOR_CONSENSUS.Pressure_Response_Valid THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22011;
    L_Error_Text := 'Pressure response invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_SENSOR_CONSENSUS.Airflow_Response_Valid THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22012;
    L_Error_Text := 'Airflow response invalid';
END_IF;

IF L_Consensus_Valid
AND NOT GVL_SENSOR_CONSENSUS.Current_Signature_Valid THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22013;
    L_Error_Text := 'Current signature invalid';
END_IF;

// Consensus freshness.
L_Consensus_Age_MS :=
    L_Now_MS - GVL_SENSOR_CONSENSUS.Last_Consensus_Update_MS;

IF L_Consensus_Valid
AND (L_Consensus_Age_MS > 5000) THEN
    L_Consensus_Valid := FALSE;
    L_Error_Code := 22020;
    L_Error_Text := 'Sensor consensus stale';
END_IF;

IF L_Consensus_Valid THEN
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid := TRUE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Quarantine_Active := FALSE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Lease_Expired := FALSE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Freshness_Valid := TRUE;

    GVL_SENSOR_CONSENSUS.Physics_Invariants_Satisfied := TRUE;
    GVL_SENSOR_CONSENSUS.Cross_Sensor_Correlation_Valid := TRUE;
    GVL_SENSOR_CONSENSUS.Telemetry_Plausibility_Valid := TRUE;

    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Epoch :=
        GVL_SENSOR_CONSENSUS.Sensor_Consensus_Epoch + 1;

    GVL_SENSOR_CONSENSUS.Last_Consensus_Update_MS := L_Now_MS;

    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Last_Error_Code := 0;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Last_Error_Text := '';
ELSE
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid := FALSE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Quarantine_Active := TRUE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Lease_Expired := TRUE;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Freshness_Valid := FALSE;

    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Last_Error_Code := L_Error_Code;
    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Last_Error_Text := L_Error_Text;

    GVL_SENSOR_CONSENSUS.Sensor_Consensus_Invalidation_Count :=
        GVL_SENSOR_CONSENSUS.Sensor_Consensus_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Integrity_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Valid := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Granted := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Quarantine_Active := TRUE;

GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Execution_Feedback_Causality_Isolated := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Derivation_Inputs_Canonical := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Telemetry_To_Authority_Lineage_Valid := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Feedback_Epoch_Integrity_Stable := FALSE;
GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Lineage_Coherent := FALSE;

// Execution projection integrity required.
IF NOT GVL_EXECUTION_PROJECTION_INTEGRITY_FABRIC.Execution_Projection_Integrity_Granted THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52000;
    L_Error_Text := 'Execution projection integrity not granted';
END_IF;

// Governance feedback poisoning detectors.
IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Poisoning_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52001;
    L_Error_Text := 'Governance feedback poisoning detected';
END_IF;

IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Execution_Telemetry_Authority_Corruption THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52002;
    L_Error_Text := 'Execution telemetry authority corruption detected';
END_IF;

IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.CrossEpoch_Feedback_Lineage_Drift THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52003;
    L_Error_Text := 'Cross-epoch feedback lineage drift detected';
END_IF;

IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Retroactive_Governance_Mutation_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52004;
    L_Error_Text := 'Retroactive governance mutation detected';
END_IF;

IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Distributed_Feedback_Fork_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52005;
    L_Error_Text := 'Distributed feedback fork detected';
END_IF;

IF GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Untrusted_Execution_Observation_Injected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52006;
    L_Error_Text := 'Untrusted execution observation injected';
END_IF;

// Governance feedback validation.
IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Authenticated_Execution_Observation_Valid THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52010;
    L_Error_Text := 'Authenticated execution observation invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.CrossEpoch_Feedback_Continuity_Stable THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52011;
    L_Error_Text := 'Cross-epoch feedback continuity invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Input_Causality_Grounded THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52012;
    L_Error_Text := 'Governance input causality invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Distributed_Feedback_Consensus_Valid THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 52013;
    L_Error_Text := 'Distributed feedback consensus invalid';
END_IF;

IF L_Integrity_Valid THEN
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Valid := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Granted := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Quarantine_Active := FALSE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Execution_Feedback_Causality_Isolated := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Derivation_Inputs_Canonical := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Telemetry_To_Authority_Lineage_Valid := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Feedback_Epoch_Integrity_Stable := TRUE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Lineage_Coherent := TRUE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Epoch :=
        GVL_EXECUTION_PROJECTION_INTEGRITY_FABRIC.Execution_Projection_Integrity_Epoch;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Epoch_Coherent := TRUE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Last_Update_MS :=
        L_Now_MS;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Lease_Expired := FALSE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Last_Error_Code := 0;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Last_Error_Text := '';
ELSE
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Valid := FALSE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Granted := FALSE;
    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Quarantine_Active := TRUE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Lease_Expired := TRUE;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Last_Error_Code :=
        L_Error_Code;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Last_Error_Text :=
        L_Error_Text;

    GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Invalidation_Count :=
        GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Invalidation_Count + 1;
END_IF;

IF GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Authority_Resurrection_Boundary_Valid
AND NOT GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Residual_Energy_Leakage_Detected
AND NOT GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.CrossDomain_Power_Backfeed_Detected
AND NOT GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.SplitEnergy_Topology_Detected
AND NOT GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Unsafe_Energy_Propagation_Detected THEN

    GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Energy_Isolation_Causality_Valid := TRUE;
    GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Energy_Isolation_Causality_Granted := TRUE;
    GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Physical_Energy_Isolation_Valid := TRUE;
    GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Unsafe_Energy_Propagation_Prevented := TRUE;
    GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.CrossDomain_Power_Segmentation_Canonical := TRUE;
END_IF;

// PASSIVE ASSUMPTION OBSERVABILITY ONLY

GVL_RUNTIME_ASSUMPTION_INTEGRITY_FABRIC.Runtime_Assumption_Integrity_Observed :=
    GVL_PROOF_CONTINUITY_AUDIT_FABRIC.Proof_Continuity_Observed;

GVL_RUNTIME_ASSUMPTION_INTEGRITY_FABRIC.Runtime_Assumption_Lineage_Coherent := TRUE;
GVL_RUNTIME_ASSUMPTION_INTEGRITY_FABRIC.Runtime_Assumption_Stability_Observed := TRUE;

// SEMANTIC DOMAIN WRAPPER
// PRESERVES ORIGINAL EXECUTION ORDER
// NO EXECUTION SEMANTICS MUTATION

PRG_Safety();
PRG_Safety_Operator();
PRG_Safety_Shutdown();
PRG_Safety_Recovery();

PRG_Physical_SafeState_Lattice_Governor();
PRG_CrossDomain_FailSafe_Closure_Governor();

PRG_Safety_Observability_Truth_Governor();
PRG_Physical_Safety_Projection_Governor();

// Default per-circuit comfort/economy profiles.
// This initializer only fills empty records and does not overwrite HMI-edited
// records after circuit_id has been assigned.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].circuit_id = 0 THEN
        CASE L_i OF
            1, 2, 3, 4:
                L_Manifold := 1;
            5, 6, 7, 8:
                L_Manifold := 2;
            9, 10, 11, 12:
                L_Manifold := 3;
            13, 14:
                L_Manifold := 4;
        ELSE
                L_Manifold := 5;
        END_CASE;

        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].circuit_id := TO_BYTE(L_i);
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].zone := TO_BYTE(L_i);
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].manifold_id := L_Manifold;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].sensor_id := TO_BYTE(L_i);
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].valve_id := TO_BYTE(L_i);
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].control_type := 1;

        // Historical design_temp is kept, but explicit comfort_temp is now the
        // room comfort setpoint used by FB_Heating_Circuit_Control.
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].design_temp := 22.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].use_in_normal := TRUE;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].use_in_away_preheat := TRUE;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].comfort_temp := 22.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].economy_temp := 17.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].long_away_temp := 12.0;

        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].min_temp := 5.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].max_temp := 30.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].pid_kp := 2.0;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].pwm_period_s := 600;
    END_IF;
END_FOR;

PRG_Away_Heating_HMI_Applicator();

// Observational periodic due gates for domain execution policy.
// Does not gate execution and does not write physical outputs.


fbAccessDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Due := fbAccessDue.VO_Due;

fbLightingDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Due := fbLightingDue.VO_Due;

fbWaterDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Due := fbWaterDue.VO_Due;

fbHeatingDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Due := fbHeatingDue.VO_Due;

fbVentDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Due := fbVentDue.VO_Due;

fbSimulationDue(
    VI_Enable := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Run_Allowed,
    VI_Now_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Interval_MS := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Periodic_Interval_MS
);
GVL_DOMAIN_EXECUTION_POLICY.Simulation_Periodic_Due := fbSimulationDue.VO_Due;

GVL_DOMAIN_EXECUTION_POLICY.Any_Periodic_Due :=
    GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Due
    OR GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Due
    OR GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Due
    OR GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Due
    OR GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Due
    OR GVL_DOMAIN_EXECUTION_POLICY.Simulation_Periodic_Due;

// >>> BULK_SYNC_ANCHOR: PRG_Domain_Execution_Policy_Periodic <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Stability_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_TEMPORAL_STABILITY.Temporal_Stability_Valid := FALSE;
GVL_TEMPORAL_STABILITY.Temporal_Stability_Granted := FALSE;
GVL_TEMPORAL_STABILITY.Temporal_Stability_Quarantine_Active := TRUE;

GVL_TEMPORAL_STABILITY.Post_Convergence_Stable := FALSE;
GVL_TEMPORAL_STABILITY.No_Oscillation_Detected := FALSE;
GVL_TEMPORAL_STABILITY.No_Relay_Chatter_Detected := FALSE;
GVL_TEMPORAL_STABILITY.Thermal_Slope_Stable := FALSE;
GVL_TEMPORAL_STABILITY.Pressure_Stable := FALSE;
GVL_TEMPORAL_STABILITY.Flow_Stable := FALSE;

// Temporal stability requires completed physical transaction.
IF NOT GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Granted THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28000;
    L_Error_Text := 'Physical transaction not granted';
END_IF;

// Start deterministic observation window.
IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.Stability_Observation_Window_Active THEN
    GVL_TEMPORAL_STABILITY.Stability_Observation_Window_Active := TRUE;
    GVL_TEMPORAL_STABILITY.Stability_Window_Start_MS := L_Now_MS;
END_IF;

IF GVL_TEMPORAL_STABILITY.Stability_Observation_Window_Active THEN
    GVL_TEMPORAL_STABILITY.Stability_Window_Elapsed_MS :=
        L_Now_MS - GVL_TEMPORAL_STABILITY.Stability_Window_Start_MS;
END_IF;

// Observation window must fully elapse.
IF L_Stability_Valid
AND (GVL_TEMPORAL_STABILITY.Stability_Window_Elapsed_MS <
     GVL_TEMPORAL_STABILITY.Stability_Window_Target_MS) THEN

    L_Stability_Valid := FALSE;
    L_Error_Code := 28001;
    L_Error_Text := 'Temporal observation window not elapsed';
END_IF;

// Delayed instability detection.
IF GVL_TEMPORAL_STABILITY.Post_Convergence_Oscillation_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28002;
    L_Error_Text := 'Post-convergence oscillation detected';
END_IF;

IF GVL_TEMPORAL_STABILITY.Thermal_Inertia_Rebound_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28003;
    L_Error_Text := 'Thermal inertia rebound detected';
END_IF;

IF GVL_TEMPORAL_STABILITY.Pressure_Rebound_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28004;
    L_Error_Text := 'Pressure rebound detected';
END_IF;

IF GVL_TEMPORAL_STABILITY.Relay_Chatter_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28005;
    L_Error_Text := 'Relay chatter detected';
END_IF;

IF GVL_TEMPORAL_STABILITY.Pump_Cavitation_Recovery_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28006;
    L_Error_Text := 'Pump cavitation recovery detected';
END_IF;

IF GVL_TEMPORAL_STABILITY.Delayed_Actuator_Divergence_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28007;
    L_Error_Text := 'Delayed actuator divergence detected';
END_IF;

// Stable physical conditions required.
IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.No_Oscillation_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28010;
    L_Error_Text := 'Oscillation-free state not confirmed';
END_IF;

IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.No_Relay_Chatter_Detected THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28011;
    L_Error_Text := 'Relay chatter-free state not confirmed';
END_IF;

IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.Thermal_Slope_Stable THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28012;
    L_Error_Text := 'Thermal slope stability missing';
END_IF;

IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.Pressure_Stable THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28013;
    L_Error_Text := 'Pressure stability missing';
END_IF;

IF L_Stability_Valid
AND NOT GVL_TEMPORAL_STABILITY.Flow_Stable THEN
    L_Stability_Valid := FALSE;
    L_Error_Code := 28014;
    L_Error_Text := 'Flow stability missing';
END_IF;

IF L_Stability_Valid THEN
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Valid := TRUE;
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Granted := TRUE;
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Quarantine_Active := FALSE;

    GVL_TEMPORAL_STABILITY.Post_Convergence_Stable := TRUE;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Epoch :=
        GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Epoch;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Epoch_Coherent := TRUE;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Last_Update_MS :=
        L_Now_MS;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Lease_Expired := FALSE;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Last_Error_Code := 0;
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Last_Error_Text := '';
ELSE
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Valid := FALSE;
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Granted := FALSE;
    GVL_TEMPORAL_STABILITY.Temporal_Stability_Quarantine_Active := TRUE;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Lease_Expired := TRUE;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Last_Error_Code :=
        L_Error_Code;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Last_Error_Text :=
        L_Error_Text;

    GVL_TEMPORAL_STABILITY.Temporal_Stability_Invalidation_Count :=
        GVL_TEMPORAL_STABILITY.Temporal_Stability_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Meta_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Valid := FALSE;
GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Granted := FALSE;
GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Quarantine_Active := TRUE;

GVL_META_GOVERNANCE_FABRIC.Governance_Graph_Acyclic := FALSE;
GVL_META_GOVERNANCE_FABRIC.Authority_Rooting_Valid := FALSE;
GVL_META_GOVERNANCE_FABRIC.Independent_Validation_Preserved := FALSE;
GVL_META_GOVERNANCE_FABRIC.Meta_Consistency_Coherent := FALSE;
GVL_META_GOVERNANCE_FABRIC.Recursive_Trust_Boundaries_Stable := FALSE;

// Epistemic integrity required.
IF NOT GVL_EPISTEMIC_INTEGRITY_FABRIC.Epistemic_Integrity_Granted THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45000;
    L_Error_Text := 'Epistemic integrity authority not granted';
END_IF;

// Meta-governance recursion detectors.
IF GVL_META_GOVERNANCE_FABRIC.Recursive_Authority_Dependency_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45001;
    L_Error_Text := 'Recursive authority dependency detected';
END_IF;

IF GVL_META_GOVERNANCE_FABRIC.Circular_Validation_Chain_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45002;
    L_Error_Text := 'Circular validation chain detected';
END_IF;

IF GVL_META_GOVERNANCE_FABRIC.SelfJustifying_Governance_State_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45003;
    L_Error_Text := 'Self-justifying governance state detected';
END_IF;

IF GVL_META_GOVERNANCE_FABRIC.Epistemic_Recursion_Leakage_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45004;
    L_Error_Text := 'Epistemic recursion leakage detected';
END_IF;

IF GVL_META_GOVERNANCE_FABRIC.Authority_Bootstrap_Paradox_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45005;
    L_Error_Text := 'Authority bootstrap paradox detected';
END_IF;

IF GVL_META_GOVERNANCE_FABRIC.Meta_Consistency_Erosion_Detected THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45006;
    L_Error_Text := 'Meta-consistency erosion detected';
END_IF;

// Meta-governance consistency validation.
IF L_Meta_Valid
AND NOT GVL_META_GOVERNANCE_FABRIC.Validator_Independence_Valid THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45010;
    L_Error_Text := 'Validator independence invalid';
END_IF;

IF L_Meta_Valid
AND NOT GVL_META_GOVERNANCE_FABRIC.CrossLayer_Causality_Grounded THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45011;
    L_Error_Text := 'Cross-layer causality grounding invalid';
END_IF;

IF L_Meta_Valid
AND NOT GVL_META_GOVERNANCE_FABRIC.Bootstrap_Validation_Absent THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45012;
    L_Error_Text := 'Bootstrap validation absence invalid';
END_IF;

IF L_Meta_Valid
AND NOT GVL_META_GOVERNANCE_FABRIC.SelfReference_Elimination_Valid THEN
    L_Meta_Valid := FALSE;
    L_Error_Code := 45013;
    L_Error_Text := 'Self-reference elimination invalid';
END_IF;

IF L_Meta_Valid THEN
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Valid := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Granted := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Quarantine_Active := FALSE;

    GVL_META_GOVERNANCE_FABRIC.Governance_Graph_Acyclic := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Authority_Rooting_Valid := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Independent_Validation_Preserved := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Meta_Consistency_Coherent := TRUE;
    GVL_META_GOVERNANCE_FABRIC.Recursive_Trust_Boundaries_Stable := TRUE;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Epoch :=
        GVL_EPISTEMIC_INTEGRITY_FABRIC.Epistemic_Integrity_Epoch;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Epoch_Coherent := TRUE;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Last_Update_MS :=
        L_Now_MS;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Lease_Expired := FALSE;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Last_Error_Code := 0;
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Last_Error_Text := '';
ELSE
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Valid := FALSE;
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Granted := FALSE;
    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Quarantine_Active := TRUE;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Lease_Expired := TRUE;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Last_Error_Code :=
        L_Error_Code;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Last_Error_Text :=
        L_Error_Text;

    GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Invalidation_Count :=
        GVL_META_GOVERNANCE_FABRIC.Meta_Governance_Invalidation_Count + 1;
END_IF;

GVL_INPUT.IN_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_INPUT.IN_Source_Valid := GVL_STATUS.G_Is_Active_PLC;

// RESET FLAGS
GVL_INPUT.IN_Validation_Failed := FALSE;
GVL_INPUT.IN_Anomaly_Detected := FALSE;
GVL_INPUT.IN_Validation_Reason := '';
GVL_INPUT.IN_Anomaly_Reason := '';
GVL_INPUT.IN_Last_Invalid_Zone := 0;
GVL_INPUT.IN_Input_Degraded := FALSE;
GVL_INPUT.IN_Sensor_Fault := FALSE;

GVL_INPUT.IN_Min_Zone_Confidence := REAL#1.0;
GVL_INPUT.IN_Worst_Zone := 0;

// ======================================================
// BASE ENVIRONMENT INPUT AGGREGATION
// ======================================================
GVL_INPUT.IN_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp;
GVL_INPUT.IN_Preheat_Request := GVL_STATE.G_Preheat_Request;
GVL_INPUT.IN_Freeze_Request := GVL_STATE.G_Freeze_Request;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    GVL_INPUT.IN_Room_Temps[L_i] := GVL_STATE.G_Room_Temps[L_i];
    GVL_INPUT.IN_Room_Hum[L_i] := GVL_STATE.G_Room_Hum[L_i];
    GVL_INPUT.IN_Room_CO2[L_i] := GVL_STATE.G_Room_CO2[L_i];

    // ======================================================
    // RANGE VALIDATION
    // ======================================================
    IF (GVL_INPUT.IN_Room_Temps[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Min) OR
       (GVL_INPUT.IN_Room_Temps[L_i] > GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Max) THEN
        GVL_INPUT.IN_Validation_Failed := TRUE;
        GVL_INPUT.IN_Input_Degraded := TRUE;
        GVL_INPUT.IN_Sensor_Fault := TRUE;
        GVL_INPUT.IN_Validation_Reason := 'Temp out of range';
        GVL_INPUT.IN_Last_Invalid_Zone := L_i;
    END_IF;

    IF (GVL_INPUT.IN_Room_Hum[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Min) OR
       (GVL_INPUT.IN_Room_Hum[L_i] > GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Max) THEN
        GVL_INPUT.IN_Validation_Failed := TRUE;
        GVL_INPUT.IN_Input_Degraded := TRUE;
        GVL_INPUT.IN_Sensor_Fault := TRUE;
        GVL_INPUT.IN_Validation_Reason := 'Hum out of range';
        GVL_INPUT.IN_Last_Invalid_Zone := L_i;
    END_IF;

    // ======================================================
    // TEMPERATURE QUALITY SEMANTICS
    // ======================================================
    // Temperature confidence/anomaly publication is now sourced from
    // the passive input quality observer. This replaces the old duplicated
    // local spike calculation while preserving GVL_INPUT as the canonical
    // normalized read-model surface.
    IF GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Quality_Visible THEN
        GVL_INPUT.IN_Room_Temp_Confidence[L_i] :=
            GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Confidence;

        IF GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Value_Degraded THEN
            GVL_INPUT.IN_Input_Degraded := TRUE;
            GVL_INPUT.IN_Anomaly_Detected := TRUE;
            GVL_INPUT.IN_Anomaly_Reason :=
                GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Reason_Text;
            GVL_INPUT.IN_Last_Invalid_Zone := L_i;
        END_IF;

        IF NOT GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Value_Valid THEN
            GVL_INPUT.IN_Validation_Failed := TRUE;
            GVL_INPUT.IN_Sensor_Fault := TRUE;
            GVL_INPUT.IN_Validation_Reason :=
                GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i].Reason_Text;
            GVL_INPUT.IN_Last_Invalid_Zone := L_i;
        END_IF;
    ELSE
        GVL_INPUT.IN_Room_Temp_Confidence[L_i] :=
            GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;
    END_IF;

    // ======================================================
    // HUMIDITY QUALITY SEMANTICS
    // ======================================================
    // Humidity still uses the simplified local path because there is no
    // dedicated humidity input-quality observer yet.
    L_HumDelta := ABS(GVL_INPUT.IN_Room_Hum[L_i] - GVL_INPUT.IN_Room_Hum_Prev[L_i]);

    GVL_INPUT.IN_Room_Hum_Confidence[L_i] :=
        GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;

    IF L_HumDelta > GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Spike_Threshold THEN
        GVL_INPUT.IN_Room_Hum_Confidence[L_i] :=
            GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence;
        GVL_INPUT.IN_Anomaly_Detected := TRUE;
        GVL_INPUT.IN_Anomaly_Reason := 'Hum spike';
    END_IF;

    // ======================================================
    // REPUTATION
    // ======================================================
    IF GVL_INPUT_VALIDATION_CONFIG.G_Enable_Reputation_Learning THEN
        GVL_INPUT.IN_Room_Temp_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Temp_Reputation[L_i] * (REAL#1.0 - GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate) +
            GVL_INPUT.IN_Room_Temp_Confidence[L_i] * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;

        GVL_INPUT.IN_Room_Hum_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Hum_Reputation[L_i] * (REAL#1.0 - GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate) +
            GVL_INPUT.IN_Room_Hum_Confidence[L_i] * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;

        GVL_INPUT.IN_Room_Temp_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Temp_Reputation[L_i] +
            (REAL#1.0 - GVL_INPUT.IN_Room_Temp_Reputation[L_i]) * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;

        GVL_INPUT.IN_Room_Hum_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Hum_Reputation[L_i] +
            (REAL#1.0 - GVL_INPUT.IN_Room_Hum_Reputation[L_i]) * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;
    END_IF;

    IF GVL_INPUT.IN_Room_Temp_Reputation[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence THEN
        GVL_INPUT.IN_Room_Temp_Reputation[L_i] :=
            GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
    END_IF;

    IF GVL_INPUT.IN_Room_Hum_Reputation[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence THEN
        GVL_INPUT.IN_Room_Hum_Reputation[L_i] :=
            GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
    END_IF;

    // ======================================================
    // FINAL ZONE CONFIDENCE
    // ======================================================
    GVL_INPUT.IN_Zone_Confidence[L_i] :=
        (GVL_INPUT.IN_Room_Temp_Confidence[L_i] * GVL_INPUT.IN_Room_Temp_Reputation[L_i] +
         GVL_INPUT.IN_Room_Hum_Confidence[L_i] * GVL_INPUT.IN_Room_Hum_Reputation[L_i]) / REAL#2.0;

    IF GVL_INPUT.IN_Zone_Confidence[L_i] < GVL_INPUT.IN_Min_Zone_Confidence THEN
        GVL_INPUT.IN_Min_Zone_Confidence := GVL_INPUT.IN_Zone_Confidence[L_i];
        GVL_INPUT.IN_Worst_Zone := L_i;
    END_IF;

    GVL_INPUT.IN_Room_Temp_Prev[L_i] := GVL_INPUT.IN_Room_Temps[L_i];
    GVL_INPUT.IN_Room_Hum_Prev[L_i] := GVL_INPUT.IN_Room_Hum[L_i];
END_FOR;

// Floor temperatures are normalized on heating-circuit boundaries,
// not generic zone boundaries.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_INPUT.IN_Floor_Temps[L_i] := GVL_STATE.G_Floor_Temps[L_i];
END_FOR;

// ======================================================
// SAFETY SENSOR INPUT AGGREGATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    GVL_INPUT.IN_Water_Sensors[L_i] := GVL_STATE.G_Water_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    GVL_INPUT.IN_Smoke_Sensors[L_i] := GVL_STATE.G_Smoke_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    GVL_INPUT.IN_Methane_Sensors[L_i] := GVL_STATE.G_Methane_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    GVL_INPUT.IN_CO_Sensors[L_i] := GVL_STATE.G_CO_Sensors[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_Input_Processing <<<

// ==============================================================================
// IO READ PHASE 04 — heating manifold analog sensors and status inputs.
// ==============================================================================
// Execution order is preserved from the former phase body.
// No gating, shedding or behavior changes are applied here.
// ==============================================================================

PRG_IO_Read_Manifold_01_Pressure_Current();
PRG_IO_Read_Manifold_02_Temperature_Status();

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Phase_04_Heating_Manifold_Sensors <<<

IF GVL_ENERGY_ISOLATION_CAUSALITY_FABRIC.Energy_Isolation_Causality_Granted
AND NOT GVL_RESIDUAL_ENERGY_STATE_FABRIC.Latent_Unsafe_Actuation_Detected
AND NOT GVL_RESIDUAL_ENERGY_STATE_FABRIC.Residual_Energy_Persistence_Detected
AND NOT GVL_RESIDUAL_ENERGY_STATE_FABRIC.Unsafe_Thermal_Energy_Retention THEN

    GVL_RESIDUAL_ENERGY_STATE_FABRIC.Residual_Energy_State_Valid := TRUE;
    GVL_RESIDUAL_ENERGY_STATE_FABRIC.Residual_Energy_Bounded := TRUE;
    GVL_RESIDUAL_ENERGY_STATE_FABRIC.Residual_Actuation_Energy_Safe := TRUE;
    GVL_RESIDUAL_ENERGY_STATE_FABRIC.Thermal_Energy_Dissipation_Stable := TRUE;
END_IF;

IF GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Unsafe_Transition_Forensics_Granted
AND NOT GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_State_Fork
AND NOT GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Cluster_Safety_Projection_Drift
AND NOT GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Unsafe_State_Hidden THEN

    GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_Reality_Consensus_Valid := TRUE;
    GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_Reality_Consensus_Granted := TRUE;
    GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_Consensus_Valid := TRUE;
    GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Cluster_Safety_Reality_Stable := TRUE;
    GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Observability_Reality_Equivalence := TRUE;
END_IF;

FOR L_i := 1 TO 4 DO
    L_Pumps_4[L_i] := GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Manifold_Pump_Out_Of_Service[L_i] := NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];
    L_Manifold_Pressure_Fault[L_i] := GVL_HEATING_DIAGNOSTICS.G_Manifold_Pressure_Fault[L_i];
    L_Manifold_Current_Fault[L_i] := GVL_HEATING_DIAGNOSTICS.G_Manifold_Current_Fault[L_i];
    L_Manifold_Return_Temp_Fault[L_i] := GVL_HEATING_DIAGNOSTICS.G_Manifold_Return_Temp_Fault[L_i];
END_FOR;

fbStateTraceLog(
    VI_System_Time := GVL_TIME_SERVICE.G_Now_MS,
    VI_Gas_Alarm := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_HEALTH_BRIDGE.G_CO_Alarm_Level,
    VI_Leak_Alarm := GVL_HEALTH_BRIDGE.G_Leak_Detected,
    VI_Pumps := L_Pumps_4,
    VO_Last_Change_Time => L_Last_State_Trace_MS
);

IF GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost AND NOT L_VentBoost_Was_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        L_VentBoost_Start_Humidity[L_i] := GVL_INPUT.IN_Room_Hum[L_i];
        L_VentBoost_Start_Valid[L_i] := TRUE;
    END_FOR;
END_IF;

IF (NOT GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost) AND L_VentBoost_Was_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        L_Hum := GVL_INPUT.IN_Room_Hum[L_i];

        IF L_VentBoost_Start_Valid[L_i] THEN
            L_StartHum := L_VentBoost_Start_Humidity[L_i];
        ELSE
            L_StartHum := L_Hum;
        END_IF;

        L_DeltaHum := L_StartHum - L_Hum;

        IF ABS(L_DeltaHum) < 0.5 THEN
            L_Confidence := 0.2;
        ELSE
            L_Confidence := 1.0;
        END_IF;

        fbAdapt(
            iScenario := REASON_SCENARIO_VENT_BOOST,
            iSuccess := (L_DeltaHum > 5.0),
            iMeasuredValue := L_Hum,
            iZone := L_i,
            iConfidence := L_Confidence
        );

        GVL_BEHAVIOR_ADAPT.G_Prev_Humidity[L_i] := L_Hum;
        GVL_BEHAVIOR_ADAPT.G_Prev_Valid[L_i] := TRUE;
        L_VentBoost_Start_Valid[L_i] := FALSE;
    END_FOR;
END_IF;

L_VentBoost_Was_Active := GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost;

IF GVL_INTENT_BEHAVIOR.I_Request_Night_Mode AND NOT L_Night_Was_Active THEN
    fbAdapt(
        iScenario := REASON_SCENARIO_NIGHT,
        iSuccess := TRUE,
        iMeasuredValue := 0.0,
        iZone := 0,
        iConfidence := 1.0
    );
END_IF;

L_Night_Was_Active := GVL_INTENT_BEHAVIOR.I_Request_Night_Mode;

fbSystemDiagnosticsPublisher(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Backup_Pump_Out_Of_Service := NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service,
    VI_Electric_Heater_Out_Of_Service := NOT GVL_CONFIG.G_Electric_Heater_In_Service,
    VI_Manifold_Pump_Out_Of_Service := L_Manifold_Pump_Out_Of_Service,
    VI_DHW_Heating_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service,
    VI_DHW_Circ_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service,
    VI_User_Access_Level := GVL_COMMAND.CMD_User_Access_Level,
    VI_Dangerous_Action_Pending := GVL_COMMAND.CMD_Dangerous_Action_Request,
    VI_Dangerous_Action_Text := 'Confirmation requested',
    VI_Sensor_Fault := GVL_STATE.G_Heating_Sensor_Fault OR GVL_STATE.G_DHW_Sensor_Fault,
    VI_IO_Offline := GVL_STATE.G_Heating_IO_Fault OR GVL_STATE.G_DHW_IO_Fault,
    VI_Subsystem_Degraded := GVL_STATE.G_Heating_Subsystem_Degraded OR GVL_STATE.G_DHW_Subsystem_Degraded,
    VI_Manifold_Pressure_Fault := L_Manifold_Pressure_Fault,
    VI_Manifold_Current_Fault := L_Manifold_Current_Fault,
    VI_Manifold_Return_Temp_Fault := L_Manifold_Return_Temp_Fault
);

GVL_System_Diagnostics_Publication.G_System_Diagnostics := fbSystemDiagnosticsPublisher.VO_Diagnostics;
GVL_System_Diagnostics_Publication.G_System_Diagnostics_Publication_Valid := fbSystemDiagnosticsPublisher.VO_Publication_Valid;
GVL_System_Diagnostics_Publication.G_System_Diagnostics_Status_Code := fbSystemDiagnosticsPublisher.VO_Status_Code;
GVL_System_Diagnostics_Publication.G_System_Diagnostics_Status_Text := fbSystemDiagnosticsPublisher.VO_Status_Text;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Monotonicity_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Valid := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Granted := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Quarantine_Active := TRUE;

GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Global_Trust_Epoch_Monotonic := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Rollback_Resistant_Authority_Valid := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Recovery_Epoch_Strictly_Newer := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Distributed_Trust_Vector_Coherent := FALSE;
GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Irreversible_Trust_Progression_Stable := FALSE;

// Provenance continuity required.
IF NOT GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Granted THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48000;
    L_Error_Text := 'Provenance continuity not granted';
END_IF;

// Temporal trust rollback detectors.
IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Temporal_Trust_Rollback_Detected THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48001;
    L_Error_Text := 'Temporal trust rollback detected';
END_IF;

IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Replay_Authority_Epoch_Detected THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48002;
    L_Error_Text := 'Replay authority epoch detected';
END_IF;

IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.CrossNode_Trust_Vector_Regression THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48003;
    L_Error_Text := 'Cross-node trust vector regression detected';
END_IF;

IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Stale_Federation_Epoch_Rejoin THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48004;
    L_Error_Text := 'Stale federation epoch rejoin detected';
END_IF;

IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Recovery_Timeline_Fork_Detected THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48005;
    L_Error_Text := 'Recovery timeline fork detected';
END_IF;

IF GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Revoked_Epoch_Resurrection_Detected THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48006;
    L_Error_Text := 'Revoked epoch resurrection detected';
END_IF;

// Monotonic trust validation.
IF L_Monotonicity_Valid
AND NOT GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.CrossNode_Trust_Epoch_Aligned THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48010;
    L_Error_Text := 'Cross-node trust epoch alignment invalid';
END_IF;

IF L_Monotonicity_Valid
AND NOT GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Recovery_Timeline_Dominance_Valid THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48011;
    L_Error_Text := 'Recovery timeline dominance invalid';
END_IF;

IF L_Monotonicity_Valid
AND NOT GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Federation_Epoch_Progression_Coherent THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48012;
    L_Error_Text := 'Federation epoch progression invalid';
END_IF;

IF L_Monotonicity_Valid
AND NOT GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Revocation_History_Monotonic THEN
    L_Monotonicity_Valid := FALSE;
    L_Error_Code := 48013;
    L_Error_Text := 'Trust revocation history monotonicity invalid';
END_IF;

IF L_Monotonicity_Valid THEN
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Valid := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Granted := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Quarantine_Active := FALSE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Global_Trust_Epoch_Monotonic := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Rollback_Resistant_Authority_Valid := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Recovery_Epoch_Strictly_Newer := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Distributed_Trust_Vector_Coherent := TRUE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Irreversible_Trust_Progression_Stable := TRUE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Epoch :=
        GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Epoch;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Epoch_Coherent := TRUE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Last_Update_MS :=
        L_Now_MS;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Lease_Expired := FALSE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Last_Error_Code := 0;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Last_Error_Text := '';
ELSE
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Valid := FALSE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Granted := FALSE;
    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Quarantine_Active := TRUE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Lease_Expired := TRUE;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Last_Error_Code :=
        L_Error_Code;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Last_Error_Text :=
        L_Error_Text;

    GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Invalidation_Count :=
        GVL_TRUST_EPOCH_MONOTONICITY_FABRIC.Trust_Epoch_Monotonicity_Invalidation_Count + 1;
END_IF;

IF GVL_SAFETY_OBSERVABILITY_TRUTH_FABRIC.Safety_Observability_Truth_Granted
AND NOT GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Physical_Safety_Projection_Drift_Detected
AND NOT GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Hidden_Unsafe_Physical_State_Detected
AND NOT GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Unsafe_Projection_Backfill_Detected THEN

    GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Physical_Safety_Projection_Valid := TRUE;
    GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Physical_Safety_Projection_Granted := TRUE;
    GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Physical_Plant_Safety_Projection_Stable := TRUE;
    GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Energy_State_Safety_Projection_Valid := TRUE;
    GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Recovery_State_Safety_Projection_Valid := TRUE;
END_IF;

// ======================================================
// REAL TRANSPORT LAYER CONTRACT
// ======================================================
// This layer converts high-level command/status structures
// into transport-safe wire images.
//
// Real Modbus RTU/TCP or serial IO code must:
//   1. Write G_Wire_Image command fields to adapter registers.
//   2. Read adapter status registers into G_Wire_Image status fields.
//
// This program keeps protocol encoding/decoding centralized.
// It does not claim transport online unless OpenTherm is enabled.
// ======================================================

IF NOT GVL_CONFIG.G_OpenTherm_Enabled THEN
    GVL_OPENTHERM_ADAPTER.G_Transport_Online := FALSE;
    GVL_OPENTHERM_ADAPTER.G_Transport_Error := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Setpoint_x10 := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Lo := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Hi := 0;

        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Online := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Flame := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Status_Word := 0;
    END_FOR;

    RETURN;
END_IF;

GVL_OPENTHERM_ADAPTER.G_Transport_Online := TRUE;
GVL_OPENTHERM_ADAPTER.G_Transport_Error := FALSE;
GVL_OPENTHERM_ADAPTER.G_Last_Transport_Update_MS := GVL_STATUS.G_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    // ======================================================
    // COMMAND → WIRE IMAGE
    // ======================================================
    IF GVL_OPENTHERM_ADAPTER.G_Command[L_i].Enable THEN
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 1;
    ELSE
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 0;
    END_IF;

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Setpoint_x10 :=
        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Setpoint_x10;

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Lo :=
        UDINT_TO_WORD(GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence AND 16#FFFF);

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Hi :=
        UDINT_TO_WORD(SHR(GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence, 16));

    // ======================================================
    // WIRE IMAGE → STATUS
    // ======================================================
    L_Heartbeat :=
        WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Heartbeat_Lo)
        OR SHL(
            WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Heartbeat_Hi),
            16
        );

    L_Ack_Seq :=
        WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Ack_Seq_Lo)
        OR SHL(
            WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Ack_Seq_Hi),
            16
        );

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Heartbeat := L_Heartbeat;
    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Ack_Seq := L_Ack_Seq;

    L_Status_Word :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Word;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Online :=
        (L_Status_Word AND 16#0001) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error :=
        (L_Status_Word AND 16#0002) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Flame :=
        (L_Status_Word AND 16#0004) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Status_Word :=
        L_Status_Word;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error_Code :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Error_Code;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Modulation_x10 :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Modulation_x10;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Boiler_Temp_x10 :=
        WORD_TO_INT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Boiler_Temp_x10);

END_FOR;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Continuity_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Valid := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Granted := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Quarantine_Active := TRUE;

GVL_PROVENANCE_CONTINUITY_FABRIC.Recovery_Provenance_Reattested := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.Authority_Resurrection_Authentic := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.Federation_Rejoin_Provenance_Valid := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.PostRecovery_TrustSeed_Coherent := FALSE;
GVL_PROVENANCE_CONTINUITY_FABRIC.CrossEpoch_Provenance_Continuity_Stable := FALSE;

// Authority provenance required.
IF NOT GVL_AUTHORITY_PROVENANCE_FABRIC.Authority_Provenance_Granted THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47000;
    L_Error_Text := 'Authority provenance not granted';
END_IF;

// Post-recovery provenance bypass detectors.
IF GVL_PROVENANCE_CONTINUITY_FABRIC.Stale_Provenance_Resurrection_Detected THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47001;
    L_Error_Text := 'Stale provenance resurrection detected';
END_IF;

IF GVL_PROVENANCE_CONTINUITY_FABRIC.Recovered_Authority_Without_Reattestation_Detected THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47002;
    L_Error_Text := 'Recovered authority without re-attestation detected';
END_IF;

IF GVL_PROVENANCE_CONTINUITY_FABRIC.Federation_Rejoin_Without_Provenance_Detected THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47003;
    L_Error_Text := 'Federation rejoin without provenance detected';
END_IF;

IF GVL_PROVENANCE_CONTINUITY_FABRIC.CrossEpoch_Trust_Continuity_Broken THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47004;
    L_Error_Text := 'Cross-epoch trust continuity broken';
END_IF;

IF GVL_PROVENANCE_CONTINUITY_FABRIC.Recovery_Trust_Seed_Drift_Detected THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47005;
    L_Error_Text := 'Recovery trust-seed drift detected';
END_IF;

IF GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Resurrection_Bypass_Detected THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47006;
    L_Error_Text := 'Provenance resurrection bypass detected';
END_IF;

// Provenance continuity validation.
IF L_Continuity_Valid
AND NOT GVL_PROVENANCE_CONTINUITY_FABRIC.Recovery_Epoch_Authenticity_Valid THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47010;
    L_Error_Text := 'Recovery epoch authenticity invalid';
END_IF;

IF L_Continuity_Valid
AND NOT GVL_PROVENANCE_CONTINUITY_FABRIC.Distributed_Rejoin_Attestation_Coherent THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47011;
    L_Error_Text := 'Distributed rejoin attestation invalid';
END_IF;

IF L_Continuity_Valid
AND NOT GVL_PROVENANCE_CONTINUITY_FABRIC.Authority_Restoration_Provenance_Grounded THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47012;
    L_Error_Text := 'Authority restoration provenance invalid';
END_IF;

IF L_Continuity_Valid
AND NOT GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Lease_Continuity_Valid THEN
    L_Continuity_Valid := FALSE;
    L_Error_Code := 47013;
    L_Error_Text := 'Provenance lease continuity invalid';
END_IF;

IF L_Continuity_Valid THEN
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Valid := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Granted := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Quarantine_Active := FALSE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Recovery_Provenance_Reattested := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Authority_Resurrection_Authentic := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Federation_Rejoin_Provenance_Valid := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.PostRecovery_TrustSeed_Coherent := TRUE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.CrossEpoch_Provenance_Continuity_Stable := TRUE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Epoch :=
        GVL_AUTHORITY_PROVENANCE_FABRIC.Authority_Provenance_Epoch;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Epoch_Coherent := TRUE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Last_Update_MS :=
        L_Now_MS;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Lease_Expired := FALSE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Last_Error_Code := 0;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Last_Error_Text := '';
ELSE
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Valid := FALSE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Granted := FALSE;
    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Quarantine_Active := TRUE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Lease_Expired := TRUE;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Last_Error_Code :=
        L_Error_Code;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Last_Error_Text :=
        L_Error_Text;

    GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Invalidation_Count :=
        GVL_PROVENANCE_CONTINUITY_FABRIC.Provenance_Continuity_Invalidation_Count + 1;
END_IF;

// Daily limit reset on monotonic 24h window.
IF (GVL_WATER_EMERGENCY_OPEN.G_Daily_Reset_MS = 0) OR
   ((GVL_TIME_SERVICE.G_Now_MS - GVL_WATER_EMERGENCY_OPEN.G_Daily_Reset_MS) >= GVL_CONSTANTS.C_MS_IN_DAY) THEN
    FOR L_i := 1 TO 4 DO
        GVL_WATER_EMERGENCY_OPEN.G_Open_Count_Today[L_i] := 0;
    END_FOR;
    GVL_WATER_EMERGENCY_OPEN.G_Daily_Reset_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

L_Leak_Active := GVL_STATE.G_Safety_Leak_Alarm OR GVL_STATE.G_Safety_Leak_Latched;
L_Close_Fault_Active := GVL_STATUS.G_Diagnostics.Water_Close_Fault_Active OR GVL_STATUS.G_Diagnostics.Water_Main_Shutdown_Recommended;
L_Hard_Stop_Active := (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GLOBAL_STOP) OR GVL_INTENT_SAFETY.I_System_Safe_Stop_Required;

IF (L_Close_Fault_Active OR L_Hard_Stop_Active) AND GVL_WATER_EMERGENCY_OPEN.G_Any_Open_Active THEN
    FOR L_i := 1 TO 4 DO
        GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_i] := FALSE;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_i] := 0;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_i] := 0;
    END_FOR;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Accepted := FALSE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_Group := 0;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_MS := GVL_TIME_SERVICE.G_Now_MS;

    IF L_Hard_Stop_Active THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 7;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open cancelled: hard stop active';
    ELSE
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 6;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open cancelled: water close fault';
    END_IF;
END_IF;

// HMI immediate close before timeout.
IF GVL_WATER_EMERGENCY_OPEN.G_Request_Close_Now THEN
    L_Group := GVL_WATER_EMERGENCY_OPEN.G_Target_Isolation_Group;

    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Accepted := FALSE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := FALSE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 0;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_Group := L_Group;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_MS := GVL_TIME_SERVICE.G_Now_MS;

    IF (L_Group >= 1) AND (L_Group <= 4) THEN
        GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_Group] := FALSE;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_Group] := 0;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_Group] := 0;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open cancelled by HMI';
    ELSE
        FOR L_i := 1 TO 4 DO
            GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_i] := FALSE;
            GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_i] := 0;
            GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_i] := 0;
        END_FOR;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'All emergency opens cancelled by HMI';
    END_IF;

    GVL_WATER_EMERGENCY_OPEN.G_Request_Close_Now := FALSE;
END_IF;

// HMI emergency open request.
// Groups 1..3 = local risers; group 4 = common inlet 35/36.
IF GVL_WATER_EMERGENCY_OPEN.G_Request_Open THEN
    L_Group := GVL_WATER_EMERGENCY_OPEN.G_Target_Isolation_Group;
    L_Duration_MS := 0;

    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Accepted := FALSE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := FALSE;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 0;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_Group := L_Group;
    GVL_WATER_EMERGENCY_OPEN.G_Last_Event_MS := GVL_TIME_SERVICE.G_Now_MS;

    CASE GVL_WATER_EMERGENCY_OPEN.G_Duration_Minutes OF
        1:
            L_Duration_MS := GVL_CONSTANTS.C_MS_IN_MINUTE;
        3:
            L_Duration_MS := GVL_CONSTANTS.C_MS_IN_MINUTE * 3;
        5:
            L_Duration_MS := GVL_CONSTANTS.C_MS_IN_MINUTE * 5;
    ELSE
            L_Duration_MS := 0;
    END_CASE;

    IF L_Hard_Stop_Active THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 7;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: hard stop active';
    ELSIF L_Close_Fault_Active THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 6;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: water close fault active';
    ELSIF NOT L_Leak_Active THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 1;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: no active leak alarm';
    ELSIF GVL_INTENT_USER.I_User_Access_Level < 2 THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 2;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: access level < 2';
    ELSIF (L_Group < 1) OR (L_Group > 4) THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 3;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: invalid isolation group';
    ELSIF L_Duration_MS = 0 THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 4;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: invalid duration';
    ELSIF GVL_WATER_EMERGENCY_OPEN.G_Open_Count_Today[L_Group] >= 3 THEN
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Denied := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Denial_Code := 5;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open denied: daily limit reached';
    ELSE
        GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_Group] := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Start_MS[L_Group] := GVL_TIME_SERVICE.G_Now_MS;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_Group] := L_Duration_MS;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_Group] := L_Duration_MS;
        GVL_WATER_EMERGENCY_OPEN.G_Open_Count_Today[L_Group] := GVL_WATER_EMERGENCY_OPEN.G_Open_Count_Today[L_Group] + 1;
        GVL_WATER_EMERGENCY_OPEN.G_Last_Request_Accepted := TRUE;
        GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open accepted';
    END_IF;

    GVL_WATER_EMERGENCY_OPEN.G_Request_Open := FALSE;
END_IF;

GVL_WATER_EMERGENCY_OPEN.G_Any_Open_Active := FALSE;

// Timeout and remaining-time management.
FOR L_i := 1 TO 4 DO
    IF GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_i] THEN
        IF GVL_TIME_SERVICE.G_Now_MS >= GVL_WATER_EMERGENCY_OPEN.G_Open_Start_MS[L_i] THEN
            L_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_WATER_EMERGENCY_OPEN.G_Open_Start_MS[L_i];
        ELSE
            L_Elapsed_MS := (4294967295 - GVL_WATER_EMERGENCY_OPEN.G_Open_Start_MS[L_i]) + GVL_TIME_SERVICE.G_Now_MS + 1;
        END_IF;

        IF L_Elapsed_MS >= GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_i] THEN
            GVL_WATER_EMERGENCY_OPEN.G_Open_Active[L_i] := FALSE;
            GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_i] := 0;
            GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_i] := 0;
            GVL_WATER_EMERGENCY_OPEN.G_Last_Event_Group := L_i;
            GVL_WATER_EMERGENCY_OPEN.G_Last_Event_MS := GVL_TIME_SERVICE.G_Now_MS;
            GVL_WATER_EMERGENCY_OPEN.G_Status_Text := 'Emergency open timeout elapsed';
        ELSE
            L_Remaining_MS := GVL_WATER_EMERGENCY_OPEN.G_Open_Duration_MS[L_i] - L_Elapsed_MS;
            GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_i] := L_Remaining_MS;
            GVL_WATER_EMERGENCY_OPEN.G_Any_Open_Active := TRUE;
        END_IF;
    ELSE
        GVL_WATER_EMERGENCY_OPEN.G_Open_Remaining_MS[L_i] := 0;
    END_IF;
END_FOR;

GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_1_Active := GVL_WATER_EMERGENCY_OPEN.G_Open_Active[1];
GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_2_Active := GVL_WATER_EMERGENCY_OPEN.G_Open_Active[2];
GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_3_Active := GVL_WATER_EMERGENCY_OPEN.G_Open_Active[3];
GVL_WATER_EMERGENCY_OPEN.G_Open_Common_Inlet_Active := GVL_WATER_EMERGENCY_OPEN.G_Open_Active[4];
GVL_WATER_EMERGENCY_OPEN.G_Any_Open_Active :=
    GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_1_Active OR
    GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_2_Active OR
    GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_3_Active OR
    GVL_WATER_EMERGENCY_OPEN.G_Open_Common_Inlet_Active;
GVL_WATER_EMERGENCY_OPEN.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

L_Now_MS := GVL_STATUS.G_System_Time_MS;

GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Valid := FALSE;
GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Granted := FALSE;
GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Quarantine_Active := TRUE;

IF NOT GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Granted THEN
    L_Valid := FALSE;
END_IF;

IF GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Conflict_Detected
OR GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.Unsafe_Recovery_Topology_Detected
OR GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_Recovery_Race_Detected
OR GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.Distributed_SafeState_Fork_Detected
OR GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.PowerDomain_Unsafe_Reactivation_Detected
OR GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.MultiDomain_Recovery_Deadlock_Detected THEN
    L_Valid := FALSE;
END_IF;

IF L_Valid THEN
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Valid := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Granted := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Quarantine_Active := FALSE;

    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_SafeState_Compatibility_Valid := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.FailSafe_Topology_Closure_Canonical := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.MultiDomain_SafeTransition_Stable := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.SafeState_Recovery_Ordering_Bounded := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.Physical_Domain_Isolation_Coherent := TRUE;

    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Epoch :=
        GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Epoch;

    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Epoch_Coherent := TRUE;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Last_Update_MS := L_Now_MS;
    GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Lease_Expired := FALSE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Runtime_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Valid := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Granted := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Quarantine_Active := TRUE;

GVL_RUNTIME_SUSTAINABILITY_FABRIC.Deterministic_Cycle_Budget_Stable := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Queue_Load_Stable := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Memory_Fragmentation_Stable := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.Watchdog_Jitter_Stable := FALSE;
GVL_RUNTIME_SUSTAINABILITY_FABRIC.HA_Synchronization_Load_Stable := FALSE;

// Energy causality authority required.
IF NOT GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Granted THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38000;
    L_Error_Text := 'Energy causality authority not granted';
END_IF;

// Resource-collapse detectors.
IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.Memory_Fragmentation_Drift_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38001;
    L_Error_Text := 'Memory fragmentation drift detected';
END_IF;

IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.Queue_Saturation_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38002;
    L_Error_Text := 'Runtime queue saturation detected';
END_IF;

IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.Historical_Persistence_Amplification_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38003;
    L_Error_Text := 'Historical persistence amplification detected';
END_IF;

IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.Watchdog_Jitter_Escalation_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38004;
    L_Error_Text := 'Watchdog jitter escalation detected';
END_IF;

IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.HASynchronization_Overload_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38005;
    L_Error_Text := 'HA synchronization overload detected';
END_IF;

IF GVL_RUNTIME_SUSTAINABILITY_FABRIC.Deterministic_Cycle_Erosion_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38006;
    L_Error_Text := 'Deterministic cycle erosion detected';
END_IF;

// Long-term runtime sustainability validation.
IF L_Runtime_Valid
AND NOT GVL_RUNTIME_SUSTAINABILITY_FABRIC.Historical_Persistence_Load_Stable THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38010;
    L_Error_Text := 'Historical persistence load unstable';
END_IF;

IF L_Runtime_Valid
AND NOT GVL_RUNTIME_SUSTAINABILITY_FABRIC.Snapshot_Publication_Stable THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38011;
    L_Error_Text := 'Snapshot publication unstable';
END_IF;

IF L_Runtime_Valid
AND NOT GVL_RUNTIME_SUSTAINABILITY_FABRIC.Distributed_Runtime_Load_Coherent THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38012;
    L_Error_Text := 'Distributed runtime load coherence invalid';
END_IF;

IF L_Runtime_Valid
AND NOT GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Evolution_Sustainable THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 38013;
    L_Error_Text := 'Runtime evolution sustainability invalid';
END_IF;

IF L_Runtime_Valid THEN
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Valid := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Granted := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Quarantine_Active := FALSE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Deterministic_Cycle_Budget_Stable := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Queue_Load_Stable := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Memory_Fragmentation_Stable := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Watchdog_Jitter_Stable := TRUE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.HA_Synchronization_Load_Stable := TRUE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Epoch :=
        GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Epoch;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Epoch_Coherent := TRUE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Last_Update_MS :=
        L_Now_MS;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Lease_Expired := FALSE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Last_Error_Code := 0;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Valid := FALSE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Granted := FALSE;
    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Quarantine_Active := TRUE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Lease_Expired := TRUE;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Last_Error_Code :=
        L_Error_Code;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Last_Error_Text :=
        L_Error_Text;

    GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Invalidation_Count :=
        GVL_RUNTIME_SUSTAINABILITY_FABRIC.Runtime_Sustainability_Invalidation_Count + 1;
END_IF;

// ======================================================
// DISTRIBUTED COMMIT INGESTION
// ======================================================
// Explicit peer distributed commit ingestion layer.
//
// Purpose:
// normalize replicated peer commit-handshake state into
// distributed commit peer-input fields.
//
// This layer does NOT:
// - perform commit reconciliation
// - validate replay continuity
// - validate peer acknowledgements
// ======================================================

IF GVL_HA_SESSION_REPLICATION.HA_Remote_Session_Valid THEN
    GVL_DISTRIBUTED_COMMIT.Peer_Publication_Commit_Epoch :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Publication_Commit_Epoch;

    GVL_DISTRIBUTED_COMMIT.Peer_Prepare_Epoch :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Prepare_Epoch;

    GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Ack_Valid;

    GVL_DISTRIBUTED_COMMIT.Peer_Commit_Last_Refresh_MS :=
        GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Last_Refresh_MS;
ELSE
