L_Error_Text := '';

// ======================================================
// DISTRIBUTED IMMUTABLE SNAPSHOT GOVERNOR
// ======================================================
// Governs immutable peer publication snapshot exchange.
// Publication-authoritative only.
// Does not invalidate runtime barrier, PLC fencing
// or local immutable snapshot freeze.
//
// Recovery/release is convergence-lease based:
// distributed snapshot quarantine is not released on a
// single healthy scan.
// ======================================================

GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Reconciliation_Lost := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Expired := FALSE;

// ------------------------------------------------------
// Local immutable publication projection.
// ------------------------------------------------------
// Distributed snapshot is upstream of output freshness in MAIN.
// Therefore local publication baseline must not read GVL_OUTPUT_EPOCH.
// It uses the already-frozen runtime snapshot epoch instead.
// ------------------------------------------------------

GVL_DISTRIBUTED_SNAPSHOT.Local_Distributed_Snapshot_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;
GVL_DISTRIBUTED_SNAPSHOT.Local_Runtime_Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch;
GVL_DISTRIBUTED_SNAPSHOT.Local_Publication_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch;

// ------------------------------------------------------
// Local immutable publication freeze semantics.
// ------------------------------------------------------

IF GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
THEN
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Frozen := TRUE;
ELSE
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Frozen := FALSE;

    L_Distributed_Snapshot_Valid := FALSE;
    L_Error_Code := 14000;
    L_Error_Text := 'Local immutable snapshot not frozen';
END_IF;

// ------------------------------------------------------
// Peer session detection.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Runtime_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Distributed_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Immutable THEN
    L_Peer_Session_Active := TRUE;
END_IF;

// ------------------------------------------------------
// Peer snapshot lease validation.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Timeout_MS THEN
            GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Expired := TRUE;

            L_Distributed_Snapshot_Valid := FALSE;
            L_Error_Code := 14001;
            L_Error_Text := 'Peer snapshot lease expired';
        END_IF;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer immutable snapshot semantics.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF NOT GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Immutable THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable := TRUE;

        L_Distributed_Snapshot_Valid := FALSE;
        L_Error_Code := 14002;
        L_Error_Text := 'Peer snapshot not immutable';
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer publication continuity.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Epoch < GVL_DISTRIBUTED_SNAPSHOT.Local_Publication_Epoch THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer publication reconciliation continuity.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Runtime_Snapshot_Epoch <> GVL_DISTRIBUTED_SNAPSHOT.Local_Runtime_Snapshot_Epoch THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence := TRUE;
    END_IF;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale
OR GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence
OR GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable
THEN
    GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Reconciliation_Lost := TRUE;
END_IF;

// ------------------------------------------------------
// Publish authoritative distributed snapshot state.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid THEN
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch + 1;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Reconciliation_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled := TRUE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid := TRUE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent := TRUE;

    // Lease-based recovery release.
    IF GVL_CONVERGENCE.Convergence_Release_Allowed THEN
        GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Quarantine_Active := FALSE;
    END_IF;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Code := 0;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Text := '';
ELSE
    // Invalid distributed snapshot state escalates immediately.
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled := FALSE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid := FALSE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent := FALSE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Quarantine_Active := TRUE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Text := L_Error_Text;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Federation_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Valid := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Granted := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Quarantine_Active := TRUE;

GVL_SEMANTIC_FEDERATION_FABRIC.External_SCADA_Semantics_Coherent := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.Cloud_Authority_Projection_Aligned := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.MQTT_Semantic_State_Fresh := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.ThirdParty_Integration_Trust_Valid := FALSE;
GVL_SEMANTIC_FEDERATION_FABRIC.Federated_Observability_Coherent := FALSE;

// Operator semantic alignment required.
IF NOT GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Granted THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41000;
    L_Error_Text := 'Operator semantic alignment not granted';
END_IF;

// Ecosystem semantic split-brain detectors.
IF GVL_SEMANTIC_FEDERATION_FABRIC.External_Semantic_Lag_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41001;
    L_Error_Text := 'External semantic lag detected';
END_IF;

IF GVL_SEMANTIC_FEDERATION_FABRIC.SCADA_Projection_Skew_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41002;
    L_Error_Text := 'SCADA projection skew detected';
END_IF;

IF GVL_SEMANTIC_FEDERATION_FABRIC.Cloud_Authority_Desynchronization_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41003;
    L_Error_Text := 'Cloud authority desynchronization detected';
END_IF;

IF GVL_SEMANTIC_FEDERATION_FABRIC.ThirdParty_Semantic_Drift_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41004;
    L_Error_Text := 'Third-party semantic drift detected';
END_IF;

IF GVL_SEMANTIC_FEDERATION_FABRIC.Integration_Trust_Divergence_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41005;
    L_Error_Text := 'Integration trust divergence detected';
END_IF;

IF GVL_SEMANTIC_FEDERATION_FABRIC.Federated_Authority_Inconsistency_Detected THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41006;
    L_Error_Text := 'Federated authority inconsistency detected';
END_IF;

// External semantic federation validation.
IF L_Federation_Valid
AND NOT GVL_SEMANTIC_FEDERATION_FABRIC.Exported_Authority_State_Coherent THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41010;
    L_Error_Text := 'Exported authority state coherence invalid';
END_IF;

IF L_Federation_Valid
AND NOT GVL_SEMANTIC_FEDERATION_FABRIC.Federation_Projection_Temporal_Stable THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41011;
    L_Error_Text := 'Federation projection temporal stability invalid';
END_IF;

IF L_Federation_Valid
AND NOT GVL_SEMANTIC_FEDERATION_FABRIC.External_Runtime_Interpretation_Aligned THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41012;
    L_Error_Text := 'External runtime interpretation alignment invalid';
END_IF;

IF L_Federation_Valid
AND NOT GVL_SEMANTIC_FEDERATION_FABRIC.Federated_Trust_Boundary_Stable THEN
    L_Federation_Valid := FALSE;
    L_Error_Code := 41013;
    L_Error_Text := 'Federated trust boundary unstable';
END_IF;

IF L_Federation_Valid THEN
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Valid := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Granted := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Quarantine_Active := FALSE;

    GVL_SEMANTIC_FEDERATION_FABRIC.External_SCADA_Semantics_Coherent := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Cloud_Authority_Projection_Aligned := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.MQTT_Semantic_State_Fresh := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.ThirdParty_Integration_Trust_Valid := TRUE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Federated_Observability_Coherent := TRUE;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Epoch :=
        GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Epoch;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Epoch_Coherent := TRUE;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Last_Update_MS :=
        L_Now_MS;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Lease_Expired := FALSE;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Last_Error_Code := 0;
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Valid := FALSE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Granted := FALSE;
    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Quarantine_Active := TRUE;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Lease_Expired := TRUE;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Last_Error_Code :=
        L_Error_Code;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Last_Error_Text :=
        L_Error_Text;

    GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Invalidation_Count :=
        GVL_SEMANTIC_FEDERATION_FABRIC.Semantic_Federation_Invalidation_Count + 1;
END_IF;

// ADVISORY SURVIVABILITY INTELLIGENCE
// READ-ONLY / NON-INVASIVE
// NO ACTUATION / AUTHORITY / RECOVERY MUTATION

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.System_Survivable :=
    GVL_PHYSICAL_REALITY_VERIFICATION_FABRIC.Physical_Runtime_Reality_Valid;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Degraded_But_Safe :=
    GVL_RUNTIME_STATE_ALGEBRA.Current_Runtime_State = SYS_DEGRADED;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Isolated_But_Stable :=
    GVL_RUNTIME_STATE_ALGEBRA.Current_Runtime_State = SYS_ISOLATED;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Partitioned_But_Survivable :=
    GVL_RUNTIME_STATE_ALGEBRA.Current_Runtime_State = SYS_PARTITIONED;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Resource_Starved_But_Recoverable :=
    GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Complexity_Pressure_Observed;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Essential_Functions_Preserved :=
    GVL_SAFETY_OBSERVABILITY_TRUTH_FABRIC.Observability_Reality_Equivalence_Granted;

IF GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Saturation_Observed THEN
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.NonEssential_Shedding_Recommended := TRUE;
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Heavy_Diagnostics_Defer_Recommended := TRUE;
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Trend_Analytics_Defer_Recommended := TRUE;
END_IF;

IF GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Complexity_Pressure_Observed THEN
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Telemetry_Rate_Reduction_Recommended := TRUE;
END_IF;

IF GVL_RUNTIME_TRANSITION_SYSTEM.Illegal_Runtime_Transition_Observed THEN
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.LongDuration_Degradation_Observed := TRUE;
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Chronic_Degradation_Risk_Increasing := TRUE;
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Survivability_Advisory_Available := TRUE;
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Survivability_Advisory_Code :=
        'survivability degraded under prolonged instability';
END_IF;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Governance_Saturation_Pressure_Observed :=
    GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Saturation_Observed;

GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Distributed_Instability_Pressure_Observed :=
    NOT GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_Consensus_Valid;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Restoration_Valid := TRUE;

GVL_AUTHORITY_RESTORATION.Authority_Restoration_Active := FALSE;
GVL_AUTHORITY_RESTORATION.Authority_Restoration_Allowed := FALSE;
GVL_AUTHORITY_RESTORATION.Authority_Restoration_Completed := FALSE;

GVL_AUTHORITY_RESTORATION.Snapshot_Restoration_Valid := FALSE;
GVL_AUTHORITY_RESTORATION.Consensus_Restoration_Valid := FALSE;
GVL_AUTHORITY_RESTORATION.Causality_Restoration_Valid := FALSE;
GVL_AUTHORITY_RESTORATION.Epoch_Restoration_Valid := FALSE;
GVL_AUTHORITY_RESTORATION.Lineage_Restoration_Valid := FALSE;

GVL_AUTHORITY_RESTORATION.Revocation_Clearance_Valid := FALSE;
GVL_AUTHORITY_RESTORATION.Stabilization_Window_Elapsed := FALSE;
GVL_AUTHORITY_RESTORATION.Reauthorization_Order_Valid := FALSE;

IF GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid
AND (
    GVL_SAFETY_SHUTDOWN.G_Safety_Active
    OR GVL_SAFETY_RECOVERY.G_Recovery_Active
    OR (GVL_SAFETY_RECOVERY.G_Recovery_Phase <> IDLE)
) THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid
AND NOT GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Valid THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Snapshot_Restoration_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND NOT GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Consensus_Restoration_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND NOT GVL_TELEMETRY.Command_Telemetry_Causality_Valid THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Causality_Restoration_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND NOT GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Epoch_Restoration_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND NOT GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Lineage_Restoration_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND GVL_AUTHORITY_REVOCATION.Quarantine_Fabric_Active THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Revocation_Clearance_Valid := TRUE;
END_IF;

IF L_Restoration_Valid
AND ((L_Now_MS - GVL_AUTHORITY_REVOCATION.Revocation_Last_Update_MS) < 5000) THEN
    L_Restoration_Valid := FALSE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Stabilization_Window_Elapsed := TRUE;
END_IF;

IF L_Restoration_Valid THEN
    GVL_AUTHORITY_RESTORATION.Authority_Restoration_Active := TRUE;
    GVL_AUTHORITY_RESTORATION.Authority_Restoration_Allowed := TRUE;
    GVL_AUTHORITY_RESTORATION.Authority_Restoration_Completed := TRUE;
    GVL_AUTHORITY_RESTORATION.Reauthorization_Order_Valid := TRUE;
    GVL_AUTHORITY_RESTORATION.Restoration_Epoch :=
        GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch;
    GVL_AUTHORITY_RESTORATION.Restoration_Last_Update_MS := L_Now_MS;
END_IF;

L_Audible_Alarm_Active :=
    GVL_HEALTH_BRIDGE.G_Gas_Detected OR
    GVL_HEALTH_BRIDGE.G_CO_Alarm_Level OR
    GVL_HEALTH_BRIDGE.G_Smoke_Detected OR
    GVL_HEALTH_BRIDGE.G_Leak_Detected OR
    GVL_ALARM.G_Security_Alarm OR
    GVL_ALARM.G_Global_Critical;

GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Accepted := FALSE;
GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied := FALSE;
GVL_ALARM_AUDIBLE_ACK.G_Last_Denial_Code := 0;

IF GVL_CONFIG.G_HMI_Mute_Alarm THEN
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Request := TRUE;
    GVL_CONFIG.G_HMI_Mute_Alarm := FALSE;
END_IF;

IF NOT L_Audible_Alarm_Active THEN
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Active := FALSE;
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Start_MS := 0;
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Expires_MS := 0;
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS := 0;
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm := 0;
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached := FALSE;
    GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible alarm acknowledgement idle';
END_IF;

IF GVL_ALARM_AUDIBLE_ACK.G_Ack_Active THEN
    IF GVL_TIME_SERVICE.G_Now_MS >= GVL_ALARM_AUDIBLE_ACK.G_Ack_Start_MS THEN
        L_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_ALARM_AUDIBLE_ACK.G_Ack_Start_MS;
    ELSE
        L_Elapsed_MS := (4294967295 - GVL_ALARM_AUDIBLE_ACK.G_Ack_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
    END_IF;

    IF L_Elapsed_MS >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Active := FALSE;
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS := 0;
        GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible alarm acknowledgement expired';
    ELSE
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS := (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) - L_Elapsed_MS;
    END_IF;
END_IF;

IF GVL_ALARM_AUDIBLE_ACK.G_Ack_Request THEN
    IF NOT L_Audible_Alarm_Active THEN
        GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Last_Denial_Code := 1;
        GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible acknowledgement denied: no active audible alarm';
    ELSIF GVL_INTENT_USER.I_User_Access_Level < 2 THEN
        GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Last_Denial_Code := 2;
        GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible acknowledgement denied: access level < 2';
    ELSIF GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm >= 3 THEN
        GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Denied := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Last_Denial_Code := 3;
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible acknowledgement denied: limit reached';
    ELSE
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm := GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm + 1;
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Active := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Expires_MS := GVL_TIME_SERVICE.G_Now_MS + (GVL_CONSTANTS.C_MS_IN_MINUTE * 5);
        GVL_ALARM_AUDIBLE_ACK.G_Ack_Remaining_MS := GVL_CONSTANTS.C_MS_IN_MINUTE * 5;
        GVL_ALARM_AUDIBLE_ACK.G_Last_Ack_Accepted := TRUE;
        GVL_ALARM_AUDIBLE_ACK.G_Last_Event_MS := GVL_TIME_SERVICE.G_Now_MS;
        GVL_ALARM_AUDIBLE_ACK.G_Status_Text := 'Audible alarm acknowledged for 5 minutes';
    END_IF;

    GVL_ALARM_AUDIBLE_ACK.G_Ack_Request := FALSE;
END_IF;

IF GVL_ALARM_AUDIBLE_ACK.G_Ack_Count_Current_Alarm >= 3 THEN
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached := TRUE;
ELSE
    GVL_ALARM_AUDIBLE_ACK.G_Ack_Limit_Reached := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Alarm_Audible_Ack_Manager <<<

GVL_SIMULATION.G_Sim_Heating_Sensor_Fault := FALSE;
GVL_SIMULATION.G_Sim_IO_Fault := FALSE;
GVL_SIMULATION.G_Sim_Low_Pressure := FALSE;
GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := FALSE;
GVL_SIMULATION.G_Sim_Gas_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Leak_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Smoke_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Dual_PLC_Active := FALSE;

IF NOT GVL_SIMULATION.G_Simulation_Enable THEN
    GVL_SIMULATION.G_Test_Running := FALSE;
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
    GVL_SIMULATION.G_Test_Expected_Result_Code := 0;
    RETURN;
END_IF;

L_Scenario_Index := TO_INT(GVL_STATUS.G_Current_Scenario);
IF (L_Scenario_Index < 1) OR (L_Scenario_Index > GVL_CONSTANTS.C_MAX_SCENARIOS) THEN
    L_Scenario_Index := 1;
END_IF;
L_Scenario_Config := GVL_CONFIG.G_HMI_Scenario_Configs[L_Scenario_Index];

fbSimulation(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Config := L_Scenario_Config
);

fbPlayback(
    VI_Mode_Record := FALSE,
    VI_Time_Index := GVL_TIME_SERVICE.G_Now_MS,
    VI_Light_Inputs := L_Playback_Lights
);

IF GVL_SIMULATION.G_Test_Start THEN
    GVL_SIMULATION.G_Test_Scenario_Active := TRUE;
    GVL_SIMULATION.G_Test_Started_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

IF GVL_SIMULATION.G_Test_Stop THEN
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
END_IF;

GVL_SIMULATION.G_Test_Running := GVL_SIMULATION.G_Test_Scenario_Active;

IF NOT GVL_SIMULATION.G_Test_Scenario_Active THEN
    GVL_SIMULATION.G_Test_Expected_Result_Code := 0;
    RETURN;
END_IF;

CASE GVL_SIMULATION.G_Test_Scenario_ID OF

    0:
        GVL_SIMULATION.G_Sim_Heating_Sensor_Fault := GVL_SIMULATION.G_Inject_Heating_Sensor_Fault;
        GVL_SIMULATION.G_Sim_IO_Fault := GVL_SIMULATION.G_Inject_IO_Fault;
        GVL_SIMULATION.G_Sim_Low_Pressure := GVL_SIMULATION.G_Inject_Low_Pressure;
        GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := GVL_SIMULATION.G_Inject_Predictive_Pump_Fault;
        GVL_SIMULATION.G_Sim_Gas_Alarm := GVL_SIMULATION.G_Inject_Gas_Alarm;
        GVL_SIMULATION.G_Sim_Leak_Alarm := GVL_SIMULATION.G_Inject_Leak_Alarm;
        GVL_SIMULATION.G_Sim_Smoke_Alarm := GVL_SIMULATION.G_Inject_Smoke_Alarm;
        GVL_SIMULATION.G_Sim_Dual_PLC_Active := GVL_SIMULATION.G_Inject_Dual_PLC_Active;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 0;

    1:
        GVL_SIMULATION.G_Sim_Gas_Alarm := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 1;

    2:
        GVL_SIMULATION.G_Sim_Leak_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Low_Pressure := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 2;

    3:
        GVL_SIMULATION.G_Sim_Heating_Sensor_Fault := TRUE;
        GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 2;

    4:
        GVL_SIMULATION.G_Sim_Dual_PLC_Active := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 3;

    5:
        GVL_SIMULATION.G_Sim_Gas_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Leak_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Smoke_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Low_Pressure := TRUE;
        GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 4;

ELSE
        GVL_SIMULATION.G_Test_Expected_Result_Code := 0;
END_CASE;

IF (GVL_TIME_SERVICE.G_Now_MS - GVL_SIMULATION.G_Test_Started_MS) > GVL_SIMULATION.G_Test_Duration_MS THEN
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
    GVL_SIMULATION.G_Test_Running := FALSE;
END_IF;

