// ======================================================
// DISTRIBUTED COMMIT PUBLICATION
// ======================================================
// Canonical local distributed commit export into the
// HA replication boundary.
//
// Purpose:
// publish normalized deterministic commit handshake state
// into the dedicated HA boundary before commit ingestion.
//
// This layer does NOT:
// - perform reconciliation
// - validate peer acknowledgements
// - arbitrate publication authority
//
// Disabled HA replication must not leave stale commit mirrors.
// ======================================================

IF NOT GVL_HA_SESSION_REPLICATION.HA_Replication_Enabled THEN
    GVL_HA_SESSION_REPLICATION.HA_Remote_Publication_Commit_Epoch := 0;
    GVL_HA_SESSION_REPLICATION.HA_Remote_Prepare_Epoch := 0;
    GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Ack_Valid := FALSE;
    GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Last_Refresh_MS := 0;
    RETURN;
END_IF;

GVL_HA_SESSION_REPLICATION.HA_Remote_Publication_Commit_Epoch :=
    GVL_DISTRIBUTED_COMMIT.Local_Publication_Commit_Epoch;

GVL_HA_SESSION_REPLICATION.HA_Remote_Prepare_Epoch :=
    GVL_DISTRIBUTED_COMMIT.Local_Prepare_Epoch;

GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Ack_Valid :=
    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed;

GVL_HA_SESSION_REPLICATION.HA_Remote_Commit_Last_Refresh_MS :=
    GVL_STATUS.G_System_Time_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Distributed_Commit_Publication <<<

IF GVL_POWER_DOMAIN_SEGMENTATION_FABRIC.Power_Domain_Segmentation_Granted
AND NOT GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Unsafe_Energy_Resurrection_Detected
AND NOT GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.CrossDomain_Energy_Recovery_Race
AND NOT GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Energy_Recovery_Fork_Detected THEN

    GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Energy_Resurrection_Boundary_Valid := TRUE;
    GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Energy_Resurrection_Boundary_Granted := TRUE;
    GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Energy_Resurrection_Causality_Valid := TRUE;
    GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.Energy_Authority_Recovery_Bounded := TRUE;
    GVL_ENERGY_RESURRECTION_BOUNDARY_FABRIC.CrossDomain_Energy_Recovery_Stable := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Semantic_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Phase_Stall_Detected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Output_Stall_Detected := FALSE;

GVL_SEMANTIC_PROGRESS.Semantic_Runtime_Barrier_Epoch := ULINT_TO_UDINT(GVL_RUNTIME_EPOCH.Runtime_Epoch);
GVL_SEMANTIC_PROGRESS.Semantic_Runtime_Snapshot_Epoch := ULINT_TO_UDINT(GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch);
GVL_SEMANTIC_PROGRESS.Semantic_Distributed_Commit_Epoch := ULINT_TO_UDINT(GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Epoch);
GVL_SEMANTIC_PROGRESS.Semantic_Output_Publication_Epoch := ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch);

GVL_SEMANTIC_PROGRESS.Semantic_Runtime_Barrier_Evidence_OK :=
    GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK AND
    GVL_RUNTIME_EPOCH.Runtime_Snapshot_Published AND
    GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed;

GVL_SEMANTIC_PROGRESS.Semantic_Runtime_Snapshot_Evidence_OK :=
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen AND
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed AND
    GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid AND
    GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid AND
    GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid AND
    NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected;

GVL_SEMANTIC_PROGRESS.Semantic_Distributed_Commit_Evidence_OK :=
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid AND
    GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid AND
    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed AND
    NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch AND
    NOT GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active AND
    NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired;

GVL_SEMANTIC_PROGRESS.Semantic_Output_Publication_Evidence_OK :=
    GVL_OUTPUT_EPOCH.Output_Publication_Valid AND
    GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid AND
    NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired AND
    NOT GVL_OUTPUT_EPOCH.Output_Stale_Detected AND
    NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    fbDebounce_Flood[L_i](
        IN := GVL_IO.DI_Flood_Sensors[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );
    GVL_STATE.G_Water_Sensors[L_i] := fbDebounce_Flood[L_i].Q;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    fbDebounce_Smoke[L_i](
        IN := GVL_IO.DI_Smoke_Sensors[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );
    GVL_STATE.G_Smoke_Sensors[L_i] := fbDebounce_Smoke[L_i].Q;
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Discrete_03_Safety_Sensors <<<

// IO write phase 02: publish hard-stop safe physical outputs.


FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_IO.DO_Zone_Valves[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
