// >>> BULK_SYNC_ANCHOR: PRG_Safety <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Causality_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_TELEMETRY.Telemetry_Runtime_Valid := FALSE;
GVL_TELEMETRY.Telemetry_Freshness_Valid := FALSE;
GVL_TELEMETRY.Command_Telemetry_Causality_Valid := FALSE;
GVL_TELEMETRY.Actuator_Feedback_Valid := FALSE;
GVL_TELEMETRY.Actuator_Feedback_Fresh := FALSE;
GVL_TELEMETRY.Physical_Effect_Confirmed := FALSE;
GVL_TELEMETRY.Physical_Effect_Finalized := FALSE;
GVL_TELEMETRY.Physical_Target_Converged := FALSE;
GVL_TELEMETRY.Physical_Stable_Window_OK := FALSE;
GVL_TELEMETRY.Command_Telemetry_Divergence_Detected := TRUE;

GVL_TELEMETRY.Command_Epoch := ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch);

IF NOT GVL_OUTPUT_EPOCH.Output_Publication_Valid THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21000;
    L_Error_Text := 'Telemetry causality output publication invalid';
END_IF;

IF L_Causality_Valid AND NOT GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21001;
    L_Error_Text := 'Telemetry causality runtime epoch invalid';
END_IF;

IF L_Causality_Valid AND GVL_OUTPUT_EPOCH.Output_Lease_Expired THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21002;
    L_Error_Text := 'Telemetry causality output lease expired';
END_IF;

IF L_Causality_Valid AND GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21003;
    L_Error_Text := 'Telemetry causality output forced safe decay';
END_IF;

IF L_Causality_Valid AND (GVL_TELEMETRY.Telemetry_Epoch <> GVL_TELEMETRY.Command_Epoch) THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21010;
    L_Error_Text := 'Telemetry epoch does not match command epoch';
END_IF;

IF L_Causality_Valid AND (GVL_TELEMETRY.Telemetry_Epoch < GVL_TELEMETRY.Last_Acknowledged_Command_Epoch) THEN
    GVL_TELEMETRY.Telemetry_Replay_Suspected := TRUE;

    L_Causality_Valid := FALSE;
    L_Error_Code := 21011;
    L_Error_Text := 'Telemetry epoch replay suspected';
END_IF;

L_Ack_Age_MS := L_Now_MS - GVL_TELEMETRY.Last_Physical_Ack_Time_MS;

IF L_Causality_Valid AND (L_Ack_Age_MS > 5000) THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21020;
    L_Error_Text := 'Physical acknowledgement stale';
END_IF;

L_Convergence_Age_MS := L_Now_MS - GVL_TELEMETRY.Last_Physical_Convergence_MS;

IF L_Causality_Valid AND (L_Convergence_Age_MS > 10000) THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21021;
    L_Error_Text := 'Physical convergence stale';
END_IF;

L_Stable_Dwell_MS :=
    L_Now_MS - GVL_TELEMETRY.Last_Physical_Convergence_MS;

IF L_Causality_Valid AND (L_Stable_Dwell_MS < 3000) THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21030;
    L_Error_Text := 'Physical stabilization dwell window incomplete';
END_IF;

IF L_Causality_Valid
AND GVL_TELEMETRY.Physical_Oscillation_Detected THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21031;
    L_Error_Text := 'Physical oscillation detected';
END_IF;

IF L_Causality_Valid
AND GVL_TELEMETRY.Physical_Transition_Active THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21032;
    L_Error_Text := 'Physical transition still active';
END_IF;

IF L_Causality_Valid
AND GVL_TELEMETRY.Physical_Convergence_Replay_Suspected THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21033;
    L_Error_Text := 'Physical convergence replay suspected';
END_IF;

L_Consensus_Age_MS :=
    L_Now_MS - GVL_SENSOR_CONSENSUS.Last_Consensus_Update_MS;

IF L_Causality_Valid
AND (L_Consensus_Age_MS > 5000) THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21040;
    L_Error_Text := 'Sensor consensus stale';
END_IF;

IF L_Causality_Valid
AND NOT GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21041;
    L_Error_Text := 'Sensor consensus invalid';
END_IF;

IF L_Causality_Valid
AND NOT GVL_SENSOR_CONSENSUS.Physics_Invariants_Satisfied THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21042;
    L_Error_Text := 'Physics invariants violated';
END_IF;

IF L_Causality_Valid
AND NOT GVL_SENSOR_CONSENSUS.Cross_Sensor_Correlation_Valid THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21043;
    L_Error_Text := 'Cross sensor correlation invalid';
END_IF;

IF L_Causality_Valid
AND NOT GVL_SENSOR_CONSENSUS.Telemetry_Plausibility_Valid THEN
    L_Causality_Valid := FALSE;
    L_Error_Code := 21044;
    L_Error_Text := 'Telemetry plausibility invalid';
END_IF;

IF L_Causality_Valid
AND (GVL_SENSOR_CONSENSUS.Sensor_Drift_Detected
     OR GVL_SENSOR_CONSENSUS.Sensor_Partition_Detected
     OR GVL_SENSOR_CONSENSUS.Sensor_Hallucination_Suspected
     OR GVL_SENSOR_CONSENSUS.Cross_Sensor_Divergence_Detected
     OR GVL_SENSOR_CONSENSUS.Sensor_Oscillation_Detected
     OR GVL_SENSOR_CONSENSUS.Sensor_Stuck_State_Detected
     OR GVL_SENSOR_CONSENSUS.Sensor_Replay_Suspected) THEN

    L_Causality_Valid := FALSE;
    L_Error_Code := 21045;
    L_Error_Text := 'Sensor consensus divergence detected';
END_IF;

IF L_Causality_Valid THEN
    GVL_TELEMETRY.Telemetry_Runtime_Valid := TRUE;
    GVL_TELEMETRY.Telemetry_Freshness_Valid := TRUE;
    GVL_TELEMETRY.Telemetry_Lease_Expired := FALSE;
    GVL_TELEMETRY.Telemetry_Quarantine_Active := FALSE;

    GVL_TELEMETRY.Command_Telemetry_Causality_Valid := TRUE;
    GVL_TELEMETRY.Command_Telemetry_Divergence_Detected := FALSE;

    GVL_TELEMETRY.Actuator_Feedback_Valid := TRUE;
    GVL_TELEMETRY.Actuator_Feedback_Fresh := TRUE;
    GVL_TELEMETRY.Physical_Effect_Confirmed := TRUE;

    GVL_TELEMETRY.Physical_Target_Converged := TRUE;
    GVL_TELEMETRY.Physical_Stable_Window_OK := TRUE;
    GVL_TELEMETRY.Physical_Effect_Finalized := TRUE;

    GVL_TELEMETRY.Last_Acknowledged_Command_Epoch := GVL_TELEMETRY.Command_Epoch;

    GVL_TELEMETRY.Telemetry_Last_Error_Code := 0;
    GVL_TELEMETRY.Telemetry_Last_Error_Text := '';
ELSE
    GVL_TELEMETRY.Telemetry_Runtime_Valid := FALSE;
    GVL_TELEMETRY.Telemetry_Freshness_Valid := FALSE;
    GVL_TELEMETRY.Telemetry_Lease_Expired := TRUE;
    GVL_TELEMETRY.Telemetry_Quarantine_Active := TRUE;

    GVL_TELEMETRY.Command_Telemetry_Causality_Valid := FALSE;
    GVL_TELEMETRY.Command_Telemetry_Divergence_Detected := TRUE;

    GVL_TELEMETRY.Telemetry_Last_Error_Code := L_Error_Code;
    GVL_TELEMETRY.Telemetry_Last_Error_Text := L_Error_Text;
    GVL_TELEMETRY.Telemetry_Invalidation_Count :=
        GVL_TELEMETRY.Telemetry_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_History_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_HISTORICAL_TRUTH.Historical_Truth_Valid := FALSE;
GVL_HISTORICAL_TRUTH.Historical_Truth_Granted := FALSE;
GVL_HISTORICAL_TRUTH.Historical_Truth_Quarantine_Active := TRUE;

GVL_HISTORICAL_TRUTH.Trend_History_Causally_Immutable := FALSE;
GVL_HISTORICAL_TRUTH.Alarm_Chronology_Immutable := FALSE;
GVL_HISTORICAL_TRUTH.Blackbox_Snapshot_Immutable := FALSE;
GVL_HISTORICAL_TRUTH.Diagnostics_History_Coherent := FALSE;
GVL_HISTORICAL_TRUTH.Failover_Chronology_Coherent := FALSE;

// Observability truth authority required.
IF NOT GVL_OBSERVABILITY_TRUTH.Observability_Truth_Granted THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33000;
    L_Error_Text := 'Observability truth authority not granted';
END_IF;

// Historical corruption detectors.
IF GVL_HISTORICAL_TRUTH.History_Epoch_Skew_Detected THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33001;
    L_Error_Text := 'Historical epoch skew detected';
END_IF;

IF GVL_HISTORICAL_TRUTH.Failover_Chronology_Corruption_Detected THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33002;
    L_Error_Text := 'Failover chronology corruption detected';
END_IF;

IF GVL_HISTORICAL_TRUTH.Trend_Replay_Race_Detected THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33003;
    L_Error_Text := 'Trend replay race detected';
END_IF;

IF GVL_HISTORICAL_TRUTH.Blackbox_Causality_Drift_Detected THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33004;
    L_Error_Text := 'Blackbox causality drift detected';
END_IF;

IF GVL_HISTORICAL_TRUTH.Alarm_Order_Reconstruction_Error THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33005;
    L_Error_Text := 'Alarm order reconstruction error detected';
END_IF;

IF GVL_HISTORICAL_TRUTH.Mixed_Authority_Persistence_Detected THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33006;
    L_Error_Text := 'Mixed-authority persistence detected';
END_IF;

// Historical persistence integrity validation.
IF L_History_Valid
AND NOT GVL_HISTORICAL_TRUTH.Persisted_Epochs_Coherent THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33010;
    L_Error_Text := 'Persisted epoch coherence invalid';
END_IF;

IF L_History_Valid
AND NOT GVL_HISTORICAL_TRUTH.Recovery_Replay_Coherent THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33011;
    L_Error_Text := 'Recovery replay coherence invalid';
END_IF;

IF L_History_Valid
AND NOT GVL_HISTORICAL_TRUTH.Historical_Snapshot_Coherent THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33012;
    L_Error_Text := 'Historical snapshot coherence invalid';
END_IF;

IF L_History_Valid
AND NOT GVL_HISTORICAL_TRUTH.Mixed_Authority_Persistence_Absent THEN
    L_History_Valid := FALSE;
    L_Error_Code := 33013;
    L_Error_Text := 'Mixed-authority persistence absence invalid';
END_IF;

IF L_History_Valid THEN
    GVL_HISTORICAL_TRUTH.Historical_Truth_Valid := TRUE;
    GVL_HISTORICAL_TRUTH.Historical_Truth_Granted := TRUE;
    GVL_HISTORICAL_TRUTH.Historical_Truth_Quarantine_Active := FALSE;

    GVL_HISTORICAL_TRUTH.Trend_History_Causally_Immutable := TRUE;
    GVL_HISTORICAL_TRUTH.Alarm_Chronology_Immutable := TRUE;
    GVL_HISTORICAL_TRUTH.Blackbox_Snapshot_Immutable := TRUE;
    GVL_HISTORICAL_TRUTH.Diagnostics_History_Coherent := TRUE;
    GVL_HISTORICAL_TRUTH.Failover_Chronology_Coherent := TRUE;

    GVL_HISTORICAL_TRUTH.Historical_Truth_Epoch :=
        GVL_OBSERVABILITY_TRUTH.Observability_Truth_Epoch;

    GVL_HISTORICAL_TRUTH.Historical_Truth_Epoch_Coherent := TRUE;

    GVL_HISTORICAL_TRUTH.Historical_Last_Update_MS := L_Now_MS;
    GVL_HISTORICAL_TRUTH.Historical_Lease_Expired := FALSE;

    GVL_HISTORICAL_TRUTH.Historical_Last_Error_Code := 0;
    GVL_HISTORICAL_TRUTH.Historical_Last_Error_Text := '';
ELSE
    GVL_HISTORICAL_TRUTH.Historical_Truth_Valid := FALSE;
    GVL_HISTORICAL_TRUTH.Historical_Truth_Granted := FALSE;
    GVL_HISTORICAL_TRUTH.Historical_Truth_Quarantine_Active := TRUE;

    GVL_HISTORICAL_TRUTH.Historical_Lease_Expired := TRUE;

    GVL_HISTORICAL_TRUTH.Historical_Last_Error_Code :=
        L_Error_Code;

    GVL_HISTORICAL_TRUTH.Historical_Last_Error_Text :=
        L_Error_Text;

    GVL_HISTORICAL_TRUTH.Historical_Invalidation_Count :=
        GVL_HISTORICAL_TRUTH.Historical_Invalidation_Count + 1;
END_IF;

// IO write phase 03: publish normal domain output projections.


FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF (L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits)
       OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Heating_Forced_Off THEN
        GVL_IO.DO_Zone_Valves[L_i] := FALSE;
    ELSE
        GVL_IO.DO_Zone_Valves[L_i] := GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Heating_Forced_Off
       AND NOT (GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Safety_Stop
                AND GVL_IO_WRITE_RUNTIME_BUFFER.B_Freeze_Active) THEN
        GVL_IO.DO_Manifold_Pumps[L_i] := FALSE;
        GVL_IO.AO_Manifold_Valves[L_i] := 0;
    ELSE
        GVL_IO.DO_Manifold_Pumps[L_i] := GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i];
        GVL_IO.AO_Manifold_Valves[L_i] := GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i];
    END_IF;
END_FOR;

IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Heating_Forced_Off
   AND NOT (GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Safety_Stop
            AND GVL_IO_WRITE_RUNTIME_BUFFER.B_Freeze_Active) THEN
    GVL_IO.DO_DHW_Heating_Pump := FALSE;
    GVL_IO.DO_DHW_Circ_Pump := FALSE;
    GVL_IO.DO_Backup_Circulation_Pump := FALSE;
    GVL_IO.DO_Electric_Heater_Enable := FALSE;
ELSE
    GVL_IO.DO_DHW_Heating_Pump := GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump;
    GVL_IO.DO_DHW_Circ_Pump := GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump;
    GVL_IO.DO_Backup_Circulation_Pump := GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump;
    GVL_IO.DO_Electric_Heater_Enable := GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Vent_Forced_Off THEN
        GVL_IO.AO_Supply_Fans[L_i] := 0;
    ELSE
        GVL_IO.AO_Supply_Fans[L_i] := GVL_VENT_OUTPUT.AO_Supply_Fans[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Vent_Forced_Off THEN
        GVL_IO.AO_Exhaust_Fans[L_i] := 0;
    ELSE
        GVL_IO.AO_Exhaust_Fans[L_i] := GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i];
    END_IF;
END_FOR;

// Water outputs. PRG_Water owns the domain projection in GVL_WATER_OUTPUT;
// command shadow remains the common-inlet emergency fallback.
IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Water_Forced_Off THEN
    GVL_IO.DO_Water_Valve_35_Open := FALSE;
    GVL_IO.DO_Water_Valve_35_Close := FALSE;
    GVL_IO.DO_Water_Valve_36_Open := FALSE;
    GVL_IO.DO_Water_Valve_36_Close := FALSE;

    FOR L_i := 1 TO 6 DO
        GVL_IO.DO_Water_Local_Valve_Open[L_i] := FALSE;
        GVL_IO.DO_Water_Local_Valve_Close[L_i] := FALSE;
    END_FOR;
ELSE
    GVL_IO.DO_Water_Valve_35_Open := GVL_WATER_OUTPUT.DO_Water_Valve_35_Open;
    GVL_IO.DO_Water_Valve_35_Close := GVL_WATER_OUTPUT.DO_Water_Valve_35_Close OR GVL_COMMAND_SHADOW.G_Close_Valve_35;
    GVL_IO.DO_Water_Valve_36_Open := GVL_WATER_OUTPUT.DO_Water_Valve_36_Open;
    GVL_IO.DO_Water_Valve_36_Close := GVL_WATER_OUTPUT.DO_Water_Valve_36_Close OR GVL_COMMAND_SHADOW.G_Close_Valve_36;

    FOR L_i := 1 TO 6 DO
        GVL_IO.DO_Water_Local_Valve_Open[L_i] := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Open[L_i];
        GVL_IO.DO_Water_Local_Valve_Close[L_i] := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Close[L_i];
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    IF (L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones)
       OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Water_Forced_Off THEN
        GVL_IO.DO_Water_Zone_Enable[L_i] := FALSE;
    ELSE
        GVL_IO.DO_Water_Zone_Enable[L_i] := GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    IF L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones THEN
        GVL_IO.AO_Lighting_Levels[L_i] := 0;
    ELSE
        GVL_IO.AO_Lighting_Levels[L_i] := GVL_LIGHTING_OUTPUT.AO_Lighting_Levels[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    IF L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Blinds THEN
        GVL_IO.AO_Blinds_Positions[L_i] := 1000;
    ELSE
        GVL_IO.AO_Blinds_Positions[L_i] := GVL_LIGHTING_OUTPUT.AO_Blinds_Positions[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    IF L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Sockets THEN
        GVL_IO.DO_Sockets[L_i] := FALSE;
    ELSE
        GVL_IO.DO_Sockets[L_i] := GVL_LIGHTING_OUTPUT.DO_Sockets[L_i];
    END_IF;
END_FOR;

IF GVL_IO_WRITE_RUNTIME_BUFFER.B_Access_Forced_Off THEN
    GVL_IO.DO_Gate_Open := FALSE;
    GVL_IO.DO_Wicket_Open := FALSE;
    GVL_IO.DO_Lock_1_Open := FALSE;
    GVL_IO.DO_Lock_1_Close := FALSE;
    GVL_IO.DO_Lock_2_Open := FALSE;
    GVL_IO.DO_Lock_2_Close := FALSE;
ELSE
    GVL_IO.DO_Gate_Open := GVL_ACCESS_OUTPUT.DO_Gate_Open;
    GVL_IO.DO_Wicket_Open := GVL_ACCESS_OUTPUT.DO_Wicket_Open;
    GVL_IO.DO_Lock_1_Open := GVL_ACCESS_OUTPUT.DO_Lock_1_Open;
    GVL_IO.DO_Lock_1_Close := GVL_ACCESS_OUTPUT.DO_Lock_1_Close;
    GVL_IO.DO_Lock_2_Open := GVL_ACCESS_OUTPUT.DO_Lock_2_Open;
    GVL_IO.DO_Lock_2_Close := GVL_ACCESS_OUTPUT.DO_Lock_2_Close;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Write_Phase_03_Domain_Projection <<<

IF GVL_PHYSICAL_SAFETY_PROJECTION_FABRIC.Physical_Safety_Projection_Granted
AND NOT GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Unsafe_Transition_Hidden
AND NOT GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Forensic_Lineage_Break_Detected
AND NOT GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Historical_Safety_Gap_Detected THEN

    GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Unsafe_Transition_Forensics_Valid := TRUE;
    GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Unsafe_Transition_Forensics_Granted := TRUE;
    GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Unsafe_Transition_Lineage_Preserved := TRUE;
    GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Forensic_Causality_Continuity_Valid := TRUE;
    GVL_UNSAFE_TRANSITION_FORENSICS_FABRIC.Distributed_Unsafe_Event_Consensus := TRUE;
END_IF;

IF GVL_LIGHTING_RUNTIME_BUFFER.B_Distributed_Execute_Allowed THEN
// Copy user/system rule actions into a cycle-local surface. Outdoor lighting // adds actions here so global GVL_STATE.G_Rule_Actions is not overwritten. FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO L_Effective_Rule_Actions[L_i] := GVL_STATE.G_Rule_Actions[L_i]; END_FOR;
fbOutdoorLightingManager( VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Current_Scenario := GVL_STATUS.G_Current_Scenario, VI_Security_Armed := GVL_ALARM.G_Security_Armed, VI_Is_Night := GVL_STATUS.G_Is_Night, VI_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Time_Of_Day_MS, VIO_Rule_Actions := L_Effective_Rule_Actions, VI_Motion_Sensors := GVL_LIGHTING_RUNTIME_BUFFER.B_Motion_Sensors );
fbLightingManager( VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Current_Scenario := GVL_STATUS.G_Current_Scenario, VI_Away_Level := GVL_POLICY.G_Away_Level, VI_Simulation_Active := GVL_STATUS.G_Sim_Active OR GVL_POLICY.G_Away_Simulation_Active, VI_Is_Night := GVL_STATUS.G_Is_Night, VI_System_Mode := GVL_STATE.G_System_Mode, VI_Manual_Light_Override := GVL_LIGHTING_RUNTIME_BUFFER.B_Manual_Light_Override, VI_Manual_Blinds_Override := GVL_LIGHTING_RUNTIME_BUFFER.B_Blinds_Override, VI_Simulation_Lights := GVL_LIGHTING_RUNTIME_BUFFER.B_Sim_Lights, VI_Physical_Switches := GVL_LIGHTING_RUNTIME_BUFFER.B_Physical_Switches, VI_Motion_Sensors := GVL_LIGHTING_RUNTIME_BUFFER.B_Motion_Sensors, VI_Rule_Actions := L_Effective_Rule_Actions, VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online, VI_Wet_Zone_Map := GVL_CONFIG.G_Wet_Zone_Map, VI_Scenario_Configs := GVL_CONFIG.G_HMI_Scenario_Configs, VO_Lighting_Levels => GVL_STATE.G_Lighting_Levels, VO_Blinds_Positions => GVL_STATE.G_Blinds_Positions, VO_Wet_Zone_Light_Active => GVL_LIGHTING_RUNTIME_BUFFER.B_Wet_Zone_Light_Active );
fbSocketManager( VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Scenario := GVL_STATUS.G_Current_Scenario, VI_Manual_Override := GVL_LIGHTING_RUNTIME_BUFFER.B_Socket_Override, VI_Physical_Switches := GVL_STATE.G_Socket_Switches, VI_Rule_Actions := L_Effective_Rule_Actions, VI_Fire_Alarm := GVL_LIGHTING_RUNTIME_BUFFER.B_Fire_Alarm_Active, VI_Flood_Alarm := GVL_LIGHTING_RUNTIME_BUFFER.B_Flood_Alarm_Active, VI_Security_Armed := GVL_ALARM.G_Security_Armed, VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online, VO_Socket_States => GVL_STATE.G_Socket_States );
END_IF;
// >>> BULK_SYNC_ANCHOR: PRG_Lighting_Phase_02_Managers <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    fbRoomTempQuality[L_i](
        VI_Enable := GVL_INPUT_VALIDATION_CONFIG.G_Enable_Temporal_Anomaly_Detection,
        VI_Value := GVL_STATE.G_Room_Temps[L_i],
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Spike_Threshold := GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Spike_Threshold,
        VI_Stuck_Timeout_MS := GVL_INPUT_VALIDATION_CONFIG.G_Sensor_Stuck_Timeout_MS,
        VO_Quality => GVL_INPUT_QUALITY.G_Room_Temp_Quality[L_i]
    );
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    fbFloorTempQuality[L_i](
        VI_Enable := GVL_INPUT_VALIDATION_CONFIG.G_Enable_Temporal_Anomaly_Detection,
        VI_Value := GVL_STATE.G_Floor_Temps[L_i],
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Spike_Threshold := GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Spike_Threshold,
        VI_Stuck_Timeout_MS := GVL_INPUT_VALIDATION_CONFIG.G_Sensor_Stuck_Timeout_MS,
        VO_Quality => GVL_INPUT_QUALITY.G_Floor_Temp_Quality[L_i]
    );
END_FOR;

// CONTROLLED CAPABILITY SHEDDING
// DETERMINISTIC / TIER-AWARE / NON-INVASIVE

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Budget_Pressure_Observed THEN
    GVL_FABRIC_LIFECYCLE_REGISTRY.Controlled_Capability_Shedding_Allowed := TRUE;
    GVL_FABRIC_LIFECYCLE_REGISTRY.Runtime_Adaptive_Mode := REDUCED_ANALYTICS_MODE;
END_IF;

IF GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Chronic_Degradation_Risk_Increasing THEN
    GVL_FABRIC_LIFECYCLE_REGISTRY.Runtime_Adaptive_Mode := SURVIVABILITY_MODE;
    GVL_FABRIC_LIFECYCLE_REGISTRY.NonEssential_Analytics_Shedding_Recommended := TRUE;
    GVL_FABRIC_LIFECYCLE_REGISTRY.Diagnostics_Degradation_Recommended := TRUE;
END_IF;

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Verification_Induced_Runtime_Risk THEN
    GVL_FABRIC_LIFECYCLE_REGISTRY.Extended_Observability_Shedding_Recommended := TRUE;
    GVL_FABRIC_LIFECYCLE_REGISTRY.Simulation_Suspension_Recommended := TRUE;
END_IF;

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Stability_Budget_At_Risk THEN
    GVL_FABRIC_LIFECYCLE_REGISTRY.Analytics_Fabric_State := FABRIC_DEGRADED;
    GVL_FABRIC_LIFECYCLE_REGISTRY.Observability_Fabric_State := FABRIC_PASSIVE;
END_IF;

// Critical fabrics remain protected.
GVL_FABRIC_LIFECYCLE_REGISTRY.Safety_Fabric_State := FABRIC_ACTIVE;
GVL_FABRIC_LIFECYCLE_REGISTRY.Authority_Fabric_State := FABRIC_ACTIVE;
GVL_FABRIC_LIFECYCLE_REGISTRY.Physical_Reality_Fabric_State := FABRIC_ACTIVE;

IF NOT GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Budget_Pressure_Observed THEN
    GVL_FABRIC_LIFECYCLE_REGISTRY.Gradual_Reactivation_Allowed := TRUE;
END_IF;

// CANONICAL EXECUTION DOMAIN
// PRESERVES EXECUTION ORDER

PRG_Time_Service();
PRG_System_Init();
PRG_Runtime_Barrier();
PRG_Runtime_Snapshot_Governor();
PRG_Runtime_Assumption_Integrity_Governor();

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Runtime_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Valid := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Granted := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Quarantine_Active := TRUE;

GVL_RUNTIME_RESOURCE_AUTHORITY.Deterministic_Cycle_Time_Valid := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Task_Jitter_Within_Bounds := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Watchdog_Margin_Stable := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Latency_Stable := FALSE;
GVL_RUNTIME_RESOURCE_AUTHORITY.Queue_Backlog_Stable := FALSE;

// Environmental authority required.
IF NOT GVL_ENVIRONMENTAL_AUTHORITY.Environmental_Authority_Granted THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30000;
    L_Error_Text := 'Environmental authority not granted';
END_IF;

// Resource exhaustion detectors.
IF GVL_RUNTIME_RESOURCE_AUTHORITY.Hidden_Jitter_Amplification_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30001;
    L_Error_Text := 'Hidden jitter amplification detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Queue_Induced_Authority_Lag_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30002;
    L_Error_Text := 'Queue-induced authority lag detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Watchdog_Near_Death_Oscillation_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30003;
    L_Error_Text := 'Watchdog near-death oscillation detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Starvation_Race_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30004;
    L_Error_Text := 'Runtime starvation race detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Cycle_Collapse_SplitBrain_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30005;
    L_Error_Text := 'Cycle collapse split-brain detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Heap_Fragmentation_Critical THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30006;
    L_Error_Text := 'Critical heap fragmentation detected';
END_IF;

IF GVL_RUNTIME_RESOURCE_AUTHORITY.Fieldbus_Backlog_Saturation_Detected THEN
    L_Runtime_Valid := FALSE;
    L_Error_Code := 30007;
    L_Error_Text := 'Fieldbus backlog saturation detected';
END_IF;

// Deterministic execution envelope validation.
IF L_Runtime_Valid
AND (GVL_RUNTIME_RESOURCE_AUTHORITY.Current_Task_Jitter_US >
     GVL_RUNTIME_RESOURCE_AUTHORITY.Max_Allowed_Task_Jitter_US) THEN

    L_Runtime_Valid := FALSE;
    L_Error_Code := 30010;
    L_Error_Text := 'Task jitter exceeds deterministic envelope';
END_IF;

IF L_Runtime_Valid
AND (GVL_RUNTIME_RESOURCE_AUTHORITY.Current_Runtime_Latency_US >
     GVL_RUNTIME_RESOURCE_AUTHORITY.Max_Allowed_Runtime_Latency_US) THEN

    L_Runtime_Valid := FALSE;
    L_Error_Code := 30011;
    L_Error_Text := 'Runtime latency exceeds deterministic envelope';
END_IF;

IF L_Runtime_Valid
AND (GVL_RUNTIME_RESOURCE_AUTHORITY.Current_Fieldbus_Queue_Depth >
     GVL_RUNTIME_RESOURCE_AUTHORITY.Max_Allowed_Fieldbus_Queue_Depth) THEN

    L_Runtime_Valid := FALSE;
    L_Error_Code := 30012;
    L_Error_Text := 'Fieldbus queue depth exceeds deterministic envelope';
END_IF;

IF L_Runtime_Valid
AND (GVL_RUNTIME_RESOURCE_AUTHORITY.Current_Watchdog_Margin_MS <
     GVL_RUNTIME_RESOURCE_AUTHORITY.Minimum_Watchdog_Margin_MS) THEN

    L_Runtime_Valid := FALSE;
    L_Error_Code := 30013;
    L_Error_Text := 'Watchdog margin below deterministic envelope';
END_IF;

IF L_Runtime_Valid THEN
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Valid := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Granted := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Quarantine_Active := FALSE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Deterministic_Cycle_Time_Valid := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Task_Jitter_Within_Bounds := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Watchdog_Margin_Stable := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Latency_Stable := TRUE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Queue_Backlog_Stable := TRUE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Epoch :=
        GVL_ENVIRONMENTAL_AUTHORITY.Environmental_Authority_Epoch;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Epoch_Coherent := TRUE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Last_Update_MS :=
        L_Now_MS;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Lease_Expired := FALSE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Last_Error_Code := 0;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Valid := FALSE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Granted := FALSE;
    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Quarantine_Active := TRUE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Lease_Expired := TRUE;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Last_Error_Code :=
        L_Error_Code;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Last_Error_Text :=
        L_Error_Text;

    GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Invalidation_Count :=
        GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Invalidation_Count + 1;
END_IF;

// adapt motion sensors (32 -> 16)
FOR L_i := 1 TO 16 DO
    L_Motion_16[L_i] := GVL_STATE.G_Motion_Sensors[L_i];
END_FOR;

IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    L_Scenario_Req_Operator := GVL_COMMAND.G_Scenario_Request_Operator;
ELSE
    L_Scenario_Req_Operator := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

L_Scenario_Req_Gateway := GVL_INTENT_USER.I_Scenario_Request;
L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
L_Best_Rule_Priority := 0;
GVL_POLICY.G_Rule_Preheat_Request := FALSE;
GVL_POLICY.G_Scenario_Request_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;

fbRuleEngine(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VI_Current_Time := GVL_TIME_SERVICE.G_Current_TOD,
    VI_Day_Of_Week := GVL_TIME_SERVICE.G_Day_Of_Week,
    VI_Rules := GVL_CONFIG.G_HMI_User_Rules,
    VI_Indoor_Temps := GVL_STATE.G_Room_Temps,
    VI_Floor_Temps := GVL_STATE.G_Floor_Temps,
    VI_Humidities := GVL_STATE.G_Room_Hum,
    VI_CO2_Levels := GVL_STATE.G_Room_CO2,
    VI_Motion_Sensors := L_Motion_16,
    VI_Door_Sensors := GVL_STATE.G_Door_Sensors,
    VI_Window_Sensors := GVL_STATE.G_Window_Sensors,
    VI_Water_Sensors := GVL_STATE.G_Water_Sensors,
    VI_Smoke_Sensors := GVL_STATE.G_Smoke_Sensors,
    VI_Methane_Sensors := GVL_STATE.G_Methane_Sensors,
    VI_CO_Sensors := GVL_STATE.G_CO_Sensors,
    VO_Preheat_Request => GVL_POLICY.G_Rule_Preheat_Request,
    VO_Actions => GVL_STATE.G_Rule_Actions
);

// Scenario actions are bridged into policy/scenario arbitration. If several
// scenario rules are active, the highest rule Priority wins. Operator and
// gateway requests still outrank rule requests in FB_System_Scenario_Arbitration.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
    IF GVL_STATE.G_Rule_Actions[L_i].Active AND
       (GVL_STATE.G_Rule_Actions[L_i].Action_Type = E_Rule_Action_Type.ACTION_ACTIVATE_SCENARIO) THEN

        L_Rule_Scenario_Code := REAL_TO_INT(GVL_STATE.G_Rule_Actions[L_i].Value);

        IF (L_Rule_Scenario_Code >= 0) AND (L_Rule_Scenario_Code <= 7) AND
           ((L_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) OR
            (GVL_CONFIG.G_HMI_User_Rules[L_i].Priority >= L_Best_Rule_Priority)) THEN

            L_Best_Rule_Priority := GVL_CONFIG.G_HMI_User_Rules[L_i].Priority;

            CASE L_Rule_Scenario_Code OF
                0:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
                1:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_MORNING;
                2:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_EVENING;
                3:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_AWAY;
                4:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_PARTY;
                5:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_SLEEP;
                6:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_EMERGENCY;
                7:
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_PRESENCE;
            ELSE
                    L_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
            END_CASE;
        END_IF;
    END_IF;
END_FOR;

GVL_POLICY.G_Scenario_Request_Rule := L_Scenario_Req_Rule;

fbSystemScenarioArb(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VIO_Scenario_Req_Operator := L_Scenario_Req_Operator,
    VIO_Scenario_Req_Gateway := L_Scenario_Req_Gateway,
    VIO_Scenario_Req_Rule := L_Scenario_Req_Rule,
    VIO_Scenario_Req_Final := L_Scenario_Req_Final,
    VIO_Scenario_Intent := L_Scenario_Intent,
    VIO_Scenario_Source := L_Scenario_Source
);

GVL_POLICY.G_Scenario_Intent := L_Scenario_Intent;
GVL_POLICY.G_Scenario_Source := L_Scenario_Source;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Observability_Valid := TRUE;

// Fail-safe defaults.
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Authority_Valid := FALSE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Quarantine_Active := TRUE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Publication_Allowed := FALSE;

GVL_OBSERVABILITY_AUTHORITY_FABRIC.HMI_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Diagnostics_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Blackbox_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Trend_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_AUTHORITY_FABRIC.Alarm_Authority_Coherent := FALSE;

// Revocation blocks authoritative observability.
IF GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active THEN
    L_Observability_Valid := FALSE;
END_IF;

// Restoration must be fully completed.
IF L_Observability_Valid
AND NOT GVL_AUTHORITY_RESTORATION.Authority_Restoration_Completed THEN
    L_Observability_Valid := FALSE;
END_IF;

// Physical authority epoch coherence required.
IF L_Observability_Valid
AND NOT GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid THEN
    L_Observability_Valid := FALSE;
END_IF;

// Authority lineage continuity required.
IF L_Observability_Valid
AND NOT GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid THEN
    L_Observability_Valid := FALSE;
END_IF;

IF L_Observability_Valid THEN
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Authority_Valid := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Quarantine_Active := FALSE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Publication_Allowed := TRUE;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.HMI_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Diagnostics_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Blackbox_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Trend_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Alarm_Authority_Coherent := TRUE;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Epoch :=
        GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Epoch_Coherent := TRUE;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Last_Update_MS :=
        L_Now_MS;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Lease_Expired := FALSE;
ELSE
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Authority_Valid := FALSE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Quarantine_Active := TRUE;
    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Publication_Allowed := FALSE;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Lease_Expired := TRUE;

    GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Invalidation_Count :=
        GVL_OBSERVABILITY_AUTHORITY_FABRIC.Observability_Invalidation_Count + 1;
END_IF;

// Priority overrides after normal manager calculation:
// Evacuation > Fire > Security Alarm > Security Armed > Normal
IF GVL_STATE.G_Evacuation_Lighting_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        CASE GVL_STATE.G_Evac_Guidance[L_i] OF
            -1:
                GVL_STATE.G_Lighting_Levels[L_i] := 0;
            1:
                GVL_STATE.G_Lighting_Levels[L_i] := 100;
        ELSE
            IF GVL_LIGHTING_RUNTIME_BUFFER.B_Evac_Blink_On THEN
                GVL_STATE.G_Lighting_Levels[L_i] := 100;
            ELSE
                GVL_STATE.G_Lighting_Levels[L_i] := 0;
            END_IF;
        END_CASE;
    END_FOR;
ELSIF GVL_LIGHTING_RUNTIME_BUFFER.B_Fire_Alarm_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 100;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        GVL_STATE.G_Blinds_Positions[L_i] := 100;
    END_FOR;
ELSIF GVL_LIGHTING_RUNTIME_BUFFER.B_Security_Alarm THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 100;
    END_FOR;
ELSIF GVL_LIGHTING_RUNTIME_BUFFER.B_Security_Armed THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 0;
    END_FOR;
END_IF;

// Distributed execution/projection restriction.
// If manager execution or output projection is blocked, clear non-emergency lighting state
// so publication cannot reuse stale values from a previous scan.
IF (
        NOT GVL_LIGHTING_RUNTIME_BUFFER.B_Distributed_Execute_Allowed
        OR NOT GVL_LIGHTING_RUNTIME_BUFFER.B_Distributed_Projection_Allowed
   )
   AND NOT GVL_LIGHTING_RUNTIME_BUFFER.B_Emergency_Lighting_Override THEN

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        GVL_STATE.G_Blinds_Positions[L_i] := 100;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
        GVL_STATE.G_Socket_States[L_i] := FALSE;
    END_FOR;

END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Lighting_Phase_03_Priority_Restrictions <<<

// Critical deterministic water output runtime path.
// Must run every PLC scan while water projection is enabled.

fbWaterOutputProjector(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterOutputReconciliation(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterValveFeedback(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterPhysicalRuntime(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterRuntimeHardening(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterRecoveryRuntime(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

// >>> BULK_SYNC_ANCHOR: PRG_Water_Output_Projection_Phase_01_Runtime <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

GVL_COMMAND_VERIFY.Command_Mismatch_Count := 0;
GVL_COMMAND_VERIFY.Command_Match_OK := TRUE;
GVL_COMMAND_VERIFY.Command_Mismatch_Active := FALSE;

L_Runtime_Error := FALSE;
L_Runtime_Error_Code := 0;
L_Runtime_Error_Text := '';
L_Any_Manifold_Pump_On := FALSE;
L_Any_Vent_Fan_On := FALSE;

IF (NOT L_Runtime_Error) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF GVL_IO.DO_Zone_Valves[L_i] THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 10;
            L_Runtime_Error_Text := 'PLC inactive zone valve on';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Runtime_Error) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_IO.DO_Manifold_Pumps[L_i] THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 11;
            L_Runtime_Error_Text := 'PLC inactive pump on';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) AND (NOT GVL_IO.DO_Gas_Valve_Close) THEN
    L_Runtime_Error := TRUE;
    L_Runtime_Error_Code := 1;
    L_Runtime_Error_Text := 'Gas valve not closed';
END_IF;

IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF GVL_IO.AO_Supply_Fans[L_i] <> 0 THEN
            L_Any_Vent_Fan_On := TRUE;
        END_IF;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        IF GVL_IO.AO_Exhaust_Fans[L_i] <> 0 THEN
            L_Any_Vent_Fan_On := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Any_Vent_Fan_On THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 3;
        L_Runtime_Error_Text := 'Gas ventilation inactive';
    END_IF;
END_IF;

IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        IF GVL_IO.AO_Exhaust_Fans[L_i] = 0 THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 2;
            L_Runtime_Error_Text := 'Smoke exhaust not active';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF GVL_IO.AO_Supply_Fans[L_i] <> 0 THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 4;
            L_Runtime_Error_Text := 'Supply fan active in fire';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = WATER_LEAK) THEN
    IF GVL_COMMAND_SHADOW.G_Close_Valve_35 AND (NOT GVL_IO.DO_Water_Valve_35_Close) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 5;
        L_Runtime_Error_Text := 'Water valve 35 not closed';
    ELSIF GVL_COMMAND_SHADOW.G_Close_Valve_36 AND (NOT GVL_IO.DO_Water_Valve_36_Close) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 6;
        L_Runtime_Error_Text := 'Water valve 36 not closed';
    END_IF;
END_IF;

IF (NOT L_Runtime_Error) AND GVL_STATE.G_Safety_Freeze_Risk THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_IO.DO_Manifold_Pumps[L_i] THEN
            L_Any_Manifold_Pump_On := TRUE;
        END_IF;
    END_FOR;

    IF (NOT L_Any_Manifold_Pump_On) AND (NOT GVL_IO.DO_Backup_Circulation_Pump) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 7;
        L_Runtime_Error_Text := 'Freeze circulation inactive';
    END_IF;
END_IF;

IF (NOT L_Runtime_Error) AND GVL_STATE.G_Safety_Freeze_Risk AND GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop THEN
    IF GVL_IO.DO_DHW_Heating_Pump THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 8;
        L_Runtime_Error_Text := 'DHW heating active during gas freeze';
    END_IF;
END_IF;

IF L_Runtime_Error THEN
    GVL_COMMAND_VERIFY.Runtime_Sanity_OK := FALSE;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Code := L_Runtime_Error_Code;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Text := L_Runtime_Error_Text;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Time_MS := L_Now_MS;

    IF NOT L_Prev_Runtime_Error THEN
        GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count := GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count + 1;
        fbLog(
            VI_Event_Type := 1001,
            VI_Timestamp := L_Now_MS,
            VI_Param1 := L_Runtime_Error_Code,
            VI_Param2 := GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count
        );
    END_IF;
ELSE
    GVL_COMMAND_VERIFY.Runtime_Sanity_OK := TRUE;
END_IF;

L_Prev_Runtime_Error := L_Runtime_Error;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    fbDebounce_Switches[L_i](
        IN := GVL_IO.DI_Lighting_Switches[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );
    GVL_STATE.G_Physical_Switches[L_i] := fbDebounce_Switches[L_i].Q;

    fbDebounce_Motion[L_i](
        IN := GVL_IO.DI_Motion_Sensors[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );
    GVL_STATE.G_Motion_Sensors[L_i] := fbDebounce_Motion[L_i].Q;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    GVL_STATE.G_Socket_Switches[L_i] := GVL_IO.DI_Socket_Switches[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Discrete_01_Lighting_Sockets <<<

// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_A <<<

IF L_Init_Done THEN
    RETURN;
END_IF;

// ======================================================
// SYSTEM INIT VALIDATION
// ======================================================
// Performs one-shot base system configuration checks.
//
// This PRG may publish status text, but it must not mutate
// aggregated diagnostics fields directly. Diagnostics aggregate
// ownership is centralized in FB_System_Health_Orchestrator.
//
// Runtime operational command authority is owned by
// PRG_Command_Arbitration.
// ======================================================

L_Active_Zones_Count := GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits;

IF (L_Active_Zones_Count < 1) OR (L_Active_Zones_Count > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
    GVL_STATUS.G_System_Mode_Text := 'CONFIG ERROR: invalid active heating circuits';
    L_Active_Zones_Count := GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS;
END_IF;

FOR L_i := 1 TO L_Active_Zones_Count DO
    L_Zone_Index := GVL_CONFIG.G_Heating_Circuit_To_Zone[L_i];
    IF (L_Zone_Index < 1) OR (L_Zone_Index > GVL_CONSTANTS.C_MAX_ZONES) THEN
        GVL_STATUS.G_System_Mode_Text := CONCAT('CONFIG ERROR CIRCUIT ', INT_TO_STRING(L_i));
    END_IF;
END_FOR;

L_Init_Done := TRUE;

// >>> BULK_SYNC_ANCHOR: PRG_System_Init <<<

// SEMANTIC EXECUTION COLLAPSE PREVENTION
// DETERMINISTIC SEMANTIC SCHEDULING
// NON-INVASIVE / ADVISORY-FIRST

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Budget_Pressure_Observed THEN
    GVL_SEMANTIC_EXECUTION_CONTROL.Diagnostics_Execution_Path := DEFERRED_PATH;
    GVL_SEMANTIC_EXECUTION_CONTROL.Trend_Analytics_Execution_Path := BACKGROUND_PATH;
END_IF;

IF GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Depth_Limit_Reached THEN
    GVL_SEMANTIC_EXECUTION_CONTROL.Semantic_Chain_Depth_Limit_Reached := TRUE;
    GVL_SEMANTIC_EXECUTION_CONTROL.Semantic_Execution_Fragmentation_Risk := TRUE;
END_IF;

IF GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Verification_Chaining_Limit_Reached THEN
    GVL_SEMANTIC_EXECUTION_CONTROL.Verification_Fanout_Limit_Reached := TRUE;
    GVL_SEMANTIC_EXECUTION_CONTROL.Semantic_Cascade_Amplification_Risk := TRUE;
END_IF;

IF GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Observability_Amplification_Limit_Reached THEN
    GVL_SEMANTIC_EXECUTION_CONTROL.Observability_Fanout_Limit_Reached := TRUE;
END_IF;

IF GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Chronic_Degradation_Risk_Increasing THEN
    GVL_SEMANTIC_EXECUTION_CONTROL.Semantic_Complexity_Ceiling_Reached := TRUE;
    GVL_SEMANTIC_EXECUTION_CONTROL.Autonomous_Complexity_Ceiling_Enforced := TRUE;
END_IF;

// Critical execution paths remain immediate.
GVL_SEMANTIC_EXECUTION_CONTROL.Safety_Execution_Path := FAST_PATH;
GVL_SEMANTIC_EXECUTION_CONTROL.Physical_Verification_Path := FAST_PATH;

// PASSIVE CAUSAL NARRATIVE ENGINE
// HUMAN-READABLE SEMANTIC PROJECTION

GVL_CAUSAL_NARRATIVE_FABRIC.Narrative_Causality_Coherent :=
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Coherent;

GVL_CAUSAL_NARRATIVE_FABRIC.Narrative_Runtime_Alignment_Valid :=
