IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Validator_Interpretation_Equivalence_Valid THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 53013;
    L_Error_Text := 'Validator interpretation equivalence invalid';
END_IF;

IF L_Integrity_Valid THEN
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Valid := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Granted := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Quarantine_Active := FALSE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Validator_Semantics_Immutable := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.CrossEpoch_Validation_Equivalence_Stable := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Distributed_Validator_Consensus_Valid := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Rule_Integrity_Canonical := TRUE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Validator_Lineage_Coherent := TRUE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Epoch :=
        GVL_GOVERNANCE_FEEDBACK_INTEGRITY_FABRIC.Governance_Feedback_Integrity_Epoch;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Epoch_Coherent := TRUE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Last_Update_MS :=
        L_Now_MS;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Lease_Expired := FALSE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Last_Error_Code := 0;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Last_Error_Text := '';
ELSE
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Valid := FALSE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Granted := FALSE;
    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Quarantine_Active := TRUE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Lease_Expired := TRUE;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Last_Error_Code :=
        L_Error_Code;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Last_Error_Text :=
        L_Error_Text;

    GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Invalidation_Count :=
        GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_TIME_SERVICE.G_Now_MS;
L_Timeout_MS := GVL_CONSTANTS.C_MS_IN_SECOND * 10;
L_Any_Fault := FALSE;
L_Any_Close_Fault := FALSE;
L_Any_Open_Block := FALSE;
L_First_Close_Fault := 0;
L_First_Open_Block := 0;

GVL_WATER_VALVE_SERVICE.G_Last_Reset_Accepted := FALSE;
GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denied := FALSE;
GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denial_Code := 0;

IF GVL_WATER_VALVE_SERVICE.G_Reset_Confirm THEN
    IF GVL_INTENT_USER.I_User_Access_Level < 2 THEN
        GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denied := TRUE;
        GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denial_Code := 1;
        GVL_WATER_VALVE_SERVICE.G_Status_Text := 'Water valve reset denied: access level < 2';
    ELSE
        IF GVL_WATER_VALVE_SERVICE.G_Reset_All_Open_Blocks_Request THEN
            FOR L_i := 1 TO 8 DO
                GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[L_i] := FALSE;
                GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
                GVL_WATER_VALVE_SERVICE.G_Reset_Open_Block_Request[L_i] := FALSE;
            END_FOR;
            GVL_WATER_VALVE_SERVICE.G_Last_Reset_Accepted := TRUE;
            GVL_WATER_VALVE_SERVICE.G_Last_Reset_Valve_Index := 0;
            GVL_WATER_VALVE_SERVICE.G_Last_Reset_MS := L_Now_MS;
            GVL_WATER_VALVE_SERVICE.G_Status_Text := 'All water valve open blocks reset';
        ELSE
            FOR L_i := 1 TO 8 DO
                IF GVL_WATER_VALVE_SERVICE.G_Reset_Open_Block_Request[L_i] THEN
                    GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[L_i] := FALSE;
                    GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
                    GVL_WATER_VALVE_SERVICE.G_Reset_Open_Block_Request[L_i] := FALSE;
                    GVL_WATER_VALVE_SERVICE.G_Last_Reset_Accepted := TRUE;
                    GVL_WATER_VALVE_SERVICE.G_Last_Reset_Valve_Index := L_i;
                    GVL_WATER_VALVE_SERVICE.G_Last_Reset_MS := L_Now_MS;
                    GVL_WATER_VALVE_SERVICE.G_Status_Text := 'Water valve open block reset';
                END_IF;
            END_FOR;
        END_IF;

        IF NOT GVL_WATER_VALVE_SERVICE.G_Last_Reset_Accepted THEN
            GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denied := TRUE;
            GVL_WATER_VALVE_SERVICE.G_Last_Reset_Denial_Code := 2;
            GVL_WATER_VALVE_SERVICE.G_Status_Text := 'Water valve reset denied: no target';
        END_IF;
    END_IF;

    GVL_WATER_VALVE_SERVICE.G_Reset_All_Open_Blocks_Request := FALSE;
    GVL_WATER_VALVE_SERVICE.G_Reset_Confirm := FALSE;
END_IF;

FOR L_i := 1 TO 6 DO
    L_Open_Command[L_i] := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Open[L_i];
    L_Close_Command[L_i] := GVL_WATER_OUTPUT.DO_Water_Local_Valve_Close[L_i];
END_FOR;

L_Open_Command[7] := GVL_WATER_OUTPUT.DO_Water_Valve_35_Open;
L_Close_Command[7] := GVL_WATER_OUTPUT.DO_Water_Valve_35_Close;
L_Open_Command[8] := GVL_WATER_OUTPUT.DO_Water_Valve_36_Open;
L_Close_Command[8] := GVL_WATER_OUTPUT.DO_Water_Valve_36_Close;

FOR L_i := 1 TO 8 DO
    IF L_Open_Command[L_i] AND NOT L_Last_Open_Command[L_i] THEN
        L_Open_Start_MS[L_i] := L_Now_MS;
    END_IF;

    IF L_Close_Command[L_i] AND NOT L_Last_Close_Command[L_i] THEN
        L_Close_Start_MS[L_i] := L_Now_MS;
    END_IF;

    IF L_Open_Command[L_i] THEN
        IF GVL_STATE.G_Water_Zone_Open_FB[L_i] THEN
            GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
        ELSE
            IF L_Now_MS >= L_Open_Start_MS[L_i] THEN
                L_Elapsed_MS := L_Now_MS - L_Open_Start_MS[L_i];
            ELSE
                L_Elapsed_MS := (4294967295 - L_Open_Start_MS[L_i]) + L_Now_MS + 1;
            END_IF;

            IF L_Elapsed_MS >= L_Timeout_MS THEN
                GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := TRUE;
                GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[L_i] := TRUE;
            ELSE
                GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
            END_IF;
        END_IF;
    ELSE
        GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] := FALSE;
    END_IF;

    IF L_Close_Command[L_i] THEN
        IF GVL_STATE.G_Water_Zone_Close_FB[L_i] THEN
            GVL_STATUS.G_Diagnostics.Water_Zone_Close_Fault[L_i] := FALSE;
            GVL_STATUS.G_Diagnostics.Water_Zone_Critical_Close_Fault[L_i] := FALSE;
        ELSE
            IF L_Now_MS >= L_Close_Start_MS[L_i] THEN
                L_Elapsed_MS := L_Now_MS - L_Close_Start_MS[L_i];
            ELSE
                L_Elapsed_MS := (4294967295 - L_Close_Start_MS[L_i]) + L_Now_MS + 1;
            END_IF;
            GVL_STATUS.G_Diagnostics.Water_Zone_Close_Fault[L_i] := L_Elapsed_MS >= L_Timeout_MS;
            GVL_STATUS.G_Diagnostics.Water_Zone_Critical_Close_Fault[L_i] := L_Elapsed_MS >= L_Timeout_MS;
        END_IF;
    ELSE
        GVL_STATUS.G_Diagnostics.Water_Zone_Close_Fault[L_i] := FALSE;
        GVL_STATUS.G_Diagnostics.Water_Zone_Critical_Close_Fault[L_i] := FALSE;
    END_IF;

    IF GVL_STATUS.G_Diagnostics.Water_Zone_Open_Fault[L_i] OR GVL_STATUS.G_Diagnostics.Water_Zone_Close_Fault[L_i] THEN
        L_Any_Fault := TRUE;
    END_IF;

    IF GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[L_i] THEN
        L_Any_Open_Block := TRUE;
        IF L_First_Open_Block = 0 THEN
            L_First_Open_Block := L_i;
        END_IF;
    END_IF;

    IF GVL_STATUS.G_Diagnostics.Water_Zone_Critical_Close_Fault[L_i] THEN
        L_Any_Close_Fault := TRUE;
        IF L_First_Close_Fault = 0 THEN
            L_First_Close_Fault := L_i;
        END_IF;
    END_IF;

    L_Last_Open_Command[L_i] := L_Open_Command[L_i];
    L_Last_Close_Command[L_i] := L_Close_Command[L_i];
END_FOR;

GVL_STATUS.G_Diagnostics.Water_Open_Block_Active := L_Any_Open_Block;
GVL_STATUS.G_Diagnostics.Water_Close_Fault_Active := L_Any_Close_Fault;
GVL_STATUS.G_Diagnostics.Water_Main_Shutdown_Recommended := L_Any_Close_Fault;
GVL_STATUS.G_Diagnostics.Water_Localization_Failed := L_Any_Close_Fault;

IF L_Any_Open_Block THEN
    GVL_STATUS.G_Diagnostics.Water_Open_Block_Text := 'Water valve automatic opening blocked after open timeout';
ELSIF NOT L_Any_Fault THEN
    GVL_STATUS.G_Diagnostics.Water_Open_Block_Text := '';
END_IF;

IF L_Any_Close_Fault THEN
    GVL_STATUS.G_Diagnostics.Water_Close_Fault_Text := 'Water valve close feedback timeout';
    GVL_STATUS.G_Diagnostics.Water_Escalation_Text := 'Water close fault: common inlet fallback recommended';
    IF L_First_Close_Fault <= 6 THEN
        GVL_STATUS.G_Diagnostics.Water_Close_Fault_Zone_Name := 'Local water valve';
    ELSE
        GVL_STATUS.G_Diagnostics.Water_Close_Fault_Zone_Name := 'Common inlet valve';
    END_IF;
ELSIF NOT L_Any_Fault THEN
    GVL_STATUS.G_Diagnostics.Water_Close_Fault_Text := '';
    GVL_STATUS.G_Diagnostics.Water_Escalation_Text := '';
    GVL_STATUS.G_Diagnostics.Water_Close_Fault_Zone_Name := '';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Water_Valve_Diagnostics <<<

fbPolicy(
    VI_Zone_Occupied := GVL_PRESENCE.G_Zone_Occupied,
    VI_Zone_Last_Motion_TS := GVL_PRESENCE.G_Zone_Last_Motion_TS,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Zone_Permanent_Use := GVL_HEATING_POLICY.G_Zone_Permanent_Use,
    VI_Zone_Guest_Preheat := GVL_HEATING_POLICY.G_Zone_Guest_Preheat_Request,
    VI_Behavior_Mode := GVL_MODE.G_Current_Behavior_Mode
);

GVL_HEATING_POLICY.G_Zone_Empty_Duration_MS := fbPolicy.VO_Zone_Empty_Duration_MS;
GVL_HEATING_POLICY.G_Zone_Policy_Class := fbPolicy.VO_Zone_Policy_Class;
GVL_HEATING_POLICY.G_Zone_Target_Adjustment := fbPolicy.VO_Zone_Target_Adjustment;
GVL_HEATING_POLICY.G_Zone_Priority_Bias := fbPolicy.VO_Zone_Priority_Bias;

// Central time update point.
// Must run before PRG_IO_Read and all consumers of GVL_TIME_SERVICE.
fbTimebase();
fbTime();

// Step 4.2 compatibility bridge.
// Legacy consumers of GVL_STATUS.G_System_Time_MS receive the same canonical time.
GVL_STATUS.G_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_STATUS.G_Current_TOD := GVL_TIME_SERVICE.G_Current_TOD;
GVL_STATUS.G_Current_Day := TO_UINT(GVL_TIME_SERVICE.G_Day_Of_Week);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Operator_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Valid := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Granted := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Quarantine_Active := TRUE;

GVL_OPERATOR_SEMANTIC_ALIGNMENT.HMI_Semantic_State_Coherent := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Recovery_Intent_Aligned := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Alarm_Semantic_Priority_Coherent := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Runtime_Explanation_Coherent := FALSE;
GVL_OPERATOR_SEMANTIC_ALIGNMENT.Authority_State_Human_Visible := FALSE;

// Semantic preservation required.
IF NOT GVL_SEMANTIC_PRESERVATION_FABRIC.Semantic_Preservation_Granted THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40000;
    L_Error_Text := 'Semantic preservation authority not granted';
END_IF;

// Human-machine semantic split-brain detectors.
IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.HMI_Semantic_Lag_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40001;
    L_Error_Text := 'HMI semantic lag detected';
END_IF;

IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Interpretation_Skew_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40002;
    L_Error_Text := 'Operator interpretation skew detected';
END_IF;

IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.Alarm_Cognition_Mismatch_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40003;
    L_Error_Text := 'Alarm cognition mismatch detected';
END_IF;

IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.Hidden_Authority_State_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40004;
    L_Error_Text := 'Hidden authority state detected';
END_IF;

IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.Semantic_Explanation_Divergence_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40005;
    L_Error_Text := 'Semantic explanation divergence detected';
END_IF;

IF GVL_OPERATOR_SEMANTIC_ALIGNMENT.Human_Recovery_Misunderstanding_Detected THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40006;
    L_Error_Text := 'Human recovery misunderstanding detected';
END_IF;

// Operator cognition coherence validation.
IF L_Operator_Valid
AND NOT GVL_OPERATOR_SEMANTIC_ALIGNMENT.Human_Interpretation_Coherent THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40010;
    L_Error_Text := 'Human interpretation coherence invalid';
END_IF;

IF L_Operator_Valid
AND NOT GVL_OPERATOR_SEMANTIC_ALIGNMENT.Adaptive_Runtime_Visibility_Valid THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40011;
    L_Error_Text := 'Adaptive runtime visibility invalid';
END_IF;

IF L_Operator_Valid
AND NOT GVL_OPERATOR_SEMANTIC_ALIGNMENT.Semantic_Explanation_Fresh THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40012;
    L_Error_Text := 'Semantic explanation freshness invalid';
END_IF;

IF L_Operator_Valid
AND NOT GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Action_Context_Aligned THEN
    L_Operator_Valid := FALSE;
    L_Error_Code := 40013;
    L_Error_Text := 'Operator action context alignment invalid';
END_IF;

IF L_Operator_Valid THEN
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Valid := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Granted := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Quarantine_Active := FALSE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.HMI_Semantic_State_Coherent := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Recovery_Intent_Aligned := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Alarm_Semantic_Priority_Coherent := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Runtime_Explanation_Coherent := TRUE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Authority_State_Human_Visible := TRUE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Epoch :=
        GVL_SEMANTIC_PRESERVATION_FABRIC.Semantic_Preservation_Epoch;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Epoch_Coherent := TRUE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Last_Update_MS :=
        L_Now_MS;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Lease_Expired := FALSE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Last_Error_Code := 0;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Last_Error_Text := '';
ELSE
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Valid := FALSE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Granted := FALSE;
    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Semantic_Alignment_Quarantine_Active := TRUE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Lease_Expired := TRUE;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Last_Error_Code :=
        L_Error_Code;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Last_Error_Text :=
        L_Error_Text;

    GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Invalidation_Count :=
        GVL_OPERATOR_SEMANTIC_ALIGNMENT.Operator_Alignment_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;

IF GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Granted
AND NOT GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Unsafe_Recovery_Path_Detected
AND NOT GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Recovery_Path_Divergence_Detected
AND NOT GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Recovery_Causality_Break_Detected
AND NOT GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Distributed_Recovery_Fork_Detected THEN

    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Valid := TRUE;
    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Granted := TRUE;
    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Canonical := TRUE;
    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Recovery_Lineage_Causality_Valid := TRUE;
    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Recovery_Physical_Convergence_Stable := TRUE;
    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Recovery_Timeline_Monotonic := TRUE;

    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Epoch :=
        GVL_CROSSDOMAIN_FAILSAFE_CLOSURE_FABRIC.CrossDomain_FailSafe_Closure_Epoch;

    GVL_DETERMINISTIC_RECOVERY_PATH_FABRIC.Deterministic_Recovery_Path_Last_Update_MS :=
        L_Now_MS;
END_IF;

IF GVL_DISTRIBUTED_SAFETY_REALITY_CONSENSUS_FABRIC.Distributed_Safety_Reality_Consensus_Granted
AND NOT GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Fork_Detected
AND NOT GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Stale_Causality_Application_Detected
AND NOT GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Recovery_Before_Revocation_Detected
AND NOT GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Distributed_Timeline_Drift_Detected THEN

    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Closure_Valid := TRUE;
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Closure_Granted := TRUE;
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Coherent := TRUE;
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Monotonic_Reality_Timeline_Valid := TRUE;
    GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Recovery_Revocation_Ordering_Valid := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Integrity_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Valid := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Granted := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Quarantine_Active := TRUE;

GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Execution_Liveness_Stable := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Integrity_Governor_Scheduling_Canonical := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.CrossGovernor_Execution_Continuity_Valid := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Deterministic_Validation_Cycle_Integrity := FALSE;
GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Runtime_Liveness_Coherent := FALSE;

// Governance validator integrity required.
IF NOT GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Granted THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54000;
    L_Error_Text := 'Governance validator integrity not granted';
END_IF;

// Governance liveness degradation detectors.
IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Integrity_Governor_Starvation_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54001;
    L_Error_Text := 'Integrity governor starvation detected';
END_IF;

IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Validation_Cycle_Skip_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54002;
    L_Error_Text := 'Validation cycle skip detected';
END_IF;

IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.CrossGovernor_Execution_Jitter_Fork THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54003;
    L_Error_Text := 'Cross-governor execution jitter fork detected';
END_IF;

IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Selective_Governance_Degradation_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54004;
    L_Error_Text := 'Selective governance degradation detected';
END_IF;

IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Runtime_Governor_Execution_Stall_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54005;
    L_Error_Text := 'Runtime governor execution stall detected';
END_IF;

IF GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Distributed_Liveness_Reality_Fork_Detected THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54006;
    L_Error_Text := 'Distributed liveness reality fork detected';
END_IF;

// Governance liveness validation.
IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Validation_Cycle_Timing_Monotonic THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54010;
    L_Error_Text := 'Validation cycle timing invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Distributed_Governor_Execution_Aligned THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54011;
    L_Error_Text := 'Distributed governor execution alignment invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Runtime_Integrity_Causality_Grounded THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54012;
    L_Error_Text := 'Runtime integrity causality invalid';
END_IF;

IF L_Integrity_Valid
AND NOT GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Execution_Budget_Stable THEN
    L_Integrity_Valid := FALSE;
    L_Error_Code := 54013;
    L_Error_Text := 'Governance execution budget invalid';
END_IF;

IF L_Integrity_Valid THEN
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Valid := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Granted := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Quarantine_Active := FALSE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Execution_Liveness_Stable := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Integrity_Governor_Scheduling_Canonical := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.CrossGovernor_Execution_Continuity_Valid := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Deterministic_Validation_Cycle_Integrity := TRUE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Runtime_Liveness_Coherent := TRUE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Epoch :=
        GVL_GOVERNANCE_VALIDATOR_INTEGRITY_FABRIC.Governance_Validator_Integrity_Epoch;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Epoch_Coherent := TRUE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Last_Update_MS :=
        L_Now_MS;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Lease_Expired := FALSE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Last_Error_Code := 0;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Last_Error_Text := '';
ELSE
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Valid := FALSE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Granted := FALSE;
    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Quarantine_Active := TRUE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Lease_Expired := TRUE;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Last_Error_Code :=
        L_Error_Code;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Last_Error_Text :=
        L_Error_Text;

    GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Invalidation_Count :=
        GVL_GOVERNANCE_LIVENESS_INTEGRITY_FABRIC.Governance_Liveness_Integrity_Invalidation_Count + 1;
END_IF;

// ARCHITECTURAL CONSOLIDATION & RUNTIME COMPRESSION
// READ-ONLY / NON-INVASIVE

GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Runtime_Complexity_Pressure_Observed :=
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Governance_Saturation_Pressure_Observed;

GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Runtime_Cost_Observed :=
    GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Complexity_Pressure_Observed;

GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Verification_Induced_Instability_Risk :=
    GVL_SURVIVABILITY_INTELLIGENCE_FABRIC.Chronic_Degradation_Risk_Increasing;

IF GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Governance_Saturation_Observed THEN
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Scattering_Observed := TRUE;
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Semantic_Duplication_Observed := TRUE;
END_IF;

IF GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Runtime_Complexity_Pressure_Observed THEN
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Depth_Limit_Reached := TRUE;
END_IF;

IF GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Runtime_Cost_Observed THEN
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Verification_Chaining_Limit_Reached := TRUE;
END_IF;

IF GVL_OPERATIONAL_INTELLIGENCE_FABRIC.Operational_Opacity_Observed THEN
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Observability_Amplification_Limit_Reached := TRUE;
END_IF;

// Root distributed runtime execution chain.
//
// Execution order intentionally deterministic:
// safety -> discovery -> sessions -> authority -> replication
// -> transport -> ownership -> orchestration -> recovery locking
// -> unified execution gates -> cluster runtime FSM.
//
// Important convergence contract:
// execution gates must never reopen distributed execution authority
// before finalized convergence/publication continuity is achieved.
//
// Required finalized authority chain:
// immutable snapshot
// -> distributed reconciliation
// -> distributed commit continuity
// -> finalized publication validity
// -> convergence release
// -> execution gates reopen.

fbClusterSafetyBarrier(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbRuntimeDiscovery(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbRuntimeSessions(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbDistributedRuntimeContinuity(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbDistributedAuthority(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbRuntimeBusReplication(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbMQTTRuntimeAdapter(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbOPCUARuntimeAdapter(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbADSRuntimeAdapter(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbProjectionOwnership(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbDistributedOrchestration(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbRecoveryLock(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbExecutionGates(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbClusterRuntimeFSM(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Lineage_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid := FALSE;
GVL_AUTHORITY_LINEAGE.Warm_Restart_Continuity_Valid := FALSE;
GVL_AUTHORITY_LINEAGE.HA_Resume_Continuity_Valid := FALSE;
GVL_AUTHORITY_LINEAGE.Retained_State_Integrity_Valid := FALSE;

IF GVL_AUTHORITY_LINEAGE.Authority_Replay_Suspected THEN
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25000;
    L_Error_Text := 'Authority replay suspected';
END_IF;

IF L_Lineage_Valid AND GVL_AUTHORITY_LINEAGE.Retained_State_Skew_Detected THEN
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25001;
    L_Error_Text := 'Retained state skew detected';
END_IF;

IF L_Lineage_Valid AND GVL_AUTHORITY_LINEAGE.Partial_Authority_Resurrection_Detected THEN
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25002;
    L_Error_Text := 'Partial authority resurrection detected';
END_IF;

IF L_Lineage_Valid AND GVL_AUTHORITY_LINEAGE.Epoch_Lineage_Discontinuity_Detected THEN
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25003;
    L_Error_Text := 'Epoch lineage discontinuity detected';
END_IF;

IF L_Lineage_Valid
AND (ULINT_TO_UDINT(GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch) < GVL_AUTHORITY_LINEAGE.Last_Physical_Authority_Epoch) THEN
    GVL_AUTHORITY_LINEAGE.Authority_Replay_Suspected := TRUE;
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25010;
    L_Error_Text := 'Physical authority epoch rollback detected';
END_IF;

IF L_Lineage_Valid
AND (ULINT_TO_UDINT(GVL_RUNTIME_EPOCH.Runtime_Epoch) < GVL_AUTHORITY_LINEAGE.Last_Runtime_Epoch) THEN
    GVL_AUTHORITY_LINEAGE.Retained_State_Skew_Detected := TRUE;
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25011;
    L_Error_Text := 'Runtime epoch rollback detected';
END_IF;

IF L_Lineage_Valid
AND (ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch) < GVL_AUTHORITY_LINEAGE.Last_Output_Publication_Epoch) THEN
    GVL_AUTHORITY_LINEAGE.Partial_Authority_Resurrection_Detected := TRUE;
    L_Lineage_Valid := FALSE;
    L_Error_Code := 25012;
    L_Error_Text := 'Output publication epoch rollback detected';
END_IF;

IF L_Lineage_Valid THEN
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid := TRUE;
    GVL_AUTHORITY_LINEAGE.Warm_Restart_Continuity_Valid := TRUE;
    GVL_AUTHORITY_LINEAGE.HA_Resume_Continuity_Valid := TRUE;
    GVL_AUTHORITY_LINEAGE.Retained_State_Integrity_Valid := TRUE;

    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Epoch := ULINT_TO_UDINT(GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch);
    GVL_AUTHORITY_LINEAGE.Last_Physical_Authority_Epoch := ULINT_TO_UDINT(GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch);
    GVL_AUTHORITY_LINEAGE.Last_Runtime_Epoch := ULINT_TO_UDINT(GVL_RUNTIME_EPOCH.Runtime_Epoch);
    GVL_AUTHORITY_LINEAGE.Last_Output_Publication_Epoch := ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch);
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Last_Update_MS := L_Now_MS;
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Last_Error_Code := 0;
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Last_Error_Text := '';
ELSE
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid := FALSE;
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Last_Error_Code := L_Error_Code;
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Last_Error_Text := L_Error_Text;
    GVL_AUTHORITY_LINEAGE.Authority_Lineage_Invalidation_Count := GVL_AUTHORITY_LINEAGE.Authority_Lineage_Invalidation_Count + 1;
END_IF;

L_Movement_Timeout_MS := GVL_CONSTANTS.C_MS_IN_SECOND * 10;

GVL_HMI_WATER_TOPOLOGY.G_Active_Config_Version := GVL_Water_Topology_Config.G_Active_Config_Version;
