// Default to no gateway scenario request each scan.
// The gateway FB may override it through the VIO parameter.
L_Scenario_Req_Gateway := SCENARIO_NONE;

PRG_Alarm_Audible_Ack_Manager();

fbSystemAlarmOrchestrator(
    VI_First_Fault_Active := GVL_SYSTEM_HEALTH.G_First_Fault_Active,
    VI_First_Fault_Type := GVL_SYSTEM_HEALTH.G_First_Fault_Type,
    VI_First_Fault_Source := GVL_SYSTEM_HEALTH.G_First_Fault_Source
);

fbSystemGatewayIntent(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Gateway_Writes_Allowed := NOT GVL_STATUS.G_Diagnostics.Operator_Action_Blocked,
    VIO_FloorHeating_Temps := GVL_STATE.G_Floor_Temps,
    VIO_Zone_Valve_States := GVL_STATE.G_Zone_Valves,
    VIO_Lighting_Base_Levels := GVL_STATE.G_Lighting_Levels,
    VIO_Scenario_Req_Gateway := L_Scenario_Req_Gateway
);

GVL_INTENT_USER.I_Scenario_Request := L_Scenario_Req_Gateway;

GVL_DEBUG_VIEW.D_Current_Time_MS := GVL_TIME_SERVICE.G_Now_MS;

GVL_DEBUG_VIEW.D_Safety_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
GVL_DEBUG_VIEW.D_Safety_Active := (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> NORMAL);
GVL_DEBUG_VIEW.D_Recovery_Phase := GVL_SAFETY_RECOVERY.G_Recovery_Phase;
GVL_DEBUG_VIEW.D_Recovery_Active := GVL_SAFETY_RECOVERY.G_Recovery_Active;
GVL_DEBUG_VIEW.D_Recovery_Exit_Allowed := GVL_SAFETY_RECOVERY.G_Recovery_Exit_Allowed;
GVL_DEBUG_VIEW.D_Authority_Revocation_Active := GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active;
