GVL_DEBUG_VIEW.D_Main_Phase_Any_Skipped_By_Design := GVL_MAIN_PHASE_FEEDBACK.G_Any_Phase_Skipped_By_Design;
GVL_DEBUG_VIEW.D_Main_Phase_Status_Code := GVL_MAIN_PHASE_FEEDBACK.G_Status_Code;
GVL_DEBUG_VIEW.D_Main_Phase_Status_Text := GVL_MAIN_PHASE_FEEDBACK.G_Status_Text;

// DOMAIN EXECUTION POLICY SUMMARY -> DEBUG VIEW
GVL_DEBUG_VIEW.D_Domain_Policy_Any_Critical := GVL_DOMAIN_EXECUTION_POLICY.Any_Critical_Run;
GVL_DEBUG_VIEW.D_Domain_Policy_Any_Periodic := GVL_DOMAIN_EXECUTION_POLICY.Any_Periodic_Run;
GVL_DEBUG_VIEW.D_Domain_Policy_Any_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Any_Periodic_Due;
GVL_DEBUG_VIEW.D_Domain_Policy_Any_Idle := GVL_DOMAIN_EXECUTION_POLICY.Any_Idle_By_Design;
GVL_DEBUG_VIEW.D_Domain_Policy_Status_Code := GVL_DOMAIN_EXECUTION_POLICY.Status_Code;
GVL_DEBUG_VIEW.D_Domain_Policy_Status_Text := GVL_DOMAIN_EXECUTION_POLICY.Status_Text;

GVL_DEBUG_VIEW.D_Access_Mode := GVL_DOMAIN_EXECUTION_POLICY.Access_Mode;
GVL_DEBUG_VIEW.D_Access_Critical_Run := GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run;
GVL_DEBUG_VIEW.D_Access_Periodic_Run := GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Run;
GVL_DEBUG_VIEW.D_Access_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Due;
GVL_DEBUG_VIEW.D_Access_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Access_Idle_By_Design;

GVL_DEBUG_VIEW.D_Lighting_Mode := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Mode;
GVL_DEBUG_VIEW.D_Lighting_Critical_Run := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run;
GVL_DEBUG_VIEW.D_Lighting_Periodic_Run := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Run;
GVL_DEBUG_VIEW.D_Lighting_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Due;
GVL_DEBUG_VIEW.D_Lighting_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Lighting_Idle_By_Design;

GVL_DEBUG_VIEW.D_Water_Mode := GVL_DOMAIN_EXECUTION_POLICY.Water_Mode;
GVL_DEBUG_VIEW.D_Water_Critical_Run := GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run;
GVL_DEBUG_VIEW.D_Water_Periodic_Run := GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Run;
GVL_DEBUG_VIEW.D_Water_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Due;
GVL_DEBUG_VIEW.D_Water_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Water_Idle_By_Design;

GVL_DEBUG_VIEW.D_Heating_Mode := GVL_DOMAIN_EXECUTION_POLICY.Heating_Mode;
GVL_DEBUG_VIEW.D_Heating_Critical_Run := GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run;
GVL_DEBUG_VIEW.D_Heating_Periodic_Run := GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Run;
GVL_DEBUG_VIEW.D_Heating_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Due;
GVL_DEBUG_VIEW.D_Heating_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Heating_Idle_By_Design;

GVL_DEBUG_VIEW.D_Vent_Mode := GVL_DOMAIN_EXECUTION_POLICY.Vent_Mode;
GVL_DEBUG_VIEW.D_Vent_Critical_Run := GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run;
GVL_DEBUG_VIEW.D_Vent_Periodic_Run := GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Run;
GVL_DEBUG_VIEW.D_Vent_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Due;
GVL_DEBUG_VIEW.D_Vent_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Vent_Idle_By_Design;

GVL_DEBUG_VIEW.D_Simulation_Mode := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Mode;
GVL_DEBUG_VIEW.D_Simulation_Run_Allowed := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Run_Allowed;
GVL_DEBUG_VIEW.D_Simulation_Periodic_Due := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Periodic_Due;
GVL_DEBUG_VIEW.D_Simulation_Idle_By_Design := GVL_DOMAIN_EXECUTION_POLICY.Simulation_Idle_By_Design;

// DOMAIN EXECUTION VALIDATION SUMMARY -> DEBUG VIEW
GVL_DEBUG_VIEW.D_Domain_Validation_Executed := GVL_DOMAIN_EXECUTION_VALIDATION.G_Validation_Executed;
GVL_DEBUG_VIEW.D_Domain_Validation_Valid := GVL_DOMAIN_EXECUTION_VALIDATION.G_Validation_Valid;
GVL_DEBUG_VIEW.D_Domain_Validation_Any_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Any_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Domain_Validation_Any_Policy_Mismatch := GVL_DOMAIN_EXECUTION_VALIDATION.Any_Policy_Mismatch;
GVL_DEBUG_VIEW.D_Access_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Access_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Lighting_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Lighting_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Water_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Water_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Heating_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Heating_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Vent_Stale_Output_Risk := GVL_DOMAIN_EXECUTION_VALIDATION.Vent_Stale_Output_Risk;
GVL_DEBUG_VIEW.D_Domain_Validation_Status_Code := GVL_DOMAIN_EXECUTION_VALIDATION.Status_Code;
GVL_DEBUG_VIEW.D_Domain_Validation_Status_Text := GVL_DOMAIN_EXECUTION_VALIDATION.Status_Text;

// RUNTIME SCENARIO VALIDATION SUMMARY -> DEBUG VIEW
GVL_DEBUG_VIEW.D_Runtime_Scenario_Validation_Executed := GVL_RUNTIME_SCENARIO_VALIDATION.G_Validation_Executed;
GVL_DEBUG_VIEW.D_Runtime_Scenario_Validation_Valid := GVL_RUNTIME_SCENARIO_VALIDATION.G_Validation_Valid;
GVL_DEBUG_VIEW.D_Runtime_Scenario_Any_Context_Invalid := GVL_RUNTIME_SCENARIO_VALIDATION.Any_Context_Invalid;
GVL_DEBUG_VIEW.D_Runtime_Idle_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Idle_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Security_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Security_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Away_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Away_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Presence_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Presence_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Fire_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Fire_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Gas_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Gas_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Leak_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Leak_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Global_Stop_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Global_Stop_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Freeze_Context_Active := GVL_RUNTIME_SCENARIO_VALIDATION.Freeze_Context_Active;
GVL_DEBUG_VIEW.D_Runtime_Heating_Context_Valid := GVL_RUNTIME_SCENARIO_VALIDATION.Heating_Context_Valid;
GVL_DEBUG_VIEW.D_Runtime_Vent_Context_Valid := GVL_RUNTIME_SCENARIO_VALIDATION.Vent_Context_Valid;
GVL_DEBUG_VIEW.D_Runtime_Access_Context_Valid := GVL_RUNTIME_SCENARIO_VALIDATION.Access_Context_Valid;
GVL_DEBUG_VIEW.D_Runtime_Global_Stop_Context_Valid := GVL_RUNTIME_SCENARIO_VALIDATION.Global_Stop_Context_Valid;
GVL_DEBUG_VIEW.D_Runtime_Scenario_Status_Code := GVL_RUNTIME_SCENARIO_VALIDATION.Status_Code;
GVL_DEBUG_VIEW.D_Runtime_Scenario_Status_Text := GVL_RUNTIME_SCENARIO_VALIDATION.Status_Text;

// RUNTIME PHYSICAL IO VALIDATION SUMMARY -> DEBUG VIEW
GVL_DEBUG_VIEW.D_Runtime_IO_Validation_Executed := GVL_RUNTIME_IO_VALIDATION.G_Validation_Executed;
GVL_DEBUG_VIEW.D_Runtime_IO_Validation_Valid := GVL_RUNTIME_IO_VALIDATION.G_Validation_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Any_Invalid := GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid;
GVL_DEBUG_VIEW.D_Runtime_IO_Fire_Valid := GVL_RUNTIME_IO_VALIDATION.Fire_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Gas_Valid := GVL_RUNTIME_IO_VALIDATION.Gas_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Leak_Valid := GVL_RUNTIME_IO_VALIDATION.Leak_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Global_Stop_Valid := GVL_RUNTIME_IO_VALIDATION.Global_Stop_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Inactive_PLC_Valid := GVL_RUNTIME_IO_VALIDATION.Inactive_PLC_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Freeze_Valid := GVL_RUNTIME_IO_VALIDATION.Freeze_IO_Valid;
GVL_DEBUG_VIEW.D_Runtime_IO_Status_Code := GVL_RUNTIME_IO_VALIDATION.Status_Code;
GVL_DEBUG_VIEW.D_Runtime_IO_Status_Text := GVL_RUNTIME_IO_VALIDATION.Status_Text;

// SENSOR QUALITY → HMI
GVL_DEBUG_VIEW.D_Input_Source_Valid := GVL_INPUT.IN_Source_Valid;
GVL_DEBUG_VIEW.D_Input_Degraded := GVL_INPUT.IN_Input_Degraded;
GVL_DEBUG_VIEW.D_Sensor_Fault := GVL_INPUT.IN_Sensor_Fault;
GVL_DEBUG_VIEW.D_Validation_Failed := GVL_INPUT.IN_Validation_Failed;
GVL_DEBUG_VIEW.D_Anomaly_Detected := GVL_INPUT.IN_Anomaly_Detected;
GVL_DEBUG_VIEW.D_Validation_Reason := GVL_INPUT.IN_Validation_Reason;
GVL_DEBUG_VIEW.D_Anomaly_Reason := GVL_INPUT.IN_Anomaly_Reason;
GVL_DEBUG_VIEW.D_Last_Invalid_Zone := GVL_INPUT.IN_Last_Invalid_Zone;
GVL_DEBUG_VIEW.D_Min_Zone_Confidence := GVL_INPUT.IN_Min_Zone_Confidence;
GVL_DEBUG_VIEW.D_Worst_Zone := GVL_INPUT.IN_Worst_Zone;

GVL_DEBUG_VIEW.D_Adapt_Profile := GVL_BEHAVIOR_ADAPT.G_Adapt_Profile;

IF GVL_BEHAVIOR_ADAPT.G_Adapt_Profile = ADAPT_PROFILE_STABLE THEN
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'STABLE';
ELSIF GVL_BEHAVIOR_ADAPT.G_Adapt_Profile = ADAPT_PROFILE_BALANCED THEN
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'BALANCED';
ELSE
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'AGGRESSIVE';
END_IF;

L_MaxWeight := 0.0;
L_MinWeight := 9999.0;
GVL_DEBUG_VIEW.D_Main_VentBoost_Zone := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Weight := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight;
    IF L_Weight > L_MaxWeight THEN
        L_MaxWeight := L_Weight;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone := L_i;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone_Weight := L_Weight;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone_Confidence :=
            GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Confidence;
    END_IF;
    IF L_Weight < L_MinWeight THEN
        L_MinWeight := L_Weight;
    END_IF;
END_FOR;

GVL_DEBUG_VIEW.D_Max_VentBoost_Zone_Weight := L_MaxWeight;
GVL_DEBUG_VIEW.D_Min_VentBoost_Zone_Weight := L_MinWeight;

L_Index := GVL_TRACE.G_Trace_Write_Index - 1;
IF L_Index < 1 THEN
    L_Index := 200;
END_IF;

GVL_DEBUG_VIEW.D_Last_Trace_Text := GVL_TRACE.G_Trace_Buffer[L_Index].Text;
GVL_DEBUG_VIEW.D_Last_Trace_Time_MS := GVL_TRACE.G_Trace_Buffer[L_Index].Timestamp_MS;
GVL_DEBUG_VIEW.D_Last_Trace_Reason := GVL_TRACE.G_Trace_Buffer[L_Index].Reason_Code;

IF GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Recovery_Reactivation_Control_Granted
AND NOT GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Partial_Recovery_Authority_Leak
AND NOT GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Unsafe_Authority_Resurrection_Detected
AND NOT GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Resurrection_Authority_Fork_Detected THEN

    GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Authority_Resurrection_Boundary_Valid := TRUE;
    GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Authority_Resurrection_Bounded := TRUE;
    GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Authority_Recovery_Lineage_Stable := TRUE;
    GVL_AUTHORITY_RESURRECTION_BOUNDARY_FABRIC.Distributed_Authority_Recovery_Consensus := TRUE;
END_IF;

// BlackBox must record authoritative safety truth and latches,
// not stale alarm projection fields.
L_BB_Gas_Active := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_HEALTH_BRIDGE.G_CO_Alarm_Level OR GVL_STATE.G_Safety_Gas_Latched;
L_BB_Fire_Active := GVL_HEALTH_BRIDGE.G_Smoke_Detected OR GVL_STATE.G_Safety_Smoke_Latched;
L_BB_Flood_Active := GVL_HEALTH_BRIDGE.G_Leak_Detected OR GVL_STATE.G_Safety_Leak_Latched;

L_BB_Record.Timestamp := GVL_TIME_SERVICE.G_Now_MS;
L_BB_Record.PLC_Active_ID := GVL_STATUS.G_PLC_ID;
L_BB_Record.Gas_Methane_LEL := GVL_STATE.G_Methane_Sensors[1];
L_BB_Record.Gas_CO_PPM := GVL_STATE.G_CO_Sensors[1];
L_BB_Record.Flood_Active := L_BB_Flood_Active;
L_BB_Record.Fire_Active := L_BB_Fire_Active;

L_BB_Record.System_Mode := TO_BYTE(TO_INT(GVL_STATE.G_System_Mode));
L_BB_Record.First_Fault_Type := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Type);
L_BB_Record.First_Fault_Source := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
L_BB_Record.First_Fault_Active := GVL_SYSTEM_HEALTH.G_First_Fault_Active;
L_BB_Record.System_Severity := TO_BYTE(GVL_SYSTEM_HEALTH.G_System_Severity);
L_BB_Record.Root_Cause := TO_BYTE(GVL_SYSTEM_HEALTH.G_Root_Cause);
L_BB_Record.Watchdog_Fault := GVL_SYSTEM_HEALTH.G_Watchdog_Fault;

L_BB_Freeze := L_BB_Gas_Active OR L_BB_Fire_Active OR L_BB_Flood_Active OR GVL_SYSTEM_HEALTH.G_First_Fault_Active;

fbBlackBox(
    VI_Current_Data := L_BB_Record,
    VI_Freeze := L_BB_Freeze,
    VI_Reset := GVL_COMMAND.G_Reset_Errors
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Healthy := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_CONVERGENCE.Convergence_Runtime_Barrier_OK :=
    GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK
    AND GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed;

GVL_CONVERGENCE.Convergence_Runtime_Snapshot_OK :=
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected;

GVL_CONVERGENCE.Convergence_Distributed_Snapshot_OK :=
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent;

GVL_CONVERGENCE.Convergence_Distributed_Commit_OK :=
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired;

GVL_CONVERGENCE.Convergence_Semantic_Progress_OK :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active;

GVL_CONVERGENCE.Convergence_Output_Freshness_OK :=
    GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK
    AND GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay
    AND GVL_COMMAND_VERIFY.PreOutput_Barrier_OK
    AND NOT GVL_COMMAND_VERIFY.PreOutput_Block_IO;

// Epoch advancement freshness.
L_Epoch_Advancement_Healthy :=
    (GVL_SEMANTIC_PROGRESS.Semantic_Runtime_Barrier_Epoch -
     GVL_SEMANTIC_PROGRESS.Semantic_Last_Runtime_Barrier_Epoch) <= 2
    AND
    (GVL_SEMANTIC_PROGRESS.Semantic_Distributed_Commit_Epoch -
     GVL_SEMANTIC_PROGRESS.Semantic_Last_Distributed_Commit_Epoch) <= 2
    AND
    (GVL_SEMANTIC_PROGRESS.Semantic_Output_Publication_Epoch -
     GVL_SEMANTIC_PROGRESS.Semantic_Last_Output_Publication_Epoch) <= 2;

// Oscillation damping window.
L_Recent_Invalidation :=
    (L_Now_MS - GVL_CONVERGENCE.Convergence_Last_Invalidation_MS) < 30000;

IF NOT GVL_CONVERGENCE.Convergence_Runtime_Barrier_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18000;
    L_Error_Text := 'Runtime barrier convergence invalid';
END_IF;

IF L_Healthy AND NOT GVL_CONVERGENCE.Convergence_Runtime_Snapshot_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18001;
    L_Error_Text := 'Runtime snapshot convergence invalid';
END_IF;

IF L_Healthy AND NOT GVL_CONVERGENCE.Convergence_Distributed_Snapshot_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18002;
    L_Error_Text := 'Distributed snapshot convergence invalid';
END_IF;

IF L_Healthy AND NOT GVL_CONVERGENCE.Convergence_Distributed_Commit_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18003;
    L_Error_Text := 'Distributed commit convergence invalid';
END_IF;

IF L_Healthy AND NOT GVL_CONVERGENCE.Convergence_Semantic_Progress_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18004;
    L_Error_Text := 'Semantic progress convergence invalid';
END_IF;

IF L_Healthy AND NOT GVL_CONVERGENCE.Convergence_Output_Freshness_OK THEN
    L_Healthy := FALSE;
    L_Error_Code := 18005;
    L_Error_Text := 'Output freshness convergence invalid';
END_IF;

IF L_Healthy AND NOT L_Epoch_Advancement_Healthy THEN
    L_Healthy := FALSE;
    L_Error_Code := 18006;
    L_Error_Text := 'Epoch advancement freshness invalid';
END_IF;

IF L_Healthy AND L_Recent_Invalidation THEN
    L_Healthy := FALSE;
    L_Error_Code := 18007;
    L_Error_Text := 'Convergence oscillation damping active';
END_IF;

IF L_Healthy THEN
    GVL_CONVERGENCE.Convergence_Healthy_Observed := TRUE;

    GVL_CONVERGENCE.Recovery_Stable_Cycle_Count :=
        GVL_CONVERGENCE.Recovery_Stable_Cycle_Count + 1;

    IF GVL_CONVERGENCE.Convergence_Last_Healthy_MS = 0 THEN
        GVL_CONVERGENCE.Convergence_Last_Healthy_MS := L_Now_MS;
    END_IF;

    GVL_CONVERGENCE.Recovery_Stable_Time_MS :=
        L_Now_MS - GVL_CONVERGENCE.Convergence_Last_Healthy_MS;

    IF (GVL_CONVERGENCE.Recovery_Stable_Cycle_Count >= GVL_CONVERGENCE.Convergence_Min_Stable_Cycles)
    AND (GVL_CONVERGENCE.Recovery_Stable_Time_MS >= GVL_CONVERGENCE.Convergence_Min_Stable_Time_MS)
    THEN
        GVL_CONVERGENCE.Convergence_Lease_OK := TRUE;
        GVL_CONVERGENCE.Convergence_Release_Allowed := TRUE;
    ELSE
        GVL_CONVERGENCE.Convergence_Lease_OK := FALSE;
        GVL_CONVERGENCE.Convergence_Release_Allowed := FALSE;
    END_IF;

    GVL_CONVERGENCE.Convergence_Last_Error_Code := 0;
    GVL_CONVERGENCE.Convergence_Last_Error_Text := '';
ELSE
    GVL_CONVERGENCE.Convergence_Healthy_Observed := FALSE;

    GVL_CONVERGENCE.Recovery_Stable_Cycle_Count := 0;
    GVL_CONVERGENCE.Recovery_Stable_Time_MS := 0;

    GVL_CONVERGENCE.Convergence_Lease_OK := FALSE;
    GVL_CONVERGENCE.Convergence_Release_Allowed := FALSE;

    GVL_CONVERGENCE.Convergence_Last_Healthy_MS := 0;
    GVL_CONVERGENCE.Convergence_Last_Invalidation_MS := L_Now_MS;

    GVL_CONVERGENCE.Convergence_Invalidation_Count :=
        GVL_CONVERGENCE.Convergence_Invalidation_Count + 1;

    // Oscillation quarantine.
    IF GVL_CONVERGENCE.Convergence_Invalidation_Count > 5 THEN
        GVL_CONVERGENCE.Convergence_Oscillation_Quarantine_Active := TRUE;
    END_IF;

    GVL_CONVERGENCE.Convergence_Last_Error_Code := L_Error_Code;
    GVL_CONVERGENCE.Convergence_Last_Error_Text := L_Error_Text;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Control_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Valid := FALSE;
GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Granted := FALSE;
GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Quarantine_Active := TRUE;

GVL_CONTROL_TIMING_FABRIC.Loop_Sampling_Coherent := FALSE;
GVL_CONTROL_TIMING_FABRIC.Feedback_Freshness_Valid := FALSE;
GVL_CONTROL_TIMING_FABRIC.PID_Phase_Alignment_Valid := FALSE;
GVL_CONTROL_TIMING_FABRIC.Cross_Loop_Temporal_Stable := FALSE;
GVL_CONTROL_TIMING_FABRIC.Multi_Rate_Causality_Coherent := FALSE;

// Global authority synchronization required.
IF NOT GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Sync_Granted THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35000;
    L_Error_Text := 'Global authority synchronization not granted';
END_IF;

// Temporal aliasing detectors.
IF GVL_CONTROL_TIMING_FABRIC.PID_Phase_Skew_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35001;
    L_Error_Text := 'PID phase skew detected';
END_IF;

IF GVL_CONTROL_TIMING_FABRIC.Sampling_Window_Divergence_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35002;
    L_Error_Text := 'Sampling window divergence detected';
END_IF;

IF GVL_CONTROL_TIMING_FABRIC.Feedback_Freshness_Aliasing_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35003;
    L_Error_Text := 'Feedback freshness aliasing detected';
END_IF;

IF GVL_CONTROL_TIMING_FABRIC.Cross_Loop_Stabilization_Lag_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35004;
    L_Error_Text := 'Cross-loop stabilization lag detected';
END_IF;

IF GVL_CONTROL_TIMING_FABRIC.Multi_Rate_Oscillation_Risk_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35005;
    L_Error_Text := 'Multi-rate oscillation risk detected';
END_IF;

IF GVL_CONTROL_TIMING_FABRIC.Distributed_Control_Ringing_Detected THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35006;
    L_Error_Text := 'Distributed control ringing detected';
END_IF;

// Deterministic control timing validation.
IF L_Control_Valid
AND NOT GVL_CONTROL_TIMING_FABRIC.Control_Snapshot_Epoch_Coherent THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35010;
    L_Error_Text := 'Control snapshot epoch coherence invalid';
END_IF;

IF L_Control_Valid
AND NOT GVL_CONTROL_TIMING_FABRIC.Feedback_Window_Stable THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35011;
    L_Error_Text := 'Feedback window unstable';
END_IF;

IF L_Control_Valid
AND NOT GVL_CONTROL_TIMING_FABRIC.Loop_Execution_Phase_Stable THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35012;
    L_Error_Text := 'Loop execution phase unstable';
END_IF;

IF L_Control_Valid
AND NOT GVL_CONTROL_TIMING_FABRIC.Temporal_Observation_Aligned THEN
    L_Control_Valid := FALSE;
    L_Error_Code := 35013;
    L_Error_Text := 'Temporal observation alignment invalid';
END_IF;

IF L_Control_Valid THEN
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Valid := TRUE;
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Granted := TRUE;
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Quarantine_Active := FALSE;

    GVL_CONTROL_TIMING_FABRIC.Loop_Sampling_Coherent := TRUE;
    GVL_CONTROL_TIMING_FABRIC.Feedback_Freshness_Valid := TRUE;
    GVL_CONTROL_TIMING_FABRIC.PID_Phase_Alignment_Valid := TRUE;
    GVL_CONTROL_TIMING_FABRIC.Cross_Loop_Temporal_Stable := TRUE;
    GVL_CONTROL_TIMING_FABRIC.Multi_Rate_Causality_Coherent := TRUE;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Epoch :=
        GVL_GLOBAL_AUTHORITY_SYNC.Global_Authority_Epoch;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Epoch_Coherent := TRUE;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Last_Update_MS := L_Now_MS;
    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Lease_Expired := FALSE;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Last_Error_Code := 0;
    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Last_Error_Text := '';
ELSE
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Valid := FALSE;
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Granted := FALSE;
    GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Quarantine_Active := TRUE;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Lease_Expired := TRUE;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Last_Error_Code :=
        L_Error_Code;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Last_Error_Text :=
        L_Error_Text;

    GVL_CONTROL_TIMING_FABRIC.Control_Timing_Invalidation_Count :=
        GVL_CONTROL_TIMING_FABRIC.Control_Timing_Invalidation_Count + 1;
END_IF;

// Reset local output buffers at the beginning of every PRG call.
// This prevents stale publication when manager phases are skipped by governance.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Zone_Valves[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Manifold_Pumps[L_i] := FALSE;
    L_Manifold_Valves[L_i] := 0.0;
    L_Manifold_Status[L_i] := L_Empty_Manifold_Status;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    L_Boiler_OT_Enable[L_i] := FALSE;
    L_Boiler_OT_Setpoint[L_i] := 0.0;
    L_Boiler_Status[L_i] := L_Empty_Boiler_Status;
END_FOR;

L_Backup_Circulation_Pump := FALSE;
L_Electric_Heater_Enable := FALSE;
L_Freeze_Risk_Status := FALSE;
L_DHW_Heating_Pump := FALSE;
L_DHW_Circ_Pump := FALSE;
L_DHW_Status := L_Empty_DHW_Status;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    L_Boiler_Modulation_REAL[L_i] := TO_REAL(GVL_IO.AI_Boiler_Modulation[L_i]);
END_FOR;

L_Current_Hour := TO_UINT(GVL_TIME_SERVICE.G_Time_Of_Day_MS / 3600000);

L_Outdoor_Temp_Normalized := GVL_INPUT.IN_Outdoor_Temp;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Room_Temps_Normalized[L_i] := GVL_INPUT.IN_Room_Temps[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Floor_Temps_Normalized[L_i] := GVL_INPUT.IN_Floor_Temps[L_i];
END_FOR;

L_Heating_Emergency_Stop := GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop;
L_Heating_Gas_Safety_Stop := GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop OR GVL_STATE.G_Safety_Gas_Latched;

// Centralized distributed runtime governance.
// Freeze protection and gas safety semantics remain authoritative.
L_Distributed_Execute_Allowed :=
    GVL_Distributed_Execution_Gates.G_Can_Execute;

L_Distributed_Orchestrate_Allowed :=
    GVL_Distributed_Execution_Gates.G_Can_Orchestrate;

L_Distributed_Projection_Allowed :=
    GVL_Distributed_Execution_Gates.G_Can_Own_Projection;

L_Runtime_Context.Runtime_Enabled := TRUE;
L_Runtime_Context.Runtime_Ready := TRUE;
L_Runtime_Context.Runtime_Fault := FALSE;
L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_IDLE;

L_Runtime_Context.Allow_DHW_Phase :=
    L_Distributed_Execute_Allowed;

L_Runtime_Context.Allow_Heating_Phase :=
    L_Distributed_Orchestrate_Allowed;

L_Runtime_Context.Allow_Service_Gating_Phase := TRUE;
L_Runtime_Context.Allow_State_Publication_Phase := TRUE;
L_Runtime_Context.Allow_Diagnostics_Phase := TRUE;

L_Runtime_Context.Allow_Output_Projection_Phase :=
    L_Distributed_Projection_Allowed;

L_Runtime_Context.DHW_Executed := FALSE;
L_Runtime_Context.Heating_Executed := FALSE;
L_Runtime_Context.Service_Gating_Executed := FALSE;
L_Runtime_Context.State_Publication_Executed := FALSE;
L_Runtime_Context.Diagnostics_Executed := FALSE;
L_Runtime_Context.Output_Projection_Executed := FALSE;

L_Runtime_Context.DHW_Before_Heating_Valid := TRUE;
L_Runtime_Context.State_Publication_Before_Diagnostics_Valid := TRUE;
L_Runtime_Context.Output_Projection_Last_Valid := TRUE;

L_Runtime_Context.Diagnostics_Isolation_Valid := TRUE;
L_Runtime_Context.Explainability_Isolation_Valid := TRUE;
L_Runtime_Context.Safety_Isolation_Valid := TRUE;
L_Runtime_Context.OpenTherm_Ownership_Valid := TRUE;
L_Runtime_Context.Cascade_Ownership_Valid := TRUE;

IF NOT L_Distributed_Execute_Allowed THEN
    L_Runtime_Context.Runtime_Status_Code := 20;
    L_Runtime_Context.Runtime_Status_Text :=
        'Heating runtime blocked by distributed governance';
ELSE
    L_Runtime_Context.Runtime_Status_Code := 1;
    L_Runtime_Context.Runtime_Status_Text :=
        'Heating runtime nominal';
END_IF;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_IDLE;

fbObserverPhase(
    VI_Authorization_Stage := TRUE,
    VI_Finalization_Stage := FALSE,
    VI_Runtime_Context := L_Runtime_Context,
    VI_Diagnostics_Valid := TRUE
);

IF L_Distributed_Execute_Allowed THEN

    L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_DHW;

    fbDHWManager(
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Current_TOD := GVL_STATUS.G_Current_TOD,
        VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
        VI_Temp := GVL_STATE.G_DHW_Temp,
        VI_Pressure := GVL_STATE.G_DHW_Pressure,
        VI_Config := GVL_CONFIG.G_DHW_Config,
        VI_Current_Day_Of_Week := GVL_STATUS.G_Current_Day,
        VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
        VI_Reset_Errors := GVL_INTENT_USER.I_Reset_Errors,
        VI_Emergency_Stop := L_Heating_Emergency_Stop,
        VI_System_Mode := GVL_STATE.G_System_Mode,
        VO_Status => L_DHW_Status,
        VO_Heating_Pump => L_DHW_Heating_Pump,
        VO_Circ_Pump => L_DHW_Circ_Pump
    );

    L_Runtime_Context.DHW_Executed := TRUE;

END_IF;

IF L_Heating_Gas_Safety_Stop THEN
    L_DHW_Heating_Pump := FALSE;
    L_DHW_Status.Heating_Pump_On := FALSE;
END_IF;

IF L_Distributed_Orchestrate_Allowed THEN

    L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_HEATING;

    fbHeatingManager(
        VI_System_Mode := GVL_STATE.G_System_Mode,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
        VI_Outdoor_Temp := L_Outdoor_Temp_Normalized,
        VI_Config := GVL_CONFIG.G_Heating_Config,
        VI_Tariff := GVL_CONFIG.G_HMI_Tariff_Settings,
        VI_Current_Hour := L_Current_Hour,
        VI_DHW_Heating_Demand := L_DHW_Heating_Pump,
        VI_DHW_Target_Temp := GVL_CONFIG.G_DHW_Config.Target_Temp,
        VI_Emergency_Stop := L_Heating_Emergency_Stop,
        VI_Gas_Safety_Stop := L_Heating_Gas_Safety_Stop,
        VI_Boiler_Error_Status := GVL_STATE.G_Boiler_Error,
        VI_Boiler_OT_Online := GVL_STATE.G_Boiler_OT_Online,
        VI_Boiler_Modulation := L_Boiler_Modulation_REAL,
        VI_Floor_Temps := L_Floor_Temps_Normalized,
        VI_Room_Temps := L_Room_Temps_Normalized,
        VI_Manifold_Pressures := GVL_STATE.G_Manifold_Pressures,
        VI_Manifold_Currents := GVL_STATE.G_Manifold_Currents,
        VI_Manifold_Temps_Supply := GVL_STATE.G_Manifold_T_Supply,
        VI_Manifold_Temps_Return := GVL_STATE.G_Manifold_T_Return,
        VI_Boiler_Flame_Status := GVL_STATE.G_Boiler_Flame,
        VI_Zone_Configs := GVL_CONFIG.G_HMI_FloorHeating_Configs,
        VI_Rule_Actions := GVL_STATE.G_Rule_Actions,
        VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
        VI_Manifold_End_Switches := GVL_STATE.G_Manifold_End_Switches,
        VI_Valve_Test_Config := GVL_CONFIG.G_Valve_Test_Config,
        VO_Manifold_Valves => L_Manifold_Valves,
        VO_Manifold_Pumps => L_Manifold_Pumps,
        VO_Zone_Valves => L_Zone_Valves,
        VO_Boiler_OT_Enable => L_Boiler_OT_Enable,
        VO_Boiler_OT_Setpoint => L_Boiler_OT_Setpoint,
        VO_Backup_Circulation_Pump => L_Backup_Circulation_Pump,
        VO_Electric_Heater_Enable => L_Electric_Heater_Enable,
        VO_Freeze_Risk_Status => L_Freeze_Risk_Status,
        VO_Status => L_Manifold_Status,
        VO_Boiler_Status => L_Boiler_Status
    );

    L_Runtime_Context.Heating_Executed := TRUE;

END_IF;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_SERVICE_GATING;

fbServiceGatingPhase(
    VI_Enable := TRUE,
    VIO_Manifold_Pumps := L_Manifold_Pumps,
    VIO_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
    VIO_Electric_Heater_Enable := L_Electric_Heater_Enable,
    VIO_DHW_Heating_Pump := L_DHW_Heating_Pump,
    VIO_DHW_Circ_Pump := L_DHW_Circ_Pump,
    VIO_DHW_Status := L_DHW_Status,
    VIO_Freeze_Risk_Status := L_Freeze_Risk_Status
);

L_Runtime_Context.Service_Gating_Executed := fbServiceGatingPhase.VO_Executed;
L_Runtime_Context.Safety_Isolation_Valid := fbServiceGatingPhase.VO_Valid;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_STATE_PUBLICATION;

fbStatePublicationPhase(
    VI_Enable := TRUE,
    VI_Zone_Valves := L_Zone_Valves,
    VI_Manifold_Pumps := L_Manifold_Pumps,
    VI_Manifold_Valves := L_Manifold_Valves,
    VI_Boiler_OT_Enable := L_Boiler_OT_Enable,
    VI_Boiler_OT_Setpoint := L_Boiler_OT_Setpoint,
    VI_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
    VI_Electric_Heater_Enable := L_Electric_Heater_Enable,
    VI_Freeze_Risk_Status := L_Freeze_Risk_Status,
    VI_Manifold_Status := L_Manifold_Status,
    VI_Boiler_Status := L_Boiler_Status,
    VI_DHW_Heating_Pump := L_DHW_Heating_Pump,
    VI_DHW_Circ_Pump := L_DHW_Circ_Pump,
    VI_DHW_Status := L_DHW_Status
);

L_Runtime_Context.State_Publication_Executed := fbStatePublicationPhase.VO_Executed;
L_Runtime_Context.State_Publication_Before_Diagnostics_Valid := fbStatePublicationPhase.VO_Valid;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_DIAGNOSTICS;

fbDiagnosticsPhase(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Runtime_Context.Diagnostics_Executed := fbDiagnosticsPhase.VO_Executed;
L_Runtime_Context.Diagnostics_Isolation_Valid := fbDiagnosticsPhase.VO_Valid;

fbObserverPhase(
    VI_Authorization_Stage := FALSE,
    VI_Finalization_Stage := TRUE,
    VI_Runtime_Context := L_Runtime_Context,
    VI_Diagnostics_Valid := L_Runtime_Context.Diagnostics_Isolation_Valid
);

fbMetaSupervisionPublisher(
    VI_Enable := TRUE,
    VI_Runtime_Observation_Valid := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid,
    VI_Runtime_Observer_Ready := GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready,
    VI_Runtime_Observer_Fault := GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault,
    VI_Runtime_Status_Code := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code,
    VI_Runtime_Status_Text := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text
);

GVL_Heating_Runtime_Meta.G_Runtime_Meta_Supervision :=
    fbMetaSupervisionPublisher.VO_Meta;

GVL_Heating_Runtime_Meta.G_Runtime_Meta_Publication_Valid :=
    fbMetaSupervisionPublisher.VO_Publication_Valid;

GVL_Heating_Runtime_Meta.G_Runtime_Meta_Status_Code :=
    fbMetaSupervisionPublisher.VO_Meta.Status_Code;

GVL_Heating_Runtime_Meta.G_Runtime_Meta_Status_Text :=
    fbMetaSupervisionPublisher.VO_Meta.Status_Text;

fbExplainabilityPublisher(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Runtime_Context := L_Runtime_Context,
    VI_Runtime_Observation_Valid := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid,
    VI_Runtime_Observer_Fault := GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault,
    VI_Runtime_Status_Code := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code,
    VI_Runtime_Status_Text := GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text
);

GVL_Heating_Runtime_Explainability.G_Runtime_Phase_Event :=
    fbExplainabilityPublisher.VO_Phase_Event;

GVL_Heating_Runtime_Explainability.G_Runtime_Anomaly :=
    fbExplainabilityPublisher.VO_Anomaly;

GVL_Heating_Runtime_Explainability.G_Runtime_Blackbox_Event :=
    fbExplainabilityPublisher.VO_Blackbox_Event;

GVL_Heating_Runtime_Explainability.G_Runtime_Blackbox_Timeline :=
    fbExplainabilityPublisher.VO_Blackbox_Timeline;

GVL_Heating_Runtime_Explainability.G_Runtime_Event_Buffer :=
    fbExplainabilityPublisher.VO_Event_Buffer;

GVL_Heating_Runtime_Explainability.G_Runtime_Adaptive_Intelligence :=
    fbExplainabilityPublisher.VO_Adaptive_Intelligence;

GVL_Heating_Runtime_Explainability.G_Runtime_Causality_Graph :=
    fbExplainabilityPublisher.VO_Causality_Graph;

GVL_Heating_Runtime_Explainability.G_Runtime_Explainability_Publication_Valid :=
    fbExplainabilityPublisher.VO_Publication_Valid;

GVL_Heating_Runtime_Explainability.G_Runtime_Explainability_Status_Code :=
    fbExplainabilityPublisher.VO_Phase_Event.Status_Code;

GVL_Heating_Runtime_Explainability.G_Runtime_Explainability_Status_Text :=
    fbExplainabilityPublisher.VO_Phase_Event.Status_Text;

IF L_Distributed_Projection_Allowed THEN

    L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_OUTPUT_PROJECTION;

    fbOutputProjectionPhase(
        VI_Enable := TRUE,
        VI_Zone_Valves := L_Zone_Valves,
        VI_Manifold_Pumps := L_Manifold_Pumps,
        VI_Manifold_Valves := L_Manifold_Valves,
        VI_DHW_Heating_Pump := L_DHW_Heating_Pump,
        VI_DHW_Circ_Pump := L_DHW_Circ_Pump,
        VI_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
        VI_Electric_Heater_Enable := L_Electric_Heater_Enable
    );

    L_Runtime_Context.Output_Projection_Executed :=
        fbOutputProjectionPhase.VO_Executed;

    L_Runtime_Context.Output_Projection_Last_Valid :=
        fbOutputProjectionPhase.VO_Valid;

END_IF;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_COMPLETE;

// >>> BULK_SYNC_ANCHOR: PRG_Heating <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Semantic_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Valid := FALSE;
GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Granted := FALSE;
GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Quarantine_Active := TRUE;

GVL_SEMANTIC_CONTINUITY.Operator_Intent_Coherent := FALSE;
GVL_SEMANTIC_CONTINUITY.Policy_Intent_Coherent := FALSE;
GVL_SEMANTIC_CONTINUITY.Adaptive_Behavior_Coherent := FALSE;
GVL_SEMANTIC_CONTINUITY.Recovery_Intent_Coherent := FALSE;
GVL_SEMANTIC_CONTINUITY.Distributed_Semantic_Coherent := FALSE;

// Runtime resource authority required.
IF NOT GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Granted THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31000;
    L_Error_Text := 'Runtime resource authority not granted';
END_IF;

// Semantic drift detectors.
IF GVL_SEMANTIC_CONTINUITY.Goal_Drift_Detected THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31001;
    L_Error_Text := 'Goal drift detected';
END_IF;

IF GVL_SEMANTIC_CONTINUITY.Policy_Divergence_Detected THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31002;
    L_Error_Text := 'Policy divergence detected';
END_IF;

IF GVL_SEMANTIC_CONTINUITY.Adaptive_Learning_Semantic_Skew THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31003;
    L_Error_Text := 'Adaptive semantic skew detected';
END_IF;

IF GVL_SEMANTIC_CONTINUITY.Recovery_Intent_Mismatch_Detected THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31004;
    L_Error_Text := 'Recovery intent mismatch detected';
END_IF;

IF GVL_SEMANTIC_CONTINUITY.Optimization_Authority_Corruption_Detected THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31005;
    L_Error_Text := 'Optimization authority corruption detected';
END_IF;

IF GVL_SEMANTIC_CONTINUITY.Distributed_Semantic_Fragmentation_Detected THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31006;
    L_Error_Text := 'Distributed semantic fragmentation detected';
END_IF;

// Intent continuity validation.
IF L_Semantic_Valid
AND NOT GVL_SEMANTIC_CONTINUITY.Declared_System_Intent_Valid THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31010;
    L_Error_Text := 'Declared system intent invalid';
END_IF;

IF L_Semantic_Valid
AND NOT GVL_SEMANTIC_CONTINUITY.Runtime_Goal_Alignment_Valid THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31011;
    L_Error_Text := 'Runtime goal alignment invalid';
END_IF;

IF L_Semantic_Valid
AND NOT GVL_SEMANTIC_CONTINUITY.Optimization_Boundary_Valid THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31012;
    L_Error_Text := 'Optimization boundary invalid';
END_IF;

IF L_Semantic_Valid
AND NOT GVL_SEMANTIC_CONTINUITY.Autonomous_Adjustment_Valid THEN
    L_Semantic_Valid := FALSE;
    L_Error_Code := 31013;
    L_Error_Text := 'Autonomous adjustment invalid';
END_IF;

IF L_Semantic_Valid THEN
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Valid := TRUE;
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Granted := TRUE;
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Quarantine_Active := FALSE;

    GVL_SEMANTIC_CONTINUITY.Operator_Intent_Coherent := TRUE;
    GVL_SEMANTIC_CONTINUITY.Policy_Intent_Coherent := TRUE;
    GVL_SEMANTIC_CONTINUITY.Adaptive_Behavior_Coherent := TRUE;
    GVL_SEMANTIC_CONTINUITY.Recovery_Intent_Coherent := TRUE;
    GVL_SEMANTIC_CONTINUITY.Distributed_Semantic_Coherent := TRUE;

    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Epoch :=
        GVL_RUNTIME_RESOURCE_AUTHORITY.Runtime_Resource_Authority_Epoch;

    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Epoch_Coherent := TRUE;

    GVL_SEMANTIC_CONTINUITY.Semantic_Last_Update_MS := L_Now_MS;
    GVL_SEMANTIC_CONTINUITY.Semantic_Lease_Expired := FALSE;

    GVL_SEMANTIC_CONTINUITY.Semantic_Last_Error_Code := 0;
    GVL_SEMANTIC_CONTINUITY.Semantic_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Valid := FALSE;
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Granted := FALSE;
    GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Quarantine_Active := TRUE;

    GVL_SEMANTIC_CONTINUITY.Semantic_Lease_Expired := TRUE;

    GVL_SEMANTIC_CONTINUITY.Semantic_Last_Error_Code :=
        L_Error_Code;

    GVL_SEMANTIC_CONTINUITY.Semantic_Last_Error_Text :=
        L_Error_Text;

    GVL_SEMANTIC_CONTINUITY.Semantic_Invalidation_Count :=
        GVL_SEMANTIC_CONTINUITY.Semantic_Invalidation_Count + 1;
END_IF;

L_Now := GVL_TIME_SERVICE.G_Now_MS;
L_Last := GVL_DIAGNOSTICS_EXT.G_Last_Update_Time;

// ===============================
// CYCLE INTERVAL MEASUREMENT
// ===============================
IF L_Last = 0 THEN
    L_Cycle_MS := GVL_DIAGNOSTICS_EXT.G_Cycle_Expected_MS;
ELSE
    IF L_Now >= L_Last THEN
        L_Cycle_MS := L_Now - L_Last;
    ELSE
        L_Cycle_MS := (4294967295 - L_Last) + L_Now + 1;
    END_IF;
END_IF;

GVL_DIAGNOSTICS_EXT.G_Last_Update_Time := L_Now;
GVL_DIAGNOSTICS_EXT.G_Cycle_Last_MS := L_Cycle_MS;

// min/max
IF (GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS = 0) OR (L_Cycle_MS < GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS) THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS := L_Cycle_MS;
END_IF;

IF L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Max_MS THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Max_MS := L_Cycle_MS;
END_IF;

// average (incremental)
GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count + 1;
GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS :=
    GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS +
    (UDINT_TO_REAL(L_Cycle_MS) - GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS) /
    UDINT_TO_REAL(GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count);

// ===============================
// OVERRUN / CRITICAL DETECTION
// ===============================
GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active := (L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Warning_MS);
GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active := (L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_MS);

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count + 1;
    GVL_DIAGNOSTICS_EXT.G_Cycle_Last_Overrun_MS := L_Cycle_MS;
    GVL_DIAGNOSTICS_EXT.G_Cycle_Last_Overrun_Time_MS := L_Now;
END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count + 1;
END_IF;

// edge logging
IF GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active AND NOT L_Prev_Overrun THEN
    fbLog(
        VI_Event_Type := 2001,
        VI_Timestamp := L_Now,
        VI_Param1 := L_Cycle_MS,
        VI_Param2 := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count
    );
END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active AND NOT L_Prev_Critical THEN
    fbLog(
        VI_Event_Type := 2002,
        VI_Timestamp := L_Now,
        VI_Param1 := L_Cycle_MS,
        VI_Param2 := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count
    );
END_IF;

L_Prev_Overrun := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active;
L_Prev_Critical := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active;

// ===============================
// EXISTING HEALTH LOGIC
// ===============================
IF L_Last = 0 THEN
    L_Delta_Time := 0.1;
ELSE
    L_Delta_Time := UDINT_TO_REAL(L_Cycle_MS) / 1000.0;
END_IF;

L_Error_Heating := GVL_STATE.G_Heating_Subsystem_Degraded;

// Extended diagnostics must use authoritative safety truth and latches,
// not stale projected GVL_STATE.G_Safety_*_Alarm compatibility fields.
L_Error_Safety :=
    GVL_HEALTH_BRIDGE.G_Gas_Detected OR
    GVL_HEALTH_BRIDGE.G_CO_Alarm_Level OR
    GVL_HEALTH_BRIDGE.G_Leak_Detected OR
    GVL_HEALTH_BRIDGE.G_Smoke_Detected OR
    GVL_STATE.G_Safety_Gas_Latched OR
    GVL_STATE.G_Safety_Leak_Latched OR
    GVL_STATE.G_Safety_Smoke_Latched;

L_Error_IO := GVL_STATE.G_Heating_IO_Fault;

IF L_Error_Heating THEN
    IF NOT L_Prev_Error_Heating THEN
        GVL_DIAGNOSTICS_EXT.G_Error_Count_Heating := GVL_DIAGNOSTICS_EXT.G_Error_Count_Heating + 1;
    END_IF;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_Heating := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_Heating := GVL_DIAGNOSTICS_EXT.G_Health_Heating - (0.5 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_Heating := GVL_DIAGNOSTICS_EXT.G_Health_Heating + (0.1 * L_Delta_Time);
END_IF;

IF L_Error_Safety THEN
    IF NOT L_Prev_Error_Safety THEN
        GVL_DIAGNOSTICS_EXT.G_Error_Count_Safety := GVL_DIAGNOSTICS_EXT.G_Error_Count_Safety + 1;
    END_IF;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_Safety := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_Safety := GVL_DIAGNOSTICS_EXT.G_Health_Safety - (1.0 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_Safety := GVL_DIAGNOSTICS_EXT.G_Health_Safety + (0.2 * L_Delta_Time);
END_IF;

IF L_Error_IO THEN
    IF NOT L_Prev_Error_IO THEN
        GVL_DIAGNOSTICS_EXT.G_Error_Count_IO := GVL_DIAGNOSTICS_EXT.G_Error_Count_IO + 1;
    END_IF;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_IO := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_IO := GVL_DIAGNOSTICS_EXT.G_Health_IO - (0.5 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_IO := GVL_DIAGNOSTICS_EXT.G_Health_IO + (0.1 * L_Delta_Time);
END_IF;

L_Prev_Error_Heating := L_Error_Heating;
L_Prev_Error_Safety := L_Error_Safety;
L_Prev_Error_IO := L_Error_IO;

// clamp
IF GVL_DIAGNOSTICS_EXT.G_Health_Heating < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Heating := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_Heating > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Heating := 1.0; END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Health_Safety < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Safety := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_Safety > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Safety := 1.0; END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Health_IO < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_IO := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_IO > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_IO := 1.0; END_IF;

// ======================================================
// HA SESSION REPLICATION
// ======================================================
// Dedicated HA/session replication boundary.
//
// Purpose:
// replicate canonical peer-session state through isolated
// HA replication surface.
//
// Current implementation:
// bounded loopback foundation.
//
// Future implementations may replace this with:
// - SysCom HA channel
// - shared-memory replication
// - dedicated Ethernet HA link
// - deterministic fieldbus synchronization
//
// without changing distributed governors.
// ======================================================

IF NOT GVL_HA_SESSION_REPLICATION.HA_Replication_Enabled THEN
    GVL_HA_SESSION_REPLICATION.HA_Channel_Healthy := FALSE;
    RETURN;
END_IF;

// ------------------------------------------------------
// Canonical session export replication.
// ------------------------------------------------------

GVL_HA_SESSION_REPLICATION.HA_Remote_Session_Valid :=
    GVL_PEER_SESSION.Remote_Session_Valid;

GVL_HA_SESSION_REPLICATION.HA_Remote_Last_Refresh_MS :=
    GVL_PEER_SESSION.Remote_Last_Refresh_MS;

GVL_HA_SESSION_REPLICATION.HA_Remote_Runtime_Epoch :=
    GVL_PEER_SESSION.Remote_Runtime_Epoch;

GVL_HA_SESSION_REPLICATION.HA_Remote_Snapshot_Epoch :=
    GVL_PEER_SESSION.Remote_Snapshot_Epoch;

GVL_HA_SESSION_REPLICATION.HA_Remote_Boot_Generation :=
    GVL_PEER_SESSION.Remote_Boot_Generation;

GVL_HA_SESSION_REPLICATION.HA_Remote_Fencing_Token :=
    GVL_PEER_SESSION.Remote_Fencing_Token;

GVL_HA_SESSION_REPLICATION.HA_Remote_Publication_Allowed :=
    GVL_PEER_SESSION.Remote_Publication_Allowed;

GVL_HA_SESSION_REPLICATION.HA_Remote_Runtime_Healthy :=
    GVL_PEER_SESSION.Remote_Runtime_Healthy;

GVL_HA_SESSION_REPLICATION.HA_Last_TX_MS :=
    GVL_STATUS.G_System_Time_MS;

GVL_HA_SESSION_REPLICATION.HA_Last_RX_MS :=
    GVL_STATUS.G_System_Time_MS;

GVL_HA_SESSION_REPLICATION.HA_Channel_Healthy := TRUE;

// >>> BULK_SYNC_ANCHOR: PRG_HA_Session_Replication <<<

GVL_RUNTIME_IO_VALIDATION.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_RUNTIME_IO_VALIDATION.G_Validation_Executed := TRUE;
GVL_RUNTIME_IO_VALIDATION.G_Validation_Valid := TRUE;

L_Any_Exhaust_On := FALSE;
L_Any_Supply_On := FALSE;
L_Any_Heating_Output_On := FALSE;
L_Any_Water_Zone_On := FALSE;
L_Any_Access_Output_On := FALSE;
L_Any_Lighting_Output_On := FALSE;
L_Any_Socket_On := FALSE;
L_Any_Freeze_Circulation_On := FALSE;
L_Fire_Access_Valid := TRUE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    IF GVL_IO.AO_Exhaust_Fans[L_i] > 0 THEN
        L_Any_Exhaust_On := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    IF GVL_IO.AO_Supply_Fans[L_i] > 0 THEN
        L_Any_Supply_On := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF GVL_IO.DO_Zone_Valves[L_i] THEN
        L_Any_Heating_Output_On := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_IO.DO_Manifold_Pumps[L_i] OR (GVL_IO.AO_Manifold_Valves[L_i] > 0) THEN
        L_Any_Heating_Output_On := TRUE;
        L_Any_Freeze_Circulation_On := TRUE;
    END_IF;
END_FOR;

IF GVL_IO.DO_DHW_Heating_Pump
   OR GVL_IO.DO_DHW_Circ_Pump
   OR GVL_IO.DO_Backup_Circulation_Pump
   OR GVL_IO.DO_Electric_Heater_Enable THEN
    L_Any_Heating_Output_On := TRUE;
END_IF;

IF GVL_IO.DO_Backup_Circulation_Pump THEN
    L_Any_Freeze_Circulation_On := TRUE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    IF GVL_IO.DO_Water_Zone_Enable[L_i] THEN
        L_Any_Water_Zone_On := TRUE;
    END_IF;
END_FOR;

L_Any_Access_Output_On :=
    GVL_IO.DO_Gate_Open
    OR GVL_IO.DO_Wicket_Open
    OR GVL_IO.DO_Lock_1_Open
    OR GVL_IO.DO_Lock_1_Close
    OR GVL_IO.DO_Lock_2_Open
    OR GVL_IO.DO_Lock_2_Close;

IF GVL_COMMAND_SHADOW.G_Lock_1_Open AND NOT GVL_IO.DO_Lock_1_Open THEN
    L_Fire_Access_Valid := FALSE;
END_IF;
IF GVL_COMMAND_SHADOW.G_Lock_2_Open AND NOT GVL_IO.DO_Lock_2_Open THEN
    L_Fire_Access_Valid := FALSE;
END_IF;
IF GVL_COMMAND_SHADOW.G_Gate_Open AND NOT GVL_IO.DO_Gate_Open THEN
    L_Fire_Access_Valid := FALSE;
END_IF;
IF GVL_COMMAND_SHADOW.G_Wicket_Open AND NOT GVL_IO.DO_Wicket_Open THEN
    L_Fire_Access_Valid := FALSE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    IF GVL_IO.AO_Lighting_Levels[L_i] > 0 THEN
        L_Any_Lighting_Output_On := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    IF GVL_IO.DO_Sockets[L_i] THEN
        L_Any_Socket_On := TRUE;
    END_IF;
END_FOR;

GVL_RUNTIME_IO_VALIDATION.Fire_IO_Valid :=
    (NOT GVL_STATUS.G_Is_Active_PLC)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> FIRE)
    OR (
        L_Any_Exhaust_On
        AND NOT L_Any_Supply_On
        AND L_Fire_Access_Valid
    );

GVL_RUNTIME_IO_VALIDATION.Gas_IO_Valid :=
    (NOT GVL_STATUS.G_Is_Active_PLC)
    OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> GAS)
    OR (
        GVL_IO.DO_Gas_Valve_Close
        AND (L_Any_Exhaust_On OR L_Any_Supply_On)
        AND NOT GVL_IO.DO_DHW_Heating_Pump
    );

GVL_RUNTIME_IO_VALIDATION.Leak_IO_Valid :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> WATER_LEAK)
    OR (
        GVL_IO.DO_Water_Valve_35_Close
        AND GVL_IO.DO_Water_Valve_36_Close
    );

GVL_RUNTIME_IO_VALIDATION.Global_Stop_IO_Valid :=
    (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> GLOBAL_STOP)
    OR (
        NOT L_Any_Heating_Output_On
        AND NOT L_Any_Exhaust_On
        AND NOT L_Any_Supply_On
        AND NOT L_Any_Water_Zone_On
        AND NOT L_Any_Access_Output_On
        AND NOT L_Any_Lighting_Output_On
        AND NOT L_Any_Socket_On
        AND GVL_IO.DO_Water_Valve_35_Close
        AND GVL_IO.DO_Water_Valve_36_Close
        AND GVL_IO.DO_Gas_Valve_Close
    );

GVL_RUNTIME_IO_VALIDATION.Inactive_PLC_IO_Valid :=
    GVL_STATUS.G_Is_Active_PLC
    OR (
        NOT L_Any_Heating_Output_On
        AND NOT L_Any_Exhaust_On
        AND NOT L_Any_Supply_On
        AND NOT L_Any_Water_Zone_On
        AND NOT L_Any_Access_Output_On
        AND NOT L_Any_Lighting_Output_On
        AND NOT L_Any_Socket_On
        AND GVL_IO.DO_Water_Valve_35_Close
        AND GVL_IO.DO_Water_Valve_36_Close
        AND GVL_IO.DO_Gas_Valve_Close
    );

GVL_RUNTIME_IO_VALIDATION.Freeze_IO_Valid :=
    (NOT GVL_STATUS.G_Is_Active_PLC)
    OR (NOT GVL_STATE.G_Safety_Freeze_Risk)
    OR L_Any_Freeze_Circulation_On;

GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid :=
    NOT GVL_RUNTIME_IO_VALIDATION.Fire_IO_Valid
    OR NOT GVL_RUNTIME_IO_VALIDATION.Gas_IO_Valid
    OR NOT GVL_RUNTIME_IO_VALIDATION.Leak_IO_Valid
    OR NOT GVL_RUNTIME_IO_VALIDATION.Global_Stop_IO_Valid
    OR NOT GVL_RUNTIME_IO_VALIDATION.Inactive_PLC_IO_Valid
    OR NOT GVL_RUNTIME_IO_VALIDATION.Freeze_IO_Valid;

IF GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid THEN
    GVL_RUNTIME_IO_VALIDATION.G_Validation_Valid := FALSE;
    GVL_RUNTIME_IO_VALIDATION.Status_Code := 1;
    GVL_RUNTIME_IO_VALIDATION.Status_Text := 'Runtime physical IO validation mismatch';
ELSE
    GVL_RUNTIME_IO_VALIDATION.Status_Code := 0;
    GVL_RUNTIME_IO_VALIDATION.Status_Text := 'Runtime physical IO validation nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Runtime_IO_Validation <<<

FB_Backend(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbMode(
    VI_Is_Night := GVL_STATUS.G_Is_Night,
    VI_Away_Request := GVL_MODE.G_Away_Request OR GVL_PRESENCE.G_Auto_Away_Request,
    VI_Maintenance_Request := GVL_MODE.G_Maintenance_Request,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

GVL_MODE.G_Current_Behavior_Mode := fbMode.VO_Mode;
GVL_MODE.G_Mode_Code := fbMode.VO_Mode_Code;

IF L_Last_Mode <> fbMode.VO_Mode THEN
    GVL_MODE.G_Mode_Last_Change_TS := GVL_STATUS.G_System_Time_MS;
    L_Last_Mode := fbMode.VO_Mode;
END_IF;

// ==============================================================================
// FILE ARCHIVE HMI APPLICATOR — validates HMI intent and updates archive runtime.
// ==============================================================================
// HMI is not allowed to write files or physical outputs directly. This program
// only transfers validated one-shot requests/configuration into GVL_FILE_ARCHIVE,
// where PRG_File_Archive_Manager consumes them and publishes deterministic status.
// ==============================================================================


L_Any_Write_Request :=
    GVL_FILE_ARCHIVE_HMI.G_Write_Event_CSV_Req
    OR GVL_FILE_ARCHIVE_HMI.G_Write_Trend_CSV_Req
    OR GVL_FILE_ARCHIVE_HMI.G_Write_BlackBox_CSV_Req
    OR GVL_FILE_ARCHIVE_HMI.G_Write_Config_Backup_Req;

IF GVL_FILE_ARCHIVE_HMI.G_Set_Archive_Config_Req THEN
    IF GVL_FILE_ARCHIVE_HMI.G_File_Archive_Target_Code <= 3 THEN
        GVL_FILE_ARCHIVE.G_Archive_Interface_Enabled := GVL_FILE_ARCHIVE_HMI.G_Archive_Interface_Enabled;
        GVL_FILE_ARCHIVE.G_CSV_Write_Enabled := GVL_FILE_ARCHIVE_HMI.G_CSV_Write_Enabled;
        GVL_FILE_ARCHIVE.G_File_Archive_Target_Code := GVL_FILE_ARCHIVE_HMI.G_File_Archive_Target_Code;

        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := TRUE;
        GVL_FILE_ARCHIVE.G_Write_Error := FALSE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 0;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Archive configuration applied';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := FALSE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 0;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Archive configuration applied';
    ELSE
        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Error := TRUE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 16#A101;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Archive configuration rejected: invalid target';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := TRUE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 16#A101;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Archive configuration rejected: invalid target';
    END_IF;

    GVL_FILE_ARCHIVE_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_FILE_ARCHIVE_HMI.G_Set_Archive_Config_Req := FALSE;
END_IF;

IF GVL_FILE_ARCHIVE_HMI.G_Set_Auto_Config_Backup_Req THEN
    IF GVL_FILE_ARCHIVE_HMI.G_Auto_Config_Backup_Time_Of_Day_MS < GVL_CONSTANTS.C_MS_IN_DAY THEN
        GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Enabled := GVL_FILE_ARCHIVE_HMI.G_Auto_Config_Backup_Enabled;
        GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Time_Of_Day_MS := GVL_FILE_ARCHIVE_HMI.G_Auto_Config_Backup_Time_Of_Day_MS;
        GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Last_Status_Text := 'Auto config backup schedule applied';

        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := TRUE;
        GVL_FILE_ARCHIVE.G_Write_Error := FALSE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 0;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Auto config backup schedule applied';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := FALSE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 0;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Auto config backup schedule applied';
    ELSE
        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Error := TRUE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 16#A104;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Auto config backup rejected: invalid time';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := TRUE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 16#A104;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Auto config backup rejected: invalid time';
    END_IF;

    GVL_FILE_ARCHIVE_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_FILE_ARCHIVE_HMI.G_Set_Auto_Config_Backup_Req := FALSE;
END_IF;

IF L_Any_Write_Request THEN
    IF NOT GVL_FILE_ARCHIVE.G_Archive_Interface_Enabled THEN
        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Error := TRUE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 16#A102;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Archive write rejected: interface disabled';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := TRUE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 16#A102;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Archive write rejected: interface disabled';
    ELSIF NOT GVL_FILE_ARCHIVE.G_CSV_Write_Enabled THEN
        GVL_FILE_ARCHIVE.G_Write_Busy := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Done := FALSE;
        GVL_FILE_ARCHIVE.G_Write_Error := TRUE;
        GVL_FILE_ARCHIVE.G_Last_Error_Code := 16#A103;
        GVL_FILE_ARCHIVE.G_Last_Status_Text := 'Archive write rejected: CSV disabled';
        GVL_FILE_ARCHIVE.G_Last_Write_MS := GVL_TIME_SERVICE.G_Now_MS;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := TRUE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 16#A103;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Archive write rejected: CSV disabled';
    ELSE
        GVL_FILE_ARCHIVE.G_Write_Event_CSV_Request :=
            GVL_FILE_ARCHIVE.G_Write_Event_CSV_Request OR GVL_FILE_ARCHIVE_HMI.G_Write_Event_CSV_Req;
        GVL_FILE_ARCHIVE.G_Write_Trend_CSV_Request :=
            GVL_FILE_ARCHIVE.G_Write_Trend_CSV_Request OR GVL_FILE_ARCHIVE_HMI.G_Write_Trend_CSV_Req;
        GVL_FILE_ARCHIVE.G_Write_BlackBox_CSV_Request :=
            GVL_FILE_ARCHIVE.G_Write_BlackBox_CSV_Request OR GVL_FILE_ARCHIVE_HMI.G_Write_BlackBox_CSV_Req;
        GVL_FILE_ARCHIVE.G_Write_Config_Backup_Request :=
            GVL_FILE_ARCHIVE.G_Write_Config_Backup_Request OR GVL_FILE_ARCHIVE_HMI.G_Write_Config_Backup_Req;

        GVL_FILE_ARCHIVE_HMI.G_Last_Error := FALSE;
        GVL_FILE_ARCHIVE_HMI.G_Last_Error_Code := 0;
        GVL_FILE_ARCHIVE_HMI.G_Last_Status_Text := 'Archive write request accepted';
    END_IF;

    GVL_FILE_ARCHIVE_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

    // HMI requests are one-shot. Runtime requests are consumed by archive manager.
    GVL_FILE_ARCHIVE_HMI.G_Write_Event_CSV_Req := FALSE;
    GVL_FILE_ARCHIVE_HMI.G_Write_Trend_CSV_Req := FALSE;
    GVL_FILE_ARCHIVE_HMI.G_Write_BlackBox_CSV_Req := FALSE;
    GVL_FILE_ARCHIVE_HMI.G_Write_Config_Backup_Req := FALSE;
END_IF;

