END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Transaction_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Valid := FALSE;
GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Granted := FALSE;
GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Quarantine_Active := TRUE;

GVL_PHYSICAL_TRANSACTION.All_Actuators_Converged := FALSE;
GVL_PHYSICAL_TRANSACTION.Cross_Actuator_Epoch_Coherent := FALSE;
GVL_PHYSICAL_TRANSACTION.Distributed_Actuation_Coherent := FALSE;
GVL_PHYSICAL_TRANSACTION.Stable_Plant_State_Confirmed := FALSE;

// Bind transaction epochs.
GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Command_Epoch :=
    GVL_ACTUATION_AUTHORITY.Actuation_Command_Epoch;

GVL_PHYSICAL_TRANSACTION.Physical_Transaction_ACK_Epoch :=
    GVL_ACTUATION_AUTHORITY.Field_ACK_Epoch;

IF GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Command_Epoch <>
   GVL_PHYSICAL_TRANSACTION.Physical_Transaction_ACK_Epoch THEN

    GVL_PHYSICAL_TRANSACTION.Cross_Actuator_Convergence_Skew := TRUE;

    L_Transaction_Valid := FALSE;
    L_Error_Code := 27000;
    L_Error_Text := 'Physical transaction epoch skew detected';
END_IF;

// Ordering race detection.
IF L_Transaction_Valid
AND GVL_PHYSICAL_TRANSACTION.Pump_Valve_Ordering_Race_Detected THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27001;
    L_Error_Text := 'Pump/valve ordering race detected';
END_IF;

// Brownout / rollback protection.
IF L_Transaction_Valid
AND GVL_PHYSICAL_TRANSACTION.Distributed_Actuator_Rollback_Detected THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27002;
    L_Error_Text := 'Distributed actuator rollback detected';
END_IF;

IF L_Transaction_Valid
AND GVL_PHYSICAL_TRANSACTION.Brownout_Partial_Switching_Detected THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27003;
    L_Error_Text := 'Brownout partial switching detected';
END_IF;

IF L_Transaction_Valid
AND GVL_PHYSICAL_TRANSACTION.Transaction_Timeout_Detected THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27004;
    L_Error_Text := 'Physical transaction timeout detected';
END_IF;

IF L_Transaction_Valid
AND GVL_PHYSICAL_TRANSACTION.Partial_Plant_Transition_Detected THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27005;
    L_Error_Text := 'Partial plant transition detected';
END_IF;

// All actuator transitions required.
IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Valve_Transition_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27010;
    L_Error_Text := 'Valve transition confirmation missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Pump_Transition_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27011;
    L_Error_Text := 'Pump transition confirmation missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Damper_Transition_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27012;
    L_Error_Text := 'Damper transition confirmation missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Relay_Bank_Transition_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27013;
    L_Error_Text := 'Relay bank transition confirmation missing';
END_IF;

// Stable plant convergence required.
IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Flow_Stabilization_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27020;
    L_Error_Text := 'Flow stabilization missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Pressure_Stabilization_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27021;
    L_Error_Text := 'Pressure stabilization missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Thermal_Response_Confirmed THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27022;
    L_Error_Text := 'Thermal response confirmation missing';
END_IF;

IF L_Transaction_Valid
AND NOT GVL_PHYSICAL_TRANSACTION.Electrical_Load_Stabilized THEN
    L_Transaction_Valid := FALSE;
    L_Error_Code := 27023;
    L_Error_Text := 'Electrical load stabilization missing';
END_IF;

IF L_Transaction_Valid THEN
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Valid := TRUE;
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Granted := TRUE;
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Quarantine_Active := FALSE;

    GVL_PHYSICAL_TRANSACTION.All_Actuators_Converged := TRUE;
    GVL_PHYSICAL_TRANSACTION.Cross_Actuator_Epoch_Coherent := TRUE;
    GVL_PHYSICAL_TRANSACTION.Distributed_Actuation_Coherent := TRUE;
    GVL_PHYSICAL_TRANSACTION.Stable_Plant_State_Confirmed := TRUE;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Epoch :=
        GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Command_Epoch;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Last_Update_MS :=
        L_Now_MS;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Lease_Expired := FALSE;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Last_Error_Code := 0;
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Last_Error_Text := '';
ELSE
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Valid := FALSE;
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Granted := FALSE;
    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Quarantine_Active := TRUE;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Lease_Expired := TRUE;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Last_Error_Code :=
        L_Error_Code;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Last_Error_Text :=
        L_Error_Text;

    GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Invalidation_Count :=
        GVL_PHYSICAL_TRANSACTION.Physical_Transaction_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Commit_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Expired := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Replay_Detected := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Missing := FALSE;
GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired := FALSE;

L_Publication_Authority_Allowed :=
    GVL_Distributed_Execution_Gates.G_Runtime_Valid
    AND GVL_Distributed_Execution_Gates.G_Can_Replicate
    AND GVL_Distributed_Execution_Gates.G_Can_Own_Projection
    AND GVL_CONVERGENCE.Convergence_Lease_OK
    AND GVL_CONVERGENCE.Convergence_Release_Allowed
    AND GVL_RECOVERY_GOVERNANCE.Recovery_Governance_Valid
    AND NOT GVL_RECOVERY_GOVERNANCE.Recovery_Quarantine_Active;

GVL_DISTRIBUTED_COMMIT.Local_Publication_Commit_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;
GVL_DISTRIBUTED_COMMIT.Local_Prepare_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;

IF NOT L_Publication_Authority_Allowed THEN
    L_Commit_Valid := FALSE;
    L_Error_Code := 14999;
    L_Error_Text := 'Distributed publication authority restricted';
END_IF;

IF L_Commit_Valid THEN
    IF GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    THEN
        GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Active := TRUE;
        GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid := TRUE;
    ELSE
        GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Active := FALSE;
        GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid := FALSE;
        L_Commit_Valid := FALSE;
        L_Error_Code := 15000;
        L_Error_Text := 'Distributed immutable publication prepare invalid';
    END_IF;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Publication_Commit_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Prepare_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_COMMIT.Peer_Commit_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_COMMIT.Commit_Timeout_MS THEN
            GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired := TRUE;
            L_Commit_Valid := FALSE;
            L_Error_Code := 15001;
            L_Error_Text := 'Distributed commit lease expired';
        END_IF;
    END_IF;
END_IF;

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Missing := TRUE;
        L_Commit_Valid := FALSE;
        L_Error_Code := 15002;
        L_Error_Text := 'Peer commit acknowledgement missing';
    END_IF;
END_IF;

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_COMMIT.Peer_Publication_Commit_Epoch < GVL_DISTRIBUTED_COMMIT.Local_Publication_Commit_Epoch THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch := TRUE;
        L_Commit_Valid := FALSE;
        L_Error_Code := 15003;
        L_Error_Text := 'Peer commit epoch mismatch';
    END_IF;
END_IF;

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_COMMIT.Peer_Prepare_Epoch < GVL_DISTRIBUTED_COMMIT.Local_Prepare_Epoch THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Replay_Detected := TRUE;
        L_Commit_Valid := FALSE;
        L_Error_Code := 15004;
        L_Error_Text := 'Peer commit replay detected';
    END_IF;
END_IF;

IF L_Commit_Valid THEN
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Epoch := GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Epoch + 1;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Reconciliation_Epoch := GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Requested := TRUE;
    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed := TRUE;

    IF L_Peer_Session_Active THEN
        GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active := TRUE;
    ELSE
        GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active := FALSE;
    END_IF;

    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid := TRUE;

    IF GVL_CONVERGENCE.Convergence_Release_Allowed THEN
        GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active := FALSE;
    END_IF;

    GVL_DISTRIBUTED_COMMIT.Commit_Last_Reconciliation_MS := L_Now_MS;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Code := 0;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Text := '';
ELSE
    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed := FALSE;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid := FALSE;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active := TRUE;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Text := L_Error_Text;
END_IF;

// Default unused module slots to online so domain loops over C_MAX_MODULES
// do not report false faults for modules without watchdog bindings.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    GVL_STATUS.G_IO_Modules_Online[L_i] := TRUE;
END_FOR;

fbIO_Watchdog_1(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Module_ID := 1,
    VI_Heartbeat_Signal := GVL_IO.DI_Module_1_Heartbeat,
    VI_Timeout_MS := 2000
);

fbIO_Watchdog_2(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Module_ID := 2,
    VI_Heartbeat_Signal := GVL_IO.DI_Module_2_Heartbeat,
    VI_Timeout_MS := 2000
);

GVL_STATUS.G_IO_Modules_Online[1] := fbIO_Watchdog_1.VO_Module_Online;
GVL_STATUS.G_IO_Modules_Online[2] := fbIO_Watchdog_2.VO_Module_Online;

L_IO_Error_Active := fbIO_Watchdog_1.VO_Error_Active OR fbIO_Watchdog_2.VO_Error_Active;

fbDiagEventManager(
    VI_Code := 16#E001,
    VI_Severity := 4,
    VI_Active := NOT fbIO_Watchdog_1.VO_Module_Online,
    VI_Timestamp := GVL_STATUS.G_System_Time_MS,
    VI_Source := 1,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := 16#E002,
    VI_Severity := 4,
    VI_Active := NOT fbIO_Watchdog_2.VO_Module_Online,
    VI_Timestamp := GVL_STATUS.G_System_Time_MS,
    VI_Source := 2,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Phase_01_Module_Health <<<

IF GVL_PHYSICAL_DEADLOCK_RESOLUTION_FABRIC.Physical_Deadlock_Resolution_Granted
AND NOT GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Distributed_Execution_Stall_Detected
AND NOT GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Execution_Progress_Divergence_Detected
AND NOT GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Recovery_Progress_Oscillation_Detected THEN

    GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Execution_Progress_Causality_Valid := TRUE;
    GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Execution_Progress_Causality_Granted := TRUE;
    GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Progress_Causality_Grounded := TRUE;
    GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Deterministic_Execution_Continuation_Valid := TRUE;
END_IF;

// Command arbitration phase 04: single deterministic write into GVL_COMMAND_SHADOW.

GVL_COMMAND_SHADOW.G_Gas_Valve_Close := GVL_COMMAND_ARBITRATION_BUFFER.B_Gas_Valve_Close;
GVL_COMMAND_SHADOW.G_Boiler_Stop := GVL_COMMAND_ARBITRATION_BUFFER.B_Boiler_Stop;
GVL_COMMAND_SHADOW.G_Supply_100_Req := GVL_COMMAND_ARBITRATION_BUFFER.B_Supply_100_Req;
GVL_COMMAND_SHADOW.G_Supply_80_Req := GVL_COMMAND_ARBITRATION_BUFFER.B_Supply_80_Req;
