GVL_COMMAND_SHADOW.G_Vent_Block := GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Block;
GVL_COMMAND_SHADOW.G_Vent_Smoke_Exhaust := GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Smoke_Exhaust;

GVL_COMMAND_SHADOW.G_Heating_Block := GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Block;
GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop := GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Emergency_Stop;
GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop := GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Gas_Safety_Stop;

GVL_COMMAND_SHADOW.G_Water_Block := GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Block;
GVL_COMMAND_SHADOW.G_Water_Emergency_Stop := GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Emergency_Stop;
GVL_COMMAND_SHADOW.G_Close_Valve_35 := GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_35;
GVL_COMMAND_SHADOW.G_Close_Valve_36 := GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_36;

GVL_COMMAND_SHADOW.G_Lock_1_Open := GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_1_Open;
GVL_COMMAND_SHADOW.G_Lock_1_Close := GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_1_Close;
GVL_COMMAND_SHADOW.G_Lock_2_Open := GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_2_Open;
GVL_COMMAND_SHADOW.G_Lock_2_Close := GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_2_Close;
GVL_COMMAND_SHADOW.G_Gate_Open := GVL_COMMAND_ARBITRATION_BUFFER.B_Gate_Open;
GVL_COMMAND_SHADOW.G_Wicket_Open := GVL_COMMAND_ARBITRATION_BUFFER.B_Wicket_Open;

