);

// ======================================================
// PEER SESSION PUBLICATION
// ======================================================
// Canonical local PLC session export.
//
// Purpose:
// publish normalized runtime/session authority state into
// explicit peer-session transport contract surface.
//
// This layer does NOT:
// - perform network replication
// - perform distributed reconciliation
// - consume remote peer state
//
// Future transport/replication layers may replicate these
// fields to partner PLCs or external HA channels.
// ======================================================

GVL_PEER_SESSION.Remote_Session_Valid :=
    GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK
    AND GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed;

GVL_PEER_SESSION.Remote_Last_Refresh_MS :=
    GVL_STATUS.G_System_Time_MS;

GVL_PEER_SESSION.Remote_Runtime_Epoch :=
    GVL_RUNTIME_EPOCH.Runtime_Epoch;

GVL_PEER_SESSION.Remote_Snapshot_Epoch :=
    GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch;

GVL_PEER_SESSION.Remote_Boot_Generation :=
    GVL_TIME_MONOTONIC.Boot_Generation_ID;

GVL_PEER_SESSION.Remote_Fencing_Token :=
    GVL_PLC_FENCING.PLC_Fencing_Token;

GVL_PEER_SESSION.Remote_Publication_Allowed :=
    GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay;

GVL_PEER_SESSION.Remote_Runtime_Healthy :=
    GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK;

// >>> BULK_SYNC_ANCHOR: PRG_Peer_Session_Publication <<<

L_Any_Sensor_Fault := FALSE;

fbCalib_Outdoor_Temp(
    VI_Raw_Value := GVL_IO.AI_Temp_Outdoor.rValue,
    VI_Record := GVL_CONFIG.G_Calib_Outdoor_Temp
);
GVL_STATE.G_Outdoor_Temp := fbCalib_Outdoor_Temp.VO_Calibrated_Value;
IF fbCalib_Outdoor_Temp.VO_Record_Fault THEN
    L_Any_Sensor_Fault := TRUE;
END_IF;

IF GVL_CONFIG.G_Entrance_Light_Assist_Use_Lux_Sensor THEN
    IF GVL_IO.AI_Ambient_Lux.wStatus = 0 THEN
        fbCalib_Ambient_Lux(
            VI_Raw_Value := GVL_IO.AI_Ambient_Lux.rValue,
            VI_Record := GVL_CONFIG.G_Calib_Ambient_Lux
        );
        L_Ambient_Lux := fbCalib_Ambient_Lux.VO_Calibrated_Value;
        IF fbCalib_Ambient_Lux.VO_Record_Fault THEN
            L_Any_Sensor_Fault := TRUE;
        END_IF;

        IF (L_Ambient_Lux < 0.0) OR (L_Ambient_Lux > 200000.0) THEN
            GVL_STATE.G_Ambient_Lux_Sensor_Fault := TRUE;
            GVL_STATE.G_Ambient_Lux_Valid := FALSE;
            L_Any_Sensor_Fault := TRUE;
        ELSE
            GVL_STATE.G_Ambient_Lux := L_Ambient_Lux;
            GVL_STATE.G_Ambient_Lux_Valid := TRUE;
            GVL_STATE.G_Ambient_Lux_Sensor_Fault := FALSE;
        END_IF;
    ELSE
        GVL_STATE.G_Ambient_Lux_Valid := FALSE;
        GVL_STATE.G_Ambient_Lux_Sensor_Fault := TRUE;
        L_Any_Sensor_Fault := TRUE;
    END_IF;
ELSE
    GVL_STATE.G_Ambient_Lux_Valid := FALSE;
    GVL_STATE.G_Ambient_Lux_Sensor_Fault := FALSE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS DO
    IF GVL_IO.AI_Supply_Temps[L_i].wStatus = 0 THEN
        fbCalib_Supply_Temps[L_i](
            VI_Raw_Value := GVL_IO.AI_Supply_Temps[L_i].rValue,
            VI_Record := GVL_CONFIG.G_Calib_Supply_Temps[L_i]
        );
        GVL_STATE.G_Supply_Temps[L_i] := fbCalib_Supply_Temps[L_i].VO_Calibrated_Value;
        IF fbCalib_Supply_Temps[L_i].VO_Record_Fault THEN
            L_Any_Sensor_Fault := TRUE;
        END_IF;
    ELSE
        L_Any_Sensor_Fault := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    fbCalib_Room_Hum[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_Hum[L_i],
        VI_Record := GVL_CONFIG.G_Calib_Humidity[L_i]
    );
    GVL_STATE.G_Room_Hum[L_i] := fbCalib_Room_Hum[L_i].VO_Calibrated_Value;
    IF fbCalib_Room_Hum[L_i].VO_Record_Fault THEN
        L_Any_Sensor_Fault := TRUE;
    END_IF;

    fbCalib_Room_CO2[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_CO2[L_i],
        VI_Record := GVL_CONFIG.G_Calib_CO2[L_i]
    );
    GVL_STATE.G_Room_CO2[L_i] := fbCalib_Room_CO2[L_i].VO_Calibrated_Value;
    IF fbCalib_Room_CO2[L_i].VO_Record_Fault THEN
        L_Any_Sensor_Fault := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    fbCalib_Room_Temps[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_Temps[L_i],
        VI_Record := GVL_CONFIG.G_Calib_Room_Temps[L_i]
    );
    IF fbCalib_Room_Temps[L_i].VO_Record_Fault THEN
        L_Any_Sensor_Fault := TRUE;
    END_IF;

    IF GVL_STATE.G_Last_Valid_Room_Temps[L_i] = 0.0 THEN
        L_Filtered_Room_Temp := fbCalib_Room_Temps[L_i].VO_Calibrated_Value;
    ELSE
        L_Filtered_Room_Temp := (GVL_STATE.G_Last_Valid_Room_Temps[L_i] * 0.9) + (fbCalib_Room_Temps[L_i].VO_Calibrated_Value * 0.1);
    END_IF;

    IF (L_Filtered_Room_Temp < -50.0) OR (L_Filtered_Room_Temp > 100.0) THEN
        GVL_STATE.G_Temp_Sensor_Fault[L_i] := TRUE;
        GVL_STATE.G_Room_Temps[L_i] := GVL_STATE.G_Last_Valid_Room_Temps[L_i];
        L_Any_Sensor_Fault := TRUE;
    ELSE
        GVL_STATE.G_Temp_Sensor_Fault[L_i] := FALSE;
        GVL_STATE.G_Room_Temps[L_i] := L_Filtered_Room_Temp;
        GVL_STATE.G_Last_Valid_Room_Temps[L_i] := L_Filtered_Room_Temp;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF L_i <= GVL_CONSTANTS.C_MAX_ZONES THEN
        fbCalib_Floor_Temps[L_i](
            VI_Raw_Value := GVL_IO.AI_Floor_Temps[L_i],
            VI_Record := GVL_CONFIG.G_Calib_Floor_Temps[L_i]
        );
        IF fbCalib_Floor_Temps[L_i].VO_Record_Fault THEN
            L_Any_Sensor_Fault := TRUE;
        END_IF;

        IF GVL_STATE.G_Last_Valid_Floor_Temps[L_i] = 0.0 THEN
            L_Filtered_Floor_Temp := fbCalib_Floor_Temps[L_i].VO_Calibrated_Value;
        ELSE
            L_Filtered_Floor_Temp := (GVL_STATE.G_Last_Valid_Floor_Temps[L_i] * 0.9) + (fbCalib_Floor_Temps[L_i].VO_Calibrated_Value * 0.1);
        END_IF;

        IF (L_Filtered_Floor_Temp < -50.0) OR (L_Filtered_Floor_Temp > 100.0) THEN
            GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := TRUE;
            GVL_STATE.G_Floor_Temps[L_i] := GVL_STATE.G_Last_Valid_Floor_Temps[L_i];
            L_Any_Sensor_Fault := TRUE;
        ELSE
            GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := FALSE;
            GVL_STATE.G_Floor_Temps[L_i] := L_Filtered_Floor_Temp;
            GVL_STATE.G_Last_Valid_Floor_Temps[L_i] := L_Filtered_Floor_Temp;
        END_IF;
    ELSE
        GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := TRUE;
        GVL_STATE.G_Floor_Temps[L_i] := GVL_STATE.G_Last_Valid_Floor_Temps[L_i];
        L_Any_Sensor_Fault := TRUE;
    END_IF;
END_FOR;

GVL_STATUS.G_Diagnostics.Sensor_Fault := L_Any_Sensor_Fault;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Phase_03_Environment_Sensors <<<

// Non-authoritative water runtime observability path.
// Does not write physical outputs or command shadow.

fbPredictiveDiagnostics(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbForensicJournal(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

// >>> BULK_SYNC_ANCHOR: PRG_Water_Output_Projection_Phase_02_Observability <<<

// Local-only PLC authority for the cold-spare architecture.
//
// Hot A/B failover and lowest-ID arbitration are intentionally disabled.
// The reserve PLC is not expected to be connected to the same physical outputs
// during normal runtime.

GVL_STATUS.G_Is_Active_PLC := TRUE;
GVL_STATUS.G_Other_PLC_Is_Active := FALSE;
GVL_STATUS.G_Remote_PLC_Alive := FALSE;
GVL_STATUS.G_Active_PLC_ID := GVL_STATUS.G_Local_PLC_ID;

// Keep remote visibility fields reset so old partner pulses cannot resurrect a
// standby/active split-brain path.
GVL_STATUS.G_Remote_PLC_Pulse := FALSE;
GVL_STATUS.G_Remote_PLC_Last_Seen_MS := 0;

// >>> BULK_SYNC_ANCHOR: PRG_PLC_Arbitration <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Snapshot_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Valid := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Frozen := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Publication_Allowed := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Isolation_Valid := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Copy_Valid := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Freshness_Valid := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Consensus_Coherent := FALSE;
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Causality_Coherent := FALSE;

GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Runtime_Epoch := ULINT_TO_UDINT(GVL_RUNTIME_EPOCH.Runtime_Epoch);
GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Output_Epoch := ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch);

IF NOT GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 23000;
    L_Error_Text := 'Physical snapshot runtime barrier invalid';
END_IF;

IF L_Snapshot_Valid AND NOT GVL_OUTPUT_EPOCH.Output_Publication_Valid THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 23001;
    L_Error_Text := 'Physical snapshot output publication invalid';
END_IF;

IF L_Snapshot_Valid AND GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Mutation_Detected THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 23002;
    L_Error_Text := 'Physical snapshot mutation detected';
END_IF;

IF L_Snapshot_Valid AND GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Replay_Suspected THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 23003;
    L_Error_Text := 'Physical snapshot replay suspected';
END_IF;

IF L_Snapshot_Valid AND GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Lease_Expired THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 23004;
    L_Error_Text := 'Physical snapshot lease expired';
END_IF;

IF L_Snapshot_Valid THEN
    GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Valid := TRUE;
    GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Frozen := TRUE;
    GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Publication_Allowed := TRUE;
