// >>> BULK_SYNC_ANCHOR: PRG_Command_Arbitration_Phase_01_Reset_Role <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_IO.AI_Manifold_Temps_Supply[L_i].wStatus = 0 THEN
        fbCalib_Manifold_T_Supply[L_i](
            VI_Raw_Value := GVL_IO.AI_Manifold_Temps_Supply[L_i].rValue,
            VI_Record := GVL_CONFIG.G_Calib_Manifold_T_Supply[L_i]
        );
        GVL_STATE.G_Manifold_T_Supply[L_i] := fbCalib_Manifold_T_Supply[L_i].VO_Calibrated_Value;
        IF fbCalib_Manifold_T_Supply[L_i].VO_Record_Fault THEN
            GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
        END_IF;
    ELSE
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
    END_IF;

    fbCalib_Manifold_T_Return[L_i](
        VI_Raw_Value := INT_TO_REAL(GVL_IO.AI_Manifold_Temps_Return[L_i]) / 10.0,
        VI_Record := GVL_CONFIG.G_Calib_Manifold_T_Return[L_i]
    );
    GVL_STATE.G_Manifold_T_Return[L_i] := fbCalib_Manifold_T_Return[L_i].VO_Calibrated_Value;
    IF fbCalib_Manifold_T_Return[L_i].VO_Record_Fault THEN
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
    END_IF;

    GVL_STATE.G_Manifold_End_Switches[L_i] := GVL_IO.DI_Manifold_End_Switches[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Manifold_02_Temperature_Status <<<

IF GVL_HISTORICAL_ORDERING_INTEGRITY_FABRIC.Historical_Ordering_Integrity_Granted
AND NOT GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Causality_Reversal_Detected
AND NOT GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Resurrection_After_Revocation_Detected
AND NOT GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Unsafe_Temporal_Replay_Detected THEN

    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Causality_Reversal_Prevention_Valid := TRUE;
    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Causality_Reversal_Prevention_Granted := TRUE;
    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Causality_Reversal_Prevented := TRUE;
    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Authority_Ordering_Canonical := TRUE;
    GVL_CAUSALITY_REVERSAL_PREVENTION_FABRIC.Revocation_Resurrection_Boundary_Stable := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Epistemic_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_EPISTEMIC_INTEGRITY_FABRIC.Epistemic_Integrity_Valid := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Epistemic_Integrity_Granted := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Epistemic_Integrity_Quarantine_Active := TRUE;

GVL_EPISTEMIC_INTEGRITY_FABRIC.Physical_Reality_Model_Coherent := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Sensor_Truth_Consensus_Valid := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Telemetry_Reality_Alignment_Stable := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Distributed_Reality_Model_Consistent := FALSE;
GVL_EPISTEMIC_INTEGRITY_FABRIC.Causal_Model_Physically_Valid := FALSE;

// Forensic evidence required.
IF NOT GVL_FORENSIC_EVIDENCE_FABRIC.Forensic_Evidence_Granted THEN
    L_Epistemic_Valid := FALSE;
    L_Error_Code := 44000;
    L_Error_Text := 'Forensic evidence authority not granted';
END_IF;

// Epistemic split-brain detectors.
IF GVL_EPISTEMIC_INTEGRITY_FABRIC.Physically_False_Consensus_Detected THEN
    L_Epistemic_Valid := FALSE;
    L_Error_Code := 44001;
    L_Error_Text := 'Physically false consensus detected';
END_IF;

IF GVL_EPISTEMIC_INTEGRITY_FABRIC.Telemetry_Corruption_Coherent_Detected THEN
