    OR GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    OR GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active;

// Hard semantic continuity invalidation.
IF L_Output_Valid
AND GVL_OUTPUT_EPOCH.Output_Semantic_Continuity_Warning
THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6500;
    L_Error_Text := 'Semantic continuity invalid';
END_IF;

IF L_Output_Valid THEN
    IF GVL_OUTPUT_EPOCH.Output_Runtime_Epoch > GVL_RUNTIME_EPOCH.Runtime_Epoch THEN
        L_Output_Valid := FALSE;
        L_Error_Code := 6002;
        L_Error_Text := 'Output epoch ahead of runtime epoch';
    END_IF;
END_IF;

L_Delta_MS := L_Now_MS - GVL_OUTPUT_EPOCH.Output_Last_Refresh_MS;

IF L_Output_Valid AND GVL_OUTPUT_EPOCH.Output_Lease_Active THEN
    IF L_Delta_MS > GVL_OUTPUT_EPOCH.Output_Lease_Timeout_MS THEN
        L_Output_Valid := FALSE;
        L_Error_Code := 6003;
        L_Error_Text := 'Output lease expired';
    END_IF;
END_IF;

IF L_Output_Valid THEN
    GVL_OUTPUT_EPOCH.Output_Publication_Epoch := GVL_OUTPUT_EPOCH.Output_Publication_Epoch + 1;

    GVL_OUTPUT_EPOCH.Output_Publication_Valid := TRUE;
    GVL_OUTPUT_EPOCH.Output_Lease_Active := TRUE;
    GVL_OUTPUT_EPOCH.Output_Lease_Expired := FALSE;

    GVL_OUTPUT_EPOCH.Output_Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch;
    GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid := TRUE;

    GVL_OUTPUT_EPOCH.Output_Last_Publication_MS := L_Now_MS;
    GVL_OUTPUT_EPOCH.Output_Last_Refresh_MS := L_Now_MS;

    IF GVL_CONVERGENCE.Convergence_Release_Allowed THEN
        GVL_OUTPUT_EPOCH.Output_Stale_Detected := FALSE;
        GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay := FALSE;
    END_IF;

    GVL_OUTPUT_EPOCH.Output_Last_Error_Code := 0;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Text := '';
ELSE
    GVL_OUTPUT_EPOCH.Output_Publication_Valid := FALSE;
    GVL_OUTPUT_EPOCH.Output_Lease_Expired := TRUE;
    GVL_OUTPUT_EPOCH.Output_Stale_Detected := TRUE;
    GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay := TRUE;

    GVL_OUTPUT_EPOCH.Output_Last_Invalidation_MS := L_Now_MS;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Code := L_Error_Code;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Text := L_Error_Text;
END_IF;

GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active := FALSE;
GVL_STATUS.G_Diagnostics.Manifold_Pressure_First_Fault_Index := 0;
GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active := FALSE;
GVL_STATUS.G_Diagnostics.Manifold_Current_First_Fault_Index := 0;
GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := '';
GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := '';

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_IO.AI_Manifold_Pressures[L_i] < 0 THEN
        L_Manifold_Pressure_Raw := 0;
    ELSE
        L_Manifold_Pressure_Raw := INT_TO_WORD(GVL_IO.AI_Manifold_Pressures[L_i]);
    END_IF;

    IF GVL_IO.AI_Manifold_Currents[L_i] < 0 THEN
        L_Manifold_Current_Raw := 0;
    ELSE
        L_Manifold_Current_Raw := INT_TO_WORD(GVL_IO.AI_Manifold_Currents[L_i]);
    END_IF;

    fbAnalog_Manifold_Pressure[L_i](
        VI_Raw_Value := L_Manifold_Pressure_Raw,
        VI_Sensor_Type := 0,
        VI_Min_Scale := 0.0,
        VI_Max_Scale := 10.0,
        VI_Offset := 0.0,
        VI_Multiplier := 1.0,
        VI_Filter_Time_MS := GVL_CONSTANTS.C_MS_IN_SECOND,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Fallback_Mode := 0,
        VI_Default_Value := 0.0
    );
    GVL_STATE.G_Manifold_Pressures[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Value;
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Error;
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Diag_Code[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Diag_Code;

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE,
        VI_Severity := 3,
        VI_Active := fbAnalog_Manifold_Pressure[L_i].VO_Error,
        VI_Timestamp := GVL_STATUS.G_System_Time_MS,
        VI_Source := 100 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );

    fbAnalog_Manifold_Current[L_i](
        VI_Raw_Value := L_Manifold_Current_Raw,
        VI_Sensor_Type := 0,
        VI_Min_Scale := 0.0,
        VI_Max_Scale := 16.0,
        VI_Offset := 0.0,
        VI_Multiplier := 1.0,
        VI_Filter_Time_MS := GVL_CONSTANTS.C_MS_IN_SECOND,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Fallback_Mode := 0,
        VI_Default_Value := 0.0
    );
    GVL_STATE.G_Manifold_Currents[L_i] := fbAnalog_Manifold_Current[L_i].VO_Value;
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] := fbAnalog_Manifold_Current[L_i].VO_Error;
    GVL_STATUS.G_Diagnostics.Manifold_Current_Diag_Code[L_i] := fbAnalog_Manifold_Current[L_i].VO_Diag_Code;

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_PUMP_UNDERCURRENT,
        VI_Severity := 3,
        VI_Active := fbAnalog_Manifold_Current[L_i].VO_Error,
        VI_Timestamp := GVL_STATUS.G_System_Time_MS,
        VI_Source := 200 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );

    IF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] THEN
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
        GVL_STATUS.G_Diagnostics.Subsystem_Degraded := TRUE;
    END_IF;

    IF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] AND GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] THEN
        GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := 'Correlated pressure/current fault detected';
        GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := 'Correlated pressure/current fault detected';
    ELSIF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] AND (GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text = '') THEN
        GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := 'Pressure sensor fault detected';
    ELSIF GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] AND (GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text = '') THEN
        GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := 'Current sensor fault detected';
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Manifold_01_Pressure_Current <<<

GVL_POLICY.G_Away_Restore_Requested := FALSE;

// ============================================================
// CONFIGURATION SAFETY CLAMP
// ============================================================
// Configuration validation is diagnostic-only here.
// System mode ownership remains in FB_State_Manager via
// FB_System_Health_Orchestrator. Policy must not directly write
// GVL_STATE.G_System_Mode.
IF GVL_CONFIG_VALIDATION.G_Config_Force_Safe_Mode AND
   (NOT GVL_CONFIG_VALIDATION.G_Config_Valid) AND
   (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL) THEN
    GVL_STATUS.G_Diagnostics.Subsystem_Degraded := TRUE;
    GVL_STATUS.G_System_Mode_Text := 'CONFIG DEGRADED';
END_IF;

// ============================================================
// SCENARIO POLICY OWNER
// ============================================================

// 1. Base priority resolution
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
    GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

ELSIF GVL_POLICY.G_Scenario_Request_Operator <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Operator;
    GVL_POLICY.G_Scenario_Source := SRC_OPERATOR;

ELSIF GVL_POLICY.G_Scenario_Request_Gateway <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Gateway;
    GVL_POLICY.G_Scenario_Source := SRC_GATEWAY;

ELSIF GVL_POLICY.G_Scenario_Request_Rule <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Rule;
    GVL_POLICY.G_Scenario_Source := SRC_RULE;

ELSE
    GVL_POLICY.G_Scenario_Intent := GVL_STATUS.G_Current_Scenario;
    GVL_POLICY.G_Scenario_Source := SRC_NONE;
END_IF;

// 2. Fail-safe clamp
CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE GVL_POLICY.G_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ;
        ELSE
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_CASE;
END_CASE;

// 3. Context automation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF GVL_ALARM.G_Security_Armed AND
       (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;
    END_IF;
END_IF;

// 4. Degraded adaptation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF GVL_ALARM.G_Security_Armed THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;

        ELSIF GVL_POLICY.G_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_IF;
    END_IF;
END_IF;

// 5. Security alarm escalation.
// On security alarm, force long-away and publish a 5-minute lighting boost.
IF GVL_ALARM.G_Security_Alarm THEN
    GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
    GVL_POLICY.G_Scenario_Source := SRC_POLICY;
    GVL_POLICY.G_Security_Alarm_Force_Long_Away := TRUE;

    IF (NOT L_Security_Alarm_Prev) AND (NOT GVL_POLICY.G_Security_Alarm_Light_Boost_Active) THEN
        GVL_POLICY.G_Security_Alarm_Light_Boost_Active := TRUE;
        GVL_POLICY.G_Security_Alarm_Light_Boost_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
    END_IF;
ELSIF NOT GVL_ALARM.G_Security_Armed THEN
    GVL_POLICY.G_Security_Alarm_Force_Long_Away := FALSE;
END_IF;

IF GVL_POLICY.G_Security_Alarm_Light_Boost_Duration_MS = 0 THEN
    GVL_POLICY.G_Security_Alarm_Light_Boost_Duration_MS := 300000;
END_IF;

IF GVL_POLICY.G_Security_Alarm_Light_Boost_Active THEN
    IF GVL_TIME_SERVICE.G_Now_MS >= GVL_POLICY.G_Security_Alarm_Light_Boost_Start_MS THEN
        L_Security_Boost_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_POLICY.G_Security_Alarm_Light_Boost_Start_MS;
    ELSE
        L_Security_Boost_Elapsed_MS := (4294967295 - GVL_POLICY.G_Security_Alarm_Light_Boost_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
    END_IF;

    IF L_Security_Boost_Elapsed_MS >= GVL_POLICY.G_Security_Alarm_Light_Boost_Duration_MS THEN
        GVL_POLICY.G_Security_Alarm_Light_Boost_Active := FALSE;
    END_IF;
END_IF;

// 6. Entrance lighting assist.
// Trigger: entrance door rising edge while dark by configured source.
L_Entrance_Door_Open := FALSE;
IF (GVL_CONFIG.G_Entrance_Door_1_Index >= 1) AND (GVL_CONFIG.G_Entrance_Door_1_Index <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS) THEN
    L_Entrance_Door_Open := L_Entrance_Door_Open OR GVL_STATE.G_Door_Sensors[GVL_CONFIG.G_Entrance_Door_1_Index];
END_IF;
IF (GVL_CONFIG.G_Entrance_Door_2_Index >= 1) AND (GVL_CONFIG.G_Entrance_Door_2_Index <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS) THEN
    L_Entrance_Door_Open := L_Entrance_Door_Open OR GVL_STATE.G_Door_Sensors[GVL_CONFIG.G_Entrance_Door_2_Index];
END_IF;

L_Entrance_Dark_Active := FALSE;
IF GVL_CONFIG.G_Entrance_Light_Assist_Fallback_To_Night THEN
    L_Entrance_Dark_Active := GVL_STATUS.G_Is_Night;
END_IF;
IF GVL_CONFIG.G_Entrance_Light_Assist_Use_Lux_Sensor AND GVL_STATE.G_Ambient_Lux_Valid THEN
    L_Entrance_Dark_Active := L_Entrance_Dark_Active OR (GVL_STATE.G_Ambient_Lux < GVL_CONFIG.G_Entrance_Light_Assist_Lux_Threshold);
END_IF;
GVL_POLICY.G_Entrance_Light_Assist_Dark_Active := L_Entrance_Dark_Active;

IF GVL_CONFIG.G_Entrance_Light_Assist_Duration_MS = 0 THEN
    GVL_CONFIG.G_Entrance_Light_Assist_Duration_MS := 300000;
END_IF;

IF GVL_CONFIG.G_Entrance_Light_Assist_Enabled AND
   L_Entrance_Door_Open AND (NOT L_Entrance_Door_Open_Prev) AND
   L_Entrance_Dark_Active THEN
    GVL_POLICY.G_Entrance_Light_Assist_Active := TRUE;
    GVL_POLICY.G_Entrance_Light_Assist_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

L_Entrance_Motion_Active := FALSE;
IF (GVL_CONFIG.G_Entrance_Corridor_Light_Zone >= 1) AND (GVL_CONFIG.G_Entrance_Corridor_Light_Zone <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
    L_Entrance_Motion_Active := L_Entrance_Motion_Active OR GVL_STATE.G_Motion_Sensors[GVL_CONFIG.G_Entrance_Corridor_Light_Zone];
END_IF;
IF (GVL_CONFIG.G_Entrance_Stairs_Light_Zone >= 1) AND (GVL_CONFIG.G_Entrance_Stairs_Light_Zone <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
    L_Entrance_Motion_Active := L_Entrance_Motion_Active OR GVL_STATE.G_Motion_Sensors[GVL_CONFIG.G_Entrance_Stairs_Light_Zone];
END_IF;

IF GVL_POLICY.G_Entrance_Light_Assist_Active THEN
    IF L_Entrance_Motion_Active THEN
        GVL_POLICY.G_Entrance_Light_Assist_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
    END_IF;

    IF GVL_TIME_SERVICE.G_Now_MS >= GVL_POLICY.G_Entrance_Light_Assist_Start_MS THEN
        L_Entrance_Assist_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_POLICY.G_Entrance_Light_Assist_Start_MS;
    ELSE
        L_Entrance_Assist_Elapsed_MS := (4294967295 - GVL_POLICY.G_Entrance_Light_Assist_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
    END_IF;

    IF L_Entrance_Assist_Elapsed_MS >= GVL_CONFIG.G_Entrance_Light_Assist_Duration_MS THEN
        GVL_POLICY.G_Entrance_Light_Assist_Active := FALSE;
    END_IF;
END_IF;

// ============================================================
// AWAY LEVEL POLICY
// ============================================================
// 0=none, 1=short, 2=medium, 3=long.
// Short: light 100%, heating -1C, simulation off.
// Medium: light/simulation medium, heating -3C, simulation 0.3.
// Long: minimal reasonable heating economy; planned-return preheat may
// temporarily raise selected rooms before the expected arrival.
L_Away_Return_Window_Reached := FALSE;

IF GVL_POLICY.G_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_AWAY THEN
    IF NOT GVL_POLICY.G_Away_Active THEN
        GVL_POLICY.G_Away_Active := TRUE;
        GVL_POLICY.G_Away_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
        GVL_POLICY.G_Away_Elapsed_MS := 0;
        GVL_POLICY.G_Away_Level := 1;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
        GVL_POLICY.G_Away_Return_Expired := FALSE;
    ELSE
        IF GVL_TIME_SERVICE.G_Now_MS >= GVL_POLICY.G_Away_Start_MS THEN
            L_Away_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_POLICY.G_Away_Start_MS;
        ELSE
            L_Away_Elapsed_MS := (4294967295 - GVL_POLICY.G_Away_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
        END_IF;

        GVL_POLICY.G_Away_Elapsed_MS := L_Away_Elapsed_MS;

        IF L_Away_Elapsed_MS >= GVL_POLICY.G_Away_Medium_To_Long_MS THEN
            GVL_POLICY.G_Away_Level := 3;
        ELSIF L_Away_Elapsed_MS >= GVL_POLICY.G_Away_Short_To_Medium_MS THEN
            GVL_POLICY.G_Away_Level := 2;
        ELSE
            GVL_POLICY.G_Away_Level := 1;
        END_IF;
    END_IF;

    // Planned return preheat window.
    IF GVL_POLICY.G_Away_Planned_Return_Enabled AND NOT GVL_POLICY.G_Away_Return_Expired THEN
        IF GVL_POLICY.G_Away_Planned_Return_MS >= GVL_TIME_SERVICE.G_Now_MS THEN
            L_Return_Delta_MS := GVL_POLICY.G_Away_Planned_Return_MS - GVL_TIME_SERVICE.G_Now_MS;
            L_Away_Return_Window_Reached := (L_Return_Delta_MS <= GVL_POLICY.G_Away_Preheat_Lead_MS);
        ELSE
            L_Away_Return_Window_Reached := TRUE;
        END_IF;

        IF L_Away_Return_Window_Reached THEN
            GVL_POLICY.G_Away_Return_Preheat_Active := TRUE;

            IF NOT GVL_POLICY.G_Away_Return_Grace_Active THEN
                GVL_POLICY.G_Away_Return_Grace_Active := TRUE;
                GVL_POLICY.G_Away_Return_Grace_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
            END_IF;
        END_IF;

        IF GVL_POLICY.G_Away_Return_Grace_Active THEN
            IF GVL_TIME_SERVICE.G_Now_MS >= GVL_POLICY.G_Away_Return_Grace_Start_MS THEN
                L_Return_Grace_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_POLICY.G_Away_Return_Grace_Start_MS;
            ELSE
                L_Return_Grace_Elapsed_MS := (4294967295 - GVL_POLICY.G_Away_Return_Grace_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
            END_IF;

            IF L_Return_Grace_Elapsed_MS >= GVL_POLICY.G_Away_Return_Grace_MS THEN
                GVL_POLICY.G_Away_Return_Expired := TRUE;
                GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
                GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
            END_IF;
        END_IF;
    ELSE
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
    END_IF;

    IF GVL_POLICY.G_Security_Alarm_Force_Long_Away THEN
        GVL_POLICY.G_Away_Active := TRUE;
        GVL_POLICY.G_Away_Level := 3;
        GVL_POLICY.G_Away_Elapsed_MS := GVL_POLICY.G_Away_Medium_To_Long_MS;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
    END_IF;

    CASE GVL_POLICY.G_Away_Level OF
        1:
            GVL_POLICY.G_Away_Simulation_Active := FALSE;
            GVL_POLICY.G_Away_Simulation_Intensity := 0.0;
            GVL_POLICY.G_Away_Heating_Offset_C := -1.0;
        2:
            GVL_POLICY.G_Away_Simulation_Active := TRUE;
            GVL_POLICY.G_Away_Simulation_Intensity := 0.3;
            GVL_POLICY.G_Away_Heating_Offset_C := -3.0;
        3:
            GVL_POLICY.G_Away_Simulation_Active := TRUE;
            GVL_POLICY.G_Away_Simulation_Intensity := 0.2;

            IF GVL_POLICY.G_Away_Return_Preheat_Active THEN
                GVL_POLICY.G_Away_Heating_Offset_C := 0.0;
            ELSE
                GVL_POLICY.G_Away_Heating_Offset_C := GVL_POLICY.G_Away_Long_Economy_Setpoint_C - 22.0;
            END_IF;
    ELSE
            GVL_POLICY.G_Away_Simulation_Active := FALSE;
            GVL_POLICY.G_Away_Simulation_Intensity := 0.0;
            GVL_POLICY.G_Away_Heating_Offset_C := 0.0;
    END_CASE;

ELSE
    IF GVL_POLICY.G_Away_Active AND (GVL_POLICY.G_Away_Level = 1) THEN
        GVL_POLICY.G_Away_Restore_Requested := TRUE;
        GVL_POLICY.G_Away_Restore_Active := TRUE;
        GVL_POLICY.G_Away_Restore_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
    END_IF;

    GVL_POLICY.G_Away_Active := FALSE;
    GVL_POLICY.G_Away_Level := 0;
    GVL_POLICY.G_Away_Elapsed_MS := 0;
    GVL_POLICY.G_Away_Simulation_Active := FALSE;
    GVL_POLICY.G_Away_Simulation_Intensity := 0.0;
    GVL_POLICY.G_Away_Heating_Offset_C := 0.0;
    GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
    GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
    GVL_POLICY.G_Away_Return_Expired := FALSE;
END_IF;

IF GVL_POLICY.G_Away_Restore_Active THEN
    IF GVL_TIME_SERVICE.G_Now_MS >= GVL_POLICY.G_Away_Restore_Start_MS THEN
        L_Restore_Elapsed_MS := GVL_TIME_SERVICE.G_Now_MS - GVL_POLICY.G_Away_Restore_Start_MS;
    ELSE
        L_Restore_Elapsed_MS := (4294967295 - GVL_POLICY.G_Away_Restore_Start_MS) + GVL_TIME_SERVICE.G_Now_MS + 1;
    END_IF;

    IF L_Restore_Elapsed_MS >= GVL_POLICY.G_Away_Restore_Duration_MS THEN
        GVL_POLICY.G_Away_Restore_Progress := 1.0;
        GVL_POLICY.G_Away_Restore_Active := FALSE;
    ELSE
        GVL_POLICY.G_Away_Restore_Progress := TO_REAL(L_Restore_Elapsed_MS) / TO_REAL(GVL_POLICY.G_Away_Restore_Duration_MS);
    END_IF;
ELSE
    GVL_POLICY.G_Away_Restore_Progress := 0.0;
END_IF;

L_Previous_Away_Active := GVL_POLICY.G_Away_Active;
L_Previous_Away_Level := GVL_POLICY.G_Away_Level;
L_Security_Alarm_Prev := GVL_ALARM.G_Security_Alarm;
L_Entrance_Door_Open_Prev := L_Entrance_Door_Open;

// 5. Heating bridge
// Policy publishes preheat intent only. Actual per-circuit comfort/economy
// target selection is owned by FB_Heating_Circuit_Control through
// ST_FloorHeating_Circuit_Config.
GVL_STATE.G_Preheat_Request :=
    GVL_POLICY.G_Rule_Preheat_Request OR GVL_POLICY.G_Away_Return_Preheat_Active;
GVL_HEATING_REQUEST.G_Preheat_Request := GVL_STATE.G_Preheat_Request;
GVL_HEATING_REQUEST.G_Target_Temperature := GVL_STATE.G_Target_Temperature;

GVL_STATE.G_Freeze_Request :=
    (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
GVL_HEATING_REQUEST.G_Freeze_Request := GVL_STATE.G_Freeze_Request;

PRG_Away_Restore_Manager();

// IO write phase 04: publish final sirens, gas valve and normal trace.


GVL_IO.DO_Gas_Siren :=
    GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Fire_Siren_Enable
    AND GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Siren_Authority;

GVL_IO.DO_Fire_Siren :=
    GVL_IO_WRITE_RUNTIME_BUFFER.B_Gas_Fire_Siren_Enable
    AND GVL_IO_WRITE_RUNTIME_BUFFER.B_Fire_Siren_Authority;

GVL_IO.DO_Security_Siren :=
    GVL_ALARM.G_Security_Siren
    OR (GVL_ALARM.G_Global_Siren AND GVL_ALARM.G_Security_Alarm);

GVL_IO.DO_Gas_Valve_Close := GVL_COMMAND_SHADOW.G_Gas_Valve_Close;

fbTrace(
    iLayer := TRACE_IO,
    iSource := SRC_IO,
    iReason := REASON_DOMAIN_PROJECTION,
    iValueBool := TRUE,
    iValueReal := 0.0,
    iText := 'IO write projection executed'
);

// >>> BULK_SYNC_ANCHOR: PRG_IO_Write_Phase_04_Alarm_Trace <<<

// Water/Flood supervisory publication orchestration.
//
// Runtime chain:
// config activation/workflow
//   -> restart continuity
//   -> hardware binding resolver
//   -> runtime topology config
//   -> leak semantics
//   -> topology validation
//   -> graph/path resolution
//   -> orchestration/traversal governance
//   -> isolation semantics
//   -> authority arbitration
//   -> valve governance
//   -> supervisory publication
//
// Distributed execution gates are authoritative.
// Water runtime orchestration must never bypass cluster execution policy.

fbConfigActivationRuntime(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbHMIConfigWorkflowRuntime(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbRestartContinuity(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Warm_Restart := GVL_Runtime_Restart_Continuity.G_Restore_Request
);

fbWaterHardwareBindingRuntime(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterTopologyConfig(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterLeakProjection(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterTopologyValidator(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterIsolationPathResolver(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Orchestrate,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterOrchestrationRuntime(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Orchestrate,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterIsolationProjection(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Execute,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterIsolationIntentBuilder(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Execute
);

fbWaterAuthorityArbitrator(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Execute,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbWaterValveGovernance(
    VI_Enable := GVL_Distributed_Execution_Gates.G_Can_Own_Projection,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Any_Leak := FALSE;
L_Any_Warning := FALSE;
L_Any_Degraded_Mapping := FALSE;
L_Selective_Isolation_Available := FALSE;
L_Global_Fallback_Required := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO

    L_State := GVL_Water_Runtime_Projection.G_Leak_Runtime_State[L_i];

    L_Any_Leak := L_Any_Leak OR L_State.Leak_Confirmed;
    L_Any_Warning := L_Any_Warning OR L_State.Leak_Warning_Active;

    L_Any_Degraded_Mapping :=
        L_Any_Degraded_Mapping
        OR GVL_Water_Orchestration.G_Traversal_State[L_i].Traversal_Conflict
        OR NOT GVL_Water_Topology_Config.G_Config_Record[L_i].Config_Valid
        OR GVL_IO_Binding_Runtime.G_Any_Invalid_Binding;

    L_Selective_Isolation_Available :=
        L_Selective_Isolation_Available
        OR GVL_Water_Orchestration.G_Traversal_State[L_i].Selective_Path_Allowed;

    L_Global_Fallback_Required :=
        L_Global_Fallback_Required
        OR GVL_Water_Orchestration.G_Traversal_State[L_i].Global_Fallback_Required;

END_FOR;

GVL_Water_Runtime_Supervisory_Publication.G_Supervisory_Valid := TRUE;
GVL_Water_Runtime_Supervisory_Publication.G_Last_Update_MS :=
    GVL_STATUS.G_System_Time_MS;

GVL_Water_Runtime_Supervisory_Publication.G_Any_Leak_Active :=
    L_Any_Leak;

GVL_Water_Runtime_Supervisory_Publication.G_Any_Warning_Active :=
    L_Any_Warning;

GVL_Water_Runtime_Supervisory_Publication.G_Any_Degraded_Mapping :=
    L_Any_Degraded_Mapping;

GVL_Water_Runtime_Supervisory_Publication.G_Selective_Isolation_Available :=
    L_Selective_Isolation_Available;

GVL_Water_Runtime_Supervisory_Publication.G_Global_Fallback_Active :=
    L_Global_Fallback_Required;

IF NOT GVL_Distributed_Execution_Gates.G_Can_Execute THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 20;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Distributed execution gates restricted';
ELSIF GVL_Config_Activation.G_Config_Quarantine_Active THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 11;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Runtime config quarantine active';
ELSIF GVL_IO_Binding_Runtime.G_Any_Invalid_Binding THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 10;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Hardware binding invalid';
ELSIF GVL_Water_Topology_Config.G_Any_Invalid_Config THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 8;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Runtime topology config invalid';
ELSIF GVL_Water_Orchestration.G_Any_Escalation_Required THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 7;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Topology-aware orchestration escalation active';
ELSIF GVL_Water_Orchestration.G_Any_Traversal_Conflict THEN
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 6;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Traversal conflict detected';
ELSE
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Code := 0;
    GVL_Water_Runtime_Supervisory_Publication.G_Status_Text :=
        'Runtime topology orchestration active';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Water_Supervisory_Publication <<<

// Command arbitration phase 02: project safety mode into deterministic buffer.

GVL_COMMAND_ARBITRATION_BUFFER.B_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := FALSE;

CASE GVL_COMMAND_ARBITRATION_BUFFER.B_Mode OF

    NORMAL:
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := FALSE;

    FIRE:
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_Fire_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_Fire_Stop_Boiler;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Stop := FALSE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_PV3_Boost := FALSE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Exhaust_100_Req := FALSE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Smoke_Exhaust := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_Fire_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_1_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Lock_1;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_2_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Lock_2;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Gate_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Gate;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Wicket_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Wicket;

    GAS:
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Gas_Valve_Close := GVL_COMMAND_POLICY_CONFIG.G_Gas_Close_Gas;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_Gas_Stop_Boiler;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_Gas_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Gas_Safety_Stop := GVL_COMMAND_POLICY_CONFIG.G_Gas_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_PV3_Boost := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Smoke_Exhaust := FALSE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Gate_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Gate;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Wicket_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Wicket;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_1_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Lock_1;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Lock_2_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Lock_2;

    WATER_LEAK:
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Block := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_35 := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_36 := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;

    GLOBAL_STOP:
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Heating;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Stop_Boiler;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Stop_Vent;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Block := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_35 := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_36 := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;

ELSE
        GVL_COMMAND_ARBITRATION_BUFFER.B_Safety_Active := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Gas_Valve_Close := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Boiler_Stop := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Block := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Heating_Emergency_Stop := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Vent_Stop := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Block := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Water_Emergency_Stop := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_35 := TRUE;
        GVL_COMMAND_ARBITRATION_BUFFER.B_Close_Valve_36 := TRUE;
END_CASE;

// >>> BULK_SYNC_ANCHOR: PRG_Command_Arbitration_Phase_02_Safety_Mode <<<

// Input degraded forces safe stop first
IF GVL_INPUT.IN_Input_Degraded THEN
    L_Mode := GLOBAL_STOP;
ELSE

    // Priority: FIRE > GAS > WATER > GLOBAL_STOP > NORMAL

    IF GVL_INTENT_SAFETY.I_Fire_Alarm_Active THEN
        L_Mode := FIRE;
    ELSIF GVL_INTENT_SAFETY.I_Gas_Close_Required OR GVL_INTENT_SAFETY.I_Test_Timeout_Gas_Close THEN
        L_Mode := GAS;
    ELSIF GVL_INTENT_SAFETY.I_Water_Main_Close_Required OR GVL_INTENT_SAFETY.I_Test_Timeout_Water_Close THEN
        L_Mode := WATER_LEAK;
    ELSIF GVL_INTENT_SAFETY.I_System_Safe_Stop_Required THEN
        L_Mode := GLOBAL_STOP;
    ELSE
        L_Mode := NORMAL;
    END_IF;

END_IF;

GVL_SAFETY_SHUTDOWN.G_Safety_Mode := L_Mode;
GVL_SAFETY_SHUTDOWN.G_Safety_Active := (L_Mode <> NORMAL);

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Shutdown <<<

// ==============================================================================
// IO WRITE — deterministic physical output publication phase map.
// ==============================================================================
// Execution preserves the former priority model:
// 1. derive publication guards and forced-off flags
// 2. hard-stop safe-state publication and return when required
// 3. normal domain output projection
// 4. final alarm/gas valve and trace publication
// ==============================================================================

PRG_IO_Write_Phase_01_Context();

IF (NOT GVL_STATUS.G_Is_Active_PLC)
   OR GVL_IO_WRITE_RUNTIME_BUFFER.B_Global_Hard_Stop THEN
    PRG_IO_Write_Phase_02_Hard_Stop_Safe_State();
    RETURN;
END_IF;

PRG_IO_Write_Phase_03_Domain_Projection();
PRG_IO_Write_Phase_04_Alarm_Trace();

// >>> BULK_SYNC_ANCHOR: PRG_IO_Write <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Actuator_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Valid := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Granted := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Quarantine_Active := TRUE;

GVL_ACTUATOR_SEMANTIC_VERIFICATION.Valve_Semantic_Realization_Valid := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Relay_Semantic_Realization_Valid := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Pump_Semantic_Realization_Valid := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Fan_Semantic_Realization_Valid := FALSE;
GVL_ACTUATOR_SEMANTIC_VERIFICATION.Hydraulic_Response_Valid := FALSE;

// Control temporal coherence required.
IF NOT GVL_CONTROL_TIMING_FABRIC.Control_Temporal_Coherence_Granted THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36000;
    L_Error_Text := 'Control temporal coherence not granted';
END_IF;

// Semantic realization failure detectors.
IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.False_Positive_Actuation_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36001;
    L_Error_Text := 'False-positive actuation detected';
END_IF;

IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.Mechanical_NonRealization_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36002;
    L_Error_Text := 'Mechanical non-realization detected';
END_IF;

IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.Welded_Relay_Semantics_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36003;
    L_Error_Text := 'Welded relay semantics detected';
END_IF;

IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.Hydraulic_NoEffect_Execution_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36004;
    L_Error_Text := 'Hydraulic no-effect execution detected';
END_IF;

IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.Airflow_Realization_Mismatch_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36005;
    L_Error_Text := 'Airflow realization mismatch detected';
END_IF;

IF GVL_ACTUATOR_SEMANTIC_VERIFICATION.Physical_Convergence_Divergence_Detected THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36006;
    L_Error_Text := 'Physical convergence divergence detected';
END_IF;

// Physical semantic convergence validation.
IF L_Actuator_Valid
AND NOT GVL_ACTUATOR_SEMANTIC_VERIFICATION.Physical_Effect_Converged THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36010;
    L_Error_Text := 'Physical effect convergence invalid';
END_IF;

IF L_Actuator_Valid
AND NOT GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuation_Response_Temporal_Valid THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36011;
    L_Error_Text := 'Actuation response timing invalid';
END_IF;

IF L_Actuator_Valid
AND NOT GVL_ACTUATOR_SEMANTIC_VERIFICATION.Sensor_Confirmed_Execution_Valid THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36012;
    L_Error_Text := 'Sensor-confirmed execution invalid';
END_IF;

IF L_Actuator_Valid
AND NOT GVL_ACTUATOR_SEMANTIC_VERIFICATION.Semantic_Outcome_Aligned THEN
    L_Actuator_Valid := FALSE;
    L_Error_Code := 36013;
    L_Error_Text := 'Semantic outcome alignment invalid';
END_IF;

IF L_Actuator_Valid THEN
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Valid := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Granted := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Quarantine_Active := FALSE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Valve_Semantic_Realization_Valid := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Relay_Semantic_Realization_Valid := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Pump_Semantic_Realization_Valid := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Fan_Semantic_Realization_Valid := TRUE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Hydraulic_Response_Valid := TRUE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Epoch :=
        GVL_CONTROL_TIMING_FABRIC.Control_Timing_Epoch;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Epoch_Coherent := TRUE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Last_Update_MS :=
        L_Now_MS;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Lease_Expired := FALSE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Last_Error_Code := 0;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Last_Error_Text := '';
ELSE
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Valid := FALSE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Granted := FALSE;
    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Quarantine_Active := TRUE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Lease_Expired := TRUE;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Last_Error_Code :=
        L_Error_Code;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Last_Error_Text :=
        L_Error_Text;

    GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Invalidation_Count :=
        GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Invalidation_Count + 1;
END_IF;

L_History_Write_Event := FALSE;
L_History_Event.timestamp_ms := GVL_TIME_SERVICE.G_Now_MS;
L_History_Event.event_code := 0;
L_History_Event.event_value := 0.0;
L_History_Event.unit := 0;
L_History_Event.zone_id := 0;
L_History_Event.operator_id := 'SYSTEM';
L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;

IF GVL_STATE.G_System_Mode <> L_Last_System_Mode THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1101;
    L_History_Event.event_value := TO_REAL(TO_INT(GVL_STATE.G_System_Mode));
    L_History_Event.unit := 1;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_System_Mode := GVL_STATE.G_System_Mode;

ELSIF GVL_SYSTEM_HEALTH.G_First_Fault_Active
      AND (GVL_SYSTEM_HEALTH.G_Root_Cause <> L_Last_Root_Cause) THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1102;
    L_History_Event.event_value := TO_REAL(TO_INT(GVL_SYSTEM_HEALTH.G_Root_Cause));
    L_History_Event.unit := 2;
    L_History_Event.zone_id := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_Root_Cause := GVL_SYSTEM_HEALTH.G_Root_Cause;

ELSIF GVL_SYSTEM_HEALTH.G_First_Fault_Active
      AND (GVL_SYSTEM_HEALTH.G_First_Fault_Source <> L_Last_First_Fault_Source) THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1103;
    L_History_Event.event_value := TO_REAL(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.unit := 3;
    L_History_Event.zone_id := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_First_Fault_Source := GVL_SYSTEM_HEALTH.G_First_Fault_Source;

ELSIF GVL_STATUS.G_Current_Scenario <> GVL_STATUS.G_Previous_Scenario THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1001;
    L_History_Event.event_value := TO_REAL(GVL_STATUS.G_Current_Scenario);
    L_History_Event.unit := 4;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    GVL_STATUS.G_Previous_Scenario := GVL_STATUS.G_Current_Scenario;

ELSIF GVL_STATUS.G_Diagnostics.Alarm_Event_Pulse THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := TO_WORD(GVL_STATUS.G_Diagnostics.Alarm_Event_Code);
    L_History_Event.event_value := GVL_STATUS.G_Diagnostics.Alarm_Event_Value;
    L_History_Event.unit := 10;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;

ELSIF GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq <> L_Last_Operator_Journal_Seq THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1301;
    L_History_Event.event_value := TO_REAL(GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq);
    L_History_Event.unit := 20;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_Operator_Journal_Seq := GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq;
END_IF;

IF NOT GVL_SYSTEM_HEALTH.G_First_Fault_Active THEN
    L_Last_Root_Cause := GVL_SYSTEM_HEALTH.G_Root_Cause;
    L_Last_First_Fault_Source := GVL_SYSTEM_HEALTH.G_First_Fault_Source;
END_IF;

IF L_History_Write_Event THEN
    IF (L_History_Event.event_code = L_Last_Event_Code)
       AND (ABS(L_History_Event.event_value - L_Last_Event_Value) < 0.001)
       AND (GVL_TIME_SERVICE.G_Now_MS - L_Last_Event_Time_MS < 5000) THEN
        L_History_Write_Event := FALSE;
    ELSE
        L_Last_Event_Code := L_History_Event.event_code;
        L_Last_Event_Value := L_History_Event.event_value;
        L_Last_Event_Time_MS := GVL_TIME_SERVICE.G_Now_MS;
    END_IF;
END_IF;

fbHistoryManager(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Write_Event := L_History_Write_Event,
    VI_Event := L_History_Event
);

GVL_MAIN_PHASE_FEEDBACK.G_Current_Phase := 3;

PRG_IO_Read();
PRG_Input_Quality_Read();
PRG_Input_Processing();

PRG_Heating_Config_Defaults();

PRG_Mode_Manager();
PRG_Presence_Manager();
PRG_Safety_Selector();
PRG_Safety();
PRG_Safety_Operator();
PRG_Safety_Shutdown();
PRG_Safety_Recovery();
PRG_System_Intent();
PRG_Security();
PRG_System_Access_Maintenance();
PRG_User_Adapt_Control();
PRG_Behavior_Adapt_Profile();

PRG_Scenario_Engine();
PRG_System_Scenario_Rules();
PRG_System_Evacuation();
PRG_Policy();
PRG_Heating_Policy_Manager();
PRG_Heating_Policy_Observer();
PRG_System_Coordinator();
PRG_Command_Arbitration();

GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Executed := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Valid := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Status_Text := 'Input/safety/command phase executed';
GVL_MAIN_PHASE_FEEDBACK.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Main_Phase_03_Input_Safety_Command <<<

// CANONICAL EXECUTION DOMAIN
// PRESERVES EXECUTION ORDER

PRG_Distributed_Peer_Ingestion();
PRG_Distributed_Epoch_Governor();
PRG_Distributed_Snapshot_Governor();
PRG_Distributed_Runtime_Supervisor();
PRG_Distributed_Commit_Governor();

// Complete cleanup one cycle after publishing progress=1.0. This lets domain
// output managers consume the final restore state before snapshot invalidation.
IF GVL_AWAY_RESTORE.G_Restore_Finalize_Pending THEN
    GVL_AWAY_RESTORE.G_Restore_Active := FALSE;
    GVL_AWAY_RESTORE.G_Restore_Done := TRUE;
    GVL_AWAY_RESTORE.G_Snapshot_Valid := FALSE;
    GVL_AWAY_RESTORE.G_Restore_Finalize_Pending := FALSE;
    GVL_AWAY_RESTORE.G_Restore_Progress := 0.0;
END_IF;

L_Take_Snapshot :=
    GVL_POLICY.G_Away_Active AND
    (GVL_POLICY.G_Away_Level = 1) AND
    (NOT L_Away_Active_Prev);

IF L_Take_Snapshot THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_AWAY_RESTORE.G_Lighting_Levels[L_i] := GVL_STATE.G_Lighting_Levels[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
        GVL_AWAY_RESTORE.G_Socket_States[L_i] := GVL_STATE.G_Socket_States[L_i];
    END_FOR;

    GVL_AWAY_RESTORE.G_Snapshot_Valid := TRUE;
    GVL_AWAY_RESTORE.G_Snapshot_Taken_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_AWAY_RESTORE.G_Restore_Done := FALSE;
    GVL_AWAY_RESTORE.G_Restore_Finalize_Pending := FALSE;
END_IF;

L_Start_Restore :=
    GVL_POLICY.G_Away_Restore_Requested AND
    GVL_AWAY_RESTORE.G_Snapshot_Valid;

IF L_Start_Restore THEN
    GVL_AWAY_RESTORE.G_Restore_Active := TRUE;
    GVL_AWAY_RESTORE.G_Restore_Started_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_AWAY_RESTORE.G_Restore_Done := FALSE;
    GVL_AWAY_RESTORE.G_Restore_Finalize_Pending := FALSE;
END_IF;

IF GVL_AWAY_RESTORE.G_Restore_Active THEN
    GVL_AWAY_RESTORE.G_Restore_Progress := GVL_POLICY.G_Away_Restore_Progress;

    IF NOT GVL_POLICY.G_Away_Restore_Active THEN
        GVL_AWAY_RESTORE.G_Restore_Progress := 1.0;
        GVL_AWAY_RESTORE.G_Restore_Finalize_Pending := TRUE;
    END_IF;
ELSE
    IF NOT GVL_AWAY_RESTORE.G_Restore_Done THEN
        GVL_AWAY_RESTORE.G_Restore_Progress := 0.0;
    END_IF;
END_IF;

L_Away_Active_Prev := GVL_POLICY.G_Away_Active;
L_Away_Level_Prev := GVL_POLICY.G_Away_Level;

// Centralized tuning profile controller.
// This block enforces consistent adaptive behavior settings.

CASE GVL_BEHAVIOR_ADAPT.G_Adapt_Profile OF

    ADAPT_PROFILE_STABLE:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.03;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.03;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.998;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 7;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 0.9;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

    ADAPT_PROFILE_BALANCED:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.05;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.05;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.995;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 5;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

    ADAPT_PROFILE_AGGRESSIVE:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.08;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.08;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.990;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 3;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 1.1;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

ELSE
        // No fallback required
END_CASE;

// >>> BULK_SYNC_ANCHOR: PRG_Behavior_Adapt_Profile <<<

// HMI per-circuit profile update.
IF GVL_AWAY_HEATING_HMI.G_Set_Circuit_Profile_Req THEN
    L_Circuit := GVL_AWAY_HEATING_HMI.G_Profile_Circuit;

    IF (L_Circuit >= 1) AND (L_Circuit <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
        IF (GVL_AWAY_HEATING_HMI.G_Profile_Comfort_Temp >= REAL#5.0) AND
           (GVL_AWAY_HEATING_HMI.G_Profile_Comfort_Temp <= REAL#30.0) AND
           (GVL_AWAY_HEATING_HMI.G_Profile_Economy_Temp >= REAL#5.0) AND
           (GVL_AWAY_HEATING_HMI.G_Profile_Economy_Temp <= GVL_AWAY_HEATING_HMI.G_Profile_Comfort_Temp) AND
           (GVL_AWAY_HEATING_HMI.G_Profile_Long_Away_Temp >= REAL#5.0) AND
           (GVL_AWAY_HEATING_HMI.G_Profile_Long_Away_Temp <= GVL_AWAY_HEATING_HMI.G_Profile_Economy_Temp) THEN

            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].use_in_normal := GVL_AWAY_HEATING_HMI.G_Profile_Use_In_Normal;
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].use_in_away_preheat := GVL_AWAY_HEATING_HMI.G_Profile_Use_In_Away_Preheat;
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].comfort_temp := GVL_AWAY_HEATING_HMI.G_Profile_Comfort_Temp;
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].economy_temp := GVL_AWAY_HEATING_HMI.G_Profile_Economy_Temp;
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].long_away_temp := GVL_AWAY_HEATING_HMI.G_Profile_Long_Away_Temp;
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].design_temp := GVL_AWAY_HEATING_HMI.G_Profile_Comfort_Temp;

            GVL_AWAY_HEATING_HMI.G_Last_Error := FALSE;
            GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Away heating profile applied';
        ELSE
            GVL_AWAY_HEATING_HMI.G_Last_Error := TRUE;
            GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Away heating profile rejected: invalid temperatures';
        END_IF;
    ELSE
        GVL_AWAY_HEATING_HMI.G_Last_Error := TRUE;
        GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Away heating profile rejected: invalid circuit';
    END_IF;

    GVL_AWAY_HEATING_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_AWAY_HEATING_HMI.G_Set_Circuit_Profile_Req := FALSE;
END_IF;

// Gateway compatibility: CMD_SET_TEMP updates comfort temperature for one circuit.
IF GVL_INTENT_USER.I_Set_Temp_Req THEN
    L_Circuit := GVL_INTENT_USER.I_Target_Zone;

    IF (L_Circuit >= 1) AND (L_Circuit <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) AND
       (GVL_INTENT_USER.I_Target_Temperature >= REAL#5.0) AND
       (GVL_INTENT_USER.I_Target_Temperature <= REAL#30.0) THEN
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].comfort_temp := GVL_INTENT_USER.I_Target_Temperature;
        GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].design_temp := GVL_INTENT_USER.I_Target_Temperature;

        IF GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].economy_temp <= REAL#0.0 THEN
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].economy_temp := GVL_INTENT_USER.I_Target_Temperature - REAL#3.0;
        END_IF;

        IF GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].long_away_temp <= REAL#0.0 THEN
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_Circuit].long_away_temp := GVL_POLICY.G_Away_Long_Economy_Setpoint_C;
        END_IF;
    END_IF;
END_IF;

// HMI planned return update. Delay is relative to current monotonic PLC time.
IF GVL_AWAY_HEATING_HMI.G_Set_Planned_Return_Req THEN
    IF GVL_AWAY_HEATING_HMI.G_Planned_Return_Enabled AND (GVL_AWAY_HEATING_HMI.G_Planned_Return_Delay_Hours > REAL#0.0) THEN
        L_Delay_MS := REAL_TO_UDINT(GVL_AWAY_HEATING_HMI.G_Planned_Return_Delay_Hours * REAL#3600000.0);
        L_Preheat_Lead_MS := REAL_TO_UDINT(GVL_AWAY_HEATING_HMI.G_Preheat_Lead_Hours * REAL#3600000.0);
        L_Return_Grace_MS := REAL_TO_UDINT(GVL_AWAY_HEATING_HMI.G_Return_Grace_Hours * REAL#3600000.0);

        IF L_Preheat_Lead_MS = 0 THEN
            L_Preheat_Lead_MS := 10800000;
        END_IF;
        IF L_Return_Grace_MS = 0 THEN
            L_Return_Grace_MS := 86400000;
        END_IF;

        GVL_POLICY.G_Away_Planned_Return_Enabled := TRUE;
        GVL_POLICY.G_Away_Planned_Return_MS := GVL_TIME_SERVICE.G_Now_MS + L_Delay_MS;
        GVL_POLICY.G_Away_Preheat_Lead_MS := L_Preheat_Lead_MS;
        GVL_POLICY.G_Away_Return_Grace_MS := L_Return_Grace_MS;
        GVL_POLICY.G_Away_Return_Expired := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;

        GVL_AWAY_HEATING_HMI.G_Last_Error := FALSE;
        GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Planned return configured';
    ELSE
        GVL_POLICY.G_Away_Planned_Return_Enabled := FALSE;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
        GVL_POLICY.G_Away_Return_Expired := FALSE;

        GVL_AWAY_HEATING_HMI.G_Last_Error := FALSE;
        GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Planned return disabled';
    END_IF;

    GVL_AWAY_HEATING_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_AWAY_HEATING_HMI.G_Set_Planned_Return_Req := FALSE;
END_IF;

IF GVL_AWAY_HEATING_HMI.G_Clear_Planned_Return_Req THEN
    GVL_POLICY.G_Away_Planned_Return_Enabled := FALSE;
    GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
    GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
    GVL_POLICY.G_Away_Return_Expired := FALSE;
    GVL_AWAY_HEATING_HMI.G_Last_Error := FALSE;
    GVL_AWAY_HEATING_HMI.G_Last_Status_Text := 'Planned return cleared';
    GVL_AWAY_HEATING_HMI.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
    GVL_AWAY_HEATING_HMI.G_Clear_Planned_Return_Req := FALSE;
END_IF;

// Gateway compatibility: CMD_SET_CONFIG with target_zone=0 configures/clears planned return.
IF GVL_INTENT_USER.I_Set_Config_Req AND
   (GVL_GATEWAY.G_Gateway_Command.command_type = E_Gateway_Command_Type.CMD_SET_CONFIG) AND
   (GVL_GATEWAY.G_Gateway_Command.target_zone = 0) THEN
    IF GVL_GATEWAY.G_Gateway_Command.target_on_off AND (GVL_GATEWAY.G_Gateway_Command.target_value > REAL#0.0) THEN
        L_Delay_MS := REAL_TO_UDINT(GVL_GATEWAY.G_Gateway_Command.target_value * REAL#3600000.0);
        GVL_POLICY.G_Away_Planned_Return_Enabled := TRUE;
        GVL_POLICY.G_Away_Planned_Return_MS := GVL_TIME_SERVICE.G_Now_MS + L_Delay_MS;
        GVL_POLICY.G_Away_Return_Expired := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
    ELSE
        GVL_POLICY.G_Away_Planned_Return_Enabled := FALSE;
        GVL_POLICY.G_Away_Return_Preheat_Active := FALSE;
        GVL_POLICY.G_Away_Return_Grace_Active := FALSE;
        GVL_POLICY.G_Away_Return_Expired := FALSE;
    END_IF;
END_IF;

// ==============================================================================
// WATER OUTPUT PROJECTION — deterministic water output runtime boundary.
// ==============================================================================
// Runtime-critical projection/convergence path is separated from observability.
// No authority ownership or command-shadow writes are introduced here.
// ==============================================================================

PRG_Water_Output_Projection_Phase_01_Runtime();
PRG_Water_Output_Projection_Phase_02_Observability();

// Runtime bridge integrated in PRG_Water.
// This PRG remains the deterministic projection boundary.

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Energy_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Valid := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Granted := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Quarantine_Active := TRUE;

GVL_ENERGY_CAUSALITY_FABRIC.Hydraulic_Energy_State_Valid := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Thermal_Energy_State_Valid := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Electrical_Load_State_Valid := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Motor_Energy_Envelope_Valid := FALSE;
GVL_ENERGY_CAUSALITY_FABRIC.Distributed_Load_Coherent := FALSE;

// Actuator semantic verification required.
IF NOT GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Semantic_Verification_Granted THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37000;
    L_Error_Text := 'Actuator semantic verification not granted';
END_IF;

// Energy divergence detectors.
IF GVL_ENERGY_CAUSALITY_FABRIC.DryRun_Energy_State_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37001;
    L_Error_Text := 'Dry-run energy state detected';
END_IF;

IF GVL_ENERGY_CAUSALITY_FABRIC.Thermal_Extraction_Divergence_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37002;
    L_Error_Text := 'Thermal extraction divergence detected';
END_IF;

IF GVL_ENERGY_CAUSALITY_FABRIC.Load_Synchronization_Spike_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37003;
    L_Error_Text := 'Load synchronization spike detected';
END_IF;

IF GVL_ENERGY_CAUSALITY_FABRIC.Hydraulic_Energy_Starvation_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37004;
    L_Error_Text := 'Hydraulic energy starvation detected';
END_IF;

IF GVL_ENERGY_CAUSALITY_FABRIC.Distributed_Transient_Overload_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37005;
    L_Error_Text := 'Distributed transient overload detected';
END_IF;

IF GVL_ENERGY_CAUSALITY_FABRIC.Energy_Recovery_Instability_Detected THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37006;
    L_Error_Text := 'Energy recovery instability detected';
END_IF;

// Stable energy envelope validation.
IF L_Energy_Valid
AND NOT GVL_ENERGY_CAUSALITY_FABRIC.Energy_Envelope_Stable THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37010;
    L_Error_Text := 'Energy envelope unstable';
END_IF;

IF L_Energy_Valid
AND NOT GVL_ENERGY_CAUSALITY_FABRIC.Transient_Load_Stable THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37011;
    L_Error_Text := 'Transient load stability invalid';
END_IF;

IF L_Energy_Valid
AND NOT GVL_ENERGY_CAUSALITY_FABRIC.Thermal_Accumulation_Stable THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37012;
    L_Error_Text := 'Thermal accumulation unstable';
END_IF;

IF L_Energy_Valid
AND NOT GVL_ENERGY_CAUSALITY_FABRIC.Recovery_Energy_Coherent THEN
    L_Energy_Valid := FALSE;
    L_Error_Code := 37013;
    L_Error_Text := 'Recovery energy coherence invalid';
END_IF;

IF L_Energy_Valid THEN
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Valid := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Granted := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Quarantine_Active := FALSE;

    GVL_ENERGY_CAUSALITY_FABRIC.Hydraulic_Energy_State_Valid := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Thermal_Energy_State_Valid := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Electrical_Load_State_Valid := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Motor_Energy_Envelope_Valid := TRUE;
    GVL_ENERGY_CAUSALITY_FABRIC.Distributed_Load_Coherent := TRUE;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Epoch :=
        GVL_ACTUATOR_SEMANTIC_VERIFICATION.Actuator_Verification_Epoch;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Epoch_Coherent := TRUE;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Last_Update_MS :=
        L_Now_MS;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Lease_Expired := FALSE;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Last_Error_Code := 0;
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Last_Error_Text := '';
ELSE
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Valid := FALSE;
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Granted := FALSE;
    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Quarantine_Active := TRUE;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Lease_Expired := TRUE;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Last_Error_Code :=
        L_Error_Code;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Last_Error_Text :=
        L_Error_Text;

    GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Invalidation_Count :=
        GVL_ENERGY_CAUSALITY_FABRIC.Energy_Causality_Invalidation_Count + 1;
END_IF;

// ======================================================
// SAFE READ-ONLY MODBUS REGISTER SCAN
// ======================================================
// Safety rules:
//   - FC03/FC04 only.
//   - Never write registers.
//   - Manual enable only.
//   - Limited scan range.
// ======================================================

IF NOT GVL_MODBUS_SCAN.G_Scan_Enable THEN
    GVL_MODBUS_SCAN.G_Scan_Active := FALSE;
    GVL_MODBUS_SCAN.G_Scan_Done := FALSE;
    RETURN;
END_IF;

GVL_MODBUS_SCAN.G_Scan_Active := TRUE;
GVL_MODBUS_SCAN.G_Scan_Error := FALSE;

IF GVL_MODBUS_SCAN.G_Current_Register < GVL_MODBUS_SCAN.G_Start_Register THEN
    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Start_Register;
END_IF;

IF GVL_MODBUS_SCAN.G_Current_Register > GVL_MODBUS_SCAN.G_End_Register THEN
    GVL_MODBUS_SCAN.G_Scan_Active := FALSE;
    GVL_MODBUS_SCAN.G_Scan_Done := TRUE;
    RETURN;
END_IF;

L_Register := GVL_MODBUS_SCAN.G_Current_Register;

// ======================================================
// Issue read-only FC03 request
// ======================================================
GVL_MODBUS_MASTER.G_Request[16].Enable := TRUE;
GVL_MODBUS_MASTER.G_Request[16].Slave_ID := GVL_MODBUS_SCAN.G_Slave_ID;
GVL_MODBUS_MASTER.G_Request[16].Function_Code := MB_FC03_READ_HOLDING_REGISTERS;
GVL_MODBUS_MASTER.G_Request[16].Start_Register := L_Register;
GVL_MODBUS_MASTER.G_Request[16].Register_Count := 1;
GVL_MODBUS_MASTER.G_Request[16].Sequence :=
    GVL_MODBUS_MASTER.G_Request[16].Sequence + 1;
GVL_MODBUS_MASTER.G_Request[16].Timeout_MS := 250;

// ======================================================
// Process response
// ======================================================
IF GVL_MODBUS_MASTER.G_Response[16].Done THEN

    GVL_MODBUS_SCAN.G_Found_Register[L_Register] := TRUE;

    GVL_MODBUS_SCAN.G_Found_Value[L_Register] :=
        GVL_MODBUS_MASTER.G_Response[16].Read_Value[1];

    GVL_MODBUS_SCAN.G_Last_Scan_MS := GVL_STATUS.G_System_Time_MS;

    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Current_Register + 1;

ELSIF GVL_MODBUS_MASTER.G_Response[16].Error THEN

    GVL_MODBUS_SCAN.G_Found_Register[L_Register] := FALSE;

    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Current_Register + 1;

END_IF;

L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Recovery := GVL_SAFETY_RECOVERY.G_Recovery_Phase;

GVL_EXPLAINABILITY.G_Last_Safety_Mode := L_Mode;
GVL_EXPLAINABILITY.G_Last_Recovery_Phase := L_Recovery;
GVL_EXPLAINABILITY.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

CASE L_Mode OF
    FIRE: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'FIRE';
    GAS: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GAS';
    WATER_LEAK: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'WATER';
    GLOBAL_STOP: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GLOBAL_STOP';
    ELSE
        IF GVL_SAFETY_RECOVERY.G_Recovery_Active OR (GVL_SAFETY_RECOVERY.G_Recovery_Phase <> IDLE) THEN
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'RECOVERY';
        ELSE
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'NORMAL';
        END_IF;
END_CASE;

GVL_EXPLAINABILITY.G_Reason_Chain_Behavior := GVL_INTENT_BEHAVIOR.I_Reason_Text;

IF GVL_COMMAND_SHADOW.G_Heating_Block THEN
    L_Command := 'Heating Blocked';
ELSIF GVL_COMMAND_SHADOW.G_Vent_Stop THEN
    L_Command := 'Vent Stopped';
ELSIF GVL_COMMAND_SHADOW.G_Water_Block THEN
    L_Command := 'Water Blocked';
ELSE
    L_Command := 'Command OK';
END_IF;
GVL_EXPLAINABILITY.G_Reason_Chain_Command := L_Command;

IF GVL_STATE.G_Heating_RootCause <> E_Heating_RootCause.RC_NONE THEN
    L_Heating := GVL_STATE.G_Heating_Confidence_Reason_Text;
ELSIF GVL_STATE.G_Heating_Cascade_Degraded THEN
    L_Heating := 'Heating cascade degraded';
ELSE
    L_Heating := 'Heating OK';
END_IF;
GVL_EXPLAINABILITY.G_Heating_Why_Blocked := L_Heating;

IF GVL_COMMAND_VERIFY.PreOutput_Block_IO THEN
    L_Output := 'Outputs held by PreOutput barrier';
ELSIF GVL_SAFETY_RECOVERY.G_Recovery_Phase <> IDLE THEN
    L_Output := 'Outputs held during recovery';
ELSIF GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid THEN
    L_Output := 'Outputs applied with IO validation mismatch';
ELSE
    L_Output := 'Outputs Applied';
END_IF;
GVL_EXPLAINABILITY.G_Reason_Chain_Output := L_Output;

GVL_EXPLAINABILITY.G_Reason_Chain_Full := CONCAT(
    CONCAT(
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety,
            ' -> '
        ),
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Behavior,
            ' -> '
        )
    ),
    CONCAT(
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Command,
            ' -> '
        ),
        CONCAT(
            L_Heating,
            CONCAT(' -> ', L_Output)
        )
    )
);

GVL_EXPLAINABILITY.G_Behavior_Why_Active := GVL_INTENT_BEHAVIOR.I_Reason_Text;

IF GVL_EXECUTION_PROGRESS_CAUSALITY_FABRIC.Execution_Progress_Causality_Granted
AND NOT GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Resource_Starvation_Detected
AND NOT GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Scheduler_Starvation_Detected
AND NOT GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Distributed_Allocation_Deadlock_Detected THEN

    GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Resource_Starvation_Boundary_Valid := TRUE;
    GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Resource_Starvation_Boundary_Granted := TRUE;
    GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Resource_Starvation_Bounded := TRUE;
    GVL_RESOURCE_STARVATION_BOUNDARY_FABRIC.Fair_Execution_Scheduling_Valid := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Commit_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// SEMANTIC PUBLICATION COMMIT GOVERNOR
// ======================================================
// Governs semantic publication checkpoint coherence.
// Downstream/publication continuity only.
// Does not invalidate runtime barrier, PLC fencing,
// immutable snapshots, distributed commit or IO authority.
// ======================================================

GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Mismatch := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Commit_Mismatch := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Rollback_Detected := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Replay_Fenced := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Missing := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := FALSE;

// ------------------------------------------------------
// Semantic checkpoint epoch progression.
// ------------------------------------------------------

GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch :=
    GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch + 1;

GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch :=
    GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch + 1;

// ------------------------------------------------------
// Rollback/replay fencing foundation.
// ------------------------------------------------------

IF GVL_SEMANTIC_COMMIT.Peer_Semantic_Checkpoint_Epoch
< GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch THEN
    GVL_SEMANTIC_COMMIT.Semantic_Rollback_Detected := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Replay_Fenced := TRUE;

    L_Commit_Valid := FALSE;
    L_Error_Code := 18000;
    L_Error_Text := 'Semantic rollback detected';
END_IF;

// ------------------------------------------------------
// Checkpoint acknowledgement foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    IF NOT GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Ack_Valid THEN
        GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Missing := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18001;
        L_Error_Text := 'Semantic checkpoint acknowledgement missing';
    END_IF;
END_IF;

// ------------------------------------------------------
// Semantic checkpoint mismatch foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    IF GVL_SEMANTIC_COMMIT.Peer_Semantic_Commit_Epoch
    <> GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch THEN
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Mismatch := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18002;
        L_Error_Text := 'Semantic commit mismatch detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Semantic commit lease freshness.
// ------------------------------------------------------

L_Delta_MS :=
    L_Now_MS - GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Refresh_MS;

IF L_Commit_Valid
AND GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Active THEN
    IF L_Delta_MS > GVL_SEMANTIC_COMMIT.Semantic_Commit_Timeout_MS THEN
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18003;
        L_Error_Text := 'Semantic commit lease expired';
    END_IF;
END_IF;

// ------------------------------------------------------
// Publish semantic commit coherence foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Publication_Commit_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Publication_Commit_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Valid := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Active := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := FALSE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Quarantine_Active := FALSE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Forced_Safe_Mode := FALSE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Refresh_MS := L_Now_MS;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Code := 0;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Valid := FALSE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Quarantine_Active := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Forced_Safe_Mode := TRUE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Code := L_Error_Code;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Text := L_Error_Text;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Invalidation_Count :=
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Epoch_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid := FALSE;
GVL_PHYSICAL_AUTHORITY_EPOCH.Snapshot_Epoch_Coherent := FALSE;
GVL_PHYSICAL_AUTHORITY_EPOCH.Consensus_Epoch_Coherent := FALSE;
GVL_PHYSICAL_AUTHORITY_EPOCH.Causality_Epoch_Coherent := FALSE;
GVL_PHYSICAL_AUTHORITY_EPOCH.PreOutput_Epoch_Coherent := FALSE;

L_Global_Epoch := GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Epoch;

// Snapshot epoch is the authoritative physical world epoch.
IF GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Epoch = 0 THEN
    L_Epoch_Valid := FALSE;
    L_Error_Code := 24000;
    L_Error_Text := 'Physical snapshot epoch invalid';
END_IF;

// Consensus must validate the same immutable world.
IF L_Epoch_Valid
AND (GVL_SENSOR_CONSENSUS.Sensor_Consensus_Epoch <> L_Global_Epoch) THEN
    GVL_PHYSICAL_AUTHORITY_EPOCH.Cross_Cycle_Epoch_Skew_Detected := TRUE;

    L_Epoch_Valid := FALSE;
    L_Error_Code := 24001;
    L_Error_Text := 'Sensor consensus epoch skew detected';
END_IF;

// Telemetry causality must validate the same immutable world.
IF L_Epoch_Valid
AND (GVL_TELEMETRY.Telemetry_Epoch <> L_Global_Epoch) THEN
    GVL_PHYSICAL_AUTHORITY_EPOCH.Cross_Cycle_Epoch_Skew_Detected := TRUE;

    L_Epoch_Valid := FALSE;
    L_Error_Code := 24002;
    L_Error_Text := 'Telemetry epoch skew detected';
END_IF;

// Output publication epoch must remain coherent.
IF L_Epoch_Valid
AND (GVL_OUTPUT_EPOCH.Output_Publication_Epoch <> L_Global_Epoch) THEN
    GVL_PHYSICAL_AUTHORITY_EPOCH.Partial_Epoch_Advancement_Detected := TRUE;

    L_Epoch_Valid := FALSE;
    L_Error_Code := 24003;
    L_Error_Text := 'Output publication epoch skew detected';
END_IF;

IF L_Epoch_Valid
AND GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Epoch_Replay_Suspected THEN
    L_Epoch_Valid := FALSE;
    L_Error_Code := 24004;
    L_Error_Text := 'Physical authority epoch replay suspected';
END_IF;

IF L_Epoch_Valid
AND GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Epoch_Drift_Detected THEN
    L_Epoch_Valid := FALSE;
    L_Error_Code := 24005;
    L_Error_Text := 'Physical authority epoch drift detected';
END_IF;

IF L_Epoch_Valid THEN
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch := L_Global_Epoch;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid := TRUE;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Snapshot_Epoch_Coherent := TRUE;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Consensus_Epoch_Coherent := TRUE;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Causality_Epoch_Coherent := TRUE;
    GVL_PHYSICAL_AUTHORITY_EPOCH.PreOutput_Epoch_Coherent := TRUE;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Lease_Expired := FALSE;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Quarantine_Active := FALSE;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Last_Update_MS := L_Now_MS;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Last_Error_Code := 0;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Last_Error_Text := '';
ELSE
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid := FALSE;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Lease_Expired := TRUE;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Quarantine_Active := TRUE;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Last_Error_Code := L_Error_Code;
    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Last_Error_Text := L_Error_Text;

    GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Invalidation_Count :=
        GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Observability_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// Fail-safe defaults.
GVL_OBSERVABILITY_TRUTH.Observability_Truth_Valid := FALSE;
GVL_OBSERVABILITY_TRUTH.Observability_Truth_Granted := FALSE;
GVL_OBSERVABILITY_TRUTH.Observability_Truth_Quarantine_Active := TRUE;

GVL_OBSERVABILITY_TRUTH.HMI_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_TRUTH.Alarm_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_TRUTH.Trend_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_TRUTH.Diagnostics_Authority_Coherent := FALSE;
GVL_OBSERVABILITY_TRUTH.History_Authority_Coherent := FALSE;

// Semantic continuity authority required.
IF NOT GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Granted THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32000;
    L_Error_Text := 'Semantic continuity authority not granted';
END_IF;

// Observability split-brain detectors.
IF GVL_OBSERVABILITY_TRUTH.Stale_HMI_Epoch_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32001;
    L_Error_Text := 'Stale HMI epoch detected';
END_IF;

IF GVL_OBSERVABILITY_TRUTH.Alarm_Publication_Lag_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32002;
    L_Error_Text := 'Alarm publication lag detected';
END_IF;

IF GVL_OBSERVABILITY_TRUTH.Trend_Causality_Skew_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32003;
    L_Error_Text := 'Trend causality skew detected';
END_IF;

IF GVL_OBSERVABILITY_TRUTH.Diagnostic_Truth_Race_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32004;
    L_Error_Text := 'Diagnostic truth race detected';
END_IF;

IF GVL_OBSERVABILITY_TRUTH.Operator_Visibility_Fragmentation_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32005;
    L_Error_Text := 'Operator visibility fragmentation detected';
END_IF;

IF GVL_OBSERVABILITY_TRUTH.Authority_UI_Divergence_Detected THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32006;
    L_Error_Text := 'Authority/UI divergence detected';
END_IF;

// Projection causality validation.
IF L_Observability_Valid
AND NOT GVL_OBSERVABILITY_TRUTH.HMI_Epoch_Coherent THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32010;
    L_Error_Text := 'HMI epoch coherence invalid';
END_IF;

IF L_Observability_Valid
AND NOT GVL_OBSERVABILITY_TRUTH.Alarm_Publication_Coherent THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32011;
    L_Error_Text := 'Alarm publication coherence invalid';
END_IF;

IF L_Observability_Valid
AND NOT GVL_OBSERVABILITY_TRUTH.Trend_Causality_Coherent THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32012;
    L_Error_Text := 'Trend causality coherence invalid';
END_IF;

IF L_Observability_Valid
AND NOT GVL_OBSERVABILITY_TRUTH.Diagnostics_Causality_Coherent THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32013;
    L_Error_Text := 'Diagnostics causality coherence invalid';
END_IF;

IF L_Observability_Valid
AND NOT GVL_OBSERVABILITY_TRUTH.Operator_Visibility_Consistent THEN
    L_Observability_Valid := FALSE;
    L_Error_Code := 32014;
    L_Error_Text := 'Operator visibility consistency invalid';
END_IF;

IF L_Observability_Valid THEN
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Valid := TRUE;
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Granted := TRUE;
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Quarantine_Active := FALSE;

    GVL_OBSERVABILITY_TRUTH.HMI_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_TRUTH.Alarm_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_TRUTH.Trend_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_TRUTH.Diagnostics_Authority_Coherent := TRUE;
    GVL_OBSERVABILITY_TRUTH.History_Authority_Coherent := TRUE;

    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Epoch :=
        GVL_SEMANTIC_CONTINUITY.Semantic_Continuity_Epoch;

    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Epoch_Coherent := TRUE;

    GVL_OBSERVABILITY_TRUTH.Observability_Last_Update_MS := L_Now_MS;
    GVL_OBSERVABILITY_TRUTH.Observability_Lease_Expired := FALSE;

    GVL_OBSERVABILITY_TRUTH.Observability_Last_Error_Code := 0;
    GVL_OBSERVABILITY_TRUTH.Observability_Last_Error_Text := '';
ELSE
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Valid := FALSE;
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Granted := FALSE;
    GVL_OBSERVABILITY_TRUTH.Observability_Truth_Quarantine_Active := TRUE;

    GVL_OBSERVABILITY_TRUTH.Observability_Lease_Expired := TRUE;

    GVL_OBSERVABILITY_TRUTH.Observability_Last_Error_Code :=
        L_Error_Code;

    GVL_OBSERVABILITY_TRUTH.Observability_Last_Error_Text :=
        L_Error_Text;

    GVL_OBSERVABILITY_TRUTH.Observability_Invalidation_Count :=
        GVL_OBSERVABILITY_TRUTH.Observability_Invalidation_Count + 1;
END_IF;

// ==============================================================================
// CONFIG STAGED CHANGE MONITOR
// ==============================================================================
// Tracks generic staged config fields controlled by GVL_CONFIG_CONTROL. When any
// staged value changes, the staged config version is incremented so HMI validation
// cannot be reused for a different draft.
// ==============================================================================


L_Changed := FALSE;

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
ELSE
    IF L_Last_STG_Reputation_Learning_Rate <> GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_Reputation_Recovery_Decay <> GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_Min_Sensor_Confidence <> GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_Bad_Spike_Confidence <> GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_Default_Confidence <> GVL_CONFIG_CONTROL.STG_Default_Confidence THEN L_Changed := TRUE; END_IF;

    IF L_Last_STG_Night_Start_Hour <> GVL_CONFIG_CONTROL.STG_Night_Start_Hour THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_Night_End_Hour <> GVL_CONFIG_CONTROL.STG_Night_End_Hour THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_VentBoost_Humidity_Threshold <> GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold THEN L_Changed := TRUE; END_IF;

    IF L_Last_STG_Stabilization_Delay_MS <> GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS THEN L_Changed := TRUE; END_IF;

    IF L_Last_STG_PLC_Inactive_Close_Gas <> GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_PLC_Inactive_Stop_Boiler <> GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_PLC_Inactive_Block_Heating <> GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_PLC_Inactive_Stop_Vent <> GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent THEN L_Changed := TRUE; END_IF;
    IF L_Last_STG_PLC_Inactive_Block_Water <> GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water THEN L_Changed := TRUE; END_IF;
END_IF;

IF L_Changed THEN
    GVL_CONFIG_CONTROL.G_Staged_Config_Version := GVL_CONFIG_CONTROL.G_Staged_Config_Version + 1;
    GVL_CONFIG_CONTROL.G_Staged_Last_Changed_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

L_Last_STG_Reputation_Learning_Rate := GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate;
L_Last_STG_Reputation_Recovery_Decay := GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay;
L_Last_STG_Min_Sensor_Confidence := GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence;
L_Last_STG_Bad_Spike_Confidence := GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence;
L_Last_STG_Default_Confidence := GVL_CONFIG_CONTROL.STG_Default_Confidence;

L_Last_STG_Night_Start_Hour := GVL_CONFIG_CONTROL.STG_Night_Start_Hour;
L_Last_STG_Night_End_Hour := GVL_CONFIG_CONTROL.STG_Night_End_Hour;
L_Last_STG_VentBoost_Humidity_Threshold := GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold;

L_Last_STG_Stabilization_Delay_MS := GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS;

L_Last_STG_PLC_Inactive_Close_Gas := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas;
L_Last_STG_PLC_Inactive_Stop_Boiler := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler;
L_Last_STG_PLC_Inactive_Block_Heating := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating;
L_Last_STG_PLC_Inactive_Stop_Vent := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent;
L_Last_STG_PLC_Inactive_Block_Water := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water;

// >>> BULK_SYNC_ANCHOR: PRG_Config_Staged_Change_Monitor <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// Fail-safe defaults.
GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active := FALSE;
GVL_AUTHORITY_REVOCATION.Authority_Revocation_Propagated := FALSE;
GVL_AUTHORITY_REVOCATION.Authority_Fail_Closed_Valid := FALSE;
GVL_AUTHORITY_REVOCATION.Revocation_Order_Valid := FALSE;

// Detect upstream authority invalidation.
GVL_AUTHORITY_REVOCATION.Snapshot_Authority_Revoked :=
    NOT GVL_PHYSICAL_SNAPSHOT.Physical_Snapshot_Valid;

GVL_AUTHORITY_REVOCATION.Sensor_Consensus_Authority_Revoked :=
    NOT GVL_SENSOR_CONSENSUS.Sensor_Consensus_Valid;

GVL_AUTHORITY_REVOCATION.Telemetry_Causality_Authority_Revoked :=
    NOT GVL_TELEMETRY.Command_Telemetry_Causality_Valid;

GVL_AUTHORITY_REVOCATION.Physical_Authority_Epoch_Revoked :=
    NOT GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch_Valid;

GVL_AUTHORITY_REVOCATION.Authority_Lineage_Revoked :=
    NOT GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid;

L_Revocation_Required :=
    GVL_AUTHORITY_REVOCATION.Snapshot_Authority_Revoked
    OR GVL_AUTHORITY_REVOCATION.Sensor_Consensus_Authority_Revoked
    OR GVL_AUTHORITY_REVOCATION.Telemetry_Causality_Authority_Revoked
    OR GVL_AUTHORITY_REVOCATION.Physical_Authority_Epoch_Revoked
    OR GVL_AUTHORITY_REVOCATION.Authority_Lineage_Revoked;

IF L_Revocation_Required THEN
    GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active := TRUE;
    GVL_AUTHORITY_REVOCATION.Quarantine_Fabric_Active := TRUE;

    GVL_AUTHORITY_REVOCATION.PreOutput_Authority_Revoked := TRUE;
    GVL_AUTHORITY_REVOCATION.Physical_IO_Release_Denied := TRUE;

    GVL_AUTHORITY_REVOCATION.Authority_Revocation_Propagated := TRUE;
    GVL_AUTHORITY_REVOCATION.Authority_Fail_Closed_Valid := TRUE;
    GVL_AUTHORITY_REVOCATION.Revocation_Order_Valid := TRUE;

    GVL_AUTHORITY_REVOCATION.Revocation_Epoch :=
        GVL_PHYSICAL_AUTHORITY_EPOCH.Physical_Authority_Epoch;

    GVL_AUTHORITY_REVOCATION.Revocation_Last_Update_MS := L_Now_MS;
ELSE
    GVL_AUTHORITY_REVOCATION.Authority_Revocation_Active := FALSE;
    GVL_AUTHORITY_REVOCATION.Quarantine_Fabric_Active := FALSE;

    GVL_AUTHORITY_REVOCATION.PreOutput_Authority_Revoked := FALSE;
    GVL_AUTHORITY_REVOCATION.Physical_IO_Release_Denied := FALSE;

    GVL_AUTHORITY_REVOCATION.Authority_Revocation_Propagated := FALSE;
    GVL_AUTHORITY_REVOCATION.Authority_Fail_Closed_Valid := TRUE;
    GVL_AUTHORITY_REVOCATION.Revocation_Order_Valid := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Runtime_OK := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// AUTHORITATIVE RUNTIME BARRIER
// ======================================================
// Creates authoritative runtime publication semantics.
// Rejects impossible runtime states before physical publication.
//
// Runtime authority remains:
// - monotonic-time authoritative;
// - PLC fencing authoritative;
// - transport freshness authoritative.
//
// Finalized distributed commit continuity is allowed
// as upstream authority evidence.
//
// Semantic continuity intentionally remains downstream
// to avoid primordial semantic/runtime recursion.
// ======================================================

GVL_RUNTIME_EPOCH.Runtime_Cycle_Start_MS := L_Now_MS;
GVL_RUNTIME_EPOCH.Runtime_Snapshot_Published := FALSE;
GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected := FALSE;
GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed := FALSE;

IF NOT GVL_TIME_MONOTONIC.Monotonic_Time_Initialized THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4900;
    L_Error_Text := 'Monotonic time not initialized';
END_IF;

IF L_Runtime_OK AND (NOT GVL_TIME_MONOTONIC.Monotonic_Time_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4901;
    L_Error_Text := 'Monotonic time invalid';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Startup_Quarantine_Active THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4902;
    L_Error_Text := 'Startup quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Time_Rollback_Detected THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4903;
    L_Error_Text := 'Monotonic rollback detected';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Retained_Time_Invalid THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4904;
    L_Error_Text := 'Retained monotonic time invalid';
END_IF;

IF L_Runtime_OK AND (GVL_TIME_MONOTONIC.Boot_Generation_ID = 0) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4905;
    L_Error_Text := 'Boot generation missing';
END_IF;

IF L_Runtime_OK AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5000;
    L_Error_Text := 'Runtime barrier inactive PLC';
END_IF;

IF L_Runtime_OK AND (NOT GVL_PLC_FENCING.PLC_Ownership_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5010;
    L_Error_Text := 'PLC ownership invalid';
END_IF;

IF L_Runtime_OK AND (NOT GVL_PLC_FENCING.PLC_Semantic_Authority_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5011;
    L_Error_Text := 'PLC semantic authority invalid';
END_IF;

IF L_Runtime_OK AND GVL_PLC_FENCING.PLC_Forced_Safe_Quarantine THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5012;
    L_Error_Text := 'PLC fencing quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_PLC_FENCING.PLC_Lease_Expired THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5013;
    L_Error_Text := 'PLC authority lease expired';
END_IF;

IF L_Runtime_OK AND (GVL_PLC_FENCING.PLC_Fencing_Token = 0) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5014;
    L_Error_Text := 'PLC fencing token missing';
END_IF;

IF L_Runtime_OK AND (NOT GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5200;
    L_Error_Text := 'Transport freshness invalid';
END_IF;

IF L_Runtime_OK AND (NOT GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5201;
    L_Error_Text := 'Transport publication blocked';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5202;
    L_Error_Text := 'Transport quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5203;
    L_Error_Text := 'Transport lease expired';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5204;
    L_Error_Text := 'Transport snapshot invalid';
END_IF;

// Finalized distributed commit continuity.
// Intentionally excludes semantic continuity
// to avoid primordial semantic/runtime recursion.
L_Finalized_Continuity_Healthy :=
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired;

IF L_Runtime_OK
AND NOT L_Finalized_Continuity_Healthy THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5300;
    L_Error_Text := 'Finalized continuity invalid';
END_IF;

IF L_Runtime_OK THEN
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    AND (GVL_COMMAND_SHADOW.G_Vent_Stop)
    THEN
        L_Runtime_OK := FALSE;
        L_Error_Code := 5003;
        L_Error_Text := 'Impossible fire ventilation state';
    END_IF;
END_IF;

IF L_Runtime_OK THEN
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    AND (NOT GVL_COMMAND_SHADOW.G_Gas_Valve_Close)
    THEN
        L_Runtime_OK := FALSE;
        L_Error_Code := 5004;
        L_Error_Text := 'Impossible gas valve state';
    END_IF;
END_IF;

GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK := L_Runtime_OK;
GVL_RUNTIME_EPOCH.Runtime_Snapshot_Valid := L_Runtime_OK;
GVL_RUNTIME_EPOCH.Runtime_PLC_Authority_Valid :=
    GVL_STATUS.G_Is_Active_PLC
    AND GVL_PLC_FENCING.PLC_Semantic_Authority_Valid
    AND GVL_PLC_FENCING.PLC_Ownership_Valid
    AND GVL_TIME_MONOTONIC.Monotonic_Time_Valid
    AND GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid
    AND L_Finalized_Continuity_Healthy;

GVL_RUNTIME_EPOCH.Runtime_Last_Validation_Time_MS := L_Now_MS;

IF L_Runtime_OK THEN
    GVL_RUNTIME_EPOCH.Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch + 1;
    GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Snapshot_Published := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Code := 0;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Code := L_Error_Code;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Text := L_Error_Text;
    GVL_RUNTIME_EPOCH.Runtime_Barrier_Block_Count := GVL_RUNTIME_EPOCH.Runtime_Barrier_Block_Count + 1;
END_IF;

GVL_RUNTIME_EPOCH.Runtime_Cycle_End_MS := L_Now_MS;

IF GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Closure_Granted
AND NOT GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Epoch_Rollback_Detected
AND NOT GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Distributed_Epoch_Fork_Detected
AND NOT GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Stale_Epoch_Application_Detected THEN

    GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Distributed_Epoch_Linearity_Valid := TRUE;
    GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Distributed_Epoch_Linearity_Granted := TRUE;
    GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Distributed_Epoch_Linearity_Valid_Proof := TRUE;
    GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Epoch_Timeline_Monotonic := TRUE;
    GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Cluster_Epoch_Consensus_Stable := TRUE;
END_IF;

GVL_MAIN_PHASE_FEEDBACK.G_Current_Phase := 5;

PRG_Domain_Execution_Policy();
PRG_Domain_Execution_Policy_Periodic();

IF GVL_DOMAIN_EXECUTION_POLICY.Heating_Critical_Run
   OR GVL_DOMAIN_EXECUTION_POLICY.Heating_Periodic_Due THEN
    PRG_Heating();
END_IF;
PRG_Heating_Supervisory_Publication();

IF GVL_DOMAIN_EXECUTION_POLICY.Vent_Critical_Run
   OR GVL_DOMAIN_EXECUTION_POLICY.Vent_Periodic_Due THEN
    PRG_Ventilation();
END_IF;

PRG_Water_Supervisory_Publication();
IF GVL_DOMAIN_EXECUTION_POLICY.Water_Critical_Run
   OR GVL_DOMAIN_EXECUTION_POLICY.Water_Periodic_Due THEN
    PRG_Water_Output_Projection();
    PRG_Water();
END_IF;

IF GVL_DOMAIN_EXECUTION_POLICY.Access_Critical_Run
   OR GVL_DOMAIN_EXECUTION_POLICY.Access_Periodic_Due THEN
    PRG_Access();
END_IF;

IF GVL_DOMAIN_EXECUTION_POLICY.Lighting_Critical_Run
   OR GVL_DOMAIN_EXECUTION_POLICY.Lighting_Periodic_Due THEN
    PRG_Lighting();
END_IF;

PRG_Domain_Execution_Policy();
PRG_Domain_Execution_Policy_Periodic();
PRG_Domain_Execution_Validation();
PRG_Runtime_Scenario_Validation();

PRG_Output_Freshness_Governor();
PRG_Physical_Snapshot_Governor();
PRG_Sensor_Consensus_Governor();
PRG_Telemetry_Causality_Governor();
PRG_Physical_Authority_Epoch_Governor();
PRG_Authority_Lineage_Governor();
PRG_Authority_Revocation_Governor();
PRG_Authority_Restoration_Governor();

PRG_PreOutput_Safety_Barrier();
PRG_IO_Write();
PRG_Runtime_IO_Validation();

GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Executed := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Valid :=
    NOT GVL_DOMAIN_EXECUTION_VALIDATION.Any_Policy_Mismatch
    AND NOT GVL_RUNTIME_SCENARIO_VALIDATION.Any_Context_Invalid
    AND NOT GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid;

IF GVL_DOMAIN_EXECUTION_VALIDATION.Any_Policy_Mismatch THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Status_Text := 'Domain/output phase validation mismatch';
ELSIF GVL_RUNTIME_SCENARIO_VALIDATION.Any_Context_Invalid THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Status_Text := 'Domain/output phase scenario mismatch';
ELSIF GVL_RUNTIME_IO_VALIDATION.Any_IO_Invalid THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Status_Text := 'Domain/output phase physical IO mismatch';
ELSIF GVL_DOMAIN_EXECUTION_POLICY.Any_Idle_By_Design THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Status_Text := 'Domain/output phase executed with policy gating';
ELSE
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Status_Text := 'Domain/output phase executed';
END_IF;

GVL_MAIN_PHASE_FEEDBACK.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Main_Phase_05_Domain_Output <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ======================================================
// LOCAL-ONLY PLC FENCING GOVERNOR
// ======================================================
// Cold-spare architecture: there is exactly one runtime owner.
// A reserve PLC is not connected in parallel and is not allowed to arbitrate
// outputs during normal runtime. Therefore split-brain/stale-owner detection is
// held inactive here while still publishing a valid local ownership epoch/token
// for downstream authority checks.
// ======================================================

GVL_PLC_FENCING.PLC_Heartbeat_Only_Mode := FALSE;
GVL_PLC_FENCING.PLC_Split_Brain_Detected := FALSE;
GVL_PLC_FENCING.PLC_Stale_Owner_Detected := FALSE;
GVL_PLC_FENCING.PLC_Asymmetric_Partition_Detected := FALSE;
GVL_PLC_FENCING.PLC_Forced_Safe_Quarantine := FALSE;

GVL_PLC_FENCING.PLC_Ownership_Epoch := GVL_PLC_FENCING.PLC_Ownership_Epoch + 1;
GVL_PLC_FENCING.PLC_Fencing_Token := GVL_PLC_FENCING.PLC_Ownership_Epoch;

GVL_PLC_FENCING.PLC_Ownership_Valid := TRUE;
GVL_PLC_FENCING.PLC_Semantic_Authority_Valid := TRUE;

GVL_PLC_FENCING.PLC_Lease_Active := TRUE;
GVL_PLC_FENCING.PLC_Lease_Expired := FALSE;
GVL_PLC_FENCING.PLC_Last_Lease_Refresh_MS := L_Now_MS;
GVL_PLC_FENCING.PLC_Last_Authority_Validation_MS := L_Now_MS;

GVL_PLC_FENCING.PLC_Last_Error_Code := 0;
GVL_PLC_FENCING.PLC_Last_Error_Text := '';

// >>> BULK_SYNC_ANCHOR: PRG_PLC_Fencing_Governor <<<

// ==============================================================================
// IO READ — deterministic physical input acquisition phase map.
// ==============================================================================
// Execution order is preserved from the former monolithic PRG_IO_Read body.
// No gating, shedding or behavior changes are applied here.
// ==============================================================================

PRG_IO_Read_Phase_01_Module_Health();
PRG_IO_Read_Phase_02_Discrete_Debounce();
PRG_IO_Read_Phase_03_Environment_Sensors();
PRG_IO_Read_Phase_04_Heating_Manifold_Sensors();
PRG_IO_Read_Phase_05_Gas_DHW_Water_Feedback();

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read <<<

L_Maintenance_Apply_Intent := FALSE;

// Dangerous action request
IF GVL_COMMAND.CMD_Dangerous_Action_Request AND (GVL_COMMAND.CMD_User_Access_Level >= 2) THEN
    IF NOT L_Dangerous_Action_Armed THEN
        fbLogEvent(
            VI_Event_Type := 8,
            VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
            VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
            VI_Param2 := 1
        );
    END_IF;

    L_Dangerous_Action_Armed := TRUE;
    L_Dangerous_Action_Deadline_MS := GVL_TIME_SERVICE.G_Now_MS + 15000;

    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := TRUE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Deadline_MS := L_Dangerous_Action_Deadline_MS;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Подтвердите опасное действие в течение 15 секунд';
END_IF;

// Timeout
IF L_Dangerous_Action_Armed AND (GVL_TIME_SERVICE.G_Now_MS > L_Dangerous_Action_Deadline_MS) THEN
    L_Dangerous_Action_Armed := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Окно подтверждения истекло';
END_IF;

// Confirm
IF GVL_COMMAND.CMD_Dangerous_Action_Confirm AND
   L_Dangerous_Action_Armed AND
   (GVL_COMMAND.CMD_User_Access_Level >= 2) THEN

    L_Maintenance_Apply_Intent := TRUE;

    fbLogEvent(
        VI_Event_Type := 9,
        VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
        VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
        VI_Param2 := 1
    );

    L_Dangerous_Action_Armed := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Опасное действие подтверждено оператором';
END_IF;

// Apply maintenance
IF L_Maintenance_Apply_Intent THEN
    GVL_CONFIG.G_DHW_Heating_Pump_In_Service := GVL_COMMAND.CMD_Set_DHW_Heating_Pump_In_Service;
    GVL_CONFIG.G_DHW_Circ_Pump_In_Service := GVL_COMMAND.CMD_Set_DHW_Circ_Pump_In_Service;
END_IF;

// Access enforcement
GVL_STATUS.G_Diagnostics.User_Access_Level_Active := GVL_COMMAND.CMD_User_Access_Level;
GVL_STATUS.G_Diagnostics.User_Access_Denied := FALSE;

IF GVL_COMMAND.CMD_Dangerous_Action_Request OR GVL_COMMAND.CMD_Dangerous_Action_Confirm THEN
    IF GVL_COMMAND.CMD_User_Access_Level < 2 THEN
        IF NOT L_User_Access_Denied_Prev THEN
            fbLogEvent(
                VI_Event_Type := 10,
                VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
                VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
                VI_Param2 := 2
            );
        END_IF;

        GVL_STATUS.G_Diagnostics.User_Access_Denied := TRUE;
        GVL_STATUS.G_Diagnostics.Operator_Action_Blocked := TRUE;
    END_IF;
END_IF;

L_User_Access_Denied_Prev := GVL_STATUS.G_Diagnostics.User_Access_Denied;

// Centralized Health execution (Phase 5)
fbSystemHealthOrchestrator(
    VO_First_Fault_Active => GVL_SYSTEM_HEALTH.G_First_Fault_Active,
    VO_First_Fault_Type => GVL_SYSTEM_HEALTH.G_First_Fault_Type,
    VO_First_Fault_Source => GVL_SYSTEM_HEALTH.G_First_Fault_Source,
    VO_System_Severity => GVL_SYSTEM_HEALTH.G_System_Severity,
    VO_Root_Cause => GVL_SYSTEM_HEALTH.G_Root_Cause,
    VO_Watchdog_Fault => GVL_SYSTEM_HEALTH.G_Watchdog_Fault
);

L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Now_MS := GVL_STATUS.G_System_Time_MS;

GVL_ACCESS_RUNTIME.G_Runtime_Required := FALSE;
GVL_ACCESS_RUNTIME.G_Runtime_Executed := TRUE;
GVL_ACCESS_RUNTIME.G_Runtime_Idle_By_Design := FALSE;
GVL_ACCESS_RUNTIME.G_Runtime_Blocked_By_Distributed_Gates := FALSE;
GVL_ACCESS_RUNTIME.G_Any_Pulse_Active := FALSE;
GVL_ACCESS_RUNTIME.G_Last_Update_MS := L_Now_MS;

// Distributed runtime governance.
// FIRE/GAS emergency semantics remain authoritative.
L_Distributed_Execute_Allowed :=
    GVL_Distributed_Execution_Gates.G_Can_Execute;

L_Distributed_Access_Allowed :=
    GVL_Distributed_Execution_Gates.G_Can_Own_Projection;

IF (L_Mode <> FIRE)
   AND (L_Mode <> GAS)
   AND (
        NOT L_Distributed_Execute_Allowed
        OR NOT L_Distributed_Access_Allowed
       ) THEN

    // Clear all pulse channels before blocking projection to avoid stale pulse-active state.
    fbPulseLock1Open(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);
    fbPulseLock1Close(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);
    fbPulseLock2Open(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);
    fbPulseLock2Close(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);
    fbPulseGateOpen(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);
    fbPulseWicketOpen(VI_Command := FALSE, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := 100);

    fbProjection(
        VI_Lock_1_Open := FALSE,
        VI_Lock_1_Close := FALSE,
        VI_Lock_2_Open := FALSE,
        VI_Lock_2_Close := FALSE,
        VI_Gate_Open := FALSE,
        VI_Wicket_Open := FALSE
    );

    GVL_ACCESS_RUNTIME.G_Runtime_Blocked_By_Distributed_Gates := TRUE;
    GVL_ACCESS_RUNTIME.G_Any_Pulse_Active := FALSE;
    GVL_ACCESS_RUNTIME.G_Status_Code := 2;
    GVL_ACCESS_RUNTIME.G_Status_Text := 'Access runtime blocked by distributed gates';

    RETURN;
END_IF;

// Load pulse duration from config with safety clamp.
L_Pulse_MS := GVL_CONFIG.G_Access_Pulse_MS;
IF L_Pulse_MS < 100 THEN
    L_Pulse_MS := 100;
ELSIF L_Pulse_MS > 5000 THEN
    L_Pulse_MS := 5000;
END_IF;

L_Lock_1_Open := FALSE;
L_Lock_1_Close := FALSE;
L_Lock_2_Open := FALSE;
L_Lock_2_Close := FALSE;
L_Gate_Open := FALSE;
L_Wicket_Open := FALSE;

CASE L_Mode OF
    FIRE:
        // Fire evacuation access commands are authoritative and continuous.
        L_Lock_1_Open := GVL_COMMAND_SHADOW.G_Lock_1_Open;
        L_Lock_2_Open := GVL_COMMAND_SHADOW.G_Lock_2_Open;
        L_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;
        L_Wicket_Open := GVL_COMMAND_SHADOW.G_Wicket_Open;

        // Synchronize pulse channels with current command state and clear active pulses.
        fbPulseLock1Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Open, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock1Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Close, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Open, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Close, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseGateOpen(VI_Command := GVL_COMMAND_SHADOW.G_Gate_Open, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseWicketOpen(VI_Command := GVL_COMMAND_SHADOW.G_Wicket_Open, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);

    GAS:
        // Gas mode uses direct gate opening plus limited pulsed pedestrian/lock release.
        L_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;

        fbPulseLock1Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseWicketOpen(VI_Command := GVL_COMMAND_SHADOW.G_Wicket_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);

        fbPulseLock1Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Close, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Close, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseGateOpen(VI_Command := GVL_COMMAND_SHADOW.G_Gate_Open, VI_Reset := TRUE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);

        L_Lock_1_Open := fbPulseLock1Open.VO_Output;
        L_Lock_2_Open := fbPulseLock2Open.VO_Output;
        L_Wicket_Open := fbPulseWicketOpen.VO_Output;

ELSE
        fbPulseLock1Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock1Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_1_Close, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Open(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseLock2Close(VI_Command := GVL_COMMAND_SHADOW.G_Lock_2_Close, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseGateOpen(VI_Command := GVL_COMMAND_SHADOW.G_Gate_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);
        fbPulseWicketOpen(VI_Command := GVL_COMMAND_SHADOW.G_Wicket_Open, VI_Reset := FALSE, VI_Now_MS := L_Now_MS, VI_Pulse_MS := L_Pulse_MS);

        L_Lock_1_Open := fbPulseLock1Open.VO_Output;
        L_Lock_1_Close := fbPulseLock1Close.VO_Output;
        L_Lock_2_Open := fbPulseLock2Open.VO_Output;
        L_Lock_2_Close := fbPulseLock2Close.VO_Output;
        L_Gate_Open := fbPulseGateOpen.VO_Output;
        L_Wicket_Open := fbPulseWicketOpen.VO_Output;
END_CASE;

GVL_ACCESS_RUNTIME.G_Any_Pulse_Active :=
    fbPulseLock1Open.VO_Active
    OR fbPulseLock1Close.VO_Active
    OR fbPulseLock2Open.VO_Active
    OR fbPulseLock2Close.VO_Active
    OR fbPulseGateOpen.VO_Active
    OR fbPulseWicketOpen.VO_Active;

GVL_ACCESS_RUNTIME.G_Runtime_Required :=
    (L_Mode = FIRE)
    OR (L_Mode = GAS)
    OR GVL_COMMAND_SHADOW.G_Lock_1_Open
    OR GVL_COMMAND_SHADOW.G_Lock_1_Close
    OR GVL_COMMAND_SHADOW.G_Lock_2_Open
    OR GVL_COMMAND_SHADOW.G_Lock_2_Close
    OR GVL_COMMAND_SHADOW.G_Gate_Open
    OR GVL_COMMAND_SHADOW.G_Wicket_Open
    OR GVL_ACCESS_RUNTIME.G_Any_Pulse_Active;

GVL_ACCESS_RUNTIME.G_Runtime_Idle_By_Design :=
    NOT GVL_ACCESS_RUNTIME.G_Runtime_Required;

IF GVL_ACCESS_RUNTIME.G_Runtime_Idle_By_Design THEN
    GVL_ACCESS_RUNTIME.G_Status_Code := 0;
    GVL_ACCESS_RUNTIME.G_Status_Text := 'Access runtime idle by design';
ELSE
    GVL_ACCESS_RUNTIME.G_Status_Code := 1;
    GVL_ACCESS_RUNTIME.G_Status_Text := 'Access runtime active';
END_IF;

fbProjection(
    VI_Lock_1_Open := L_Lock_1_Open,
    VI_Lock_1_Close := L_Lock_1_Close,
    VI_Lock_2_Open := L_Lock_2_Open,
    VI_Lock_2_Close := L_Lock_2_Close,
    VI_Gate_Open := L_Gate_Open,
    VI_Wicket_Open := L_Wicket_Open
);

// >>> BULK_SYNC_ANCHOR: PRG_Access <<<

// Extracted from PRG_System (Phase 5A).
// Idempotent projection: safe to run while legacy call still exists.
L_Gateway_Writes_Allowed :=
    NOT GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm AND
    NOT GVL_STATUS.G_Diagnostics.Operator_Action_Blocked AND
    NOT GVL_STATUS.G_Diagnostics.User_Access_Denied;

fbSystemIntentPublisher(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Gateway_Writes_Allowed := L_Gateway_Writes_Allowed
);

// ======================================================
// MODBUS RTU DRIVER EXECUTION
// ======================================================
// Runtime execution wrapper for the RTU driver FB.
//
// Driver_Attached is a configuration/HMI decision and must not depend
// on runtime bridge state.
// ======================================================

FB_RTU_Driver(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_Driver_Attached := GVL_CONFIG.G_Modbus_RTU_Driver_Attached,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;

GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Valid := FALSE;
GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Granted := FALSE;
GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Quarantine_Active := TRUE;

IF NOT GVL_GOVERNANCE_PUBLICATION_BINDING_FABRIC.Governance_Publication_Binding_Granted THEN
    L_Valid := FALSE;
END_IF;

IF GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.SafeState_Ambiguity_Detected
OR GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Partial_SafeState_Asymmetry_Detected
OR GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Deadlock_Detected
OR GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Unsafe_SafeState_Topology_Detected
OR GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Residual_Unsafe_Actuation_Detected
OR GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.SafeState_Energy_Leakage_Detected THEN
    L_Valid := FALSE;
END_IF;

IF L_Valid THEN
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Valid := TRUE;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Granted := TRUE;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Quarantine_Active := FALSE;

    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Canonical_SafeState_Topology_Valid := TRUE;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Coherent := TRUE;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Deterministic_FailSafe_Convergence_Granted := TRUE;

    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Epoch :=
        GVL_GOVERNANCE_PUBLICATION_BINDING_FABRIC.Governance_Publication_Binding_Epoch;

    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Epoch_Coherent := TRUE;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Last_Update_MS := L_Now_MS;
    GVL_PHYSICAL_SAFESTATE_LATTICE_FABRIC.Physical_SafeState_Lattice_Lease_Expired := FALSE;
END_IF;

// ======================================================
// HEATING CONFIDENCE
// ======================================================
GVL_HMI.G_HMI_Heating_Confidence := GVL_STATE.G_Heating_Confidence;
GVL_HMI.G_HMI_Heating_Confidence_Percent := REAL_TO_INT(GVL_STATE.G_Heating_Confidence * 100.0);

// ======================================================
// HEATING ROOT CAUSE
// ======================================================
GVL_HMI.G_HMI_Heating_Reason_Code := GVL_STATE.G_Heating_Confidence_Reason_Code;
GVL_HMI.G_HMI_Heating_Status_Text := GVL_STATE.G_Heating_Confidence_Reason_Text;

// ======================================================
// HEATING STATUS LEVEL
// ======================================================
IF GVL_STATE.G_Heating_Confidence > 0.8 THEN
    GVL_HMI.G_HMI_Heating_Status_Level := 0;
ELSIF GVL_STATE.G_Heating_Confidence > 0.5 THEN
    GVL_HMI.G_HMI_Heating_Status_Level := 1;
ELSE
    GVL_HMI.G_HMI_Heating_Status_Level := 2;
END_IF;

// ======================================================
// CASCADE SEMANTIC STATE
// ======================================================
GVL_HMI.G_HMI_Heating_Cascade_Available :=
    GVL_STATE.G_Heating_Cascade_Available;

GVL_HMI.G_HMI_Heating_Cascade_Degraded :=
    GVL_STATE.G_Heating_Cascade_Degraded;

GVL_HMI.G_HMI_Heating_Cascade_Partial_Capacity :=
    GVL_STATE.G_Heating_Cascade_Partial_Capacity;

GVL_HMI.G_HMI_Heating_Cascade_No_Flame :=
    GVL_STATE.G_Heating_Cascade_No_Flame;

GVL_HMI.G_HMI_Heating_Cascade_Transport_Degraded :=
    GVL_STATE.G_Heating_Cascade_Transport_Degraded;

GVL_HMI.G_HMI_Heating_Cascade_Ignition_Timeout :=
    GVL_STATE.G_Heating_Cascade_Ignition_Timeout;

GVL_HMI.G_HMI_Heating_Cascade_Active_Boilers :=
    GVL_STATE.G_Heating_Cascade_Active_Boilers;

GVL_HMI.G_HMI_Heating_Cascade_Available_Boilers :=
    GVL_STATE.G_Heating_Cascade_Available_Boilers;

// ======================================================
// OPENTHERM SEMANTIC STATE
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    GVL_HMI.G_HMI_Boiler_OT_Online[L_i] :=
        GVL_STATE.G_Boiler_OT_Online[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Ack[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Ack[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Timeout[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Timeout[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Heartbeat_Timeout[L_i] :=
        GVL_STATE.G_Boiler_OT_Heartbeat_Timeout[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Adapter_Error[L_i] :=
        GVL_STATE.G_Boiler_OT_Adapter_Error[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Heartbeat_Age_MS[L_i] :=
        GVL_STATE.G_Boiler_OT_Heartbeat_Age_MS[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Age_MS[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Age_MS[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Adapter_State[L_i] :=
        GVL_STATE.G_Boiler_OT_Adapter_State[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Error_State[L_i] :=
        GVL_STATE.G_Boiler_OT_Error_State[L_i];

END_FOR;

// ======================================================
