// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_HMI.G_HMI_Heating_Predictive_Pressure_Drop[L_i] :=
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i];

    GVL_HMI.G_HMI_Heating_Predictive_Current_Rise[L_i] :=
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i];
END_FOR;

// ======================================================
// FILE / ARCHIVE STATUS (READ-ONLY DASHBOARD)
// ======================================================
L_Archive_Target_Available := FALSE;
CASE GVL_FILE_ARCHIVE.G_File_Archive_Target_Code OF
    1:
        L_Archive_Target_Available := GVL_FILE_ARCHIVE.G_PLC_File_Target_Available;
    2:
        L_Archive_Target_Available := GVL_FILE_ARCHIVE.G_USB_Target_Available;
    3:
        L_Archive_Target_Available := GVL_FILE_ARCHIVE.G_Gateway_Target_Available;
ELSE
    L_Archive_Target_Available := FALSE;
END_CASE;

GVL_HMI.G_HMI_File_Archive_Interface_Enabled := GVL_FILE_ARCHIVE.G_Archive_Interface_Enabled;
GVL_HMI.G_HMI_File_Archive_CSV_Enabled := GVL_FILE_ARCHIVE.G_CSV_Write_Enabled;
GVL_HMI.G_HMI_File_Archive_Target_Code := GVL_FILE_ARCHIVE.G_File_Archive_Target_Code;
GVL_HMI.G_HMI_File_Archive_Target_Available := L_Archive_Target_Available;
GVL_HMI.G_HMI_File_Archive_Write_Busy := GVL_FILE_ARCHIVE.G_Write_Busy;
GVL_HMI.G_HMI_File_Archive_Write_Done := GVL_FILE_ARCHIVE.G_Write_Done;
GVL_HMI.G_HMI_File_Archive_Write_Error := GVL_FILE_ARCHIVE.G_Write_Error;
GVL_HMI.G_HMI_File_Archive_Last_Error_Code := GVL_FILE_ARCHIVE.G_Last_Error_Code;
GVL_HMI.G_HMI_File_Archive_Last_Status_Text := GVL_FILE_ARCHIVE.G_Last_Status_Text;
GVL_HMI.G_HMI_File_Archive_Last_Write_MS := GVL_FILE_ARCHIVE.G_Last_Write_MS;

GVL_HMI.G_HMI_File_Archive_Auto_Backup_Enabled := GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Enabled;
GVL_HMI.G_HMI_File_Archive_Auto_Backup_Time_Of_Day_MS := GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Time_Of_Day_MS;
GVL_HMI.G_HMI_File_Archive_Auto_Backup_Last_Day_Of_Week := GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Last_Day_Of_Week;
GVL_HMI.G_HMI_File_Archive_Auto_Backup_Last_Request_MS := GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Last_Request_MS;
GVL_HMI.G_HMI_File_Archive_Auto_Backup_Last_Status_Text := GVL_FILE_ARCHIVE.G_Auto_Config_Backup_Last_Status_Text;

IF GVL_FILE_ARCHIVE.G_Write_Error THEN
    GVL_HMI.G_HMI_File_Archive_Status_Level := 2;
ELSIF GVL_FILE_ARCHIVE.G_Write_Busy THEN
    GVL_HMI.G_HMI_File_Archive_Status_Level := 1;
ELSIF GVL_FILE_ARCHIVE.G_Archive_Interface_Enabled AND GVL_FILE_ARCHIVE.G_CSV_Write_Enabled AND L_Archive_Target_Available THEN
    GVL_HMI.G_HMI_File_Archive_Status_Level := 0;
ELSE
    GVL_HMI.G_HMI_File_Archive_Status_Level := 1;
END_IF;

// ======================================================
// CONFIG CONTROL STATUS (READ-ONLY DASHBOARD)
// ======================================================
GVL_HMI.G_HMI_Config_Control_Version := GVL_CONFIG_CONTROL.G_Config_Version;
GVL_HMI.G_HMI_Config_Control_Last_Good_Version := GVL_CONFIG_CONTROL.G_Last_Good_Version;
GVL_HMI.G_HMI_Config_Control_Staged_Config_Version := GVL_CONFIG_CONTROL.G_Staged_Config_Version;
GVL_HMI.G_HMI_Config_Control_Staged_Last_Changed_MS := GVL_CONFIG_CONTROL.G_Staged_Last_Changed_MS;
GVL_HMI.G_HMI_Config_Control_Backup_Valid := GVL_CONFIG_CONTROL.G_Backup_Valid;
GVL_HMI.G_HMI_Config_Control_Apply_Pending := GVL_CONFIG_CONTROL.G_Apply_Request;
GVL_HMI.G_HMI_Config_Control_Rollback_Pending := GVL_CONFIG_CONTROL.G_Rollback_Request;
GVL_HMI.G_HMI_Config_Control_Apply_Done := GVL_CONFIG_CONTROL.G_Apply_Done;
GVL_HMI.G_HMI_Config_Control_Rollback_Done := GVL_CONFIG_CONTROL.G_Rollback_Done;
GVL_HMI.G_HMI_Config_Control_Reset_Default_Done := GVL_CONFIG_VALIDATION.G_Config_Reset_To_Default_Done;
GVL_HMI.G_HMI_Config_Control_Config_Valid := GVL_CONFIG_VALIDATION.G_Config_Valid;
GVL_HMI.G_HMI_Config_Control_Last_Action_Text := GVL_CONFIG_HISTORY.G_Last_Action_Text;
GVL_HMI.G_HMI_Config_Control_Last_Error_Text := GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text;
GVL_HMI.G_HMI_Config_Control_Last_Update_MS := GVL_CONFIG_VALIDATION.G_Config_Last_Update_MS;

// ======================================================
// CONFIG WORKFLOW STATUS (READ-ONLY DASHBOARD)
// ======================================================
GVL_HMI.G_HMI_Config_Workflow_Runtime_Valid := GVL_HMI_Config_Workflow.G_Runtime_Valid;
GVL_HMI.G_HMI_Config_Workflow_Draft_Dirty := GVL_HMI_Config_Workflow.G_Workflow_State.Draft_Dirty;
GVL_HMI.G_HMI_Config_Workflow_Validation_OK := GVL_HMI_Config_Workflow.G_Workflow_State.Validation_OK;
GVL_HMI.G_HMI_Config_Workflow_Validation_Failed := GVL_HMI_Config_Workflow.G_Workflow_State.Validation_Failed;
GVL_HMI.G_HMI_Config_Workflow_Draft_Version := GVL_HMI_Config_Workflow.G_Workflow_State.Draft_Version;
GVL_HMI.G_HMI_Config_Workflow_Validated_Draft_Version := GVL_HMI_Config_Workflow.G_Workflow_State.Validated_Draft_Version;
GVL_HMI.G_HMI_Config_Workflow_Topology_Draft_Version := GVL_HMI_Config_Workflow.G_Workflow_State.Topology_Draft_Version;
GVL_HMI.G_HMI_Config_Workflow_Validated_Topology_Version := GVL_HMI_Config_Workflow.G_Workflow_State.Validated_Topology_Version;
GVL_HMI.G_HMI_Config_Workflow_Validation_Last_Run_MS := GVL_HMI_Config_Workflow.G_Workflow_State.Validation_Last_Run_MS;
GVL_HMI.G_HMI_Config_Workflow_Validation_Result_Seq := GVL_HMI_Config_Workflow.G_Workflow_State.Validation_Result_Seq;
GVL_HMI.G_HMI_Config_Workflow_Topology_Activation_Required := GVL_HMI_Config_Workflow.G_Workflow_State.Topology_Activation_Required;
GVL_HMI.G_HMI_Config_Workflow_Topology_Validation_OK := GVL_HMI_Config_Workflow.G_Workflow_State.Topology_Validation_OK;
GVL_HMI.G_HMI_Config_Workflow_Status_Code := GVL_HMI_Config_Workflow.G_Status_Code;
GVL_HMI.G_HMI_Config_Workflow_Status_Text := GVL_HMI_Config_Workflow.G_Status_Text;

IF NOT GVL_HMI_Config_Workflow.G_Runtime_Valid THEN
    GVL_HMI.G_HMI_Config_Workflow_Status_Level := 2;
ELSIF GVL_HMI_Config_Workflow.G_Workflow_State.Validation_Failed THEN
    GVL_HMI.G_HMI_Config_Workflow_Status_Level := 2;
ELSIF GVL_HMI_Config_Workflow.G_Workflow_State.Draft_Dirty THEN
    GVL_HMI.G_HMI_Config_Workflow_Status_Level := 1;
ELSIF GVL_HMI_Config_Workflow.G_Status_Code > 0 THEN
    GVL_HMI.G_HMI_Config_Workflow_Status_Level := 1;
ELSE
    GVL_HMI.G_HMI_Config_Workflow_Status_Level := 0;
END_IF;

GVL_HMI.G_HMI_Config_Simulation_Request_Pending :=
    GVL_CONFIG_SIMULATION.G_Simulation_Request OR GVL_CONFIG_SIMULATION.G_Simulation_Confirm;
GVL_HMI.G_HMI_Config_Simulation_Result_OK := GVL_CONFIG_SIMULATION.G_Simulation_Result_OK;
GVL_HMI.G_HMI_Config_Simulation_Error_Text := GVL_CONFIG_SIMULATION.G_Simulation_Error_Text;
GVL_HMI.G_HMI_Config_Simulation_Last_Run_MS := GVL_CONFIG_SIMULATION.G_Simulation_Last_Run_MS;
GVL_HMI.G_HMI_Config_Simulation_Result_Seq := GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq;
GVL_HMI.G_HMI_Config_Simulation_Staged_Config_Version := GVL_CONFIG_SIMULATION.G_Simulation_Staged_Config_Version;

IF GVL_HMI.G_HMI_Config_Simulation_Request_Pending THEN
    GVL_HMI.G_HMI_Config_Simulation_Status_Level := 1;
ELSIF NOT GVL_CONFIG_SIMULATION.G_Simulation_Result_OK THEN
    GVL_HMI.G_HMI_Config_Simulation_Status_Level := 2;
ELSE
    GVL_HMI.G_HMI_Config_Simulation_Status_Level := 0;
END_IF;

IF NOT GVL_CONFIG_VALIDATION.G_Config_Valid THEN
    GVL_HMI.G_HMI_Config_Control_Status_Level := 2;
ELSIF (GVL_CONFIG_HISTORY.G_Last_Action_Text = 'CONFIG APPLY REJECTED') OR
      (GVL_CONFIG_HISTORY.G_Last_Action_Text = 'CONFIG ROLLBACK REJECTED - NO BACKUP') THEN
    GVL_HMI.G_HMI_Config_Control_Status_Level := 2;
ELSIF GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text <> '' THEN
    GVL_HMI.G_HMI_Config_Control_Status_Level := 2;
ELSIF GVL_CONFIG_CONTROL.G_Apply_Request OR GVL_CONFIG_CONTROL.G_Rollback_Request OR GVL_CONFIG_CONTROL.G_Reset_Default_Request THEN
    GVL_HMI.G_HMI_Config_Control_Status_Level := 1;
ELSE
    GVL_HMI.G_HMI_Config_Control_Status_Level := 0;
END_IF;

L_Error := FALSE;
L_Staged_Error := FALSE;
GVL_CONFIG_VALIDATION.G_Config_Auto_Corrected := FALSE;
GVL_CONFIG_VALIDATION.G_Config_Reset_To_Default_Done := FALSE;
GVL_CONFIG_CONTROL.G_Apply_Done := FALSE;
GVL_CONFIG_CONTROL.G_Rollback_Done := FALSE;

// ===== SIZE VALIDATION =====
IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits := GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS;
    L_Error := TRUE;
END_IF;

IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones > GVL_CONSTANTS.C_MAX_WATER_ZONES THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones := GVL_CONSTANTS.C_MAX_WATER_ZONES;
    L_Error := TRUE;
END_IF;

IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones > GVL_CONSTANTS.C_MAX_LIGHT_ZONES THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones := GVL_CONSTANTS.C_MAX_LIGHT_ZONES;
    L_Error := TRUE;
END_IF;

// ===== EXISTING ACTIVE VALIDATION =====
IF GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate < 0.0 OR GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate > 1.0 THEN
    GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := 0.05;
    L_Error := TRUE;
END_IF;

// ===== APPLY STAGED CONFIG =====
IF GVL_CONFIG_CONTROL.G_Apply_Request AND GVL_CONFIG_CONTROL.G_Apply_Confirm THEN
    L_Staged_Error := FALSE;

    IF (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate < 0.0) OR (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate > 1.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay < 0.0) OR (GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay > 1.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence > 1.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence > 1.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Default_Confidence < 0.0) OR (GVL_CONFIG_CONTROL.STG_Default_Confidence > 1.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Night_Start_Hour < 0) OR (GVL_CONFIG_CONTROL.STG_Night_Start_Hour > 23) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_Night_End_Hour < 0) OR (GVL_CONFIG_CONTROL.STG_Night_End_Hour > 23) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold < 0.0) OR (GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold > 100.0) THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS < 1000 THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF NOT GVL_CONFIG_SIMULATION.G_Simulation_Result_OK THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq = 0 THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF GVL_CONFIG_SIMULATION.G_Simulation_Staged_Config_Version <> GVL_CONFIG_CONTROL.G_Staged_Config_Version THEN
        L_Staged_Error := TRUE;
    END_IF;

    IF L_Staged_Error THEN
        L_Index := GVL_CONFIG_HISTORY.G_History_Index;
        GVL_CONFIG_HISTORY.G_History_Version[L_Index] := GVL_CONFIG_CONTROL.G_Config_Version;
        GVL_CONFIG_HISTORY.G_History_Time_MS[L_Index] := GVL_TIME_SERVICE.G_Now_MS;
        GVL_CONFIG_HISTORY.G_History_Action[L_Index] := 'APPLY_REJECTED';
        GVL_CONFIG_HISTORY.G_Last_Action_Text := 'CONFIG APPLY REJECTED';

        L_Index := L_Index + 1;
        IF L_Index > 5 THEN L_Index := 1; END_IF;
        GVL_CONFIG_HISTORY.G_History_Index := L_Index;

        IF GVL_CONFIG_SIMULATION.G_Simulation_Result_Seq = 0 THEN
            GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := 'STAGED CONFIG NOT SIMULATED';
        ELSIF GVL_CONFIG_SIMULATION.G_Simulation_Staged_Config_Version <> GVL_CONFIG_CONTROL.G_Staged_Config_Version THEN
            GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := 'STAGED CONFIG SIMULATION STALE';
        ELSE
            GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := 'STAGED CONFIG INVALID';
        END_IF;
    ELSE
        // Backup current active values before applying staged values.
        GVL_CONFIG_CONTROL.BCK_Reputation_Learning_Rate := GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;
        GVL_CONFIG_CONTROL.BCK_Reputation_Recovery_Decay := GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;
        GVL_CONFIG_CONTROL.BCK_Min_Sensor_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
        GVL_CONFIG_CONTROL.BCK_Bad_Spike_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence;
        GVL_CONFIG_CONTROL.BCK_Default_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;

        GVL_CONFIG_CONTROL.BCK_Night_Start_Hour := GVL_SCENARIO_CONFIG.G_Night_Start_Hour;
        GVL_CONFIG_CONTROL.BCK_Night_End_Hour := GVL_SCENARIO_CONFIG.G_Night_End_Hour;
        GVL_CONFIG_CONTROL.BCK_VentBoost_Humidity_Threshold := GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold;

        GVL_CONFIG_CONTROL.BCK_Stabilization_Delay_MS := GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS;

        GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Close_Gas := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas;
        GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Boiler := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler;
        GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Heating := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating;
        GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Vent := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent;
        GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Water := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water;

        // Apply staged input config.
        GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate;
        GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay := GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay;
        GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence := GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence;
        GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence := GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence;
        GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence := GVL_CONFIG_CONTROL.STG_Default_Confidence;

        // Apply staged scenario config.
        GVL_SCENARIO_CONFIG.G_Night_Start_Hour := GVL_CONFIG_CONTROL.STG_Night_Start_Hour;
        GVL_SCENARIO_CONFIG.G_Night_End_Hour := GVL_CONFIG_CONTROL.STG_Night_End_Hour;
        GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold := GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold;

        // Apply staged recovery config.
        GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS := GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS;

        // Apply staged command-policy critical config.
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water := GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water;

        GVL_CONFIG_CONTROL.G_Config_Version := GVL_CONFIG_CONTROL.G_Config_Version + 1;
        GVL_CONFIG_CONTROL.G_Last_Good_Version := GVL_CONFIG_CONTROL.G_Config_Version;
        GVL_CONFIG_CONTROL.G_Backup_Valid := TRUE;
        GVL_CONFIG_CONTROL.G_Apply_Done := TRUE;
        GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := '';

        L_Index := GVL_CONFIG_HISTORY.G_History_Index;
        GVL_CONFIG_HISTORY.G_History_Version[L_Index] := GVL_CONFIG_CONTROL.G_Config_Version;
        GVL_CONFIG_HISTORY.G_History_Time_MS[L_Index] := GVL_TIME_SERVICE.G_Now_MS;
        GVL_CONFIG_HISTORY.G_History_Action[L_Index] := 'APPLY';
        GVL_CONFIG_HISTORY.G_Last_Action_Text := 'CONFIG APPLY';

        L_Index := L_Index + 1;
        IF L_Index > 5 THEN L_Index := 1; END_IF;
        GVL_CONFIG_HISTORY.G_History_Index := L_Index;
    END_IF;

    GVL_CONFIG_CONTROL.G_Apply_Request := FALSE;
    GVL_CONFIG_CONTROL.G_Apply_Confirm := FALSE;
END_IF;

// ===== RESET CONTROLLED CONFIG TO DEFAULTS =====
IF GVL_CONFIG_CONTROL.G_Reset_Default_Request AND GVL_CONFIG_CONTROL.G_Reset_Default_Confirm THEN
    // Backup current active values before resetting controlled config defaults.
    GVL_CONFIG_CONTROL.BCK_Reputation_Learning_Rate := GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;
    GVL_CONFIG_CONTROL.BCK_Reputation_Recovery_Decay := GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;
    GVL_CONFIG_CONTROL.BCK_Min_Sensor_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
    GVL_CONFIG_CONTROL.BCK_Bad_Spike_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence;
    GVL_CONFIG_CONTROL.BCK_Default_Confidence := GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;

    GVL_CONFIG_CONTROL.BCK_Night_Start_Hour := GVL_SCENARIO_CONFIG.G_Night_Start_Hour;
    GVL_CONFIG_CONTROL.BCK_Night_End_Hour := GVL_SCENARIO_CONFIG.G_Night_End_Hour;
    GVL_CONFIG_CONTROL.BCK_VentBoost_Humidity_Threshold := GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold;

    GVL_CONFIG_CONTROL.BCK_Stabilization_Delay_MS := GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS;

    GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Close_Gas := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas;
    GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Boiler := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler;
    GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Heating := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating;
    GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Vent := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent;
    GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Water := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water;

    // Reset staged and active controlled config values to conservative defaults.
    GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate := 0.05;
    GVL_CONFIG_CONTROL.STG_Reputation_Recovery_Decay := 0.01;
    GVL_CONFIG_CONTROL.STG_Min_Sensor_Confidence := 0.1;
    GVL_CONFIG_CONTROL.STG_Bad_Spike_Confidence := 0.3;
    GVL_CONFIG_CONTROL.STG_Default_Confidence := 1.0;

    GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := 0.05;
    GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay := 0.01;
    GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence := 0.1;
    GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence := 0.3;
    GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence := 1.0;

    GVL_CONFIG_CONTROL.STG_Night_Start_Hour := 22;
    GVL_CONFIG_CONTROL.STG_Night_End_Hour := 6;
    GVL_CONFIG_CONTROL.STG_VentBoost_Humidity_Threshold := 65.0;

    GVL_SCENARIO_CONFIG.G_Night_Start_Hour := 22;
    GVL_SCENARIO_CONFIG.G_Night_End_Hour := 6;
    GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold := 65.0;

    GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS := 5000;
    GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS := 5000;

    GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas := TRUE;
    GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler := TRUE;
    GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating := TRUE;
    GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent := TRUE;
    GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water := TRUE;

    GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas := TRUE;
    GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler := TRUE;
    GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating := TRUE;
    GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent := TRUE;
    GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water := TRUE;

    GVL_CONFIG_CONTROL.G_Config_Version := GVL_CONFIG_CONTROL.G_Config_Version + 1;
    GVL_CONFIG_CONTROL.G_Last_Good_Version := GVL_CONFIG_CONTROL.G_Config_Version;
    GVL_CONFIG_CONTROL.G_Backup_Valid := TRUE;
    GVL_CONFIG_VALIDATION.G_Config_Reset_To_Default_Done := TRUE;
    GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := '';

    L_Index := GVL_CONFIG_HISTORY.G_History_Index;
    GVL_CONFIG_HISTORY.G_History_Version[L_Index] := GVL_CONFIG_CONTROL.G_Config_Version;
    GVL_CONFIG_HISTORY.G_History_Time_MS[L_Index] := GVL_TIME_SERVICE.G_Now_MS;
    GVL_CONFIG_HISTORY.G_History_Action[L_Index] := 'RESET_DEFAULT';
    GVL_CONFIG_HISTORY.G_Last_Action_Text := 'CONFIG RESET DEFAULT';

    L_Index := L_Index + 1;
    IF L_Index > 5 THEN L_Index := 1; END_IF;
    GVL_CONFIG_HISTORY.G_History_Index := L_Index;

    GVL_CONFIG_CONTROL.G_Reset_Default_Request := FALSE;
    GVL_CONFIG_CONTROL.G_Reset_Default_Confirm := FALSE;
END_IF;

// ===== ROLLBACK TO LAST BACKUP =====
IF GVL_CONFIG_CONTROL.G_Rollback_Request AND GVL_CONFIG_CONTROL.G_Rollback_Confirm THEN
    IF GVL_CONFIG_CONTROL.G_Backup_Valid THEN
        GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := GVL_CONFIG_CONTROL.BCK_Reputation_Learning_Rate;
        GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay := GVL_CONFIG_CONTROL.BCK_Reputation_Recovery_Decay;
        GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence := GVL_CONFIG_CONTROL.BCK_Min_Sensor_Confidence;
        GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence := GVL_CONFIG_CONTROL.BCK_Bad_Spike_Confidence;
        GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence := GVL_CONFIG_CONTROL.BCK_Default_Confidence;

        GVL_SCENARIO_CONFIG.G_Night_Start_Hour := GVL_CONFIG_CONTROL.BCK_Night_Start_Hour;
        GVL_SCENARIO_CONFIG.G_Night_End_Hour := GVL_CONFIG_CONTROL.BCK_Night_End_Hour;
        GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold := GVL_CONFIG_CONTROL.BCK_VentBoost_Humidity_Threshold;

        GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS := GVL_CONFIG_CONTROL.BCK_Stabilization_Delay_MS;

        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas := GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Close_Gas;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler := GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Boiler;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating := GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Heating;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent := GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Stop_Vent;
        GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water := GVL_CONFIG_CONTROL.BCK_PLC_Inactive_Block_Water;

        GVL_CONFIG_CONTROL.G_Config_Version := GVL_CONFIG_CONTROL.G_Config_Version + 1;
        GVL_CONFIG_CONTROL.G_Rollback_Done := TRUE;
        GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := '';

        L_Index := GVL_CONFIG_HISTORY.G_History_Index;
        GVL_CONFIG_HISTORY.G_History_Version[L_Index] := GVL_CONFIG_CONTROL.G_Config_Version;
        GVL_CONFIG_HISTORY.G_History_Time_MS[L_Index] := GVL_TIME_SERVICE.G_Now_MS;
        GVL_CONFIG_HISTORY.G_History_Action[L_Index] := 'ROLLBACK';
        GVL_CONFIG_HISTORY.G_Last_Action_Text := 'CONFIG ROLLBACK';

        L_Index := L_Index + 1;
        IF L_Index > 5 THEN L_Index := 1; END_IF;
        GVL_CONFIG_HISTORY.G_History_Index := L_Index;
    ELSE
        GVL_CONFIG_HISTORY.G_Last_Action_Text := 'CONFIG ROLLBACK REJECTED - NO BACKUP';
        GVL_CONFIG_VALIDATION.G_Config_Control_Error_Text := 'ROLLBACK REJECTED - NO BACKUP';
    END_IF;

    GVL_CONFIG_CONTROL.G_Rollback_Request := FALSE;
    GVL_CONFIG_CONTROL.G_Rollback_Confirm := FALSE;
END_IF;

GVL_CONFIG_VALIDATION.G_Config_Valid := NOT L_Error;
GVL_CONFIG_VALIDATION.G_Config_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Config_Manager <<<

// Observational validation for policy-gated domain execution.
// Detects stale-output risks when a domain is classified idle.


GVL_DOMAIN_EXECUTION_VALIDATION.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_DOMAIN_EXECUTION_VALIDATION.G_Validation_Executed := TRUE;
GVL_DOMAIN_EXECUTION_VALIDATION.G_Validation_Valid := TRUE;

L_Access_Output_Active :=
    GVL_ACCESS_OUTPUT.DO_Lock_1_Open
    OR GVL_ACCESS_OUTPUT.DO_Lock_1_Close
    OR GVL_ACCESS_OUTPUT.DO_Lock_2_Open
    OR GVL_ACCESS_OUTPUT.DO_Lock_2_Close
    OR GVL_ACCESS_OUTPUT.DO_Gate_Open
    OR GVL_ACCESS_OUTPUT.DO_Wicket_Open;

L_Lighting_Output_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    L_Lighting_Output_Active :=
        L_Lighting_Output_Active
        OR (GVL_LIGHTING_OUTPUT.AO_Lighting_Levels[L_i] > 0);
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    L_Lighting_Output_Active :=
        L_Lighting_Output_Active
        OR (GVL_LIGHTING_OUTPUT.AO_Blinds_Positions[L_i] < 1000);
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Lighting_Output_Active :=
        L_Lighting_Output_Active
        OR GVL_LIGHTING_OUTPUT.DO_Sockets[L_i];
END_FOR;

// Water close outputs are fail-safe holds, not stale activity by themselves.
// Zone enable is the only water output treated as stale when policy says idle.
L_Water_Output_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    L_Water_Output_Active :=
        L_Water_Output_Active
        OR GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i];
END_FOR;

L_Heating_Output_Active :=
    GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump
    OR GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump
    OR GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump
    OR GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Heating_Output_Active :=
        L_Heating_Output_Active
        OR GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i];
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Heating_Output_Active :=
        L_Heating_Output_Active
        OR GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i]
        OR (GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i] > 0);
END_FOR;

L_Vent_Output_Active := GVL_VENT_OUTPUT.DO_Vent_Enable;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    L_Vent_Output_Active :=
        L_Vent_Output_Active
        OR (GVL_VENT_OUTPUT.AO_Supply_Fans[L_i] > 0);
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    L_Vent_Output_Active :=
        L_Vent_Output_Active
        OR (GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i] > 0);
END_FOR;

GVL_DOMAIN_EXECUTION_VALIDATION.Access_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_POLICY.Access_Idle_By_Design AND L_Access_Output_Active;

GVL_DOMAIN_EXECUTION_VALIDATION.Lighting_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_POLICY.Lighting_Idle_By_Design AND L_Lighting_Output_Active;

GVL_DOMAIN_EXECUTION_VALIDATION.Water_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_POLICY.Water_Idle_By_Design AND L_Water_Output_Active;

GVL_DOMAIN_EXECUTION_VALIDATION.Heating_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_POLICY.Heating_Idle_By_Design AND L_Heating_Output_Active;

GVL_DOMAIN_EXECUTION_VALIDATION.Vent_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_POLICY.Vent_Idle_By_Design AND L_Vent_Output_Active;

GVL_DOMAIN_EXECUTION_VALIDATION.Any_Stale_Output_Risk :=
    GVL_DOMAIN_EXECUTION_VALIDATION.Access_Stale_Output_Risk
    OR GVL_DOMAIN_EXECUTION_VALIDATION.Lighting_Stale_Output_Risk
    OR GVL_DOMAIN_EXECUTION_VALIDATION.Water_Stale_Output_Risk
    OR GVL_DOMAIN_EXECUTION_VALIDATION.Heating_Stale_Output_Risk
    OR GVL_DOMAIN_EXECUTION_VALIDATION.Vent_Stale_Output_Risk;

GVL_DOMAIN_EXECUTION_VALIDATION.Any_Policy_Mismatch :=
    GVL_DOMAIN_EXECUTION_VALIDATION.Any_Stale_Output_Risk;

IF GVL_DOMAIN_EXECUTION_VALIDATION.Any_Stale_Output_Risk THEN
    GVL_DOMAIN_EXECUTION_VALIDATION.G_Validation_Valid := FALSE;
    GVL_DOMAIN_EXECUTION_VALIDATION.Status_Code := 1;
    GVL_DOMAIN_EXECUTION_VALIDATION.Status_Text := 'Domain execution validation detected stale output risk';
ELSE
    GVL_DOMAIN_EXECUTION_VALIDATION.Status_Code := 0;
    GVL_DOMAIN_EXECUTION_VALIDATION.Status_Text := 'Domain execution validation nominal';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Domain_Execution_Validation <<<

GVL_LIGHTING_RUNTIME.G_Runtime_Required := FALSE;
GVL_LIGHTING_RUNTIME.G_Runtime_Executed := TRUE;
GVL_LIGHTING_RUNTIME.G_Runtime_Idle_By_Design := FALSE;
GVL_LIGHTING_RUNTIME.G_Runtime_Blocked_By_Distributed_Gates := FALSE;
GVL_LIGHTING_RUNTIME.G_Emergency_Override_Active := GVL_LIGHTING_RUNTIME_BUFFER.B_Emergency_Lighting_Override;
GVL_LIGHTING_RUNTIME.G_Any_Light_Active := FALSE;
GVL_LIGHTING_RUNTIME.G_Any_Blind_Not_Safe_Open := FALSE;
GVL_LIGHTING_RUNTIME.G_Any_Socket_Active := FALSE;
GVL_LIGHTING_RUNTIME.G_Last_Update_MS := GVL_STATUS.G_System_Time_MS;

// Publish wet-zone activity from the final lighting state seen by IO_Write.
L_Wet_Zone_Any_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    IF GVL_CONFIG.G_Wet_Zone_Map[L_i] AND (GVL_STATE.G_Lighting_Levels[L_i] > 10) THEN
        L_Wet_Zone_Any_Active := TRUE;
    END_IF;

    IF GVL_STATE.G_Lighting_Levels[L_i] > 0 THEN
        GVL_LIGHTING_RUNTIME.G_Any_Light_Active := TRUE;
    END_IF;
END_FOR;
GVL_STATUS.G_Wet_Zone_Light_Active := L_Wet_Zone_Any_Active;

// Domain output projection.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    GVL_LIGHTING_OUTPUT.AO_Lighting_Levels[L_i] := BYTE_TO_UINT(GVL_STATE.G_Lighting_Levels[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    IF GVL_STATE.G_Blinds_Positions[L_i] < 100 THEN
        GVL_LIGHTING_RUNTIME.G_Any_Blind_Not_Safe_Open := TRUE;
    END_IF;

    GVL_LIGHTING_OUTPUT.AO_Blinds_Positions[L_i] := BYTE_TO_UINT(GVL_STATE.G_Blinds_Positions[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    IF GVL_STATE.G_Socket_States[L_i] THEN
        GVL_LIGHTING_RUNTIME.G_Any_Socket_Active := TRUE;
    END_IF;

    GVL_LIGHTING_OUTPUT.DO_Sockets[L_i] := GVL_STATE.G_Socket_States[L_i];
END_FOR;

GVL_LIGHTING_RUNTIME.G_Runtime_Blocked_By_Distributed_Gates :=
    NOT GVL_LIGHTING_RUNTIME_BUFFER.B_Distributed_Projection_Allowed
    AND NOT GVL_LIGHTING_RUNTIME_BUFFER.B_Emergency_Lighting_Override;

GVL_LIGHTING_RUNTIME.G_Runtime_Required :=
    GVL_LIGHTING_RUNTIME.G_Emergency_Override_Active
    OR GVL_LIGHTING_RUNTIME.G_Any_Light_Active
    OR GVL_LIGHTING_RUNTIME.G_Any_Blind_Not_Safe_Open
    OR GVL_LIGHTING_RUNTIME.G_Any_Socket_Active
    OR GVL_LIGHTING_RUNTIME_BUFFER.B_Security_Armed
    OR GVL_LIGHTING_RUNTIME_BUFFER.B_Security_Alarm;

GVL_LIGHTING_RUNTIME.G_Runtime_Idle_By_Design :=
    NOT GVL_LIGHTING_RUNTIME.G_Runtime_Required;

IF GVL_LIGHTING_RUNTIME.G_Runtime_Blocked_By_Distributed_Gates THEN
    GVL_LIGHTING_RUNTIME.G_Status_Code := 2;
    GVL_LIGHTING_RUNTIME.G_Status_Text := 'Lighting runtime blocked by distributed gates';
ELSIF GVL_LIGHTING_RUNTIME.G_Runtime_Idle_By_Design THEN
    GVL_LIGHTING_RUNTIME.G_Status_Code := 0;
    GVL_LIGHTING_RUNTIME.G_Status_Text := 'Lighting runtime idle by design';
ELSE
    GVL_LIGHTING_RUNTIME.G_Status_Code := 1;
    GVL_LIGHTING_RUNTIME.G_Status_Text := 'Lighting runtime active';
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Lighting_Phase_04_Output_Publication <<<

// MAIN PHASE 13 — verification, explainability, diagnostics, history, simulation, HMI and debug.
// Critical: mixed. Command verification, health, alarm and debug summary remain active.
// History/trend/blackbox/simulation are shed when runtime budget asks for reduced work.


GVL_MAIN_PHASE_FEEDBACK.G_Current_Phase := 8;

L_Run_Extended_Diagnostics :=
    NOT GVL_FABRIC_LIFECYCLE_REGISTRY.Diagnostics_Degradation_Recommended;

L_Run_Extended_Observability :=
    (GVL_FABRIC_LIFECYCLE_REGISTRY.Runtime_Adaptive_Mode = FULL_SEMANTIC_MODE)
    AND NOT GVL_FABRIC_LIFECYCLE_REGISTRY.Extended_Observability_Shedding_Recommended;

L_Simulation_Context_Active :=
    GVL_SIMULATION.G_Test_Scenario_Active
    OR GVL_SIMULATION.G_Test_Start
    OR GVL_ALARM.G_Security_Armed
    OR (GVL_STATUS.G_Current_Scenario = SCENARIO_AWAY);

L_Run_Simulation :=
    GVL_SIMULATION.G_Simulation_Enable
    AND L_Simulation_Context_Active
    AND NOT GVL_FABRIC_LIFECYCLE_REGISTRY.Simulation_Suspension_Recommended;

GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Diagnostics_Requested := L_Run_Extended_Diagnostics;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Diagnostics_Executed := FALSE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Diagnostics_Skipped_By_Design := NOT L_Run_Extended_Diagnostics;

GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Observability_Requested := L_Run_Extended_Observability;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Observability_Executed := FALSE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Observability_Skipped_By_Design := NOT L_Run_Extended_Observability;

GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Simulation_Requested := L_Run_Simulation;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Simulation_Executed := FALSE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Simulation_Skipped_By_Design := NOT L_Run_Simulation;

PRG_Command_Verifier();
PRG_Explainability();
PRG_System_Health();
PRG_System_Alarm_Gateway();
PRG_System_Diagnostics();
PRG_HMI_Config_Workflow_Manager();
PRG_File_Archive_HMI_Applicator();
PRG_File_Archive_Manager();
PRG_HMI_Dashboard();
PRG_HMI_Water_Dashboard();
PRG_Debug_View();

IF L_Run_Extended_Diagnostics THEN
    PRG_System_Diagnostics_Ext();
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Diagnostics_Executed := TRUE;
END_IF;

IF L_Run_Extended_Observability THEN
    PRG_System_History();
    PRG_System_BlackBox();
    PRG_System_Trend();
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Observability_Executed := TRUE;
END_IF;

IF L_Run_Simulation THEN
    PRG_System_Simulation();
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Simulation_Executed := TRUE;
END_IF;

GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Executed := TRUE;
GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Valid := TRUE;

IF L_Run_Extended_Diagnostics AND L_Run_Extended_Observability AND L_Run_Simulation THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Status_Text := 'Diagnostics/HMI phase executed';
ELSE
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Status_Text := 'Diagnostics/HMI phase executed with designed shedding';
END_IF;

GVL_MAIN_PHASE_FEEDBACK.G_Critical_Path_Executed :=
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_01_Bootstrap_Executed
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Executed
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Executed
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Executed;

GVL_MAIN_PHASE_FEEDBACK.G_Critical_Path_Valid :=
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_01_Bootstrap_Valid
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Valid
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Valid
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Valid;

GVL_MAIN_PHASE_FEEDBACK.G_Observability_Path_Executed :=
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Semantic_Governance_Executed
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Executed;

GVL_MAIN_PHASE_FEEDBACK.G_Observability_Path_Valid :=
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Semantic_Governance_Valid
    AND GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Valid;

GVL_MAIN_PHASE_FEEDBACK.G_Any_Phase_Invalid :=
    NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_01_Bootstrap_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_02_Redundancy_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_03_Input_Safety_Command_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_04_Transport_Distributed_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_05_Domain_Output_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_06_PostOutput_Authority_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Semantic_Governance_Valid
    OR NOT GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Diagnostics_HMI_Valid;

GVL_MAIN_PHASE_FEEDBACK.G_Any_Phase_Skipped_By_Design :=
    GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Full_Semantic_Skipped_By_Design
    OR GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Extended_Observability_Skipped_By_Design
    OR GVL_MAIN_PHASE_FEEDBACK.G_Phase_07_Analytics_Skipped_By_Design
    OR GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Diagnostics_Skipped_By_Design
    OR GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Extended_Observability_Skipped_By_Design
    OR GVL_MAIN_PHASE_FEEDBACK.G_Phase_08_Simulation_Skipped_By_Design;

IF GVL_MAIN_PHASE_FEEDBACK.G_Any_Phase_Invalid THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Code := 1;
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Text := 'MAIN phase feedback degraded';
ELSIF GVL_MAIN_PHASE_FEEDBACK.G_Any_Phase_Skipped_By_Design THEN
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Code := 2;
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Text := 'MAIN phase feedback nominal with designed shedding';
ELSE
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Code := 0;
    GVL_MAIN_PHASE_FEEDBACK.G_Status_Text := 'MAIN phase feedback nominal';
END_IF;

GVL_MAIN_PHASE_FEEDBACK.G_Current_Phase := 0;
GVL_MAIN_PHASE_FEEDBACK.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Main_Phase_08_Diagnostics_HMI <<<

// RUNTIME BUDGET ENFORCEMENT
// READ-ONLY / NON-INVASIVE

GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Budget_Pressure_Observed :=
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Runtime_Complexity_Pressure_Observed;

GVL_RUNTIME_BUDGET_ENFORCEMENT.Governance_Runtime_Overhead_Observed :=
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Governance_Runtime_Cost_Observed;

GVL_RUNTIME_BUDGET_ENFORCEMENT.Verification_Runtime_Budget_Observed :=
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Verification_Chaining_Limit_Reached;

GVL_RUNTIME_BUDGET_ENFORCEMENT.Observability_Runtime_Budget_Observed :=
    GVL_CANONICAL_RUNTIME_FABRIC_REGISTRY.Observability_Amplification_Limit_Reached;

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Budget_Pressure_Observed THEN
    GVL_RUNTIME_BUDGET_ENFORCEMENT.Runtime_Stability_Budget_At_Risk := TRUE;
END_IF;

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Verification_Runtime_Budget_Observed THEN
    GVL_RUNTIME_BUDGET_ENFORCEMENT.Verification_Time_Budget_Exceeded := TRUE;
    GVL_RUNTIME_BUDGET_ENFORCEMENT.Verification_Induced_Runtime_Risk := TRUE;
END_IF;

IF GVL_RUNTIME_BUDGET_ENFORCEMENT.Observability_Runtime_Budget_Observed THEN
    GVL_RUNTIME_BUDGET_ENFORCEMENT.Observability_Amplification_Budget_Exceeded := TRUE;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Actuation_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_ACTUATION_AUTHORITY.Actuation_Authority_Valid := FALSE;
GVL_ACTUATION_AUTHORITY.Actuation_Authority_Granted := FALSE;
GVL_ACTUATION_AUTHORITY.Actuation_Quarantine_Active := TRUE;
GVL_ACTUATION_AUTHORITY.Field_Device_ACK_Valid := FALSE;
GVL_ACTUATION_AUTHORITY.Actuator_Transition_Observed := FALSE;
GVL_ACTUATION_AUTHORITY.Physical_Convergence_Confirmed := FALSE;
GVL_ACTUATION_AUTHORITY.Stable_Physical_Convergence := FALSE;

GVL_ACTUATION_AUTHORITY.Actuation_Command_Epoch := ULINT_TO_UDINT(GVL_OUTPUT_EPOCH.Output_Publication_Epoch);

IF GVL_ACTUATION_AUTHORITY.Field_ACK_Epoch <> GVL_ACTUATION_AUTHORITY.Actuation_Command_Epoch THEN
    GVL_ACTUATION_AUTHORITY.Command_Actuation_Skew_Detected := TRUE;
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26000;
    L_Error_Text := 'Command actuation epoch skew detected';
END_IF;

IF L_Actuation_Valid AND GVL_ACTUATION_AUTHORITY.ACK_Replay_Suspected THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26001;
    L_Error_Text := 'Field ACK replay suspected';
END_IF;

IF L_Actuation_Valid AND GVL_ACTUATION_AUTHORITY.Write_Without_Confirm_Detected THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26002;
    L_Error_Text := 'Write without field confirmation detected';
END_IF;

IF L_Actuation_Valid AND GVL_ACTUATION_AUTHORITY.Relay_Weld_Suspected THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26003;
    L_Error_Text := 'Relay weld suspected';
END_IF;

IF L_Actuation_Valid AND GVL_ACTUATION_AUTHORITY.Actuator_Stall_Detected THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26004;
    L_Error_Text := 'Actuator stall detected';
END_IF;

IF L_Actuation_Valid AND GVL_ACTUATION_AUTHORITY.Partial_Actuation_Detected THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26005;
    L_Error_Text := 'Partial actuation detected';
END_IF;

IF L_Actuation_Valid AND NOT GVL_ACTUATION_AUTHORITY.Current_Signature_Confirmed THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26010;
    L_Error_Text := 'Current signature confirmation missing';
END_IF;

IF L_Actuation_Valid AND NOT GVL_ACTUATION_AUTHORITY.Flow_Response_Confirmed THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26011;
    L_Error_Text := 'Flow response confirmation missing';
END_IF;

IF L_Actuation_Valid AND NOT GVL_ACTUATION_AUTHORITY.Pressure_Response_Confirmed THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26012;
    L_Error_Text := 'Pressure response confirmation missing';
END_IF;

IF L_Actuation_Valid AND NOT GVL_ACTUATION_AUTHORITY.Motion_Response_Confirmed THEN
    L_Actuation_Valid := FALSE;
    L_Error_Code := 26013;
    L_Error_Text := 'Motion response confirmation missing';
END_IF;

IF L_Actuation_Valid THEN
    GVL_ACTUATION_AUTHORITY.Actuation_Authority_Valid := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuation_Authority_Granted := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuation_Quarantine_Active := FALSE;
    GVL_ACTUATION_AUTHORITY.Field_Device_ACK_Valid := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuator_Transition_Observed := TRUE;
    GVL_ACTUATION_AUTHORITY.Physical_Convergence_Confirmed := TRUE;
    GVL_ACTUATION_AUTHORITY.Stable_Physical_Convergence := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuation_Authority_Epoch := GVL_ACTUATION_AUTHORITY.Actuation_Command_Epoch;
    GVL_ACTUATION_AUTHORITY.Actuation_Last_Update_MS := L_Now_MS;
    GVL_ACTUATION_AUTHORITY.Actuation_Lease_Expired := FALSE;
    GVL_ACTUATION_AUTHORITY.Actuation_Last_Error_Code := 0;
    GVL_ACTUATION_AUTHORITY.Actuation_Last_Error_Text := '';
ELSE
    GVL_ACTUATION_AUTHORITY.Actuation_Authority_Valid := FALSE;
    GVL_ACTUATION_AUTHORITY.Actuation_Authority_Granted := FALSE;
    GVL_ACTUATION_AUTHORITY.Actuation_Quarantine_Active := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuation_Lease_Expired := TRUE;
    GVL_ACTUATION_AUTHORITY.Actuation_Last_Error_Code := L_Error_Code;
    GVL_ACTUATION_AUTHORITY.Actuation_Last_Error_Text := L_Error_Text;
    GVL_ACTUATION_AUTHORITY.Actuation_Invalidation_Count := GVL_ACTUATION_AUTHORITY.Actuation_Invalidation_Count + 1;
END_IF;

// ==============================================================================
// Water runtime output bridge.
//
// Topology:
// - group 1: riser 1 kitchen, local valves 1(HWS/CW) and 2(HW);
// - group 2: riser 2 master bathroom, local valves 3 and 4;
// - group 3: riser 3 guest bathrooms + laundry, local valves 5 and 6;
// - group 4: common inlet 35(CW) and 36(HW).
//
// Normally-open valves are used because water is from a well: no electrical
// power means no pump and no pressurized water. Leak/fallback projects Close;
// HMI emergency-open projects Open for a timed, limited interval.
// ==============================================================================

PRG_Water_Emergency_Open_Manager();

GVL_WATER_DOMAIN_STATUS.G_Runtime_Required := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Runtime_Executed := TRUE;
GVL_WATER_DOMAIN_STATUS.G_Runtime_Idle_By_Design := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Recovery_Requested := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Output_35_Active := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Output_36_Active := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Any_Zone_Active := FALSE;
GVL_WATER_DOMAIN_STATUS.G_Last_Update_MS := GVL_STATUS.G_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    L_Zone_Enable[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO 6 DO
    L_Local_Valve_Open[L_i] := FALSE;
    L_Local_Valve_Close[L_i] := FALSE;
END_FOR;

L_Valve_35_Open := FALSE;
L_Valve_35_Close := FALSE;
L_Valve_36_Open := FALSE;
L_Valve_36_Close := FALSE;

IF GVL_INTENT_SAFETY.I_Water_Selective_Recovery_Allowed THEN
    GVL_WATER_DOMAIN_STATUS.G_Recovery_Requested := TRUE;

    IF (GVL_INTENT_SAFETY.I_Water_Recovery_Target_Zone >= 1) AND (GVL_INTENT_SAFETY.I_Water_Recovery_Target_Zone <= GVL_CONSTANTS.C_MAX_WATER_ZONES) THEN
        L_Zone_Enable[GVL_INTENT_SAFETY.I_Water_Recovery_Target_Zone] := TRUE;
    END_IF;
END_IF;

// Existing authoritative common inlet fallback path from command shadow.
L_Valve_35_Close := GVL_COMMAND_SHADOW.G_Close_Valve_35;
L_Valve_36_Close := GVL_COMMAND_SHADOW.G_Close_Valve_36;

// Deterministic water output projection by isolation group.
IF GVL_Water_Output_Projection.G_Runtime_Valid THEN

    IF GVL_Water_Output_Projection.G_Global_Fallback_Projecting THEN
        FOR L_i := 1 TO 6 DO
            L_Local_Valve_Close[L_i] := TRUE;
        END_FOR;
        L_Valve_35_Close := TRUE;
        L_Valve_36_Close := TRUE;
        GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active := TRUE;
    ELSE
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
            IF GVL_Water_Output_Projection.G_Output_Projection_State[L_i].Projection_Allowed AND
               GVL_Water_Output_Projection.G_Output_Projection_State[L_i].Physical_Close_Project THEN

                L_Projected_Valve_Group := GVL_Water_Output_Projection.G_Output_Projection_State[L_i].Valve_Group_Id;

                CASE L_Projected_Valve_Group OF
                    1:
                        L_Local_Valve_Close[1] := TRUE;
                        L_Local_Valve_Close[2] := TRUE;
                    2:
                        L_Local_Valve_Close[3] := TRUE;
                        L_Local_Valve_Close[4] := TRUE;
                    3:
                        L_Local_Valve_Close[5] := TRUE;
                        L_Local_Valve_Close[6] := TRUE;
                    4:
                        L_Valve_35_Close := TRUE;
                        L_Valve_36_Close := TRUE;
                ELSE
                    L_Valve_35_Close := TRUE;
                    L_Valve_36_Close := TRUE;
                    GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active := TRUE;
                END_CASE;
            END_IF;
        END_FOR;
    END_IF;
END_IF;

// Emergency open for selected riser/common inlet: project Open and suppress
// the corresponding Close command for the timed interval.
IF GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_1_Active THEN
    L_Local_Valve_Close[1] := FALSE;
    L_Local_Valve_Close[2] := FALSE;
    L_Local_Valve_Open[1] := TRUE;
    L_Local_Valve_Open[2] := TRUE;
END_IF;

IF GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_2_Active THEN
    L_Local_Valve_Close[3] := FALSE;
    L_Local_Valve_Close[4] := FALSE;
    L_Local_Valve_Open[3] := TRUE;
    L_Local_Valve_Open[4] := TRUE;
END_IF;

IF GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_3_Active THEN
    L_Local_Valve_Close[5] := FALSE;
    L_Local_Valve_Close[6] := FALSE;
    L_Local_Valve_Open[5] := TRUE;
    L_Local_Valve_Open[6] := TRUE;
END_IF;

IF GVL_WATER_EMERGENCY_OPEN.G_Open_Common_Inlet_Active THEN
    L_Valve_35_Close := FALSE;
    L_Valve_36_Close := FALSE;
    L_Valve_35_Open := TRUE;
    L_Valve_36_Open := TRUE;
END_IF;

// Open-timeout service latch blocks further automatic opening until reset.
FOR L_i := 1 TO 6 DO
    IF GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[L_i] THEN
        L_Local_Valve_Open[L_i] := FALSE;
    END_IF;
END_FOR;

IF GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[7] THEN
    L_Valve_35_Open := FALSE;
END_IF;

IF GVL_STATUS.G_Diagnostics.Water_Zone_Open_Blocked[8] THEN
    L_Valve_36_Open := FALSE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    IF L_Zone_Enable[L_i] THEN
        GVL_WATER_DOMAIN_STATUS.G_Any_Zone_Active := TRUE;
    END_IF;
END_FOR;

GVL_WATER_DOMAIN_STATUS.G_Output_35_Active := L_Valve_35_Close OR L_Valve_35_Open;
GVL_WATER_DOMAIN_STATUS.G_Output_36_Active := L_Valve_36_Close OR L_Valve_36_Open;

FOR L_i := 1 TO 6 DO
    IF L_Local_Valve_Close[L_i] OR L_Local_Valve_Open[L_i] THEN
        GVL_WATER_DOMAIN_STATUS.G_Any_Zone_Active := TRUE;
    END_IF;
END_FOR;

GVL_WATER_DOMAIN_STATUS.G_Runtime_Required :=
    GVL_WATER_DOMAIN_STATUS.G_Recovery_Requested
    OR GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Output_35_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Output_36_Active
    OR GVL_WATER_DOMAIN_STATUS.G_Any_Zone_Active;

GVL_WATER_DOMAIN_STATUS.G_Runtime_Idle_By_Design := NOT GVL_WATER_DOMAIN_STATUS.G_Runtime_Required;

IF GVL_WATER_DOMAIN_STATUS.G_Runtime_Idle_By_Design THEN
    GVL_WATER_DOMAIN_STATUS.G_Status_Code := 0;
    GVL_WATER_DOMAIN_STATUS.G_Status_Text := 'Water domain idle by design';
ELSIF GVL_WATER_DOMAIN_STATUS.G_Global_Path_Active THEN
    GVL_WATER_DOMAIN_STATUS.G_Status_Code := 2;
    GVL_WATER_DOMAIN_STATUS.G_Status_Text := 'Water domain global path active';
ELSIF GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_1_Active OR
      GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_2_Active OR
      GVL_WATER_EMERGENCY_OPEN.G_Open_Riser_3_Active OR
      GVL_WATER_EMERGENCY_OPEN.G_Open_Common_Inlet_Active THEN
    GVL_WATER_DOMAIN_STATUS.G_Status_Code := 3;
    GVL_WATER_DOMAIN_STATUS.G_Status_Text := 'Water emergency open active';
ELSE
    GVL_WATER_DOMAIN_STATUS.G_Status_Code := 1;
    GVL_WATER_DOMAIN_STATUS.G_Status_Text := 'Water domain active';
END_IF;

fbProjection(
    VI_Zone_Enable := L_Zone_Enable,
    VI_Valve_35_Open := L_Valve_35_Open,
    VI_Valve_35_Close := L_Valve_35_Close,
    VI_Valve_36_Open := L_Valve_36_Open,
    VI_Valve_36_Close := L_Valve_36_Close,
    VI_Local_Valve_Open := L_Local_Valve_Open,
    VI_Local_Valve_Close := L_Local_Valve_Close
);

PRG_Water_Valve_Diagnostics();

// >>> BULK_SYNC_ANCHOR: PRG_Water <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SECURITY_SENSORS DO
    fbDebounce_Security_Open[L_i](
        IN := GVL_IO.DI_Security_Open[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );

    fbDebounce_Security_Glass[L_i](
        IN := GVL_IO.DI_Security_Glass[L_i],
        PT := L_Debounce_Time,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
    );
END_FOR;

fbDebounce_Group_2F(
    IN := GVL_IO.DI_Security_2F_Group,
    PT := L_Debounce_Time,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
    GVL_STATE.G_Door_Sensors[L_i] := FALSE;
    IF GVL_CONFIG.G_Door_Map[L_i] > 0 AND GVL_CONFIG.G_Door_Map[L_i] <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS THEN
        GVL_STATE.G_Door_Sensors[L_i] := fbDebounce_Security_Open[GVL_CONFIG.G_Door_Map[L_i]].Q;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    GVL_STATE.G_Window_Sensors[L_i] := FALSE;
    L_Map_Index := GVL_CONFIG.G_Window_Map[L_i];
    IF L_Map_Index > 0 THEN
        IF L_Map_Index <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS THEN
            GVL_STATE.G_Window_Sensors[L_i] := fbDebounce_Security_Open[L_Map_Index].Q;
        ELSE
            L_Glass_Index := L_Map_Index - GVL_CONSTANTS.C_MAX_SECURITY_SENSORS;
            IF (L_Glass_Index >= 1) AND (L_Glass_Index <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS) THEN
                GVL_STATE.G_Window_Sensors[L_i] := fbDebounce_Security_Glass[L_Glass_Index].Q;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

GVL_STATE.G_Window_Sensors[16] := fbDebounce_Group_2F.Q;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read_Discrete_02_Security_Openings <<<

IF GVL_RECOVERY_ORDERING_INTEGRITY_FABRIC.Recovery_Ordering_Integrity_Valid
AND NOT GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Unsafe_Reactivation_Ordering_Detected
AND NOT GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Partial_Reactivation_Leak_Detected
AND NOT GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.CrossSubsystem_Reactivation_Fork THEN

    GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Recovery_Reactivation_Control_Valid := TRUE;
    GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Recovery_Reactivation_Control_Granted := TRUE;
    GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Recovery_Reactivation_Boundary_Stable := TRUE;
    GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.CrossSubsystem_Reactivation_Consistent := TRUE;
    GVL_RECOVERY_REACTIVATION_CONTROL_FABRIC.Reactivation_Energy_Boundary_Safe := TRUE;
END_IF;

IF GVL_INTENT_USER.I_Set_Adapt_Profile_Req THEN

    // block if safety active
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> NORMAL) OR GVL_SAFETY_RECOVERY.G_Recovery_Active THEN

        fbTrace(
            iLayer := TRACE_USER,
            iSource := SRC_USER,
            iReason := REASON_SAFETY,
            iValueBool := FALSE,
            iValueReal := 0.0,
            iText := 'Profile change blocked: SAFETY ACTIVE'
        );

    ELSE

        IF (GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm)
           AND (GVL_INTENT_USER.I_User_Access_Level >= 2) THEN

            GVL_BEHAVIOR_ADAPT.G_Adapt_Profile :=
                GVL_INTENT_USER.I_Adapt_Profile_Value;

            IF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_STABLE THEN
                L_Text := 'Adapt profile: STABLE';
            ELSIF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_BALANCED THEN
                L_Text := 'Adapt profile: BALANCED';
            ELSE
                L_Text := 'Adapt profile: AGGRESSIVE';
            END_IF;

            fbTrace(
                iLayer := TRACE_USER,
                iSource := SRC_USER,
                iReason := REASON_USER_REQUEST,
                iValueBool := TRUE,
                iValueReal := TO_REAL(GVL_INTENT_USER.I_User_Access_Level),
                iText := L_Text
            );

        END_IF;

    END_IF;

    GVL_INTENT_USER.I_Set_Adapt_Profile_Req := FALSE;
    GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm := FALSE;

END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Block_IO := FALSE;
L_Error_Code := 0;
L_Error_Text := '';
L_Any_Manifold_Pump_On := FALSE;
L_Prev_Block_IO := GVL_COMMAND_VERIFY.PreOutput_Block_IO;

L_Selective_Projection_Active :=
    GVL_Water_Isolation_Authority.G_Any_Selective_Authority_Allowed;

L_Global_Fallback_Active :=
    GVL_Water_Isolation_Authority.G_Any_Global_Fallback_Required;

L_Runtime_Projection_Healthy :=
    GVL_Water_Output_Reconciliation.G_Runtime_Valid
    AND NOT GVL_Water_Output_Reconciliation.G_Any_Conflict_Detected;

// Command shadow is now the command ownership surface for domain execution.
// Legacy GVL_COMMAND mismatch must not block physical publication.
GVL_COMMAND_VERIFY.Command_Match_OK := TRUE;
GVL_COMMAND_VERIFY.Command_Mismatch_Active := FALSE;
GVL_COMMAND_VERIFY.Command_Mismatch_Count := 0;

// Command ↔ telemetry epoch binding.
L_Command_Telemetry_Epoch_Aligned :=
    GVL_TELEMETRY.Command_Epoch = GVL_OUTPUT_EPOCH.Output_Publication_Epoch
    AND GVL_TELEMETRY.Telemetry_Epoch = GVL_OUTPUT_EPOCH.Output_Publication_Epoch
    AND GVL_TELEMETRY.Telemetry_Epoch >=
        GVL_TELEMETRY.Last_Acknowledged_Command_Epoch;

// Physical acknowledgment freshness.
L_Physical_Ack_Fresh :=
    (L_Now_MS - GVL_TELEMETRY.Last_Physical_Ack_Time_MS) <= 5000;

// Physical causality evidence.
L_Physical_Causality_Healthy :=
    GVL_TELEMETRY.Telemetry_Runtime_Valid
    AND GVL_TELEMETRY.Telemetry_Freshness_Valid
    AND NOT GVL_TELEMETRY.Telemetry_Lease_Expired
    AND NOT GVL_TELEMETRY.Telemetry_Quarantine_Active
    AND GVL_TELEMETRY.Command_Telemetry_Causality_Valid
    AND NOT GVL_TELEMETRY.Command_Telemetry_Divergence_Detected
    AND GVL_TELEMETRY.Actuator_Feedback_Valid
    AND GVL_TELEMETRY.Actuator_Feedback_Fresh
    AND GVL_TELEMETRY.Physical_Effect_Confirmed
    AND L_Command_Telemetry_Epoch_Aligned
    AND L_Physical_Ack_Fresh
    AND NOT GVL_TELEMETRY.Telemetry_Replay_Suspected;

// Finalized publication continuity proof chain.
L_Finalized_Publication_Continuity :=
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid
    AND GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    AND NOT GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
    AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
    AND NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
    AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
    AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid
    AND GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed
    AND NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch
    AND NOT GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active
    AND NOT GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired
    AND GVL_OUTPUT_EPOCH.Output_Publication_Valid
    AND GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid
    AND NOT GVL_OUTPUT_EPOCH.Output_Lease_Expired
    AND NOT GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay;

IF (NOT L_Block_IO)
   AND (NOT L_Finalized_Publication_Continuity) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 3999;
    L_Error_Text := 'PreOutput finalized publication continuity invalid';
END_IF;

IF (NOT L_Block_IO)
   AND (NOT L_Physical_Causality_Healthy) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 3998;
    L_Error_Text := 'Physical causality evidence invalid';
END_IF;

IF (NOT L_Block_IO) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4000;
    L_Error_Text := 'PreOutput inactive PLC';
END_IF;

GVL_COMMAND_VERIFY.PreOutput_Physical_Causality_Valid :=
    L_Physical_Causality_Healthy;

GVL_COMMAND_VERIFY.PreOutput_Barrier_OK := NOT L_Block_IO;
GVL_COMMAND_VERIFY.PreOutput_Block_IO := L_Block_IO;
GVL_COMMAND_VERIFY.PreOutput_Last_Error_Code := L_Error_Code;
GVL_COMMAND_VERIFY.PreOutput_Last_Error_Text := L_Error_Text;

IF L_Block_IO THEN
    GVL_COMMAND_VERIFY.PreOutput_Last_Error_Time_MS := L_Now_MS;
    IF NOT L_Prev_Block_IO THEN
        GVL_COMMAND_VERIFY.PreOutput_Block_Count :=
            GVL_COMMAND_VERIFY.PreOutput_Block_Count + 1;
        fbLog(
            VI_Event_Type := 1002,
            VI_Timestamp := L_Now_MS,
            VI_Param1 := L_Error_Code,
            VI_Param2 := GVL_COMMAND_VERIFY.PreOutput_Block_Count
        );
    END_IF;
END_IF;

// PASSIVE FORMAL TRANSITION VALIDATOR
// NO EXECUTION MUTATION
// NO AUTHORITY MUTATION
// OBSERVABILITY ONLY

GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal := FALSE;
GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Proofs_Valid := FALSE;
GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Lineage_Valid := FALSE;
GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Temporal_Valid := FALSE;

CASE GVL_RUNTIME_STATE_ALGEBRA.Current_Runtime_State OF

    SYS_SAFE:
        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal := TRUE;
        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Proofs_Valid := TRUE;

    SYS_RECOVERING:
        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal :=
            GVL_TEMPORAL_CAUSALITY_CLOSURE_FABRIC.Temporal_Causality_Coherent;

        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Proofs_Valid :=
            GVL_SAFETY_OBSERVABILITY_TRUTH_FABRIC.Observability_Reality_Equivalence_Granted;

        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Lineage_Valid :=
            GVL_AUTHORITY_LINEAGE.Authority_Lineage_Valid;

        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Temporal_Valid :=
            GVL_DISTRIBUTED_EPOCH_LINEARITY_FABRIC.Epoch_Timeline_Monotonic;

    SYS_QUARANTINED:
        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal := TRUE;

    SYS_TRUSTLESS:
        GVL_RUNTIME_TRANSITION_SYSTEM.Runtime_Transition_Legal := FALSE;
        GVL_RUNTIME_TRANSITION_SYSTEM.Unsafe_Trust_Escalation_Observed := TRUE;

ELSE
    GVL_RUNTIME_TRANSITION_SYSTEM.Illegal_Runtime_Transition_Observed := TRUE;

END_CASE;

